-- Included migrations through: 0267
-- 0128 仅为首次统一前显式开启的测试数据清空；新库安装不执行清空，其结构与数据不受影响。
-- 仅用于全新数据库，禁止在已有环境重复导入；已有库必须按编号执行增量迁移。
-- 此基线供统一模型新版应用使用；旧版应用不兼容 0127 删除业务过程与业务对象后的结构。
-- 新库保留业务域、数据域、主题域与数仓分层；末尾迁移清理业务过程、业务对象及其演示数据。
-- 扩展内部类型和函数由 PostgreSQL 官方扩展管理，不按普通业务对象导出或重建。
CREATE SCHEMA IF NOT EXISTS "datahub-center";

-- ETL 文件输出恢复账本（0115，已在隔离 PostgreSQL 重放验证）
CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_file_output_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_file_output (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_file_output_seq'),
    tenant_id bigint NOT NULL,
    record_id bigint NOT NULL,
    pipeline_id bigint NOT NULL,
    node_no varchar(128) NOT NULL,
    owner_id bigint NOT NULL,
    run_token varchar(128) NOT NULL,
    operation_key varchar(36) NOT NULL,
    storage_key varchar(64) NOT NULL,
    storage_identity varchar(36) NOT NULL,
    file_name varchar(255) NOT NULL,
    state varchar(32) NOT NULL DEFAULT 'INTENT',
    temporary_file_key varchar(1024),
    payload_hash varchar(64),
    payload_bytes bigint,
    publication_approved boolean NOT NULL DEFAULT false,
    recovery_status varchar(16) NOT NULL DEFAULT 'PENDING',
    attempts integer NOT NULL DEFAULT 0,
    recovery_token varchar(36),
    recovery_lease_until timestamp,
    next_attempt_at timestamp,
    last_error_code varchar(64),
    revision bigint NOT NULL DEFAULT 0,
    temporary_resources_json jsonb DEFAULT '[]'::jsonb,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted int2 NOT NULL DEFAULT 0,
    CONSTRAINT dh_etl_file_node_uq UNIQUE(tenant_id,record_id,node_no),
    CONSTRAINT dh_etl_file_operation_uq UNIQUE(operation_key),
    CONSTRAINT dh_etl_file_state_ck CHECK(state IN ('INTENT','STAGED','READY','PUBLISHING','PUBLISHED','DISCARDED','UNKNOWN','CLEANUP_PENDING','PUBLISHED_CLEANUP_PENDING','MANUAL')),
    CONSTRAINT dh_etl_file_recovery_ck CHECK(recovery_status IN ('PENDING','CLAIMED','RETRY','DONE','MANUAL')),
    CONSTRAINT dh_etl_file_budget_ck CHECK(attempts BETWEEN 0 AND 10 AND revision >= 0 AND (payload_bytes IS NULL OR payload_bytes BETWEEN 0 AND 134217728)),
    CONSTRAINT dh_etl_file_payload_ck CHECK((payload_hash IS NULL AND payload_bytes IS NULL) OR (payload_hash IS NOT NULL AND payload_hash ~ '^[a-f0-9]{64}$' AND payload_bytes IS NOT NULL)),
    CONSTRAINT dh_etl_file_approve_ck CHECK(NOT publication_approved OR (payload_hash IS NOT NULL AND temporary_file_key IS NOT NULL)),
    CONSTRAINT dh_etl_file_resources_budget_ck CHECK(temporary_resources_json IS NULL OR CASE WHEN jsonb_typeof(temporary_resources_json)='array'
        THEN jsonb_array_length(temporary_resources_json)<=4 AND octet_length(convert_to(temporary_resources_json::text,'UTF8'))<=16384 ELSE false END)
);
-- 表用途说明：ETL文件输出持久意图、发布回执与孤儿恢复账本
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_file_output IS '可视化ETL-文件输出账本';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.id IS '文件输出编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.record_id IS '所属运行';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.pipeline_id IS '所属流程';
