COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.file_name IS '输出文件名';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.state IS '文件副作用状态';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.temporary_file_key IS '暂存文件系统对象身份';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.payload_hash IS '已封存内容摘要';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.payload_bytes IS '已封存字节数';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.publication_approved IS '整体图成功后批准发布';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.recovery_status IS '恢复状态';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.attempts IS '自动恢复次数';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.recovery_token IS '恢复抢占令牌';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.recovery_lease_until IS '恢复租约到期';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.next_attempt_at IS '下次重试时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.last_error_code IS '脱敏失败分类';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.revision IS '乐观修订号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.temporary_resources_json IS '受控暂存资源意图、对象身份及清理回执清单，历史空值不补造证据';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.deleted IS '逻辑删除标记';
CREATE INDEX IF NOT EXISTS dh_etl_file_recovery_idx ON "datahub-center".dh_dataforge_etl_file_output(recovery_status,next_attempt_at,id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS dh_etl_file_owner_idx ON "datahub-center".dh_dataforge_etl_file_output(tenant_id,owner_id,record_id) WHERE deleted=0;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_file_audit (
    id bigserial PRIMARY KEY,
    tenant_id bigint NOT NULL,
    output_id bigint NOT NULL,
    actor_id bigint NOT NULL,
    action varchar(32) NOT NULL,
    before_state varchar(128) NOT NULL,
    after_state varchar(128) NOT NULL,
    revision bigint NOT NULL,
    reason varchar(500) NOT NULL,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted int2 NOT NULL DEFAULT 0
);
-- 表用途说明：ETL文件账本只追加状态与人工重试审计
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_file_audit IS '可视化ETL-文件输出审计';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.id IS '审计编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.output_id IS '文件输出编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.actor_id IS '运行或人工操作主体';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.action IS '操作类型';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.before_state IS '操作前状态摘要';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.after_state IS '提交后状态摘要';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.revision IS '提交后修订号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.reason IS '脱敏原因';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_audit.deleted IS '逻辑删除标记';
CREATE INDEX IF NOT EXISTS dh_etl_file_audit_idx ON "datahub-center".dh_dataforge_etl_file_audit(tenant_id,output_id,id);
CREATE OR REPLACE FUNCTION "datahub-center".dh_etl_file_audit_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'ETL文件审计记录只允许追加'; END $$;
DROP TRIGGER IF EXISTS dh_etl_file_audit_immutable_trg ON "datahub-center".dh_dataforge_etl_file_audit;
CREATE TRIGGER dh_etl_file_audit_immutable_trg BEFORE UPDATE OR DELETE ON "datahub-center".dh_dataforge_etl_file_audit
FOR EACH ROW EXECUTE FUNCTION "datahub-center".dh_etl_file_audit_immutable();

-- ETL 字典质量协同持久化结构
CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_version_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_version (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_version_seq'),
    tenant_id bigint NOT NULL,
    pipeline_id bigint NOT NULL,
    revision integer NOT NULL CHECK (revision >= 0),
    release_generation bigint,
    event_type varchar(16) NOT NULL CHECK (event_type IN ('PUBLISH','RESTORE')),
    source_version_id bigint,
    actor_id bigint NOT NULL,
    reason varchar(500) NOT NULL,
    content_hash varchar(64) NOT NULL,
    config_json text NOT NULL CHECK (jsonb_typeof(config_json::jsonb) = 'object'),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT ck_etl_version_kind CHECK
        ((event_type='PUBLISH' AND release_generation IS NOT NULL AND source_version_id IS NULL)
         OR (event_type='RESTORE' AND release_generation IS NULL AND source_version_id IS NOT NULL))
);
-- 表用途说明：ETL 不可变发布历史和恢复草稿审计，不支持直接更新或删除
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_version IS '可视化ETL-发布版本';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.id IS '历史事件编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.pipeline_id IS '流程编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.revision IS '对应草稿修订号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.release_generation IS '发布代次，恢复事件为空';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.event_type IS '事件类型，发布或恢复为草稿';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.source_version_id IS '恢复来源的发布历史编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.actor_id IS '操作人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.reason IS '发布或恢复原因';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.content_hash IS '原始快照文本的 SHA256 摘要';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.config_json IS '不可变快照，文本保存以保证摘要可复核';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.create_time IS '创建时间，补录历史使用最后一次发布或更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_version.deleted IS '逻辑删除标识';
CREATE UNIQUE INDEX IF NOT EXISTS uk_etl_version_publication ON "datahub-center".dh_dataforge_etl_version
    (tenant_id,pipeline_id,release_generation) WHERE event_type='PUBLISH';
CREATE INDEX IF NOT EXISTS idx_etl_version_pipeline ON "datahub-center".dh_dataforge_etl_version (tenant_id,pipeline_id,id DESC);

