CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_quality_batch_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_quality_batch (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_quality_batch_seq'),
    tenant_id bigint NOT NULL,
    record_id bigint NOT NULL,
    node_no varchar(128) NOT NULL,
    execution_user_id bigint NOT NULL,
    plan_hash varchar(64) NOT NULL,
    input_count bigint,
    pass_count bigint,
    warn_count bigint,
    reject_count bigint,
    violation_count bigint,
    registration_status varchar(24) NOT NULL DEFAULT 'COLLECTING',
    governance_report_id bigint,
    attempt_count integer NOT NULL DEFAULT 0,
    lease_token varchar(64),
    lease_until timestamp,
    next_attempt_at timestamp,
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT uk_etl_quality_batch UNIQUE (tenant_id, record_id, node_no),
    CONSTRAINT ck_etl_quality_batch_state CHECK (registration_status IN ('COLLECTING','PENDING','REGISTERING','RETRY','REGISTERED','FAILED')),
    CONSTRAINT ck_etl_quality_counts CHECK ((input_count IS NULL AND pass_count IS NULL AND warn_count IS NULL
        AND reject_count IS NULL AND violation_count IS NULL) OR
        (input_count IS NOT NULL AND pass_count IS NOT NULL AND warn_count IS NOT NULL AND reject_count IS NOT NULL
         AND violation_count IS NOT NULL AND input_count >= 0 AND pass_count >= 0 AND warn_count >= 0 AND reject_count >= 0
         AND violation_count >= 0 AND input_count = pass_count + warn_count + reject_count))
);
-- 表用途说明：ETL 内联检测事实与治理登记状态，不代表目标写入验收
