CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_quality_issue_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_quality_issue (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_quality_issue_seq'),
    tenant_id bigint NOT NULL,
