COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_issue.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_issue.deleted IS '逻辑删除标识';

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_quality_retry_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_quality_retry (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_quality_retry_seq'),
    tenant_id bigint NOT NULL,
    batch_id bigint NOT NULL,
    actor_id bigint NOT NULL,
    previous_attempts integer NOT NULL CHECK (previous_attempts >= 0),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0
);
-- 表用途说明：质量登记人工重试审计，状态固定从失败变为待登记，不重跑 ETL
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_quality_retry IS '可视化ETL-质量登记重试记录';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.id IS '审计编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.batch_id IS '质量批次编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.actor_id IS '本次人工重试操作人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.previous_attempts IS '重试前登记尝试次数';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_quality_retry.deleted IS '逻辑删除标识';
CREATE INDEX IF NOT EXISTS idx_etl_quality_retry_batch ON "datahub-center".dh_dataforge_etl_quality_retry (tenant_id,batch_id,id);

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_governance_etl_quality_report_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_etl_quality_report (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_governance_etl_quality_report_seq'),
    tenant_id bigint NOT NULL,
    run_id varchar(64) NOT NULL,
    node_id varchar(128) NOT NULL,
    batch_id varchar(128) NOT NULL,
    source_type varchar(32) NOT NULL DEFAULT 'ETL_INLINE',
    plan_hash varchar(64) NOT NULL,
    idempotency_key varchar(180) NOT NULL,
    request_hash varchar(64) NOT NULL,
    execution_user_id bigint NOT NULL,
    total_count bigint NOT NULL CHECK (total_count >= 0),
    pass_count bigint NOT NULL CHECK (pass_count >= 0),
    warn_count bigint NOT NULL CHECK (warn_count >= 0),
    reject_count bigint NOT NULL CHECK (reject_count >= 0),
    issue_references_json jsonb NOT NULL DEFAULT '[]'::jsonb,
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT uk_governance_etl_report UNIQUE (tenant_id, idempotency_key),
    CONSTRAINT ck_governance_etl_report_counts CHECK (total_count = pass_count + warn_count + reject_count)
);
-- 表说明（原文）：受权接收的 ETL 内联报告，与回源 SQL 检测实例独立
COMMENT ON TABLE "datahub-center".dh_governance_etl_quality_report IS '数据质量-ETL内联报告';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.id IS '内联报告编号';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.run_id IS '来源运行编号';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.node_id IS '来源节点编号';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.batch_id IS '来源质量批次';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.source_type IS '报告来源类型';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.plan_hash IS '规则计划摘要';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.idempotency_key IS '租户范围幂等键';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.request_hash IS '服务端计算的请求摘要';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.execution_user_id IS '受权执行身份';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.total_count IS '参与检测的行数';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.pass_count IS '合格行数';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.warn_count IS '警告行数';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.reject_count IS '不合格行数';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.issue_references_json IS '有界问题证据引用，不包含原始行';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.deleted IS '逻辑删除标识';

CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_push_alert (
    id bigserial PRIMARY KEY,
    tenant_id bigint NOT NULL CHECK (tenant_id > 0),
    task_id bigint NOT NULL,
    run_id bigint NOT NULL,
    execute_no varchar(64) NOT NULL,
    event_type varchar(32) NOT NULL CHECK (event_type IN ('UNKNOWN','DISPATCH_EXHAUSTED')),
    recipient_id bigint,
    task_name varchar(128) NOT NULL,
    status smallint NOT NULL DEFAULT 0 CHECK (status BETWEEN 0 AND 4),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    available_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lease_token varchar(36),
    lease_until timestamp(6),
    notify_message_id bigint,
    last_error varchar(128),
    occurred_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    handled_at timestamp(6),
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, run_id, event_type)
);
-- 表用途说明：推送关键终态告警持久投递账本；仅通知允许至少一次，不重发业务数据
COMMENT ON TABLE "datahub-center".dh_dataforge_push_alert IS '数据推送-告警投递记录';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.id IS '告警编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.task_id IS '推送任务编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.run_id IS '推送执行记录编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.execute_no IS '原执行关联编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.event_type IS '告警事件类型';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.recipient_id IS '冻结的通知接收者，缺失时进入待人工处置';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.task_name IS '冻结的任务名称，不含业务载荷';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.status IS '0待投递 1投递中 2已获站内信编号 3死信 4已人工接管';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.attempts IS '当前重试周期已领取次数';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.available_at IS '数据库时钟下可领取时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.lease_token IS '领取随机令牌';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.lease_until IS '领取截止时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.notify_message_id IS '站内信服务返回的消息编号，不代表用户已读';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.last_error IS '脱敏失败分类，不保存远端错误或载荷';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.occurred_at IS '原告警持久化时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.handled_at IS '确认投递或人工接管时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.creator IS '创建者';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.updater IS '更新者';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert.deleted IS '逻辑删除标志；待投递与死信不得清理';
CREATE INDEX IF NOT EXISTS idx_dataforge_push_alert_due ON "datahub-center".dh_dataforge_push_alert (available_at, id) WHERE deleted=0 AND status IN (0,1);
CREATE INDEX IF NOT EXISTS idx_dataforge_push_alert_dead ON "datahub-center".dh_dataforge_push_alert (tenant_id, id) WHERE deleted=0 AND status=3;
CREATE INDEX IF NOT EXISTS idx_dataforge_push_alert_delivered ON "datahub-center".dh_dataforge_push_alert (handled_at, tenant_id, id) WHERE status=2;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_push_alert_disposition (
    tenant_id bigint NOT NULL,
    command_id varchar(100) NOT NULL,
    alert_id bigint NOT NULL,
    action varchar(16) NOT NULL CHECK (action IN ('RETRY','ACKNOWLEDGE')),
    reason varchar(500) NOT NULL,
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id, command_id)
);
-- 表用途说明：推送告警死信人工操作审计；操作来源为受控XXL-Job执行编号，非用户身份自证
COMMENT ON TABLE "datahub-center".dh_dataforge_push_alert_disposition IS '数据推送-告警处置审计';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert_disposition.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert_disposition.command_id IS '受控调度执行编号，同编号不同请求拒绝';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert_disposition.alert_id IS '告警编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert_disposition.action IS 'RETRY重新投递或ACKNOWLEDGE人工接管，不改变原执行状态';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert_disposition.reason IS '核查原因或受控工单编号，禁止记录凭据';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_alert_disposition.create_time IS '数据库时钟操作时间';
