DROP TABLE IF EXISTS "datahub-center"."bpm_oa_leave";
CREATE TABLE "datahub-center"."bpm_oa_leave" (
  "id" int8 NOT NULL,
  "user_id" int8 NOT NULL,
  "type" int2 NOT NULL,
  "reason" varchar(200) COLLATE "pg_catalog"."default" NOT NULL,
  "start_time" timestamp(6) NOT NULL,
  "end_time" timestamp(6) NOT NULL,
  "day" int2 NOT NULL,
  "status" int2 NOT NULL,
  "process_instance_id" varchar(64) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."id" IS '请假表单主键';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."user_id" IS '申请人的用户编号';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."type" IS '请假类型';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."reason" IS '请假原因';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."start_time" IS '开始时间';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."end_time" IS '结束时间';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."day" IS '请假天数';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."status" IS '审批结果';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."process_instance_id" IS '流程实例的编号';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."bpm_oa_leave"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."bpm_oa_leave" IS 'OA 请假申请表';

