  "icon" varchar(512) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "description" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "form_type" int2 NOT NULL,
  "form_id" int8,
  "form_conf" text COLLATE "pg_catalog"."default",
  "form_fields" text COLLATE "pg_catalog"."default",
