  "allow_cancel_running_process" bool NOT NULL DEFAULT true,
  "allow_withdraw_task" bool NOT NULL DEFAULT false,
  "process_id_rule" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "auto_approval_type" int2 NOT NULL DEFAULT 0,
  "title_setting" varchar(512) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "summary_setting" varchar(512) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "process_before_trigger_setting" varchar(1024) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
