  "task_before_trigger_setting" varchar(1024) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "task_after_trigger_setting" varchar(1024) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "print_template_setting" varchar(4096) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
