-- ----------------------------
-- 表结构： dh_dataforge_datasource_driver
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_dataforge_datasource_driver";
CREATE TABLE "datahub-center"."dh_dataforge_datasource_driver" (
  "id" int8 NOT NULL,
  "driver_code" varchar(255) COLLATE "pg_catalog"."default",
  "driver_name" varchar(255) COLLATE "pg_catalog"."default",
  "product_type" varchar(255) COLLATE "pg_catalog"."default",
  "support_schema" int2,
  "jar_file_name" varchar(255) COLLATE "pg_catalog"."default",
  "jar_file_path" varchar(255) COLLATE "pg_catalog"."default",
  "jar_file_md5" varchar(255) COLLATE "pg_catalog"."default",
  "jar_file_size" float8,
  "sort" int4 NOT NULL DEFAULT 0,
  "status" int2 NOT NULL DEFAULT 0,
  "remark" varchar(512) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."driver_code" IS '驱动编码';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."driver_name" IS '驱动名称';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."product_type" IS '数据库产品类型：MYSQL、POSTGRESQL、ORACLE、HIVE、DORIS、CLICKHOUSE   字典数据';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."support_schema" IS '是否有 schema 概念：1有 0无';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."jar_file_name" IS '上传驱动 JAR 文件名称（内置为空）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."jar_file_path" IS '上传驱动 JAR 文件路径（内置为空，走 classpath）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."jar_file_md5" IS '上传驱动 JAR 文件 MD5';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."jar_file_size" IS '上传驱动 JAR 文件大小';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."sort" IS '显示排序号，数值越小越靠前';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."status" IS '状态：0启用，1停用';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."deleted" IS '是否删除：0未删除，1已删除';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_datasource_driver"."tenant_id" IS '租户编号，0表示平台级公共数据';
COMMENT ON TABLE "datahub-center"."dh_dataforge_datasource_driver" IS '数据源-驱动';

-- ----------------------------
-- 数据记录： dh_dataforge_datasource_driver
-- ----------------------------

