-- ----------------------------
-- 表结构： dh_dataforge_dev_record
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_dataforge_dev_record";
CREATE TABLE "datahub-center"."dh_dataforge_dev_record" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_dev_record_seq'::regclass),
  "task_id" int8 NOT NULL,
  "task_name" varchar(100) COLLATE "pg_catalog"."default",
  "database_id" int8,
  "datasource_name" varchar(100) COLLATE "pg_catalog"."default",
  "trigger_type" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'MANUAL'::character varying,
  "status" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'RUNNING'::character varying,
  "start_time" timestamp(6),
  "end_time" timestamp(6),
  "duration_ms" int8,
  "statement_total" int4 NOT NULL DEFAULT 0,
  "statement_success" int4 NOT NULL DEFAULT 0,
  "affected_rows" int8 NOT NULL DEFAULT 0,
  "ds_instance_id" int4,
  "log" text COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."task_id" IS '任务编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."task_name" IS '任务名称（冗余）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."database_id" IS '数据源编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."datasource_name" IS '数据源名称（冗余）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."trigger_type" IS '触发方式：MANUAL-手动 SCHEDULE-调度';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."status" IS '执行状态：RUNNING/SUCCESS/FAILED/STOPPED';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."start_time" IS '开始时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."end_time" IS '结束时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."duration_ms" IS '执行耗时（毫秒）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."statement_total" IS '语句总数';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."statement_success" IS '成功语句数';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."affected_rows" IS '累计影响行数';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."ds_instance_id" IS 'DolphinScheduler 工作流实例编号（集群任务用）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."log" IS '执行日志';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_dev_record"."updater" IS '最后更新者';
