  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_etl_tool_seq'::regclass),
  "parent_id" int8 NOT NULL DEFAULT 0,
  "name" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "icon" varchar(100) COLLATE "pg_catalog"."default",
  "type" int4 NOT NULL DEFAULT '-1'::integer,
  "code" varchar(100) COLLATE "pg_catalog"."default",
  "built_in" int2 NOT NULL DEFAULT 0,
  "enabled" int2 NOT NULL DEFAULT 1,
  "order_no" int4 NOT NULL DEFAULT 0,
  "description" varchar(300) COLLATE "pg_catalog"."default",
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."parent_id" IS '父级编号，0 表示根';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."name" IS '名称';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."icon" IS '图标';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."type" IS '类型：-1 目录 1 输入 2 转换 3 输出 4 脚本';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."code" IS '组件代码（决定执行器与前端编辑器）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."built_in" IS '是否内置：0-否 1-是';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."enabled" IS '是否启用：0-禁用 1-启用';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."order_no" IS '排序号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_tool"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."dh_dataforge_etl_tool" IS '可视化ETL-工具箱组件';

