INSERT INTO "datahub-center".dh_dataforge_etl_tool
    (id,parent_id,name,icon,type,code,built_in,enabled,order_no,description,tenant_id,creator,create_time,updater,update_time,deleted)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM "datahub-center".dh_dataforge_etl_tool),2,'行级质量检测','lucide:shield-check',2,
       'quality-check',1,1,24,'复用治理规则集并分流或标记数据，持久留存问题证据',1,'1',CURRENT_TIMESTAMP,'1',CURRENT_TIMESTAMP,0
WHERE NOT EXISTS (SELECT 1 FROM "datahub-center".dh_dataforge_etl_tool WHERE code='quality-check');


-- ----------------------------
-- 表结构： dh_dataforge_file
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_dataforge_file";
CREATE TABLE "datahub-center"."dh_dataforge_file" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_file_seq'::regclass),
  "name" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "file_category_id" int8 NOT NULL,
  "type" varchar(32) COLLATE "pg_catalog"."default",
  "file_url" varchar(2000) COLLATE "pg_catalog"."default" NOT NULL,
  "description" varchar(300) COLLATE "pg_catalog"."default",
  "size" int8,
  "org_id" int8,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."name" IS '文件名称';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."file_category_id" IS '所属分组编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."type" IS '文件后缀（不含点）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."file_url" IS '文件访问 URL（infra 文件服务返回）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."size" IS '文件大小（字节）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."org_id" IS '所属机构编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_file"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."dh_dataforge_file" IS '文件管理-数据文件';

