CREATE TABLE "datahub-center"."dh_dataforge_fill_notify_record" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_fill_notify_record_seq'::regclass),
  "notify_type" int2 NOT NULL,
  "task_id" int8,
  "work_item_id" int8,
  "receiver_user_id" int8 NOT NULL,
  "channel" int2 NOT NULL DEFAULT 1,
  "template_code" varchar(64) COLLATE "pg_catalog"."default",
  "content_summary" varchar(500) COLLATE "pg_catalog"."default",
  "send_status" int2 NOT NULL DEFAULT 0,
  "send_time" timestamp(6),
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."notify_type" IS '类型：1-指定填报人 2-转派/重新分配 3-任务开始 4-临近截止 5-已逾期 6-他人已提交 7-驳回 8-通过 9-合并成功 10-合并失败 11-催办';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."channel" IS '渠道：1-站内信 2-短信 3-邮件';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."send_status" IS '发送状态：0-待发送 1-已发送 2-发送失败';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_notify_record"."deleted" IS '逻辑删除标识：0-未删除 1-已删除';
-- 表用途说明：在线填报-通知与催办记录（送达能力受限于渠道，本表记录发送事实供看板与频控）
COMMENT ON TABLE "datahub-center"."dh_dataforge_fill_notify_record" IS '在线填报-通知与催办记录';

