DROP TABLE IF EXISTS "datahub-center"."dh_dataforge_fill_operation";
CREATE TABLE "datahub-center"."dh_dataforge_fill_operation" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_fill_operation_seq'::regclass),
  "work_item_id" int8 NOT NULL,
  "server_version" int8 NOT NULL,
  "client_op_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "client_session_id" varchar(64) COLLATE "pg_catalog"."default",
  "op_type" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "row_id" varchar(64) COLLATE "pg_catalog"."default",
  "field_code" varchar(64) COLLATE "pg_catalog"."default",
  "old_value" jsonb,
  "new_value" jsonb,
  "operator_user_id" int8 NOT NULL,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."server_version" IS '工作项内单调递增版本（协同拉取增量的游标）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."client_op_id" IS '客户端操作号（网络重试去重）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."op_type" IS '操作类型：SET_CELL/ADD_ROW/REMOVE_ROW/REORDER_ROW/IMPORT_CONFIRM/PREFILL';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."old_value" IS '旧值（敏感字段按制度脱敏/加密后存储）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."new_value" IS '新值（敏感字段按制度脱敏/加密后存储）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_operation"."deleted" IS '逻辑删除标识：0-未删除 1-已删除';
-- 表用途说明：在线填报-操作日志（只追加，协同重放与强审计事实源；一期不分区，唯一键以 work_item_id 前导为 HASH 分区预留；按留存策略归档清理，不得删除仍被快照/合并引用的数据）
COMMENT ON TABLE "datahub-center"."dh_dataforge_fill_operation" IS '在线填报-操作日志';

