-- ----------------------------
-- 表结构： dh_dataforge_fill_plan_category
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_dataforge_fill_plan_category";
CREATE TABLE "datahub-center"."dh_dataforge_fill_plan_category" (
    "id" bigint NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_fill_plan_category_seq'::regclass),
    "parent_id" bigint NOT NULL DEFAULT 0,
    "name" varchar(100) NOT NULL,
    "sort" integer NOT NULL DEFAULT 0,
    "tenant_id" bigint NOT NULL DEFAULT 1,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" smallint NOT NULL DEFAULT 0,
    CONSTRAINT "dh_dataforge_fill_plan_category_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "ck_dh_fill_plan_category_parent" CHECK ("parent_id" >= 0 AND "parent_id" <> "id"),
    CONSTRAINT "ck_dh_fill_plan_category_name" CHECK (length(btrim("name")) > 0),
    CONSTRAINT "ck_dh_fill_plan_category_sort" CHECK ("sort" BETWEEN 0 AND 9999)
);
COMMENT ON TABLE "datahub-center"."dh_dataforge_fill_plan_category" IS '采集计划-分类目录';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."id" IS '分类编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."parent_id" IS '父分类编号，根目录为 0';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."name" IS '分类名称';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."sort" IS '同级显示顺序';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan_category"."deleted" IS '逻辑删除标识：0-未删除 1-已删除';
CREATE UNIQUE INDEX "uk_dh_fill_plan_category_name"
    ON "datahub-center"."dh_dataforge_fill_plan_category" ("tenant_id", "parent_id", "name")
    WHERE "deleted" = 0;

-- ----------------------------
-- 表结构： dh_dataforge_fill_plan
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_dataforge_fill_plan";
CREATE TABLE "datahub-center"."dh_dataforge_fill_plan" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dataforge_fill_plan_seq'::regclass),
  "name" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "description" varchar(500) COLLATE "pg_catalog"."default",
  "table_id" int8 NOT NULL,
  "table_version_id" int8 NOT NULL,
  "period_type" int2 NOT NULL,
  "period_config" jsonb NOT NULL DEFAULT '{}'::jsonb,
  "time_zone" varchar(64) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'Asia/Shanghai'::character varying,
  "remind_config" jsonb,
  "overdue_policy" int2 NOT NULL DEFAULT 1,
  "process_definition_key" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "publish_approval_enabled" int2 NOT NULL DEFAULT 0,
  "prefill_last_period" int2 NOT NULL DEFAULT 0,
  "owner_org_id" int8,
  "status" int2 NOT NULL DEFAULT 0,
  "last_period_key" varchar(32) COLLATE "pg_catalog"."default",
  "next_generate_time" timestamp(6),
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "category_id" int8
)
;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."category_id" IS '计划分类编号，空值表示未分类';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."period_type" IS '周期类型：1-一次性 2-每日 3-每周 4-每月 5-每季度';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."period_config" IS '周期参数：周几/生成日/开放与截止偏移/一次性任务的起止时间等';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."remind_config" IS '提醒规则：临近截止提前量、催办频控等';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."overdue_policy" IS '逾期策略：1-软逾期（可继续提交并标记） 2-硬截止（锁定，需发起者延期）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."process_definition_key" IS 'BPM 流程定义 Key（任务发布时冻结具体 processDefinitionId）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."publish_approval_enabled" IS '任务发布审批开关：0-关 1-开（V1.1 §2.1 可选触点）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."prefill_last_period" IS '上期数据带入：0-关 1-开（生成工作项时复制上期已合并数据为初始草稿）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."status" IS '状态：0-草稿 1-启用 2-停用';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."last_period_key" IS '最近一次已生成任务的所属期（周期任务生成位点，用于停机追赶补生成）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."next_generate_time" IS '下次生成时间（生成 Job 扫描 + CAS 抢占）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_fill_plan"."deleted" IS '逻辑删除标识：0-未删除 1-已删除';
-- 表用途说明：在线填报-采集计划（周期规则与任务生成模板；creator 即任务发起者）
COMMENT ON TABLE "datahub-center"."dh_dataforge_fill_plan" IS '在线填报-采集计划';

