COMMENT ON COLUMN "datahub-center"."dh_dataforge_push_task_log"."error_info" IS '失败信息';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_push_task_log"."execute_no" IS '本次执行关联编号（手动及自动）';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_push_task_log"."org_id" IS '所属机构编号';
COMMENT ON COLUMN "datahub-center"."dh_dataforge_push_task_log"."heartbeat_time" IS '数据库时钟心跳；超时重新比较状态与心跳，发送后保留未知';
COMMENT ON TABLE "datahub-center"."dh_dataforge_push_task_log" IS '数据集成-数据推送执行日志';
CREATE INDEX IF NOT EXISTS idx_dataforge_push_unresolved
    ON "datahub-center".dh_dataforge_push_task_log (tenant_id, push_task_id, id)
    WHERE deleted=0 AND run_status IN (1,2,5);
COMMENT ON INDEX "datahub-center".idx_dataforge_push_unresolved IS '推送未确认运行与未知结果占位查询';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.dispatch_protocol IS '派发协议：0-旧记录禁止重领，1-持久受理及令牌隔离';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.dispatch_token IS '本次发送前领取随机令牌，心跳、发送与结果回写必须匹配，不对外返回';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.dispatch_lease_until IS '数据库时钟领取期限；仅发送前可接管，发送后到期保留未知';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.dispatch_attempts IS '本次持久意图领取次数，达到上限时发送前失败留痕';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.next_dispatch_at IS '数据库时钟下次发送前领取时间，队列拒绝退避不丢执行意图';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.scheduled_time IS '本次受理对应原始到期时间，非周期触发为空';
CREATE INDEX IF NOT EXISTS idx_dataforge_push_dispatch_pending
    ON "datahub-center".dh_dataforge_push_task_log (next_dispatch_at, dispatch_lease_until, id)
    WHERE deleted=0 AND dispatch_protocol=1 AND run_status=1;
COMMENT ON INDEX "datahub-center".idx_dataforge_push_dispatch_pending IS '推送持久等待领取及发送前失联恢复扫描';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.resolution_request_id IS '人工处置幂等请求编号，租户内唯一，普通清理不得删除';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.resolution_outcome IS '人工核查结论：NO_EFFECT-全部未生效，COMPENSATED-已完整补偿；不代表推送成功';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.resolution_reason IS '人工处置原因，禁止记录凭据或业务载荷';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.stopped_evidence_ref IS '旧工作者及远端请求终止的受控证据编号；超时与租约到期不构成证明';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.output_evidence_ref IS '本次运行全部批次与异步消费结果未生效或已完整补偿的受控证据编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.resolved_by IS '核查操作者编号，从可信登录上下文取得';
COMMENT ON COLUMN "datahub-center".dh_dataforge_push_task_log.resolved_at IS '数据库时钟下人工处置提交时间';
CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_push_resolution_request
    ON "datahub-center".dh_dataforge_push_task_log (tenant_id, resolution_request_id)
    WHERE resolution_request_id IS NOT NULL;
COMMENT ON INDEX "datahub-center".uk_dataforge_push_resolution_request IS '人工核查请求租户内唯一，含已删除记录，禁止复用请求号篡改核查结论';
CREATE INDEX IF NOT EXISTS idx_dataforge_push_alert_missing ON "datahub-center".dh_dataforge_push_task_log (id, tenant_id) WHERE deleted=0 AND run_status=5;
COMMENT ON INDEX "datahub-center".idx_dataforge_push_alert_missing IS '历史未知告警补账的有界候选扫描索引';

