COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."type" IS '系统类型';
COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."owner_user_id" IS '负责人ID';
COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."description" IS '说明';
