COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."dept_id" IS '所属部门id';
COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."status" IS '状态：0停用 1启用';
COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."dh_foundation_system_source"."creator" IS '创建者';
