INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (1, '字段字符类型校验', 5, 1, '107', 'CHARACTER_VALIDATION', '检查字段值是否为期望的字符组成（字母、数字等）', '检查字段值是否为期望的字符组成（字母、数字等）', '• 手机号字段应为纯数字，出现“+86-138****”或“138x123”触发告警
