INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (2, '字段长度范围校验', 2, 1, '108', 'LENGTH_VALIDATION', '检查字段长度是否在定义范围内（如11位手机号）', '检查字段长度是否在定义范围内（如11位手机号）', '• 手机号字段必须为11位，过长/过短为非法
• 银行卡号字段不得超过19位
• 姓名字段超过50字符为异常（如自动抓取异常数据）', 0, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (3, '日期时间格式校验', 2, 1, '109', NULL, '检查字段值是否为合法的时间格式（如yyyy-MM-dd）', '检查字段值是否为合法的时间格式（如yyyy-MM-dd）', '• 日期字段要求格式为yyyy-MM-dd，禁止yyyy/MM/dd或中文日期格式
• 日期时间字段必须为yyyy-MM-dd HH:mm:ss，缺失秒或用12小时制视为非法
• 禁止出现“0000-00-00”或“1970-01-01”作为默认占位', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (4, '数值精度校验', 2, 1, '110', 'DECIMAL_PRECISION_VALIDATION', '检查小数位数是否符合业务定义（如保留2位）', '检查小数位数是否符合业务定义（如保留2位）', '• 金额字段小数点后最多保留2位，保留3位或更多为异常
• 利率字段精度需为4位，如0.0523，不能为0.052312', 0, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (5, '枚举值校验', 2, 1, '111', 'ENUM_VALIDATION', '检查字段值是否在字典或枚举集中', '检查字段值是否在字典或枚举集中', '• 性别字段仅允许“男/女/未知”，出现“female”、“1”视为非法
• 订单状态字段必须在“已下单/已付款/已发货/已取消”内', 0, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (6, '主数据引用一致性校验', 2, 1, '112', NULL, '检查引用字段是否在主数据中存在', '检查引用字段是否在主数据中存在', '• 客户ID字段在客户主数据中找不到对应记录则视为无效
• 门店编码未能在门店主数据中匹配成功时标记为脏数据', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (7, '逻辑模型一致性校验', 2, 1, '113', NULL, '检查表结构是否与数据模型一致', '检查表结构是否与数据模型一致', '• 数据集字段数量多于模型定义（如多出“备用字段1~3”）则为冗余字段
• 数据类型与模型不符，如应为decimal结果为varchar', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (8, '字段元信息完整性校验', 2, 1, '114', NULL, '检查字段是否配置必要的元信息（类型、说明等）', '检查字段是否配置必要的元信息（类型、说明等）', '• 字段未配置中文名称或业务定义，不利于后续治理与血缘追踪
• 缺失字段类型定义，影响自动校验与建模', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (9, '时间字段顺序逻辑校验', 2, 1, '115', 'TIME_ORDER_VALIDATION', '检查多个时间字段之间的前后逻辑', '检查多个时间字段之间的前后逻辑', '• 订单完成时间早于创建时间为异常
• 上岗时间应早于离职时间', 0, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (10, '数值字段逻辑关系校验', 2, 1, '116', NULL, '检查多个数值字段之间的业务逻辑关系', '检查多个数值字段之间的业务逻辑关系', '• 实际付款金额不得超过应付款，否则为溢付错误
• 销售数量不得超过库存数量', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (11, '状态字段依赖项校验', 2, 1, '117', NULL, '检查某状态下是否填写了必须字段', '检查某状态下是否填写了必须字段', '• 状态=已取消时，取消原因字段不能为空
• 状态=完成时，必须填写完成时间、操作人', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (12, '互斥字段冲突校验', 2, 1, '118', NULL, '检查不能同时存在的字段值是否冲突', '检查不能同时存在的字段值是否冲突', '• 内部客户标志与外部客户标志只能选其一
• 线上订单标识与线下订单标识不能同时为“是”', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (13, '敏感字段脱敏校验', 2, 1, '119', NULL, '检查敏感字段是否存在明文泄露风险', '检查敏感字段是否存在明文泄露风险', '• 客户手机号展示为“138****1234”
• 身份证号仅展示前6位和最后4位，中间脱敏
• 银行卡号仅展示后四位，其余使用“*”替代', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (14, '必填字段非空校验', 5, 1, '203', NULL, '检查强制必填字段是否存在空值', '检查强制必填字段是否存在空值', '• 用户ID、订单号、收件地址等字段不能为空
• 财务系统中凭证编号为强制必填项', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (15, '非法占位值识别', 5, 1, '204', NULL, '检查是否使用非法占位（如N/A、-999）替代有效值', '检查是否使用非法占位（如N/A、-999）替代有效值', '• 年龄字段为-1、“N/A”、NULL等值视为缺失
