INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (16, '字段组完整性校验', 1, 1, '205', 'GROUP_FIELD_COMPLETENESS', '检查逻辑上应成对出现的字段是否齐全', '检查逻辑上应成对出现的字段是否齐全', '• 经纬度缺一不可，否则无法定位
