INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (17, '整记录缺失检查校验', 5, 1, '206', NULL, '检查是否存在除主键外字段全为空的记录', '检查是否存在除主键外字段全为空的记录', '• 某条记录仅有主键，其他字段全为空，应标记为垃圾数据
