INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (18, '条件字段完整性校验', 5, 1, '207', NULL, '检查满足某条件时，相关字段是否已填写', '检查满足某条件时，相关字段是否已填写', '• 是否加班=是，则加班工时不能为空
