INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (19, '数值字段范围校验', 1, 1, '306', 'NUMERIC_RANGE_VALIDATION', '检查字段值是否落在业务定义的合理区间', '检查字段值是否落在业务定义的合理区间', '• 年龄字段不得小于0或大于120
• 折扣字段不得超过100%，小于0也不合法', 0, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (20, '数值字段逻辑值合法校验', 1, 1, '307', NULL, '校验字段值是否违反业务规则（如库存不为负，销售额不能小于0）', '校验字段值是否违反业务规则（如库存不为负，销售额不能小于0）', '• 销售额出现负值为异常，需判断是否退款未记录
• 库存为负说明有异常出库操作', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (21, '数值字段异常值识别', 1, 1, '308', NULL, '检测异常的极端数值或明显错误数据', '检测异常的极端数值或明显错误数据', '• 薪资字段为“99999999”视为默认或错误写入
• 年龄=200、商品价格=0.01等为极端可疑值', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (22, '脏数据识别', 1, 1, '309', NULL, '标记无意义、无效或错误占位的数据值', '标记无意义、无效或错误占位的数据值', '• 性别字段为“unknown”、错误拼写如“Unkown”应纠正或剔除
• 组织名称字段为“test”、“123”等为无效数据', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (23, '单字段唯一性校验', 1, 1, '310', NULL, '检查字段值是否唯一（如订单号）', '检查字段值是否唯一（如订单号）', '• 订单号重复会导致资金、库存重复记录
• 员工编号重复会干扰排班与考勤', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (24, '多字段组合唯一性校验', 1, 1, '311', 'COMPOSITE_UNIQUENESS_VALIDATION', '检查字段组合在全表中是否唯一', '检查字段组合在全表中是否唯一', '• 同一用户在某一天只能有一条签到记录
• [门店+SKU+日期] 不得重复出现', 0, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (25, '跨表字段值一致性校验', 3, 1, '403', NULL, '检查同一字段在不同表间是否值一致', '检查同一字段在不同表间是否值一致', '• 用户表中姓名与订单表中收件人姓名需一致
• 员工信息在HR表与考勤表中性别字段不能冲突', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (26, '外键有效性校验', 3, 1, '404', NULL, '检查外键值是否存在于目标主表中', '检查外键值是否存在于目标主表中', '• 订单表中商品ID必须能在商品主表中找到
• 工单记录引用的操作人ID必须在员工表中存在', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (27, '状态字段一致性校验', 3, 1, '405', NULL, '检查状态与其他字段值是否存在逻辑冲突', '检查状态与其他字段值是否存在逻辑冲突', '• 状态=未审核但存在审核时间，说明数据录入异常
• 状态=草稿但存在付款金额不应出现', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);
INSERT INTO "datahub-center"."dh_governance_audit_rule" VALUES (28, '时间字段先后顺序校验', 4, 1, '504', NULL, '检查时间字段是否有逻辑上的早晚关系', '流程控制、事件日志、审批流程等', '• 项目开始时间不能晚于结束时间
• 发货时间不能早于下单时间', 1, '1', '2026-08-28 13:29:27.722764', '1', '2026-08-28 13:29:27.722764', 0, 1);

