-- ----------------------------
-- 表结构： dh_governance_category_standard
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_governance_category_standard";
CREATE TABLE "datahub-center"."dh_governance_category_standard" (
  "id" int8 NOT NULL,
  "parent_id" int8 NOT NULL DEFAULT 0,
  "category_name" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "category_code" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "sort" int4 NOT NULL DEFAULT 0,
  "status" int2 NOT NULL DEFAULT 1,
  "remark" text COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."parent_id" IS '父级ID';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."category_name" IS '类目名称';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."category_code" IS '层级编码';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."sort" IS '排序';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."status" IS '状态：0停用 1启用';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."dh_governance_category_standard"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."dh_governance_category_standard" IS '全局管理-标准分类类目管理';

