-- ----------------------------
-- 表结构： dh_governance_clean_rule
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_governance_clean_rule";
CREATE TABLE "datahub-center"."dh_governance_clean_rule" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_governance_clean_rule_seq'::regclass),
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "category_id" int8 NOT NULL,
  "rule_level" int2 NOT NULL DEFAULT 1,
  "code" varchar(32) COLLATE "pg_catalog"."default",
  "strategy_key" varchar(64) COLLATE "pg_catalog"."default",
  "description" varchar(500) COLLATE "pg_catalog"."default",
  "use_case" varchar(500) COLLATE "pg_catalog"."default",
  "example" varchar(2000) COLLATE "pg_catalog"."default",
  "status" int2 NOT NULL DEFAULT 0,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."name" IS '规则名称';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."category_id" IS '清洗规则类目编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."rule_level" IS '规则级别：1-字段级 2-表级';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."code" IS '规则编码';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."strategy_key" IS '策略标识（质量引擎清洗函数），为空表示暂未接入引擎';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."description" IS '规则描述';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."use_case" IS '使用场景';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."example" IS '示例';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."status" IS '状态：0-启用 1-停用';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."update_time" IS '最后更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."deleted" IS '逻辑删除标识：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_governance_clean_rule"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."dh_governance_clean_rule" IS '数据治理-清洗规则';

