INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (1, '数值边界调整', 75, 1, '001', 'WITHIN_BOUNDARY', '将超出预设范围的数值调整为范围的边界值', '将超出预设范围的数值调整为范围的边界值', '年龄 > 150 → 设置为 150', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (2, '字段值替换', 75, 1, '002', 'VALUE_REPLACE', '将不符合预设规则的数据值替换为指定的默认值或空值', '将不符合预设规则的数据值替换为指定的默认值或空值', '状态字段值为“abc” → 替换为“未知”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (3, '字符串转数值', 77, 1, '003', NULL, '将纯数字字符串转换为数值类型', '将纯数字字符串转换为数值类型', '“1000” → 1000', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (4, '字符串转日期', 77, 1, '004', NULL, '将符合格式的字符串转换为日期类型', '将符合格式的字符串转换为日期类型', '“2025-07-01” → 日期类型', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (5, '任意类型转布尔值', 77, 1, '005', NULL, '将“是/否”、“1/0”、“true/false”等转换为布尔值', '将“是/否”、“1/0”、“true/false”等转换为布尔值', '“是” → true', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (6, '手机号格式统一', 79, 1, '006', 'PHONE_FORMAT_STD', '统一手机号为国内11位纯数字格式，去除国家码、空格、短横线等', '统一手机号为国内11位纯数字格式，去除国家码、空格、短横线等', '“+86-138 1234 5678” → “13812345678”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (7, '日期格式统一', 79, 1, '007', 'DATE_FORMAT_STD', '统一各种日期格式为指定标准格式（如 yyyy-MM-dd），支持配置模板', '统一各种日期格式为指定标准格式（如 yyyy-MM-dd），支持配置模板', '“20250701” → “2025-07-01”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (8, '小数位统一', 79, 1, '008', 'FIX_TO_PRECISION', '将数值字段统一保留指定的小数位数（如保留两位小数）', '将数值字段统一保留指定的小数位数（如保留两位小数）', '“12.3” → “12.30”；“100” → “100.00”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (9, '去除字段空格', 79, 1, '009', 'REMOVE_WHITESPACE', '去除字段中的前后空格或中间多余空格，提升匹配准确性', '去除字段中的前后空格或中间多余空格，提升匹配准确性', '“  山西 省  ” → “山西省”，收尾、中间等', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (10, '字段前缀/后缀统一', 79, 1, '010', 'ADD_PREFIX_SUFFIX', '对字段值统一加前缀或后缀，或去除非业务所需的标记', '对字段值统一加前缀或后缀，或去除非业务所需的标记', '“编号123” → 去除“编号” → “123”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (11, '正则表达式替换', 79, 1, '011', 'SIMPLE_REPLACE', '通过正则表达式匹配符合特定规则的文本，并将其批量替换为指定内容', '通过正则表达式匹配符合特定规则的文本，并将其批量替换为指定内容', '使用 (\d{4})/(\d{2})/(\d{2}) 匹配 2026/08/18，替换为 $1-$2-$3 后得到 2026-08-18', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (12, '超长字段截断', 81, 1, '012', 'STRING_SUBSTR', '当字段长度超过指定长度时进行截断处理', '当字段长度超过指定长度时进行截断处理', '描述字段超100字符 → 截取前100字符', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (13, '字段补零', 81, 1, '013', NULL, '在字段前/后补0，保持固定长度', '在字段前/后补0，保持固定长度', '组织编码“1” → 补全为“00001”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (14, '数值空值填充', 83, 1, '014', NULL, '将空的数值字段填充为指定默认值（如 0、-1、平均数等）', '将空的数值字段填充为指定默认值（如 0、-1、平均数等）', '年龄字段为空 → 配置默认值为 0', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (15, '字符串空值填充', 83, 1, '015', NULL, '将空的字符串字段填充为指定字符（如“未知”、“无”）', '将空的字符串字段填充为指定字符（如“未知”、“无”）', '籍贯字段为空 → 配置默认值为“未知”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (16, '布尔空值填充', 83, 1, '016', NULL, '布尔字段为空时填充为指定布尔值（如 false / true）', '布尔字段为空时填充为指定布尔值（如 false / true）', '是否启用字段为空 → 配置默认值为 false', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (17, '日期空值填充', 83, 1, '017', 'DATE_FILL_NULL', '日期字段为空时填充为配置的默认日期（如当前日期、昨天、固定值等）', '日期字段为空时填充为配置的默认日期（如当前日期、昨天、固定值等）', '注册时间为空 → 配置默认值为“当前日期”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (18, '全字段为空删除', 85, 1, '018', NULL, '整行所有字段都为空、null 或空字符串时，直接删除该记录', '整行所有字段都为空、null 或空字符串时，直接删除该记录', '{姓名: null, 手机: "", 地址: null} → 删除', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (19, '组合字段为空删除', 85, 1, '019', 'REMOVE_EMPTY_COMBINATION', '配置关键字段（如主键）为空时，删除整行记录', '配置关键字段（如主键）为空时，删除整行记录', '用户ID为 null → 删除该记录', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (20, '单位标准化类', 87, 1, '020', NULL, '将字段中的值根据配置的换算关系，从源单位换算为目标单位，保留数值精度', '将字段中的值根据配置的换算关系，从源单位换算为目标单位，保留数值精度', '“2.5 万元” → “25000 元”；“3 kg” → “3000 g”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (21, '字段值转大写', 89, 1, '021', 'TO_UPPERCASE', '将字段值统一转为全大写，适用于省份、代码、简称等字段', '将字段值统一转为全大写，适用于省份、代码、简称等字段', '“shanxi” → “SHANXI”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (22, '字段值转小写', 89, 1, '022', 'TO_LOWERCASE', '将字段值统一转为全小写，适用于邮箱、域名等字段', '将字段值统一转为全小写，适用于邮箱、域名等字段', '“EXAMPLE@MAIL.COM” → “example@mail.com”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (23, '字段值首字母大写', 89, 1, '023', NULL, '将字段中的每个单词首字母大写，其余转为小写', '将字段中的每个单词首字母大写，其余转为小写', '“beijing city” → “Beijing City”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (24, '枚举值映射标准化', 91, 1, '024', 'MENU_CUSTOM', '将字段值根据配置字典进行映射替换，确保值域统一', '将字段值根据配置字典进行映射替换，确保值域统一', '“1” → “启用”；“0” → “停用”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (25, '按主键去重（保留首条）', 92, 1, '025', 'PK_DEDUP_FIRST', '按指定唯一标识字段对记录去重，仅保留首条出现的数据，适用于无时间戳场景', '按指定唯一标识字段对记录去重，仅保留首条出现的数据，适用于无时间戳场景', '按“客户ID”去重，保留最先出现的记录', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (26, '按主键去重（按时间字段保留最新）', 92, 1, '026', NULL, '配置时间字段，在重复记录中仅保留时间最新的一条', '配置时间字段，在重复记录中仅保留时间最新的一条', '按“订单编号”去重，保留“更新时间”最大的一条记录', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (27, '按优先级字段保留记录', 92, 1, '027', NULL, '当记录存在多个来源或等级标记时，按照优先级高的记录进行保留', '当记录存在多个来源或等级标记时，按照优先级高的记录进行保留', '“数据来源”为“系统录入”优先于“Excel导入”，如果多条都是“系统录入”则应用最新一条', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (28, '按非空字段优先保留记录', 92, 1, '028', NULL, '当关键字段存在空值时，优先保留值完整的记录', '当关键字段存在空值时，优先保留值完整的记录', '两条重复记录中一条手机号为空 → 保留手机号不为空的那条', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (29, '按组合字段去重（保留最新或首条）', 92, 1, '029', 'KEEP_LATEST_OR_FIRST', '指定多个字段作为联合唯一键，对重复记录进行去重，可配置保留策略（首条、最新）', '指定多个字段作为联合唯一键，对重复记录进行去重，可配置保留策略（首条、最新）', '按“用户ID + 年份”去重，保留“更新时间”最大的一条记录', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (30, '替换无效数值', 93, 1, '030', NULL, '将不在合法范围内的数值字段替换为指定默认值（如负数、过大值、异常标识值）', '将不在合法范围内的数值字段替换为指定默认值（如负数、过大值、异常标识值）', '年龄字段为 -1 或 999 → 替换为 null 或 0', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (31, '替换非法枚举值', 93, 1, '031', NULL, '当字段值不在指定值域集合中时，替换为默认值或空值', '当字段值不在指定值域集合中时，替换为默认值或空值', '状态字段值为“异常值99” → 替换为“未知”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (32, '替换无效时间格式', 93, 1, '032', NULL, '当字段值不符合日期时间标准格式时，替换为默认时间或空值', '当字段值不符合日期时间标准格式时，替换为默认时间或空值', '“32/13/2023” → 替换为 null 或“1970-01-01”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (33, '替换非法布尔值', 93, 1, '033', NULL, '将字段中不符合布尔定义的值替换为默认布尔值', '将字段中不符合布尔定义的值替换为默认布尔值', '“abc” → 替换为 false', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (34, '关键词脱敏', 98, 1, '034', NULL, '将字段值中包含的敏感词进行掩码处理，支持配置脱敏字符', '将字段值中包含的敏感词进行掩码处理，支持配置脱敏字符', '“这是一条涉黄内容” → “这是一条***内容”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (35, '敏感词替换', 98, 1, '035', NULL, '将命中词表中的敏感词替换为指定文本（如“未知”、“违规内容”）', '将命中词表中的敏感词替换为指定文本（如“未知”、“违规内容”）', '“暴恐言论” → 替换为“违规内容”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (36, '修正未来时间值', 95, 1, '036', NULL, '当时间字段值晚于当前时间时，自动修正为当前时间或指定边界值', '当时间字段值晚于当前时间时，自动修正为当前时间或指定边界值', '注册时间为“2099-12-31” → 替换为“当前系统时间”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (37, '校正超前时间差值', 95, 1, '037', NULL, '当字段时间超过当前时间指定间隔（如7天）时，进行修正处理', '当字段时间超过当前时间指定间隔（如7天）时，进行修正处理', '预约时间为当前时间+15天 → 替换为“当前时间+7天”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (38, '填补空时间为当前时间', 96, 1, '038', NULL, '当时间字段为空时，填充为系统当前时间或默认时间', '当时间字段为空时，填充为系统当前时间或默认时间', '更新时间字段为 null → 替换为“2025-07-18 10:00:00”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (39, '清理过期记录', 97, 1, '039', 'CHECK_EXPIRATION', '当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除', '当记录中的时间字段早于当前时间指定阈值时（如30天），标记或删除', '最后登录时间早于30天前 → 该用户记录设为“过期”', 0, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);
INSERT INTO "datahub-center"."dh_governance_clean_rule" VALUES (40, '修正历史时间边界', 97, 1, '040', NULL, '当字段值早于系统可接受最早时间时，替换为指定边界值', '当字段值早于系统可接受最早时间时，替换为指定边界值', '创建时间为“1900-01-01” → 替换为“2000-01-01”', 1, '1', '2026-08-28 13:34:35.126799', '1', '2026-08-28 13:34:35.126799', 0, 1);


-- ----------------------------
-- 表结构： dh_governance_master_catalog
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_governance_master_catalog";
CREATE TABLE "datahub-center"."dh_governance_master_catalog" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_governance_master_catalog_seq'::regclass),
  "parent_id" int8 NOT NULL DEFAULT 0,
  "type" int2 NOT NULL DEFAULT 0,
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "order_no" int4 NOT NULL DEFAULT 0,
  "description" varchar(300) COLLATE "pg_catalog"."default",
  "path" varchar(500) COLLATE "pg_catalog"."default" NOT NULL,
  "org_id" int8,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."parent_id" IS '父级编号，0 表示根';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."type" IS '节点类型：0-普通目录 1-主数据（下挂模型）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."name" IS '节点名称';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."order_no" IS '同级排序号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."path" IS '完整路径（各级名称以 / 拼接）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."org_id" IS '所属机构编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_catalog"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."dh_governance_master_catalog" IS '主数据管理-主数据目录';

