COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."field_type" IS 'dbswitch 逻辑类型：1-小数 2-字符串 3-日期 4-布尔 5-整数 6-长整型 9-日期时间 10-时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."field_length" IS '字段长度';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."field_scale" IS '小数位数';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."nullable" IS '是否可为空：0-否 1-是';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."pk" IS '是否主键：0-否 1-是';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."sort" IS '字段顺序（建表与页面展示顺序）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_column"."standard_element_id" IS '绑定的标准数据元编号';
COMMENT ON TABLE "datahub-center"."dh_governance_master_column" IS '主数据管理-模型字段';

