COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."name" IS '派发名称';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."distribute_type" IS '派发类型：1-数据库 2-API 3-消息队列';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."distribute_json" IS '派发配置（按类型只保留 db / api / mq 节点）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."status" IS '发布状态：0-未发布 1-已发布';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."task_type" IS '调度类型：1-一次性 2-周期性';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."cron" IS 'Cron 表达式（周期任务）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."next_run_time" IS '下次执行时间（周期任务调度扫描用）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."release_time" IS '发布时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."release_user_id" IS '发布人编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."org_id" IS '所属机构编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."dh_governance_master_distribute" IS '主数据管理-派发任务';

