  "distribute_id" int8 NOT NULL,
  "master_model_id" int8 NOT NULL,
  "run_type" int2 NOT NULL DEFAULT 1,
  "run_status" int2 NOT NULL,
  "start_time" timestamp(6) NOT NULL,
  "end_time" timestamp(6),
  "error_info" text COLLATE "pg_catalog"."default",
  "data_count" int8 NOT NULL DEFAULT 0,
  "byte_count" varchar(50) COLLATE "pg_catalog"."default" NOT NULL DEFAULT '0'::character varying,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."distribute_id" IS '派发任务编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."master_model_id" IS '主数据模型编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."run_type" IS '触发方式：1-自动调度 2-手动执行';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."run_status" IS '运行状态：2-运行中 3-成功 4-失败';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."start_time" IS '开始时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."end_time" IS '结束时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."error_info" IS '错误信息（异常堆栈摘要）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."data_count" IS '派发记录数';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."byte_count" IS '派发数据量（可读格式，如 12KB）';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_master_distribute_log"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."dh_governance_master_distribute_log" IS '主数据管理-派发执行记录';

