 ADD COLUMN IF NOT EXISTS schedule_generation bigint NOT NULL DEFAULT 0;
ALTER TABLE "datahub-center".dh_governance_master_distribute_log
 ADD COLUMN IF NOT EXISTS run_protocol smallint NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS lease_token varchar(36),
 ADD COLUMN IF NOT EXISTS lease_until timestamp(6),
 ADD COLUMN IF NOT EXISTS attempts integer NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS available_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
 ADD COLUMN IF NOT EXISTS schedule_generation bigint,
 ADD COLUMN IF NOT EXISTS scheduled_for timestamp(6);
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute.schedule_generation IS '发布和取消排期代际，防止旧扫描触发新排期';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.run_protocol IS '运行协议：零为历史，一为持久受理和发送边界';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.lease_token IS '随机领取令牌，隔离迟到工作者';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.lease_until IS '数据库时钟租约截止时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.attempts IS '发送前领取次数，上限五次';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.available_at IS '等待记录下次可领取时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.schedule_generation IS '受理时冻结的排期代际';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.scheduled_for IS '原始周期槽位，手动和一次性为空';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.run_status IS '运行状态：1-等待派发 2-已进入发送 3-成功 4-发送前失败 5-结果未知待核查';
CREATE INDEX IF NOT EXISTS idx_master_distribute_blocking ON "datahub-center".dh_governance_master_distribute_log(tenant_id,distribute_id,run_status)
 WHERE deleted=0 AND run_status IN (1,2,5);
CREATE INDEX IF NOT EXISTS idx_master_distribute_recovery ON "datahub-center".dh_governance_master_distribute_log(available_at,id)
 WHERE deleted=0 AND run_protocol=1 AND run_status IN (1,2);
CREATE UNIQUE INDEX IF NOT EXISTS uk_master_distribute_active ON "datahub-center".dh_governance_master_distribute_log(tenant_id,distribute_id)
 WHERE deleted=0 AND run_protocol=1 AND run_status IN (1,2);
CREATE UNIQUE INDEX IF NOT EXISTS uk_master_distribute_slot ON "datahub-center".dh_governance_master_distribute_log(tenant_id,distribute_id,schedule_generation,scheduled_for)
 WHERE deleted=0 AND run_protocol=1 AND scheduled_for IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_master_distribute_due ON "datahub-center".dh_governance_master_distribute(next_run_time,id)
 WHERE deleted=0 AND status=1 AND next_run_time IS NOT NULL;

-- 主数据派发核查审计，已包含增量0061；保留原始未知结果，不自动解锁。
ALTER TABLE "datahub-center".dh_governance_master_distribute_log
    ADD COLUMN IF NOT EXISTS resolution_request_id varchar(36),
    ADD COLUMN IF NOT EXISTS resolution_outcome varchar(32),
    ADD COLUMN IF NOT EXISTS resolution_reason varchar(500),
    ADD COLUMN IF NOT EXISTS stopped_evidence_ref varchar(160),
    ADD COLUMN IF NOT EXISTS output_evidence_ref varchar(160),
    ADD COLUMN IF NOT EXISTS resolved_by bigint,
    ADD COLUMN IF NOT EXISTS resolved_at timestamp(6);
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.resolution_request_id IS '人工核查幂等请求编号，租户内唯一，不得清理或复用';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.resolution_outcome IS '人工核查结论：NO_EFFECT-全部未生效，COMPENSATED-已完整补偿，不代表派发成功';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.resolution_reason IS '核查原因，禁止记录凭据或业务载荷';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.stopped_evidence_ref IS '旧工作者及远端请求和异步消费终止的受控证据编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.output_evidence_ref IS '全部输出未生效或已完整补偿的受控证据编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.resolved_by IS '可信登录上下文核查操作者编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.resolved_at IS '数据库时钟下人工核查提交时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_log.run_status IS '运行状态：1-等待派发 2-已进入发送 3-成功 4-发送前失败（旧协议不保证）5-结果未知待核查 6-已人工核查处置（非成功）';
CREATE UNIQUE INDEX IF NOT EXISTS uk_master_distribute_resolution_request
    ON "datahub-center".dh_governance_master_distribute_log(tenant_id,resolution_request_id) WHERE resolution_request_id IS NOT NULL;
COMMENT ON INDEX "datahub-center".uk_master_distribute_resolution_request IS '核查请求租户内唯一，含逻辑删除凭证，不得复用以篡改审计';

-- 主数据派发独立停止凭证，已包含增量0065；不改变发布、排期或任何历史运行状态。
SET search_path TO "datahub-center", public;
ALTER TABLE dh_governance_master_distribute_log
    ADD COLUMN IF NOT EXISTS stop_requested_by bigint,
    ADD COLUMN IF NOT EXISTS stop_requested_at timestamp(6),
    ADD COLUMN IF NOT EXISTS stop_reason varchar(500);
COMMENT ON COLUMN dh_governance_master_distribute_log.stop_requested_by IS '可信登录上下文中的停止操作者，停止凭证不得覆盖';
COMMENT ON COLUMN dh_governance_master_distribute_log.stop_requested_at IS '数据库时钟下停止命令受理时间，不证明工作者或远端已终止';
COMMENT ON COLUMN dh_governance_master_distribute_log.stop_reason IS '停止原因，禁止填写凭据或业务载荷；同次运行重试必须保持一致';
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_master_distribute_log'::regclass
                   AND conname='ck_master_distribute_stop_audit') THEN
        ALTER TABLE dh_governance_master_distribute_log ADD CONSTRAINT ck_master_distribute_stop_audit CHECK (
            (stop_requested_by IS NULL AND stop_requested_at IS NULL AND stop_reason IS NULL)
            OR (stop_requested_by IS NOT NULL AND stop_requested_by>0 AND stop_requested_at IS NOT NULL
                AND stop_reason IS NOT NULL AND length(btrim(stop_reason))>0 AND run_protocol=1 AND run_status IN (4,5,6))
        );
    END IF;
END $$;
COMMENT ON CONSTRAINT ck_master_distribute_stop_audit ON dh_governance_master_distribute_log IS '停止凭证全空或完整，必须保留发送边界对应终态，不代替人工核查';

