-- 数据记录： dh_governance_master_distribute_log
-- ----------------------------

-- 主数据派发关键终态告警账本，已包含增量0063；不回填或改写业务执行状态。
CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_master_distribute_alert (
    id bigserial PRIMARY KEY,
    tenant_id bigint NOT NULL CHECK (tenant_id > 0),
    task_id bigint NOT NULL,
    run_id bigint NOT NULL,
    event_type varchar(32) NOT NULL CHECK (event_type IN ('UNKNOWN','DISPATCH_EXHAUSTED')),
    recipient_id bigint,
    task_name varchar(128) NOT NULL,
    status smallint NOT NULL DEFAULT 0 CHECK (status BETWEEN 0 AND 4),
    attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
    available_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    lease_token varchar(36),
    lease_until timestamp(6),
    notify_message_id bigint,
    last_error varchar(128),
    occurred_at timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    handled_at timestamp(6),
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    UNIQUE (tenant_id, run_id, event_type)
);
-- 表说明（原文）：主数据派发关键终态告警持久投递账本；仅通知允许至少一次，不重发业务数据
COMMENT ON TABLE "datahub-center".dh_governance_master_distribute_alert IS '主数据管理-派发告警投递记录';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.id IS '告警编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.task_id IS '主数据派发任务编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.run_id IS '主数据派发执行记录编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.event_type IS '告警事件类型';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.recipient_id IS '冻结的通知接收者，缺失时进入待人工处置';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.task_name IS '冻结的任务名称，不含业务载荷';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.status IS '0待投递 1投递中 2已获站内信编号 3死信 4已人工接管';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.attempts IS '当前重试周期已领取次数';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.available_at IS '数据库时钟下可领取时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.lease_token IS '领取随机令牌';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.lease_until IS '领取截止时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.notify_message_id IS '站内信服务返回的消息编号，不代表用户已读';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.last_error IS '脱敏失败分类，不保存远端错误或载荷';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.occurred_at IS '原告警持久化时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.handled_at IS '确认投递或人工接管时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.creator IS '创建者';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.updater IS '更新者';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert.deleted IS '逻辑删除标志；待投递与死信不得清理';
CREATE INDEX IF NOT EXISTS idx_master_distribute_alert_due ON "datahub-center".dh_governance_master_distribute_alert (available_at, id) WHERE deleted=0 AND status IN (0,1);
CREATE INDEX IF NOT EXISTS idx_master_distribute_alert_dead ON "datahub-center".dh_governance_master_distribute_alert (tenant_id, id) WHERE deleted=0 AND status=3;
CREATE INDEX IF NOT EXISTS idx_master_distribute_alert_delivered ON "datahub-center".dh_governance_master_distribute_alert (handled_at, tenant_id, id) WHERE status=2;
CREATE INDEX IF NOT EXISTS idx_master_distribute_alert_missing ON "datahub-center".dh_governance_master_distribute_log (id, tenant_id) WHERE deleted=0 AND (run_status=5 OR (run_status=4 AND run_protocol=1 AND attempts>=5));
COMMENT ON INDEX "datahub-center".idx_master_distribute_alert_missing IS '历史未知告警补账的有界候选扫描索引';
CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_master_distribute_alert_disposition (
    tenant_id bigint NOT NULL,
    command_id varchar(100) NOT NULL,
    alert_id bigint NOT NULL,
    action varchar(16) NOT NULL CHECK (action IN ('RETRY','ACKNOWLEDGE')),
    reason varchar(500) NOT NULL,
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id, command_id)
);
-- 表说明（原文）：主数据派发告警死信人工操作审计；操作来源为受控XXL-Job执行编号，非用户身份自证
COMMENT ON TABLE "datahub-center".dh_governance_master_distribute_alert_disposition IS '主数据管理-派发告警处置审计';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert_disposition.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert_disposition.command_id IS '受控调度执行编号，同编号不同请求拒绝';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert_disposition.alert_id IS '告警编号';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert_disposition.action IS 'RETRY重新投递或ACKNOWLEDGE人工接管，不改变原执行状态';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert_disposition.reason IS '核查原因或受控工单编号，禁止记录凭据';
COMMENT ON COLUMN "datahub-center".dh_governance_master_distribute_alert_disposition.create_time IS '数据库时钟操作时间';
CREATE INDEX IF NOT EXISTS idx_master_distribute_alert_disposition_owner ON "datahub-center".dh_governance_master_distribute_alert_disposition (tenant_id, alert_id);
COMMENT ON INDEX "datahub-center".idx_master_distribute_alert_disposition_owner IS '历史通知清理前按租户与告警检查人工审计';

