COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."use_case" IS '使用场景';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."example" IS '示例';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."status" IS '状态：0-启用 1-停用';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."builtin" IS '是否内置：1-是（不可删）0-否';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."description" IS '说明';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."deleted" IS '是否删除：0-否 1-是';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."standard_element_id" IS '来源标准数据元编号；空表示手工或内置规则';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."element_version" IS '生成该规则时的标准数据元版本号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_rule"."constraint_hash" IS '冻结约束 SHA-256；与 standard_element_id 一起构成幂等键';
-- 表说明（原文）：数据治理-数据质量-质量规则库
COMMENT ON TABLE "datahub-center"."dh_governance_quality_rule" IS '数据质量-质量规则库';

CREATE UNIQUE INDEX "uk_dh_governance_quality_rule_std_constraint"
  ON "datahub-center"."dh_governance_quality_rule" ("tenant_id", "standard_element_id", "constraint_hash")
  WHERE "deleted" = 0 AND "standard_element_id" IS NOT NULL;
CREATE INDEX "idx_dh_governance_quality_rule_std_element"
  ON "datahub-center"."dh_governance_quality_rule" ("tenant_id", "standard_element_id")
  WHERE "deleted" = 0 AND "standard_element_id" IS NOT NULL;

