INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (1, NULL, '手机号格式校验', 'BUILTIN_MOBILE', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^1[3-9]\\d{9}$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为 11 位大陆手机号', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (2, NULL, '二代身份证号校验', 'BUILTIN_ID_CARD', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^[1-9]\\d{5}(19|20)\\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\\d|3[01])\\d{3}[\\dXx]$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为 18 位二代身份证号', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (3, NULL, '电子邮箱格式校验', 'BUILTIN_EMAIL', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为合法电子邮箱', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (4, NULL, 'IPV4地址校验', 'BUILTIN_IPV4', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^((25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)\\.){3}(25[0-5]|2[0-4]\\d|1\\d\\d|[1-9]?\\d)$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为合法 IPV4 地址', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (5, NULL, 'IPV6地址校验', 'BUILTIN_IPV6', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为合法 IPV6 地址（完整格式）', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (6, NULL, '统一社会信用代码校验', 'BUILTIN_USCC', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^[0-9A-HJ-NPQRTUWXY]{2}\\d{6}[0-9A-HJ-NPQRTUWXY]{10}$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为 18 位统一社会信用代码', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (7, NULL, '邮政编码校验', 'BUILTIN_POSTCODE', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^[1-9]\\d{5}$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为 6 位邮政编码', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (8, NULL, '固定电话校验', 'BUILTIN_TEL', 'NORMALIZATION', 'FIELD', 'REGEX', 'REGEX_VALIDATION', '{"regex": "^(0\\d{2,3}-?)?\\d{7,8}$", "column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值是否为固定电话（可含区号）', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (9, NULL, '字段非空校验', 'BUILTIN_NOT_NULL', 'COMPLETENESS', 'FIELD', 'NOT_NULL', 'NOT_NULL_VALIDATION', '{"column": "", "allowBlank": false}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值不得为 NULL 或空字符串', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (10, NULL, '单字段唯一校验', 'BUILTIN_UNIQUE', 'UNIQUENESS', 'FIELD', 'UNIQUE', 'UNIQUE_VALIDATION', '{"column": ""}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段值在表内唯一', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (11, NULL, '多字段组合唯一校验', 'BUILTIN_COMPOSITE_UNIQUE', 'UNIQUENESS', 'FIELD', 'COMPOSITE_UNIQUE', 'COMPOSITE_UNIQUENESS_VALIDATION', '{"columns": []}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验多个字段的组合值在表内唯一', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);
INSERT INTO "datahub-center"."dh_governance_quality_rule" VALUES (12, NULL, '字段长度范围校验', 'BUILTIN_LENGTH', 'NORMALIZATION', 'FIELD', 'LENGTH', 'LENGTH_VALIDATION', '{"column": "", "maxLength": 64, "minLength": 0}', NULL, 'MID', NULL, 1, NULL, NULL, 0, 1, '校验字段字符长度在指定范围内（如 11 位手机号）', NULL, '1', '2026-09-07 23:21:26.987624', '1', '2026-09-07 23:21:26.987624', 0, 0, NULL, NULL, NULL);

