CREATE SEQUENCE IF NOT EXISTS "datahub-center"."dh_governance_quality_work_order_action_seq";
CREATE TABLE IF NOT EXISTS "datahub-center"."dh_governance_quality_work_order_action" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_governance_quality_work_order_action_seq'::regclass),
  "work_order_id" int8 NOT NULL,
  "request_id" varchar(64) NOT NULL,
  "action_type" varchar(32) NOT NULL,
  "from_status" varchar(32),
  "to_status" varchar(32),
  "from_owner_user_id" int8,
  "to_owner_user_id" int8,
  "from_dept_id" int8,
  "to_dept_id" int8,
  "reason" varchar(1024),
  "payload_hash" varchar(64) NOT NULL,
  "actor_user_id" int8 NOT NULL,
  "actor_dept_id" int8,
  "submission_id" int8,
  "creator" varchar(64) DEFAULT '',
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) DEFAULT '',
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0,
  "follow_up_work_order_id" int8,
  "expiry_result_version" int2,
  "expiry_issue_hash" varchar(64),
  "expiry_issue_count" int8,
  "expiry_receiver_user_id" int8,
  CONSTRAINT "ck_quality_expiry_result" CHECK (
    ("follow_up_work_order_id" IS NULL AND "expiry_result_version" IS NULL
      AND "expiry_issue_hash" IS NULL AND "expiry_issue_count" IS NULL AND "expiry_receiver_user_id" IS NULL)
    OR ("expiry_result_version" IS NOT NULL AND "expiry_result_version" = 1
      AND "action_type" = 'EXCEPTION_EXPIRED'
      AND "follow_up_work_order_id" IS NOT NULL AND "follow_up_work_order_id" > 0
      AND "follow_up_work_order_id" <> "work_order_id"
      AND "expiry_issue_hash" IS NOT NULL AND "expiry_issue_hash" ~ '^[0-9a-f]{64}$'
      AND "expiry_issue_count" IS NOT NULL AND "expiry_issue_count" >= 0)
  )
);
-- 表说明（原文）：质量工单只追加操作历史；同一 request_id 只生效一次
COMMENT ON TABLE "datahub-center"."dh_governance_quality_work_order_action" IS '数据质量-工单操作记录';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."work_order_id" IS '所属质量工单编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."request_id" IS '请求幂等编号，同一工单内只生效一次';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."action_type" IS '操作类型：ASSIGN指派、CLAIM认领、TRANSFER转派、SUBMIT提交、RECHECK复检、CONFIRM确认、WITHDRAW撤回、EXTEND延期、REOPEN重开、COORDINATE协调、EXCEPTION_EXPIRED例外到期';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."from_status" IS '操作前办理阶段';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."to_status" IS '操作后办理阶段';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."from_owner_user_id" IS '操作前办理人用户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."to_owner_user_id" IS '操作后办理人用户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."from_dept_id" IS '操作前办理部门编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."to_dept_id" IS '操作后办理部门编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."reason" IS '操作原因';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."payload_hash" IS '操作内容摘要';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."actor_user_id" IS '操作人用户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."actor_dept_id" IS '操作人部门编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."submission_id" IS '关联提交编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."follow_up_work_order_id" IS '到期事务创建的后续工单编号；旧空值不可按同根候选推断';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."expiry_result_version" IS '到期结果摘要版本；一表示问题编号多重集合摘要及原接收人';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."expiry_issue_hash" IS '创建时有效问题编号按数值排序保留重复，以expiry-issues-v1:加逗号连接编号的UTF8文本计算SHA256';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."expiry_issue_count" IS '创建时有效问题关联数量，保留重复；不沿用原工单缓存计数';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."expiry_receiver_user_id" IS '创建时通知接收人；空值表示当时无接收人，不使用当前办理人替换';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."deleted" IS '逻辑删除：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_action"."tenant_id" IS '租户编号';
CREATE UNIQUE INDEX IF NOT EXISTS "uk_quality_expiry_result_target"
  ON "datahub-center"."dh_governance_quality_work_order_action" ("tenant_id", "follow_up_work_order_id")
  WHERE "follow_up_work_order_id" IS NOT NULL;
COMMENT ON CONSTRAINT "ck_quality_expiry_result" ON "datahub-center"."dh_governance_quality_work_order_action" IS '允许旧历史全空或完整版本一结果，禁止部分绑定；不证明通知已送达';
COMMENT ON INDEX "datahub-center"."uk_quality_expiry_result_target" IS '每租户的后续工单只能属于一个到期结果，包含已逻辑删除的历史';
CREATE SEQUENCE IF NOT EXISTS "datahub-center"."dh_governance_quality_work_order_notify_seq";
CREATE TABLE IF NOT EXISTS "datahub-center"."dh_governance_quality_work_order_notify" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_governance_quality_work_order_notify_seq'::regclass),
  "work_order_id" int8 NOT NULL,
  "event_type" varchar(32) NOT NULL,
  "receiver_user_id" int8 NOT NULL,
  "time_slice" varchar(32) NOT NULL,
  "payload_summary" varchar(512),
  "send_status" varchar(32) NOT NULL DEFAULT 'PENDING',
  "retry_count" int4 NOT NULL DEFAULT 0,
  "next_retry_time" timestamp(6),
  "last_error" varchar(512),
  "creator" varchar(64) DEFAULT '',
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) DEFAULT '',
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0,
  "claim_token" varchar(64),
  "lease_until" timestamp(6)
);
-- 表说明（原文）：工单提醒投递记录，失败可重试，不能作为待办唯一存储
COMMENT ON TABLE "datahub-center"."dh_governance_quality_work_order_notify" IS '数据质量-工单通知记录';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."work_order_id" IS '所属质量工单编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."event_type" IS '提醒事件类型：ASSIGN指派、TRANSFER转派、RETURN退回、COORDINATE协调、RECHECK_FAIL复检未通过、OVERDUE超期、DEADLINE临期、EXCEPTION_EXPIRED例外到期';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."receiver_user_id" IS '接收人用户编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."time_slice" IS '去重时间片';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."payload_summary" IS '提醒内容摘要';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."send_status" IS '投递状态：PENDING待发送、SENDING已认领、SENT已确认、FAILED明确未发送、UNKNOWN结果不明；FAILED/UNKNOWN 按幂等键自动重试，共 8 次后转 EXHAUSTED 待人工核验';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."retry_count" IS '自动投递已失败次数（FAILED 与 UNKNOWN 共用），达到 8 次转 EXHAUSTED；人工授权重试时清零';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."next_retry_time" IS '下次允许重试时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."claim_token" IS '通知投递认领令牌；完成状态更新仅允许当前令牌持有者写入';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."lease_until" IS '上海本地时间戳通知认领租约截止时间；租约到期收敛为 UNKNOWN，退避后按同一幂等键重试';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."last_error" IS '最近一次投递失败原因';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."deleted" IS '逻辑删除：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_governance_quality_work_order_notify"."tenant_id" IS '租户编号';
CREATE INDEX IF NOT EXISTS idx_quality_work_order_notify_dispatch
  ON "datahub-center"."dh_governance_quality_work_order_notify" ("next_retry_time", "id")
  WHERE "deleted" = 0 AND "send_status" IN ('PENDING', 'FAILED', 'UNKNOWN');
CREATE INDEX IF NOT EXISTS idx_quality_work_order_notify_expired_claim
  ON "datahub-center"."dh_governance_quality_work_order_notify" ("tenant_id", "lease_until", "id")
  WHERE "deleted" = 0 AND "send_status" = 'SENDING';

-- ----------------------------
-- 表结构： dh_governance_quality_expiry_failure（例外到期处理失败账本，0267）
-- ----------------------------
CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_governance_quality_expiry_failure_seq;

CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_quality_expiry_failure (
    id int8 NOT NULL DEFAULT nextval('"datahub-center".dh_governance_quality_expiry_failure_seq'::regclass),
    submission_id int8 NOT NULL,
    work_order_id int8 NOT NULL,
    status varchar(16) NOT NULL,
    attempt_count int4 NOT NULL DEFAULT 0,
    last_error varchar(512),
    first_failed_at timestamp(6),
    last_failed_at timestamp(6),
    next_attempt_at timestamp(6),
    resolution_action varchar(32),
    resolution_reason varchar(500),
    resolved_by int8,
    resolved_at timestamp(6),
    version int4 NOT NULL DEFAULT 0,
    creator varchar(64) DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted int2 NOT NULL DEFAULT 0,
    CONSTRAINT pk_dh_governance_quality_expiry_failure PRIMARY KEY (id),
    CONSTRAINT ck_quality_expiry_failure_status CHECK (status IN ('RETRYING', 'EXHAUSTED', 'RESOLVED')),
    CONSTRAINT ck_quality_expiry_failure_attempts CHECK (attempt_count >= 0)
);

CREATE UNIQUE INDEX IF NOT EXISTS uk_quality_expiry_failure_submission
    ON "datahub-center".dh_governance_quality_expiry_failure (submission_id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_quality_expiry_failure_status
    ON "datahub-center".dh_governance_quality_expiry_failure (status, last_failed_at) WHERE deleted = 0;

COMMENT ON TABLE "datahub-center".dh_governance_quality_expiry_failure IS '数据质量-例外到期处理失败账本';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.id IS '账本编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.submission_id IS '例外提交编号（每个提交一条有效账本）';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.work_order_id IS '原工单编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.status IS '状态：RETRYING退避重试中、EXHAUSTED次数耗尽待人工、RESOLVED已关闭';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.attempt_count IS '自动处理已失败次数，达到 5 次转 EXHAUSTED，人工授权重试时清零';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.last_error IS '最近一次失败的安全摘要，不含驱动或厂商原文';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.first_failed_at IS '本轮首次失败时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.last_failed_at IS '最近一次失败时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.next_attempt_at IS '下次允许自动处理时间：5 分钟 × 2^(次数-1)，封顶 6 小时';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.resolution_action IS '处置动作：SUCCEEDED自动成功、RETRY_AUTHORIZED人工授权重试';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.resolution_reason IS '人工授权理由';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.resolved_by IS '最近一次人工处置操作人';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.resolved_at IS '最近一次关闭或人工处置时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.version IS 'CAS 版本，防止旧页面覆盖新状态';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.creator IS '创建者';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.updater IS '更新者';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_expiry_failure.deleted IS '逻辑删除：0未删除、1已删除';


