-- 例外到期公平扫描新增结构；不清零已有租户游标
CREATE SEQUENCE IF NOT EXISTS "datahub-center"."dh_governance_quality_exception_expiry_cursor_seq";
CREATE TABLE IF NOT EXISTS "datahub-center"."dh_governance_quality_exception_expiry_cursor" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_governance_quality_exception_expiry_cursor_seq'::regclass),
  "after_submission_id" int8 NOT NULL DEFAULT 0,
  "through_submission_id" int8 NOT NULL DEFAULT 0,
  "creator" varchar(64) DEFAULT '',
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) DEFAULT '',
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL,
  CONSTRAINT "pk_quality_expiry_cursor" PRIMARY KEY ("id"),
  CONSTRAINT "uk_quality_expiry_cursor_tenant" UNIQUE ("tenant_id"),
  CONSTRAINT "ck_quality_expiry_cursor_range" CHECK ("after_submission_id" >= 0 AND "through_submission_id" >= "after_submission_id"),
  CONSTRAINT "ck_quality_expiry_cursor_live" CHECK ("deleted" = 0)
);
