COMMENT ON COLUMN "datahub-center"."dh_governance_safety_field_permission"."table_name" IS '表名';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_field_permission"."field_name" IS '字段名';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_field_permission"."role_id" IS '角色编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_field_permission"."security_level_id" IS '数据分级编号（关联 dh_governance_safety_level.id）';
