DROP TABLE IF EXISTS "datahub-center"."dh_governance_safety_identify_rule";
CREATE TABLE "datahub-center"."dh_governance_safety_identify_rule" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_safety_identify_rule_seq'::regclass),
  "rule_name" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "match_type" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "pattern" varchar(512) COLLATE "pg_catalog"."default" NOT NULL,
  "category_id" int8 NOT NULL,
  "level_id" int8,
  "min_hit_ratio" numeric(5,2) NOT NULL DEFAULT 80,
  "sample_rows" int4 NOT NULL DEFAULT 50,
  "builtin_flag" int2 NOT NULL DEFAULT 0,
  "status" int2 NOT NULL DEFAULT 0,
  "sort" int4 NOT NULL DEFAULT 0,
  "description" varchar(1024) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."id" IS '规则编号';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."rule_name" IS '规则名称';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."match_type" IS '匹配方式：COLUMN_NAME-字段名正则、COLUMN_COMMENT-注释关键词（逗号分隔）、DATA_REGEX-数据内容正则（采样）';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."pattern" IS '匹配模式：正则表达式或关键词列表';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."category_id" IS '命中后归属的数据分类（关联 dh_governance_safety_category.id）';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."level_id" IS '命中后建议的数据分级（为空取分类上配置的分级）';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."min_hit_ratio" IS 'DATA_REGEX 方式的采样命中率阈值（百分比，达到才判定命中）';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."sample_rows" IS 'DATA_REGEX 方式的采样行数（上限 100）';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."builtin_flag" IS '是否内置规则：0-自定义 1-内置';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_identify_rule"."status" IS '状态：0-启用 1-停用';
-- 表说明（原文）：数据治理-数据安全--敏感数据识别规则
COMMENT ON TABLE "datahub-center"."dh_governance_safety_identify_rule" IS '数据安全-敏感数据识别规则';

