-- ----------------------------
-- 数据记录： dh_governance_safety_level
-- ----------------------------
INSERT INTO "datahub-center"."dh_governance_safety_level" VALUES (1, 'L1', '#52c41a', '1级（对外公开）', 0, 1, '可以对外公开的数据，如水雨情简报、已公开的监测站点水质年报、宣传类信息等，不涉及安全和隐私。可直接展示或仅弱化部分敏感字段（如展示省、市，不展示精确坐标）', '1', '2026-07-16 00:19:29.274192', '1', '2026-07-16 00:22:31.564521', 0, 1);
INSERT INTO "datahub-center"."dh_governance_safety_level" VALUES (2, 'L2', '#1677ff', '2级（内部公开）', 0, 2, '一般内部使用数据，如运维日志、调度流程记录、一般统计数据等，泄露影响较小但仍需内部保护。', '1', '2026-07-16 00:23:12.759693', '1', '2026-07-16 00:23:12.759693', 0, 1);
INSERT INTO "datahub-center"."dh_governance_safety_level" VALUES (3, 'L3', '#faad14', '3级（机密数据）', 0, 3, '涉及日常监测数据（如流量、水位、雨量等明细）、取水户用水记录、内部分析报表等，一旦泄露会对业务管理和内部运行造成不利影响。', '1', '2026-07-16 00:23:59.123074', '1', '2026-07-16 00:23:59.123074', 0, 1);
INSERT INTO "datahub-center"."dh_governance_safety_level" VALUES (4, 'L4', '#f5222d', '4级（绝密数据）', 0, 4, '包含国家涉密信息、重大水利工程调度方案、涉安全生产的核心数据，一旦泄露将严重危害国家安全和重大工程运行安全。', '1', '2026-07-16 00:24:51.372102', '1', '2026-07-16 00:24:51.372102', 0, 1);

