COMMENT ON COLUMN "datahub-center"."dh_governance_safety_rule_ver"."update_time" IS '最后更新时间';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_rule_ver"."deleted" IS '逻辑删除标识：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_rule_ver"."tenant_id" IS '租户编号';
