-- 表说明（原文）：数据治理-数据安全--数据表访问权限
COMMENT ON TABLE "datahub-center"."dh_governance_safety_table_permission" IS '数据安全-数据表访问权限';
-- 已同步 0074：历史 NULL 模式不是通配符，必须核验后才能更新绑定。
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_table_permission"."schema_name" IS '核验后的精确物理模式；NULL为历史未绑定，不是通配符';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_table_permission"."binding_note" IS '精确配置或历史绑定核验原因';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_table_permission"."binding_actor_id" IS '绑定核验操作人';
COMMENT ON COLUMN "datahub-center"."dh_governance_safety_table_permission"."binding_time" IS '绑定核验时间';
ALTER TABLE "datahub-center"."dh_governance_safety_table_permission" ADD CONSTRAINT ck_safety_table_binding
  CHECK (schema_name IS NULL OR (length(btrim(schema_name))>0 AND binding_actor_id>0
    AND binding_actor_id IS NOT NULL AND binding_time IS NOT NULL
    AND binding_note IS NOT NULL AND length(btrim(binding_note))>0));
CREATE UNIQUE INDEX uk_safety_table_exact_role ON "datahub-center"."dh_governance_safety_table_permission"
  (tenant_id,database_id,schema_name,table_name,role_id)
  WHERE deleted=0 AND schema_name IS NOT NULL;
CREATE INDEX idx_safety_table_unbound ON "datahub-center"."dh_governance_safety_table_permission"
  (tenant_id,database_id) WHERE deleted=0 AND status=0 AND schema_name IS NULL;

