COMMENT ON TABLE "datahub-center"."dh_market_audit_event" IS '数据集市-领域审计事件';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."event_id" IS '事件编号，租户内唯一';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."event_type" IS '事件类型';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."actor_user_id" IS '操作人用户编号';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."dept_id" IS '操作人部门编号';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."object_type" IS '对象类型';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."object_id" IS '对象编号';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."from_status" IS '变更前状态';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."to_status" IS '变更后状态';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."reason" IS '原因说明';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."result" IS '处理结果';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."occurred_at" IS '事件发生时间';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."correlation_id" IS '业务关联号';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."deleted" IS '逻辑删除：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_market_audit_event"."tenant_id" IS '租户编号';

-- 0066：交付核查结论审计，与编号迁移保持一致；不推断或回填历史权限。
ALTER TABLE "datahub-center".dh_market_audit_event
    ADD COLUMN IF NOT EXISTS review_operation_id varchar(128),
    ADD COLUMN IF NOT EXISTS review_request_hash varchar(64),
    ADD COLUMN IF NOT EXISTS review_evidence jsonb;
COMMENT ON COLUMN "datahub-center".dh_market_audit_event.review_operation_id IS '核查对应的原始交付操作号，不按当前申请重建';
COMMENT ON COLUMN "datahub-center".dh_market_audit_event.review_request_hash IS '核查请求摘要，绑定租户、操作者、操作、结论、原因与依据';
COMMENT ON COLUMN "datahub-center".dh_market_audit_event.review_evidence IS '服务端生成的有界证据摘要，不保存字段值或完整冻结载荷，不作为授权令牌';
ALTER TABLE "datahub-center".dh_market_audit_event ADD CONSTRAINT ck_market_delivery_review_evidence CHECK (
    event_type <> 'DELIVERY_REVIEW_DECISION' OR (
        review_operation_id IS NOT NULL AND btrim(review_operation_id) <> ''
        AND review_request_hash IS NOT NULL AND review_request_hash ~ '^[0-9a-f]{64}$'
        AND review_evidence IS NOT NULL AND jsonb_typeof(review_evidence)='object'
        AND octet_length(review_evidence::text)<=8192
        AND (review_evidence->>'schemaVersion'='1') IS TRUE
        AND (review_evidence->>'evidenceHash' ~ '^[0-9a-f]{64}$') IS TRUE
        AND actor_user_id IS NOT NULL AND actor_user_id>0
        AND object_type='DELIVERY' AND object_id IS NOT NULL
        AND result IS NOT NULL AND result IN ('KEEP_PENDING','REAPPLY_REQUIRED')
        AND from_status IS NOT NULL AND to_status IS NOT NULL AND to_status=from_status
        AND reason IS NOT NULL AND btrim(reason) <> ''
        AND (length(btrim(review_evidence->>'basis')) BETWEEN 1 AND 500) IS TRUE
    ));
CREATE UNIQUE INDEX uk_market_delivery_review_request
    ON "datahub-center".dh_market_audit_event(tenant_id,event_id) WHERE event_type='DELIVERY_REVIEW_DECISION';
CREATE INDEX idx_market_delivery_review_history
    ON "datahub-center".dh_market_audit_event(tenant_id,review_operation_id,id)
    WHERE event_type='DELIVERY_REVIEW_DECISION' AND deleted=0;
-- 0066 核查审计结构结束。

-- 0067：新批准的来源语义凭证；不补造历史批准。
ALTER TABLE dh_market_audit_event
    ADD COLUMN IF NOT EXISTS approval_ref varchar(64),
    ADD COLUMN IF NOT EXISTS approval_asset_id bigint,
    ADD COLUMN IF NOT EXISTS approval_scope_hash varchar(64);
COMMENT ON COLUMN dh_market_audit_event.approval_ref IS '正式批准的申请及版本引用，不以恢复或核查待办补造';
COMMENT ON COLUMN dh_market_audit_event.approval_asset_id IS '正式批准时的原资产身份';
COMMENT ON COLUMN dh_market_audit_event.approval_scope_hash IS '批准语义摘要，绑定主体、字段、期限、用途、物理绑定和合同版本';
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_market_audit_event'::regclass
                   AND conname='ck_market_grant_approval_evidence') THEN
        ALTER TABLE dh_market_audit_event ADD CONSTRAINT ck_market_grant_approval_evidence CHECK (
            event_type <> 'GRANT_APPROVAL_EVIDENCE' OR (
                (object_type='APPLY') IS TRUE AND object_id IS NOT NULL AND object_id>0
                AND actor_user_id IS NOT NULL AND actor_user_id>0
                AND approval_asset_id IS NOT NULL AND approval_asset_id>0
                AND approval_ref IS NOT NULL AND btrim(approval_ref)<>''
                AND approval_scope_hash IS NOT NULL AND approval_scope_hash ~ '^[0-9a-f]{64}$'
                AND (from_status='1' AND to_status='2' AND result='APPROVED') IS TRUE
                AND (deleted=0) IS TRUE
            ));
    END IF;
END $$;
-- 一份申请只产生一份正式批准；重新申请或续期必须使用新的申请身份。
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_grant_approval_apply
    ON dh_market_audit_event(tenant_id,object_id) WHERE event_type='GRANT_APPROVAL_EVIDENCE';
-- 原批准不可覆盖/软删除/物理删除；其他事件仍使用原生命周期。
CREATE OR REPLACE FUNCTION market_protect_grant_approval() RETURNS trigger
LANGUAGE plpgsql SET search_path TO "datahub-center" AS $$
BEGIN
    IF TG_OP='TRUNCATE' THEN
        IF EXISTS (SELECT 1 FROM dh_market_audit_event WHERE event_type='GRANT_APPROVAL_EVIDENCE') THEN
            RAISE EXCEPTION '存在正式批准凭证，禁止清空市场审计表' USING ERRCODE='23514';
        END IF;
        RETURN NULL;
    END IF;
    IF OLD.event_type='GRANT_APPROVAL_EVIDENCE' THEN
        RAISE EXCEPTION '正式批准凭证只可追加，不可修改或删除' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW.event_type='GRANT_APPROVAL_EVIDENCE' THEN
            RAISE EXCEPTION '不能将其他事件修改成正式批准凭证' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    RETURN OLD;
END $$;
COMMENT ON FUNCTION market_protect_grant_approval() IS '保护原正式批准证据，应用升级回退不删除批准审计';
CREATE OR REPLACE TRIGGER trg_market_protect_grant_approval
    BEFORE UPDATE OR DELETE ON dh_market_audit_event
    FOR EACH ROW EXECUTE FUNCTION market_protect_grant_approval();
CREATE OR REPLACE TRIGGER trg_market_protect_grant_approval_truncate
    BEFORE TRUNCATE ON dh_market_audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION market_protect_grant_approval();
-- 0067 批准凭证结构结束。
-- 0069：交付历史处置（收回或有条件确认原批准）审计，与编号迁移保持一致；不回填历史。
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='datahub-center'
                   AND table_name='dh_market_audit_event' AND column_name='review_evidence')
       OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='datahub-center'
                   AND table_name='dh_market_audit_event' AND column_name='approval_scope_hash') THEN
        RAISE EXCEPTION '缺少0066/0067核查及批准凭证前置，禁止从不完整基线升级';
    END IF;
END $$;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_market_audit_event'::regclass
                   AND conname='ck_market_delivery_disposal') THEN
        -- 处置审计：原操作号、请求摘要、服务端证据摘要、操作者与原因均必填；结果仅限两种实际处置。
        ALTER TABLE dh_market_audit_event ADD CONSTRAINT ck_market_delivery_disposal CHECK (
            event_type <> 'DELIVERY_DISPOSAL' OR (
                review_operation_id IS NOT NULL AND btrim(review_operation_id) <> ''
                AND review_request_hash IS NOT NULL AND review_request_hash ~ '^[0-9a-f]{64}$'
                AND review_evidence IS NOT NULL AND jsonb_typeof(review_evidence)='object'
                AND octet_length(review_evidence::text)<=8192
                AND (review_evidence->>'schemaVersion'='1') IS TRUE
                AND (review_evidence->>'evidenceHash' ~ '^[0-9a-f]{64}$') IS TRUE
                AND actor_user_id IS NOT NULL AND actor_user_id>0
                AND (object_type='DELIVERY') IS TRUE AND object_id IS NOT NULL
                AND (result IN ('REVOKE','CONFIRM_ORIGINAL')) IS TRUE
                AND from_status IS NOT NULL AND to_status IS NOT NULL
                AND reason IS NOT NULL AND btrim(reason) <> ''
                AND (length(btrim(review_evidence->>'basis')) BETWEEN 1 AND 500) IS TRUE
                AND (deleted=0) IS TRUE
            ));
    END IF;
END $$;
-- 包括历史记录在内永久占用处置请求编号，不能复用相同幂等身份再次处置。
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_delivery_disposal_request
    ON dh_market_audit_event(tenant_id,event_id) WHERE event_type='DELIVERY_DISPOSAL';
-- 核查历史按原操作同时列出待办结论与实际处置。
CREATE INDEX IF NOT EXISTS idx_market_delivery_review_disposal_history
    ON dh_market_audit_event(tenant_id,review_operation_id,id)
    WHERE event_type IN ('DELIVERY_REVIEW_DECISION','DELIVERY_DISPOSAL') AND deleted=0;
-- 处置审计只可追加：不可修改、软删除、物理删除，也不能把其他事件改写为处置。
CREATE OR REPLACE FUNCTION market_protect_delivery_disposal() RETURNS trigger
LANGUAGE plpgsql SET search_path TO "datahub-center" AS $$
BEGIN
    IF TG_OP='TRUNCATE' THEN
        IF EXISTS (SELECT 1 FROM dh_market_audit_event WHERE event_type='DELIVERY_DISPOSAL') THEN
            RAISE EXCEPTION '存在交付处置审计，禁止清空市场审计表' USING ERRCODE='23514';
        END IF;
        RETURN NULL;
    END IF;
    IF OLD.event_type='DELIVERY_DISPOSAL' THEN
        RAISE EXCEPTION '交付处置审计只可追加，不可修改或删除' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW.event_type='DELIVERY_DISPOSAL' THEN
            RAISE EXCEPTION '不能将其他事件修改成交付处置审计' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    RETURN OLD;
END $$;
COMMENT ON FUNCTION market_protect_delivery_disposal() IS '保护交付历史处置审计，应用升级回退不删除处置记录';
CREATE OR REPLACE TRIGGER trg_market_protect_delivery_disposal
    BEFORE UPDATE OR DELETE ON dh_market_audit_event
    FOR EACH ROW EXECUTE FUNCTION market_protect_delivery_disposal();
CREATE OR REPLACE TRIGGER trg_market_protect_delivery_disposal_truncate
    BEFORE TRUNCATE ON dh_market_audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION market_protect_delivery_disposal();
-- 0069 交付处置审计结构结束。

-- 0072 交付受控重投意图审计唯一索引开始。
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='datahub-center'
                   AND table_name='dh_market_audit_event' AND column_name='review_operation_id')
       OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='datahub-center'
                   AND table_name='dh_market_audit_event' AND column_name='review_request_hash') THEN
        RAISE EXCEPTION '缺少0066核查及请求摘要前置，禁止从不完整基线升级';
    END IF;
END $$;
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_delivery_redeliver_request
    ON dh_market_audit_event(tenant_id,event_id) WHERE event_type='DELIVERY_REDELIVERY';
CREATE OR REPLACE FUNCTION market_protect_delivery_redeliver() RETURNS trigger
LANGUAGE plpgsql SET search_path TO "datahub-center" AS $$
BEGIN
    IF TG_OP='TRUNCATE' THEN
        IF EXISTS (SELECT 1 FROM dh_market_audit_event WHERE event_type='DELIVERY_REDELIVERY') THEN
            RAISE EXCEPTION '存在交付重投审计，禁止清空市场审计表' USING ERRCODE='23514';
        END IF;
        RETURN NULL;
    END IF;
    IF OLD.event_type='DELIVERY_REDELIVERY' THEN
        RAISE EXCEPTION '交付重投审计只可追加，不可修改或删除' USING ERRCODE='23514';
    END IF;
    IF TG_OP='UPDATE' THEN
        IF NEW.event_type='DELIVERY_REDELIVERY' THEN
            RAISE EXCEPTION '不能将其他事件修改成交付重投审计' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    RETURN OLD;
END $$;
COMMENT ON FUNCTION market_protect_delivery_redeliver() IS '保护交付受控重投意图审计，应用升级回退不删除重投记录';
CREATE OR REPLACE TRIGGER trg_market_protect_delivery_redeliver
    BEFORE UPDATE OR DELETE ON dh_market_audit_event
    FOR EACH ROW EXECUTE FUNCTION market_protect_delivery_redeliver();
CREATE OR REPLACE TRIGGER trg_market_protect_delivery_redeliver_truncate
    BEFORE TRUNCATE ON dh_market_audit_event
    FOR EACH STATEMENT EXECUTE FUNCTION market_protect_delivery_redeliver();
-- 0072 交付受控重投意图审计唯一索引结束。

