-- ----------------------------
-- 表结构： dh_modeling_biz_theme
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_biz_theme";
CREATE TABLE "datahub-center"."dh_modeling_biz_theme" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_biz_theme_seq'::regclass),
  "parent_id" int8 NOT NULL DEFAULT 0,
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "code" varchar(64) COLLATE "pg_catalog"."default",
  "sort" int4 NOT NULL DEFAULT 0,
  "description" varchar(500) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."parent_id" IS '父级编号，0 表示顶级目录';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."name" IS '目录名称';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."code" IS '目录编码';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."sort" IS '排序';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."update_time" IS '最后更新时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."deleted" IS '逻辑删除标识：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_theme"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."dh_modeling_biz_theme" IS '数据建模-模型目录';

