  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_business_process_seq'::regclass),
  "biz_category_id" int8 NOT NULL,
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "code" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "activity_definition" varchar(1024) COLLATE "pg_catalog"."default" NOT NULL,
  "start_condition" varchar(1024) COLLATE "pg_catalog"."default",
  "end_condition" varchar(1024) COLLATE "pg_catalog"."default",
  "canonical_grain_definition" varchar(512) COLLATE "pg_catalog"."default" NOT NULL,
  "leader_user_id" int8,
  "leader_phone" varchar(20) COLLATE "pg_catalog"."default",
  "status" int2 NOT NULL DEFAULT 0,
  "description" varchar(1024) COLLATE "pg_catalog"."default",
  "remark" varchar(512) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."biz_category_id" IS '所属业务分类编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."name" IS '业务流程名称';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."code" IS '业务流程编码';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."activity_definition" IS '活动定义';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."start_condition" IS '开始条件';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."end_condition" IS '结束条件';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."canonical_grain_definition" IS '标准粒度定义';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."leader_user_id" IS '负责人用户编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."leader_phone" IS '负责人电话';
COMMENT ON COLUMN "datahub-center"."dh_modeling_business_process"."status" IS '状态：0-启用 1-停用';
