-- ----------------------------
-- 数据记录： dh_modeling_business_process
-- ----------------------------
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (1, 2, '事项申报', 'ITEM_APPLY', '申请人通过政务服务网、一体机或大厅窗口提交政务服务事项申报材料，系统核验身份、事项编码和材料目录后生成办件。', '申请人已完成实名认证，所选事项在本市实施清单内且按办事指南备齐材料。', '系统生成办件编号，办件状态变更为待受理，并完成材料电子化归档。', '一次办件申报（一事项一申请人一办件编号）', 100, '', 0, '对应政务服务实施清单申报环节，为办件明细和证照签发提供最细粒度事实。来源：政务服务网、大厅综合受理系统。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:10:00', '1', '2026-09-03 09:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (2, 2, '办件受理', 'ITEM_ACCEPT', '窗口或系统对申报材料进行形式审查，确认主体资格、申请事项和材料完整性后作出受理或不予受理决定。', '办件已完成申报且处于待受理状态，受理时限未超法定或承诺时限。', '出具受理通知书或不予受理告知书，办件进入审查或退回补正。', '一次办件受理决定', 100, '', 0, '记录受理决定、受理人和受理时点，支撑审批时效和一次办成率分析。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:13:00', '1', '2026-09-03 09:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (3, 2, '材料补正', 'ITEM_SUPPLEMENT', '对材料不全或不符合法定形式的办件一次性告知补正，申请人按告知清单补正后重新提交。', '受理环节认定材料不齐或不符合法定形式，并已出具补正告知书。', '申请人在告知期限内完成补正提交，或逾期未补正导致办件作废。', '一次办件补正告知及回传', 100, '', 0, '用于分析补正率、一次性告知落实情况和材料精简成效。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:16:00', '1', '2026-09-03 09:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (4, 2, '实质审查', 'ITEM_REVIEW', '审批部门依据法律法规和审查细则开展实质审查，形成拟准予、拟不予或转专家评审意见。', '办件已受理且材料齐全，必要时已完成现场踏勘或部门会审。', '审查意见生效，办件进入决定或听证、现场核查等后续环节。', '一次办件审查意见', 100, '', 0, '沉淀审查结论、审查依据和耗时，支撑超时预警和部门履职分析。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:19:00', '1', '2026-09-03 09:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (5, 2, '许可决定', 'ITEM_DECIDE', '审批机关依法作出准予许可、不予许可或终止办理决定，并完成决定文书编号。', '审查完毕且无未了结的听证、公示或会审事项。', '决定书签发，办件状态变为准予、不予或终止，并同步信用和证照系统。', '一次行政许可决定', 100, '', 0, '作为许可结果权威事实，对接公共信用双公示和电子证照签发。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:22:00', '1', '2026-09-03 09:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (6, 2, '证照制发', 'ITEM_LICENSE', '对准予许可的办件生成电子证照或实体证照，完成证照赋码、签章和目录登记。', '许可决定为准予，且证照模板、持证主体和有效期要素齐全。', '证照签发成功并可核验，办件关联证照标识。', '一次证照签发', 100, '', 0, '对接电子证照库，支撑免证办和证照核验。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:25:00', '1', '2026-09-03 09:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (7, 2, '结果送达', 'ITEM_DELIVER', '通过短信、政务服务网、邮寄或窗口领取等方式将决定文书和证照送达申请人。', '许可决定已作出，送达地址或领取方式已确认。', '申请人签收或系统确认电子送达成功，办件办结。', '一次办件结果送达', 100, '', 0, '用于送达时效、电子送达占比和办结闭环统计。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:28:00', '1', '2026-09-03 09:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (8, 2, '办件评价', 'ITEM_EVALUATE', '办结后采集申请人好差评，差评转入整改和回访。', '办件已办结且评价窗口在有效期内。', '评价结果入库，差评形成整改工单或到期自动关闭。', '一次办件评价', 100, '', 0, '支撑政务服务好差评和营商环境测评。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:31:00', '1', '2026-09-03 09:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (9, 2, '窗口纸质收件', 'ITEM_PAPER_INTAKE', '大厅窗口收取纸质材料并手工登记台账，仅用于全流程网办覆盖前的过渡。', '申请人到窗口提交纸质材料且事项尚未纳入全流程网办。', '纸质材料扫描归档或转综合受理系统。', '一次窗口纸质收件', 100, '', 1, '历史过渡过程，已停用。现网办件以事项申报为准。', '责任单位：市行政审批局；所属业务分类编号：2；建模用途：DWD 明细事实过程。状态：停用（历史过渡过程，保留口径对照）。', '1', '2026-09-03 09:34:00', '1', '2026-09-03 09:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (10, 3, '公文收文', 'DOC_RECEIVE', '收文岗对来文进行登记、编号、拟办和分办，进入公文流转。', '来文要素齐全，收文机关为本市党政机关或授权单位。', '完成收文编号并分送承办处室。', '一份来文的一次收文登记', 100, '', 0, '来源：协同办公系统。支撑公文办理时效和部门履职分析。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:37:00', '1', '2026-09-03 09:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (11, 3, '公文发文', 'DOC_DISPATCH', '承办处室拟稿、核稿、会签后按发文权限签发并编号发出。', '发文依据明确，核稿和会签节点已完成。', '公文签发并完成电子公文发送或纸质用印发出。', '一份公文的一次发文', 100, '', 0, '记录发文文种、密级和发送范围，用于政务协同效率分析。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:40:00', '1', '2026-09-03 09:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (12, 3, '公文签批', 'DOC_APPROVE', '领导或授权人员对呈批件、发文稿和请示件进行签批。', '公文已完成拟办并送达签批人待办。', '签批意见生效，公文转入下一办理环节或办结。', '一次公文签批动作', 100, '', 0, '用于签批时长和待办积压监测，不存储批示原文。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:43:00', '1', '2026-09-03 09:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (13, 3, '会议召开', 'MEETING_HOLD', '登记市委市政府及部门会议的通知、出席、议题和纪要形成。', '会议已获批并完成通知发送。', '会议结束且纪要编号归档。', '一次正式会议', 100, '', 0, '支撑会议数量、议题落实和督办关联分析。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:46:00', '1', '2026-09-03 09:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (14, 3, '督查任务下达', 'SUPERVISE_ASSIGN', '对重点工作、领导批示和会议议定事项分解下达督查任务。', '任务来源已确认，责任单位和办结时限已明确。', '任务书送达责任单位并进入执行台账。', '一条督查任务下达', 100, '', 0, '对接部门履职和重点任务完成率分析。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:49:00', '1', '2026-09-03 09:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (15, 3, '督查反馈销号', 'SUPERVISE_CLOSE', '责任单位反馈进展，督查室审核后予以通过、退回或销号。', '督查任务已下达且到达反馈节点。', '审核通过并销号，或退回限期整改。', '一次督查任务反馈审核', 100, '', 0, '用于逾期、多次退回和销号率分析。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:52:00', '1', '2026-09-03 09:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (16, 3, '跨部门协同请求', 'COLLAB_REQUEST', '主办部门向协办部门发起数据核验、联合审查或意见会签请求。', '主办事项需要法定协办且协办部门在组织机构目录中。', '协办部门反馈意见或超时系统标记超期。', '一次跨部门协同请求', 100, '', 0, '支撑政务协同分析和并联审批耗时拆解。', '责任单位：市政府办公室、市大数据局；所属业务分类编号：3；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:55:00', '1', '2026-09-03 09:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (17, 4, '交易项目登记', 'TRADE_REGISTER', '招标人将工程、政府采购、土地或产权交易项目登记入库并赋项目编号。', '项目已完成立项或采购计划备案，交易主体资格合法。', '项目在公共资源交易平台生效，进入公告编制。', '一个交易项目的一次登记', 100, '', 0, '来源：公共资源交易平台。关联法人、财政和信用数据。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 09:58:00', '1', '2026-09-03 09:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (18, 4, '招标公告发布', 'TRADE_ANNOUNCE', '对依法必须招标或公开采购项目发布招标（采购）公告。', '招标文件审核通过，公告要素符合公开要求。', '公告在指定媒介发布并记录发布时间。', '一次招标或采购公告发布', 100, '', 0, '用于公开率、公告更正率和市场参与度分析。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:01:00', '1', '2026-09-03 10:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (19, 4, '投标报名', 'TRADE_BID_APPLY', '潜在投标人或供应商下载文件并完成报名、保证金缴纳。', '公告在报名期内，主体未被列入严重失信名单。', '报名成功并获得投标资格确认。', '一个项目下一次投标报名', 100, '', 0, '支撑竞争充分度和围标串标风险线索分析。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:04:00', '1', '2026-09-03 10:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (20, 4, '开评标', 'TRADE_EVALUATE', '按法定程序开标并组织评标委员会评审，形成评标报告。', '投标截止已到，开标条件满足且评标委员会组建完成。', '评标报告签字确认，推荐中标候选人。', '一个标段的一次开评标', 100, '', 0, '记录废标、否决投标和评标时长。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:07:00', '1', '2026-09-03 10:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (21, 4, '中标结果确定', 'TRADE_AWARD', '对中标候选人进行公示，处理异议后确定中标人并发出中标通知书。', '评标结束且公示期安排符合规定。', '中标通知书发出或依法重新招标。', '一次中标结果确定', 100, '', 0, '对接信用公示和财政资金支付。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:10:00', '1', '2026-09-03 10:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (22, 4, '交易合同签订', 'TRADE_CONTRACT', '招标人与中标人签订合同并在平台备案。', '中标通知书已发出，合同文本通过合法性审查。', '合同备案完成并生成合同编号。', '一份交易合同备案', 100, '', 0, '用于合同履约和资金支付关联。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:13:00', '1', '2026-09-03 10:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (23, 4, '交易资金结算', 'TRADE_SETTLE', '办理保证金退还、交易服务费和合同价款支付登记。', '合同已备案，支付条件按合同约定达成。', '资金收付凭证入账并与项目闭环。', '一笔交易资金收付', 100, '', 0, '对接公共财政和项目全生命周期主题。', '责任单位：市行政审批局、公共资源交易中心；所属业务分类编号：4；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:16:00', '1', '2026-09-03 10:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (24, 6, '统计报表报送', 'STAT_REPORT', '调查对象或部门按统计调查制度报送月度、季度和年度报表。', '报告期开启且报送主体在统计名录库中。', '报表通过审核入库或退回修改。', '一个调查对象一个报告期的一次报表报送', 100, '', 0, '来源：统计联网直报。支撑宏观经济数据域。', '责任单位：市发展改革委、市统计局；所属业务分类编号：6；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:19:00', '1', '2026-09-03 10:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (25, 6, '经济指标核定', 'STAT_INDICATOR', '对地区生产总值、固定资产投资、社会消费品零售总额、工业增加值等核心指标进行审核认定。', '基础报表已齐，专业处室完成初审。', '指标正式数或快报数发布并冻结版本。', '一个指标一个报告期的一次核定', 100, '', 0, '作为城市体征和经济监测的权威口径。', '责任单位：市发展改革委、市统计局；所属业务分类编号：6；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:22:00', '1', '2026-09-03 10:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (26, 6, '经济景气监测', 'STAT_CLIMATE', '综合用电、税收、货运、用工等先行指标形成景气判断。', '监测周期到达且多源指标已汇聚。', '景气指数或监测专报发布。', '一个监测周期的一次景气评估', 100, '', 0, '用于经济运行调度会商，非法定统计数据。', '责任单位：市发展改革委、市统计局；所属业务分类编号：6；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:25:00', '1', '2026-09-03 10:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (27, 6, '国民经济核算确认', 'STAT_ACCOUNT', '按核算制度确认季度、年度地区生产总值及其产业结构。', '专业统计数据已齐，核算方法版本已确定。', '核算结果审定并按权限发布。', '一个核算期的一次 GDP 核算确认', 100, '', 0, '版本化管理，修订数与快报数分口径存放。', '责任单位：市发展改革委、市统计局；所属业务分类编号：6；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:28:00', '1', '2026-09-03 10:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (74, 15, '热线知识更新', 'HOTLINE_KNOWLEDGE', '对高频咨询事项维护标准答复和答案库。', '事项口径变化或新政策发布。', '知识条目审核发布。', '一条热线知识的一次发布（更新）', 100, '', 0, '提升即办率，减少工单派发。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:49:00', '1', '2026-09-03 12:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (28, 6, '专项调查实施', 'STAT_SURVEY', '组织劳动力调查、人口变动调查等专项调查的样本登记和数据回收。', '调查方案已批复，样本框已抽取。', '调查数据审核入库并形成调查报告。', '一个样本一个调查轮次的一次调查登记', 100, '', 0, '用于补充常规报表无法覆盖的结构分析。', '责任单位：市发展改革委、市统计局；所属业务分类编号：6；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:31:00', '1', '2026-09-03 10:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (29, 6, '手工报表汇总', 'STAT_MANUAL_SUM', '基层统计人员通过电子表格汇总后人工导入，仅用于直报覆盖前。', '报告期已到且该专业尚未纳入联网直报。', '汇总表导入并完成逻辑审核。', '一个专业一个报告期的一次手工汇总', 100, '', 1, '历史过程，已停用。现以统计报表报送为准。', '责任单位：市发展改革委、市统计局；所属业务分类编号：6；建模用途：DWD 明细事实过程。状态：停用（历史过渡过程，保留口径对照）。', '1', '2026-09-03 10:34:00', '1', '2026-09-03 10:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (30, 7, '规上企业纳统', 'IND_ABOVE_SCALE', '对达到规模标准的工业、批零住餐和服务业企业办理入库纳统。', '企业连续达标且证照、统计关系清楚。', '企业进入名录库并开始定期报送。', '一家企业的一次纳统入库', 100, '', 0, '关联法人单位数据域，支撑产业运行和营商监测。', '责任单位：市工业和信息化局；所属业务分类编号：7；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:37:00', '1', '2026-09-03 10:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (31, 7, '工业产值报送', 'IND_OUTPUT', '规上工业企业按月报送产值、增加值和主要产品产量。', '报告月开启且企业在工业名录中。', '产值数据审核通过并进入运行调度台账。', '一家企业一个月度的产值报送', 100, '', 0, '用于工业增速、行业贡献和产业链监测。', '责任单位：市工业和信息化局；所属业务分类编号：7；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:40:00', '1', '2026-09-03 10:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (32, 7, '产业链监测填报', 'IND_CHAIN', '对主导产业链关键节点企业填报订单、库存、用工和断点风险。', '企业被列入本市产业链监测名单。', '监测表审核入库，风险线索转运行调度。', '一家链上企业一个监测周期的填报', 100, '', 0, '服务产业链安全和稳增长调度。', '责任单位：市工业和信息化局；所属业务分类编号：7；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:43:00', '1', '2026-09-03 10:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (33, 7, '工业运行调度', 'IND_DISPATCH', '对停产半停产、用电异常和产值大幅波动企业开展调度会商。', '监测指标触发预警或主管部门下达调度任务。', '形成调度记录和帮扶措施，并跟踪销号。', '一家企业一次运行调度', 100, '', 0, '对接惠企政策和项目全生命周期。', '责任单位：市工业和信息化局；所属业务分类编号：7；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:46:00', '1', '2026-09-03 10:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (34, 7, '企业服务事项办理', 'IND_SERVICE', '受理企业提出的要素保障、政策咨询和问题诉求并转办相关部门。', '企业已实名且诉求要素齐全。', '事项办结并回访，或转入政策兑现流程。', '一家企业一次服务诉求办理', 100, '', 0, '支撑营商环境和惠企政策兑现分析。', '责任单位：市工业和信息化局；所属业务分类编号：7；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:49:00', '1', '2026-09-03 10:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (35, 7, '亩均效益评价', 'IND_MU_EVAL', '按年度对工业企业开展亩均税收、亩均增加值和单位能耗评价。', '评价年度结束且土地、税收、能耗数据已齐。', '评价等次确定并反馈企业。', '一家企业一个评价年度的亩均评价', 100, '', 0, '用于资源差别化配置和低效用地治理。', '责任单位：市工业和信息化局；所属业务分类编号：7；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:52:00', '1', '2026-09-03 10:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (36, 8, '项目储备入库', 'PRJ_RESERVE', '谋划生成的固定资产投资项目进入储备库，明确业主、投资和行业。', '项目建议书或谋划材料通过初审。', '项目获得储备编号并进入年度计划候选。', '一个投资项目的一次储备入库', 100, '', 0, '来源：投资项目在线审批监管平台。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:55:00', '1', '2026-09-03 10:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (37, 8, '项目立项审批', 'PRJ_APPROVE', '对政府投资项目审批或企业投资项目核准、备案。', '项目已储备或直接申报，要件符合审批目录。', '批复、核准或备案文件生效。', '一个项目的一次立项（审批/核准/备案）决定', 100, '', 0, '作为项目全生命周期起点法律事实。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 10:58:00', '1', '2026-09-03 10:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (38, 8, '项目开工登记', 'PRJ_START', '项目取得施工许可或具备开工条件后登记实际开工。', '立项已完成，用地和施工许可等开工要件已具备。', '开工日期确认并进入建设期监测。', '一个项目的一次开工登记', 100, '', 0, '用于开工率、投资进度和建设监管。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:01:00', '1', '2026-09-03 11:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (39, 8, '建设进度填报', 'PRJ_PROGRESS', '项目单位按月填报形象进度、完成投资和存在问题。', '项目处于建设期，报告月已开启。', '进度数据审核入库，滞后项目转调度。', '一个项目一个月度的进度填报', 100, '', 0, '支撑重大项目调度和财政资金支付。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:04:00', '1', '2026-09-03 11:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (40, 8, '项目竣工验收', 'PRJ_ACCEPT', '项目按批准内容建成后组织竣工验收或备案。', '建设内容完成，专项验收意见齐全。', '竣工验收合格并出具验收文件。', '一个项目的一次竣工验收', 100, '', 0, '建设期结束标志，转入投产达效跟踪。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:07:00', '1', '2026-09-03 11:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (41, 8, '投产达效跟踪', 'PRJ_BENEFIT', '对已竣工项目跟踪达产、税收、就业和承诺履约。', '项目已竣工或部分投产，跟踪周期到达。', '形成达效评估记录，未达效转入督导。', '一个项目一个跟踪周期的达效评估', 100, '', 0, '对接惠企政策和财政绩效。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:10:00', '1', '2026-09-03 11:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (42, 8, '项目变更调整', 'PRJ_CHANGE', '对建设内容、投资规模、工期或资金来源发生重大变化的项目办理变更。', '项目已立项且变更事项达到规定幅度。', '变更批复生效并更新项目台账。', '一个项目的一次变更审批', 100, '', 0, '保证项目口径前后一致，避免重复计算投资。', '责任单位：市发展改革委；所属业务分类编号：8；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:13:00', '1', '2026-09-03 11:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (43, 10, '市场主体设立登记', 'ENT_ESTABLISH', '对有限公司、个体工商户、农民专业合作社等办理设立登记并核发营业执照。', '申请人提交的名称、住所、出资和人员信息通过核验。', '核准登记并签发营业执照，同步法人库。', '一个市场主体的一次设立登记', 100, '', 0, '法人单位数据域权威入口，对接电子证照和信用。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:16:00', '1', '2026-09-03 11:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (44, 10, '市场主体变更登记', 'ENT_CHANGE', '办理名称、住所、法定代表人、经营范围或出资等信息变更。', '主体存续且变更事项依法应登记。', '变更登记完成并换发或标注执照。', '一个市场主体的一次变更登记', 100, '', 0, '用于企业生命周期和经营异常分析。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:19:00', '1', '2026-09-03 11:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (45, 10, '市场主体注销登记', 'ENT_CANCEL', '对解散、被吊销或简易注销的市场主体办理注销。', '清算公告、税务和社保清算等前置条件满足，或符合简易注销情形。', '核准注销，主体退出名录。', '一个市场主体的一次注销登记', 100, '', 0, '企业退出事实，需保留历史快照供追溯。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:22:00', '1', '2026-09-03 11:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (46, 10, '经营许可办理', 'ENT_LICENSE', '对食品经营、工业产品许可等与主体资格相关的行政许可办理。', '主体已设立，许可事项在市场监管职责目录内。', '许可决定作出并制发许可证照。', '一次经营许可办件', 100, '', 0, '与行政审批办件口径衔接，按许可事项拆分。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:25:00', '1', '2026-09-03 11:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (47, 10, '经营异常列入', 'ENT_ABNORMAL', '对未年报、通过登记住所无法联系等情形列入经营异常名录。', '法定列入情形成立且已履行告知程序。', '列入决定生效并推送信用平台。', '一个市场主体的一次异常列入', 100, '', 0, '企业信用风险主题的关键事实。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:28:00', '1', '2026-09-03 11:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (48, 10, '经营异常移出', 'ENT_ABNORMAL_OUT', '主体补报年报或恢复联系后申请移出经营异常名录。', '列入事由已消除并提交移出申请。', '核准移出并更新信用状态。', '一个市场主体的一次异常移出', 100, '', 0, '与列入成对，保证信用状态可追溯。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:31:00', '1', '2026-09-03 11:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (49, 10, '分支机构备案', 'ENT_BRANCH', '对分公司、经营网点等分支机构办理设立或撤销备案。', '隶属企业存续，分支机构住所和负责人信息齐全。', '备案完成并纳入主体关系图谱。', '一个分支机构的一次备案', 100, '', 0, '支撑企业集团结构和监管对象识别。', '责任单位：市市场监督管理局；所属业务分类编号：10；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:34:00', '1', '2026-09-03 11:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (50, 11, '双随机抽查任务生成', 'INSPECT_RANDOM', '按年度计划从检查对象名录和执法人员名录中随机抽取并生成检查任务。', '抽查事项清单和两库已维护，计划批次获批。', '检查任务下达至执法人员。', '一个抽查批次中一条检查任务', 100, '', 0, '来源：事中事后监管平台。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:37:00', '1', '2026-09-03 11:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (51, 11, '现场检查实施', 'INSPECT_ONSITE', '执法人员按检查单到场检查并采集检查结果、证据和整改要求。', '检查任务已领取，被检查对象可定位。', '检查结果提交审核，需要立案的转入立案。', '一次现场检查', 100, '', 0, '企业经营监管的核心事实粒度。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:40:00', '1', '2026-09-03 11:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (52, 11, '投诉举报受理', 'INSPECT_COMPLAINT', '受理消费者投诉、违法行为举报并分流至承办机构。', '投诉举报要素齐全且属于市场监管职责。', '生成工单并派发，或告知不予受理理由。', '一件投诉举报受理', 100, '', 0, '可与 12345 工单对账，避免重复统计。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:43:00', '1', '2026-09-03 11:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (53, 11, '行政处罚立案', 'INSPECT_CASE', '对涉嫌违法线索审核后立案，确定案由、当事人和承办人。', '初步证据表明存在违法行为且未超过追责时效。', '立案审批表生效并进入调查取证。', '一起行政处罚案件立案', 100, '', 0, '处罚案件生命周期起点。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:46:00', '1', '2026-09-03 11:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (54, 11, '行政处罚决定', 'INSPECT_PENALTY', '调查终结后依法作出处罚、不予处罚或移送决定。', '调查终结，权利告知和听证程序已履行。', '处罚决定书送达并推送信用公示。', '一起案件的一次处罚决定', 100, '', 0, '公共信用双公示的权威来源之一。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:49:00', '1', '2026-09-03 11:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (55, 11, '处罚执行结案', 'INSPECT_CLOSE', '当事人履行处罚或依法强制执行后结案归档。', '决定书已送达，执行措施已完成或依法中止。', '结案审批通过，案卷归档。', '一起案件的一次结案', 100, '', 0, '用于执行到位率和案卷评查。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:52:00', '1', '2026-09-03 11:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (56, 11, '信用修复办理', 'INSPECT_CREDIT_REPAIR', '对符合修复条件的行政处罚或异常信息办理信用修复。', '公示期届满或整改到位，申请人提交修复材料。', '修复决定生效并更新信用记录。', '一条信用信息的一次修复', 100, '', 0, '对接公共信用数据域和企业信用风险主题。', '责任单位：市市场监督管理局；所属业务分类编号：11；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:55:00', '1', '2026-09-03 11:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (57, 12, '产品质量监督抽检', 'QUALITY_SAMPLE', '按抽检计划对产品进行抽样、检测并公示结果。', '抽检计划获批，样品可溯源至生产者或销售者。', '检测报告出具，不合格转入核查处置。', '一个样品的一次监督抽检', 100, '', 0, '不合格率、问题产品和区域风险分析基础。', '责任单位：市市场监督管理局；所属业务分类编号：12；建模用途：DWD 明细事实过程。', '1', '2026-09-03 11:58:00', '1', '2026-09-03 11:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (58, 12, '食品经营许可', 'QUALITY_FOOD_LICENSE', '对食品销售、餐饮服务等办理食品经营许可或备案。', '主体已登记，经营项目和场所条件符合规定。', '许可或备案完成并制发证件。', '一次食品经营许可（备案）办件', 100, '', 0, '与市场准入许可区分：本过程专指食品安全许可。', '责任单位：市市场监督管理局；所属业务分类编号：12；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:01:00', '1', '2026-09-03 12:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (59, 12, '药品不良反应报告', 'QUALITY_ADR', '医疗机构、经营企业报告药品、医疗器械不良反应或事件。', '发生疑似不良反应且报告单位具备报告资格。', '报告审核入库并按级别评价。', '一份不良反应报告', 100, '', 0, '医疗健康与市场监管交叉事实，粒度到报告编号。', '责任单位：市市场监督管理局；所属业务分类编号：12；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:04:00', '1', '2026-09-03 12:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (60, 12, '特种设备检验', 'QUALITY_SPECIAL', '对电梯、锅炉、压力容器、起重机械等实施法定检验。', '设备在册且到达检验周期或新装登记。', '出具检验结论，不合格设备停止使用。', '一台特种设备的一次法定检验', 100, '', 0, '城市生命线和公共安全相关。', '责任单位：市市场监督管理局；所属业务分类编号：12；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:07:00', '1', '2026-09-03 12:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (61, 12, '不合格产品处置', 'QUALITY_UNQUALIFIED', '对抽检不合格产品责令下架、召回、整改并复查。', '不合格检测结论已生效。', '处置措施落实并复查合格或立案处罚。', '一个不合格批次的一次处置闭环', 100, '', 0, '与抽检、处罚过程关联，禁止重复计算不合格批次。', '责任单位：市市场监督管理局；所属业务分类编号：12；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:10:00', '1', '2026-09-03 12:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (62, 12, '检验检测机构资质认定', 'QUALITY_LAB', '对检验检测机构办理资质认定、变更或撤销。', '机构申请事项符合资质认定目录。', '认定决定作出并更新机构名录。', '一家机构的一次资质认定决定', 100, '', 0, '保证抽检和溯源数据的检测能力可信。', '责任单位：市市场监督管理局；所属业务分类编号：12；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:13:00', '1', '2026-09-03 12:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (63, 14, '网格事件上报', 'GRID_REPORT', '网格员对发现的城市管理、治安、矛盾和民生问题拍照定位上报。', '事件发生在本网格且要素满足上报规范。', '生成事件单并进入分流。', '一条网格事件上报', 100, '', 0, '城市事件闭环的发现端事实。来源：综治网格或城运系统。', '责任单位：市委政法委；所属业务分类编号：14；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:16:00', '1', '2026-09-03 12:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (64, 14, '事件分拨派遣', 'GRID_DISPATCH', '指挥中心按职责清单将事件派遣至处置部门或下沉网格。', '事件已受理且职责归属可判定。', '处置单位签收或退回重派。', '一条事件的一次派遣', 100, '', 0, '用于派遣准确率和跨部门推诿分析。', '责任单位：市委政法委；所属业务分类编号：14；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:19:00', '1', '2026-09-03 12:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (65, 14, '事件处置反馈', 'GRID_HANDLE', '处置单位现场处置后反馈结果、影像和办结说明。', '事件已签收且在处置时限内。', '反馈提交，进入核查或结案。', '一条事件的一次处置反馈', 100, '', 0, '事件闭环的处置端事实。', '责任单位：市委政法委；所属业务分类编号：14；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:22:00', '1', '2026-09-03 12:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (66, 14, '重点人员巡查', 'GRID_PATROL', '对重点关注人员按频次开展走访并记录在离状态和风险。', '人员在重点人员库且到达巡查周期。', '巡查记录入库，异常线索转事件。', '一名对象的一次巡查记录', 100, '', 0, '人口与社会治理交叉，按最小必要原则存储。', '责任单位：市委政法委；所属业务分类编号：14；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:25:00', '1', '2026-09-03 12:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (67, 14, '房屋信息采集', 'GRID_HOUSE', '采集或更新房屋地址、用途、出租和实有人口关联信息。', '房屋地址已挂接标准地名地址库。', '采集数据质检通过并更新房屋人房关系。', '一套房屋的一次信息采集（更新）', 100, '', 0, '人房关联基础过程，服务网格和住房主题。', '责任单位：市委政法委；所属业务分类编号：14；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:28:00', '1', '2026-09-03 12:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (68, 14, '矛盾隐患排查', 'GRID_HAZARD', '排查邻里纠纷、安全隐患和不稳定因素并分级建档。', '排查任务下达或网格日常巡查发现。', '隐患录入并明确稳控或化解责任。', '一条矛盾隐患的一次排查建档', 100, '', 0, '可流转至人民调解或应急隐患治理。', '责任单位：市委政法委；所属业务分类编号：14；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:31:00', '1', '2026-09-03 12:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (69, 15, '诉求受理', 'HOTLINE_ACCEPT', '话务或网上渠道受理群众咨询、求助、投诉和建议，生成热线工单。', '诉求要素可识别且属于政府职责或公共服务范围。', '工单编号生成并完成分类赋码。', '一件热线诉求受理', 100, '', 0, '政务热线数据域权威入口。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:34:00', '1', '2026-09-03 12:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (70, 15, '工单派发', 'HOTLINE_DISPATCH', '按部门职责和区划将工单派至主办、协办单位。', '工单已受理，知识库或职责清单可匹配承办单位。', '承办单位签收或退回重派。', '一件工单的一次派发', 100, '', 0, '与网格派遣区分：本过程仅限 12345 工单。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:37:00', '1', '2026-09-03 12:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (71, 15, '工单办理', 'HOTLINE_HANDLE', '承办单位调查核实并答复诉求人，上传办理结果。', '工单已签收。', '办理结果提交，进入回访或退回重办。', '一件工单的一次办理反馈', 100, '', 0, '部门履职和城市事件闭环的核心时效事实。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:40:00', '1', '2026-09-03 12:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (72, 15, '回访评价', 'HOTLINE_FOLLOWUP', '对办结工单开展回访，采集解决情况和满意度。', '工单已提交办理结果。', '回访完成，不满意件转重办或升级。', '一件工单的一次回访', 100, '', 0, '支撑满意率和重办率分析。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:43:00', '1', '2026-09-03 12:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (73, 15, '逾期催办', 'HOTLINE_URGE', '对临期、逾期工单自动或人工催办并记录升级。', '工单超过承诺时限或进入临期窗口。', '催办通知送达并更新预警级别。', '一件工单的一次催办', 100, '', 0, '用于超时治理，不替代办理事实。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:46:00', '1', '2026-09-03 12:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (75, 15, '热线人工台账登记', 'HOTLINE_LEDGER', '话务员在电子表格登记来电，仅用于系统割接前。', '热线系统不可用或事项未建档。', '台账导入正式工单库或作废。', '一条人工台账登记', 100, '', 1, '历史过程，已停用。', '责任单位：市政府办公室；所属业务分类编号：15；建模用途：DWD 明细事实过程。状态：停用（历史过渡过程，保留口径对照）。', '1', '2026-09-03 12:52:00', '1', '2026-09-03 12:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (76, 16, '信访事项登记', 'PETITION_REGISTER', '对来访、来信、网上信访进行登记、分类和重复件识别。', '信访人身份可核验，诉求属于信访受理范围。', '生成信访件号并进入转办。', '一件信访事项登记', 100, '', 0, '与 12345 工单对账，同一诉求不得双边重复计件。', '责任单位：市信访局、市司法局；所属业务分类编号：16；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:55:00', '1', '2026-09-03 12:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (77, 16, '信访事项转办', 'PETITION_TRANSFER', '按属地和职责将信访事项转送或交办责任单位。', '事项已登记且责任单位可判定。', '责任单位签收。', '一件信访事项的一次转办', 100, '', 0, '用于转办准确率和空转分析。', '责任单位：市信访局、市司法局；所属业务分类编号：16；建模用途：DWD 明细事实过程。', '1', '2026-09-03 12:58:00', '1', '2026-09-03 12:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (78, 16, '信访办理答复', 'PETITION_REPLY', '责任单位调查核实后出具答复意见并送达信访人。', '事项已签收且办理期限未届满或已依法延期。', '答复送达，信访人可申请复查复核。', '一件信访事项的一次办理答复', 100, '', 0, '信访办理闭环的核心事实。', '责任单位：市信访局、市司法局；所属业务分类编号：16；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:01:00', '1', '2026-09-03 13:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (79, 16, '人民调解受理', 'MEDIATE_ACCEPT', '人民调解组织受理民间纠纷并确定调解员。', '当事人申请或接受调解，纠纷属于调解范围。', '调解案件立案并约定调解时间。', '一起纠纷的一次调解受理', 100, '', 0, '基层治理和信访分流的重要过程。', '责任单位：市信访局、市司法局；所属业务分类编号：16；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:04:00', '1', '2026-09-03 13:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (80, 16, '调解协议达成', 'MEDIATE_AGREE', '经调解达成书面或口头协议并归档，必要时申请司法确认。', '调解已开展且当事人自愿。', '协议生效或调解不成终结。', '一起纠纷的一次调解结果', 100, '', 0, '用于调解成功率和积案化解分析。', '责任单位：市信访局、市司法局；所属业务分类编号：16；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:07:00', '1', '2026-09-03 13:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (81, 16, '信访积案化解销号', 'PETITION_RESOLVE', '对纳入积案库的疑难信访开展包案化解并销号。', '事项在积案库且包案领导、方案已明确。', '审核确认化解并销号，或继续挂牌。', '一件积案的一次化解审核', 100, '', 0, '社会治理重点任务，按件追踪不按人次拆分。', '责任单位：市信访局、市司法局；所属业务分类编号：16；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:10:00', '1', '2026-09-03 13:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (82, 18, '就业登记', 'EMP_REGISTER', '劳动者与用人单位建立劳动关系后办理就业登记。', '劳动合同或用工事实成立，双方身份核验通过。', '就业登记生效并关联参保。', '一名劳动者在一家单位的一次就业登记', 100, '', 0, '就业社保监测的就业端事实。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:13:00', '1', '2026-09-03 13:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (83, 18, '失业登记', 'UNEMP_REGISTER', '符合条件的失业人员办理失业登记并纳入就业帮扶。', '劳动关系解除或终止，且符合失业登记条件。', '失业登记生效，可申领失业金或享受服务。', '一名人员的一次失业登记', 100, '', 0, '与就业登记互斥有效，需记录起止时间。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:16:00', '1', '2026-09-03 13:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (84, 18, '职业培训报名', 'TRAIN_ENROLL', '劳动者报名参加补贴性职业技能培训并审核资格。', '培训项目在目录内，学员符合补贴对象条件。', '报名审核通过并进入培训实施。', '一名学员一个培训班次的报名', 100, '', 0, '用于培训人次和持证转化分析。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:19:00', '1', '2026-09-03 13:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (85, 18, '社保参保登记', 'SI_ENROLL', '办理企业职工、灵活就业或城乡居民社会保险参保登记。', '参保身份核验通过，险种组合符合政策。', '参保关系建立并生成社保编号。', '一名参保人一个险种的一次参保登记', 100, '', 0, '就业社保数据域权威入口。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:22:00', '1', '2026-09-03 13:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (86, 18, '社保缴费核定', 'SI_CONTRIBUTE', '按缴费基数和费率核定单位或个人应缴社会保险费。', '参保关系有效，工资申报或档次选择已完成。', '核定单生成并推送税务征收。', '一个缴费主体一个费款所属期的一次核定', 100, '', 0, '与税务实缴对账，禁止用核定代替实缴。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:25:00', '1', '2026-09-03 13:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (87, 18, '社保待遇申领', 'SI_BENEFIT', '办理养老、失业、工伤等待遇申领并核定发放。', '参保缴费条件满足，待遇资格审核通过。', '待遇核定完成并进入发放。', '一名享受人一个待遇项目的一次申领核定', 100, '', 0, '民生保障主题的待遇事实。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:28:00', '1', '2026-09-03 13:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (88, 18, '社保关系转移', 'SI_TRANSFER', '办理跨统筹区养老保险等关系转入转出。', '转出地和转入地参保信息核验一致。', '关系接续完成，基金转移指令发出。', '一名参保人一次关系转移', 100, '', 0, '需保留转入转出两侧流水以便对账。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:31:00', '1', '2026-09-03 13:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (89, 18, '社保纸质申报', 'SI_PAPER_DECLARE', '单位通过纸质报表申报增减员，仅用于网厅覆盖前。', '单位未开通网厅且属过渡期允许情形。', '纸质申报录入系统。', '一个单位一次纸质增减员申报', 100, '', 1, '历史过程，已停用。', '责任单位：市人力资源社会保障局；所属业务分类编号：18；建模用途：DWD 明细事实过程。状态：停用（历史过渡过程，保留口径对照）。', '1', '2026-09-03 13:34:00', '1', '2026-09-03 13:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (189, 40, '农村人居环境整治', 'RURAL_ENV', '对村庄生活污水、垃圾和村容村貌问题建账整治。', '问题点位已摸排上图。', '整治验收销号。', '一个村庄问题点位一次整治销号', 100, '', 0, '宜居乡村建设主题过程。', '责任单位：市农业农村局；所属业务分类编号：40；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:34:00', '1', '2026-09-03 18:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (90, 19, '最低生活保障审核', 'ASSIST_DIBAO', '对家庭提出的低保申请开展经济状况核对、评议和审批。', '申请人提交申请，家庭成员可核验。', '作出批准、调整或不予批准决定。', '一个保障家庭的一次低保审批', 100, '', 0, '困难群体保障主题核心过程。经济核对结果单独成表。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:37:00', '1', '2026-09-03 13:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (91, 19, '特困人员供养认定', 'ASSIST_DESTITUTE', '对无劳动能力、无生活来源且无法定赡养抚养人的人员认定特困供养。', '申请或乡镇街道摸排发现，核对材料齐全。', '认定决定生效并明确供养方式。', '一名特困人员的一次认定', 100, '', 0, '与低保互斥管理，防止重复保障。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:40:00', '1', '2026-09-03 13:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (92, 19, '临时救助审批', 'ASSIST_TEMP', '对急难型或支出型困难家庭给予一次性或阶段性临时救助。', '急难情形成立或刚性支出超出承受能力。', '救助金审批拨付或物资发放完成。', '一个家庭一次临时救助审批', 100, '', 0, '按救助决定计件，不按发放批次拆分。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:43:00', '1', '2026-09-03 13:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (93, 19, '养老机构入住', 'ELDER_CHECKIN', '老年人与养老机构签订服务协议并办理入住登记。', '评估等级和床位匹配，费用和监护人信息齐全。', '入住生效，服务计划建立。', '一名老年人一次机构入住', 100, '', 0, '一老一小服务主题的供给事实。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:46:00', '1', '2026-09-03 13:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (94, 19, '居家养老服务工单', 'ELDER_HOME', '为居家老年人提供助餐、助洁、助医等服务并回访。', '老年人在居家养老对象库且服务项目已签约。', '服务完成并确认，异常转投诉。', '一名对象一次上门服务工单', 100, '', 0, '用于服务覆盖率和补贴资金核销。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:49:00', '1', '2026-09-03 13:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (95, 19, '高龄津贴发放', 'ELDER_ALLOWANCE', '对达到年龄条件的老年人按月核定并发放高龄津贴。', '户籍、生存和年龄核验通过。', '发放成功或因死亡迁出停发。', '一名老年人一个发放月份的津贴发放', 100, '', 0, '生存认证失败不得发放，需保留停发原因。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:52:00', '1', '2026-09-03 13:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (96, 19, '经济状况核对', 'ASSIST_CHECK', '向公安、人社、住建、金融等部门发起救助对象家庭经济状况核对。', '救助申请已受理或定期复核到期。', '核对报告生成并反馈审批环节。', '一个家庭一次经济状况核对', 100, '', 0, '跨部门核验过程，不直接产生发放事实。', '责任单位：市民政局；所属业务分类编号：19；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:55:00', '1', '2026-09-03 13:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (97, 20, '医保参保登记', 'MI_ENROLL', '办理职工医保、居民医保参保登记和停保。', '参保身份和缴费主体明确。', '参保关系生效或终止。', '一名参保人一个险种的一次参保变动', 100, '', 0, '与社保参保分库管理，人员主索引需对齐人口库。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 13:58:00', '1', '2026-09-03 13:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (98, 20, '医保缴费核定', 'MI_CONTRIBUTE', '核定医保费征缴计划并推送税务。', '参保有效，缴费基数或档次已确认。', '核定完成。', '一个缴费主体一个费款所属期的医保费核定', 100, '', 0, '与税务实缴对账。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:01:00', '1', '2026-09-03 14:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (99, 20, '就医结算', 'MI_SETTLE', '参保人在定点医药机构发生的费用按政策即时结算。', '持证或电子凭证核验通过，诊疗符合医保目录。', '结算单生成，基金支付和个人负担入账。', '一次就诊（处方）的医保结算', 100, '', 0, '基金运行最细事实，需保留目录明细。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:04:00', '1', '2026-09-03 14:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (100, 20, '医保待遇支付', 'MI_BENEFIT', '办理门诊慢特病、生育、手工报销等待遇支付。', '待遇资格审核通过，票据和病历符合规定。', '支付指令发出并到账。', '一笔待遇支付', 100, '', 0, '与即时结算区分：本过程覆盖零星报销。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:07:00', '1', '2026-09-03 14:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (101, 20, '异地就医备案', 'MI_OFFSITE', '对长期异地居住或转诊人员办理异地就医备案。', '参保状态正常，备案类型符合政策。', '备案生效，可在备案地直接结算。', '一名参保人一次异地就医备案', 100, '', 0, '影响结算地和支付政策，需记录有效期。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:10:00', '1', '2026-09-03 14:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (102, 20, '基金监管检查', 'MI_SUPERVISE', '对定点医药机构开展协议考核、飞行检查和智能监控。', '检查计划下达或监控规则触发线索。', '检查结论形成，违约金或移交处理。', '一家机构一次基金监管检查', 100, '', 0, '欺诈骗保查处的前置过程。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:13:00', '1', '2026-09-03 14:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (103, 20, '欺诈骗保查处', 'MI_FRAUD', '对虚假就医、倒卖药品、违规收费等线索立案查处。', '监控或举报线索达到立案标准。', '处理决定生效，追回基金并公示。', '一起欺诈骗保案件的处理决定', 100, '', 0, '可与市场监管、公安移送衔接。', '责任单位：市医疗保障局；所属业务分类编号：20；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:16:00', '1', '2026-09-03 14:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (104, 22, '学籍注册', 'EDU_ENROLL', '新生入学后注册学籍并建立全国学籍号关联。', '录取或入学资格审核通过，身份信息核验一致。', '学籍状态为在籍。', '一名学生在一所学校的一次学籍注册', 100, '', 0, '教育数据域核心过程。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:19:00', '1', '2026-09-03 14:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (105, 22, '学籍异动', 'EDU_TRANSFER', '办理转学、休学、复学、退学等学籍变动。', '异动原因符合规定，转出转入学校确认。', '学籍状态更新并完成电子档案移交。', '一名学生一次学籍异动', 100, '', 0, '学位供需和就学稳定性分析基础。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:22:00', '1', '2026-09-03 14:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (106, 22, '招生录取', 'EDU_ADMISSION', '按招生计划完成幼儿园、义务教育和普通高中录取。', '招生计划下达，报名和志愿信息有效。', '录取结果公布并通知入学。', '一名学生一个学段的一次录取', 100, '', 0, '与学籍注册衔接，未报到需记录。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:25:00', '1', '2026-09-03 14:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (107, 22, '学位分配', 'EDU_SEAT', '依据学位预警和施教区规则分配入学学位。', '适龄儿童少年信息核验通过。', '学位确定或进入调剂。', '一名适龄儿童一次学位分配', 100, '', 0, '教育资源均衡主题的关键事实。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:28:00', '1', '2026-09-03 14:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (108, 22, '教师资格认定', 'EDU_TEACHER', '对申请认定教师资格的人员开展学历、体检和普通话等审核。', '考试成绩合格且材料齐全。', '认定决定作出并制发资格证书。', '一名申请人一次教师资格认定', 100, '', 0, '对接电子证照。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:31:00', '1', '2026-09-03 14:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (109, 22, '学校设立许可', 'EDU_SCHOOL', '对民办学校或其他教育机构办理设立、变更或终止许可。', '举办者条件和章程符合规定。', '许可决定生效并更新学校名录。', '一所学校一次设立（变更）许可', 100, '', 0, '教育机构主数据维护过程。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:34:00', '1', '2026-09-03 14:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (110, 22, '教学质量监测', 'EDU_QUALITY', '组织学业质量监测、作业量和课后服务评估。', '监测方案获批，样本校抽取完成。', '监测结果入库并反馈学校。', '一所学校一个监测轮次的质量监测', 100, '', 0, '不存储学生个人试卷明细到主题层。', '责任单位：市教育体育局；所属业务分类编号：22；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:37:00', '1', '2026-09-03 14:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (111, 23, '传染病报告', 'PH_INFECT', '医疗机构对法定传染病进行网络直报和订正。', '诊断符合病例定义。', '报告卡审核入库，暴发线索转应急。', '一张传染病报告卡', 100, '', 0, '公共卫生预警主题最细事实。按最小必要原则管理。', '责任单位：市卫生健康委；所属业务分类编号：23；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:40:00', '1', '2026-09-03 14:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (112, 23, '预防接种登记', 'PH_VACCINE', '受种者接种疫苗并登记剂次、批号和异常反应。', '接种资质和知情同意完成，疫苗可追溯。', '接种记录写入免疫档案。', '一名受种者一次剂次接种', 100, '', 0, '免疫规划过程，关联人口主索引。', '责任单位：市卫生健康委；所属业务分类编号：23；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:43:00', '1', '2026-09-03 14:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (113, 23, '妇幼保健建册', 'PH_MATERNAL', '为孕产妇和 0—6 岁儿童建立保健手册并开展随访。', '怀孕或出生信息核验通过。', '手册建立，随访计划生成。', '一名服务对象一次建册', 100, '', 0, '一老一小和公共卫生交叉过程。', '责任单位：市卫生健康委；所属业务分类编号：23；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:46:00', '1', '2026-09-03 14:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (114, 23, '卫生监督执法', 'PH_SUPERVISE', '对公共场所、生活饮用水、职业卫生等实施监督抽查。', '监督任务下达或投诉线索成立。', '监督意见书送达，违法线索立案。', '一次卫生监督检查', 100, '', 0, '与市场监管现场检查分区：本过程属卫健职责。', '责任单位：市卫生健康委；所属业务分类编号：23；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:49:00', '1', '2026-09-03 14:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (115, 23, '居民健康档案建档', 'PH_ARCHIVE', '基层医疗卫生机构为常住居民建立或更新电子健康档案。', '居民身份核验通过并知情同意。', '档案质控通过并赋予档案号。', '一名居民一次建档（更新）', 100, '', 0, '人口与医疗健康交叉主数据过程。', '责任单位：市卫生健康委；所属业务分类编号：23；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:52:00', '1', '2026-09-03 14:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (116, 23, '突发公共卫生事件报告', 'PH_EMERGENCY', '对聚集性疫情、食品安全事故等突发公卫事件进行分级报告。', '事件达到报告标准。', '报告审核并启动应急响应衔接。', '一起突发公共卫生事件的一次报告', 100, '', 0, '对接应急处置过程，事件编号需统一。', '责任单位：市卫生健康委；所属业务分类编号：23；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:55:00', '1', '2026-09-03 14:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (117, 24, '医疗机构执业许可', 'MED_LICENSE', '对医疗机构办理执业许可、校验、变更和注销。', '设置批准或备案完成，人员设备达标。', '许可决定生效并更新机构名录。', '一家医疗机构一次执业许可决定', 100, '', 0, '医疗资源配置主题的机构主数据过程。', '责任单位：市卫生健康委；所属业务分类编号：24；建模用途：DWD 明细事实过程。', '1', '2026-09-03 14:58:00', '1', '2026-09-03 14:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (118, 24, '医师执业注册', 'MED_DOCTOR', '办理医师执业注册、变更执业地点和多点执业备案。', '资格证书有效，聘用机构合法。', '注册完成并制发执业证书。', '一名医师一次执业注册（变更）', 100, '', 0, '医务人员主数据过程。', '责任单位：市卫生健康委；所属业务分类编号：24；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:01:00', '1', '2026-09-03 15:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (119, 24, '门诊就诊', 'MED_OUTPATIENT', '患者在医疗机构完成挂号、接诊、检查和处方。', '患者身份核验，号源有效。', '接诊结束并产生门诊日志。', '一名患者一次门诊就诊', 100, '', 0, '诊疗服务最细粒度之一，需脱敏后入仓。', '责任单位：市卫生健康委；所属业务分类编号：24；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:04:00', '1', '2026-09-03 15:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (120, 24, '住院入院', 'MED_ADMIT', '患者办理入院登记，确定科室、诊断和主管医师。', '入院指征成立，床位可用。', '入院登记完成，住院号生效。', '一名患者一次住院入院', 100, '', 0, '与出院成对，构成一次住院过程。', '责任单位：市卫生健康委；所属业务分类编号：24；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:07:00', '1', '2026-09-03 15:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (121, 24, '出院结算', 'MED_DISCHARGE', '患者出院办理诊断确认、病案归档和费用结算。', '临床出院医嘱开立。', '出院结算完成，病案首页提交。', '一名患者一次出院结算', 100, '', 0, '对接医保结算，住院费用以出院为准。', '责任单位：市卫生健康委；所属业务分类编号：24；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:10:00', '1', '2026-09-03 15:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (122, 24, '医疗质量质控', 'MED_QC', '对病案首页、合理用药、院感等开展质控评价。', '质控周期到达或触发专项。', '质控结果反馈机构并纳入绩效考核。', '一家机构一个质控周期的评价', 100, '', 0, '服务质量分析，不替代行政处罚。', '责任单位：市卫生健康委；所属业务分类编号：24；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:13:00', '1', '2026-09-03 15:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (123, 26, '规划编制报批', 'PLAN_COMPILE', '组织国土空间总体规划、详细规划专项规划编制并报批。', '编制任务下达，基础数据现势。', '规划成果批复并入库上图。', '一部规划的一次报批', 100, '', 0, '规划实施监测的规则源头。', '责任单位：市自然资源和规划局；所属业务分类编号：26；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:16:00', '1', '2026-09-03 15:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (124, 26, '用地预审与选址', 'PLAN_PRECHECK', '对建设项目用地进行预审和规划选址。', '项目已立项或同步申报，用地范围明确。', '预审（选址）意见书核发。', '一个建设项目一次用地预审', 100, '', 0, '项目全生命周期与规划实施交叉过程。', '责任单位：市自然资源和规划局；所属业务分类编号：26；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:19:00', '1', '2026-09-03 15:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (125, 26, '建设工程规划许可', 'PLAN_PERMIT', '核发建设工程规划许可证，明确容积率、退线和用途。', '设计方案审查通过，用地手续齐全。', '许可证签发并上图监管。', '一个工程一次规划许可', 100, '', 0, '违法建设认定的对照基准。', '责任单位：市自然资源和规划局；所属业务分类编号：26；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:22:00', '1', '2026-09-03 15:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (126, 26, '土地用途管制审查', 'PLAN_CONTROL', '对农转用、土地征收和规划用途调整进行审查。', '报件符合管制规则和生态红线要求。', '审查意见或批复生效。', '一宗地一次用途管制审查', 100, '', 0, '自然资源和生态文明交叉过程。', '责任单位：市自然资源和规划局；所属业务分类编号：26；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:25:00', '1', '2026-09-03 15:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (127, 26, '不动产登记', 'REG_IMMOVABLE', '办理土地、房屋等不动产首次登记、转移、抵押和注销。', '权属来源清楚，税费和地籍调查完成。', '登记完成并颁发（更新）权证。', '一宗不动产一次登记', 100, '', 0, '权属权威事实，安全等级按人口法人交叉从严。', '责任单位：市自然资源和规划局；所属业务分类编号：26；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:28:00', '1', '2026-09-03 15:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (128, 26, '规划核实', 'PLAN_VERIFY', '工程竣工后对照许可内容进行规划核实。', '工程完工并提交核实申请。', '核实合格意见出具或责令整改。', '一个工程一次规划核实', 100, '', 0, '规划许可闭环，未核实不得办理产权。', '责任单位：市自然资源和规划局；所属业务分类编号：26；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:31:00', '1', '2026-09-03 15:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (129, 27, '建筑工程施工许可', 'BLD_PERMIT', '对房屋建筑和市政工程核发施工许可证。', '用地、规划、图纸审查和资金到位等条件满足。', '施工许可签发，工程进入施工监管。', '一个工程一次施工许可', 100, '', 0, '工程建设监管主题的法定开工依据。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:34:00', '1', '2026-09-03 15:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (130, 27, '工程质量监督注册', 'BLD_QUALITY', '工程开工前办理质量监督手续并实施过程监督。', '施工许可已取得或同步办理。', '监督注册完成，监督计划下达。', '一个工程一次质量监督注册', 100, '', 0, '质量问题整改单独成过程。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:37:00', '1', '2026-09-03 15:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (131, 27, '竣工验收备案', 'BLD_ACCEPT', '建设单位组织竣工验收后向主管部门备案。', '规划、消防、档案等专项验收通过。', '备案完成，工程可交付使用。', '一个工程一次竣工验收备案', 100, '', 0, '与投资项目竣工验收区分：本过程为住建法定备案。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:40:00', '1', '2026-09-03 15:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (132, 27, '商品房预售许可', 'BLD_PRESALE', '对符合条件的商品房项目核发预售许可证。', '工程形象进度和资金监管账户达标。', '预售许可签发并公示楼盘表。', '一个预售项目一次许可', 100, '', 0, '房地产市场监管关键门槛。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:43:00', '1', '2026-09-03 15:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (133, 27, '房屋网签备案', 'BLD_CONTRACT', '对商品房、存量房买卖合同进行网签和备案。', '房源核验通过，当事人实名。', '合同备案号生成。', '一份房屋买卖合同网签备案', 100, '', 0, '住房保障与房地产主题交易事实。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:46:00', '1', '2026-09-03 15:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (134, 27, '保障性住房申请审核', 'BLD_AFFORDABLE', '对公租房、保障性租赁住房等申请开展资格审核和配租。', '申请人家庭住房、收入核验通过。', '资格认定或配租选房完成。', '一个家庭一次保障性住房资格（配租）审核', 100, '', 0, '与民政救助对象可交叉核验。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:49:00', '1', '2026-09-03 15:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (135, 27, '物业项目备案', 'BLD_PROPERTY', '对物业管理区域、业委会和物业企业项目备案。', '项目交付或业主大会依法成立。', '备案完成并纳入物业监管。', '一个物业项目一次备案', 100, '', 0, '城市运行和住房交叉过程。', '责任单位：市住房城乡建设局；所属业务分类编号：27；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:52:00', '1', '2026-09-03 15:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (136, 28, '市政设施巡查', 'MUNI_PATROL', '对城市道路、桥梁、照明和井盖等设施按频次巡查。', '巡查路线和部件编码已挂接城运一张图。', '巡查记录入库，病害转入上报。', '一条巡查路线一次巡查', 100, '', 0, '城市生命线监测的日常过程。', '责任单位：市城管局；所属业务分类编号：28；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:55:00', '1', '2026-09-03 15:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (137, 28, '设施病害上报', 'MUNI_DEFECT', '发现坑槽、沉陷、井盖缺失、灯具熄灭等病害并建单。', '病害可定位到部件或路段。', '工单生成并派发养护单位。', '一条设施病害工单', 100, '', 0, '与网格事件可对账，城管部件类以本过程为准。', '责任单位：市城管局；所属业务分类编号：28；建模用途：DWD 明细事实过程。', '1', '2026-09-03 15:58:00', '1', '2026-09-03 15:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (138, 28, '维修养护处置', 'MUNI_REPAIR', '养护单位按工单完成维修并回传影像和工程量。', '工单已签收。', '验收合格后销号。', '一条养护工单的一次处置', 100, '', 0, '设施完好率和处置时效分析基础。', '责任单位：市城管局；所属业务分类编号：28；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:01:00', '1', '2026-09-03 16:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (139, 28, '环卫作业考核', 'MUNI_SANITATION', '对道路清扫、垃圾收运和公厕管护进行日常考核。', '作业合同和作业路段明确，考核周期到达。', '考核得分入库并关联经费拨付。', '一个作业标段一个考核周期的考核', 100, '', 0, '城市运行主题。', '责任单位：市城管局；所属业务分类编号：28；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:04:00', '1', '2026-09-03 16:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (140, 28, '供水管网监测告警', 'MUNI_WATER', '对压力、流量和漏损异常进行告警确认和派单。', '监测点超阈值且持续达到告警规则。', '告警确认并生成抢修单或误报关闭。', '一个监测点一次告警事件', 100, '', 0, '生命线实时过程，粒度到告警编号。', '责任单位：市城管局；所属业务分类编号：28；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:07:00', '1', '2026-09-03 16:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (141, 28, '地下管线事故处置', 'MUNI_PIPELINE', '对燃气、供水、排水管线泄漏或破损开展应急抢修。', '接报属实并启动应急。', '险情排除，事故报告归档。', '一起管线事故处置', 100, '', 0, '可升级为突发事件对接应急过程。', '责任单位：市城管局；所属业务分类编号：28；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:10:00', '1', '2026-09-03 16:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (142, 30, '公交线路审批', 'BUS_ROUTE', '对公交（轨道接驳）线路开行、调整和终止进行审批。', '线网规划和客流论证完成。', '线路批复生效并更新线网站点。', '一条线路一次审批', 100, '', 0, '公共交通运行主题的线网主数据过程。', '责任单位：市交通运输局；所属业务分类编号：30；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:13:00', '1', '2026-09-03 16:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (143, 30, '车辆运营调度', 'BUS_DISPATCH', '按计划发车并对大间隔、串车进行实时调度。', '线路当日运营计划生效。', '调度指令执行并回传到位。', '一个车次一次调度指令', 100, '', 0, '准点率和运力投放分析基础。', '责任单位：市交通运输局；所属业务分类编号：30；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:16:00', '1', '2026-09-03 16:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (144, 30, '客流采集统计', 'BUS_RIDERSHIP', '通过刷卡、码票和客流仪汇总站点、线路客流。', '运营日结束或实时窗口到达。', '客流指标入库。', '一条线路一个统计周期的客流汇总', 100, '', 0, '明细刷卡属人口敏感，主题层用汇总。', '责任单位：市交通运输局；所属业务分类编号：30；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:19:00', '1', '2026-09-03 16:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (145, 30, '公交站点设置', 'BUS_STOP', '办理站点新增、迁移和撤销并更新空间坐标。', '现场踏勘和交通组织方案通过。', '站点生效并同步电子站牌。', '一个站点一次设置（调整）', 100, '', 0, '覆盖率和步行可达分析基础。', '责任单位：市交通运输局；所属业务分类编号：30；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:22:00', '1', '2026-09-03 16:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (146, 30, '运营服务考核', 'BUS_EVALUATE', '对运营企业准点、投诉、安全和里程完成情况进行考核。', '考核周期结束，运营数据已齐。', '考核结果确认并用于补贴清算。', '一家企业一个考核周期的服务考核', 100, '', 0, '财政补贴和行业监管依据。', '责任单位：市交通运输局；所属业务分类编号：30；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:25:00', '1', '2026-09-03 16:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (147, 30, '新能源车辆更新', 'BUS_FLEET', '办理新能源公交车更新、报废和充电设施配套验收。', '更新计划获批，车辆达标。', '车辆入籍运营或退出。', '一辆车一次更新（退出）登记', 100, '', 0, '绿色交通和资产台账过程。', '责任单位：市交通运输局；所属业务分类编号：30；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:28:00', '1', '2026-09-03 16:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (148, 31, '道路运输经营许可', 'ROAD_LICENSE', '对道路客运、普通货运、危货运输企业核发经营许可。', '企业具备安全制度和车辆、人员条件。', '许可决定作出并制发证件。', '一家企业一次道路运输许可', 100, '', 0, '法人与交通运输交叉过程。', '责任单位：市交通运输局；所属业务分类编号：31；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:31:00', '1', '2026-09-03 16:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (149, 31, '营运车辆年度审验', 'ROAD_VEHICLE', '对道路运输车辆进行年度审验和技术等级评定。', '车辆在册且保险、检测有效。', '审验结论出具，不合格责令停运。', '一辆营运车辆一次年审', 100, '', 0, '运输安全基础过程。', '责任单位：市交通运输局；所属业务分类编号：31；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:34:00', '1', '2026-09-03 16:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (150, 31, '从业人员资格注册', 'ROAD_STAFF', '对客运驾驶员、危货押运员等从业资格进行注册和继续教育。', '考试合格或继续教育课时达标。', '资格有效并关联企业。', '一名从业人员一次资格注册（继续教育）', 100, '', 0, '人车户一致性监管基础。', '责任单位：市交通运输局；所属业务分类编号：31；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:37:00', '1', '2026-09-03 16:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (151, 31, '客运班线审批', 'ROAD_PASSENGER', '对省际、市际、县际客运班线开行和调整审批。', '运力投放符合规划，站点方案明确。', '班线许可生效。', '一条班线一次审批', 100, '', 0, '与公交线路分区：本过程为道路客运。', '责任单位：市交通运输局；所属业务分类编号：31；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:40:00', '1', '2026-09-03 16:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (152, 31, '货运源头监管', 'ROAD_FREIGHT', '对矿山、商砼、港口等货运源头装载和超限进行检查。', '源头企业在监管名录。', '检查结果入库，违法线索移送执法。', '一个源头企业一次检查', 100, '', 0, '治超和交通安全交叉过程。', '责任单位：市交通运输局；所属业务分类编号：31；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:43:00', '1', '2026-09-03 16:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (153, 31, '道路运输违法查处', 'ROAD_VIOLATE', '对非法营运、超限超载等实施处罚。', '证据固定且符合立案标准。', '处罚决定生效。', '一起道路运输违法案件的处罚决定', 100, '', 0, '可与综合执法案件对账，按行业案由区分。', '责任单位：市交通运输局；所属业务分类编号：31；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:46:00', '1', '2026-09-03 16:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (154, 32, '路网拥堵监测', 'TRAF_CONGESTION', '按路段计算行程速度、拥堵指数并发布预警。', '检测器或浮动车数据完整。', '拥堵事件生成或指标快照入库。', '一个路段一个统计时段的拥堵监测', 100, '', 0, '路网运行监测主题核心过程。', '责任单位：市交通运输局、市城管局；所属业务分类编号：32；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:49:00', '1', '2026-09-03 16:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (155, 32, '交通事件接报', 'TRAF_INCIDENT', '接报事故、施工占道和设备故障等影响通行的事件。', '事件位置可定位。', '事件建单并通知处置力量。', '一起交通运行事件接报', 100, '', 0, '与应急突发事件衔接，一般拥堵不升级。', '责任单位：市交通运输局、市城管局；所属业务分类编号：32；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:52:00', '1', '2026-09-03 16:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (156, 32, '缓堵措施调度', 'TRAF_MITIGATE', '对持续拥堵路段采取信号优化、临时管制或公交加车。', '拥堵达到调度阈值。', '措施执行并评估缓解效果。', '一次缓堵调度动作', 100, '', 0, '效果评估需关联拥堵监测快照。', '责任单位：市交通运输局、市城管局；所属业务分类编号：32；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:55:00', '1', '2026-09-03 16:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (157, 32, '停车泊位备案', 'PARK_BERTH', '对路内泊位、公共停车场泊位编号、类型和收费标准备案。', '权属和施划方案通过。', '泊位进入停车资源库。', '一个泊位一次备案（调整）', 100, '', 0, '停车资源治理主数据过程。', '责任单位：市交通运输局、市城管局；所属业务分类编号：32；建模用途：DWD 明细事实过程。', '1', '2026-09-03 16:58:00', '1', '2026-09-03 16:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (158, 32, '停车场经营许可', 'PARK_LICENSE', '对经营性停车场办理备案或许可。', '场地消防、进出口和收费系统达标。', '许可（备案）完成。', '一个停车场一次经营许可', 100, '', 0, '与泊位备案区分：本过程对经营主体。', '责任单位：市交通运输局、市城管局；所属业务分类编号：32；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:01:00', '1', '2026-09-03 17:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (159, 32, '违法停车查处', 'PARK_ILLEGAL', '对违法停放进行抓拍、抄告或拖车处置。', '违法事实清楚，设备检定有效。', '违法记录生效并进入处罚。', '一起违法停车记录', 100, '', 0, '城管与交管数据需按执法主体去重。', '责任单位：市交通运输局、市城管局；所属业务分类编号：32；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:04:00', '1', '2026-09-03 17:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (160, 34, '环境空气质量监测', 'ENV_AIR', '国控、省控和市控站产出空气质量指数和六参数。', '监测仪器质控合格，小时数据完整。', '有效监测数据入库并参与评价。', '一个站点一个小时的空气质量监测', 100, '', 0, '蓝天保卫主题基础事实。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:07:00', '1', '2026-09-03 17:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (161, 34, '污染源在线监测', 'ENV_SOURCE', '重点排污单位在线监控烟气、废水排放数据。', '监控设备验收合格并联网。', '有效数据包入库，异常触发预警。', '一家排污单位一个监测因子一个小时的在线监测', 100, '', 0, '与手工监测对标，超标不直接等于处罚。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:10:00', '1', '2026-09-03 17:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (162, 34, '排污许可核发', 'ENV_PERMIT', '对固定污染源核发、变更或注销排污许可证。', '环评和达标可行性材料齐全。', '许可证签发并明确排放口和许可量。', '一家单位一次排污许可决定', 100, '', 0, '环境执法和固废管理的许可基准。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:13:00', '1', '2026-09-03 17:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (163, 34, '地表水断面监测', 'ENV_WATER', '对考核断面、饮用水源地开展水质采样和评价。', '监测断面在名录，采样符合规范。', '水质类别评定入库。', '一个断面一次水质监测', 100, '', 0, '碧水治理主题基础事实。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:16:00', '1', '2026-09-03 17:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (164, 34, '环境违法查处', 'ENV_ENFORCE', '对超标排放、自动监测弄虚作假等立案处罚。', '证据固定且符合环境违法立案标准。', '处罚决定送达并公开。', '一起环境违法案件的处罚决定', 100, '', 0, '与市场监管处罚分区，案由属生态环境。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:19:00', '1', '2026-09-03 17:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (165, 34, '重污染天气应急响应', 'ENV_HEAVY_POLLUTION', '根据预警级别启动停限产、工地停工和管控清单。', '达到重污染天气预警条件。', '响应启动或解除，企业执行反馈入库。', '一次重污染天气应急响应（含企业执行反馈）', 100, '', 0, '响应批次与企业执行应分表，本过程记录响应批次主事实。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:22:00', '1', '2026-09-03 17:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (166, 34, '入河排污口整治', 'ENV_OUTFALL', '对入河排污口开展排查、监测、溯源和整治销号。', '排污口已编码上图。', '整治完成验收或依法封堵。', '一个排污口一次整治销号', 100, '', 0, '碧水治理场景过程。', '责任单位：市生态环境局、市水利局；所属业务分类编号：34；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:25:00', '1', '2026-09-03 17:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (167, 35, '土壤污染调查', 'WASTE_SOIL', '对建设用地和农用地开展土壤污染状况调查与评审。', '地块列入调查名录或出让前依法应调查。', '调查报告评审通过并确定风险等级。', '一个地块一次土壤污染调查', 100, '', 0, '出让和规划许可的前置过程。', '责任单位：市生态环境局；所属业务分类编号：35；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:28:00', '1', '2026-09-03 17:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (168, 35, '危险废物转移联单', 'WASTE_HAZARD', '产废单位转移危险废物时运行电子联单。', '转移计划和经营许可有效。', '接收单位签收，联单闭环。', '一份危险废物转移联单', 100, '', 0, '固废与低碳主题核心监管事实。', '责任单位：市生态环境局；所属业务分类编号：35；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:31:00', '1', '2026-09-03 17:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (169, 35, '生活垃圾收运', 'WASTE_MSW', '记录生活垃圾从收集点到处理厂的收运量和去向。', '收运线路和处置设施有效。', '过磅数据入库并对账。', '一个收运车次一次过磅', 100, '', 0, '用于收运量和处置能力分析。', '责任单位：市生态环境局；所属业务分类编号：35；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:34:00', '1', '2026-09-03 17:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (170, 35, '固体废物处置入库', 'WASTE_DISPOSE', '填埋、焚烧或综合利用设施接收废物并计量。', '废物类别与设施许可范围匹配。', '入库计量完成。', '一个处置设施一车（一批）废物入库', 100, '', 0, '与危废联单对账，一般固废单独计量。', '责任单位：市生态环境局；所属业务分类编号：35；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:37:00', '1', '2026-09-03 17:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (171, 35, '土壤修复验收', 'WASTE_REMEDIATE', '对污染地块修复效果进行评估验收。', '修复方案实施完毕。', '验收意见出具，地块可安全利用或继续管控。', '一个地块一次修复验收', 100, '', 0, '调查—修复闭环终点。', '责任单位：市生态环境局；所属业务分类编号：35；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:40:00', '1', '2026-09-03 17:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (172, 35, '生活垃圾分类考核', 'WASTE_SORT', '对居民小区、单位分类质量进行抽查考核。', '考核周期到达，样本点抽取完成。', '考核结果反馈并纳入街道评价。', '一个投放点一个考核周期的分类考核', 100, '', 0, '城市运行与固废交叉过程。', '责任单位：市生态环境局；所属业务分类编号：35；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:43:00', '1', '2026-09-03 17:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (173, 36, '生态保护红线监管', 'ECO_REDLINE', '对红线内新增建设、采矿和违法占用进行监测预警。', '遥感或巡查发现疑似变化图斑。', '图斑核查办结，违法线索移交。', '一个图斑一次红线核查', 100, '', 0, '生态文明和规划实施交叉过程。', '责任单位：市生态环境局、市自然资源和规划局；所属业务分类编号：36；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:46:00', '1', '2026-09-03 17:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (174, 36, '自然保护地巡护', 'ECO_RESERVE', '对自然保护区、湿地公园等开展巡护和人类活动监测。', '巡护路线和保护地边界有效。', '巡护记录入库，问题转执法。', '一条巡护路线一次巡护', 100, '', 0, '生物多样性保护日常过程。', '责任单位：市生态环境局、市自然资源和规划局；所属业务分类编号：36；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:49:00', '1', '2026-09-03 17:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (175, 36, '生态修复项目实施', 'ECO_RESTORE', '对矿山、岸线、湿地等生态修复项目登记进度和验收。', '项目已立项并具备施工条件。', '阶段验收或竣工验收完成。', '一个生态修复项目一次进度（验收）登记', 100, '', 0, '可关联投资项目库，避免双头立项。', '责任单位：市生态环境局、市自然资源和规划局；所属业务分类编号：36；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:52:00', '1', '2026-09-03 17:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (176, 36, '生物多样性监测', 'ECO_BIODIV', '布设样方或红外相机监测物种和栖息地变化。', '监测方案获批，样地坐标固定。', '监测数据质控入库。', '一个样地一个监测轮次', 100, '', 0, '长期序列，禁止随意变更样地编号。', '责任单位：市生态环境局、市自然资源和规划局；所属业务分类编号：36；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:55:00', '1', '2026-09-03 17:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (177, 36, '林草湿资源调查', 'ECO_FOREST', '开展森林、草原、湿地资源调查和变更调查。', '调查年度任务下达。', '调查成果评审入库。', '一个小班（图斑）一次资源调查', 100, '', 0, '自然资源数据域更新过程。', '责任单位：市生态环境局、市自然资源和规划局；所属业务分类编号：36；建模用途：DWD 明细事实过程。', '1', '2026-09-03 17:58:00', '1', '2026-09-03 17:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (178, 38, '种植面积核实', 'AGRI_PLANT', '对粮食和经济作物播种面积进行遥感加实地核实。', '播种季到达，地块在耕地资源库中。', '核实面积入库并用于补贴测算。', '一个地块一个作物季的面积核实', 100, '', 0, '农业生产监测主题基础事实。', '责任单位：市农业农村局；所属业务分类编号：38；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:01:00', '1', '2026-09-03 18:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (179, 38, '畜禽养殖备案', 'AGRI_LIVESTOCK', '对规模养殖场办理备案、变更和关停。', '选址符合禁养区规定。', '备案完成并纳入粪污监管。', '一个养殖场一次备案', 100, '', 0, '与环保排污许可衔接。', '责任单位：市农业农村局；所属业务分类编号：38；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:04:00', '1', '2026-09-03 18:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (180, 38, '农机作业补贴申报', 'AGRI_MACHINERY', '对深松、收割等作业量申报补贴并抽查核验。', '作业轨迹和面积可核验。', '补贴审核通过并进入兑付。', '一户（一主体）一次作业补贴申报', 100, '', 0, '财政资金过程，需保留抽查比例。', '责任单位：市农业农村局；所属业务分类编号：38；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:07:00', '1', '2026-09-03 18:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (181, 38, '农资经营监管', 'AGRI_INPUT', '对农药、肥料、种子经营主体开展检查和台账抽查。', '主体在农资经营名录。', '检查结果入库，问题产品追溯。', '一家农资经营店一次检查', 100, '', 0, '与市场监管检查分区：本过程侧重农业投入品。', '责任单位：市农业农村局；所属业务分类编号：38；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:10:00', '1', '2026-09-03 18:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (182, 38, '农业气象灾害预警', 'AGRI_WEATHER', '针对农时发布低温、干旱、风雹等农业气象预警。', '气象条件达到农业致灾指标。', '预警发布并通知乡镇和经营主体。', '一次农业气象灾害预警发布', 100, '', 0, '与自然灾害防御预警衔接，本过程面向农业生产。', '责任单位：市农业农村局；所属业务分类编号：38；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:13:00', '1', '2026-09-03 18:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (183, 38, '农业生产调度填报', 'AGRI_DISPATCH', '乡镇填报春耕、夏收、秋收进度和农资供需。', '调度周期到达。', '进度审核入库。', '一个乡镇一个调度周期的生产进度', 100, '', 0, '季节性过程，口径按农时方案执行。', '责任单位：市农业农村局；所属业务分类编号：38；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:16:00', '1', '2026-09-03 18:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (184, 39, '农产品监督抽检', 'AQ_SAMPLE', '对产地和市场上的农产品进行农药兽残等抽检。', '抽检计划获批，样品可溯源。', '检测结论出具，不合格转入处置。', '一个样品一次农产品抽检', 100, '', 0, '与产品质量抽检分区：本过程对象为食用农产品。', '责任单位：市农业农村局、市市场监督管理局；所属业务分类编号：39；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:19:00', '1', '2026-09-03 18:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (185, 39, '产地准出开具', 'AQ_ORIGIN', '对达标农产品开具承诺达标合格证或准出凭证。', '生产主体纳入名录，检测或承诺符合要求。', '合格证赋码生效。', '一批农产品一次产地准出', 100, '', 0, '质量追溯的源头过程。', '责任单位：市农业农村局、市市场监督管理局；所属业务分类编号：39；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:22:00', '1', '2026-09-03 18:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (186, 39, '质量追溯赋码', 'AQ_TRACE', '为生产主体和产品批次赋予追溯码并采集农事记录。', '主体已备案，批次信息完整。', '赋码完成，扫码可查询。', '一个产品批次一次赋码', 100, '', 0, '对接市场监管食品追溯。', '责任单位：市农业农村局、市市场监督管理局；所属业务分类编号：39；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:25:00', '1', '2026-09-03 18:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (187, 39, '不合格农产品处置', 'AQ_UNQUALIFIED', '对抽检不合格农产品进行召回、无害化处理和处罚移送。', '不合格结论生效。', '处置闭环，产品不得流入市场。', '一个不合格批次一次处置', 100, '', 0, '与抽检成对。', '责任单位：市农业农村局、市市场监督管理局；所属业务分类编号：39；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:28:00', '1', '2026-09-03 18:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (188, 39, '检测机构考核', 'AQ_LAB', '对农产品质检机构能力验证和考核。', '机构在名录且考核年度到达。', '考核结论入库。', '一家检测机构一个年度的考核', 100, '', 0, '保证抽检数据可信。', '责任单位：市农业农村局、市市场监督管理局；所属业务分类编号：39；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:31:00', '1', '2026-09-03 18:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (190, 40, '村级集体资产登记', 'RURAL_ASSET', '对农村集体资金、资产、资源进行清查登记和变动备案。', '清查任务下达或发生产权变动。', '资产卡片生效并纳入三资平台。', '一项集体资产一次登记（变动）', 100, '', 0, '农村集体经济主题主数据过程。', '责任单位：市农业农村局；所属业务分类编号：40；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:37:00', '1', '2026-09-03 18:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (191, 40, '乡村建设项目验收', 'RURAL_PROJECT', '对村内道路、供水、公共服务设施等建设项目验收。', '建设内容完成，资金使用合规。', '验收合格并移交管护。', '一个乡村建设项目一次验收', 100, '', 0, '可关联投资项目，避免重复入库。', '责任单位：市农业农村局；所属业务分类编号：40；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:40:00', '1', '2026-09-03 18:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (192, 40, '农村改厕销号', 'RURAL_TOILET', '对户厕改造完工、验收和问题整改销号。', '改造对象在年度任务清单。', '验收合格销号。', '一户一次改厕验收销号', 100, '', 0, '人居环境标志性过程，按户计件。', '责任单位：市农业农村局；所属业务分类编号：40；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:43:00', '1', '2026-09-03 18:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (193, 40, '村民议事决策', 'RURAL_GOVERN', '记录村民会议、村民代表会议对重大事项的议事表决。', '议题属于四议两公开范围。', '决议形成并公开。', '一个村一次议事决策', 100, '', 0, '乡村治理过程，不采集投票人明细入仓。', '责任单位：市农业农村局；所属业务分类编号：40；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:46:00', '1', '2026-09-03 18:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (194, 40, '高标准农田建设验收', 'RURAL_FARMLAND', '对高标准农田建设任务进行竣工验收和上图入库。', '建设任务完成，质量抽检合格。', '验收通过并更新耕地资源。', '一个建设单元一次竣工验收', 100, '', 0, '农业生产和自然资源交叉过程。', '责任单位：市农业农村局；所属业务分类编号：40；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:49:00', '1', '2026-09-03 18:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (195, 42, '公共文化活动举办', 'CULT_ACTIVITY', '图书馆、文化馆、乡镇综合文化站举办公益文化活动。', '活动方案审核通过并完成场地预约。', '活动结束，参与人次和影像归档。', '一场公共文化活动', 100, '', 0, '公共文体服务主题过程。', '责任单位：市文化旅游局；所属业务分类编号：42；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:52:00', '1', '2026-09-03 18:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (196, 42, '公共图书借阅', 'CULT_LIBRARY', '读者借阅、续借和归还公共图书。', '读者证有效，馆藏可借。', '借还事务完成。', '一条借阅事务', 100, '', 0, '明细含读者属敏感，主题层用汇总。', '责任单位：市文化旅游局；所属业务分类编号：42；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:55:00', '1', '2026-09-03 18:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (197, 42, '文物保护单位巡查', 'CULT_RELIC', '对不可移动文物进行定期巡查和险情登记。', '文物在保护名录，巡查周期到达。', '巡查记录入库，险情转修缮。', '一处文物保护单位一次巡查', 100, '', 0, '安全与文保交叉过程。', '责任单位：市文化旅游局；所属业务分类编号：42；建模用途：DWD 明细事实过程。', '1', '2026-09-03 18:58:00', '1', '2026-09-03 18:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (198, 42, '文化场馆开放服务', 'CULT_VENUE', '记录博物馆、文化馆等场馆开放时长和接待人次。', '开放日计划生效。', '当日开放数据入库。', '一个场馆一个开放日的服务统计', 100, '', 0, '设施利用率分析基础。', '责任单位：市文化旅游局；所属业务分类编号：42；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:01:00', '1', '2026-09-03 19:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (199, 42, '非物质文化遗产申报', 'CULT_ICH', '对非遗项目和代表性传承人进行申报评审和名录管理。', '申报材料符合批次要求。', '评审结果公布并更新名录。', '一个非遗项目（传承人）一次申报评审', 100, '', 0, '名录主数据过程。', '责任单位：市文化旅游局；所属业务分类编号：42；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:04:00', '1', '2026-09-03 19:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (200, 43, '景区接待统计', 'TOUR_SCENIC', 'A 级景区按日上报接待人次、收入和最大承载预警。', '统计日结束或实时达到预警阈值。', '接待数据入库，超载启动分流。', '一个景区一个统计日的接待', 100, '', 0, '文旅游客分析基础。', '责任单位：市文化旅游局；所属业务分类编号：43；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:07:00', '1', '2026-09-03 19:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (201, 43, '旅行社经营许可', 'TOUR_AGENCY', '对旅行社设立、变更和注销许可。', '质量保证金和人员条件符合规定。', '许可决定生效。', '一家旅行社一次许可决定', 100, '', 0, '文旅市场主体过程。', '责任单位：市文化旅游局；所属业务分类编号：43；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:10:00', '1', '2026-09-03 19:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (202, 43, '饭店等级评定', 'TOUR_HOTEL', '对旅游饭店、民宿开展等级评定和复核。', '申报材料齐全，现场检查完成。', '等级公布或取消。', '一家住宿单位一次等级评定', 100, '', 0, '文旅消费分析的供给质量过程。', '责任单位：市文化旅游局；所属业务分类编号：43；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:13:00', '1', '2026-09-03 19:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (203, 43, '文旅投诉处理', 'TOUR_COMPLAINT', '处理游客对景区、旅行社、饭店的投诉并回访。', '投诉属于文旅市场监管范围。', '处理完毕并回访。', '一件文旅投诉办理', 100, '', 0, '可与 12345 对账，行业办理以本过程为准。', '责任单位：市文化旅游局；所属业务分类编号：43；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:16:00', '1', '2026-09-03 19:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (204, 43, '导游执业注册', 'TOUR_GUIDE', '办理导游证注册、变更和年审。', '资格考试合格或继续教育达标。', '执业注册生效。', '一名导游一次执业注册（年审）', 100, '', 0, '从业人员监管过程。', '责任单位：市文化旅游局；所属业务分类编号：43；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:19:00', '1', '2026-09-03 19:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (205, 43, '旅游市场执法', 'TOUR_ENFORCE', '对不合理低价游、强迫消费等实施检查和处罚。', '线索成立且属于文旅执法事项。', '检查或处罚决定生效。', '一起旅游市场执法案件（检查）', 100, '', 0, '与市场监管综合执法按职责分工。', '责任单位：市文化旅游局；所属业务分类编号：43；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:22:00', '1', '2026-09-03 19:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (206, 44, '公共体育场馆开放', 'SPORT_VENUE', '记录公共体育场馆免费或低收费开放场次和人次。', '开放计划生效。', '当日开放数据入库。', '一个场馆一个开放日的开放服务', 100, '', 0, '公共文体服务主题。', '责任单位：市教育体育局；所属业务分类编号：44；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:25:00', '1', '2026-09-03 19:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (207, 44, '全民健身活动举办', 'SPORT_FITNESS', '组织社区运动会、健身走等全民健身活动。', '活动备案通过。', '活动结束并统计参与人次。', '一场全民健身活动', 100, '', 0, '与文化活动分区：本过程由体育部门主办。', '责任单位：市教育体育局；所属业务分类编号：44；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:28:00', '1', '2026-09-03 19:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (208, 44, '体育赛事活动审批', 'SPORT_EVENT', '对高危险性体育赛事或大型赛事进行审批备案。', '组织方案、医疗和安全预案齐全。', '审批（备案）完成。', '一项赛事一次审批备案', 100, '', 0, '大型赛事需对接应急和交通保障。', '责任单位：市教育体育局；所属业务分类编号：44；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:31:00', '1', '2026-09-03 19:31:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (209, 44, '体育社会组织登记', 'SPORT_ORG', '对体育协会、俱乐部办理登记和年检（协同民政）。', '章程和负责人符合规定。', '登记或年检完成。', '一个体育社会组织一次登记（年检）', 100, '', 0, '法人单位中的社会组织切片。', '责任单位：市教育体育局；所属业务分类编号：44；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:34:00', '1', '2026-09-03 19:34:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (210, 44, '健身设施维护', 'SPORT_FACILITY', '对社区健身路径、球场进行巡检和报修。', '设施已入库并挂接位置。', '维护完成或报废更新。', '一套健身设施一次维护工单', 100, '', 0, '城市运行和文体交叉过程。', '责任单位：市教育体育局；所属业务分类编号：44；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:37:00', '1', '2026-09-03 19:37:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (211, 46, '企业安全风险分级管控', 'SAFE_RISK', '生产经营单位辨识风险并确定风险等级和管控措施。', '企业在安全监管名录，双重预防机制任务下达。', '风险清单审核入库。', '一家企业一套风险分级清单的一次更新', 100, '', 0, '安全生产风险主题主过程。', '责任单位：市应急管理局；所属业务分类编号：46；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:40:00', '1', '2026-09-03 19:40:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (212, 46, '重大危险源备案', 'SAFE_HAZARD', '对构成重大危险源的罐区、库区等备案和核销。', '辨识达到重大危险源标准。', '备案完成并纳入在线监测。', '一个重大危险源一次备案', 100, '', 0, '应急资源调度的重点对象。', '责任单位：市应急管理局；所属业务分类编号：46；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:43:00', '1', '2026-09-03 19:43:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (213, 46, '生产安全隐患排查', 'SAFE_HIDDEN', '企业自查或监管部门检查发现隐患并下达整改。', '隐患描述、部位和整改时限明确。', '整改复查合格或升级查处。', '一条生产安全隐患的一次排查整改', 100, '', 0, '与网格隐患分区：本过程对象为生产经营单位。', '责任单位：市应急管理局；所属业务分类编号：46；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:46:00', '1', '2026-09-03 19:46:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (214, 46, '生产安全事故报告', 'SAFE_ACCIDENT', '发生生产安全事故后按级别时限上报并续报。', '事故达到报告标准。', '报告审核入库，应急响应按需启动。', '一起生产安全事故的一次报告（续报）', 100, '', 0, '事故编号全市唯一，续报不新开事故。', '责任单位：市应急管理局；所属业务分类编号：46；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:49:00', '1', '2026-09-03 19:49:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (215, 46, '应急预案备案', 'SAFE_PLAN', '对生产经营单位生产安全事故应急预案进行评审备案。', '预案要素符合编制导则。', '备案完成并纳入预案库。', '一家企业一套预案一次备案', 100, '', 0, '应急资源调度的预案来源。', '责任单位：市应急管理局；所属业务分类编号：46；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:52:00', '1', '2026-09-03 19:52:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (216, 46, '安全生产执法处罚', 'SAFE_ENFORCE', '对未履行主体责任、隐患逾期未改等实施行政处罚。', '违法事实清楚，权利告知完成。', '处罚决定送达并公示。', '一起安全生产违法案件的处罚决定', 100, '', 0, '与综合执法案件按职责分工。', '责任单位：市应急管理局；所属业务分类编号：46；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:55:00', '1', '2026-09-03 19:55:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (217, 47, '气象灾害预警发布', 'DIS_WEATHER', '发布暴雨、大风、冰雹、高温、寒潮等气象灾害预警。', '监测实况或预报达到预警级别。', '预警签发并通达应急、水利、农业和媒体。', '一次气象灾害预警发布', 100, '', 0, '自然灾害预警主题权威过程。', '责任单位：市应急管理局、市水利局、市气象局；所属业务分类编号：47；建模用途：DWD 明细事实过程。', '1', '2026-09-03 19:58:00', '1', '2026-09-03 19:58:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (218, 47, '洪水预报发布', 'DIS_FLOOD', '对主要河道、水库发布洪水预报和调度建议。', '降雨和水位达到预报作业条件。', '预报产品发布并更新调度方案。', '一个预报断面一次洪水预报', 100, '', 0, '与气象预警衔接，本过程由水利水文业务产生。', '责任单位：市应急管理局、市水利局、市气象局；所属业务分类编号：47；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:01:00', '1', '2026-09-03 20:01:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (219, 47, '地质灾害隐患排查', 'DIS_GEO', '对滑坡、崩塌、泥石流隐患点开展巡查和监测。', '隐患点在库，巡查频次按风险等级执行。', '巡查记录入库，高风险点转移避让。', '一个隐患点一次排查', 100, '', 0, '时空地理与应急交叉过程。', '责任单位：市应急管理局、市水利局、市气象局；所属业务分类编号：47；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:04:00', '1', '2026-09-03 20:04:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (220, 47, '森林火险监测', 'DIS_FIRE', '根据气象火险等级和卫星热点开展森林草原火险监测。', '防火期开始或热点报警。', '火险等级发布或热点核查办结。', '一个监测区一次火险（热点）监测', 100, '', 0, '可升级为突发事件。', '责任单位：市应急管理局、市水利局、市气象局；所属业务分类编号：47；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:07:00', '1', '2026-09-03 20:07:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (221, 47, '自然灾害应急响应启动', 'DIS_RESPONSE', '按预案启动防汛抗旱、地质灾害或森林防火应急响应。', '灾情或预警达到响应级别。', '响应命令签发，责任体系进入战时状态。', '一次自然灾害应急响应启动（调整、解除）', 100, '', 0, '与事故类应急响应共用事件编号规则。', '责任单位：市应急管理局、市水利局、市气象局；所属业务分类编号：47；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:10:00', '1', '2026-09-03 20:10:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (222, 47, '灾情统计上报', 'DIS_REPORT', '统计因灾倒损房屋、受灾人口和直接经济损失并逐级上报。', '灾情稳定或达到续报节点。', '灾情报表审核入库。', '一个统计单元一次灾情上报', 100, '', 0, '用于救助和恢复重建，口径按国家灾情统计制度。', '责任单位：市应急管理局、市水利局、市气象局；所属业务分类编号：47；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:13:00', '1', '2026-09-03 20:13:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (223, 48, '突发事件接报', 'EMR_RECEIVE', '应急指挥中心接收事故灾难、自然灾害和社会安全事件接报。', '事发信息可定位且达到突发事件标准。', '事件建档并分级，通知相关力量。', '一起突发事件一次接报', 100, '', 0, '应急资源调度和城市事件升级入口。', '责任单位：市应急管理局、市消防救援部门；所属业务分类编号：48；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:16:00', '1', '2026-09-03 20:16:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (224, 48, '应急响应启动', 'EMR_RESPONSE', '按事件等级启动市级或县级应急响应并成立指挥部。', '事件等级研判完成。', '响应命令生效，组织体系到位。', '一起事件一次响应启动（调整、终止）', 100, '', 0, '与自然灾害响应可共用，按事件类型区分。', '责任单位：市应急管理局、市消防救援部门；所属业务分类编号：48；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:19:00', '1', '2026-09-03 20:19:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (225, 48, '救援力量调度', 'EMR_DISPATCH', '调度消防、专业救援、物资和避难场所。', '响应已启动，资源需求明确。', '力量到位或改派。', '一次救援力量（物资）调度指令', 100, '', 0, '应急资源调度主题核心事实。', '责任单位：市应急管理局、市消防救援部门；所属业务分类编号：48；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:22:00', '1', '2026-09-03 20:22:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (226, 48, '现场处置反馈', 'EMR_HANDLE', '现场指挥部反馈搜救、疏散、管控和次生风险。', '力量已到场。', '阶段态势更新入库。', '一起事件一次现场态势反馈', 100, '', 0, '用于指挥协同，不替代事故调查报告。', '责任单位：市应急管理局、市消防救援部门；所属业务分类编号：48；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:25:00', '1', '2026-09-03 20:25:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (227, 48, '消防监督检查', 'EMR_FIRE_CHECK', '对人员密集场所、高层建筑和重点单位开展消防检查。', '检查计划下达或举报线索成立。', '检查意见送达，重大隐患挂牌。', '一个单位一次消防监督检查', 100, '', 0, '公共安全日常过程。', '责任单位：市应急管理局、市消防救援部门；所属业务分类编号：48；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:28:00', '1', '2026-09-03 20:28:00', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_business_process" VALUES (228, 48, '应急复盘评估', 'EMR_REVIEW', '事件结束后组织复盘，评估响应时效、资源短板和改进事项。', '应急响应已终止，调查材料基本齐。', '复盘报告审定并形成整改清单。', '一起事件一次复盘评估', 100, '', 0, '闭环终点，整改事项转入督查任务。', '责任单位：市应急管理局、市消防救援部门；所属业务分类编号：48；建模用途：DWD 明细事实过程。', '1', '2026-09-03 20:31:00', '1', '2026-09-03 20:31:00', 0, 1);

-- ----------------------------
-- 表结构： dh_modeling_concept_entity
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_concept_entity";
CREATE TABLE "datahub-center"."dh_modeling_concept_entity" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_concept_entity_seq'::regclass),
  "model_id" int8 NOT NULL,
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "code" varchar(64) COLLATE "pg_catalog"."default",
  "description" varchar(500) COLLATE "pg_catalog"."default",
  "attrs" jsonb,
  "pos_x" int4 NOT NULL DEFAULT 0,
  "pos_y" int4 NOT NULL DEFAULT 0,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."model_id" IS '所属概念模型编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."name" IS '实体名称';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."code" IS '实体编码';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."attrs" IS '属性定义 JSON：[{name,code,primaryFlag,description,sort}]';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."pos_x" IS '画布横坐标';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."pos_y" IS '画布纵坐标';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."update_time" IS '最后更新时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."deleted" IS '逻辑删除标识：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_modeling_concept_entity"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."dh_modeling_concept_entity" IS '数据建模-概念实体';

-- ----------------------------
-- 数据记录： dh_modeling_concept_entity
-- ----------------------------

-- ----------------------------
-- 表结构： dh_modeling_concept_logic_sync
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_concept_logic_sync";
CREATE TABLE "datahub-center"."dh_modeling_concept_logic_sync" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_concept_logic_sync_seq'::regclass),
  "logic_model_id" int8 NOT NULL,
  "concept_model_id" int8 NOT NULL,
  "concept_entity_id" int8 NOT NULL,
  "source_version" int4 NOT NULL DEFAULT 0,
  "baseline" jsonb,
  "pending_count" int4 NOT NULL DEFAULT 0,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
