-- ----------------------------
-- 表结构： dh_modeling_deploy_record
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_deploy_record";
CREATE TABLE "datahub-center"."dh_modeling_deploy_record" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_deploy_record_seq'::regclass),
  "model_id" int8 NOT NULL,
  "version_id" int8 NOT NULL,
  "version_no" int4,
  "database_id" int8,
  "datasource_name" varchar(100) COLLATE "pg_catalog"."default",
  "table_name" varchar(128) COLLATE "pg_catalog"."default",
  "request_key" varchar(64) COLLATE "pg_catalog"."default",
  "deploy_action" varchar(32) COLLATE "pg_catalog"."default",
  "status" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'QUEUED'::character varying,
  "baseline_schema_hash" varchar(64) COLLATE "pg_catalog"."default",
  "observed_schema_hash" varchar(64) COLLATE "pg_catalog"."default",
  "ddl_text" text COLLATE "pg_catalog"."default",
  "error_message" varchar(1000) COLLATE "pg_catalog"."default",
  "start_time" timestamp(6),
  "end_time" timestamp(6),
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."model_id" IS '物理模型编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."version_id" IS '部署的物理模型版本编号（计划固定，不随后续修订变化）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."version_no" IS '版本号（冗余）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."database_id" IS '目标数据源编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."datasource_name" IS '目标数据源名称（冗余）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."table_name" IS '目标表名（冗余，部署时点的表名）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."request_key" IS '幂等键：同键重复请求返回同一条记录，不重复执行 DDL';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."deploy_action" IS '部署动作：CREATE_TABLE-建表 VERIFY_ONLY-仅核验（表已存在且结构一致）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."status" IS '执行状态：QUEUED-排队中 RUNNING-执行中 VERIFYING-核验中 SUCCEEDED-成功 FAILED-失败 UNKNOWN-结果未知（需人工核验）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."baseline_schema_hash" IS '执行前采集的实库结构摘要，表不存在时为空；与上次成功部署的摘要不一致说明实库被绕过平台改过';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."observed_schema_hash" IS '执行后核验采集的实库结构摘要';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."ddl_text" IS '实际执行的 DDL，供审计与排查';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."error_message" IS '失败或未知原因';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."start_time" IS '开始时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_deploy_record"."end_time" IS '结束时间';
COMMENT ON TABLE "datahub-center"."dh_modeling_deploy_record" IS '数据建模-物理模型部署记录';

-- ----------------------------
-- 数据记录： dh_modeling_deploy_record
-- ----------------------------

-- ----------------------------
-- 表结构： dh_modeling_dw_layer
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_dw_layer";
CREATE TABLE "datahub-center"."dh_modeling_dw_layer" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_dw_layer_seq'::regclass),
  "parent_id" int8 NOT NULL DEFAULT 0,
  "ancestors" varchar(512) COLLATE "pg_catalog"."default" NOT NULL DEFAULT '0'::character varying,
  "level_no" int2 NOT NULL,
  "layer_name" varchar(64) COLLATE "pg_catalog"."default" NOT NULL,
  "layer_code" varchar(32) COLLATE "pg_catalog"."default",
  "node_type" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "table_prefix" varchar(32) COLLATE "pg_catalog"."default",
  "default_table_type" varchar(32) COLLATE "pg_catalog"."default",
  "owner_user_id" int8,
  "sort_order" int4 NOT NULL DEFAULT 0,
  "is_builtin" int2 NOT NULL DEFAULT 0,
  "status" int2 NOT NULL DEFAULT 1,
  "description" varchar(1024) COLLATE "pg_catalog"."default",
  "remark" varchar(512) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."parent_id" IS '父级ID，0表示一级分类节点';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."ancestors" IS '祖级列表，如 0 或 0,1';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."level_no" IS '层级：1分类节点，2实际分层';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."layer_name" IS '分层名称';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."layer_code" IS '分层编码：ODS/DIM/DWD/DWS/ADS，分类节点为空';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."node_type" IS '节点类型：CATEGORY分类节点/LAYER实际分层节点';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."table_prefix" IS '默认表前缀，仅实际分层节点填写';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."default_table_type" IS '默认表类型：SOURCE贴源/DETAIL明细/DIMENSION维度/SUMMARY汇总/APPLICATION应用';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."owner_user_id" IS '负责人ID';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."sort_order" IS '排序';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."is_builtin" IS '是否内置：0否 1是，内置节点不允许删除';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."status" IS '状态：0-启用 1-停用';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."description" IS '说明';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."dh_modeling_dw_layer"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."dh_modeling_dw_layer" IS '数据建模-数仓分层';

