INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (10, 0, '0', 1, '1', NULL, 'CATEGORY', NULL, NULL, 100, 1, 0, 0, '1', NULL, '1', '2026-07-07 23:39:49.733301', '1', '2026-07-08 00:03:48.514407', 1, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (8, 7, '0,7', 2, '数据应用层', 'ADS', 'LAYER', 'ads_', 'APPLICATION', 1, 1, 1, 0, '数据仓库中面向具体业务场景、报表看板、数据服务或应用系统的数据输出层，基于 DWD、DWS、DIM 等数据按应用需求进行加工、聚合和组织，直接支撑经营分析、指标监控、决策看板、数据接口、标签画像等实际使用场景。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 12:00:32.647258', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (1, 0, '0', 1, '贴源层', NULL, 'CATEGORY', NULL, NULL, 1, 1, 1, 0, '中台中对业务系统、日志系统、第三方系统等原始数据进行接入和落地的层级，通常保持数据的原始结构、原始粒度和原始语义，不做或仅做必要的格式转换与技术清洗，用于完整留存数据来源、支撑数据追溯和后续加工。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 11:47:14.414429', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (3, 0, '0', 1, '公共层', NULL, 'CATEGORY', NULL, NULL, 1, 2, 1, 0, '数据中台中对贴源层数据进行统一清洗、标准化、整合、建模和沉淀的共享数据层，按照统一的数据标准、业务口径、主题域和维度模型组织数据，形成可复用、可信赖、跨业务共享的数据资产。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 11:47:39.828181', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (7, 0, '0', 1, '应用层', NULL, 'CATEGORY', NULL, NULL, 1, 3, 1, 0, '数据中台中面向具体业务场景、分析需求或应用系统的数据服务层，基于公共层数据按业务目标进行汇总、加工、标签化或指标化处理，直接支撑报表分析、经营决策、数据接口、画像服务、风控预警等应用。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 11:51:34.944829', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (2, 1, '0,1', 2, '操作数据层', 'ODS', 'LAYER', 'ods_', 'SOURCE', 1, 1, 1, 0, '数据仓库中对业务系统、日志系统、接口数据等源数据进行接入和存储的基础层，通常尽量保持数据的原始结构、原始粒度和原始业务含义，仅进行必要的格式转换、字段映射、去重、补采等技术处理，用于承接源系统数据并支撑后续数仓加工。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 11:59:48.489486', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (4, 3, '0,3', 2, '维度层', 'DIM', 'LAYER', 'dim_', 'DIMENSION', 1, 1, 1, 0, '数据仓库中用于沉淀业务分析维度的数据层，围绕组织、人员、客户、产品、地区、时间、项目等分析对象，统一维度编码、属性、层级关系和业务口径，为明细分析、汇总统计和指标计算提供一致的维度参照。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 12:00:00.962716', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (5, 3, '0,3', 2, '明细数据层', 'DWD', 'LAYER', 'dwd_', 'DETAIL', 1, 2, 1, 0, '数据仓库中对 ODS 数据进行清洗、规范化、关联维度和业务过程建模后形成的明细事实数据层，通常保留最细业务粒度，统一字段含义、数据质量和业务口径，用于支撑后续汇总、分析和数据追溯。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 12:00:10.220168', 0, 1);
INSERT INTO "datahub-center"."dh_modeling_dw_layer" VALUES (6, 3, '0,3', 2, '汇总数据层', 'DWS', 'LAYER', 'dws_', 'SUMMARY', 1, 3, 1, 0, '数据仓库中基于 DWD 明细数据，按照主题域、业务对象、统计周期和分析维度进行轻度或中度汇总形成的共享数据层，用于沉淀可复用的主题指标、宽表和汇总结果，提升数据查询效率并支撑上层应用分析。', NULL, '', '2026-07-07 00:46:29.522026', '1', '2026-07-08 12:00:19.297108', 0, 1);

-- ----------------------------
-- 表结构： dh_modeling_logic_model
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_logic_model";
CREATE TABLE "datahub-center"."dh_modeling_logic_model" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_logic_model_seq'::regclass),
  "theme_id" int8 NOT NULL,
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL,
  "code" varchar(64) COLLATE "pg_catalog"."default",
  "create_mode" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'FORWARD'::character varying,
  "latest_version" int4 NOT NULL DEFAULT 1,
  "status" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'REVISING'::character varying,
  "description" varchar(500) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "concept_entity_id" int8,
  "pos_x" int4,
  "pos_y" int4,
  "model_style" varchar(20) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'RELATIONAL'::character varying,
  "warehouse_layer" varchar(10) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'NONE'::character varying,
  "business_process_id" int8,
  "grain" varchar(512) COLLATE "pg_catalog"."default",
  "layer_id" int8,
  "subject_domain_id" int8,
  "table_type" varchar(32) COLLATE "pg_catalog"."default",
  "classification_status" varchar(32) COLLATE "pg_catalog"."default" DEFAULT 'UNCLASSIFIED'::character varying
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."theme_id" IS '所属模型目录编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."name" IS '模型名称';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."code" IS '模型编码';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."create_mode" IS '创建方式：FORWARD-正向建模 REVERSE-逆向建模';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."latest_version" IS '最新版本号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."status" IS '状态：REVISING-修订中 PUBLISHED-已发布 DISCARDED-已废弃';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."description" IS '描述';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model"."update_time" IS '最后更新时间';
