-- 数据记录： dh_modeling_physical_model
-- ----------------------------

-- ----------------------------
-- 表结构： dh_modeling_physical_model_version
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_physical_model_version";
CREATE TABLE "datahub-center"."dh_modeling_physical_model_version" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_physical_model_version_seq'::regclass),
  "model_id" int8 NOT NULL,
  "version" int4 NOT NULL,
  "status" varchar(16) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'REVISING'::character varying,
  "fields" jsonb,
  "remark" varchar(500) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  "type_config" jsonb,
  "model_snapshot" jsonb
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."model_id" IS '物理模型编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."version" IS '版本号（1 起）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."status" IS '状态：REVISING-修订中 PUBLISHED-已发布';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."fields" IS '字段定义 JSON：中文名称/字段名称/数据类型/长度/精度/排序/注释/关联数据标准';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."updater" IS '最后更新者';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."update_time" IS '最后更新时间';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."deleted" IS '逻辑删除标识：0未删除、1已删除';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."tenant_id" IS '租户编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."type_config" IS '表类型专属配置 JSON，结构随模型 table_type 变化，见 ModelTypeConfigVO';
COMMENT ON COLUMN "datahub-center"."dh_modeling_physical_model_version"."model_snapshot" IS '发布时冻结的完整物理模型及部署配置；历史空值版本部署时失败关闭，不回退到可变模型头';
COMMENT ON TABLE "datahub-center"."dh_modeling_physical_model_version" IS '数据建模-物理模型版本';

