-- ----------------------------
-- 表结构： dh_modeling_theme_plan
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."dh_modeling_theme_plan";
CREATE TABLE "datahub-center"."dh_modeling_theme_plan" (
  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_theme_plan_seq'::regclass),
  "parent_id" int8 NOT NULL DEFAULT 0,
  "theme_name" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "theme_code" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "theme_type" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "owner_dept_id" int8,
  "owner_user_id" int8,
  "dw_source_id" int8,
  "dw_layer_id" int8,
  "sort_order" int4 NOT NULL DEFAULT 0,
  "status" int2 NOT NULL DEFAULT 1,
  "description" varchar(1024) COLLATE "pg_catalog"."default",
  "creator" varchar(64) COLLATE "pg_catalog"."default",
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default",
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "remark" varchar(512) COLLATE "pg_catalog"."default"
)
;
COMMENT ON COLUMN "datahub-center"."dh_modeling_theme_plan"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."dh_modeling_theme_plan"."parent_id" IS '父级ID';
