-- Migration: 0041 供应来源账本与聚合控制协议
-- Purpose: 建立来源身份、终态墓碑、聚合版本和持久操作回执，不推测历史字段授权
-- Depends on: 0040_dataforge_run-metrics-indexes.sql；当前本地基线已有 dh_supply_app_api 与 dh_supply_grant_op
-- Target: 已有平台 PostgreSQL 库，数据中台 schema；新库结构同步至基线但当前基线仍不完整
-- Repeatable: 是；加法字段、索引和建表可重放，不覆盖已确认的新协议状态
-- Rollback: 不自动回滚；必须保留来源墓碑和回执，回退需停全部节点、备份并另编迁移
-- 风险：新增唯一索引需要结构锁；先停止所有旧授权写入节点，在维护窗口执行。
-- 历史重复或空身份明确中止，不能猜测合并、删除历史或自动授予全部字段。

BEGIN;
SET LOCAL search_path TO "datahub-center";
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';

DO $$
BEGIN
    IF to_regclass('"datahub-center".dh_supply_app_api') IS NULL
        OR to_regclass('"datahub-center".dh_supply_grant_op') IS NULL THEN
        RAISE EXCEPTION '来源协议缺少前置授权表或操作表，禁止跳过前置状态';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_supply_app_api WHERE tenant_id IS NULL OR app_id IS NULL OR api_id IS NULL)
        OR EXISTS (SELECT 1 FROM dh_supply_grant_op WHERE tenant_id IS NULL
            OR source_system IS NULL OR btrim(source_system) = ''
            OR operation_id IS NULL OR btrim(operation_id) = '') THEN
        RAISE EXCEPTION '来源协议存在空租户或空业务身份，须先人工确认';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_supply_app_api WHERE deleted = 0
               GROUP BY tenant_id, app_id, api_id HAVING count(*) > 1) THEN
        RAISE EXCEPTION '存在重复旧聚合授权，须逐来源确认，禁止删除或猜测合并';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_supply_grant_op
               GROUP BY tenant_id, source_system, operation_id HAVING count(*) > 1) THEN
        RAISE EXCEPTION '存在重复旧授权操作回执，须人工确认';
    END IF;
END $$;

ALTER TABLE dh_supply_app_api
    ADD COLUMN IF NOT EXISTS protocol_version smallint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS aggregate_revision bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS aggregate_disabled boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS migration_status varchar(32) NOT NULL DEFAULT 'REVIEW_REQUIRED';
COMMENT ON COLUMN dh_supply_app_api.protocol_version IS '授权协议版本：零为历史，二为来源协议';
COMMENT ON COLUMN dh_supply_app_api.aggregate_revision IS '聚合权限单调版本，与来源序号和审批版本无关';
COMMENT ON COLUMN dh_supply_app_api.aggregate_disabled IS '应用与接口聚合整体禁用，来源授予不得清除';
COMMENT ON COLUMN dh_supply_app_api.migration_status IS '历史来源证据确认状态，未确认不得推测全部字段';
CREATE UNIQUE INDEX IF NOT EXISTS uk_supply_app_api_active
    ON dh_supply_app_api (tenant_id, app_id, api_id) WHERE deleted = 0;

ALTER TABLE dh_supply_grant_op
    ADD COLUMN IF NOT EXISTS protocol_version smallint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS source_revision bigint,
    ADD COLUMN IF NOT EXISTS aggregate_revision bigint,
    ADD COLUMN IF NOT EXISTS command_type varchar(16),
    ADD COLUMN IF NOT EXISTS response_json jsonb;
ALTER TABLE dh_supply_grant_op ALTER COLUMN operation_id TYPE varchar(128);
COMMENT ON COLUMN dh_supply_grant_op.operation_id IS '来源操作编号，与租户和来源系统组成不可复用身份';
COMMENT ON COLUMN dh_supply_grant_op.protocol_version IS '回执协议版本，旧回执保持零';
COMMENT ON COLUMN dh_supply_grant_op.source_revision IS '此次命令的来源单调序号';
COMMENT ON COLUMN dh_supply_grant_op.aggregate_revision IS '此次处理完成时的聚合版本';
COMMENT ON COLUMN dh_supply_grant_op.command_type IS '命令类型：授予、暂停、终态撤销';
COMMENT ON COLUMN dh_supply_grant_op.response_json IS '已确定结果的不可变来源操作回执';
CREATE UNIQUE INDEX IF NOT EXISTS uk_supply_source_operation
    ON dh_supply_grant_op (tenant_id, source_system, operation_id);

CREATE SEQUENCE IF NOT EXISTS dh_supply_grant_source_seq;
CREATE TABLE IF NOT EXISTS dh_supply_grant_source (
    id bigint PRIMARY KEY DEFAULT nextval('dh_supply_grant_source_seq'),
    tenant_id bigint NOT NULL,
    source_system varchar(64) NOT NULL CHECK (btrim(source_system) <> ''),
    source_key varchar(256) NOT NULL CHECK (btrim(source_key) <> ''),
    app_id bigint NOT NULL,
    api_id bigint NOT NULL,
    source_revision bigint NOT NULL CHECK (source_revision > 0),
    source_status varchar(32) NOT NULL CHECK (source_status IN ('ACTIVE','SUSPENDED','REVOKED','REVIEW_REQUIRED')),
    scope_json jsonb,
    payload_hash varchar(64) NOT NULL,
    compatibility_key varchar(64),
    creator varchar(64) DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT (clock_timestamp() AT TIME ZONE 'Asia/Shanghai'),
    updater varchar(64) DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT (clock_timestamp() AT TIME ZONE 'Asia/Shanghai'),
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted = 0),
    CONSTRAINT ck_supply_source_active_scope CHECK (source_status <> 'ACTIVE' OR
        COALESCE(scope_json IS NOT NULL AND jsonb_typeof(scope_json) = 'object'
          AND jsonb_typeof(scope_json->'approvedColumns') = 'array'
          AND jsonb_array_length(scope_json->'approvedColumns') > 0
          AND compatibility_key IS NOT NULL, false))
);
-- 表说明（原文）：供应逐来源授权账本，撤销保留终态墓碑
COMMENT ON TABLE dh_supply_grant_source IS '数据服务-授权来源';
COMMENT ON COLUMN dh_supply_grant_source.id IS '账本主键';
COMMENT ON COLUMN dh_supply_grant_source.tenant_id IS '受信调用上下文的租户编号';
COMMENT ON COLUMN dh_supply_grant_source.source_system IS '来源系统';
COMMENT ON COLUMN dh_supply_grant_source.source_key IS '租户内稳定来源身份，不包含审批修订号';
COMMENT ON COLUMN dh_supply_grant_source.app_id IS '绑定应用，来源身份不可迁移到其他应用';
COMMENT ON COLUMN dh_supply_grant_source.api_id IS '绑定接口，来源身份不可迁移到其他接口';
COMMENT ON COLUMN dh_supply_grant_source.source_revision IS '来源单调序号';
COMMENT ON COLUMN dh_supply_grant_source.source_status IS '来源状态：有效、暂停、终态撤销、待复核';
COMMENT ON COLUMN dh_supply_grant_source.scope_json IS '不可变批准范围，墓碑允许为空，空值不表示全字段';
COMMENT ON COLUMN dh_supply_grant_source.payload_hash IS '最近接受命令的规范语义摘要';
COMMENT ON COLUMN dh_supply_grant_source.compatibility_key IS '主体、绑定、合同、用途与策略的兼容摘要';
COMMENT ON COLUMN dh_supply_grant_source.creator IS '创建者';
COMMENT ON COLUMN dh_supply_grant_source.create_time IS '创建时间';
COMMENT ON COLUMN dh_supply_grant_source.updater IS '更新者';
COMMENT ON COLUMN dh_supply_grant_source.update_time IS '更新时间';
COMMENT ON COLUMN dh_supply_grant_source.deleted IS '固定为零，来源身份及墓碑不可逻辑删除后复用';
CREATE UNIQUE INDEX IF NOT EXISTS uk_supply_source_identity
    ON dh_supply_grant_source (tenant_id, source_system, source_key);
CREATE INDEX IF NOT EXISTS idx_supply_source_aggregate
    ON dh_supply_grant_source (tenant_id, app_id, api_id, source_status);
COMMIT;

