COMMENT ON COLUMN "datahub-center"."seatunnel_access"."next_run_time" IS '下次执行时间';
COMMENT ON COLUMN "datahub-center"."seatunnel_access"."version" IS '版本号';
COMMENT ON COLUMN "datahub-center"."seatunnel_access"."deleted" IS '删除标识  0：正常   1：已删除';
COMMENT ON COLUMN "datahub-center"."seatunnel_access"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."seatunnel_access"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."seatunnel_access"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."seatunnel_access"."update_time" IS '更新时间';
