-- ----------------------------
-- 表结构： system_dict_data
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."system_dict_data";
CREATE TABLE "datahub-center"."system_dict_data" (
  "id" int8 NOT NULL,
  "sort" int4 NOT NULL DEFAULT 0,
  "label" varchar(100) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "value" varchar(100) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "dict_type" varchar(100) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "status" int2 NOT NULL DEFAULT 0,
  "color_type" varchar(100) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "css_class" varchar(100) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "remark" varchar(500) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."system_dict_data"."id" IS '字典编码';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."sort" IS '字典排序';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."label" IS '字典标签';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."value" IS '字典键值';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."dict_type" IS '字典类型';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."status" IS '状态（0正常 1停用）';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."color_type" IS '颜色类型';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."css_class" IS 'css 样式';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_dict_data"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."system_dict_data" IS '字典数据表';

