-- ----------------------------
-- 表结构： system_dict_type
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."system_dict_type";
CREATE TABLE "datahub-center"."system_dict_type" (
  "id" int8 NOT NULL,
  "name" varchar(100) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "type" varchar(100) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "status" int2 NOT NULL DEFAULT 0,
  "remark" varchar(500) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "deleted_time" timestamp(6)
)
;
COMMENT ON COLUMN "datahub-center"."system_dict_type"."id" IS '字典主键';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."name" IS '字典名称';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."type" IS '字典类型';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."status" IS '状态（0正常 1停用）';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."system_dict_type"."deleted_time" IS '删除时间';
COMMENT ON TABLE "datahub-center"."system_dict_type" IS '字典类型表';

