-- ----------------------------
-- 表结构： system_login_log
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."system_login_log";
CREATE TABLE "datahub-center"."system_login_log" (
  "id" int8 NOT NULL,
  "log_type" int8 NOT NULL,
  "trace_id" varchar(64) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "user_id" int8 NOT NULL DEFAULT 0,
  "user_type" int2 NOT NULL DEFAULT 0,
  "username" varchar(50) COLLATE "pg_catalog"."default" NOT NULL DEFAULT ''::character varying,
  "result" int2 NOT NULL,
  "user_ip" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "user_agent" varchar(512) COLLATE "pg_catalog"."default" NOT NULL,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."system_login_log"."id" IS '访问ID';
COMMENT ON COLUMN "datahub-center"."system_login_log"."log_type" IS '日志类型';
COMMENT ON COLUMN "datahub-center"."system_login_log"."trace_id" IS '链路追踪编号';
COMMENT ON COLUMN "datahub-center"."system_login_log"."user_id" IS '用户编号';
COMMENT ON COLUMN "datahub-center"."system_login_log"."user_type" IS '用户类型';
COMMENT ON COLUMN "datahub-center"."system_login_log"."username" IS '用户账号';
COMMENT ON COLUMN "datahub-center"."system_login_log"."result" IS '登陆结果';
COMMENT ON COLUMN "datahub-center"."system_login_log"."user_ip" IS '用户 IP';
COMMENT ON COLUMN "datahub-center"."system_login_log"."user_agent" IS '浏览器 UA';
COMMENT ON COLUMN "datahub-center"."system_login_log"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."system_login_log"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_login_log"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_login_log"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_login_log"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."system_login_log"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."system_login_log" IS '系统访问记录';

-- ----------------------------
-- 数据记录： system_login_log
-- ----------------------------
-- 运行期日志、审计或会话数据不随新库基线发布，表结构与序列保持不变。

-- ----------------------------
-- 表结构： system_mail_account
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."system_mail_account";
CREATE TABLE "datahub-center"."system_mail_account" (
  "id" int8 NOT NULL,
  "mail" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "username" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "password" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "host" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "port" int4 NOT NULL,
  "ssl_enable" bool NOT NULL DEFAULT false,
  "starttls_enable" bool NOT NULL DEFAULT false,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."system_mail_account"."id" IS '主键';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."mail" IS '邮箱';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."username" IS '用户名';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."password" IS '密码';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."host" IS 'SMTP 服务器域名';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."port" IS 'SMTP 服务器端口';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."ssl_enable" IS '是否开启 SSL';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."starttls_enable" IS '是否开启 STARTTLS';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_mail_account"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."system_mail_account" IS '邮箱账号表';

-- ----------------------------
