COMMENT ON COLUMN "datahub-center"."system_mail_log"."cc_mails" IS '抄送邮箱地址';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."bcc_mails" IS '密送邮箱地址';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."account_id" IS '邮箱账号编号';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."from_mail" IS '发送邮箱地址';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."template_id" IS '模板编号';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."template_code" IS '模板编码';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."template_nickname" IS '模版发送人名称';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."template_title" IS '邮件标题';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."template_content" IS '邮件内容';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."template_params" IS '邮件参数';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."send_status" IS '发送状态';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."send_time" IS '发送时间';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."send_message_id" IS '发送返回的消息 ID';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."send_exception" IS '发送异常';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_mail_log"."deleted" IS '是否删除';
