-- ----------------------------
-- 表结构： system_notice
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."system_notice";
CREATE TABLE "datahub-center"."system_notice" (
  "id" int8 NOT NULL,
  "title" varchar(50) COLLATE "pg_catalog"."default" NOT NULL,
  "content" text COLLATE "pg_catalog"."default" NOT NULL,
  "type" int2 NOT NULL,
  "status" int2 NOT NULL DEFAULT 0,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."system_notice"."id" IS '公告ID';
COMMENT ON COLUMN "datahub-center"."system_notice"."title" IS '公告标题';
COMMENT ON COLUMN "datahub-center"."system_notice"."content" IS '公告内容';
COMMENT ON COLUMN "datahub-center"."system_notice"."type" IS '公告类型（1通知 2公告）';
