-- ----------------------------
-- 表结构： system_oauth2_access_token
-- ----------------------------
DROP TABLE IF EXISTS "datahub-center"."system_oauth2_access_token";
CREATE TABLE "datahub-center"."system_oauth2_access_token" (
  "id" int8 NOT NULL,
  "user_id" int8 NOT NULL,
  "user_type" int2 NOT NULL,
  "user_info" varchar(512) COLLATE "pg_catalog"."default" NOT NULL,
  "access_token" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "refresh_token" varchar(32) COLLATE "pg_catalog"."default" NOT NULL,
  "client_id" varchar(255) COLLATE "pg_catalog"."default" NOT NULL,
  "scopes" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "expires_time" timestamp(6) NOT NULL,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."id" IS '编号';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."user_id" IS '用户编号';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."user_type" IS '用户类型';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."user_info" IS '用户信息';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."access_token" IS '访问令牌';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."refresh_token" IS '刷新令牌';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."client_id" IS '客户端编号';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."scopes" IS '授权范围';
COMMENT ON COLUMN "datahub-center"."system_oauth2_access_token"."expires_time" IS '过期时间';
