COMMENT ON COLUMN "datahub-center"."system_role_menu"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_role_menu"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_role_menu"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_role_menu"."deleted" IS '是否删除';
COMMENT ON COLUMN "datahub-center"."system_role_menu"."tenant_id" IS '租户编号';
COMMENT ON TABLE "datahub-center"."system_role_menu" IS '角色和菜单关联表';

