DROP TABLE IF EXISTS "datahub-center"."system_sms_channel";
CREATE TABLE "datahub-center"."system_sms_channel" (
  "id" int8 NOT NULL,
  "signature" varchar(12) COLLATE "pg_catalog"."default" NOT NULL,
  "code" varchar(63) COLLATE "pg_catalog"."default" NOT NULL,
  "status" int2 NOT NULL,
  "remark" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "api_key" varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
  "api_secret" varchar(128) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "callback_url" varchar(255) COLLATE "pg_catalog"."default" DEFAULT NULL::character varying,
  "creator" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) COLLATE "pg_catalog"."default" DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0
)
;
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."id" IS '编号';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."signature" IS '短信签名';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."code" IS '渠道编码';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."status" IS '开启状态';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."remark" IS '备注';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."api_key" IS '短信 API 的账号';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."api_secret" IS '短信 API 的秘钥';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."callback_url" IS '短信发送回调 URL';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."creator" IS '创建者';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."create_time" IS '创建时间';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."updater" IS '更新者';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."update_time" IS '更新时间';
COMMENT ON COLUMN "datahub-center"."system_sms_channel"."deleted" IS '是否删除';
COMMENT ON TABLE "datahub-center"."system_sms_channel" IS '短信渠道';

