-- ----------------------------
-- 函数结构： dh_validate_standard_code_item_hierarchy
-- ----------------------------
DROP FUNCTION IF EXISTS "datahub-center"."dh_validate_standard_code_item_hierarchy"();
CREATE FUNCTION "datahub-center"."dh_validate_standard_code_item_hierarchy"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
DECLARE
  resolved_type varchar(100);
  has_cycle boolean;
BEGIN
  IF NEW."deleted" = 0 THEN
    -- The code-set row is the aggregate lock root. Serializing all active hierarchy
    -- writes in one tenant + code set prevents concurrent parent updates from
    -- committing a cycle through write skew.
    SELECT code_set."type" INTO resolved_type
    FROM "datahub-center"."dh_governance_standard_code_set" code_set
    WHERE code_set."tenant_id" = NEW."tenant_id"
      AND code_set."id" = NEW."code_set_id"
      AND code_set."deleted" = 0
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'standard code item must reference an active code set in the same tenant';
    END IF;
    IF NEW."dict_type" <> resolved_type THEN
      RAISE EXCEPTION 'standard code item dict_type must match its code set type';
    END IF;
  END IF;

  IF NEW."parent_id" IS NULL THEN
    RETURN NEW;
  END IF;
  IF NEW."parent_id" = NEW."id" THEN
    RAISE EXCEPTION 'standard code item cannot be its own parent';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM "datahub-center"."dh_governance_standard_code_item" parent
    WHERE parent."id" = NEW."parent_id"
      AND parent."tenant_id" = NEW."tenant_id"
      AND parent."code_set_id" = NEW."code_set_id"
      AND parent."deleted" = 0
  ) THEN
    RAISE EXCEPTION 'standard code-item parent must be active and in the same tenant and code set';
  END IF;

  WITH RECURSIVE ancestors AS (
    SELECT item."id", item."parent_id", ARRAY[item."id"]::int4[] AS path
    FROM "datahub-center"."dh_governance_standard_code_item" item
    WHERE item."id" = NEW."parent_id"
      AND item."tenant_id" = NEW."tenant_id"
      AND item."code_set_id" = NEW."code_set_id"
      AND item."deleted" = 0
    UNION ALL
    SELECT parent."id", parent."parent_id", ancestors.path || parent."id"
    FROM ancestors
    JOIN "datahub-center"."dh_governance_standard_code_item" parent
      ON parent."id" = ancestors."parent_id"
     AND parent."tenant_id" = NEW."tenant_id"
     AND parent."code_set_id" = NEW."code_set_id"
     AND parent."deleted" = 0
    WHERE NOT parent."id" = ANY(ancestors.path)
  )
  SELECT EXISTS (SELECT 1 FROM ancestors WHERE "id" = NEW."id") INTO has_cycle;
  IF has_cycle THEN
    RAISE EXCEPTION 'standard code-item hierarchy cycle detected';
  END IF;
  RETURN NEW;
END
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;































































































































































































































-- ----------------------------
-- 函数结构： reject_standard_element_version_mutation
-- ----------------------------
DROP FUNCTION IF EXISTS "datahub-center"."reject_standard_element_version_mutation"();
CREATE FUNCTION "datahub-center"."reject_standard_element_version_mutation"()
  RETURNS "pg_catalog"."trigger" AS $BODY$
BEGIN
  RAISE EXCEPTION 'dh_governance_standard_element_version is immutable';
END
$BODY$
  LANGUAGE plpgsql VOLATILE
  COST 100;




















