  ON "datahub-center"."dh_modeling_business_process_data_domain_rel"
      ("tenant_id", "data_domain_id", "relation_role")
  WHERE "deleted" = 0;

COMMENT ON COLUMN "datahub-center"."dh_modeling_biz_category"."domain_ids"
  IS '兼容字段：业务分类覆盖的数据域 JSON；规范化来源为 dh_modeling_biz_category_data_domain_rel';
COMMENT ON COLUMN "datahub-center"."dh_modeling_subject_domain"."layer_id"
  IS '兼容字段：历史主题域关联分层；主题域与数仓分层在业务语义上正交';

INSERT INTO "datahub-center"."dh_modeling_biz_category_data_domain_rel"
  ("biz_category_id", "data_domain_id", "sort_order", "creator", "create_time",
   "updater", "update_time", "tenant_id")
SELECT c."id",
       item."domain_id_text"::int8,
       (item."ordinality" - 1)::int4,
       c."creator", c."create_time", c."updater", c."update_time", c."tenant_id"
FROM "datahub-center"."dh_modeling_biz_category" c
CROSS JOIN LATERAL jsonb_array_elements_text(
  CASE WHEN jsonb_typeof(c."domain_ids") = 'array'
       THEN c."domain_ids" ELSE '[]'::jsonb END
) WITH ORDINALITY AS item("domain_id_text", "ordinality")
JOIN "datahub-center"."dh_modeling_data_domain" d
  ON d."id" = item."domain_id_text"::int8
 AND d."tenant_id" = c."tenant_id"
 AND d."deleted" = 0
WHERE c."deleted" = 0
  AND item."domain_id_text" ~ '^[0-9]+$'
  AND NOT EXISTS (
    SELECT 1
    FROM "datahub-center"."dh_modeling_biz_category_data_domain_rel" r
    WHERE r."biz_category_id" = c."id"
      AND r."data_domain_id" = item."domain_id_text"::int8
      AND r."tenant_id" = c."tenant_id"
      AND r."deleted" = 0
  );

INSERT INTO "datahub-center"."dh_modeling_business_process_data_domain_rel"
  ("business_process_id", "data_domain_id", "relation_role", "sort_order",
   "creator", "create_time", "updater", "update_time", "tenant_id")
SELECT p."id", r."data_domain_id", 'LEGACY_INHERITED', r."sort_order",
       p."creator", p."create_time", p."updater", p."update_time", p."tenant_id"
FROM "datahub-center"."dh_modeling_business_process" p
JOIN "datahub-center"."dh_modeling_biz_category_data_domain_rel" r
  ON r."biz_category_id" = p."biz_category_id"
 AND r."tenant_id" = p."tenant_id"
 AND r."deleted" = 0
WHERE p."deleted" = 0
  AND NOT EXISTS (
    SELECT 1
    FROM "datahub-center"."dh_modeling_business_process_data_domain_rel" existing
    WHERE existing."business_process_id" = p."id"
      AND existing."data_domain_id" = r."data_domain_id"
      AND existing."tenant_id" = p."tenant_id"
      AND existing."deleted" = 0
  );

