  "id" int8 NOT NULL DEFAULT nextval('"datahub-center".dh_modeling_business_process_domain_candidate_seq'::regclass),
  "business_process_id" int8 NOT NULL,
  "data_domain_id" int8 NOT NULL,
  "source_biz_category_id" int8 NOT NULL,
  "creator" varchar(64) DEFAULT ''::character varying,
  "create_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) DEFAULT ''::character varying,
  "update_time" timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" int2 NOT NULL DEFAULT 0,
  "tenant_id" int8 NOT NULL DEFAULT 1,
  CONSTRAINT "dh_modeling_business_process_domain_candidate_pkey" PRIMARY KEY ("id")
);
COMMENT ON TABLE "datahub-center"."dh_modeling_business_process_domain_candidate"
  IS '数据建模-历史业务过程主数据域候选，仅供治理确认';
CREATE UNIQUE INDEX IF NOT EXISTS "uk_dh_modeling_business_process_domain_candidate"
  ON "datahub-center"."dh_modeling_business_process_domain_candidate"
      ("tenant_id", "business_process_id", "data_domain_id")
  WHERE "deleted" = 0;

INSERT INTO "datahub-center"."dh_modeling_business_process_domain_candidate"
  ("business_process_id", "data_domain_id", "source_biz_category_id",
   "creator", "create_time", "updater", "update_time", "tenant_id")
SELECT r."business_process_id", r."data_domain_id", p."biz_category_id",
       p."creator", p."create_time", p."updater", p."update_time", p."tenant_id"
FROM "datahub-center"."dh_modeling_business_process_data_domain_rel" r
JOIN "datahub-center"."dh_modeling_business_process" p
  ON p."id" = r."business_process_id"
 AND p."tenant_id" = r."tenant_id"
WHERE r."relation_role" = 'LEGACY_INHERITED'
  AND r."deleted" = 0
  AND p."deleted" = 0
ON CONFLICT DO NOTHING;

WITH candidate_counts AS (
  SELECT "tenant_id", "business_process_id", COUNT(DISTINCT "data_domain_id") AS "domain_count",
         MIN("data_domain_id") AS "data_domain_id"
  FROM "datahub-center"."dh_modeling_business_process_domain_candidate"
  WHERE "deleted" = 0
  GROUP BY "tenant_id", "business_process_id"
)
UPDATE "datahub-center"."dh_modeling_business_process" p
SET "data_domain_id" = c."data_domain_id"
FROM candidate_counts c
WHERE p."tenant_id" = c."tenant_id"
  AND p."id" = c."business_process_id"
  AND p."deleted" = 0
  AND p."data_domain_id" IS NULL
  AND c."domain_count" = 1;

