-- Migration: 0013 建模存量数据兼容适配与原始证据保留
-- Purpose: 保留旧数据，迁入主域、支撑域和候选关系，补齐已有模型显式主题/过程关系并记录异常。
-- Depends on: 0003_dataforge_runtime-recovery-lineage.sql 与既有建模基线表；兼容已执行或尚未执行 0004 的结构。
-- Target: PostgreSQL 旧库；尚未执行 0004 时使用本脚本兼容升级，不再执行其破坏性清理；须先核对执行账本。
-- Repeatable: 是；成功批次登记后重放不再回填，避免覆盖之后的人工治理或复活已删除关系。
-- Rollback: 异常整事务回滚；成功后可依据原始快照制定新编号修复，禁止覆盖后续编辑；序列推进可能留下空洞。
-- 执行前停止建模写入并做整库备份。本脚本仅保留仍存在的旧字段，不能恢复已被 0004 删除且没有备份的数据。
-- 本脚本不改模型主键、目录、分层、版本快照、部署记录、发布状态，也不从主题域推导技术分层。
-- 分类推导默认仅作为候选，哪怕只有一个也不代表业务人员已经确认主域。

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';
SELECT pg_advisory_xact_lock(hashtextextended('datahub:modeling:legacy-adaptation:0013', 0));

CREATE TABLE IF NOT EXISTS "datahub-center".dh_modeling_legacy_adaptation_run (
    migration_no varchar(4) PRIMARY KEY,
    finished_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    summary jsonb NOT NULL
);
CREATE TABLE IF NOT EXISTS "datahub-center".dh_modeling_legacy_adaptation_backup (
    migration_no varchar(4) NOT NULL,
    source_table varchar(128) NOT NULL,
    tenant_id int8 NOT NULL,
    source_id int8 NOT NULL,
    source_row jsonb NOT NULL,
    backup_time timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (migration_no, source_table, tenant_id, source_id)
);
CREATE TABLE IF NOT EXISTS "datahub-center".dh_modeling_legacy_adaptation_issue (
    migration_no varchar(4) NOT NULL,
    source_table varchar(128) NOT NULL,
    tenant_id int8 NOT NULL,
    source_id int8 NOT NULL,
    issue_code varchar(64) NOT NULL,
    details jsonb NOT NULL,
    create_time timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (migration_no, source_table, tenant_id, source_id, issue_code)
);
COMMENT ON TABLE "datahub-center".dh_modeling_legacy_adaptation_run IS '建模旧数据适配完成账本（全局迁移控制记录，不是租户业务表）';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_run.migration_no IS '迁移编号，防止成功后重放覆盖人工治理';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_run.finished_at IS '完成时间';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_run.summary IS '本批次处理数量与需人工核验数量';
COMMENT ON TABLE "datahub-center".dh_modeling_legacy_adaptation_backup IS '建模旧数据适配前原始行快照，保留所有租户及逻辑删除记录';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_backup.migration_no IS '迁移编号';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_backup.source_table IS '原始建模表名';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_backup.tenant_id IS '原始行所属租户编号';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_backup.source_id IS '原始行主键，保持整数精度';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_backup.source_row IS '变更前完整原始行JSON，含旧字段和审计信息';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_backup.backup_time IS '原始快照保存时间';
COMMENT ON TABLE "datahub-center".dh_modeling_legacy_adaptation_issue IS '建模旧数据适配时发现的异常清单，不代表当前业务状态';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.migration_no IS '迁移编号';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.source_table IS '异常来源表';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.tenant_id IS '来源租户，0仅用于全局结构提示';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.source_id IS '来源行主键，0仅用于全局结构提示';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.issue_code IS '异常类型代码';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.details IS '原始引用与异常说明JSON';
COMMENT ON COLUMN "datahub-center".dh_modeling_legacy_adaptation_issue.create_time IS '异常记录时间';

-- 使用临时函数解析旧 JSON 中的 ID，禁止超长数字、负数或小数触发 int8 溢出。
CREATE OR REPLACE FUNCTION pg_temp.modeling_0013_id(value text) RETURNS bigint
LANGUAGE plpgsql IMMUTABLE AS $fn$
DECLARE normalized text;
BEGIN
    IF value IS NULL OR value !~ '^[0-9]+$' THEN RETURN NULL; END IF;
    normalized := ltrim(value, '0');
    IF length(normalized) = 0 OR length(normalized) > 19 THEN RETURN NULL; END IF;
    IF normalized::numeric > 9223372036854775807 THEN RETURN NULL; END IF;
    RETURN normalized::bigint;
END $fn$;

DO $migration$
DECLARE
    source_name text;
    relation_name text;
    comment_column_name text;
    column_comment text;
    seq_name text;
    max_id bigint;
    seq_value bigint;
    primary_count bigint := 0;
    candidate_count bigint := 0;
    supporting_count bigint := 0;
    subject_count bigint := 0;
BEGIN
    IF EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_legacy_adaptation_run WHERE migration_no = '0013') THEN
        RAISE NOTICE '0013 已完成，本次不重放旧关系，不覆盖后续人工治理。';
        RETURN;
    END IF;

    -- 必需结构缺失时显式阻断，不假装已完成适配。
    FOREACH source_name IN ARRAY ARRAY[
        'dh_modeling_biz_category', 'dh_modeling_business_process', 'dh_modeling_data_domain',
        'dh_modeling_subject_domain', 'dh_modeling_subject_domain_process_rel',
        'dh_modeling_concept_model', 'dh_modeling_logic_model', 'dh_modeling_physical_model'
    ] LOOP
        IF to_regclass(format('%I.%I', 'datahub-center', source_name)) IS NULL THEN
            RAISE EXCEPTION '0013 缺少建模前置表：%', source_name;
        END IF;
    END LOOP;

    -- 停写窗口内锁定源表，保存整行快照；不删除旧字段、旧关系或逻辑删除历史。
    FOREACH source_name IN ARRAY ARRAY[
        'dh_modeling_biz_category', 'dh_modeling_business_process', 'dh_modeling_data_domain',
        'dh_modeling_subject_domain', 'dh_modeling_subject_domain_process_rel',
        'dh_modeling_biz_category_data_domain_rel', 'dh_modeling_business_process_data_domain_rel',
        'dh_modeling_business_process_supporting_domain_rel', 'dh_modeling_business_process_domain_candidate',
        'dh_modeling_concept_model', 'dh_modeling_logic_model', 'dh_modeling_physical_model'
    ] LOOP
        IF to_regclass(format('%I.%I', 'datahub-center', source_name)) IS NOT NULL THEN
            EXECUTE format('LOCK TABLE %I.%I IN SHARE ROW EXCLUSIVE MODE', 'datahub-center', source_name);
            EXECUTE format(
                'INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_backup
                   (migration_no, source_table, tenant_id, source_id, source_row)
                 SELECT ''0013'', %L, tenant_id, id, to_jsonb(t) FROM %I.%I t
                 ON CONFLICT DO NOTHING', source_name, 'datahub-center', source_name);
        END IF;
    END LOOP;

    IF NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'datahub-center'
                   AND table_name = 'dh_modeling_biz_category' AND column_name = 'domain_ids')
       OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'datahub-center'
                   AND table_name = 'dh_modeling_subject_domain' AND column_name = 'layer_id') THEN
        INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
            (migration_no, source_table, tenant_id, source_id, issue_code, details)
        VALUES ('0013', '__schema__', 0, 0, 'LEGACY_FIELDS_ALREADY_REMOVED',
                '{"message":"部分旧字段已不存在；只适配当前仍存数据，已删除且无备份的数据无法恢复"}');
    END IF;

    ALTER TABLE "datahub-center".dh_modeling_business_process ADD COLUMN IF NOT EXISTS data_domain_id bigint;
    COMMENT ON COLUMN "datahub-center".dh_modeling_business_process.data_domain_id
        IS '业务过程直接归属的主数据域编号；旧分类推导仅供人工确认';

    CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_modeling_business_process_supporting_domain_rel_seq;
    CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_modeling_business_process_domain_candidate_seq;
    CREATE TABLE IF NOT EXISTS "datahub-center".dh_modeling_business_process_supporting_domain_rel (
        id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_modeling_business_process_supporting_domain_rel_seq'),
        business_process_id bigint NOT NULL, data_domain_id bigint NOT NULL, sort_order integer NOT NULL DEFAULT 0,
        creator varchar(64) DEFAULT '', create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updater varchar(64) DEFAULT '', update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        deleted smallint NOT NULL DEFAULT 0, tenant_id bigint NOT NULL DEFAULT 1
    );
    CREATE TABLE IF NOT EXISTS "datahub-center".dh_modeling_business_process_domain_candidate (
        id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_modeling_business_process_domain_candidate_seq'),
        business_process_id bigint NOT NULL, data_domain_id bigint NOT NULL, source_biz_category_id bigint NOT NULL,
        creator varchar(64) DEFAULT '', create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        updater varchar(64) DEFAULT '', update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
        deleted smallint NOT NULL DEFAULT 0, tenant_id bigint NOT NULL DEFAULT 1
    );
    CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_modeling_business_process_supporting_domain_rel
        ON "datahub-center".dh_modeling_business_process_supporting_domain_rel
            (tenant_id, business_process_id, data_domain_id) WHERE deleted = 0;
    CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_modeling_business_process_domain_candidate
        ON "datahub-center".dh_modeling_business_process_domain_candidate
            (tenant_id, business_process_id, data_domain_id) WHERE deleted = 0;
    CREATE INDEX IF NOT EXISTS idx_dh_modeling_business_process_supporting_domain_rel_domain
        ON "datahub-center".dh_modeling_business_process_supporting_domain_rel
            (tenant_id, data_domain_id) WHERE deleted = 0;
    COMMENT ON TABLE "datahub-center".dh_modeling_business_process_supporting_domain_rel IS '建模业务过程支撑数据域关系';
    COMMENT ON TABLE "datahub-center".dh_modeling_business_process_domain_candidate IS '建模历史数据域候选，非已确认归属';
    COMMENT ON COLUMN "datahub-center".dh_modeling_business_process_domain_candidate.source_biz_category_id IS '候选来源业务分类编号';
    COMMENT ON COLUMN "datahub-center".dh_modeling_business_process_supporting_domain_rel.sort_order IS '支撑域展示顺序';

    FOREACH relation_name IN ARRAY ARRAY[
        'dh_modeling_business_process_supporting_domain_rel', 'dh_modeling_business_process_domain_candidate'
    ] LOOP
        FOR comment_column_name, column_comment IN SELECT * FROM (VALUES
            ('id', '主键编号'), ('business_process_id', '业务过程编号'), ('data_domain_id', '数据域编号'),
            ('creator', '创建者'), ('create_time', '创建时间'), ('updater', '更新者'), ('update_time', '更新时间'),
            ('deleted', '逻辑删除标记：0未删除、1已删除'), ('tenant_id', '租户编号')
        ) comments(name, description) LOOP
            EXECUTE format('COMMENT ON COLUMN %I.%I.%I IS %L', 'datahub-center', relation_name, comment_column_name, column_comment);
        END LOOP;
    END LOOP;

    -- 原始关系从备份读取，不受本事务后续回填影响；保留非法文本用于异常核查。
    CREATE TEMP TABLE modeling_0013_links ON COMMIT DROP AS
    SELECT b.tenant_id, b.source_table, b.source_id,
           pg_temp.modeling_0013_id(b.source_row->>'business_process_id') AS process_id,
           b.source_row->>'data_domain_id' AS domain_text,
           b.source_row->>'relation_role' AS role, b.source_row
    FROM "datahub-center".dh_modeling_legacy_adaptation_backup b
    WHERE b.migration_no = '0013' AND b.source_table = 'dh_modeling_business_process_data_domain_rel'
      AND b.source_row->>'deleted' = '0';

    INSERT INTO modeling_0013_links
    SELECT b.tenant_id, b.source_table, b.source_id, p.id, item.value, 'LEGACY_INHERITED', b.source_row
    FROM "datahub-center".dh_modeling_legacy_adaptation_backup b
    JOIN "datahub-center".dh_modeling_business_process p
      ON p.tenant_id = b.tenant_id AND p.biz_category_id = b.source_id AND p.deleted = 0
    CROSS JOIN LATERAL jsonb_array_elements_text(
        CASE WHEN jsonb_typeof(b.source_row->'domain_ids') = 'array'
             THEN b.source_row->'domain_ids' ELSE '[]'::jsonb END) item(value)
    WHERE b.migration_no = '0013' AND b.source_table = 'dh_modeling_biz_category'
      AND b.source_row->>'deleted' = '0';

    INSERT INTO modeling_0013_links
    SELECT b.tenant_id, b.source_table, b.source_id, p.id, b.source_row->>'data_domain_id',
           'LEGACY_INHERITED', b.source_row
    FROM "datahub-center".dh_modeling_legacy_adaptation_backup b
    JOIN "datahub-center".dh_modeling_business_process p
      ON p.tenant_id = b.tenant_id AND p.biz_category_id = pg_temp.modeling_0013_id(b.source_row->>'biz_category_id')
      AND p.deleted = 0
    WHERE b.migration_no = '0013' AND b.source_table = 'dh_modeling_biz_category_data_domain_rel'
      AND b.source_row->>'deleted' = '0';

    -- 规范化引用必须同租户、未删除且启用。无效项留在备份和问题清单，不误转成有效单候选。
    CREATE TEMP TABLE modeling_0013_checked ON COMMIT DROP AS
    SELECT l.*, pg_temp.modeling_0013_id(l.domain_text) AS domain_id,
           COALESCE(p.id IS NOT NULL AND p.deleted = 0 AND p.status = 0
            AND d.id IS NOT NULL AND d.deleted = 0 AND d.status = 0, false) AS valid
    FROM modeling_0013_links l
    LEFT JOIN "datahub-center".dh_modeling_business_process p ON p.id = l.process_id AND p.tenant_id = l.tenant_id
    LEFT JOIN "datahub-center".dh_modeling_data_domain d
      ON d.id = pg_temp.modeling_0013_id(l.domain_text) AND d.tenant_id = l.tenant_id;

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', source_table, tenant_id, source_id, 'INVALID_LEGACY_REFERENCE',
           jsonb_agg(jsonb_build_object('processId', process_id, 'domainId', domain_text, 'role', role))
    FROM modeling_0013_checked WHERE NOT valid OR role NOT IN ('PRIMARY', 'SUPPORTING', 'LEGACY_INHERITED') OR role IS NULL
    GROUP BY source_table, tenant_id, source_id;

    -- 主域必须在原始显式 PRIMARY 集合中唯一，且所有引用均有效；不覆盖现有主域。
    WITH primary_choices AS (
        SELECT tenant_id, process_id, min(domain_id) AS domain_id
        FROM modeling_0013_checked WHERE role = 'PRIMARY'
        GROUP BY tenant_id, process_id HAVING count(DISTINCT domain_id) = 1 AND bool_and(valid)
    )
    UPDATE "datahub-center".dh_modeling_business_process p
    SET data_domain_id = c.domain_id, updater = 'migration:0013', update_time = CURRENT_TIMESTAMP
    FROM primary_choices c
    WHERE p.tenant_id = c.tenant_id AND p.id = c.process_id AND p.deleted = 0 AND p.data_domain_id IS NULL;
    GET DIAGNOSTICS primary_count = ROW_COUNT;

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', 'dh_modeling_business_process', c.tenant_id, c.process_id, 'PRIMARY_CONFLICT',
           jsonb_build_object('existingPrimary', p.data_domain_id, 'legacyPrimaries', jsonb_agg(c.domain_text))
    FROM modeling_0013_checked c JOIN "datahub-center".dh_modeling_business_process p
      ON p.id = c.process_id AND p.tenant_id = c.tenant_id
    WHERE c.role = 'PRIMARY'
    GROUP BY c.tenant_id, c.process_id, p.data_domain_id
    HAVING count(DISTINCT c.domain_id) > 1 OR NOT bool_and(c.valid)
       OR bool_or(c.domain_id IS DISTINCT FROM p.data_domain_id);

    -- 序列只前移，兼容历史显式指定 ID 导致的序列落后，不覆盖任何已有关系 ID。
    FOREACH relation_name IN ARRAY ARRAY[
        'dh_modeling_business_process_supporting_domain_rel', 'dh_modeling_business_process_domain_candidate',
        'dh_modeling_subject_domain_process_rel'
    ] LOOP
        seq_name := pg_get_serial_sequence(format('%I.%I', 'datahub-center', relation_name), 'id');
        IF seq_name IS NULL THEN
            seq_name := format('%I.%I', 'datahub-center', relation_name || '_seq');
            IF to_regclass(seq_name) IS NULL THEN RAISE EXCEPTION '0013 缺少关系序列：%', seq_name; END IF;
        END IF;
        EXECUTE format('SELECT max(id) FROM %I.%I', 'datahub-center', relation_name) INTO max_id;
        EXECUTE format('SELECT last_value FROM %s', seq_name) INTO seq_value;
        IF max_id IS NOT NULL AND max_id >= seq_value THEN PERFORM setval(seq_name::regclass, max_id, true); END IF;
    END LOOP;

    INSERT INTO "datahub-center".dh_modeling_business_process_domain_candidate
        (business_process_id, data_domain_id, source_biz_category_id, creator, updater, tenant_id)
    SELECT DISTINCT c.process_id, c.domain_id, p.biz_category_id, 'migration:0013', 'migration:0013', c.tenant_id
    FROM modeling_0013_checked c
    JOIN "datahub-center".dh_modeling_business_process p ON p.id = c.process_id AND p.tenant_id = c.tenant_id
    JOIN "datahub-center".dh_modeling_biz_category b
      ON b.id = p.biz_category_id AND b.tenant_id = p.tenant_id AND b.deleted = 0
    WHERE c.valid AND c.role = 'LEGACY_INHERITED'
      AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process_domain_candidate x
                      WHERE x.tenant_id = c.tenant_id AND x.business_process_id = c.process_id AND x.data_domain_id = c.domain_id)
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS candidate_count = ROW_COUNT;

    INSERT INTO "datahub-center".dh_modeling_business_process_supporting_domain_rel
        (business_process_id, data_domain_id, sort_order, creator, create_time, updater, update_time, tenant_id)
    SELECT DISTINCT ON (c.tenant_id, c.process_id, c.domain_id)
           c.process_id, c.domain_id, COALESCE((c.source_row->>'sort_order')::int, 0),
           c.source_row->>'creator', COALESCE((c.source_row->>'create_time')::timestamp, CURRENT_TIMESTAMP),
           c.source_row->>'updater', COALESCE((c.source_row->>'update_time')::timestamp, CURRENT_TIMESTAMP), c.tenant_id
    FROM modeling_0013_checked c
    JOIN "datahub-center".dh_modeling_business_process p ON p.id = c.process_id AND p.tenant_id = c.tenant_id
    JOIN "datahub-center".dh_modeling_data_domain primary_domain
      ON primary_domain.id = p.data_domain_id AND primary_domain.tenant_id = p.tenant_id
      AND primary_domain.deleted = 0 AND primary_domain.status = 0
    WHERE c.valid AND c.role = 'SUPPORTING' AND c.domain_id <> p.data_domain_id
      AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel x
                      WHERE x.tenant_id = c.tenant_id AND x.business_process_id = c.process_id AND x.data_domain_id = c.domain_id)
    ORDER BY c.tenant_id, c.process_id, c.domain_id, c.source_id
    ON CONFLICT DO NOTHING;
    GET DIAGNOSTICS supporting_count = ROW_COUNT;

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', c.source_table, c.tenant_id, c.source_id, 'SUPPORTING_NOT_APPLIED',
           jsonb_build_object('processId', c.process_id, 'domainId', c.domain_text,
                              'message', '缺少有效主域、支撑域等于主域或历史关系已被删除，未自动恢复')
    FROM modeling_0013_checked c
    WHERE c.valid AND c.role = 'SUPPORTING'
      AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel x
                      WHERE x.tenant_id = c.tenant_id AND x.business_process_id = c.process_id
                        AND x.data_domain_id = c.domain_id AND x.deleted = 0)
    ON CONFLICT DO NOTHING;

    -- 模型中已经显式保存的主题/过程组合就是迁移证据；只补有效组合，保留来源模型完整快照。
    CREATE TEMP TABLE modeling_0013_model_pairs ON COMMIT DROP AS
    SELECT b.*, pg_temp.modeling_0013_id(b.source_row->>'subject_domain_id') AS subject_id,
           pg_temp.modeling_0013_id(b.source_row->>'business_process_id') AS process_id
    FROM "datahub-center".dh_modeling_legacy_adaptation_backup b
    WHERE b.migration_no = '0013' AND b.source_table IN
        ('dh_modeling_concept_model', 'dh_modeling_logic_model', 'dh_modeling_physical_model')
      AND b.source_row->>'deleted' = '0'
      AND b.source_row->>'subject_domain_id' IS NOT NULL AND b.source_row->>'business_process_id' IS NOT NULL;

    INSERT INTO "datahub-center".dh_modeling_subject_domain_process_rel
        (subject_domain_id, business_process_id, sort_order, creator, updater, tenant_id)
    SELECT DISTINCT m.subject_id, m.process_id, 0, 'migration:0013', 'migration:0013', m.tenant_id
    FROM modeling_0013_model_pairs m
    JOIN "datahub-center".dh_modeling_subject_domain s
      ON s.id = m.subject_id AND s.tenant_id = m.tenant_id AND s.deleted = 0 AND s.status = 0
    JOIN "datahub-center".dh_modeling_business_process p
      ON p.id = m.process_id AND p.tenant_id = m.tenant_id AND p.deleted = 0 AND p.status = 0
    WHERE NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_subject_domain_process_rel r
                      WHERE r.tenant_id = m.tenant_id AND r.subject_domain_id = m.subject_id AND r.business_process_id = m.process_id);
    GET DIAGNOSTICS subject_count = ROW_COUNT;

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', m.source_table, m.tenant_id, m.source_id, 'MODEL_SUBJECT_PROCESS_UNRESOLVED',
           jsonb_build_object('subjectId', m.subject_id, 'processId', m.process_id,
                              'message', '引用无效、停用、跨租户或关系已被显式删除，未自动修复')
    FROM modeling_0013_model_pairs m
    WHERE NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_subject_domain_process_rel r
                      JOIN "datahub-center".dh_modeling_subject_domain s
                        ON s.id = r.subject_domain_id AND s.tenant_id = r.tenant_id AND s.deleted = 0 AND s.status = 0
                      JOIN "datahub-center".dh_modeling_business_process p
                        ON p.id = r.business_process_id AND p.tenant_id = r.tenant_id AND p.deleted = 0 AND p.status = 0
                      WHERE r.tenant_id = m.tenant_id AND r.subject_domain_id = m.subject_id
                        AND r.business_process_id = m.process_id AND r.deleted = 0);

    -- 对已经执行 0004 的数据也重新核查，但不猜测其主域是人工确认还是旧脚本自动填写。
    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', 'dh_modeling_business_process', p.tenant_id, p.id, 'PRIMARY_REQUIRES_REVIEW',
           jsonb_build_object('primaryId', p.data_domain_id, 'message', '主域缺失或引用无效，请在业务过程页面人工确认')
    FROM "datahub-center".dh_modeling_business_process p
    WHERE p.deleted = 0 AND p.status = 0
      AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_data_domain d
                      WHERE d.id = p.data_domain_id AND d.tenant_id = p.tenant_id AND d.deleted = 0 AND d.status = 0);

    -- 已升级库的候选/支撑关系不再有旧来源表，也必须扫描；仅报告，不擅自清理人工数据。
    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', 'dh_modeling_business_process_domain_candidate', c.tenant_id, c.id,
           'EXISTING_CANDIDATE_INVALID', to_jsonb(c)
    FROM "datahub-center".dh_modeling_business_process_domain_candidate c
    WHERE c.deleted = 0 AND (
        NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process p
                    WHERE p.id = c.business_process_id AND p.tenant_id = c.tenant_id AND p.deleted = 0 AND p.status = 0)
        OR NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_data_domain d
                    WHERE d.id = c.data_domain_id AND d.tenant_id = c.tenant_id AND d.deleted = 0 AND d.status = 0)
        OR NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_biz_category b
                    WHERE b.id = c.source_biz_category_id AND b.tenant_id = c.tenant_id AND b.deleted = 0));

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', 'dh_modeling_business_process_supporting_domain_rel', r.tenant_id, r.id,
           'EXISTING_SUPPORTING_INVALID', to_jsonb(r)
    FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel r
    WHERE r.deleted = 0 AND NOT EXISTS (
        SELECT 1 FROM "datahub-center".dh_modeling_business_process p
        JOIN "datahub-center".dh_modeling_data_domain primary_domain
          ON primary_domain.id = p.data_domain_id AND primary_domain.tenant_id = p.tenant_id
          AND primary_domain.deleted = 0 AND primary_domain.status = 0
        JOIN "datahub-center".dh_modeling_data_domain supporting_domain
          ON supporting_domain.id = r.data_domain_id AND supporting_domain.tenant_id = p.tenant_id
          AND supporting_domain.deleted = 0 AND supporting_domain.status = 0
        WHERE p.id = r.business_process_id AND p.tenant_id = r.tenant_id
          AND p.deleted = 0 AND p.status = 0 AND p.data_domain_id <> r.data_domain_id);

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', c.source_table, c.tenant_id, c.source_id, 'LEGACY_CANDIDATE_NOT_APPLIED',
           jsonb_agg(jsonb_build_object('processId', c.process_id, 'domainId', c.domain_text,
                                       'message', '来源分类无效或历史候选已被删除，未自动恢复'))
    FROM modeling_0013_checked c
    WHERE c.valid AND c.role = 'LEGACY_INHERITED'
      AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process_domain_candidate x
                      WHERE x.tenant_id = c.tenant_id AND x.business_process_id = c.process_id
                        AND x.data_domain_id = c.domain_id AND x.deleted = 0)
    GROUP BY c.source_table, c.tenant_id, c.source_id;

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_issue
        (migration_no, source_table, tenant_id, source_id, issue_code, details)
    SELECT '0013', b.source_table, b.tenant_id, b.source_id, 'LEGACY_DOMAIN_JSON_INVALID',
           jsonb_build_object('domainIds', b.source_row->'domain_ids', 'message', '旧分类数据域不是数组，保留原值待核查')
    FROM "datahub-center".dh_modeling_legacy_adaptation_backup b
    WHERE b.migration_no = '0013' AND b.source_table = 'dh_modeling_biz_category'
      AND b.source_row->>'deleted' = '0' AND b.source_row->>'domain_ids' IS NOT NULL
      AND jsonb_typeof(b.source_row->'domain_ids') <> 'array';

    INSERT INTO "datahub-center".dh_modeling_legacy_adaptation_run (migration_no, summary)
    SELECT '0013', jsonb_build_object(
        'primaryFilled', primary_count, 'candidatesAdded', candidate_count,
        'supportingAdded', supporting_count, 'subjectLinksAdded', subject_count,
        'snapshotRows', (SELECT count(*) FROM "datahub-center".dh_modeling_legacy_adaptation_backup WHERE migration_no = '0013'),
        'issues', (SELECT count(*) FROM "datahub-center".dh_modeling_legacy_adaptation_issue WHERE migration_no = '0013'));
END $migration$;

COMMIT;

-- 返回本次处理汇总和待核验清单；无异常也不等于已恢复此前删除且没有备份的数据。
SELECT migration_no, finished_at, summary FROM "datahub-center".dh_modeling_legacy_adaptation_run WHERE migration_no = '0013';
SELECT tenant_id, source_table, source_id, issue_code, details
FROM "datahub-center".dh_modeling_legacy_adaptation_issue WHERE migration_no = '0013'
ORDER BY tenant_id, source_table, source_id, issue_code;

-- 新库最终整理：严格按向前升级的 0015、0016 顺序执行，不包含回滚脚本。
-- Migration: 0015 删除 BizTheme 并新增 data_domain_id（幂等）
-- Purpose: v1+v1.1：新增 data_domain_id；theme_id 存在时清空并删除该列；删除 biz_theme；逻辑删除菜单 6720
-- Target: PostgreSQL 的 "datahub-center" 模式
-- Rollback: 0015_modeling_biz-theme-remove-and-data-domain_rollback.sql
-- 可安全重放：使用 ADD COLUMN IF NOT EXISTS；仅在 theme_id 存在时执行 DROP NOT NULL、UPDATE 和 DROP COLUMN

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';
SELECT pg_advisory_xact_lock(hashtextextended('datahub:modeling:biz-theme-remove:0015', 0));

ALTER TABLE "datahub-center".dh_modeling_concept_model
    ADD COLUMN IF NOT EXISTS data_domain_id int8 NULL;
COMMENT ON COLUMN "datahub-center".dh_modeling_concept_model.data_domain_id IS 'model data domain (ODS may hang domain without process; DWD+ must match process primary domain)';

ALTER TABLE "datahub-center".dh_modeling_logic_model
    ADD COLUMN IF NOT EXISTS data_domain_id int8 NULL;
COMMENT ON COLUMN "datahub-center".dh_modeling_logic_model.data_domain_id IS 'model data domain (ODS may hang domain without process; DWD+ must match process primary domain)';

ALTER TABLE "datahub-center".dh_modeling_physical_model
    ADD COLUMN IF NOT EXISTS data_domain_id int8 NULL;
COMMENT ON COLUMN "datahub-center".dh_modeling_physical_model.data_domain_id IS 'model data domain (ODS may hang domain without process; DWD+ must match process primary domain)';

-- 仅在 theme_id 仍存在时移除非空约束、更新为 NULL 并删除该列
DO $$
DECLARE
  tbl text;
BEGIN
  FOREACH tbl IN ARRAY ARRAY[
    'dh_modeling_concept_model',
    'dh_modeling_logic_model',
    'dh_modeling_physical_model'
  ]
  LOOP
    IF EXISTS (
      SELECT 1 FROM information_schema.columns
      WHERE table_schema = 'datahub-center'
        AND table_name = tbl
        AND column_name = 'theme_id'
    ) THEN
      IF EXISTS (
        SELECT 1 FROM information_schema.columns
        WHERE table_schema = 'datahub-center'
          AND table_name = tbl
          AND column_name = 'theme_id'
          AND is_nullable = 'NO'
      ) THEN
        EXECUTE format('ALTER TABLE "datahub-center".%I ALTER COLUMN theme_id DROP NOT NULL', tbl);
      END IF;
      EXECUTE format('UPDATE "datahub-center".%I SET theme_id = NULL WHERE theme_id IS NOT NULL', tbl);
      EXECUTE format('ALTER TABLE "datahub-center".%I DROP COLUMN IF EXISTS theme_id', tbl);
    END IF;
  END LOOP;
END $$;

UPDATE "datahub-center".system_menu
SET deleted = 1, update_time = CURRENT_TIMESTAMP
WHERE id = 6720 AND deleted = 0;

DROP TABLE IF EXISTS "datahub-center".dh_modeling_biz_theme;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_biz_theme_seq;

COMMIT;

-- Migration: 0016 模型归属、不可变版本快照与持久化模型检测
-- Purpose: 补齐 0015 表结构，完善数据域命名与业务过程唯一性、租户检测队列和归属引用保护
-- Depends on: 须先执行 0015_modeling_biz-theme-remove-and-data-domain.sql、0014_governance_standard-quality-rule.sql 及其前置迁移
-- Target: 已有 PostgreSQL 数据库的 "datahub-center" 模式；升级前暂停建模写入及 modelCheckJob 检测任务
-- Repeatable: 可重复执行；出现唯一性冲突时中止事务，不自动选择或删除数据域归属
-- Rollback: 新增列保留原有数据；如需恢复原有唯一性与归属规则，应还原升级前备份。无租约的历史运行中任务（RUNNING）改为失败（FAILED），不自动重试。禁止执行历史 0015 回退脚本。
-- 风险：数据扫描、索引创建及触发器安装会持有表锁；锁等待超过 5 秒时中止操作。升级前应先排查重复数据。
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';
SELECT pg_advisory_xact_lock(hashtextextended('datahub:modeling:ownership:0016', 0));

ALTER TABLE "datahub-center".dh_modeling_logic_model_version
    ADD COLUMN IF NOT EXISTS model_snapshot jsonb;
COMMENT ON COLUMN "datahub-center".dh_modeling_logic_model_version.model_snapshot
    IS '已发布版本的 v2 模型归属与配置不可变快照；历史版本为空时须修订并重新发布，禁止根据可变模型头推断';
ALTER TABLE "datahub-center".dh_modeling_physical_model
    ADD COLUMN IF NOT EXISTS source_logic_version_id bigint;
COMMENT ON COLUMN "datahub-center".dh_modeling_physical_model.source_logic_version_id
    IS '初次生成物理模型时使用的确切已发布逻辑版本编号；历史模型或非逻辑生成模型可为空';

ALTER TABLE "datahub-center".dh_modeling_model_check
    ADD COLUMN IF NOT EXISTS execution_token varchar(64),
    ADD COLUMN IF NOT EXISTS lease_until timestamp;
ALTER TABLE "datahub-center".dh_modeling_model_check ALTER COLUMN task_status SET DEFAULT 'QUEUED';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.task_status IS '任务状态：排队中（QUEUED）、运行中（RUNNING）、已完成（SUCCESS）、失败（FAILED）；已完成仅表示执行结束，异常数量见 abnormal_total';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.execution_token IS '执行隔离令牌，用于阻止已过期的执行者持久化检测结果';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.lease_until IS '执行租约到期时间；过期任务标记为失败（FAILED），可人工重新发起检测';
ALTER TABLE "datahub-center".dh_modeling_model_check_result
    ADD COLUMN IF NOT EXISTS version_id bigint;
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check_result.version_id IS '本次检测所依据的已发布物理模型版本编号';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check_result.drift_type
    IS '漂移类型：一致（CONSISTENT）、设计领先（DESIGN_AHEAD）、实库漂移（RUNTIME_DRIFT）、双向冲突（CONFLICT）、无基线（NO_BASELINE）、表不存在（MISSING_TABLE）、读取失败（READ_FAILED）、快照缺失（SNAPSHOT_MISSING）；读取失败不能证明表不存在';
UPDATE "datahub-center".dh_modeling_model_check
SET task_status = 'FAILED', end_time = CURRENT_TIMESTAMP, update_time = CURRENT_TIMESTAMP,
    error_info = '旧执行器无持久租约，升级后终止该记录；可重新发起检测'
WHERE deleted = 0 AND task_status = 'RUNNING' AND (execution_token IS NULL OR lease_until IS NULL);

-- 不自动删除或合并重复数据；须由运维或业务负责人在升级前处理冲突。
DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_model_check_config
               WHERE deleted = 0 GROUP BY tenant_id HAVING count(*) > 1) THEN
        RAISE EXCEPTION '0016: multiple model-check configs per tenant; reconcile configs before upgrade';
    END IF;
    IF EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process
               WHERE deleted = 0 AND data_domain_id IS NOT NULL
               GROUP BY tenant_id, data_domain_id, upper(btrim(code)) HAVING count(*) > 1) THEN
        RAISE EXCEPTION '0016: duplicate business process codes within a primary domain; no records were auto-merged';
    END IF;
    IF EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process
               WHERE deleted = 0 AND data_domain_id IS NOT NULL
               GROUP BY tenant_id, data_domain_id, name HAVING count(*) > 1) THEN
        RAISE EXCEPTION '0016: duplicate business process names within a primary domain; resolve before upgrade';
    END IF;
END $preflight$;

CREATE UNIQUE INDEX IF NOT EXISTS uk_modeling_check_active_tenant
    ON "datahub-center".dh_modeling_model_check (tenant_id)
    WHERE deleted = 0 AND task_status IN ('QUEUED', 'RUNNING');
CREATE UNIQUE INDEX IF NOT EXISTS uk_modeling_check_config_tenant
    ON "datahub-center".dh_modeling_model_check_config (tenant_id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_modeling_check_queue
    ON "datahub-center".dh_modeling_model_check (tenant_id, task_status, id) WHERE deleted = 0;
CREATE UNIQUE INDEX IF NOT EXISTS uk_modeling_process_domain_code
    ON "datahub-center".dh_modeling_business_process (tenant_id, data_domain_id, upper(btrim(code)))
    WHERE deleted = 0 AND data_domain_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_modeling_process_domain_name
    ON "datahub-center".dh_modeling_business_process (tenant_id, data_domain_id, name)
    WHERE deleted = 0 AND data_domain_id IS NOT NULL;
DROP INDEX IF EXISTS "datahub-center".uk_dh_modeling_business_process_code;
CREATE UNIQUE INDEX IF NOT EXISTS uk_modeling_process_pending_category_code
    ON "datahub-center".dh_modeling_business_process (tenant_id, biz_category_id, code)
    WHERE deleted = 0 AND data_domain_id IS NULL;

-- 同一租户内的模型引用写入与规划对象删除共用事务锁，防止并发产生悬空引用。
-- 仅在本地数据库写入时获取此锁，不得在持锁期间调用外部元数据接口。
CREATE OR REPLACE FUNCTION "datahub-center".modeling_ownership_reference_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
DECLARE
    row_data jsonb; old_data jsonb; tenant bigint; object_id bigint;
    deleting boolean; tbl text; ref_field text; ref_table text; ref_id bigint;
    found_row boolean; primary_id bigint; model_table text;
BEGIN
    row_data := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    old_data := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
    tenant := (row_data->>'tenant_id')::bigint;
    object_id := (row_data->>'id')::bigint;
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-tenant:' || tenant::text, 0));
    deleting := TG_OP = 'DELETE' OR COALESCE((row_data->>'deleted')::integer, 0) <> 0;
    tbl := TG_TABLE_NAME;

    IF tbl IN ('dh_modeling_concept_model', 'dh_modeling_logic_model', 'dh_modeling_physical_model')
       AND NOT deleting THEN
        FOR ref_field, ref_table IN
            SELECT * FROM (VALUES
                ('data_domain_id','dh_modeling_data_domain'),
                ('subject_domain_id','dh_modeling_subject_domain'),
                ('business_process_id','dh_modeling_business_process'),
                ('layer_id','dh_modeling_dw_layer')) AS refs(field_name, table_name)
        LOOP
            ref_id := (row_data->>ref_field)::bigint;
            IF ref_id IS NOT NULL THEN
                EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND tenant_id=$2 AND deleted=0)', ref_table)
                    INTO found_row USING ref_id, tenant;
                IF NOT found_row THEN
                    RAISE EXCEPTION 'Model ownership reference missing or belongs to another tenant: %', ref_field USING ERRCODE='23514';
                END IF;
            END IF;
        END LOOP;
        SELECT p.data_domain_id INTO primary_id FROM "datahub-center".dh_modeling_business_process p
        WHERE p.id = (row_data->>'business_process_id')::bigint AND p.tenant_id = tenant AND p.deleted = 0;
        IF primary_id IS NOT NULL AND (row_data->>'data_domain_id')::bigint IS NOT NULL
           AND primary_id <> (row_data->>'data_domain_id')::bigint THEN
            RAISE EXCEPTION 'Model data domain must match process primary domain' USING ERRCODE='23514';
        END IF;
        IF row_data->>'business_process_id' IS NOT NULL AND row_data->>'subject_domain_id' IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_subject_domain_process_rel r
                           WHERE r.tenant_id=tenant AND r.deleted=0
                             AND r.business_process_id=(row_data->>'business_process_id')::bigint
                             AND r.subject_domain_id=(row_data->>'subject_domain_id')::bigint) THEN
            RAISE EXCEPTION 'Model subject domain and process are not associated' USING ERRCODE='23514';
        END IF;
    ELSIF tbl IN ('dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_business_process','dh_modeling_dw_layer')
       AND (deleting OR (tbl = 'dh_modeling_business_process' AND TG_OP = 'UPDATE'
                         AND old_data->>'data_domain_id' IS DISTINCT FROM row_data->>'data_domain_id')) THEN
        ref_field := CASE tbl WHEN 'dh_modeling_data_domain' THEN 'data_domain_id'
            WHEN 'dh_modeling_subject_domain' THEN 'subject_domain_id'
            WHEN 'dh_modeling_dw_layer' THEN 'layer_id' ELSE 'business_process_id' END;
        FOREACH model_table IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model','dh_modeling_physical_model']
        LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE %I=$1 AND tenant_id=$2 AND deleted=0
                AND ($3 OR $4 IS NOT NULL OR (data_domain_id IS NOT NULL AND data_domain_id IS DISTINCT FROM $5)))', model_table, ref_field)
                INTO found_row USING object_id, tenant, deleting, (old_data->>'data_domain_id')::bigint,
                    (row_data->>'data_domain_id')::bigint;
            IF found_row THEN
                RAISE EXCEPTION 'Planning object is referenced by a model; cannot delete or move ownership' USING ERRCODE='23514';
            END IF;
        END LOOP;
        IF deleting AND tbl = 'dh_modeling_data_domain' AND (
            EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_business_process p
                   WHERE p.tenant_id=tenant AND p.data_domain_id=object_id AND p.deleted=0)
            OR EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel r
                      WHERE r.tenant_id=tenant AND r.data_domain_id=object_id AND r.deleted=0)) THEN
            RAISE EXCEPTION 'Data domain is referenced by a business process' USING ERRCODE='23514';
        END IF;
    END IF;
    IF tbl = 'dh_modeling_subject_domain' AND deleting AND EXISTS (
        SELECT 1 FROM "datahub-center".dh_modeling_subject_domain_process_rel r
        WHERE r.tenant_id=tenant AND r.subject_domain_id=object_id AND r.deleted=0) THEN
        RAISE EXCEPTION 'Subject domain is referenced by a process' USING ERRCODE='23514';
    END IF;
    IF tbl = 'dh_modeling_subject_domain_process_rel' AND TG_OP <> 'INSERT'
       AND (deleting OR old_data->>'subject_domain_id' IS DISTINCT FROM row_data->>'subject_domain_id'
            OR old_data->>'business_process_id' IS DISTINCT FROM row_data->>'business_process_id') THEN
        FOREACH model_table IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model','dh_modeling_physical_model']
        LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE subject_domain_id=$1
                AND business_process_id=$2 AND tenant_id=$3 AND deleted=0)', model_table)
                INTO found_row USING (old_data->>'subject_domain_id')::bigint,
                    (old_data->>'business_process_id')::bigint, tenant;
            IF found_row THEN RAISE EXCEPTION 'Subject-process association is referenced by a model' USING ERRCODE='23514'; END IF;
        END LOOP;
    END IF;
    IF tbl IN ('dh_modeling_business_process_supporting_domain_rel','dh_modeling_subject_domain_process_rel') AND NOT deleting THEN
        SELECT p.data_domain_id INTO primary_id FROM "datahub-center".dh_modeling_business_process p
        WHERE p.id=(row_data->>'business_process_id')::bigint AND p.tenant_id=tenant AND p.deleted=0;
        IF NOT FOUND THEN RAISE EXCEPTION 'Association process missing or belongs to another tenant' USING ERRCODE='23514'; END IF;
        ref_field := CASE tbl WHEN 'dh_modeling_subject_domain_process_rel' THEN 'subject_domain_id' ELSE 'data_domain_id' END;
        ref_table := CASE tbl WHEN 'dh_modeling_subject_domain_process_rel' THEN 'dh_modeling_subject_domain' ELSE 'dh_modeling_data_domain' END;
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND tenant_id=$2 AND deleted=0)',ref_table)
            INTO found_row USING (row_data->>ref_field)::bigint, tenant;
        IF NOT found_row THEN RAISE EXCEPTION 'Association target missing or belongs to another tenant' USING ERRCODE='23514'; END IF;
        IF tbl='dh_modeling_business_process_supporting_domain_rel'
           AND (primary_id IS NULL OR primary_id=(row_data->>'data_domain_id')::bigint) THEN
            RAISE EXCEPTION 'Supporting domain requires a different confirmed primary domain' USING ERRCODE='23514';
        END IF;
    END IF;
    IF tbl = 'dh_modeling_business_process' AND NOT deleting AND row_data->>'data_domain_id' IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_data_domain d
                       WHERE d.id=(row_data->>'data_domain_id')::bigint AND d.tenant_id=tenant AND d.deleted=0) THEN
            RAISE EXCEPTION 'Process primary domain missing or belongs to another tenant' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel r
                   WHERE r.business_process_id=object_id AND r.tenant_id=tenant AND r.deleted=0
                     AND r.data_domain_id=(row_data->>'data_domain_id')::bigint) THEN
            RAISE EXCEPTION 'Primary and supporting domains cannot overlap' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $guard$;

DO $install$
DECLARE tbl text;
BEGIN
    FOREACH tbl IN ARRAY ARRAY[
        'dh_modeling_concept_model','dh_modeling_logic_model','dh_modeling_physical_model',
        'dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_business_process','dh_modeling_dw_layer',
        'dh_modeling_subject_domain_process_rel','dh_modeling_business_process_supporting_domain_rel']
    LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS modeling_ownership_reference_guard ON "datahub-center".%I', tbl);
        EXECUTE format('CREATE TRIGGER modeling_ownership_reference_guard BEFORE INSERT OR UPDATE OR DELETE ON "datahub-center".%I
                        FOR EACH ROW EXECUTE FUNCTION "datahub-center".modeling_ownership_reference_guard()', tbl);
    END LOOP;
    FOREACH tbl IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model','dh_modeling_physical_model']
    LOOP
        EXECUTE format('COMMENT ON COLUMN "datahub-center".%I.data_domain_id IS %L', tbl,
            '独立于技术分层的业务数据域；指定业务过程时须与其主数据域一致；草稿允许为空');
        IF tbl <> 'dh_modeling_concept_model' THEN
            EXECUTE format('COMMENT ON COLUMN "datahub-center".%I.classification_status IS %L', tbl,
                '上次保存时的归属评估结果；当前规划状态请使用只读归属检查确认；该结果不代表已满足全部发布条件');
        END IF;
        EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON "datahub-center".%I(tenant_id,data_domain_id) WHERE deleted=0',
            'idx_' || replace(tbl,'dh_modeling_','') || '_domain', tbl);
    END LOOP;
END $install$;
COMMIT;

-- Migration: 0017 建模检测范围、协作取消与分批续跑
-- Purpose: 增加检测范围、持久扫描游标、消费者心跳并将取消中的任务纳入租户唯一活动约束
-- Depends on: 0016_modeling_ownership-check-repair.sql 及其全部前置迁移
-- Target: 已有 PostgreSQL 数据库的 "datahub-center" 模式；升级前暂停建模服务及 modelCheckJob
-- Repeatable: 可重复执行；新增列采用存在性判断，活动索引在同一事务中重建
-- Rollback: 不删除历史数据；旧程序不识别取消状态和游标，回退前须停止消费者、等待或人工终止活动任务，并保留新增列。不得执行历史回退脚本。
-- 风险：重建唯一索引会持锁；锁等待超过五秒则回滚。脚本不转换含义不明的历史字段精度，也不重写发布快照。
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';
SELECT pg_advisory_xact_lock(hashtextextended('datahub:modeling:check:0017', 0));
ALTER TABLE "datahub-center".dh_modeling_model_check
    ADD COLUMN IF NOT EXISTS scope_config jsonb,
    ADD COLUMN IF NOT EXISTS last_model_id bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS last_heartbeat_time timestamp;
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.scope_config
    IS '检测范围快照：模型编号列表、数据域、数据源，各条件取交集；空值表示全部启用模型，按已发布版本匹配';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.last_model_id
    IS '本轮已扫描到的模型编号；每批完成后持久化，下一轮从其后继续';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.last_heartbeat_time
    IS '最近一次执行者续租或让出批次的时间，不由页面查询更新';
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check.task_status
    IS '任务状态：排队中（QUEUED）、运行中（RUNNING）、取消中（CANCEL_REQUESTED）、已取消（CANCELLED）、已完成（SUCCESS）、失败（FAILED）；取消保留已完成结果';
ALTER TABLE "datahub-center".dh_modeling_model_check_config
    ADD COLUMN IF NOT EXISTS last_dispatch_time timestamp;
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check_config.last_dispatch_time
    IS '最近一次调度消费者进入本租户的时间；定时开关关闭时仍消费手动任务并更新心跳';
ALTER TABLE "datahub-center".dh_modeling_model_check_result
    ALTER COLUMN drift_type TYPE varchar(32);
COMMENT ON COLUMN "datahub-center".dh_modeling_model_check_result.drift_type
    IS '检测分类：一致（CONSISTENT）、设计领先（DESIGN_AHEAD）、实库漂移（RUNTIME_DRIFT）、双向冲突（CONFLICT）、无基线（NO_BASELINE）、表不存在（MISSING_TABLE）、读取失败（READ_FAILED）、快照缺失（SNAPSHOT_MISSING）、字段精度待确认（FIELD_CONTRACT_UNCONFIRMED）；读取失败或待确认不能证明实库漂移';
DROP INDEX IF EXISTS "datahub-center".uk_modeling_check_active_tenant;
CREATE UNIQUE INDEX uk_modeling_check_active_tenant
    ON "datahub-center".dh_modeling_model_check (tenant_id)
    WHERE deleted = 0 AND task_status IN ('QUEUED', 'RUNNING', 'CANCEL_REQUESTED');
COMMIT;

-- Migration: 0018 平台模式与 PostgreSQL 官方扩展初始化
-- Purpose: 使用官方扩展管理三元组检索和通用 GiST 类型，避免全量导出内部函数造成依赖顺序错误
-- Depends on: 0017_modeling_check-operations.sql 及其全部前置迁移；新库由全量基线提前建立模式和扩展
-- Target: 已有 PostgreSQL 数据库；账号须具备安装扩展的权限，服务端须提供 btree_gist 和 pg_trgm
-- Repeatable: 可重复执行；模式和扩展使用存在性判断，已安装扩展不迁移所属模式
-- Rollback: 不自动删除扩展，避免级联删除依赖索引；如需回退应先核对扩展依赖并恢复升级前备份
-- 风险：若旧库存在自行创建的同名扩展内部对象但没有扩展登记，本脚本会失败并回滚；不得使用级联删除处理冲突。
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';
CREATE SCHEMA IF NOT EXISTS "datahub-center";
CREATE EXTENSION IF NOT EXISTS btree_gist WITH SCHEMA "datahub-center";
CREATE EXTENSION IF NOT EXISTS pg_trgm WITH SCHEMA "datahub-center";
COMMIT;

-- Migration: 0019 数据研发生产发布与可靠执行（已按 0034 去除项目与环境维度后裁剪）
-- Purpose: 冻结数据开发保存版本、持久化运行状态，并关联独立质量检查；项目协作与环境绑定已由 0034 移除，新库不再创建
-- Depends on: 0018_modeling_extension-bootstrap.sql 及其前置迁移；已有完整平台表结构
-- Target: 已有 PostgreSQL 平台库；新库使用已包含本迁移的全量基线
-- Repeatable: 可重复执行；新增对象使用存在性保护，存量适配仅作用于尚无发布或执行标识的数据
-- Rollback: 不自动删除运行及授权历史；回退应用前备份新增数据，并由管理员恢复已明确批准的旧调度配置
-- 风险：升级前暂停研发调度并确认旧执行器已退出。本迁移关闭没有冻结版本的旧调度，旧在途记录保留为未知；
-- 风险：无法可靠推断项目的数据保持未归属，需管理员明确归属后重新发布。索引创建持锁，建议维护窗口执行。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';

