UPDATE dh_dataforge_dev_task SET status = 0, schedule_status = 0, next_run_time = NULL
WHERE current_version_id IS NULL AND (status <> 0 OR schedule_status <> 0);
UPDATE dh_dataforge_etl_pipeline SET status = 0, schedule_status = 0, next_run_time = NULL
WHERE published_config_json IS NULL AND (status <> 0 OR schedule_status <> 0);
UPDATE dh_dataforge_dev_record SET status = 'UNKNOWN',
    last_error = '升级前运行缺少持久提交标识，请核查外部作业后人工确认'
WHERE run_key IS NULL AND status IN ('RUNNING','SUBMITTING');
UPDATE dh_dataforge_etl_record SET run_status = 6,
    log = coalesce(log, '') || E'\n升级前执行缺少所有权令牌，需核查后人工确认'
WHERE execution_token IS NULL AND run_status IN (1,2);

-- 研发任务名称在租户内唯一（ETL 流程名称唯一索引 uk_dh_dataforge_etl_pipeline_name 由基线创建）。
CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_dataforge_dev_task_name
    ON dh_dataforge_dev_task(tenant_id, name) WHERE deleted = 0;

CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_dev_run_key
    ON dh_dataforge_dev_record(tenant_id, run_key) WHERE deleted = 0 AND run_key IS NOT NULL;
-- 已有未知记录保留原样，由运行服务检查阻断；新协议运行由数据库保证同任务不重叠。
CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_dev_active_run
    ON dh_dataforge_dev_record(tenant_id, task_id)
    WHERE deleted = 0 AND version_id IS NOT NULL AND (status IN ('SUBMITTING','RUNNING','UNKNOWN','CANCEL_REQUESTED')
        OR (status = 'SUCCESS' AND quality_status IN ('PENDING','UNKNOWN')));
CREATE INDEX IF NOT EXISTS idx_dataforge_dev_reconcile
    ON dh_dataforge_dev_record(status, heartbeat_time, lease_until) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_dataforge_dev_dependency
    ON dh_dataforge_dev_record(tenant_id, task_id, business_date, version_id);
CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_etl_active_run
    ON dh_dataforge_etl_record(tenant_id, pipeline_id)
    WHERE deleted = 0 AND (run_status IN (1,2) OR (run_status = 6 AND execution_token IS NOT NULL)
        OR (run_status = 3 AND quality_status IN ('PENDING','UNKNOWN')));
CREATE INDEX IF NOT EXISTS idx_dataforge_etl_reconcile
    ON dh_dataforge_etl_record(tenant_id, run_status, lease_until) WHERE deleted = 0;
CREATE UNIQUE INDEX IF NOT EXISTS uk_governance_quality_run_key
    ON dh_governance_quality_task_instance(tenant_id, request_key)
    WHERE deleted = 0 AND request_key IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_governance_quality_run_recovery
    ON dh_governance_quality_task_instance(tenant_id, instance_status, lease_until)
    WHERE deleted = 0 AND request_key IS NOT NULL;
COMMENT ON COLUMN dh_dataforge_dev_record.status IS '执行状态：WAITING等待、SUBMITTING提交中、RUNNING运行、UNKNOWN待确认、CANCEL_REQUESTED取消中、SUCCESS成功、FAILED失败、STOPPED停止';
COMMENT ON COLUMN dh_dataforge_etl_record.run_status IS '执行状态：1等待、2运行、3成功、4失败、5停止、6待确认';
COMMENT ON COLUMN dh_governance_quality_task_instance.instance_status IS '执行状态：QUEUED排队、RUNNING运行、SUCCESS完成、FAILED失败、UNKNOWN待确认';

-- 新库只保留独立写入权限；数据开发保存直接冻结版本，不再创建发布权限。
-- system_menu.id 默认走 system_menu_id_seq，但该序列通常未 OWNED BY 列，pg_get_serial_sequence 会得到 NULL，INSERT 随后复用已存在的 id。
SELECT setval(
    '"datahub-center"."system_menu_id_seq"',
    GREATEST(COALESCE((SELECT max(id) FROM "datahub-center".system_menu), 1), 1),
    true
);
INSERT INTO "datahub-center".system_menu(name, permission, type, sort, parent_id, status)
SELECT v.name, v.permission, 3, 90, m.parent_id, 0
FROM (VALUES
    ('研发写入调试','dataforge:dev-task:write','dataforge:dev-task:run')
) v(name,permission,source_permission)
JOIN LATERAL (
    SELECT parent_id
    FROM "datahub-center".system_menu
    WHERE permission = v.source_permission AND deleted = 0
    ORDER BY id
    LIMIT 1
) m ON true
WHERE NOT EXISTS (
    SELECT 1
    FROM "datahub-center".system_menu existing
    WHERE existing.permission = v.permission AND existing.deleted = 0
);

-- 独立权限由现有超级管理员/租户管理员在角色管理中按职责分配，禁止按旧保存权限自动授权。
COMMIT;

