-- ----------------------------
-- 以下同步块与对应编号迁移一致，必须在上方完整的基础结构、初始化数据与历史增量之后按编号顺序执行。
-- 这些块原先插在相关表定义附近；其前置的历史增量、系统菜单、站内信模板及供应、资产账本在更后面才创建，
-- 因此集中放在此处，除另有说明外语句内容保持不变。
-- ----------------------------

-- 当前运行协议结构同步自编号增量；仅供新库，已有库执行对应编号迁移。
-- Migration: 0038 数据同步与可视化流程持久运行协议
-- Purpose: 增加稳定执行身份、不可变快照、执行占位、租约、停止命令与结果核查记录
-- Depends on: 0037_dataforge_database-connection-status.sql；当前本地基线四张数据同步与可视化流程表
-- Target: 已有平台库；全新数据库使用已同步的全量基线；本脚本不证明既有库已执行历史迁移
-- Repeatable: 是；加法字段和索引可重复执行，历史运行只对协议零记录进行安全隔离
-- Rollback: 不自动回滚；新增运行与命令记录不得丢弃，须备份并核查所有占位后另编回退迁移
-- 风险：持有表结构锁并回填历史运行；必须暂停全部旧版调度和执行节点后在维护窗口执行。
-- 历史活动记录不假定已停止；保留未知结果占位。发现同任务多个活动记录将报告编号并整事务回滚。
-- 不删除目标数据，不伪造历史运行标识，不将停止受理解释成外部执行已终止。

BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';

-- 当前基线允许省略旧代码已使用的发布及质量字段，在此按现行领域契约补齐。
ALTER TABLE dh_dataforge_access
    ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS published_revision integer,
    ADD COLUMN IF NOT EXISTS published_execution_user_id bigint,
    ADD COLUMN IF NOT EXISTS published_config_json jsonb,
    ADD COLUMN IF NOT EXISTS schedule_generation bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS latest_run_id bigint;
COMMENT ON COLUMN dh_dataforge_access.revision IS '草稿配置版本';
COMMENT ON COLUMN dh_dataforge_access.published_revision IS '已发布配置版本';
COMMENT ON COLUMN dh_dataforge_access.published_execution_user_id IS '已发布执行主体';
COMMENT ON COLUMN dh_dataforge_access.published_config_json IS '不可变发布快照，仅保存数据源引用';
COMMENT ON COLUMN dh_dataforge_access.schedule_generation IS '发布和调度代次';
COMMENT ON COLUMN dh_dataforge_access.latest_run_id IS '最近领取的执行记录编号';

ALTER TABLE dh_dataforge_etl_pipeline
    ADD COLUMN IF NOT EXISTS quality_task_id bigint,
    ADD COLUMN IF NOT EXISTS revision integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS published_revision integer,
    ADD COLUMN IF NOT EXISTS published_execution_user_id bigint,
    ADD COLUMN IF NOT EXISTS published_config_json jsonb,
    ADD COLUMN IF NOT EXISTS schedule_generation bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS latest_run_id bigint;
COMMENT ON COLUMN dh_dataforge_etl_pipeline.quality_task_id IS '绑定的质量任务编号';
COMMENT ON COLUMN dh_dataforge_etl_pipeline.revision IS '草稿配置版本';
COMMENT ON COLUMN dh_dataforge_etl_pipeline.published_revision IS '已发布配置版本';
COMMENT ON COLUMN dh_dataforge_etl_pipeline.published_execution_user_id IS '已发布执行主体';
COMMENT ON COLUMN dh_dataforge_etl_pipeline.published_config_json IS '不可变发布快照';
COMMENT ON COLUMN dh_dataforge_etl_pipeline.schedule_generation IS '发布和调度代次';
COMMENT ON COLUMN dh_dataforge_etl_pipeline.latest_run_id IS '最近领取的执行记录编号';

ALTER TABLE dh_dataforge_access_task
    ADD COLUMN IF NOT EXISTS protocol_version smallint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS run_key varchar(256),
    ADD COLUMN IF NOT EXISTS request_hash varchar(64),
    ADD COLUMN IF NOT EXISTS scheduled_time timestamp(6),
    ADD COLUMN IF NOT EXISTS schedule_generation bigint,
    ADD COLUMN IF NOT EXISTS execution_stage varchar(32),
    ADD COLUMN IF NOT EXISTS execution_token varchar(64),
    ADD COLUMN IF NOT EXISTS lease_owner varchar(128),
    ADD COLUMN IF NOT EXISTS lease_until timestamp(6),
    ADD COLUMN IF NOT EXISTS occupies_slot boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS stop_requested boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS stop_request_id varchar(128),
    ADD COLUMN IF NOT EXISTS stop_request_hash varchar(64),
    ADD COLUMN IF NOT EXISTS stop_actor_id bigint,
    ADD COLUMN IF NOT EXISTS stop_requested_at timestamp(6),
    ADD COLUMN IF NOT EXISTS effect_state varchar(16),
    ADD COLUMN IF NOT EXISTS review_required boolean NOT NULL DEFAULT false,
    ADD COLUMN IF NOT EXISTS row_version bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS attempt_count integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS next_attempt_at timestamp(6),
    ADD COLUMN IF NOT EXISTS reconcile_token varchar(64),
    ADD COLUMN IF NOT EXISTS reconcile_lease_until timestamp(6),
    ADD COLUMN IF NOT EXISTS reconcile_attempts integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS next_reconcile_at timestamp(6),
    ADD COLUMN IF NOT EXISTS resolution_json jsonb,
    ADD COLUMN IF NOT EXISTS config_json jsonb,
    ADD COLUMN IF NOT EXISTS execution_user_id bigint,
    ADD COLUMN IF NOT EXISTS release_revision integer;
-- 0049、0051、0053 的新增列按编号先后追加，使新库物理列顺序与已升级库一致。
ALTER TABLE dh_dataforge_access_task
    ADD COLUMN IF NOT EXISTS resource_ids jsonb,
    ADD COLUMN IF NOT EXISTS sync_evidence jsonb,
    ADD COLUMN IF NOT EXISTS sync_start_position bigint;
COMMENT ON COLUMN dh_dataforge_access_task.protocol_version IS '运行协议版本：历史为零，新执行显式写一';
COMMENT ON COLUMN dh_dataforge_access_task.sync_evidence IS '实际同步配置修订及批次结果；不等于目标可见性或整改水位证明；历史为空';
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_sync_clock (
    tenant_id bigint NOT NULL,
    database_id bigint NOT NULL,
    last_position bigint NOT NULL DEFAULT 0 CHECK (last_position >= 0),
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted=0),
    PRIMARY KEY (tenant_id,database_id)
);
-- 表用途说明：目标数据源事务顺序；不可删除或按时间清理
COMMENT ON TABLE "datahub-center".dh_dataforge_sync_clock IS '数据同步-目标事务序号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.tenant_id IS '租户编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.database_id IS '目标数据源编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.last_position IS '最后已分配顺序；仅有先后含义，不是数据版本';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.create_time IS '创建时间，不用于跨服务因果判断';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_clock.deleted IS '禁止逻辑删除，避免重用顺序';

CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_sync_boundary (
    tenant_id bigint NOT NULL,
    request_key varchar(160) NOT NULL,
    database_id bigint NOT NULL,
    configuration_revision varchar(128) NOT NULL,
    product varchar(32) NOT NULL,
    schema_name varchar(1024) NOT NULL,
    table_name varchar(1024) NOT NULL,
    position bigint NOT NULL CHECK (position > 0),
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted=0),
    PRIMARY KEY (tenant_id,request_key),
    UNIQUE (tenant_id,database_id,position),
    FOREIGN KEY (tenant_id,database_id) REFERENCES "datahub-center".dh_dataforge_sync_clock(tenant_id,database_id)
);
-- 表用途说明：受信治理请求的持久提交后边界；重试复用，不代表目标数据可见
COMMENT ON TABLE "datahub-center".dh_dataforge_sync_boundary IS '数据同步-治理提交边界';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.tenant_id IS '租户编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.request_key IS '治理提交与对象绑定的稳定幂等键';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.database_id IS '目标数据源编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.configuration_revision IS '首次边界的目标配置修订';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.product IS '目标数据库产品';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.schema_name IS '已授权目标模式';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.table_name IS '已授权目标表';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.position IS '同目标事务顺序边界，不是同步水位';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.creator IS '首次请求的执行人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.create_time IS '创建时间，不用于跨节点排序';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.updater IS '更新人';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_dataforge_sync_boundary.deleted IS '禁止删除幂等身份';

ALTER TABLE "datahub-center".dh_dataforge_access_task ADD COLUMN IF NOT EXISTS sync_start_position bigint;
COMMENT ON COLUMN "datahub-center".dh_dataforge_access_task.sync_start_position IS '实际绑定与启动同事务分配的目标顺序；历史为空，不按结束时间回填';
CREATE INDEX idx_dh_access_sync_evidence_target ON dh_dataforge_access_task
    (tenant_id, (config_json->>'targetDatabaseId'), id DESC)
    WHERE protocol_version=1 AND (deleted=0 OR occupies_slot);
COMMENT ON INDEX idx_dh_access_sync_evidence_target IS '按租户及冻结目标数据源查询有界批次；不等于到数或完整写入者清单';
COMMENT ON COLUMN dh_dataforge_access_task.run_key IS '租户内稳定运行标识，软删除后仍禁止复用';
COMMENT ON COLUMN dh_dataforge_access_task.request_hash IS '首次受理命令摘要';
COMMENT ON COLUMN dh_dataforge_access_task.scheduled_time IS '本次原定执行时间';
COMMENT ON COLUMN dh_dataforge_access_task.schedule_generation IS '本次调度代次';
COMMENT ON COLUMN dh_dataforge_access_task.execution_stage IS '执行阶段：准备、开始产生外部效果或提交已发送';
COMMENT ON COLUMN dh_dataforge_access_task.execution_token IS '单次执行领取令牌';
COMMENT ON COLUMN dh_dataforge_access_task.lease_owner IS '执行节点实例标识';
COMMENT ON COLUMN dh_dataforge_access_task.lease_until IS '基于数据库时钟的执行租约截止时间';
COMMENT ON COLUMN dh_dataforge_access_task.occupies_slot IS '独立执行占位，未知结果和未核查部分写入继续占位';
COMMENT ON COLUMN dh_dataforge_access_task.stop_requested IS '已接受停止请求，不表示执行已退出';
COMMENT ON COLUMN dh_dataforge_access_task.stop_request_id IS '首次停止命令标识';
COMMENT ON COLUMN dh_dataforge_access_task.stop_request_hash IS '首次停止命令摘要';
COMMENT ON COLUMN dh_dataforge_access_task.stop_actor_id IS '停止操作人编号';
COMMENT ON COLUMN dh_dataforge_access_task.stop_requested_at IS '停止命令受理时间';
COMMENT ON COLUMN dh_dataforge_access_task.effect_state IS '外部效果：无、完整、部分或未知';
COMMENT ON COLUMN dh_dataforge_access_task.review_required IS '是否仍需人工核查';
COMMENT ON COLUMN dh_dataforge_access_task.row_version IS '状态版本，隔离人工决策与迟到对账';
COMMENT ON COLUMN dh_dataforge_access_task.attempt_count IS '执行领取累计尝试次数';
COMMENT ON COLUMN dh_dataforge_access_task.next_attempt_at IS '下次执行领取时间';
COMMENT ON COLUMN dh_dataforge_access_task.reconcile_token IS '独立对账令牌';
COMMENT ON COLUMN dh_dataforge_access_task.reconcile_lease_until IS '独立对账租约截止时间';
COMMENT ON COLUMN dh_dataforge_access_task.reconcile_attempts IS '连续对账失败次数';
COMMENT ON COLUMN dh_dataforge_access_task.next_reconcile_at IS '下次结果对账时间';
COMMENT ON COLUMN dh_dataforge_access_task.resolution_json IS '脱敏人工核查依据与结果';
COMMENT ON COLUMN dh_dataforge_access_task.config_json IS '受理时的不可变配置，仅保存数据源引用';
COMMENT ON COLUMN dh_dataforge_access_task.execution_user_id IS '本次执行主体';
COMMENT ON COLUMN dh_dataforge_access_task.release_revision IS '本次发布配置版本';

ALTER TABLE dh_dataforge_etl_record
    ADD COLUMN IF NOT EXISTS protocol_version smallint NOT NULL DEFAULT 0,
