    ADD COLUMN IF NOT EXISTS resource_ids jsonb;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_etl_record".resource_ids
    IS '受理时冻结的平台数据源编号数组；空数组表示无平台数据源，NULL 表示旧运行资源范围未知';
ALTER TABLE "datahub-center"."dh_dataforge_access_task"
    ADD COLUMN IF NOT EXISTS resource_ids jsonb;
COMMENT ON COLUMN "datahub-center"."dh_dataforge_access_task".resource_ids
    IS '受理时冻结的平台数据源编号数组；空数组表示无平台数据源，NULL 表示旧运行资源范围未知';

-- 在修改任何历史状态前检查所有活动记录，包括被逻辑删除但尚无退出证据的记录。
DO $run_preflight$
DECLARE
    conflict text;
BEGIN
    SELECT string_agg('租户='||tenant_id||' 流程='||pipeline_id||' 记录='||ids, '; ')
      INTO conflict
      FROM (SELECT tenant_id,pipeline_id,string_agg(id::text,',' ORDER BY id) ids
              FROM dh_dataforge_etl_record
             WHERE occupies_slot OR (protocol_version=0 AND
                    (run_status IN (1,2,6) OR (run_status=3 AND quality_status IN ('PENDING','UNKNOWN'))))
             GROUP BY tenant_id,pipeline_id HAVING count(*)>1) conflicts;
    IF conflict IS NOT NULL THEN
        RAISE EXCEPTION '可视化流程历史占位冲突，请先核查退出与输出结果：%', conflict;
    END IF;
    SELECT string_agg('租户='||tenant_id||' 任务='||data_access_id||' 记录='||ids, '; ')
      INTO conflict
      FROM (SELECT tenant_id,data_access_id,string_agg(id::text,',' ORDER BY id) ids
              FROM dh_dataforge_access_task
             WHERE occupies_slot OR (protocol_version=0 AND run_status IN (1,2,5))
             GROUP BY tenant_id,data_access_id HAVING count(*)>1) conflicts;
    IF conflict IS NOT NULL THEN
        RAISE EXCEPTION '数据同步历史占位冲突，请先核查退出与输出结果：%', conflict;
    END IF;
END
$run_preflight$;

-- 旧等待占位索引与新队列不兼容：仅替换目录中精确识别的旧谓词，未知策略必须中止并核查。
DO $run_indexes$
DECLARE
    candidate record;
    old_etl text := '((deleted = 0) AND ((run_status = ANY (ARRAY[1, 2])) OR ((run_status = 6) AND (execution_token IS NOT NULL)) OR ((run_status = 3) AND ((quality_status)::text = ANY ((ARRAY[''PENDING''::character varying, ''UNKNOWN''::character varying])::text[])))))';
BEGIN
    FOR candidate IN
        SELECT i.indexrelid::regclass::text AS index_name,t.relname AS table_name,
               i.indnkeyatts AS key_count,(i.indexprs IS NULL) AS no_expressions,
               pg_get_expr(i.indpred,i.indrelid) AS predicate,
               EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conindid=i.indexrelid) AS owns_constraint,
               ARRAY(SELECT a.attname::text
                       FROM unnest(i.indkey) WITH ORDINALITY k(attnum,ord)
                       JOIN pg_attribute a ON a.attrelid=i.indrelid AND a.attnum=k.attnum
                      WHERE k.ord<=i.indnkeyatts ORDER BY a.attname) AS key_names
          FROM pg_index i JOIN pg_class t ON t.oid=i.indrelid
         WHERE i.indisunique AND t.relnamespace=current_schema()::regnamespace
           AND t.relname IN ('dh_dataforge_etl_record','dh_dataforge_access_task')
    LOOP
        IF candidate.key_names NOT IN (ARRAY['pipeline_id','tenant_id'],ARRAY['data_access_id','tenant_id']) THEN
            CONTINUE;
        END IF;
        IF candidate.key_count=2 AND candidate.no_expressions
                AND candidate.predicate='occupies_slot' AND NOT candidate.owns_constraint THEN
            CONTINUE;
        END IF;
        IF candidate.key_count=2 AND candidate.no_expressions AND NOT candidate.owns_constraint AND (
            (candidate.table_name='dh_dataforge_etl_record' AND candidate.predicate=old_etl)
            OR candidate.predicate='((deleted = 0) AND (run_status = ANY (ARRAY[1, 2])))'
            OR (candidate.table_name='dh_dataforge_access_task'
                AND candidate.predicate='((deleted = 0) AND (run_status = ANY (ARRAY[1, 2, 5])))')) THEN
            EXECUTE format('DROP INDEX %s', candidate.index_name);
        ELSE
            RAISE EXCEPTION '存在未经识别的任务级唯一约束或索引 %，禁止自动删除；请先审核其策略：%',
                candidate.index_name, candidate.predicate;
        END IF;
    END LOOP;
END
$run_indexes$;

-- 历史协议允许缺少原始身份；新版必须具备稳定身份、主体和对象快照，不能用空值绕过唯一约束。
DO $run_identity$
DECLARE
    target_table text;
    constraint_name text;
BEGIN
    FOREACH target_table IN ARRAY ARRAY['dh_dataforge_etl_record','dh_dataforge_access_task'] LOOP
        constraint_name := target_table || '_protocol_identity';
        IF NOT EXISTS(SELECT 1 FROM pg_constraint
                       WHERE conrelid=target_table::regclass AND conname=constraint_name) THEN
            EXECUTE format('ALTER TABLE %I ADD CONSTRAINT %I CHECK (
                protocol_version IN (0,1) AND row_version>=0 AND attempt_count>=0 AND reconcile_attempts>=0
                AND (protocol_version=0 OR (
                    run_key IS NOT NULL AND length(btrim(run_key))>0
                    AND request_hash IS NOT NULL AND request_hash ~ ''^[0-9a-f]{64}$''
                    AND config_json IS NOT NULL AND jsonb_typeof(config_json)=''object''
                    AND execution_user_id IS NOT NULL
                    AND schedule_generation IS NOT NULL AND schedule_generation>=0
                    AND execution_stage IS NOT NULL AND execution_stage IN (''PREPARE'',''EXECUTION_STARTED'',''SUBMIT_SENT'')
                    AND effect_state IS NOT NULL AND effect_state IN (''NONE'',''COMPLETE'',''PARTIAL'',''UNKNOWN'')
                    AND run_status IN (1,2,3,4,5,6))))', target_table,constraint_name);
        END IF;
    END LOOP;
END
$run_identity$;

UPDATE dh_dataforge_etl_record
   SET run_status=6,occupies_slot=true,review_required=true,effect_state='UNKNOWN',
       execution_stage='EXECUTION_STARTED',execution_token=NULL,lease_until=NULL
 WHERE protocol_version=0 AND (run_status IN (1,2,6)
        OR (run_status=3 AND quality_status IN ('PENDING','UNKNOWN')));
UPDATE dh_dataforge_access_task
   SET run_status=5,occupies_slot=true,review_required=true,effect_state='UNKNOWN',
       execution_stage='EXECUTION_STARTED',execution_token=NULL,lease_until=NULL
 WHERE protocol_version=0 AND run_status IN (1,2,5);

-- 稳定身份和占位索引均不按逻辑删除过滤，避免软删除绕过并发与请求幂等约束。
