CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_access_run_key
    ON dh_dataforge_access_task(tenant_id,run_key) WHERE run_key IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_etl_run_slot
    ON dh_dataforge_etl_record(tenant_id,pipeline_id) WHERE occupies_slot;
CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_access_run_slot
    ON dh_dataforge_access_task(tenant_id,data_access_id) WHERE occupies_slot;
CREATE INDEX IF NOT EXISTS idx_dataforge_etl_run_waiting
    ON dh_dataforge_etl_record(tenant_id,next_attempt_at,id)
