CREATE SEQUENCE IF NOT EXISTS dh_dataforge_run_command_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_run_command (
    id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_run_command_seq'),
    tenant_id bigint NOT NULL,
    domain varchar(16) NOT NULL CHECK(domain IN ('ACCESS','ETL')),
    record_id bigint NOT NULL,
    request_id varchar(128) NOT NULL,
    action varchar(32) NOT NULL CHECK(action IN ('STOP','RESOLVE','SCHEDULE_CHANGE')),
    request_hash varchar(64) NOT NULL,
    actor_id bigint NOT NULL,
    expected_version bigint,
    result_json jsonb NOT NULL,
    before_json jsonb,
    after_json jsonb,
    creator varchar(64) DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0
);
-- 表用途说明：数据同步与可视化流程控制命令的持久回执与审计
