-- Migration: 0039 数据同步与可视化流程人工核查独立权限
-- Purpose: 为人工确认未知结果设置独立按钮权限，不向既有角色自动授予
-- Depends on: 0038_dataforge_run-protocol.sql；当前库须有完整 system_menu 及两类运行权限与父菜单
-- Target: 已有平台库；新库须使用完整且已补齐本增量的基线，当前截断基线不可用于新建库
-- Repeatable: 是；同语义权限保留原编号，缺失前置或冲突权限整事务回滚
-- Rollback: 不自动回滚；撤销应先核查并删除新权限的角色关联，再逻辑删除本次新增按钮
-- 风险：短时锁菜单表；不修改既有角色授权。序列取号不可回滚，但不影响业务数据。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '2min';

DO $run_resolution_permissions$
DECLARE
    entry record;
    parent_menu bigint;
    new_id bigint;
    existing_id bigint;
    matches integer;
    menu_sequence regclass;
BEGIN
    IF to_regclass('system_menu') IS NULL THEN
        RAISE EXCEPTION '缺少完整 system_menu 前置表；请核对当前基线完整性，不能从截断基线发布新库';
    END IF;
    LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
    menu_sequence := COALESCE(pg_get_serial_sequence('system_menu', 'id')::regclass,
                              to_regclass('system_menu_seq'));
    IF menu_sequence IS NULL THEN
        RAISE EXCEPTION '缺少 system_menu 主键序列，须先核对现有库结构';
    END IF;
    FOR entry IN SELECT * FROM (VALUES
        ('dataforge:etl:run', 'dataforge:etl:resolve', 'ETL运行结果核查'),
        ('dataforge:access:run', 'dataforge:access:resolve', '数据接入运行结果核查')
    ) AS requested(run_permission, resolution_permission, button_name)
    LOOP
        SELECT count(*), min(m.parent_id) INTO matches, parent_menu
        FROM system_menu m JOIN system_menu p ON p.id=m.parent_id AND p.deleted=0 AND p.type IN (1,2)
        WHERE m.permission=entry.run_permission AND m.deleted=0 AND m.type=3;
        IF matches <> 1 THEN
            RAISE EXCEPTION '运行权限 % 缺失、重复或无有效父菜单，停止权限迁移', entry.run_permission;
        END IF;
        SELECT count(*), min(id) INTO matches, existing_id
        FROM system_menu WHERE permission=entry.resolution_permission;
        IF matches > 0 THEN
            IF matches <> 1 OR NOT EXISTS (
                SELECT 1 FROM system_menu WHERE id=existing_id AND parent_id=parent_menu
                    AND type=3 AND status=0 AND deleted=0
            ) THEN
                RAISE EXCEPTION '人工核查权限 % 已存在冲突或被禁用/删除，不能自动改写授权策略',
                    entry.resolution_permission;
            END IF;
            CONTINUE;
        END IF;
        new_id := nextval(menu_sequence);
        WHILE EXISTS (SELECT 1 FROM system_menu WHERE id=new_id) LOOP
            new_id := nextval(menu_sequence);
        END LOOP;
        INSERT INTO system_menu (
            id,name,permission,type,sort,parent_id,path,icon,component,component_name,
            status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted
        ) VALUES (
            new_id,entry.button_name,entry.resolution_permission,3,99,parent_menu,'','',NULL,NULL,
            0,true,true,true,'migration:0039','migration:0039',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0
        );
    END LOOP;
END;
$run_resolution_permissions$;
COMMIT;

-- 已同步 0040 活动监控索引；结构块与编号迁移一致。
-- Migration: 0040 数据同步与可视化流程活动监控索引
-- Purpose: 限定监控聚合到活动/待核查记录与启用的周期排期，避免反复扫描全部历史
-- Depends on: 0038_dataforge_run-protocol.sql；四张任务/运行表及运行协议字段已就绪
-- Target: 已有平台 PostgreSQL；新库同步结构块，但当前截断基线仍不可直接导入
-- Repeatable: 是；同名且同定义索引存在时跳过，可在维护窗口重复执行
-- Rollback: 仅新增非唯一索引，不修改数据；核对无其他依赖后可单独删除本脚本四个索引
-- 风险：非并发建索引会短时阻塞表写入，须安排维护窗口；锁等待五秒、单语句两分钟，失败整事务回滚。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '2min';

CREATE INDEX IF NOT EXISTS idx_df_etl_metrics_active
    ON dh_dataforge_etl_record (run_status, create_time)
    WHERE occupies_slot OR (deleted=0 AND (run_status IN (1,6) OR review_required));
COMMENT ON INDEX idx_df_etl_metrics_active IS 'ETL监控活动集合，含软删除但仍占位及等待核查记录';

CREATE INDEX IF NOT EXISTS idx_df_access_metrics_active
    ON dh_dataforge_access_task (run_status, create_time)
    WHERE occupies_slot OR (deleted=0 AND (run_status IN (1,5) OR review_required));
COMMENT ON INDEX idx_df_access_metrics_active IS '接入监控活动集合，结果未知编码为五，保留全部未释放占位';

CREATE INDEX IF NOT EXISTS idx_df_etl_metrics_due
    ON dh_dataforge_etl_pipeline (next_run_time)
    WHERE deleted=0 AND status=1 AND schedule_status=1 AND task_type=2;
COMMENT ON INDEX idx_df_etl_metrics_due IS 'ETL已启用周期排期积压监控';

CREATE INDEX IF NOT EXISTS idx_df_access_metrics_due
    ON dh_dataforge_access (next_run_time)
    WHERE deleted=0 AND status=1 AND task_type=3;
COMMENT ON INDEX idx_df_access_metrics_due IS '接入已发布周期排期积压监控';

COMMIT;

-- Migration: 0042 资产来源交付冻结、租约隔离与续期幂等
-- Purpose: 增加固定命令载荷、领取令牌、版本隔离、未知结果对账及重新审批的续期身份
-- Depends on: 0041_supply_grant-source-protocol.sql；当前本地基线三张资产来源、市场申请及交付操作表
-- Target: 已有平台 PostgreSQL 库；新库结构同步至基线但当前基线仍不完整
-- Repeatable: 是；新增列与索引可重放，仅历史未冻结操作进入待复核
-- Rollback: 不自动回滚；不得丢弃交付意图、未知结果和来源序号，须停节点备份后另编迁移
-- 风险：需结构锁和历史状态回填，必须停止全部旧交付及审批节点后在维护窗口执行。
-- 不从当前申请重建旧操作载荷，不将未知交付推测为成功或失败。

BEGIN;
SET LOCAL search_path TO "datahub-center";
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
DO $$
BEGIN
    IF to_regclass('"datahub-center".dh_asset_grant_source') IS NULL
        OR to_regclass('"datahub-center".dh_market_resource_apply') IS NULL
        OR to_regclass('"datahub-center".dh_market_delivery_operation') IS NULL THEN
        RAISE EXCEPTION '来源交付协议缺少前置资产来源、申请或交付操作表';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_asset_grant_source WHERE tenant_id IS NULL OR revision < 0)
        OR EXISTS (SELECT 1 FROM dh_market_resource_apply WHERE tenant_id IS NULL)
        OR EXISTS (SELECT 1 FROM dh_market_delivery_operation WHERE tenant_id IS NULL
            OR operation_id IS NULL OR btrim(operation_id) = '') THEN
        RAISE EXCEPTION '来源交付存在空身份、空租户或负来源序号，须人工核查';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_market_delivery_operation
        GROUP BY tenant_id, operation_id HAVING count(*) > 1) THEN
        RAISE EXCEPTION '存在重复交付操作身份，不能猜测哪次结果有效';
    END IF;
END $$;

ALTER TABLE dh_asset_grant_source
    ADD COLUMN IF NOT EXISTS source_key varchar(256),
    ADD COLUMN IF NOT EXISTS source_status varchar(32) NOT NULL DEFAULT 'REVIEW_REQUIRED';
COMMENT ON COLUMN dh_asset_grant_source.source_key IS '稳定来源身份，历史证据确认后生成，不包含审批版本';
COMMENT ON COLUMN dh_asset_grant_source.source_status IS '有效、暂停、终态撤销或待复核，与审批状态独立';
COMMENT ON COLUMN dh_asset_grant_source.revision IS '来源单调序号，禁止复用审批修订号';
UPDATE dh_asset_grant_source SET source_status = 'REVOKED'
    WHERE revoked <> 0 AND source_status = 'REVIEW_REQUIRED';
CREATE UNIQUE INDEX IF NOT EXISTS uk_asset_source_stable_key
    ON dh_asset_grant_source (tenant_id, source_key) WHERE source_key IS NOT NULL;

ALTER TABLE dh_market_resource_apply
    ADD COLUMN IF NOT EXISTS renewal_of_apply_id bigint,
    ADD COLUMN IF NOT EXISTS renewal_operation_id varchar(128),
    ADD COLUMN IF NOT EXISTS source_revision bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS renewal_requested_end_time timestamp(6);
COMMENT ON COLUMN dh_market_resource_apply.renewal_of_apply_id IS '续期所对应的原申请，新申请仍需重新审批';
COMMENT ON COLUMN dh_market_resource_apply.renewal_operation_id IS '续期请求稳定幂等身份，重复请求返回同一新申请';
COMMENT ON COLUMN dh_market_resource_apply.renewal_requested_end_time IS '首次续期请求的不可变截止时间，空值表示历史请求证据缺失，禁止从可变申请期限回填';
COMMENT ON COLUMN dh_market_resource_apply.source_revision IS '交付来源序号，仅按确认后的最高来源序号递增';
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_renewal_operation
    ON dh_market_resource_apply (tenant_id, renewal_operation_id) WHERE renewal_operation_id IS NOT NULL;
-- 0050：普通在途申请、同一原申请的有效续期由数据库唯一索引限制。
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_active_pending_apply
    ON dh_market_resource_apply (tenant_id,apply_user_id,asset_id)
    WHERE deleted=0 AND status IN (0,1,8);
COMMENT ON INDEX uk_market_active_pending_apply IS '同租户同申请人同资产只允许一份在途申请，普通与续期共用';
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_active_renewal_parent
    ON dh_market_resource_apply (tenant_id,renewal_of_apply_id)
    WHERE deleted=0 AND renewal_of_apply_id IS NOT NULL AND status IN (0,1,2,8);
COMMENT ON INDEX uk_market_active_renewal_parent IS '同一原申请只允许一份在途或已批准的有效续期子申请';

ALTER TABLE dh_market_delivery_operation
    ADD COLUMN IF NOT EXISTS protocol_version smallint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS source_revision bigint,
    ADD COLUMN IF NOT EXISTS payload_json jsonb,
    ADD COLUMN IF NOT EXISTS payload_hash varchar(64),
    ADD COLUMN IF NOT EXISTS claim_token varchar(64),
    ADD COLUMN IF NOT EXISTS row_version bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS resolution_status varchar(32) NOT NULL DEFAULT 'REVIEW_REQUIRED',
    ADD COLUMN IF NOT EXISTS lease_until timestamp(6);
ALTER TABLE dh_market_delivery_operation ALTER COLUMN operation_id TYPE varchar(128);
COMMENT ON COLUMN dh_market_delivery_operation.operation_id IS '租户内不可复用的稳定交付操作身份';
COMMENT ON COLUMN dh_market_delivery_operation.protocol_version IS '交付协议版本，零为未确认的旧协议';
COMMENT ON COLUMN dh_market_delivery_operation.source_revision IS '冻结命令的来源单调序号';
COMMENT ON COLUMN dh_market_delivery_operation.payload_json IS '批准时冻结的完整命令，重试不得读取当前申请重建';
COMMENT ON COLUMN dh_market_delivery_operation.payload_hash IS '含租户及完整授权语义的固定命令摘要';
COMMENT ON COLUMN dh_market_delivery_operation.claim_token IS '每次领取的新隔离令牌，旧节点不得回写';
COMMENT ON COLUMN dh_market_delivery_operation.row_version IS '交付记录的并发更新版本';
COMMENT ON COLUMN dh_market_delivery_operation.resolution_status IS '未确认、结果未知、已确认或待复核的对账状态';
COMMENT ON COLUMN dh_market_delivery_operation.lease_until IS '以数据库时间计算的领取租约截止时刻';
CREATE UNIQUE INDEX IF NOT EXISTS uk_market_source_delivery_operation
    ON dh_market_delivery_operation (tenant_id, operation_id);
CREATE INDEX IF NOT EXISTS idx_market_delivery_due_v2
    ON dh_market_delivery_operation (tenant_id, status, next_retry_time, lease_until, id)
    WHERE protocol_version = 2 AND deleted = 0;
-- 0043：申请最近一次交付操作的查询索引。
CREATE INDEX IF NOT EXISTS idx_market_delivery_apply_latest
    ON dh_market_delivery_operation (tenant_id, apply_id, source_revision DESC, id DESC)
    WHERE deleted = 0;
COMMENT ON INDEX idx_market_delivery_apply_latest IS '按申请取最近一次交付操作，用于呈现真实交付结果';
COMMIT;

-- 质量工单独立复检轮次结构（0045）
-- 补齐质量运行持久协议的安装前置，已有列不改类型、不改历史数据。
ALTER TABLE "datahub-center".dh_governance_quality_task_instance
    ADD COLUMN IF NOT EXISTS request_key varchar(180),
    ADD COLUMN IF NOT EXISTS execution_user_id bigint,
    ADD COLUMN IF NOT EXISTS definition_snapshot text,
    ADD COLUMN IF NOT EXISTS lease_until timestamp;
COMMENT ON COLUMN "datahub-center".dh_governance_quality_task_instance.request_key IS '租户内稳定运行幂等键';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_task_instance.execution_user_id IS '运行授权身份';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_task_instance.definition_snapshot IS '检查任务对象规则的不可变快照，不含连接凭据';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_task_instance.lease_until IS '运行心跳租约截止时间';
CREATE UNIQUE INDEX IF NOT EXISTS uk_quality_instance_request
    ON "datahub-center".dh_governance_quality_task_instance (tenant_id, request_key)
    WHERE request_key IS NOT NULL;

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_governance_quality_work_order_recheck_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_quality_work_order_recheck (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_governance_quality_work_order_recheck_seq'::regclass),
    work_order_id bigint NOT NULL,
    submission_id bigint NOT NULL,
    attempt_no integer NOT NULL CHECK (attempt_no > 0),
    request_id varchar(64),
    request_key varchar(180) NOT NULL,
    instance_id bigint NOT NULL,
    requested_by bigint NOT NULL,
    requested_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status varchar(32) NOT NULL,
    comparable_flag smallint NOT NULL DEFAULT 0 CHECK (comparable_flag IN (0, 1)),
    last_error varchar(512),
    finished_at timestamp,
    creator varchar(64) DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    tenant_id bigint NOT NULL DEFAULT 0,
    CONSTRAINT ck_quality_recheck_status CHECK (status IN ('RUNNING', 'PASS', 'FAIL', 'WAITING_DATA', 'ERROR', 'OBSOLETE')),
    CONSTRAINT uk_quality_recheck_attempt UNIQUE (tenant_id, submission_id, attempt_no),
    CONSTRAINT uk_quality_recheck_request UNIQUE (tenant_id, work_order_id, request_id),
    CONSTRAINT uk_quality_recheck_run UNIQUE (tenant_id, request_key),
    CONSTRAINT uk_quality_recheck_instance UNIQUE (tenant_id, instance_id)
);
CREATE INDEX IF NOT EXISTS idx_quality_recheck_running
    ON "datahub-center".dh_governance_quality_work_order_recheck (tenant_id, id)
    WHERE deleted = 0 AND status = 'RUNNING';
-- 表说明（原文）：质量工单复检轮次台账，已结束轮次保留，不以新结果覆盖历史
COMMENT ON TABLE "datahub-center".dh_governance_quality_work_order_recheck IS '数据质量-工单复检轮次';
ALTER TABLE "datahub-center".dh_governance_quality_work_order_recheck ADD COLUMN IF NOT EXISTS evidence_json text;
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.evidence_json IS '版本化的复检判定依据，关联原实例与本轮实例，不含原始数据或凭据';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.id IS '主键';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.work_order_id IS '所属工单编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.submission_id IS '所属整改提交编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.attempt_no IS '同一整改提交下递增的复检轮次';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.request_id IS '发起命令的幂等编号，历史轮次无法确定时为空';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.request_key IS '本轮质量运行的稳定幂等键';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.instance_id IS '本轮唯一质量任务实例编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.requested_by IS '发起人编号，历史缺少命令时保留提交人';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.requested_at IS '本轮发起时间，历史缺少命令时保留提交时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.status IS '运行中、通过、未通过、等待数据、异常、资格失效';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.comparable_flag IS '是否具有可比资格，零否一是';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.last_error IS '复检判定原因摘要';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.finished_at IS '判定或资格失效时间，历史终态缺失时为空';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.creator IS '创建者';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.updater IS '更新者';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.update_time IS '更新时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.deleted IS '逻辑删除标记';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_work_order_recheck.tenant_id IS '租户编号';


-- 人工核查权限与增量脚本保持一致；缺少前置表时明确失败，不静默跳过权限安装。
-- 0057 推送核查独立权限；完整新库菜单初始化后执行，不向角色自动授权。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
DO $push_resolution_permission$
DECLARE
    parent_menu bigint;
    matches integer;
    existing_id bigint;
    new_id bigint;
    menu_sequence regclass;
BEGIN
    IF to_regclass('system_menu') IS NULL THEN
        RAISE EXCEPTION '缺少完整 system_menu，停止迁移；截断基线不能初始化新库';
    END IF;
    LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
    SELECT count(*), min(m.parent_id) INTO matches, parent_menu
    FROM system_menu m JOIN system_menu p ON p.id=m.parent_id AND p.deleted=0 AND p.type IN (1,2)
    WHERE m.permission='dataforge:data-push:run' AND m.deleted=0 AND m.type=3;
    IF matches <> 1 THEN
        RAISE EXCEPTION '推送运行权限缺失、重复或无有效父菜单，停止迁移';
    END IF;
    SELECT count(*), min(id) INTO matches, existing_id
    FROM system_menu WHERE permission='dataforge:data-push:resolve';
    IF matches > 0 THEN
        IF matches <> 1 OR NOT EXISTS (SELECT 1 FROM system_menu WHERE id=existing_id
                AND parent_id=parent_menu AND type=3 AND status=0 AND deleted=0) THEN
            RAISE EXCEPTION '推送核查权限已有冲突或已被禁用/删除，不自动改写授权策略';
        END IF;
        RETURN;
    END IF;
    menu_sequence := COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
    IF menu_sequence IS NULL THEN
        RAISE EXCEPTION '缺少 system_menu 主键序列';
    END IF;
    new_id := nextval(menu_sequence);
    WHILE EXISTS (SELECT 1 FROM system_menu WHERE id=new_id) LOOP
        new_id := nextval(menu_sequence);
    END LOOP;
    INSERT INTO system_menu (id,name,permission,type,sort,parent_id,path,icon,component,component_name,
        status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
    VALUES (new_id,'推送未知结果核查','dataforge:data-push:resolve',3,99,parent_menu,'','',NULL,NULL,
        0,true,true,true,'migration:0057','migration:0057',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
END;
$push_resolution_permission$;

-- 主数据派发核查独立权限，已包含增量0062；完整菜单初始化后执行，不自动授予角色。
DO $master_resolution_permission$
DECLARE
    parent_menu bigint;
    matches integer;
    existing_id bigint;
    new_id bigint;
    menu_sequence regclass;
BEGIN
    IF to_regclass('system_menu') IS NULL THEN
        RAISE EXCEPTION '缺少完整 system_menu，停止迁移；截断基线不能初始化新库';
    END IF;
    LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
    SELECT count(*), min(m.parent_id) INTO matches, parent_menu
    FROM system_menu m JOIN system_menu p ON p.id=m.parent_id AND p.deleted=0 AND p.type IN (1,2)
    WHERE m.permission='governance:master-distribute:run' AND m.deleted=0 AND m.type=3;
    IF matches <> 1 THEN
        RAISE EXCEPTION '主数据派发运行权限缺失、重复或无有效父菜单，停止迁移';
    END IF;
    SELECT count(*), min(id) INTO matches, existing_id
    FROM system_menu WHERE permission='governance:master-distribute:resolve';
    IF matches > 0 THEN
        IF matches <> 1 OR NOT EXISTS (SELECT 1 FROM system_menu WHERE id=existing_id
                AND parent_id=parent_menu AND type=3 AND status=0 AND deleted=0) THEN
            RAISE EXCEPTION '主数据派发核查权限已有冲突或已被禁用/删除，不自动改写授权策略';
        END IF;
        RETURN;
    END IF;
    menu_sequence := COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
    IF menu_sequence IS NULL THEN
        RAISE EXCEPTION '缺少 system_menu 主键序列';
    END IF;
    new_id := nextval(menu_sequence);
    WHILE EXISTS (SELECT 1 FROM system_menu WHERE id=new_id) LOOP
        new_id := nextval(menu_sequence);
    END LOOP;
    INSERT INTO system_menu (id,name,permission,type,sort,parent_id,path,icon,component,component_name,
        status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
    VALUES (new_id,'主数据派发未知结果核查','governance:master-distribute:resolve',3,99,parent_menu,'','',NULL,NULL,
        0,true,true,true,'migration:0062','migration:0062',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
END;
$master_resolution_permission$;

-- 0059 推送告警模板；恢复完整新库定义后须在站内信模板表初始化之后执行。
DO $push_alert_template$
DECLARE
    matches integer;
    template_sequence regclass;
    new_id bigint;
BEGIN
    IF to_regclass('"datahub-center".system_notify_template') IS NULL THEN
        RAISE EXCEPTION '缺少完整站内信模板表，截断基线不可用于新库初始化';
    END IF;
    LOCK TABLE "datahub-center".system_notify_template IN SHARE ROW EXCLUSIVE MODE;
    SELECT count(*) INTO matches FROM "datahub-center".system_notify_template WHERE code='dataforge_push_outcome';
    IF matches > 0 THEN
        IF matches <> 1 OR NOT EXISTS (SELECT 1 FROM "datahub-center".system_notify_template
            WHERE code='dataforge_push_outcome' AND deleted=0 AND status=0
              AND content='数据推送任务【{taskName}】执行【{executeNo}】发生【{outcome}】。告警编号：{alertId}。这是事件通知，请以执行日志当前状态为准。'
              AND params::jsonb='["taskName","executeNo","outcome","alertId"]'::jsonb) THEN
            RAISE EXCEPTION '推送告警模板冲突或禁用，请人工核查，禁止静默覆盖';
        END IF;
    ELSE
        template_sequence := COALESCE(pg_get_serial_sequence('"datahub-center".system_notify_template','id')::regclass,
            to_regclass('"datahub-center".system_notify_template_seq'));
        IF template_sequence IS NULL THEN RAISE EXCEPTION '缺少站内信模板主键序列'; END IF;
        LOOP
            new_id := nextval(template_sequence);
            EXIT WHEN NOT EXISTS (SELECT 1 FROM "datahub-center".system_notify_template WHERE id=new_id);
        END LOOP;
        INSERT INTO "datahub-center".system_notify_template
            (id,name,code,type,nickname,content,params,status,remark,creator,updater,deleted)
        VALUES (new_id,'推送关键终态告警','dataforge_push_outcome',2,'数据中台',
            '数据推送任务【{taskName}】执行【{executeNo}】发生【{outcome}】。告警编号：{alertId}。这是事件通知，请以执行日志当前状态为准。',
            '["taskName","executeNo","outcome","alertId"]',0,'通知允许重复，以告警编号关联；不代表业务重跑','1','1',0);
    END IF;
END;
$push_alert_template$;

-- 主数据派发告警模板，已包含增量0064；完整站内信模板表初始化后执行，不覆盖已有策略。
DO $master_distribute_alert_template$
DECLARE
    matches integer;
    template_sequence regclass;
    new_id bigint;
BEGIN
    IF to_regclass('"datahub-center".system_notify_template') IS NULL THEN
        RAISE EXCEPTION '缺少完整站内信模板表，截断基线不可用于新库初始化';
    END IF;
    LOCK TABLE "datahub-center".system_notify_template IN SHARE ROW EXCLUSIVE MODE;
    SELECT count(*) INTO matches FROM "datahub-center".system_notify_template WHERE code='governance_master_distribute_outcome';
    IF matches > 0 THEN
        IF matches <> 1 OR NOT EXISTS (SELECT 1 FROM "datahub-center".system_notify_template
            WHERE code='governance_master_distribute_outcome' AND deleted=0 AND status=0
              AND content='主数据派发任务【{taskName}】执行【{runId}】发生【{outcome}】。告警编号：{alertId}。这是事件通知，请以执行日志当前状态为准。'
              AND params::jsonb='["taskName","runId","outcome","alertId"]'::jsonb) THEN
            RAISE EXCEPTION '主数据派发告警模板冲突或禁用，请人工核查，禁止静默覆盖';
        END IF;
    ELSE
        template_sequence := COALESCE(pg_get_serial_sequence('"datahub-center".system_notify_template','id')::regclass,
            to_regclass('"datahub-center".system_notify_template_seq'));
        IF template_sequence IS NULL THEN RAISE EXCEPTION '缺少站内信模板主键序列'; END IF;
        LOOP
            new_id := nextval(template_sequence);
            EXIT WHEN NOT EXISTS (SELECT 1 FROM "datahub-center".system_notify_template WHERE id=new_id);
        END LOOP;
        INSERT INTO "datahub-center".system_notify_template
            (id,name,code,type,nickname,content,params,status,remark,creator,updater,deleted)
        VALUES (new_id,'主数据派发关键终态告警','governance_master_distribute_outcome',2,'数据中台',
            '主数据派发任务【{taskName}】执行【{runId}】发生【{outcome}】。告警编号：{alertId}。这是事件通知，请以执行日志当前状态为准。',
            '["taskName","runId","outcome","alertId"]',0,'通知允许重复，以告警编号关联；不代表业务重跑','1','1',0);
    END IF;
END;
$master_distribute_alert_template$;
COMMIT;

-- 0070 孤立旧 ADMIN 处置结论审计结构开始。
DO $$
BEGIN
    IF to_regclass('"datahub-center".dh_supply_app_api') IS NULL THEN
        RAISE EXCEPTION '缺少 dh_supply_app_api 授权聚合前置，禁止从不完整基线升级';
    END IF;
END $$;
CREATE SEQUENCE IF NOT EXISTS dh_supply_legacy_admin_disposal_seq;
CREATE TABLE IF NOT EXISTS dh_supply_legacy_admin_disposal (
    id bigint PRIMARY KEY DEFAULT nextval('dh_supply_legacy_admin_disposal_seq'),
    tenant_id bigint NOT NULL,
    aggregate_id bigint NOT NULL,
    request_id varchar(36) NOT NULL CHECK (btrim(request_id) <> ''),
    request_hash varchar(64) NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
    decision varchar(32) NOT NULL CHECK (decision IN ('KEEP_ISOLATED','CONFIRM_REVOKED')),
    reason varchar(500) NOT NULL CHECK (btrim(reason) <> ''),
    basis varchar(500) NOT NULL CHECK (btrim(basis) <> ''),
    evidence jsonb NOT NULL CHECK (jsonb_typeof(evidence)='object'
        AND octet_length(evidence::text)<=8192
        AND (evidence->>'schemaVersion'='1') IS TRUE
