CREATE OR REPLACE FUNCTION "datahub-center".modeling_guard_layer_reference() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE v_layer record;
BEGIN
 IF NEW.deleted<>0 OR NEW.layer_id IS NULL THEN RETURN NEW; END IF;
 IF TG_OP='UPDATE' THEN
   IF NEW.layer_id IS NOT DISTINCT FROM OLD.layer_id AND NEW.tenant_id=OLD.tenant_id THEN RETURN NEW; END IF;
 END IF;
 SELECT node_type,status INTO v_layer FROM "datahub-center".dh_modeling_dw_layer
  WHERE id=NEW.layer_id AND tenant_id=NEW.tenant_id AND deleted=0 FOR SHARE;
 IF NOT FOUND OR v_layer.node_type<>'LAYER' OR v_layer.status<>0 THEN
   RAISE EXCEPTION '分层不存在、不是实际分层或已停用' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END $$;
CREATE OR REPLACE FUNCTION "datahub-center".modeling_guard_layer_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.deleted=OLD.deleted AND NEW.status=OLD.status AND NEW.node_type=OLD.node_type
    AND NEW.layer_code IS NOT DISTINCT FROM OLD.layer_code AND NEW.table_prefix IS NOT DISTINCT FROM OLD.table_prefix
    AND NEW.default_table_type IS NOT DISTINCT FROM OLD.default_table_type THEN RETURN NEW; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_concept_model WHERE tenant_id=OLD.tenant_id AND layer_id=OLD.id AND deleted=0)
 OR EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_logic_model WHERE tenant_id=OLD.tenant_id AND layer_id=OLD.id AND deleted=0)
 OR EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_physical_model WHERE tenant_id=OLD.tenant_id AND layer_id=OLD.id AND deleted=0) THEN
  RAISE EXCEPTION '分层已被模型引用，不能删除、停用或改变技术配置' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS trg_modeling_layer_change ON "datahub-center".dh_modeling_dw_layer;
CREATE TRIGGER trg_modeling_layer_change BEFORE UPDATE OR DELETE ON "datahub-center".dh_modeling_dw_layer FOR EACH ROW EXECUTE FUNCTION "datahub-center".modeling_guard_layer_change();
DROP TRIGGER IF EXISTS trg_modeling_layer_reference ON "datahub-center".dh_modeling_concept_model;
CREATE TRIGGER trg_modeling_layer_reference BEFORE INSERT OR UPDATE ON "datahub-center".dh_modeling_concept_model FOR EACH ROW EXECUTE FUNCTION "datahub-center".modeling_guard_layer_reference();
DROP TRIGGER IF EXISTS trg_modeling_layer_reference ON "datahub-center".dh_modeling_logic_model;
CREATE TRIGGER trg_modeling_layer_reference BEFORE INSERT OR UPDATE ON "datahub-center".dh_modeling_logic_model FOR EACH ROW EXECUTE FUNCTION "datahub-center".modeling_guard_layer_reference();
DROP TRIGGER IF EXISTS trg_modeling_layer_reference ON "datahub-center".dh_modeling_physical_model;
CREATE TRIGGER trg_modeling_layer_reference BEFORE INSERT OR UPDATE ON "datahub-center".dh_modeling_physical_model FOR EACH ROW EXECUTE FUNCTION "datahub-center".modeling_guard_layer_reference();

