CREATE OR REPLACE FUNCTION "datahub-center".modeling_audit_planning_change() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE old_data jsonb:='{}'; new_data jsonb:='{}'; detail jsonb:='{}'; key text; actor_text text; actor bigint; row_data jsonb; operation text:=TG_OP;
BEGIN
 IF TG_OP<>'INSERT' THEN old_data:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_data:=to_jsonb(NEW); END IF;
 row_data:=CASE WHEN TG_OP='DELETE' THEN old_data ELSE new_data END;
 IF TG_OP='UPDATE' AND old_data->>'deleted'='0' AND new_data->>'deleted'<>'0' THEN operation:='DELETE'; END IF;
 FOREACH key IN ARRAY ARRAY['name','code','layer_name','layer_code','parent_id','biz_category_id','data_domain_id',
  'status','node_type','table_prefix','default_table_type','leader_user_id','owner_user_id','owner_department',
  'scope_includes','scope_excludes','canonical_grain_definition','activity_definition','start_condition','end_condition','deleted'] LOOP
  IF old_data->key IS DISTINCT FROM new_data->key THEN
   detail:=detail||jsonb_build_object(key,jsonb_build_object('before',old_data->>key,'after',new_data->>key));
  END IF;
 END LOOP;
 IF detail='{}'::jsonb THEN RETURN COALESCE(NEW,OLD); END IF;
 -- 没有新的审计元信息时不把历史 updater 冒充本次操作者。
 actor_text:=CASE WHEN TG_OP='INSERT' THEN row_data->>'creator'
  WHEN TG_OP='UPDATE' AND (new_data->>'updater' IS DISTINCT FROM old_data->>'updater'
       OR new_data->>'update_time' IS DISTINCT FROM old_data->>'update_time') THEN row_data->>'updater'
  ELSE NULL END;
 BEGIN actor:=actor_text::bigint; EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN actor:=NULL; END;
 INSERT INTO "datahub-center".dh_modeling_planning_change(tenant_id,kind,object_id,actor_id,action,changes,creator,updater)
 VALUES((row_data->>'tenant_id')::bigint,TG_ARGV[0],(row_data->>'id')::bigint,actor,operation,detail,COALESCE(actor_text,''),COALESCE(actor_text,''));
 RETURN COALESCE(NEW,OLD);
END $$;
