CREATE TRIGGER trg_modeling_planning_audit AFTER INSERT OR UPDATE OR DELETE ON "datahub-center".dh_modeling_data_domain FOR EACH ROW EXECUTE FUNCTION "datahub-center".modeling_audit_planning_change('DATA_DOMAIN');
