-- 建模闭环菜单扩展：恢复完整系统菜单基线后执行。
-- Migration: 0080 建模业务对象与发布管理菜单
-- Purpose: 新增业务对象、模型发布入口及独立检查、部署和核验权限。
-- Depends on: 0079_modeling_closed-loop-schema.sql；完整 system_menu 和已有业务过程、逻辑模型、模型检测菜单。
-- Target: 已有 PostgreSQL 平台库；由系统管理员按职责授予新按钮权限。
-- Repeatable: 是；按组件和权限查找，已有冲突停止执行，不重复插入或自动覆盖角色授权。
-- Rollback: 先撤销新增权限的角色授权，再停用新增菜单；保留部署和版本历史。
-- 风险：短时锁菜单表；不把原发布权限自动升级为目标数据库部署权限。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
DO $modeling_menu$
DECLARE
 business_parent bigint;
 model_parent bigint;
 object_menu bigint;
 publish_menu bigint;
 menu_id bigint;
 matches integer;
 seq regclass;
 item record;
BEGIN
 IF to_regclass('system_menu') IS NULL THEN RAISE EXCEPTION '缺少完整系统菜单表，不能使用截断基线初始化'; END IF;
 LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*),min(parent_id) INTO matches,business_parent FROM system_menu
 WHERE deleted=0 AND type=2 AND trim(both '/' from component)='modeling/businessprocess/index';
 IF matches<>1 THEN RAISE EXCEPTION '请先确认唯一有效的业务过程菜单及组件映射'; END IF;
 SELECT count(*),min(parent_id) INTO matches,model_parent FROM system_menu
 WHERE deleted=0 AND type=2 AND trim(both '/' from component)='modeling/logicmodel/index';
 IF matches<>1 THEN RAISE EXCEPTION '请先确认唯一有效的逻辑模型菜单及组件映射'; END IF;
 seq := COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
 IF seq IS NULL THEN RAISE EXCEPTION '缺少系统菜单主键序列'; END IF;
 FOR item IN SELECT * FROM (VALUES
  ('业务对象','business-object','modeling/businessobject/index','ModelingBusinessObject','lucide:boxes',business_parent,30),
  ('模型发布','model-publish','modeling/modelpublish/index','ModelingModelPublish','lucide:rocket',model_parent,50)
 ) AS menus(name,path,component,component_name,icon,parent_id,sort) LOOP
  SELECT count(*),min(id) INTO matches,menu_id FROM system_menu WHERE trim(both '/' from component)=item.component;
  IF matches>1 THEN RAISE EXCEPTION '组件映射重复：%',item.component; END IF;
  IF matches=1 THEN
   IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id AND deleted=0 AND type=2 AND parent_id=item.parent_id) THEN
    RAISE EXCEPTION '菜单位置或状态冲突：%',item.name;
   END IF;
  ELSE
   menu_id:=nextval(seq);
   WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id) LOOP menu_id:=nextval(seq); END LOOP;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
   VALUES(menu_id,item.name,'',2,item.sort,item.parent_id,item.path,item.icon,item.component,item.component_name,0,true,true,true,'migration:0080','migration:0080',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
  END IF;
  IF item.component='modeling/businessobject/index' THEN object_menu:=menu_id; ELSE publish_menu:=menu_id; END IF;
 END LOOP;
 FOR item IN SELECT * FROM (VALUES
  ('查询业务对象','modeling:business-object:query',object_menu),
  ('创建业务对象','modeling:business-object:create',object_menu),
  ('编辑业务对象','modeling:business-object:update',object_menu),
  ('删除业务对象','modeling:business-object:delete',object_menu),
  ('发布业务对象','modeling:business-object:publish',object_menu),
  ('启停业务对象','modeling:business-object:status',object_menu),
  ('部署目标数据库','modeling:model:deploy',publish_menu),
  ('核验与补偿部署','modeling:model:deploy-reconcile',publish_menu),
  ('执行模型检查','modeling:model:check',publish_menu),
  ('配置定时检查','modeling:model:check-config',publish_menu)
 ) AS permissions(name,permission,parent_id) LOOP
  SELECT count(*),min(id) INTO matches,menu_id FROM system_menu WHERE permission=item.permission;
  IF matches>1 THEN RAISE EXCEPTION '权限重复：%',item.permission; END IF;
  IF matches=1 THEN
   IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id AND type=3 AND deleted=0 AND status=0) THEN
    RAISE EXCEPTION '权限已删除或停用，不能自动恢复：%',item.permission;
   END IF;
  ELSE
   menu_id:=nextval(seq);
   WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id) LOOP menu_id:=nextval(seq); END LOOP;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
   VALUES(menu_id,item.name,item.permission,3,99,item.parent_id,'','',NULL,NULL,0,true,true,true,'migration:0080','migration:0080',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
  END IF;
 END LOOP;
END;
$modeling_menu$;
COMMIT;

-- 类型化增量检查点（0086）
CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_access_checkpoint_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_access_checkpoint (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_access_checkpoint_seq'),
    tenant_id bigint NOT NULL,
    data_access_id bigint NOT NULL,
    schema_name varchar(1024) NOT NULL,
    table_name varchar(1024) NOT NULL,
    watermark_column varchar(1024) NOT NULL,
    checkpoint_json jsonb NOT NULL,
    revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
    owner_run_id bigint NOT NULL,
    creator varchar(64) DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CONSTRAINT dh_dataforge_access_checkpoint_payload_ck CHECK (
        jsonb_typeof(checkpoint_json)='object' AND COALESCE(
            checkpoint_json->>'version'='1'
            OR (checkpoint_json->>'version'='2'
                AND checkpoint_json->>'sourceProduct' IN ('MYSQL','ORACLE','SQLSERVER2000','SQLSERVER','POSTGRESQL','GREENPLUM','MARIADB','DB2','DM','KINGBASE','OSCAR','GBASE8A','HIVE','SQLITE3','SYBASE','DORIS','CLICKHOUSE','MONGODB','TIDB','TDENGINE','INFLUXDB3','STARROCKS','HIGHGO','OPENGAUSS','ELASTICSEARCH','OCEANBASE','UXDB')
                AND checkpoint_json->>'targetProduct' IN ('MYSQL','ORACLE','SQLSERVER2000','SQLSERVER','POSTGRESQL','GREENPLUM','MARIADB','DB2','DM','KINGBASE','OSCAR','GBASE8A','HIVE','SQLITE3','SYBASE','DORIS','CLICKHOUSE','MONGODB','TIDB','TDENGINE','INFLUXDB3','STARROCKS','HIGHGO','OPENGAUSS','ELASTICSEARCH','OCEANBASE','UXDB')
                AND checkpoint_json->>'bindingFingerprint' ~ '^[0-9a-f]{64}$'
                AND checkpoint_json->>'schemaFingerprint' ~ '^[0-9a-f]{64}$'
                AND checkpoint_json->>'targetSchemaFingerprint' ~ '^[0-9a-f]{64}$'
                AND jsonb_typeof(checkpoint_json->'complete')='boolean'
                AND CASE WHEN checkpoint_json->>'sequence' ~ '^(0|[1-9][0-9]{0,18})$'
                    THEN (checkpoint_json->>'sequence')::numeric<=9223372036854775807 ELSE false END
                AND (COALESCE(checkpoint_json->'fixedUpper','null'::jsonb)='null'::jsonb
                    OR (jsonb_typeof(checkpoint_json->'fixedUpper')='object'
                        AND checkpoint_json->'fixedUpper'->>'version'='1'
                        AND jsonb_typeof(checkpoint_json->'fixedUpper'->'values')='array'
                        AND jsonb_array_length(checkpoint_json->'fixedUpper'->'values') BETWEEN 1 AND 33))
                AND (
                    (checkpoint_json->>'lastCommitAcknowledgement'='NONE'
                        AND checkpoint_json->>'sequence'='0'
                        AND COALESCE(checkpoint_json->'applied','null'::jsonb)='null'::jsonb
                        AND COALESCE(checkpoint_json->'lastCommit','null'::jsonb)='null'::jsonb)
                    OR (checkpoint_json->>'sequence'<>'0'
                        AND jsonb_typeof(checkpoint_json->'applied')='object'
                        AND checkpoint_json->'applied'->>'version'='1'
                        AND jsonb_typeof(checkpoint_json->'applied'->'values')='array'
                        AND jsonb_array_length(checkpoint_json->'applied'->'values') BETWEEN 1 AND 33
                        AND jsonb_typeof(checkpoint_json->'fixedUpper')='object'
                        AND (
                            (checkpoint_json->>'lastCommitAcknowledgement'='JDBC_COMMIT_RETURNED'
                                AND COALESCE(checkpoint_json->'lastCommit','null'::jsonb)='null'::jsonb)
                            OR (checkpoint_json->>'lastCommitAcknowledgement'='POSTGRESQL_XID8_VERIFIED'
                                AND checkpoint_json->>'targetProduct'='POSTGRESQL'
                                AND jsonb_typeof(checkpoint_json->'lastCommit')='object'
                                AND checkpoint_json->'lastCommit'->>'schemaVersion'='1'
                                AND checkpoint_json->'lastCommit'->>'protocol'='POSTGRESQL_XID8_V1'
                                AND CASE WHEN checkpoint_json->'lastCommit'->>'transactionId' ~ '^[1-9][0-9]{0,19}$'
                                    THEN (checkpoint_json->'lastCommit'->>'transactionId')::numeric BETWEEN 3 AND 18446744073709551615 ELSE false END
                                AND checkpoint_json->'lastCommit'->>'routeFingerprint' ~ '^[0-9a-f]{64}$'
                                AND (COALESCE(checkpoint_json->'lastCommit'->'relationFingerprint','null'::jsonb)='null'::jsonb
                                    OR checkpoint_json->'lastCommit'->>'relationFingerprint' ~ '^[0-9a-f]{64}$'))
                        ))
                )
            ),false))
);
CREATE UNIQUE INDEX IF NOT EXISTS dh_dataforge_access_checkpoint_live_uk
    ON "datahub-center".dh_dataforge_access_checkpoint(tenant_id,data_access_id,schema_name,table_name) WHERE deleted=0;
