COMMENT ON COLUMN dh_asset_data_asset.stop_supply_time IS '停供意图提交时间，非远端撤权完成时间';

CREATE SEQUENCE IF NOT EXISTS dh_asset_catalog_link_operation_seq;
CREATE TABLE IF NOT EXISTS dh_asset_catalog_link_operation (
    id bigint PRIMARY KEY DEFAULT nextval('dh_asset_catalog_link_operation_seq'), tenant_id bigint NOT NULL,
    operation_id varchar(64) NOT NULL, asset_id bigint NOT NULL, table_id bigint NOT NULL,
    source_key varchar(256) NOT NULL, source_revision bigint NOT NULL CHECK (source_revision > 0),
    linked boolean NOT NULL, request_hash varchar(64) NOT NULL,
    status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','RUNNING','UNKNOWN','SUCCESS','MANUAL')),
    outcome varchar(20) NOT NULL DEFAULT 'UNCONFIRMED', attempts integer NOT NULL DEFAULT 0,
    claim_token varchar(64), lease_until timestamp, next_retry_time timestamp,
    last_error varchar(500), disposition_reason varchar(500),
    creator varchar(64) DEFAULT '', updater varchar(64) DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    UNIQUE(tenant_id,operation_id), UNIQUE(tenant_id,source_key,table_id,source_revision)
);
CREATE INDEX IF NOT EXISTS idx_asset_catalog_link_due ON dh_asset_catalog_link_operation(tenant_id,status,next_retry_time) WHERE deleted=0;
-- 表说明（原文）：资产元数据挂接持久交付意图与原始回执核查
COMMENT ON TABLE dh_asset_catalog_link_operation IS '数据资产-目录挂接操作';
COMMENT ON COLUMN dh_asset_catalog_link_operation.operation_id IS '跨重试不变的操作编号，与Governance回执关联';
COMMENT ON COLUMN dh_asset_catalog_link_operation.source_revision IS '目录与技术表维度单调来源版本，阻止晚到旧命令覆盖解绑';
COMMENT ON COLUMN dh_asset_catalog_link_operation.status IS '待发送、领取中、结果未知、已确认、待人工核查';
COMMENT ON COLUMN dh_asset_catalog_link_operation.disposition_reason IS '人工重核或受控重投原因，审计同时写入市场审计表';

CREATE TABLE IF NOT EXISTS dh_governance_catalog_link_source (
    tenant_id bigint NOT NULL, source_key varchar(256) NOT NULL, table_id bigint NOT NULL,
    source_revision bigint NOT NULL CHECK (source_revision>0), PRIMARY KEY(tenant_id,source_key,table_id)
);
CREATE TABLE IF NOT EXISTS dh_governance_catalog_link_receipt (
    tenant_id bigint NOT NULL, operation_id varchar(64) NOT NULL, source_key varchar(256) NOT NULL,
    table_id bigint NOT NULL, source_revision bigint NOT NULL, linked boolean NOT NULL,
    request_hash varchar(64) NOT NULL, outcome varchar(16) NOT NULL CHECK(outcome IN ('APPLIED','REJECTED')),
    reason varchar(100), create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(tenant_id,operation_id)
);
-- 表说明（原文）：元数据提供方目录来源版本墓碑，解绑后保留以拒绝旧请求
COMMENT ON TABLE dh_governance_catalog_link_source IS '元数据管理-目录来源版本';
-- 表说明（原文）：目录挂接幂等回执，与元数据状态在同一事务提交；不得按普通日志清理
COMMENT ON TABLE dh_governance_catalog_link_receipt IS '元数据管理-目录挂接回执';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.request_hash IS '原命令摘要，用于拒绝同操作编号的不同载荷';

COMMENT ON COLUMN dh_asset_catalog_link_operation.id IS '交付主键';
COMMENT ON COLUMN dh_asset_catalog_link_operation.tenant_id IS '租户编号';
COMMENT ON COLUMN dh_asset_catalog_link_operation.asset_id IS '资产编号，资产删除后仍保留交付证据';
COMMENT ON COLUMN dh_asset_catalog_link_operation.table_id IS '治理元数据表编号';
COMMENT ON COLUMN dh_asset_catalog_link_operation.source_key IS '目录来源标识，重建同一目录继续沿用来源版本';
COMMENT ON COLUMN dh_asset_catalog_link_operation.linked IS '是否挂接；否表示解绑';
COMMENT ON COLUMN dh_asset_catalog_link_operation.request_hash IS '冻结命令摘要';
COMMENT ON COLUMN dh_asset_catalog_link_operation.outcome IS '已知远端结果或未知';
COMMENT ON COLUMN dh_asset_catalog_link_operation.attempts IS '累计领取次数';
COMMENT ON COLUMN dh_asset_catalog_link_operation.claim_token IS '本次领取令牌，拒绝旧执行者回写';
COMMENT ON COLUMN dh_asset_catalog_link_operation.lease_until IS '领取租约截止时间';
COMMENT ON COLUMN dh_asset_catalog_link_operation.next_retry_time IS '下次自动核查时间';
COMMENT ON COLUMN dh_asset_catalog_link_operation.last_error IS '脱敏结果说明';
COMMENT ON COLUMN dh_asset_catalog_link_operation.creator IS '创建人';
COMMENT ON COLUMN dh_asset_catalog_link_operation.updater IS '更新人';
COMMENT ON COLUMN dh_asset_catalog_link_operation.create_time IS '创建时间';
COMMENT ON COLUMN dh_asset_catalog_link_operation.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_catalog_link_operation.deleted IS '逻辑删除标记；未决意图与来源版本不得删除';
COMMENT ON COLUMN dh_governance_catalog_link_source.tenant_id IS '租户编号';
COMMENT ON COLUMN dh_governance_catalog_link_source.source_key IS '资产目录来源标识';
COMMENT ON COLUMN dh_governance_catalog_link_source.table_id IS '元数据表编号';
COMMENT ON COLUMN dh_governance_catalog_link_source.source_revision IS '已接收的最大来源版本；解绑后保留墓碑';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.tenant_id IS '租户编号';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.operation_id IS '稳定跨重试操作编号';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.source_key IS '资产目录来源标识';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.table_id IS '元数据表编号';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.source_revision IS '本次来源版本';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.linked IS '本次挂接或解绑意图';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.outcome IS '应用成功或明确拒绝';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.reason IS '拒绝原因代码，不含业务数据';
COMMENT ON COLUMN dh_governance_catalog_link_receipt.create_time IS '回执创建时间';

DO $asset_catalog_menu$
DECLARE
 asset_menu bigint;
 menu_id bigint;
 matches integer;
 seq regclass;
 item record;
BEGIN
 LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*),min(id) INTO matches,asset_menu FROM system_menu
 WHERE deleted=0 AND status=0 AND type=2 AND trim(both '/' from component)='asset/dataasset/index';
 IF matches<>1 THEN RAISE EXCEPTION '需要唯一有效的数据资产菜单及组件映射'; END IF;
 seq:=COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
 IF seq IS NULL THEN RAISE EXCEPTION '缺少系统菜单主键序列'; END IF;
 FOR item IN SELECT * FROM (VALUES
  ('核查与重投目录挂接','asset:catalog-delivery:handle',asset_menu),
  ('停止全部供数','asset:data-asset:stop-supply',asset_menu)
 ) AS permissions(name,permission,parent_id) LOOP
  SELECT count(*),min(id) INTO matches,menu_id FROM system_menu WHERE permission=item.permission;
  IF matches>1 THEN RAISE EXCEPTION '权限重复：%',item.permission; END IF;
  IF matches=1 THEN
   IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id AND deleted=0 AND type=3 AND status=0)
   THEN RAISE EXCEPTION '权限已停用或冲突，不能自动恢复：%',item.permission; END IF;
  ELSE
   menu_id:=nextval(seq);
   WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id) LOOP menu_id:=nextval(seq); END LOOP;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
   VALUES(menu_id,item.name,item.permission,3,99,item.parent_id,'','',NULL,NULL,0,true,true,true,'migration:0085','migration:0085',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
  END IF;
 END LOOP;
END;
$asset_catalog_menu$;
COMMIT;


-- 本轮五模块修复同步：0089_governance_review-closure.sql
-- Migration: 0089 治理审批、采集隔离与失败投递处置闭环
-- Purpose: 冻结修复对象，持久采集租约，明确销毁审批模式，保存血缘重投审计
-- Depends on: 0088_dataforge_etl-target-batch.sql；完整治理基础表与 system_menu 已初始化
-- Target: 已有平台 PostgreSQL 库；新库由同步后的全量基线包含
-- Repeatable: 是；新增列、表与权限均检查存在性，不重复修改已有审批模式
-- Rollback: 不自动回滚；保留审批与运行证据，应用回退前停用新入口；删除证据列不可逆
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '2min';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS execution_token varchar(64);
COMMENT ON COLUMN dh_governance_meta_collect_task.execution_token IS '当前采集领取令牌';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS lease_until timestamp;
COMMENT ON COLUMN dh_governance_meta_collect_task.lease_until IS '当前采集租约截止时间';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS running_instance_id bigint;
COMMENT ON COLUMN dh_governance_meta_collect_task.running_instance_id IS '当前持久采集实例编号';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS approved_sql text;
COMMENT ON COLUMN dh_governance_quality_repair_order.approved_sql IS '批准的不可变修复SQL';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS approved_content_hash varchar(64);
COMMENT ON COLUMN dh_governance_quality_repair_order.approved_content_hash IS '批准内容摘要';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS approved_snapshot text;
COMMENT ON COLUMN dh_governance_quality_repair_order.approved_snapshot IS '批准的物理目标与数据源修订快照';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS approve_user_id bigint;
COMMENT ON COLUMN dh_governance_quality_repair_order.approve_user_id IS '批准人';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS approve_time timestamp;
COMMENT ON COLUMN dh_governance_quality_repair_order.approve_time IS '批准时间';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS content_version integer DEFAULT 0;
COMMENT ON COLUMN dh_governance_quality_repair_order.content_version IS '修复内容版本';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS max_affected_rows integer DEFAULT 10000;
COMMENT ON COLUMN dh_governance_quality_repair_order.max_affected_rows IS '单次修复最大影响行数';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS operation_id varchar(160);
COMMENT ON COLUMN dh_governance_quality_repair_order.operation_id IS '修复操作关联号';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS execution_token varchar(64);
COMMENT ON COLUMN dh_governance_quality_repair_order.execution_token IS '执行领取令牌';
ALTER TABLE dh_governance_quality_repair_order ADD COLUMN IF NOT EXISTS lease_until timestamp;
COMMENT ON COLUMN dh_governance_quality_repair_order.lease_until IS '执行租约截止时间';
CREATE INDEX IF NOT EXISTS idx_meta_collect_task_expired_lease ON dh_governance_meta_collect_task(lease_until,id) WHERE deleted=0 AND execution_token IS NOT NULL;
-- 旧修复批准不具有目标修订快照，未执行单重新送审，已成功及未知执行证据保留。
UPDATE dh_governance_quality_repair_order SET approve_status='PENDING'
 WHERE approve_status='PASSED' AND exec_status IN ('PENDING','FAILED_CONFIRMED')
 AND (approved_snapshot IS NULL OR approved_snapshot NOT LIKE '%"schemaVersion":2%');
COMMIT;


-- 本轮五模块修复同步：0090_supply_write-operation-control.sql
-- Migration: 0090 数据服务开放写台账与独立操作权限
-- Purpose: 持久记录开放写请求身份、未知回执和人工核查证据，补充追踪及拒绝日志查询。
-- Depends on: 0089_governance_review-closure.sql；已有完整 dh_supply_api、dh_supply_api_log、system_menu 及数据服务/数据源菜单。
-- Target: 已有 PostgreSQL 平台库；新库须先恢复并验证完整基线。
-- Repeatable: 是；加法式结构，菜单按唯一组件/权限查找，不自动授予旧角色新增权限。
-- Rollback: 回退应用前停用开放写API；台账及人工核查证据不得删除，否则业务键可能被再次执行。
-- 风险：不自动重新执行UNKNOWN，不修改历史发布或授权状态；短时菜单锁超过五秒则失败回滚。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';

CREATE SEQUENCE IF NOT EXISTS dh_supply_api_operation_seq;
CREATE TABLE IF NOT EXISTS dh_supply_api_operation (
 id bigint PRIMARY KEY DEFAULT nextval('dh_supply_api_operation_seq'),
 tenant_id bigint NOT NULL,
 app_id bigint NOT NULL,
 api_id bigint NOT NULL,
 release_id bigint NOT NULL,
 operation_key varchar(128) NOT NULL,
 request_hash varchar(64) NOT NULL,
 state varchar(32) NOT NULL CHECK(state IN ('RUNNING','SUCCEEDED','UNKNOWN','CONFIRMED_SUCCEEDED','CONFIRMED_NOT_APPLIED')),
 result_json text,
 lease_until timestamp NOT NULL,
 trace_id varchar(64),
 resolved_by bigint,
 resolution varchar(1000),
 evidence varchar(2000),
 resolved_at timestamp,
 creator varchar(64) NOT NULL DEFAULT '',
 create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '',
 update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0,
 CONSTRAINT uk_supply_api_operation_identity UNIQUE(tenant_id,app_id,api_id,operation_key)
);
-- 表说明（原文）：开放写请求台账；未知结果禁止自动重试，不自动删除业务键
COMMENT ON TABLE dh_supply_api_operation IS '数据服务-开放写请求台账';
COMMENT ON COLUMN dh_supply_api_operation.id IS '操作记录编号';
COMMENT ON COLUMN dh_supply_api_operation.tenant_id IS '受认证应用所属租户';
COMMENT ON COLUMN dh_supply_api_operation.app_id IS '受认证应用编号';
COMMENT ON COLUMN dh_supply_api_operation.api_id IS 'API编号';
COMMENT ON COLUMN dh_supply_api_operation.release_id IS '首次认领的不可变发布编号';
COMMENT ON COLUMN dh_supply_api_operation.operation_key IS '签名保护的稳定业务操作编号';
COMMENT ON COLUMN dh_supply_api_operation.request_hash IS '发布与规范化参数摘要，不存参数原文';
COMMENT ON COLUMN dh_supply_api_operation.state IS '执行、成功、未知或人工核查结论';
COMMENT ON COLUMN dh_supply_api_operation.result_json IS '仅保存写入影响行数，不保存业务行';
COMMENT ON COLUMN dh_supply_api_operation.lease_until IS '超期转未知的时间，不用于重新执行认领';
COMMENT ON COLUMN dh_supply_api_operation.trace_id IS '请求追踪编号';
COMMENT ON COLUMN dh_supply_api_operation.resolved_by IS '人工核查操作者编号';
COMMENT ON COLUMN dh_supply_api_operation.resolution IS '人工核查原因';
COMMENT ON COLUMN dh_supply_api_operation.evidence IS '目标库核查工单或证据引用，不填敏感数据';
COMMENT ON COLUMN dh_supply_api_operation.resolved_at IS '人工核查时间';
COMMENT ON COLUMN dh_supply_api_operation.creator IS '创建者';
COMMENT ON COLUMN dh_supply_api_operation.create_time IS '创建时间';
COMMENT ON COLUMN dh_supply_api_operation.updater IS '更新者';
COMMENT ON COLUMN dh_supply_api_operation.update_time IS '更新时间';
COMMENT ON COLUMN dh_supply_api_operation.deleted IS '删除标记；业务键永久占用';
CREATE INDEX IF NOT EXISTS idx_supply_api_operation_pending ON dh_supply_api_operation(tenant_id,lease_until,id) WHERE state='RUNNING';
CREATE INDEX IF NOT EXISTS idx_supply_api_operation_history ON dh_supply_api_operation(tenant_id,api_id,id DESC);
CREATE INDEX IF NOT EXISTS idx_supply_api_operation_key ON dh_supply_api_operation(tenant_id,operation_key);
ALTER TABLE dh_supply_api_log ADD COLUMN IF NOT EXISTS trace_id varchar(64);
COMMENT ON COLUMN dh_supply_api_log.trace_id IS '开放网关请求追踪编号';
CREATE INDEX IF NOT EXISTS idx_supply_api_log_trace ON dh_supply_api_log(tenant_id,trace_id) WHERE trace_id IS NOT NULL;

DO $supply_control_menu$
DECLARE
 api_menu bigint;
 supply_parent bigint;
 database_menu bigint;
 operation_menu bigint;
 menu_id bigint;
 matches integer;
 seq regclass;
 item record;
BEGIN
 LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*),min(id),min(parent_id) INTO matches,api_menu,supply_parent FROM system_menu
 WHERE deleted=0 AND type=2 AND trim(both '/' from component)='supply/dataapi/index';
 IF matches<>1 THEN RAISE EXCEPTION '需要唯一有效的数据API菜单及组件映射'; END IF;
 SELECT count(*),min(id) INTO matches,database_menu FROM system_menu
 WHERE deleted=0 AND type=2 AND trim(both '/' from component)='dataforge/database/index';
 IF matches<>1 THEN RAISE EXCEPTION '需要唯一有效的数据源菜单及组件映射'; END IF;
 seq:=COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
 IF seq IS NULL THEN RAISE EXCEPTION '缺少系统菜单主键序列'; END IF;
 SELECT count(*),min(id) INTO matches,operation_menu FROM system_menu
 WHERE trim(both '/' from component)='supply/operation/index';
 IF matches>1 THEN RAISE EXCEPTION '写操作台账菜单组件重复'; END IF;
 IF matches=1 THEN
  IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=operation_menu AND deleted=0 AND type=2 AND parent_id=supply_parent)
  THEN RAISE EXCEPTION '写操作台账菜单位置或状态冲突'; END IF;
 ELSE
  operation_menu:=nextval(seq);
  WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=operation_menu) LOOP operation_menu:=nextval(seq); END LOOP;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
  VALUES(operation_menu,'写操作台账','',2,65,supply_parent,'write-operation','lucide:clipboard-check','supply/operation/index','SupplyWriteOperation',0,true,true,true,'migration:0090','migration:0090',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
 END IF;
 FOR item IN SELECT * FROM (VALUES
  ('查询写操作台账','supply:data-api:operation-query',operation_menu),
  ('核查未知写结果','supply:data-api:operation-resolve',operation_menu),
  ('发布或下线API','supply:data-api:publish',api_menu),
  ('预览数据源数据','dataforge:database:preview',database_menu)
 ) AS permissions(name,permission,parent_id) LOOP
  SELECT count(*),min(id) INTO matches,menu_id FROM system_menu WHERE permission=item.permission;
  IF matches>1 THEN RAISE EXCEPTION '权限重复：%',item.permission; END IF;
  IF matches=1 THEN
   IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id AND deleted=0 AND type=3 AND status=0)
   THEN RAISE EXCEPTION '权限已停用或冲突，不能自动恢复：%',item.permission; END IF;
  ELSE
   menu_id:=nextval(seq);
   WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id) LOOP menu_id:=nextval(seq); END LOOP;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
   VALUES(menu_id,item.name,item.permission,3,99,item.parent_id,'','',NULL,NULL,0,true,true,true,'migration:0090','migration:0090',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
  END IF;
 END LOOP;
END;
$supply_control_menu$;
COMMIT;

-- BEGIN ETL IMPLEMENTATION 0084_dataforge_etl-subflow-tools.sql
-- Migration: 0084 ETL 子流程组件目录
-- Purpose: 恢复本任务尚未交付的 0084 分配；子流程工具目录先于 0088 受管批次结构安装
-- Depends on: 0081_dataforge_etl-version-governance-link.sql 及既有 ETL 工具目录
-- Target: 已完成前序升级的平台 PostgreSQL；新库同时同步基线
-- Repeatable: 是；按组件编码防止重复插入，单事务目录写入
-- Rollback: 不删除已有流程引用的组件；回退应用后保留目录，停用前检查引用

BEGIN;
LOCK TABLE "datahub-center".dh_dataforge_etl_tool IN SHARE ROW EXCLUSIVE MODE;
INSERT INTO "datahub-center".dh_dataforge_etl_tool
    (id,parent_id,name,icon,type,code,built_in,enabled,order_no,description,tenant_id,creator,create_time,updater,update_time,deleted)
SELECT (SELECT COALESCE(MAX(id),0) FROM "datahub-center".dh_dataforge_etl_tool)+row_number() OVER(ORDER BY v.code),
       v.parent_id,v.name,'lucide:workflow',v.type,v.code,1,1,v.order_no,v.description,1,'1',CURRENT_TIMESTAMP,'1',CURRENT_TIMESTAMP,0
FROM (VALUES
    (1,'子流程输入',1,'boundary-input',98,'定义子流程输入端口及字段契约，不能单独运行'),
    (3,'子流程输出',3,'boundary-output',98,'定义子流程输出端口及字段契约，不能单独运行'),
    (2,'调用子流程',2,'sub-pipeline',98,'调用已发布且冻结的纯转换子流程版本')
) AS v(parent_id,name,type,code,order_no,description)
WHERE NOT EXISTS(SELECT 1 FROM "datahub-center".dh_dataforge_etl_tool t WHERE t.code=v.code);
COMMIT;
-- END ETL IMPLEMENTATION 0084_dataforge_etl-subflow-tools.sql

-- BEGIN ETL IMPLEMENTATION 0088_dataforge_etl-target-batch.sql
-- Migration: 0088 ETL 受管目标批次及真实批次质检
-- Purpose: 持久暂存、原子提交回执、恢复审计和治理实例的精确批次关联
-- Depends on: 0081_dataforge_etl-version-governance-link.sql 及既有治理质量任务/实例表
-- Target: 已完成前序升级的平台 PostgreSQL；目标 DWD 的运行时旁路账本由 DB Switch 管理
-- Repeatable: 是；加法式结构与目录增量在单事务内可重放
-- Rollback: 回退应用后保留批次、载荷和审计；删除载荷不可逆，需先完成保留策略与工单核验

BEGIN;

ALTER TABLE "datahub-center".dh_dataforge_etl_quality_batch ADD COLUMN IF NOT EXISTS identity_fields_json text;
ALTER TABLE "datahub-center".dh_dataforge_etl_quality_batch ADD COLUMN IF NOT EXISTS identity_hash varchar(64);
ALTER TABLE "datahub-center".dh_governance_etl_quality_report ADD COLUMN IF NOT EXISTS identity_fields_json jsonb;
ALTER TABLE "datahub-center".dh_governance_etl_quality_report ADD COLUMN IF NOT EXISTS identity_hash varchar(64);
COMMENT ON COLUMN "datahub-center".dh_governance_etl_quality_report.identity_hash IS '受管批次完整检测人口业务键摘要，包含被隔离行';

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_template_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_template (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_template_seq'),
    tenant_id bigint NOT NULL, name varchar(100) NOT NULL, description varchar(500),
    owner_user_id bigint NOT NULL, node_count integer NOT NULL CHECK(node_count BETWEEN 1 AND 32),
    request_id varchar(64) NOT NULL, content_hash varchar(64) NOT NULL,
    config_json text NOT NULL CHECK (jsonb_typeof(config_json::jsonb)='object'),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT uk_etl_template_request UNIQUE(tenant_id,owner_user_id,request_id)
);
-- 表用途说明：租户内不可变 ETL 团队模板，不包含凭据与运行身份
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_template IS '可视化ETL-团队模板';
CREATE INDEX IF NOT EXISTS idx_etl_template_page ON "datahub-center".dh_dataforge_etl_template(tenant_id,deleted,id DESC);

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_replay_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_replay (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_replay_seq'),
    tenant_id bigint NOT NULL, record_id bigint NOT NULL, source_record_id bigint NOT NULL,
    work_order_id bigint NOT NULL, submission_id bigint NOT NULL, actor_id bigint NOT NULL,
    request_id varchar(64) NOT NULL, request_hash varchar(64) NOT NULL,
    snapshot_mode varchar(24) NOT NULL CHECK(snapshot_mode IN ('ORIGINAL','LATEST_PUBLISHED')),
    reason varchar(1000) NOT NULL,
    attach_status varchar(24) NOT NULL CHECK(attach_status IN ('PENDING','RETRY','ATTACHING','ATTACHED','FAILED')),
    attempt_count integer NOT NULL DEFAULT 0 CHECK(attempt_count BETWEEN 0 AND 10),
    lease_token varchar(64), lease_until timestamp, next_attempt_at timestamp, last_error varchar(1000),
    creator varchar(64) NOT NULL DEFAULT '',create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,deleted smallint NOT NULL DEFAULT 0,
    UNIQUE(tenant_id,record_id),UNIQUE(tenant_id,actor_id,request_id),
    CHECK((lease_token IS NULL)=(lease_until IS NULL))
);
CREATE INDEX IF NOT EXISTS idx_etl_replay_pending ON "datahub-center".dh_dataforge_etl_replay(attach_status,next_attempt_at,id) WHERE deleted=0;
-- 表用途说明：源端整改回放运行与治理复检证据投递，不覆盖原报告
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_replay IS '可视化ETL-整改回放记录';

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_target_batch_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_target_batch (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_target_batch_seq'),
    tenant_id bigint NOT NULL,
    record_id bigint NOT NULL,
    physical_batch_key varchar(64), replay_of_batch_id bigint, replay_of_record_id bigint,
    work_order_id bigint, work_order_submission_id bigint, replaced_by_batch_id bigint,
    expected_payload_hash varchar(64), operation_key varchar(64),
    node_no varchar(128) NOT NULL,
    execution_user_id bigint NOT NULL,
    quality_batch_id bigint NOT NULL,
    quality_task_id bigint NOT NULL,
    quality_instance_id bigint,
    batch_key varchar(64) NOT NULL CHECK (batch_key ~ '^[a-f0-9]{64}$'),
    config_json text NOT NULL CHECK (jsonb_typeof(config_json::jsonb)='object'),
    payload_json text NOT NULL,
    source_payload_json text NOT NULL,
    payload_hash varchar(64) NOT NULL CHECK (payload_hash ~ '^[a-f0-9]{64}$'),
    input_count bigint NOT NULL CHECK (input_count>=0 AND input_count<=5000),
    output_count bigint NOT NULL CHECK (output_count>=0),
    admitted_count bigint NOT NULL CHECK (admitted_count>=0),
    rejected_count bigint NOT NULL CHECK (rejected_count>=0),
    identity_hash varchar(64) NOT NULL CHECK (identity_hash ~ '^[a-f0-9]{64}$'),
    commit_status varchar(24) NOT NULL CHECK (commit_status IN ('STAGED','READY','COMMITTING','COMMITTED','UNKNOWN','RETRY','FAILED','BLOCKED','CANCELLED','SUPERSEDED')),
    receipt_json text,
    quality_status varchar(24) NOT NULL CHECK (quality_status IN ('PENDING','RUNNING','PASSED','FAILED','EMPTY','NOT_RUN','UNAVAILABLE')),
    attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count>=0),
    lease_token varchar(64), lease_until timestamp, next_attempt_at timestamp,
    last_error varchar(256),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT ck_etl_target_counts CHECK (output_count<=input_count AND admitted_count<=output_count AND rejected_count<=input_count),
    CONSTRAINT ck_etl_target_receipt CHECK (commit_status<>'COMMITTED' OR receipt_json IS NOT NULL),
    CONSTRAINT ck_etl_target_lease CHECK ((lease_token IS NULL)=(lease_until IS NULL)),
    CONSTRAINT uk_etl_target_node UNIQUE (tenant_id,record_id,node_no),
    CONSTRAINT uk_etl_target_key UNIQUE (tenant_id,batch_key),
    CONSTRAINT ck_etl_target_replay CHECK ((replay_of_batch_id IS NULL AND replay_of_record_id IS NULL AND work_order_id IS NULL
       AND work_order_submission_id IS NULL AND expected_payload_hash IS NULL AND operation_key IS NULL) OR
       (replay_of_batch_id IS NOT NULL AND replay_of_record_id IS NOT NULL AND work_order_id IS NOT NULL
       AND work_order_submission_id IS NOT NULL AND physical_batch_key IS NOT NULL AND expected_payload_hash IS NOT NULL AND operation_key IS NOT NULL))
);
-- 表用途说明：ETL 受管目标的持久意图、提交回执和独立质量状态
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_target_batch IS '可视化ETL-目标写入批次';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_target_batch.payload_json IS '版本化 DB Switch typed payload 编码，保留整数、精确小数、日期及二进制类型';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_target_batch.source_payload_json IS '过滤前完整目标字段快照，用于受控复检及回放';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_target_batch.identity_hash IS '全输入业务键集合摘要，不能用过滤后子集冒充原治理范围';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_target_batch.commit_status IS 'STAGED 不可投递；只有完整图退出成功后才能 READY';
CREATE INDEX IF NOT EXISTS idx_etl_target_delivery ON "datahub-center".dh_dataforge_etl_target_batch (commit_status,next_attempt_at,id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_etl_target_quality ON "datahub-center".dh_dataforge_etl_target_batch (quality_status,id) WHERE deleted=0 AND commit_status='COMMITTED';

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_dataforge_etl_target_action_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_etl_target_action (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_dataforge_etl_target_action_seq'),
    tenant_id bigint NOT NULL, batch_id bigint NOT NULL, actor_id bigint NOT NULL,
    action varchar(32) NOT NULL, reason varchar(1000) NOT NULL,
    before_state varchar(64) NOT NULL, create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
-- 表用途说明：受管目标人工恢复与回放操作审计
COMMENT ON TABLE "datahub-center".dh_dataforge_etl_target_action IS '可视化ETL-目标恢复操作审计';

CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_governance_quality_etl_batch_run_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_quality_etl_batch_run (
    id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_governance_quality_etl_batch_run_seq'),
    tenant_id bigint NOT NULL, quality_task_id bigint NOT NULL, check_object_id bigint NOT NULL,
    inline_report_id bigint NOT NULL, quality_node_id varchar(128) NOT NULL, quality_batch_id varchar(128) NOT NULL,
    target_batch_id bigint NOT NULL, record_id bigint NOT NULL,
    replay_of_batch_id bigint, replay_of_record_id bigint, work_order_submission_id bigint,
    run_id varchar(64) NOT NULL, sink_node_id varchar(128) NOT NULL,
    batch_key varchar(64) NOT NULL CHECK (batch_key ~ '^[a-f0-9]{64}$'),
    physical_batch_value varchar(64) NOT NULL CHECK (physical_batch_value ~ '^[a-f0-9]{64}$'),
    manifest_hash varchar(64) NOT NULL CHECK (manifest_hash ~ '^[a-f0-9]{64}$'),
    manifest_json jsonb NOT NULL CHECK (jsonb_typeof(manifest_json)='object'),
    row_count bigint NOT NULL CHECK (row_count>=0), admitted_row_count bigint NOT NULL CHECK (admitted_row_count>=0 AND admitted_row_count<=row_count),
    allow_warnings boolean NOT NULL, identity_fields_json jsonb NOT NULL CHECK (jsonb_typeof(identity_fields_json)='array'),
    identity_hash varchar(64) NOT NULL CHECK (identity_hash ~ '^[a-f0-9]{64}$'),
    instance_id bigint, state varchar(24) NOT NULL,
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT uk_quality_etl_batch_key UNIQUE (tenant_id,quality_task_id,batch_key),
    CONSTRAINT uk_quality_etl_target_batch UNIQUE (tenant_id,quality_task_id,target_batch_id),
    CONSTRAINT ck_quality_etl_replay_binding CHECK (
        (replay_of_batch_id IS NULL AND replay_of_record_id IS NULL AND work_order_submission_id IS NULL)
        OR (replay_of_batch_id IS NOT NULL AND replay_of_record_id IS NOT NULL AND work_order_submission_id IS NOT NULL)
    ),
    CONSTRAINT uk_quality_etl_batch_instance UNIQUE (instance_id)
);
-- 表说明（原文）：已提交 ETL 批次与真实治理检测实例的不可变范围绑定
COMMENT ON TABLE "datahub-center".dh_governance_quality_etl_batch_run IS '数据质量-ETL批次检测绑定';
CREATE INDEX IF NOT EXISTS idx_quality_etl_inline_report ON "datahub-center".dh_governance_quality_etl_batch_run (tenant_id,inline_report_id);
CREATE INDEX IF NOT EXISTS idx_quality_etl_replay_binding ON "datahub-center".dh_governance_quality_etl_batch_run
    (tenant_id,work_order_submission_id,replay_of_batch_id,target_batch_id);
CREATE INDEX IF NOT EXISTS idx_quality_etl_batch_key ON "datahub-center".dh_governance_quality_etl_batch_run (tenant_id,quality_task_id,batch_key);

LOCK TABLE "datahub-center".dh_dataforge_etl_tool IN SHARE ROW EXCLUSIVE MODE;
INSERT INTO "datahub-center".dh_dataforge_etl_tool
    (id,parent_id,name,icon,type,code,built_in,enabled,order_no,description,tenant_id,creator,create_time,updater,update_time,deleted)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM "datahub-center".dh_dataforge_etl_tool),
       3,'受管数据库输出','lucide:database',3,'managed-db-output',1,1,99,
       '先持久暂存，完整图成功后按稳定批次提交并执行目标质量准入',1,'1',CURRENT_TIMESTAMP,'1',CURRENT_TIMESTAMP,0
WHERE NOT EXISTS (SELECT 1 FROM "datahub-center".dh_dataforge_etl_tool WHERE code='managed-db-output');

COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_template.id IS '记录编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_template.tenant_id IS '所属租户编号';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_template.name IS '模板名称';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_template.description IS '模板说明';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_template.owner_user_id IS '模板所有者';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_template.node_count IS '模板节点数量';
