COMMENT ON COLUMN "datahub-center".dh_dataforge_reference_audit.operation_id IS '关联冻结或引用变更标识';
COMMENT ON COLUMN "datahub-center".dh_dataforge_reference_audit.revision IS '操作前屏障或变更修订';
COMMENT ON COLUMN "datahub-center".dh_dataforge_reference_audit.actor_id IS '认证操作者编号；后台服务可为空';
COMMENT ON COLUMN "datahub-center".dh_dataforge_reference_audit.reason IS '操作原因';
COMMENT ON COLUMN "datahub-center".dh_dataforge_reference_audit.evidence IS '人工核查证据';
COMMENT ON COLUMN "datahub-center".dh_dataforge_reference_audit.create_time IS '审计时间';
-- 盘点仅由各领域查询自己的表；本函数只解释传入的引用文档，不访问任何业务表。
CREATE OR REPLACE FUNCTION "datahub-center".dh_reference_document_has_database(doc jsonb, db_id bigint, depth integer DEFAULT 0)
RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $fn$
DECLARE pair record; item jsonb; parsed jsonb; value_text text;
BEGIN
 IF doc IS NULL THEN RETURN false; END IF;
 IF depth > 32 THEN RETURN true; END IF;
 IF jsonb_typeof(doc) = 'object' THEN
  FOR pair IN SELECT key,value FROM jsonb_each(doc) LOOP
   IF lower(replace(pair.key,'_','')) IN ('databaseid','datasourceid','datasourceconnid','sourcedatabaseid','targetdatabaseid','sourcedatasourceid','targetdatasourceid') THEN
    value_text := pair.value #>> '{}';
    IF value_text ~ '^[0-9]+$' AND value_text::numeric = db_id THEN RETURN true; END IF;
   ELSIF "datahub-center".dh_reference_document_has_database(pair.value,db_id,depth+1) THEN RETURN true;
   END IF;
  END LOOP;
 ELSIF jsonb_typeof(doc) = 'array' THEN
  FOR item IN SELECT value FROM jsonb_array_elements(doc) LOOP
   IF "datahub-center".dh_reference_document_has_database(item,db_id,depth+1) THEN RETURN true; END IF;
  END LOOP;
 ELSIF jsonb_typeof(doc) = 'string' THEN
  value_text := doc #>> '{}';
  IF ltrim(value_text) LIKE '{%' OR ltrim(value_text) LIKE '[%' THEN
   BEGIN parsed := value_text::jsonb;
   EXCEPTION WHEN invalid_text_representation THEN RETURN true;
   END;
   RETURN "datahub-center".dh_reference_document_has_database(parsed,db_id,depth+1);
  END IF;
 END IF;
 RETURN false;
END $fn$;
COMMENT ON FUNCTION "datahub-center".dh_reference_document_has_database(jsonb,bigint,integer) IS '领域引用协议的无损数据源编号检测；兼容历史字符串JSON配置；无法解释的配置保守阻断';

