-- 新增引用控制页及细粒度权限，不自动给现有角色授予人工处置能力。
DO $reference_menu$
DECLARE base_parent bigint; page_id bigint; button_id bigint; matches integer; seq regclass;
BEGIN
 LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*),min(parent_id) INTO matches,base_parent FROM system_menu
 WHERE deleted=0 AND type=2 AND trim(both '/' from component)='dataforge/database/index';
 IF matches<>1 THEN RAISE EXCEPTION '需要唯一有效的数据源菜单'; END IF;
 seq:=COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
 IF seq IS NULL THEN RAISE EXCEPTION '缺少系统菜单主键序列'; END IF;
 SELECT count(*),min(id) INTO matches,page_id FROM system_menu
 WHERE trim(both '/' from component)='dataforge/referencecontrol/index';
 IF matches>1 THEN RAISE EXCEPTION '引用控制菜单重复'; END IF;
 IF matches=0 THEN
  page_id:=nextval(seq);
  WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=page_id) LOOP page_id:=nextval(seq); END LOOP;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
  VALUES(page_id,'数据源引用控制','dataforge:database:reference-control',2,35,base_parent,'reference-control','lucide:shield-check','dataforge/referencecontrol/index','DataForgeReferenceControl',0,true,true,true,'migration:0098','migration:0098',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
 ELSE
  IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=page_id AND parent_id=base_parent AND deleted=0 AND status=0 AND permission='dataforge:database:reference-control')
  THEN RAISE EXCEPTION '引用控制菜单位置状态或权限冲突'; END IF;
 END IF;
 SELECT count(*),min(id) INTO matches,button_id FROM system_menu WHERE permission='dataforge:database:reference-resolve';
 IF matches>1 THEN RAISE EXCEPTION '引用处置权限重复'; END IF;
 IF matches=0 THEN
  button_id:=nextval(seq);
  WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=button_id) LOOP button_id:=nextval(seq); END LOOP;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
  VALUES(button_id,'核查引用控制回执','dataforge:database:reference-resolve',3,1,page_id,'','',NULL,NULL,0,true,true,true,'migration:0098','migration:0098',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
 ELSE
  IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=button_id AND parent_id=page_id AND type=3 AND status=0 AND deleted=0)
  THEN RAISE EXCEPTION '引用处置权限位置或状态冲突'; END IF;
 END IF;
END $reference_menu$;
COMMIT;
-- END MIGRATION BASELINE SYNC

-- BEGIN MIGRATION BASELINE SYNC 0099_supply_consumption-quota.sql
-- Migration: 0099
-- Purpose: 统一门户与数据服务的申请次数、返回行数额度及可对账消费回执
-- Depends on: 0098_dataforge_datasource-reference-control.sql；既有 Supply 与 Asset 申请结构
-- Target: 已完成前序迁移的平台 PostgreSQL；新库同步全量基线
-- Repeatable: 是；单事务加法建表，不改变历史申请的批准内容
-- Rollback: 回退应用并保留计数和回执；删除台账会丢失幂等证据，禁止清空后重放请求
BEGIN;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_supply_quota_balance (
 tenant_id bigint NOT NULL,
 source_system varchar(64) NOT NULL,
 source_key varchar(256) NOT NULL,
 metric varchar(16) NOT NULL CHECK(metric IN ('CALLS','ROWS')),
 quota_limit bigint NOT NULL CHECK(quota_limit > 0),
 used_units bigint NOT NULL DEFAULT 0 CHECK(used_units >= 0),
 reserved_units bigint NOT NULL DEFAULT 0 CHECK(reserved_units >= 0),
 create_time timestamptz NOT NULL DEFAULT clock_timestamp(),
 update_time timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,source_system,source_key),
 CHECK(used_units <= quota_limit AND reserved_units <= quota_limit-used_units)
);
-- 表说明（原文）：按批准来源终身累计的消费额度；暂停、重授和来源修订不得重置额度
COMMENT ON TABLE "datahub-center".dh_supply_quota_balance IS '数据服务-消费额度账本';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.source_system IS '授权来源系统';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.source_key IS '批准来源稳定业务键';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.metric IS '计量类型：调用次数或实际返回行数';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.quota_limit IS '批准的累计额度，来源存续期间不可更改';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.used_units IS '已确认披露的数据消费量';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.reserved_units IS '执行中请求预占的消费量';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.create_time IS '首次消费登记时间';
COMMENT ON COLUMN "datahub-center".dh_supply_quota_balance.update_time IS '最近记账时间';
CREATE TABLE IF NOT EXISTS "datahub-center".dh_supply_quota_receipt (
 tenant_id bigint NOT NULL,
 consumer_key varchar(160) NOT NULL,
 request_key varchar(128) NOT NULL,
 actor_id bigint NOT NULL CHECK(actor_id > 0),
 request_hash char(64) NOT NULL,
 state varchar(16) NOT NULL CHECK(state IN ('RESERVED','COMMITTED','CANCELLED','EXPIRED')),
 token varchar(64) NOT NULL,
 row_limit integer NOT NULL CHECK(row_limit BETWEEN 1 AND 100000),
 actual_rows integer CHECK(actual_rows >= 0 AND actual_rows <= row_limit),
 allocations jsonb NOT NULL CHECK(jsonb_typeof(allocations)='array'),
 expires_at timestamptz NOT NULL,
 create_time timestamptz NOT NULL DEFAULT clock_timestamp(),
 update_time timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(tenant_id,consumer_key,request_key)
);
