-- BEGIN MIGRATION BASELINE SYNC 0100_governance_dml-authorization.sql
-- Migration: 0100 治理精确 SQL 写授权及变更审计
-- Purpose: 新增独立写策略、变更审计和只读预检权限；历史读写枚举不自动授予 DML 权限。
-- Depends on: 0099_supply_consumption-quota.sql；0074_governance_permission-schema-binding.sql 及完整治理权限页菜单。
-- Target: 已有 PostgreSQL 平台库；新库在恢复完整历史基线后合入同等最终结构。
-- Repeatable: 是；加法式结构、条件约束和唯一权限检测均可重放，事务内不修改历史授权内容。
-- Rollback: 先回退消费方和治理写权限代码，再停用预检权限；保留写策略及审计证据，不自动删除列或表。
-- 风险说明：新增列和约束会短暂锁表，应在维护窗口执行；本脚本不会对外部数据源执行写操作。
BEGIN;
SET LOCAL search_path TO "datahub-center",public;
ALTER TABLE dh_governance_safety_table_permission ADD COLUMN IF NOT EXISTS write_policy text;
COMMENT ON COLUMN dh_governance_safety_table_permission.write_policy IS '独立写授权JSON：操作、可写列、过滤列及等值行范围；NULL表示无写权限，历史读写枚举不推导写权';
DO $write_policy_constraint$
BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_safety_write_policy_json'
  AND conrelid='dh_governance_safety_table_permission'::regclass) THEN
  ALTER TABLE dh_governance_safety_table_permission ADD CONSTRAINT ck_safety_write_policy_json
   CHECK(write_policy IS NULL OR (length(write_policy)<=100000 AND jsonb_typeof(write_policy::jsonb)='object'));
 END IF;
END;
$write_policy_constraint$;

CREATE SEQUENCE IF NOT EXISTS dh_governance_safety_write_audit_seq;
CREATE TABLE IF NOT EXISTS dh_governance_safety_write_audit (
 id bigint PRIMARY KEY DEFAULT nextval('dh_governance_safety_write_audit_seq'),
 tenant_id bigint NOT NULL,
 database_id bigint NOT NULL,
 schema_name varchar(256) NOT NULL,
 table_name varchar(256) NOT NULL,
 role_id bigint NOT NULL,
 actor_id bigint NOT NULL,
 before_policy text,
 after_policy text,
 reason varchar(500) NOT NULL CHECK(length(trim(reason)) BETWEEN 5 AND 500),
 creator varchar(64) NOT NULL DEFAULT '',
 create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '',
 update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0,
 CONSTRAINT ck_safety_write_audit_identity CHECK(tenant_id>0 AND database_id>0 AND role_id>0 AND actor_id>0)
);
ALTER SEQUENCE dh_governance_safety_write_audit_seq OWNED BY dh_governance_safety_write_audit.id;
-- 表说明（原文）：独立SQL写授权新增、修改、撤销审计；与策略变更同事务提交，不允许普通业务修改
COMMENT ON TABLE dh_governance_safety_write_audit IS '数据安全-SQL写授权审计';
COMMENT ON COLUMN dh_governance_safety_write_audit.id IS '审计编号';
COMMENT ON COLUMN dh_governance_safety_write_audit.tenant_id IS '可信租户编号';
COMMENT ON COLUMN dh_governance_safety_write_audit.database_id IS '数据源编号';
COMMENT ON COLUMN dh_governance_safety_write_audit.schema_name IS '精确物理模式';
COMMENT ON COLUMN dh_governance_safety_write_audit.table_name IS '精确物理表';
COMMENT ON COLUMN dh_governance_safety_write_audit.role_id IS '被配置角色编号';
COMMENT ON COLUMN dh_governance_safety_write_audit.actor_id IS '实际登录操作人编号';
COMMENT ON COLUMN dh_governance_safety_write_audit.before_policy IS '变更前独立写策略，NULL表示无授权';
COMMENT ON COLUMN dh_governance_safety_write_audit.after_policy IS '变更后独立写策略，NULL表示撤销';
COMMENT ON COLUMN dh_governance_safety_write_audit.reason IS '授权变更的业务依据，不得填入账号或密钥';
COMMENT ON COLUMN dh_governance_safety_write_audit.creator IS '框架创建者字段，业务操作人以actor_id为准';
COMMENT ON COLUMN dh_governance_safety_write_audit.create_time IS '审计提交时间';
COMMENT ON COLUMN dh_governance_safety_write_audit.updater IS '框架更新者字段，审计记录不提供修改入口';
COMMENT ON COLUMN dh_governance_safety_write_audit.update_time IS '框架更新时间';
COMMENT ON COLUMN dh_governance_safety_write_audit.deleted IS '框架删除标记，审计记录不提供删除入口';
CREATE INDEX IF NOT EXISTS idx_safety_write_audit_object
 ON dh_governance_safety_write_audit(tenant_id,database_id,schema_name,table_name,role_id,id DESC);

DO $write_permission_menu$
DECLARE parent bigint; found integer; permission_id bigint; sequence_name regclass;
BEGIN
 LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*),min(id) INTO found,parent FROM system_menu
 WHERE deleted=0 AND type=2 AND trim(both '/' from component)='governance/permission/index';
 IF found<>1 THEN RAISE EXCEPTION '需要唯一有效的治理数据权限页菜单'; END IF;
 SELECT count(*),min(id) INTO found,permission_id FROM system_menu
 WHERE permission='governance:safety-permission:write-preflight';
 IF found>1 THEN RAISE EXCEPTION '写授权预检权限重复'; END IF;
 IF found=1 THEN
  IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=permission_id AND parent_id=parent AND deleted=0 AND status=0 AND type=3)
  THEN RAISE EXCEPTION '写授权预检权限位置或状态冲突，不能自动恢复'; END IF;
 ELSE
  sequence_name:=COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
  IF sequence_name IS NULL THEN RAISE EXCEPTION '缺少系统菜单编号序列'; END IF;
  permission_id:=nextval(sequence_name);
  WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=permission_id) LOOP permission_id:=nextval(sequence_name); END LOOP;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
  VALUES(permission_id,'SQL写授权预检','governance:safety-permission:write-preflight',3,99,parent,'','',NULL,NULL,0,true,true,true,'migration:0100','migration:0100',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
 END IF;
END;
$write_permission_menu$;
COMMIT;
-- END MIGRATION BASELINE SYNC

-- END MIGRATION BASELINE SYNC

-- 基线同步开始：0102_governance_work-order-notify-review.sql（迁移原文）
-- Migration: 0102
-- Purpose: 为投递UNKNOWN的质量工单通知提供有界、可审计的人工核验及独立显式重试授权。
-- Target: 已有 PostgreSQL 平台库；新库使用同步至0102的完整基线。
-- Repeatable: 是；新增列、序列、表、约束和索引均带存在性保护，不改写既有通知或人工处置记录。
-- Rollback: 加法迁移；回滚将删除人工核验与重试授权凭证，可能使已授权投递失去审计链，须备份并确认没有UNKNOWN、SENDING或等待重试的通知后再由运维执行。
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL search_path TO "datahub-center",public;

ALTER TABLE dh_governance_quality_work_order_notify
    ADD COLUMN IF NOT EXISTS resolution_status varchar(32) NOT NULL DEFAULT 'UNRESOLVED',
    ADD COLUMN IF NOT EXISTS resolution_version integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS manual_retry_count integer NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS resolution_reason varchar(1000),
    ADD COLUMN IF NOT EXISTS operator_message_id int8,
    ADD COLUMN IF NOT EXISTS resolved_by int8,
    ADD COLUMN IF NOT EXISTS resolved_at timestamp(6);

COMMENT ON COLUMN dh_governance_quality_work_order_notify.resolution_status IS '人工核验状态：UNRESOLVED、MANUAL_DELIVERED、MANUAL_NOT_DELIVERED、RETRY_AUTHORIZED；不代表系统远端自动核验';
COMMENT ON COLUMN dh_governance_quality_work_order_notify.resolution_version IS '人工核验决策CAS版本，防止旧页面决策覆盖新核验；每次核验或重试授权递增';
COMMENT ON COLUMN dh_governance_quality_work_order_notify.manual_retry_count IS 'UNKNOWN结果人工确认未送达后授权的重投次数，独立封顶8次，不改变普通FAILED重试计数';
COMMENT ON COLUMN dh_governance_quality_work_order_notify.resolution_reason IS '最近一次人工核验或重试授权理由';
COMMENT ON COLUMN dh_governance_quality_work_order_notify.operator_message_id IS '操作者提供的消息编号参考，不代表系统已验证该消息存在或送达';
COMMENT ON COLUMN dh_governance_quality_work_order_notify.resolved_by IS '最近一次人工处置操作人';
COMMENT ON COLUMN dh_governance_quality_work_order_notify.resolved_at IS '最近一次人工处置时间';

CREATE SEQUENCE IF NOT EXISTS dh_governance_quality_work_order_notify_review_seq;
COMMENT ON SEQUENCE dh_governance_quality_work_order_notify_review_seq IS '质量工单通知UNKNOWN人工核验审计编号序列';
CREATE TABLE IF NOT EXISTS dh_governance_quality_work_order_notify_review (
    id int8 NOT NULL DEFAULT nextval('dh_governance_quality_work_order_notify_review_seq'::regclass),
    work_order_id int8 NOT NULL,
    notify_id int8 NOT NULL,
    request_id varchar(64) NOT NULL,
    action_type varchar(32) NOT NULL,
    payload_hash varchar(64) NOT NULL,
    expected_resolution_status varchar(32) NOT NULL,
    expected_resolution_version integer NOT NULL,
    decision_id int8,
    outcome varchar(32) NOT NULL,
    reason varchar(1000) NOT NULL,
    operator_message_id int8,
    actor_user_id int8 NOT NULL,
    resulting_resolution_version integer NOT NULL,
    creator varchar(64) DEFAULT '',
    create_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted int2 NOT NULL DEFAULT 0,
    tenant_id int8 NOT NULL DEFAULT 0,
    CONSTRAINT pk_dh_governance_quality_work_order_notify_review PRIMARY KEY (id),
    CONSTRAINT ck_quality_work_order_notify_review_action
        CHECK (action_type IN ('MARK_DELIVERED', 'MARK_NOT_DELIVERED', 'AUTHORIZE_RETRY'))
);

-- 表说明（原文）：质量工单通知UNKNOWN人工核验与显式重试授权审计；不构成系统自动送达证明
COMMENT ON TABLE dh_governance_quality_work_order_notify_review IS '数据质量-工单通知核验审计';
COMMENT ON COLUMN dh_governance_quality_work_order_notify_review.id IS '人工通知处置审计编号';
