COMMENT ON COLUMN dh_governance_quality_work_order_notify_review.creator IS '创建者';
COMMENT ON COLUMN dh_governance_quality_work_order_notify_review.create_time IS '创建时间';
COMMENT ON COLUMN dh_governance_quality_work_order_notify_review.updater IS '更新者';
COMMENT ON COLUMN dh_governance_quality_work_order_notify_review.update_time IS '更新时间';
COMMENT ON COLUMN dh_governance_quality_work_order_notify_review.deleted IS '逻辑删除：0未删除、1已删除';
