-- BEGIN MIGRATION BASELINE SYNC 0104_governance_etl-task-creation.sql
-- Migration: 0104
-- Purpose: 保存从ETL目标生成SQL检测任务的不可变幂等回执；任务、检查对象及其关系同事务创建。
-- Target: 已有PostgreSQL平台库；新库仅可在完整历史基线恢复并验证后使用同步片段。
-- Repeatable: 是；单事务加法建表及替换同定义触发器，不修改历史任务或回执。
-- Rollback: 回退应用后保留此表；删除回执会丢失幂等及审计证据，恢复须依赖备份，不提供自动删除。
BEGIN;
SET LOCAL lock_timeout = '5s';
CREATE SEQUENCE IF NOT EXISTS "datahub-center".dh_governance_quality_etl_task_creation_seq;
CREATE TABLE IF NOT EXISTS "datahub-center".dh_governance_quality_etl_task_creation (
 id bigint PRIMARY KEY DEFAULT nextval('"datahub-center".dh_governance_quality_etl_task_creation_seq'),
 tenant_id bigint NOT NULL,
 request_id varchar(36) NOT NULL,
 request_hash varchar(64) NOT NULL,
 actor_id bigint NOT NULL CHECK (actor_id > 0),
 task_id bigint,
 check_object_id bigint,
 task_name varchar(100) NOT NULL,
 task_status integer NOT NULL CHECK (task_status IN (0,1)),
 definition_hash varchar(64) NOT NULL,
 target_json jsonb NOT NULL,
 creator varchar(64) NOT NULL,
 updater varchar(64) NOT NULL,
 create_time timestamp NOT NULL DEFAULT (clock_timestamp() AT TIME ZONE 'Asia/Shanghai'),
 update_time timestamp NOT NULL DEFAULT (clock_timestamp() AT TIME ZONE 'Asia/Shanghai'),
 deleted smallint NOT NULL DEFAULT 0 CHECK (deleted=0),
 UNIQUE (tenant_id,request_id),
 CHECK ((task_id IS NULL) = (check_object_id IS NULL))
);
-- 表说明（原文）：ETL目标创建独立SQL检测任务的原始回执；与检查对象、任务关系原子提交
COMMENT ON TABLE "datahub-center".dh_governance_quality_etl_task_creation IS '数据质量-ETL检测任务创建回执';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.id IS '创建回执编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.tenant_id IS '所属租户';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.request_id IS '调用方生成的稳定请求编号，同租户不复用';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.request_hash IS '包含真实操作者及规范化请求的摘要，同键异参拒绝';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.actor_id IS '创建操作者，同时作为任务负责人';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.task_id IS '原始创建的检测任务编号，后续任务编辑删除不改变回执';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.check_object_id IS '原始创建的检测对象编号';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.task_name IS '创建时任务名称';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.task_status IS '创建时任务状态：0上线、1下线';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.definition_hash IS '创建时所选规则定义摘要；执行时另行冻结完整定义';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.target_json IS '已核验的目标数据源、schema、表与规则编号，不含凭据';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.creator IS '创建人';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.updater IS '初始记录人，完成后禁止修改';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.create_time IS '创建时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.update_time IS '初始记录时间';
COMMENT ON COLUMN "datahub-center".dh_governance_quality_etl_task_creation.deleted IS '固定未删除，保留幂等与审计证据';
CREATE OR REPLACE FUNCTION "datahub-center".guard_etl_task_creation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE' AND OLD.task_id IS NULL AND NEW.task_id IS NOT NULL AND NEW.check_object_id IS NOT NULL
    AND (to_jsonb(OLD)-'task_id'-'check_object_id')=(to_jsonb(NEW)-'task_id'-'check_object_id') THEN RETURN NEW; END IF;
 RAISE EXCEPTION 'ETL任务创建回执完成后不可修改或删除';
END; $$;
DROP TRIGGER IF EXISTS trg_etl_task_creation_immutable ON "datahub-center".dh_governance_quality_etl_task_creation;
CREATE TRIGGER trg_etl_task_creation_immutable BEFORE UPDATE OR DELETE ON "datahub-center".dh_governance_quality_etl_task_creation
 FOR EACH ROW EXECUTE FUNCTION "datahub-center".guard_etl_task_creation();
COMMIT;

-- END MIGRATION BASELINE SYNC

-- BEGIN MIGRATION BASELINE SYNC 0105_dataforge_etl-source-provenance.sql
-- Migration: 0105
