    config_fingerprint varchar(64) NOT NULL,
    structure_fingerprint varchar(64),
    identity_format varchar(64),
    identity_document text CHECK (octet_length(identity_document) <= 16384),
    owner_run_id bigint NOT NULL CHECK (owner_run_id > 0),
    owner_token varchar(128) NOT NULL,
    occupied boolean NOT NULL,
    executor_drained boolean NOT NULL,
    manual_required boolean NOT NULL DEFAULT false,
