CREATE TABLE IF NOT EXISTS "datahub-center".dh_dataforge_access_table_page (
    scope varchar(64) NOT NULL,
    logical_resource varchar(64) NOT NULL,
    operation varchar(64) NOT NULL,
    image varchar(8) NOT NULL CHECK (image IN ('BEFORE','AFTER')),
    ordinal integer NOT NULL CHECK (ordinal >= 0),
    row_count integer NOT NULL CHECK (row_count > 0),
    plain_bytes integer NOT NULL CHECK (plain_bytes BETWEEN 8 AND 67108864),
    page_hash varchar(64) NOT NULL,
    key_id varchar(64) NOT NULL,
    nonce bytea NOT NULL CHECK (octet_length(nonce) = 12),
    payload bytea NOT NULL CHECK (octet_length(payload) BETWEEN 24 AND 67108880),
    PRIMARY KEY (scope, logical_resource, operation, image, ordinal),
    FOREIGN KEY (scope, logical_resource, operation) REFERENCES "datahub-center".dh_dataforge_access_table_recovery(scope, logical_resource, operation)
);
