-- Migration: 0110 建模业务过程结构化角色事件与业务分类责任范围
-- Purpose: 业务过程新增结构化的参与角色/部门与关键事件时间点列，业务分类新增责任范围列，并把三列纳入规划关键变更审计。
-- Depends on: 0079_modeling_closed-loop-schema.sql（业务过程表、业务分类表与规划审计函数 modeling_audit_planning_change）；按仓库编号执行至 0109。
-- Target: 已有 PostgreSQL 平台库；新库由 datahub-center.sql 末尾的同内容区块覆盖。
-- Repeatable: 是；新增列使用 ADD COLUMN IF NOT EXISTS，审计函数使用 CREATE OR REPLACE，重放不改变结果。
-- Rollback: 仅加法式结构；回退应用可保留新列，审计函数可用 0079 版本的 modeling_audit_planning_change 覆盖；已写入的审计记录不删除。
-- 风险：新增列与替换函数仅需短暂的表/函数锁，不回填数据；已绑定的 trg_modeling_planning_audit 触发器自动使用新函数体，无需重建。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
ALTER TABLE "datahub-center".dh_modeling_business_process ADD COLUMN IF NOT EXISTS participant_roles jsonb;
COMMENT ON COLUMN "datahub-center".dh_modeling_business_process.participant_roles IS '参与角色/部门结构化列表：JSON 数组，元素含 role（角色）、department（部门）、responsibility（职责）；空表示未填写';
ALTER TABLE "datahub-center".dh_modeling_business_process ADD COLUMN IF NOT EXISTS key_events jsonb;
COMMENT ON COLUMN "datahub-center".dh_modeling_business_process.key_events IS '关键事件与时间点结构化列表：JSON 数组，元素含 name（事件名称）、timePoint（时间点）、description（说明）；空表示未填写';
ALTER TABLE "datahub-center".dh_modeling_biz_category ADD COLUMN IF NOT EXISTS responsibility_scope varchar(2000);
COMMENT ON COLUMN "datahub-center".dh_modeling_biz_category.responsibility_scope IS '业务分类责任范围说明，不作为授权依据';
-- 规划审计函数与 0079 版本逐字一致，仅在审计键数组中追加 participant_roles、key_events、responsibility_scope。
CREATE OR REPLACE FUNCTION "datahub-center".modeling_audit_planning_change() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE old_data jsonb:='{}'; new_data jsonb:='{}'; detail jsonb:='{}'; key text; actor_text text; actor bigint; row_data jsonb; operation text:=TG_OP;
BEGIN
 IF TG_OP<>'INSERT' THEN old_data:=to_jsonb(OLD); END IF;
 IF TG_OP<>'DELETE' THEN new_data:=to_jsonb(NEW); END IF;
 row_data:=CASE WHEN TG_OP='DELETE' THEN old_data ELSE new_data END;
 IF TG_OP='UPDATE' AND old_data->>'deleted'='0' AND new_data->>'deleted'<>'0' THEN operation:='DELETE'; END IF;
 FOREACH key IN ARRAY ARRAY['name','code','layer_name','layer_code','parent_id','biz_category_id','data_domain_id',
  'status','node_type','table_prefix','default_table_type','leader_user_id','owner_user_id','owner_department',
  'scope_includes','scope_excludes','canonical_grain_definition','activity_definition','start_condition','end_condition',
  'participant_roles','key_events','responsibility_scope','deleted'] LOOP
  IF old_data->key IS DISTINCT FROM new_data->key THEN
   detail:=detail||jsonb_build_object(key,jsonb_build_object('before',old_data->>key,'after',new_data->>key));
  END IF;
 END LOOP;
 IF detail='{}'::jsonb THEN RETURN COALESCE(NEW,OLD); END IF;
 -- 没有新的审计元信息时不把历史 updater 冒充本次操作者。
 actor_text:=CASE WHEN TG_OP='INSERT' THEN row_data->>'creator'
  WHEN TG_OP='UPDATE' AND (new_data->>'updater' IS DISTINCT FROM old_data->>'updater'
       OR new_data->>'update_time' IS DISTINCT FROM old_data->>'update_time') THEN row_data->>'updater'
  ELSE NULL END;
 BEGIN actor:=actor_text::bigint; EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN actor:=NULL; END;
 INSERT INTO "datahub-center".dh_modeling_planning_change(tenant_id,kind,object_id,actor_id,action,changes,creator,updater)
 VALUES((row_data->>'tenant_id')::bigint,TG_ARGV[0],(row_data->>'id')::bigint,actor,operation,detail,COALESCE(actor_text,''),COALESCE(actor_text,''));
 RETURN COALESCE(NEW,OLD);
END $$;
COMMIT;

