-- 持久状态取值由数据库共同约束；避免未知状态脱离重试队列或绕开活动审批唯一约束。
DO $checks$
DECLARE item record;
BEGIN
 FOR item IN SELECT * FROM (VALUES
  ('dh_modeling_design_report','ck_modeling_report_kind', 'kind IN (''CONCEPT'',''LOGIC'',''PHYSICAL'')'),
  ('dh_modeling_business_object_external_ref','ck_modeling_ref_kind', 'kind IN (''TERM'',''STANDARD'',''SOURCE'')'),
  ('dh_modeling_collaboration','ck_modeling_policy_kind', 'kind IN (''CONCEPT'',''LOGIC'',''PHYSICAL'',''BUSINESS_OBJECT'')'),
  ('dh_modeling_collaboration','ck_modeling_policy_visibility', 'visibility IN (''TENANT'',''RESTRICTED'') AND revision>=0'),
  ('dh_modeling_collaborator','ck_modeling_member_principal', 'principal_type IN (''USER'',''DEPT'') AND principal_id>0'),
  ('dh_modeling_collaborator','ck_modeling_member_actions', 'actions ~ ''^(READ|EDIT|PUBLISH|DEPLOY|OWNER)(,(READ|EDIT|PUBLISH|DEPLOY|OWNER))*$'''),
  ('dh_modeling_approval','ck_modeling_approval_state', 'kind IN (''CONCEPT'',''LOGIC'',''PHYSICAL'') AND status IN (''START_PENDING'',''RUNNING'',''APPROVED'',''CANCEL_PENDING'',''MANUAL'',''REJECTED'',''CANCELLED'',''CONSUMED'') AND attempts>=0'),
  ('dh_modeling_environment_target','ck_modeling_target_code', 'code ~ ''^[A-Z][A-Z0-9_]{0,31}$'' AND revision>=0 AND database_id>0'),
  ('dh_modeling_object_change','ck_modeling_change_state', 'status IN (''PENDING'',''RETRY'',''DELIVERED'',''MANUAL'') AND attempts>=0'),
  ('dh_modeling_inbox','ck_modeling_inbox_state', 'status IN (''DELIVERED'',''READ'',''RESOLVED'') AND (status<>''RESOLVED'' OR (decision IN (''ADOPTED'',''KEEP_CURRENT'',''NO_LONGER_USED'') AND reason IS NOT NULL AND resolved_at IS NOT NULL))')
 ) AS constraints(table_name,constraint_name,expression) LOOP
  IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid=format('"datahub-center".%I',item.table_name)::regclass AND conname=item.constraint_name) THEN
   EXECUTE format('ALTER TABLE "datahub-center".%I ADD CONSTRAINT %I CHECK (%s)',item.table_name,item.constraint_name,item.expression);
  END IF;
 END LOOP;
END $checks$;
