-- 存量基线优先按成功部署记录恢复真实目标，缺少记录时仅回填同名当前模型目标。
UPDATE dh_modeling_schema_baseline b SET database_id=COALESCE(
 (SELECT d.database_id FROM dh_modeling_deploy_record d WHERE d.tenant_id=b.tenant_id AND d.model_id=b.model_id
  AND d.version_no=b.version_no AND d.table_name=b.table_name AND d.deleted=0 AND d.status='SUCCEEDED' ORDER BY d.id DESC LIMIT 1),
 (SELECT m.database_id FROM dh_modeling_physical_model m WHERE m.tenant_id=b.tenant_id AND m.id=b.model_id AND m.table_name=b.table_name AND m.deleted=0))
WHERE b.database_id IS NULL;

-- 审批证据不可修改；流程状态、投递租约与对账错误可以更新。
CREATE OR REPLACE FUNCTION dh_modeling_approval_snapshot_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF ROW(NEW.id,NEW.tenant_id,NEW.kind,NEW.model_id,NEW.version_id,NEW.version_no,NEW.source_revision,NEW.digest,NEW.snapshot,NEW.business_key,NEW.process_definition_key,NEW.applicant_id,NEW.reason)
 IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.kind,OLD.model_id,OLD.version_id,OLD.version_no,OLD.source_revision,OLD.digest,OLD.snapshot,OLD.business_key,OLD.process_definition_key,OLD.applicant_id,OLD.reason)
 THEN RAISE EXCEPTION '冻结审批证据不可修改' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS modeling_approval_immutable ON dh_modeling_approval;
CREATE TRIGGER modeling_approval_immutable BEFORE UPDATE ON dh_modeling_approval FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_snapshot_immutable();
COMMENT ON FUNCTION dh_modeling_approval_snapshot_immutable() IS '审批候选证据的数据库不可变约束';

-- 内容冻结期间拒绝竞态写入；发布先在同一事务消费已通过审批，再变更模型。
CREATE OR REPLACE FUNCTION dh_modeling_approval_freeze_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE object_kind text:=TG_ARGV[0]; object_id bigint; tenant bigint;
BEGIN
 object_id:=(to_jsonb(OLD)->>TG_ARGV[1])::bigint; tenant:=(to_jsonb(OLD)->>'tenant_id')::bigint;
 -- 物理模型运行状态与已冻结设计无关，部署旧版本可更新运行状态，不能改变模型内容。
 IF TG_TABLE_NAME='dh_modeling_physical_model' AND
    (to_jsonb(NEW)-ARRAY['deploy_status','deployed_version_id','deploy_time','updater','update_time']) =
    (to_jsonb(OLD)-ARRAY['deploy_status','deployed_version_id','deploy_time','updater','update_time'])
 THEN RETURN NEW; END IF;
 IF EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_approval a WHERE a.tenant_id=tenant AND a.kind=object_kind AND a.model_id=object_id
   AND a.deleted=0 AND a.status IN ('START_PENDING','RUNNING','APPROVED','CANCEL_PENDING','MANUAL'))
 THEN RAISE EXCEPTION '该模型内容已冻结用于发布审批，请先撤回或消费审批' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
COMMENT ON FUNCTION dh_modeling_approval_freeze_guard() IS '模型及版本冻结期间阻止更新，防止审批读后写竞态';
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_concept_model;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE ON dh_modeling_concept_model FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('CONCEPT','id');
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_logic_model;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE ON dh_modeling_logic_model FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('LOGIC','id');
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_logic_model_version;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE ON dh_modeling_logic_model_version FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('LOGIC','model_id');
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_physical_model;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE ON dh_modeling_physical_model FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('PHYSICAL','id');
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_physical_model_version;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE ON dh_modeling_physical_model_version FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('PHYSICAL','model_id');

-- 概念画布子记录同样冻结，避免绕过聚合头直接修改或删除已送审的实体及关系。
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_concept_entity;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE OR DELETE ON dh_modeling_concept_entity FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('CONCEPT','model_id');
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_concept_relation;
CREATE TRIGGER modeling_approval_freeze BEFORE UPDATE OR DELETE ON dh_modeling_concept_relation FOR EACH ROW EXECUTE FUNCTION dh_modeling_approval_freeze_guard('CONCEPT','model_id');

CREATE OR REPLACE FUNCTION dh_modeling_design_report_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION '设计检查归档证据不可修改或删除' USING ERRCODE='23514'; END $$;
DROP TRIGGER IF EXISTS modeling_design_report_immutable ON dh_modeling_design_report;
CREATE TRIGGER modeling_design_report_immutable BEFORE UPDATE OR DELETE ON dh_modeling_design_report FOR EACH ROW EXECUTE FUNCTION dh_modeling_design_report_immutable();
