COMMIT;

-- Migration: 0113
-- Purpose: 建模发布审批、对象协作、环境配置和变更收件箱的独立按钮权限
-- Depends on: 0112_modeling_review-workspace.sql；0080_modeling_closed-loop-menu.sql 提供唯一模型发布菜单
-- Target: 已有平台数据库；新库使用同步至0113的全量基线
-- Repeatable: 是；按权限查重，发现删除、停用或父菜单冲突时停止，不自动覆盖
-- Rollback: 无业务数据删除；管理员先撤回角色授权再停用新增按钮，保留审批、报告和回执
-- 不自动给任何角色授予新权限；协作策略写入口仍须同时具备查询过滤和操作 Guard。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout='5s';
DO $menus$
DECLARE parent bigint; menu_id bigint; matches integer; seq regclass; item record;
BEGIN
 LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
 SELECT count(*),min(id) INTO matches,parent FROM system_menu
 WHERE deleted=0 AND type=2 AND status=0 AND trim(both '/' from component)='modeling/modelpublish/index';
 IF matches<>1 THEN RAISE EXCEPTION '需先确认唯一有效的模型发布菜单（0080）'; END IF;
 seq:=COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
 IF seq IS NULL THEN RAISE EXCEPTION '缺少系统菜单编号序列'; END IF;
 FOR item IN SELECT * FROM (VALUES
  ('提交及撤回发布审批','modeling:workspace:approval'),
  ('管理对象与部门协作','modeling:workspace:collaboration'),
  ('管理模型环境目标','modeling:workspace:environment'),
  ('变更待办与投递恢复','modeling:workspace:inbox')
 ) AS permissions(name,permission) LOOP
  SELECT count(*),min(id) INTO matches,menu_id FROM system_menu WHERE permission=item.permission;
  IF matches>1 THEN RAISE EXCEPTION '权限存在重复：%',item.permission; END IF;
  IF matches=1 THEN
   IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id AND parent_id=parent AND type=3 AND status=0 AND deleted=0) THEN
    RAISE EXCEPTION '权限位置或状态冲突：%',item.permission;
   END IF;
  ELSE
   menu_id:=nextval(seq);
   WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id) LOOP menu_id:=nextval(seq); END LOOP;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
   VALUES(menu_id,item.name,item.permission,3,99,parent,'','',NULL,NULL,0,true,true,true,'migration:0113','migration:0113',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
  END IF;
 END LOOP;
END $menus$;
COMMIT;

-- 新库同步增量：0117_dataforge_etl-file-retirement.sql
-- Migration: 0117
-- Purpose: 为已发布的本人ETL文件增加显式申请、到期清理阶段和独立清理权限，历史文件默认保留。
-- Depends on: 0116_dataforge_etl-file-temporary-resources.sql；完整平台已存在唯一有效的ETL运行记录菜单。
-- Target: 已有平台PostgreSQL库；新库使用同步全量基线。仅文件组件隔离库可不含系统菜单表。
-- Repeatable: 是；不改写已有申请或审计，不自动授予角色权限，发现菜单冲突时停止。
-- Rollback: 脚本不删除文件；应用确认后执行的文件清理不可逆，回退应用需停用清理任务并保留新增列及审计，不自动删列。
-- 加法式结构变更设置五秒锁等待，不回填历史文件期限；实际清理须满足权限、本人、原运行关闭、租约和存储身份核验。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
ALTER TABLE "datahub-center".dh_dataforge_etl_file_output
    ADD COLUMN IF NOT EXISTS retention_status varchar(16) NOT NULL DEFAULT 'KEEP',
    ADD COLUMN IF NOT EXISTS retire_after timestamp,
    ADD COLUMN IF NOT EXISTS retirement_requested_by bigint,
    ADD COLUMN IF NOT EXISTS retirement_reason varchar(500),
    ADD COLUMN IF NOT EXISTS purge_phase varchar(24) NOT NULL DEFAULT 'NONE';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.retention_status IS '保留状态：默认保留、已显式申请清理或已清理；文件发布历史状态保留';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.retire_after IS '经数据库时钟校验的申请到期清理时间，历史文件不补造期限';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.retirement_requested_by IS '经过本人及对象权限校验的清理申请主体';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.retirement_reason IS '显式清理原因，保留审计，不接受空原因';
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_file_output.purge_phase IS '清理阶段：尚未清理、持久意图、目标已删除或目标及锚点已核验删除';
DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='dh_etl_file_retention_ck'
        AND conrelid='"datahub-center".dh_dataforge_etl_file_output'::regclass) THEN
        ALTER TABLE "datahub-center".dh_dataforge_etl_file_output ADD CONSTRAINT dh_etl_file_retention_ck
            CHECK(retention_status IN ('KEEP','REQUESTED','PURGED'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='dh_etl_file_purge_phase_ck'
        AND conrelid='"datahub-center".dh_dataforge_etl_file_output'::regclass) THEN
        ALTER TABLE "datahub-center".dh_dataforge_etl_file_output ADD CONSTRAINT dh_etl_file_purge_phase_ck
            CHECK(purge_phase IN ('NONE','INTENT','TARGET_REMOVED','COMPLETE'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='dh_etl_file_retire_request_ck'
        AND conrelid='"datahub-center".dh_dataforge_etl_file_output'::regclass) THEN
        ALTER TABLE "datahub-center".dh_dataforge_etl_file_output ADD CONSTRAINT dh_etl_file_retire_request_ck
            CHECK(retention_status='KEEP' OR (retire_after IS NOT NULL
                AND retirement_requested_by IS NOT NULL AND retirement_requested_by>0
                AND retirement_reason IS NOT NULL AND length(btrim(retirement_reason)) BETWEEN 1 AND 500));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='dh_etl_file_purged_complete_ck'
        AND conrelid='"datahub-center".dh_dataforge_etl_file_output'::regclass) THEN
        ALTER TABLE "datahub-center".dh_dataforge_etl_file_output ADD CONSTRAINT dh_etl_file_purged_complete_ck
            CHECK(retention_status<>'PURGED' OR purge_phase='COMPLETE');
    END IF;
END $constraints$;
CREATE INDEX IF NOT EXISTS dh_etl_file_retirement_due_idx
    ON "datahub-center".dh_dataforge_etl_file_output(retire_after,next_attempt_at,id)
    WHERE deleted=0 AND retention_status='REQUESTED';
DO $menus$
DECLARE parent bigint; menu_id bigint; matches integer; seq regclass;
BEGIN
    IF to_regclass('system_menu') IS NULL THEN
        -- 组件隔离数据库只有文件表；完整平台必须具备系统菜单，不以此分支代替平台部署。
        RAISE NOTICE '仅文件组件隔离库未包含系统菜单，跳过清理按钮登记';
        RETURN;
    END IF;
    LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
    SELECT count(*),min(id) INTO matches,parent FROM system_menu
        WHERE deleted=0 AND type=2 AND status=0
            AND trim(both '/' from component)='dataforge/etl/record/index';
    IF matches<>1 THEN RAISE EXCEPTION '需先确认唯一有效的ETL运行记录菜单'; END IF;
    seq:=COALESCE(pg_get_serial_sequence('system_menu','id')::regclass,to_regclass('system_menu_seq'));
    IF seq IS NULL THEN RAISE EXCEPTION '缺少系统菜单编号序列'; END IF;
    SELECT count(*),min(id) INTO matches,menu_id FROM system_menu
        WHERE permission='dataforge:etl:file-cleanup';
    IF matches>1 THEN RAISE EXCEPTION 'ETL文件清理权限存在重复'; END IF;
    IF matches=1 THEN
        IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id AND parent_id=parent
            AND type=3 AND status=0 AND deleted=0) THEN
            RAISE EXCEPTION 'ETL文件清理权限位置或状态冲突';
        END IF;
    ELSE
        menu_id:=nextval(seq);
        WHILE EXISTS(SELECT 1 FROM system_menu WHERE id=menu_id) LOOP menu_id:=nextval(seq); END LOOP;
        INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,
            status,visible,keep_alive,always_show,creator,updater,create_time,update_time,deleted)
        VALUES(menu_id,'申请及恢复本人文件清理','dataforge:etl:file-cleanup',3,99,parent,'','',NULL,NULL,
            0,true,true,true,'migration:0117','migration:0117',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,0);
    END IF;
    -- 新的不可逆操作权限由管理员按职责单独授权，不自动扩展既有角色授权。
END $menus$;
COMMIT;

-- 新库同步增量：0118_governance_clean-rule-config.sql
-- Migration: 0118
-- Purpose: 持久化治理清洗规则的函数参数，为ETL冻结执行提供服务器端配置来源。
-- Depends on: 0117_dataforge_etl-file-retirement.sql；平台已存在dh_governance_clean_rule清洗规则表。
-- Target: 已有平台PostgreSQL库；新库使用同步全量基线。
-- Repeatable: 是；不回填历史缺失参数，不改写清洗规则或已发布版本。
-- Rollback: 加法式变更；回退应用保留参数列和冻结计划，删列会不可逆丢失规则参数，不自动回滚。
-- 旧记录空值保留为未知；应用按函数真实默认值和参数规范校验，新配置必须是大小有界的JSON对象。
BEGIN;
SET LOCAL lock_timeout = '5s';
ALTER TABLE "datahub-center".dh_governance_clean_rule ADD COLUMN IF NOT EXISTS config_json jsonb;
COMMENT ON COLUMN "datahub-center".dh_governance_clean_rule.config_json IS '服务器端清洗函数参数对象，历史空值不补造配置，ETL冻结时与规则共同绑定摘要';
DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='dh_clean_rule_config_budget_ck'
        AND conrelid='"datahub-center".dh_governance_clean_rule'::regclass) THEN
        ALTER TABLE "datahub-center".dh_governance_clean_rule ADD CONSTRAINT dh_clean_rule_config_budget_ck
            CHECK(config_json IS NULL OR (jsonb_typeof(config_json)='object'
                AND octet_length(convert_to(config_json::text,'UTF8'))<=65536));
    END IF;
END $constraints$;
COMMIT;

-- 新库同步增量：0119_dataforge_etl-runtime-observation.sql
-- Migration: 0119
-- Purpose: 保存ETL正式运行的运行观测快照（节点实时读写行数、连线队列与等待时间、有界吞吐趋势），供运行详情和设计器展示。
-- Depends on: 0118_governance_clean-rule-config.sql 及之前编号已按部署账本应用；平台已存在dh_dataforge_etl_record运行记录表。
-- Target: 已有平台PostgreSQL库；新库使用同步全量基线。
-- Repeatable: 是；列与约束均先检查存在性，不回填历史运行。
-- Rollback: 加法式变更；回退应用可保留该列，删除列只丢失观测快照，不影响运行结果、提交回执与审计。
-- 历史运行保持空值，表示未记录观测；快照为近似采样，不作为提交、质量或计量依据。增加检查约束会扫描一次运行记录表。
BEGIN;
SET LOCAL lock_timeout = '5s';
ALTER TABLE "datahub-center".dh_dataforge_etl_record ADD COLUMN IF NOT EXISTS runtime_metrics_json jsonb;
COMMENT ON COLUMN "datahub-center".dh_dataforge_etl_record.runtime_metrics_json IS '运行观测快照：节点实时读写行数、连线队列与等待时间及有界吞吐趋势；历史空值表示未记录，不代表没有流量';
DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_etl_record_runtime_metrics'
        AND conrelid='"datahub-center".dh_dataforge_etl_record'::regclass) THEN
        ALTER TABLE "datahub-center".dh_dataforge_etl_record ADD CONSTRAINT ck_etl_record_runtime_metrics
            CHECK(runtime_metrics_json IS NULL OR (jsonb_typeof(runtime_metrics_json)='object'
                AND octet_length(convert_to(runtime_metrics_json::text,'UTF8'))<=131072));
    END IF;
END $constraints$;
COMMIT;

-- 新库同步增量：0120_modeling_single-target.sql
-- Migration: 0120 建模单目标部署入口
-- Purpose: 每个物理模型只使用自身的数据源和目标表，停用历史环境目标管理按钮权限。
-- Depends on: 0119_dataforge_etl-runtime-observation.sql；0113_modeling_review-workspace-permissions.sql 已建立建模工作台权限，平台存在 system_menu。
-- Target: 已有 PostgreSQL 平台库；新库使用同步至 0120 的全量基线。
-- Repeatable: 是；仅更新仍启用或可见的指定按钮，重放不改写已停用记录。
-- Rollback: 不删除角色授权、历史环境配置、部署记录或基线；回退旧应用如需恢复入口，应另建编号迁移恢复按钮状态并核对角色授权。
-- 风险：事务内仅取得指定菜单行的短暂更新锁；不执行目标数据源 DDL，不修补无法核验的历史部署状态。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '5s';
UPDATE system_menu
SET status = 1, visible = false, updater = 'migration:0120', update_time = CURRENT_TIMESTAMP
WHERE permission = 'modeling:workspace:environment'
  AND type = 3 AND deleted = 0
  AND (status IS DISTINCT FROM 1 OR visible IS DISTINCT FROM false);
COMMIT;

-- 新库同步增量：0121_dataforge_dev-program-config.sql
-- Migration: 0121 数据研发程序配置
-- Purpose: 为 Flink 与 Spark 的 SQL、JAR、Python 任务保存版本化程序配置，历史任务保持空值，不推断运行能力。
-- Depends on: 0120_modeling_single-target.sql 及之前编号已按部署账本应用；平台已存在 dh_dataforge_dev_task 研发任务表。
-- Target: 已有 PostgreSQL 平台库；新库使用同步至 0121 的全量基线。
-- Repeatable: 是；列与约束均先检查存在性，不回填历史任务，也不改写已发布快照或在途运行。
-- Rollback: 加法式变更；回退应用保留配置列，删除列会不可逆丢失程序配置，不自动回滚。
-- 风险：增加列和检查约束会短暂持有表锁，约束校验扫描研发任务表；建议研发调度暂停后的维护窗口执行。
-- 配置只能为空或 JSON 对象；结构版本由业务入口验证，数据库不将未来版本强制改写为当前版本。
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '10min';
ALTER TABLE "datahub-center".dh_dataforge_dev_task ADD COLUMN IF NOT EXISTS program_config_json jsonb;
COMMENT ON COLUMN "datahub-center".dh_dataforge_dev_task.program_config_json IS '版本化程序配置对象：引擎、运行目标、入口与依赖；历史空值不补造配置，执行能力以已验证的适配器为准';
DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname='ck_dev_task_program_config'
        AND conrelid='"datahub-center".dh_dataforge_dev_task'::regclass) THEN
        ALTER TABLE "datahub-center".dh_dataforge_dev_task ADD CONSTRAINT ck_dev_task_program_config
            CHECK (program_config_json IS NULL OR jsonb_typeof(program_config_json)='object');
    END IF;
END $constraints$;
COMMIT;

-- 统一模型新安装结构：空业务模型无需历史差异确认；这里的声明仅用于新版空库初始化。
-- Migration: 0123 统一模型设计与历史映射准备
-- Purpose: 扩展统一表模型、记录历史映射与完整备份，独立物理模型转为唯一设计草稿；不执行目标数据库 DDL。
-- Depends on: 0122_governance_remove-data-lifecycle.sql 及其全部前置迁移，特别是 0079、0112；已有完整建模表及协作表。
-- Target: 已有 PostgreSQL 的 "datahub-center" 模式；维护窗口停止模型、审批、部署写入后执行。
-- Repeatable: 清理前可重放，既有映射不重复创建；0124 完成后拒绝逆向重放。本事务失败全部回滚，序列可能产生空号。
-- Rollback: 0124 前可回切旧应用，新增设计须通过映射审查后停用；0124 后按停机前数据库备份恢复，不能只回滚代码。
-- 风险：全量 JSONB 备份占用空间，模型表及审批、授权表加写锁；应先估算容量并保留数据库外部备份。
-- 本脚本只交付候选升级方案，当前旧应用不可执行后续 0124；新应用必须实现文档中的双端对象授权与历史只读契约。
BEGIN;
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

CREATE TABLE IF NOT EXISTS dh_modeling_unification_state (
    migration_key varchar(32) PRIMARY KEY,
    phase varchar(20) NOT NULL CHECK (phase IN ('PREPARED','CLEANED')),
    operator_name varchar(128) NOT NULL,
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE dh_modeling_unification_state IS '模型统一升级的全局执行阶段账本，不是业务模型';
COMMENT ON COLUMN dh_modeling_unification_state.migration_key IS '升级契约编号';
COMMENT ON COLUMN dh_modeling_unification_state.phase IS '阶段：准备完成或旧字段清理完成';
COMMENT ON COLUMN dh_modeling_unification_state.operator_name IS '执行迁移的数据库身份';
COMMENT ON COLUMN dh_modeling_unification_state.create_time IS '首次准备时间';
COMMENT ON COLUMN dh_modeling_unification_state.update_time IS '阶段最近完成时间';

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='UNIFIED_MODEL_V1' AND phase='CLEANED') THEN
        RAISE EXCEPTION '0124 已完成，禁止重放扩展阶段；应按部署账本跳过 0123';
    END IF;
END $preflight$;

LOCK TABLE dh_modeling_logic_model, dh_modeling_logic_model_version,
    dh_modeling_physical_model, dh_modeling_physical_model_version, dh_modeling_logic_relation,
    dh_modeling_collaboration, dh_modeling_collaborator, dh_modeling_approval,
    dh_modeling_deploy_record, dh_modeling_model_check, dh_modeling_environment_target IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM dh_modeling_approval WHERE deleted=0 AND kind IN ('LOGIC','PHYSICAL')
        AND status IN ('START_PENDING','RUNNING','APPROVED','CANCEL_PENDING','MANUAL')) THEN
        RAISE EXCEPTION '存在未完结的逻辑或物理模型审批，须先撤回、消费或完成对账，不得修改冻结候选';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_model_check WHERE deleted=0 AND task_status NOT IN ('SUCCESS','FAILED','CANCELLED')) THEN
        RAISE EXCEPTION '仍有排队、运行中或取消待确认的模型检测，须先结束检测并停止消费任务';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_deploy_record WHERE deleted=0 AND
        (((metadata_payload IS NOT NULL OR metadata_status IS NOT NULL) AND metadata_status IS DISTINCT FROM 'SUCCEEDED')
         OR (baseline_status IS NOT NULL AND baseline_status<>'SAVED')
         OR delivery_lease_until>CURRENT_TIMESTAMP)) THEN
        RAISE EXCEPTION '部署虽可能已完成，但元数据或基线登记仍未完成；先完成可靠投递和对账';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_deploy_record WHERE deleted=0 AND status NOT IN ('SUCCEEDED','FAILED'))
        OR EXISTS (SELECT 1 FROM dh_modeling_physical_model WHERE deleted=0
            AND COALESCE(deploy_status,'NOT_DEPLOYED') NOT IN ('NOT_DEPLOYED','SUCCEEDED','FAILED')) THEN
        RAISE EXCEPTION '存在运行中、排队中、核验中或结果未知的部署，须先完成真实核验';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_physical_model p LEFT JOIN dh_modeling_logic_model l
        ON l.id=p.logic_model_id AND l.tenant_id=p.tenant_id
        WHERE p.logic_model_id IS NOT NULL AND (l.id IS NULL OR (p.deleted=0 AND l.deleted<>0))) THEN
        RAISE EXCEPTION '物理模型引用的逻辑模型不存在、跨租户或已删除；必须先在旧应用中纠正，禁止按名称合并';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_logic_model_version v LEFT JOIN dh_modeling_logic_model m
        ON m.id=v.model_id AND m.tenant_id=v.tenant_id WHERE m.id IS NULL)
        OR EXISTS (SELECT 1 FROM dh_modeling_physical_model_version v LEFT JOIN dh_modeling_physical_model m
        ON m.id=v.model_id AND m.tenant_id=v.tenant_id WHERE m.id IS NULL) THEN
        RAISE EXCEPTION '版本存在孤儿或跨租户引用，须先修复来源记录，不能静默迁移';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_physical_model ph WHERE ph.deleted=0 AND NOT EXISTS(
        SELECT 1 FROM dh_modeling_physical_model_version v WHERE v.tenant_id=ph.tenant_id AND v.model_id=ph.id
            AND v.version=ph.latest_version AND v.deleted=0))
        OR EXISTS (SELECT 1 FROM dh_modeling_logic_model lm WHERE lm.deleted=0 AND NOT EXISTS(
        SELECT 1 FROM dh_modeling_logic_model_version v WHERE v.tenant_id=lm.tenant_id AND v.model_id=lm.id
            AND v.version=lm.latest_version AND v.deleted=0)) THEN
        RAISE EXCEPTION '有效模型最新版本指针不存在或只指向已删除版本，不能从删除内容恢复草稿';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_logic_model_version WHERE deleted=0 GROUP BY tenant_id,model_id,version HAVING count(*)>1)
        OR EXISTS (SELECT 1 FROM dh_modeling_physical_model_version WHERE deleted=0 GROUP BY tenant_id,model_id,version HAVING count(*)>1) THEN
        RAISE EXCEPTION '存在同模型同版本号的重复有效记录，须先核实历史版本';
    END IF;
END $preflight$;

ALTER TABLE dh_modeling_logic_model ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
ALTER TABLE dh_modeling_logic_model_version ADD COLUMN IF NOT EXISTS relation_snapshot jsonb;
ALTER TABLE dh_modeling_physical_model ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
ALTER TABLE dh_modeling_physical_model_version ADD COLUMN IF NOT EXISTS design_version_id bigint;
ALTER TABLE dh_modeling_physical_model_version ADD COLUMN IF NOT EXISTS definition_origin varchar(24);
ALTER TABLE dh_modeling_logic_relation ADD COLUMN IF NOT EXISTS field_pairs jsonb;
ALTER TABLE dh_modeling_logic_relation ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_modeling_logic_model.revision IS '统一设计聚合乐观锁；字段、关系或业务口径变更在同一事务递增';
COMMENT ON COLUMN dh_modeling_logic_model_version.relation_snapshot IS '本版本发布时冻结的关系及字段标识快照；历史未知保持为空，不根据现状伪造';
COMMENT ON COLUMN dh_modeling_physical_model.revision IS '部署绑定配置乐观锁，与统一设计修订号独立';
COMMENT ON COLUMN dh_modeling_physical_model_version.design_version_id IS '本次物理候选精确采用的统一设计版本；旧版本来源无法证明时保持为空';
COMMENT ON COLUMN dh_modeling_physical_model_version.definition_origin IS '定义来源：LEGACY_PUBLISHED 历史发布、LEGACY_DRAFT 历史独立草稿、UNIFIED 统一设计派生';
COMMENT ON COLUMN dh_modeling_logic_relation.field_pairs IS '有序复合关联键数组：[{sourceFieldUid,targetFieldUid}]；历史只按名称保存的关联保持为空待确认';
COMMENT ON COLUMN dh_modeling_logic_relation.revision IS '关系编辑乐观锁；同时更新涉及的设计聚合修订号';

-- 当前历史快照从未冻结精确逻辑版本来源；不可用可变头 source_logic_version_id 猜测所有旧版本。
UPDATE dh_modeling_physical_model_version
SET definition_origin=CASE WHEN status='PUBLISHED' THEN 'LEGACY_PUBLISHED' ELSE 'LEGACY_DRAFT' END
WHERE definition_origin IS NULL;
ALTER TABLE dh_modeling_physical_model_version ALTER COLUMN definition_origin SET NOT NULL;
-- 准备阶段兼容旧服务新增草稿；0124 切换后默认改为 UNIFIED，未带精确设计版本的写入将失败。
ALTER TABLE dh_modeling_physical_model_version ALTER COLUMN definition_origin SET DEFAULT 'LEGACY_DRAFT';

CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_active_name ON dh_modeling_logic_model(tenant_id,name) WHERE deleted=0;
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_active_code ON dh_modeling_logic_model(tenant_id,code) WHERE deleted=0 AND code IS NOT NULL AND code<>'';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_tenant_id ON dh_modeling_logic_model(tenant_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_version_tenant_id ON dh_modeling_logic_model_version(tenant_id,id);
CREATE INDEX IF NOT EXISTS idx_modeling_physical_design ON dh_modeling_physical_model(tenant_id,logic_model_id);
CREATE INDEX IF NOT EXISTS idx_modeling_physical_version_design ON dh_modeling_physical_model_version(tenant_id,design_version_id);

DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_physical_model_version'::regclass AND conname='ck_modeling_definition_origin') THEN
        ALTER TABLE dh_modeling_physical_model_version ADD CONSTRAINT ck_modeling_definition_origin CHECK (
            definition_origin IN ('LEGACY_PUBLISHED','LEGACY_DRAFT','UNIFIED')
            AND (definition_origin<>'UNIFIED' OR design_version_id IS NOT NULL));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_physical_model_version'::regclass AND conname='fk_modeling_physical_design_version') THEN
        ALTER TABLE dh_modeling_physical_model_version ADD CONSTRAINT fk_modeling_physical_design_version
            FOREIGN KEY (tenant_id,design_version_id) REFERENCES dh_modeling_logic_model_version(tenant_id,id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_logic_relation'::regclass AND conname='ck_modeling_relation_field_pairs') THEN
        ALTER TABLE dh_modeling_logic_relation ADD CONSTRAINT ck_modeling_relation_field_pairs CHECK (
            field_pairs IS NULL OR (jsonb_typeof(field_pairs)='array' AND jsonb_array_length(field_pairs)>0));
    END IF;
END $constraints$;

CREATE TABLE IF NOT EXISTS dh_modeling_unification_map (
    tenant_id bigint NOT NULL,
    physical_model_id bigint NOT NULL,
    logic_model_id bigint NOT NULL,
    migration_kind varchar(16) NOT NULL CHECK (migration_kind IN ('LINKED','CREATED')),
    original_head jsonb NOT NULL,
    original_versions jsonb NOT NULL,
    original_policy jsonb,
    original_members jsonb NOT NULL,
    canonical_head jsonb NOT NULL,
    canonical_versions jsonb NOT NULL,
    canonical_policy jsonb,
    canonical_members jsonb NOT NULL,
    review_issues jsonb NOT NULL DEFAULT '[]',
    review_status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK (review_status IN ('PENDING','CONFIRMED')),
    review_evidence jsonb,
    reviewed_by varchar(128),
    reviewed_at timestamp,
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id,physical_model_id),
    CONSTRAINT ck_modeling_unification_review CHECK (
        review_status<>'CONFIRMED' OR (review_evidence IS NOT NULL AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL))
);
COMMENT ON TABLE dh_modeling_unification_map IS '旧物理模型到统一设计的迁移映射与证据备份，仅供迁移追溯，不作为第三套业务定义';
COMMENT ON COLUMN dh_modeling_unification_map.tenant_id IS '所属租户';
COMMENT ON COLUMN dh_modeling_unification_map.physical_model_id IS '原物理模型编号，切换后仍为部署绑定编号';
COMMENT ON COLUMN dh_modeling_unification_map.logic_model_id IS '唯一设计编号，沿用逻辑模型编号';
COMMENT ON COLUMN dh_modeling_unification_map.migration_kind IS '已有明确链接或由独立物理模型创建草稿';
COMMENT ON COLUMN dh_modeling_unification_map.original_head IS '删除重复列前的完整物理模型头，保持原始证据';
COMMENT ON COLUMN dh_modeling_unification_map.original_versions IS '原物理模型全部历史版本备份，包含逻辑删除版本，不改写发布证据';
COMMENT ON COLUMN dh_modeling_unification_map.original_policy IS '原物理对象有效协作策略；空表示原有默认权限';
COMMENT ON COLUMN dh_modeling_unification_map.original_members IS '原物理对象有效协作授权';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_head IS '准备时唯一设计头，用于审查及漂移校验';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_versions IS '准备时唯一设计全部版本，用于漂移校验';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_policy IS '准备时唯一设计有效协作策略';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_members IS '准备时唯一设计有效协作授权';
COMMENT ON COLUMN dh_modeling_unification_map.review_issues IS '需要审查的历史差异及缺失项，不等于审批通过';
COMMENT ON COLUMN dh_modeling_unification_map.review_status IS '迁移人工审查状态，与业务发布审批独立';
COMMENT ON COLUMN dh_modeling_unification_map.review_evidence IS '决定保留唯一设计并归档旧独立内容的审查证据及双端授权约定';
COMMENT ON COLUMN dh_modeling_unification_map.reviewed_by IS '实际执行审查确认的数据库身份';
COMMENT ON COLUMN dh_modeling_unification_map.reviewed_at IS '迁移审查确认时间';
COMMENT ON COLUMN dh_modeling_unification_map.create_time IS '映射准备时间';
COMMENT ON COLUMN dh_modeling_unification_map.update_time IS '审查状态最近更新时间';

CREATE OR REPLACE FUNCTION dh_modeling_unification_acl(p_tenant bigint,p_kind text,p_id bigint,p_creator text)
RETURNS jsonb LANGUAGE sql STABLE SET search_path="datahub-center",pg_catalog AS $fn$
    SELECT jsonb_build_object(
        'defaultCreator', CASE WHEN c.id IS NULL THEN p_creator ELSE NULL END,
        'policy', CASE WHEN c.id IS NULL THEN NULL ELSE
            jsonb_build_object('owner',c.owner_user_id,'visibility',c.visibility,
                'approvalRequired',c.approval_required,'processDefinitionKey',c.process_definition_key) END,
        'members',COALESCE((SELECT jsonb_agg(jsonb_build_object('principalType',g.principal_type,
            'principalId',g.principal_id,'actions',g.actions) ORDER BY g.principal_type,g.principal_id)
            FROM dh_modeling_collaborator g WHERE g.tenant_id=p_tenant AND g.kind=p_kind
              AND g.model_id=p_id AND g.deleted=0),'[]'::jsonb))
    FROM (SELECT 1) anchor LEFT JOIN dh_modeling_collaboration c ON c.tenant_id=p_tenant
        AND c.kind=p_kind AND c.model_id=p_id AND c.deleted=0;
$fn$;
COMMENT ON FUNCTION dh_modeling_unification_acl(bigint,text,bigint,text) IS '迁移期间比较有效对象授权，不自动合并或扩大权限';

-- 仅物理模型没有任何逻辑链接时创建新草稿；已有链接永不按名称重新合并或覆盖逻辑字段。
DO $backfill$
DECLARE p record; l record; pv record; lv record; canonical_id bigint; issues jsonb;
BEGIN
    FOR p IN SELECT * FROM dh_modeling_physical_model ORDER BY tenant_id,id LOOP
        IF EXISTS (SELECT 1 FROM dh_modeling_unification_map WHERE tenant_id=p.tenant_id AND physical_model_id=p.id) THEN
            CONTINUE;
        END IF;
        canonical_id:=p.logic_model_id;
        SELECT * INTO pv FROM dh_modeling_physical_model_version
            WHERE tenant_id=p.tenant_id AND model_id=p.id AND version=p.latest_version AND (p.deleted<>0 OR deleted=0)
            ORDER BY deleted,id DESC LIMIT 1;
        issues:='[]'::jsonb;
        IF pv.id IS NULL THEN issues:=issues||'["MISSING_LATEST_VERSION"]'::jsonb; END IF;

        IF canonical_id IS NULL THEN
            IF p.deleted=0 AND EXISTS (SELECT 1 FROM dh_modeling_logic_model lm WHERE lm.tenant_id=p.tenant_id
                AND lm.deleted=0 AND (lm.name=p.name OR (NULLIF(p.code,'') IS NOT NULL AND lm.code=p.code))) THEN
                RAISE EXCEPTION '独立物理模型 % 与已有统一设计同名或同编码；须先明确改名或修复已有链接，不自动合并',p.id;
            END IF;
            INSERT INTO dh_modeling_logic_model(name,code,create_mode,latest_version,status,
                description,creator,create_time,updater,update_time,deleted,tenant_id,
                model_style,warehouse_layer,business_process_id,layer_id,subject_domain_id,
                table_type,classification_status,data_domain_id,grain)
            VALUES(p.name,p.code,'REVERSE',1,'REVISING',p.description,
                p.creator,p.create_time,p.updater,p.update_time,p.deleted,p.tenant_id,
                p.model_style,p.warehouse_layer,p.business_process_id,p.layer_id,p.subject_domain_id,
                p.table_type,p.classification_status,p.data_domain_id,
                COALESCE(pv.type_config#>>'{detail,grainDescription}',
                    pv.type_config#>>'{summary,grainDescription}',pv.type_config#>>'{application,grainDescription}'))
            RETURNING id INTO canonical_id;
            INSERT INTO dh_modeling_logic_model_version(model_id,version,status,fields,type_config,remark,
                creator,updater,deleted,tenant_id)
            VALUES(canonical_id,1,'REVISING',COALESCE(pv.fields,'[]'::jsonb),pv.type_config,
                '由独立物理模型迁移的设计草稿；历史发布记录保留在原物理版本，不代表该草稿已发布',
                p.creator,p.updater,p.deleted,p.tenant_id);
            INSERT INTO dh_modeling_collaboration(tenant_id,kind,model_id,owner_user_id,visibility,
                approval_required,process_definition_key,revision,creator,create_time,updater,update_time,deleted)
            SELECT tenant_id,'LOGIC',canonical_id,owner_user_id,visibility,approval_required,
                process_definition_key,revision,creator,create_time,updater,update_time,deleted
            FROM dh_modeling_collaboration WHERE tenant_id=p.tenant_id AND kind='PHYSICAL' AND model_id=p.id AND deleted=0;
            INSERT INTO dh_modeling_collaborator(tenant_id,kind,model_id,principal_type,principal_id,actions,
                creator,create_time,updater,update_time,deleted)
            SELECT tenant_id,'LOGIC',canonical_id,principal_type,principal_id,actions,
                creator,create_time,updater,update_time,deleted
            FROM dh_modeling_collaborator WHERE tenant_id=p.tenant_id AND kind='PHYSICAL' AND model_id=p.id AND deleted=0;
            issues:=issues||'["NEW_DESIGN_DRAFT"]'::jsonb;
        END IF;
        SELECT * INTO STRICT l FROM dh_modeling_logic_model WHERE tenant_id=p.tenant_id AND id=canonical_id;
        SELECT * INTO lv FROM dh_modeling_logic_model_version
            WHERE tenant_id=l.tenant_id AND model_id=l.id AND version=l.latest_version
            ORDER BY deleted,id DESC LIMIT 1;
        IF p.logic_model_id IS NOT NULL AND
            (pv.fields IS DISTINCT FROM lv.fields OR pv.type_config IS DISTINCT FROM lv.type_config
             OR ROW(p.name,p.code,p.description,p.layer_id,p.data_domain_id,p.subject_domain_id,p.business_process_id,p.table_type,p.model_style,p.warehouse_layer)
                IS DISTINCT FROM ROW(l.name,l.code,l.description,l.layer_id,l.data_domain_id,l.subject_domain_id,l.business_process_id,l.table_type,l.model_style,l.warehouse_layer)) THEN
            issues:=issues||'["DESIGN_DIVERGENCE"]'::jsonb;
        END IF;
        IF EXISTS (SELECT 1 FROM dh_modeling_physical_model_version WHERE tenant_id=p.tenant_id AND model_id=p.id AND design_version_id IS NULL) THEN
            issues:=issues||'["UNKNOWN_VERSION_SOURCE"]'::jsonb;
        END IF;
        IF EXISTS (SELECT 1 FROM dh_modeling_physical_model_version WHERE tenant_id=p.tenant_id AND model_id=p.id AND status='PUBLISHED' AND model_snapshot IS NULL) THEN
            issues:=issues||'["MISSING_HISTORICAL_SNAPSHOT"]'::jsonb;
        END IF;
        IF COALESCE(jsonb_typeof(lv.fields),'null')<>'array' THEN
            issues:=issues||'["INVALID_OR_MISSING_FIELDS"]'::jsonb;
        ELSIF EXISTS (SELECT 1 FROM jsonb_array_elements(lv.fields) f WHERE NULLIF(btrim(f->>'fieldUid'),'') IS NULL)
            OR EXISTS (SELECT 1 FROM jsonb_array_elements(lv.fields) f GROUP BY f->>'fieldUid' HAVING count(*)>1) THEN
            issues:=issues||'["MISSING_OR_DUPLICATE_FIELD_UID"]'::jsonb;
        END IF;
        IF dh_modeling_unification_acl(p.tenant_id,'PHYSICAL',p.id,p.creator)
            IS DISTINCT FROM dh_modeling_unification_acl(l.tenant_id,'LOGIC',l.id,l.creator) THEN
            IF p.logic_model_id IS NULL THEN RAISE EXCEPTION '新设计未完整继承物理对象权限：%',p.id; END IF;
            issues:=issues||'["INDEPENDENT_ACL_REQUIRED"]'::jsonb;
        END IF;
        INSERT INTO dh_modeling_unification_map(tenant_id,physical_model_id,logic_model_id,migration_kind,
            original_head,original_versions,original_policy,original_members,
            canonical_head,canonical_versions,canonical_policy,canonical_members,review_issues)
        SELECT p.tenant_id,p.id,l.id,CASE WHEN p.logic_model_id IS NULL THEN 'CREATED' ELSE 'LINKED' END,
            to_jsonb(p),COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id)
                FROM dh_modeling_physical_model_version v WHERE v.tenant_id=p.tenant_id AND v.model_id=p.id),'[]'::jsonb),
            (SELECT to_jsonb(c) FROM dh_modeling_collaboration c WHERE c.tenant_id=p.tenant_id AND c.kind='PHYSICAL' AND c.model_id=p.id AND c.deleted=0),
            COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.id) FROM dh_modeling_collaborator c
                WHERE c.tenant_id=p.tenant_id AND c.kind='PHYSICAL' AND c.model_id=p.id AND c.deleted=0),'[]'::jsonb),
            to_jsonb(l),COALESCE((SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id)
                FROM dh_modeling_logic_model_version v WHERE v.tenant_id=l.tenant_id AND v.model_id=l.id),'[]'::jsonb),
            (SELECT to_jsonb(c) FROM dh_modeling_collaboration c WHERE c.tenant_id=l.tenant_id AND c.kind='LOGIC' AND c.model_id=l.id AND c.deleted=0),
            COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.id) FROM dh_modeling_collaborator c
                WHERE c.tenant_id=l.tenant_id AND c.kind='LOGIC' AND c.model_id=l.id AND c.deleted=0),'[]'::jsonb),issues;
    END LOOP;
END $backfill$;

CREATE OR REPLACE FUNCTION dh_modeling_unification_evidence_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION '模型迁移原始证据不可删除'; END IF;
    IF (to_jsonb(NEW)-ARRAY['review_status','review_evidence','reviewed_by','reviewed_at','update_time'])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['review_status','review_evidence','reviewed_by','reviewed_at','update_time']) THEN
        RAISE EXCEPTION '模型迁移映射及原始备份不可修改';
    END IF;
    IF OLD.review_status='CONFIRMED' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
        RAISE EXCEPTION '已确认的模型迁移审查证据不可修改';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unification_evidence_guard() IS '保护切换备份与迁移审查证据，防止覆盖原始行或重置已确认决定';
DROP TRIGGER IF EXISTS modeling_unification_evidence_guard ON dh_modeling_unification_map;
CREATE TRIGGER modeling_unification_evidence_guard BEFORE UPDATE OR DELETE ON dh_modeling_unification_map
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unification_evidence_guard();

CREATE OR REPLACE FUNCTION dh_modeling_confirm_unification(p_tenant bigint,p_physical bigint,p_evidence jsonb)
RETURNS void LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
DECLARE m dh_modeling_unification_map%ROWTYPE;
BEGIN
    SELECT * INTO STRICT m FROM dh_modeling_unification_map
        WHERE tenant_id=p_tenant AND physical_model_id=p_physical FOR UPDATE;
    IF jsonb_typeof(p_evidence) IS DISTINCT FROM 'object'
        OR p_evidence->>'decision' IS DISTINCT FROM 'KEEP_LOGIC_ARCHIVE_PHYSICAL'
        OR p_evidence->>'aclDecision' IS DISTINCT FROM 'KEEP_INDEPENDENT_ACL'
        OR length(COALESCE(btrim(p_evidence->>'reason'),''))<10
        OR length(COALESCE(btrim(p_evidence->>'reviewer'),''))<1
        OR p_evidence->>'physicalDigest' IS DISTINCT FROM md5(m.original_head::text||m.original_versions::text)
        OR p_evidence->>'designDigest' IS DISTINCT FROM md5(m.canonical_head::text||m.canonical_versions::text)
        THEN RAISE EXCEPTION '须提交实际审查人、具体理由、双端独立权限决定和所审查物理/设计内容的摘要'; END IF;
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_physical_model WHERE tenant_id=p_tenant AND id=p_physical)
        OR NOT EXISTS (SELECT 1 FROM dh_modeling_logic_model WHERE tenant_id=p_tenant AND id=m.logic_model_id) THEN
        RAISE EXCEPTION '映射对象不存在或租户不一致';
    END IF;
    IF m.review_status='CONFIRMED' THEN
        IF m.review_evidence IS DISTINCT FROM p_evidence THEN RAISE EXCEPTION '已确认的审查证据不可覆盖'; END IF;
        RETURN;
    END IF;
    UPDATE dh_modeling_unification_map SET review_status='CONFIRMED',review_evidence=p_evidence,
        reviewed_by=current_user,reviewed_at=CURRENT_TIMESTAMP,update_time=CURRENT_TIMESTAMP
        WHERE tenant_id=p_tenant AND physical_model_id=p_physical;
END $fn$;
COMMENT ON FUNCTION dh_modeling_confirm_unification(bigint,bigint,jsonb) IS '停机迁移审查入口：仅确认保留唯一设计并归档旧差异，不审批、不发布、不扩大对象权限';
REVOKE ALL ON FUNCTION dh_modeling_confirm_unification(bigint,bigint,jsonb) FROM PUBLIC;
REVOKE ALL ON FUNCTION dh_modeling_unification_acl(bigint,text,bigint,text) FROM PUBLIC;

INSERT INTO dh_modeling_unification_state(migration_key,phase,operator_name)
VALUES('UNIFIED_MODEL_V1','PREPARED',current_user)
ON CONFLICT(migration_key) DO NOTHING;
COMMIT;

SET datahub.modeling_unified_cutover='UNIFIED_MODEL_V1';
-- Migration: 0124 统一模型部署绑定切换与重复字段清理
-- Purpose: 切换统一设计后删除部署绑定中的重复业务头；保留原编号、物理历史版本、部署日志、审批和跨模块引用。
-- Depends on: 0123_modeling_unified-definition.sql；全部映射已逐项审查，新版统一模型应用已完成验收且旧写入入口已停用。
-- Target: 已有 PostgreSQL 的 "datahub-center" 模式；旧应用不可使用此结构，所有建模、部署、审批服务及任务保持停写。
-- Repeatable: 是；同一清理契约完成后重放为幂等校验和触发器安装，不会重复转换或删除历史数据。
-- Rollback: 含 DROP COLUMN，不能单独回滚旧应用；恢复迁移前数据库备份和旧代码，或开发经过验证的逆迁移；映射原行 JSON 仅作恢复证据。
-- 风险：表级排他锁及删列不可在线回滚；禁止 CASCADE，外部依赖列的视图将令事务完整失败，须先在新版发布中处理真实依赖。
-- 执行前由部署人员在同一会话声明 SET datahub.modeling_unified_cutover='UNIFIED_MODEL_V1'；此声明不能代替新版验收。
-- 未完成、未知结果部署、活动审批、未审查差异、授权/内容漂移或孤儿引用均使整个事务回滚，不伪造审批或部署成功。
BEGIN;
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

LOCK TABLE dh_modeling_logic_model, dh_modeling_logic_model_version,
    dh_modeling_physical_model, dh_modeling_physical_model_version, dh_modeling_logic_relation,
    dh_modeling_collaboration, dh_modeling_collaborator, dh_modeling_approval,
    dh_modeling_deploy_record, dh_modeling_model_check, dh_modeling_environment_target,
    dh_modeling_unification_map, dh_modeling_unification_state IN SHARE ROW EXCLUSIVE MODE;

DO $cutover$
DECLARE m record; p record; l record; versions jsonb; policy jsonb; members jsonb; col text;
BEGIN
    IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='UNIFIED_MODEL_V1' AND phase='CLEANED') THEN
        RETURN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='UNIFIED_MODEL_V1' AND phase='PREPARED') THEN
        RAISE EXCEPTION '必须先完整执行 0123';
    END IF;
    IF current_setting('datahub.modeling_unified_cutover',true) IS DISTINCT FROM 'UNIFIED_MODEL_V1' THEN
        RAISE EXCEPTION '未声明已验收统一模型新版并停止旧写入；拒绝删除旧字段';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_approval WHERE deleted=0 AND kind IN ('LOGIC','PHYSICAL')
        AND status IN ('START_PENDING','RUNNING','APPROVED','CANCEL_PENDING','MANUAL')) THEN
        RAISE EXCEPTION '仍有活动、已通过待消费或人工处理中的审批，禁止切换';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_model_check WHERE deleted=0 AND task_status NOT IN ('SUCCESS','FAILED','CANCELLED')) THEN
        RAISE EXCEPTION '仍有排队、运行中或取消待确认的模型检测，须先结束检测并停止消费任务';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_deploy_record WHERE deleted=0 AND
        (((metadata_payload IS NOT NULL OR metadata_status IS NOT NULL) AND metadata_status IS DISTINCT FROM 'SUCCEEDED')
         OR (baseline_status IS NOT NULL AND baseline_status<>'SAVED')
         OR delivery_lease_until>CURRENT_TIMESTAMP)) THEN
        RAISE EXCEPTION '部署虽可能已完成，但元数据或基线登记仍未完成；先完成可靠投递和对账';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_deploy_record WHERE deleted=0 AND status NOT IN ('SUCCEEDED','FAILED'))
        OR EXISTS (SELECT 1 FROM dh_modeling_physical_model WHERE deleted=0
            AND COALESCE(deploy_status,'NOT_DEPLOYED') NOT IN ('NOT_DEPLOYED','SUCCEEDED','FAILED')) THEN
        RAISE EXCEPTION '仍有未终结或未知结果的部署，禁止切换';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_physical_model ph LEFT JOIN dh_modeling_unification_map mp
        ON mp.tenant_id=ph.tenant_id AND mp.physical_model_id=ph.id WHERE mp.physical_model_id IS NULL)
        OR EXISTS (SELECT 1 FROM dh_modeling_unification_map WHERE review_status<>'CONFIRMED') THEN
        RAISE EXCEPTION '存在未映射或未审查的物理模型；运行迁移审查查询并逐项确认，不可直接删除差异';
    END IF;

    FOR m IN SELECT * FROM dh_modeling_unification_map ORDER BY tenant_id,physical_model_id LOOP
        SELECT * INTO p FROM dh_modeling_physical_model WHERE tenant_id=m.tenant_id AND id=m.physical_model_id;
        SELECT * INTO l FROM dh_modeling_logic_model WHERE tenant_id=m.tenant_id AND id=m.logic_model_id;
        IF p.id IS NULL OR l.id IS NULL OR (p.deleted=0 AND l.deleted<>0)
            OR to_jsonb(p) IS DISTINCT FROM m.original_head
            OR to_jsonb(l) IS DISTINCT FROM m.canonical_head THEN
            RAISE EXCEPTION '迁移准备后模型头已变化或引用无效，租户 % 物理模型 %；须重新制定本次切换证据',m.tenant_id,m.physical_model_id;
        END IF;
        SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY v.id),'[]'::jsonb) INTO versions
            FROM dh_modeling_physical_model_version v WHERE tenant_id=m.tenant_id AND model_id=m.physical_model_id;
        IF versions IS DISTINCT FROM m.original_versions THEN
            RAISE EXCEPTION '准备后物理历史版本发生变化：%',m.physical_model_id;
        END IF;
        SELECT COALESCE(jsonb_agg(to_jsonb(v) ORDER BY v.id),'[]'::jsonb) INTO versions
            FROM dh_modeling_logic_model_version v WHERE tenant_id=m.tenant_id AND model_id=m.logic_model_id;
        IF versions IS DISTINCT FROM m.canonical_versions THEN
            RAISE EXCEPTION '准备后统一设计版本发生变化：%',m.logic_model_id;
        END IF;
        SELECT to_jsonb(c) INTO policy FROM dh_modeling_collaboration c
            WHERE tenant_id=m.tenant_id AND kind='PHYSICAL' AND model_id=m.physical_model_id AND deleted=0;
        SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]'::jsonb) INTO members FROM dh_modeling_collaborator c
            WHERE tenant_id=m.tenant_id AND kind='PHYSICAL' AND model_id=m.physical_model_id AND deleted=0;
        IF policy IS DISTINCT FROM m.original_policy OR members IS DISTINCT FROM m.original_members THEN
            RAISE EXCEPTION '准备后物理对象权限发生变化：%',m.physical_model_id;
        END IF;
        SELECT to_jsonb(c) INTO policy FROM dh_modeling_collaboration c
            WHERE tenant_id=m.tenant_id AND kind='LOGIC' AND model_id=m.logic_model_id AND deleted=0;
        SELECT COALESCE(jsonb_agg(to_jsonb(c) ORDER BY c.id),'[]'::jsonb) INTO members FROM dh_modeling_collaborator c
            WHERE tenant_id=m.tenant_id AND kind='LOGIC' AND model_id=m.logic_model_id AND deleted=0;
        IF policy IS DISTINCT FROM m.canonical_policy OR members IS DISTINCT FROM m.canonical_members THEN
            RAISE EXCEPTION '准备后统一设计权限发生变化：%',m.logic_model_id;
        END IF;
        IF m.migration_kind='CREATED' AND
            dh_modeling_unification_acl(p.tenant_id,'PHYSICAL',p.id,p.creator)
            IS DISTINCT FROM dh_modeling_unification_acl(l.tenant_id,'LOGIC',l.id,l.creator) THEN
            RAISE EXCEPTION '独立物理模型的权限未等价继承：%',m.physical_model_id;
        END IF;
    END LOOP;

    -- 部署与环境目标继续引用原物理编号，历史版本编号不变；检查不可用跨租户记录冒充有效引用。
    IF EXISTS (SELECT 1 FROM dh_modeling_environment_target t LEFT JOIN dh_modeling_physical_model ph
        ON ph.id=t.model_id AND ph.tenant_id=t.tenant_id WHERE ph.id IS NULL)
        OR EXISTS (SELECT 1 FROM dh_modeling_deploy_record d LEFT JOIN dh_modeling_physical_model_version v
        ON v.id=d.version_id AND v.tenant_id=d.tenant_id AND v.model_id=d.model_id WHERE v.id IS NULL) THEN
        RAISE EXCEPTION '环境目标或部署记录存在孤儿/跨租户引用，必须先核查，不能删除历史';
    END IF;
    UPDATE dh_modeling_physical_model ph SET logic_model_id=mp.logic_model_id
        FROM dh_modeling_unification_map mp WHERE ph.tenant_id=mp.tenant_id AND ph.id=mp.physical_model_id
          AND ph.logic_model_id IS DISTINCT FROM mp.logic_model_id;
    ALTER TABLE dh_modeling_physical_model ALTER COLUMN logic_model_id SET NOT NULL;
    ALTER TABLE dh_modeling_physical_model ADD CONSTRAINT fk_modeling_binding_design
        FOREIGN KEY (tenant_id,logic_model_id) REFERENCES dh_modeling_logic_model(tenant_id,id);

    -- 层级归属从此只由唯一设计负责；旧触发器会直接访问即将删除的 layer_id，必须同时卸载。
    DROP TRIGGER IF EXISTS trg_modeling_layer_reference ON dh_modeling_physical_model;
    DROP TRIGGER IF EXISTS modeling_ownership_reference_guard ON dh_modeling_physical_model;

    FOREACH col IN ARRAY ARRAY['theme_id','name','code','description','model_style','warehouse_layer',
        'layer_id','subject_domain_id','business_process_id','data_domain_id','table_type','classification_status']
    LOOP
        EXECUTE format('ALTER TABLE dh_modeling_physical_model DROP COLUMN IF EXISTS %I',col);
    END LOOP;
    ALTER TABLE dh_modeling_physical_model_version ALTER COLUMN definition_origin SET DEFAULT 'UNIFIED';
    UPDATE dh_modeling_unification_state SET phase='CLEANED',operator_name=current_user,update_time=CURRENT_TIMESTAMP
        WHERE migration_key='UNIFIED_MODEL_V1';
END $cutover$;

-- 表说明（原文）：数据建模-唯一表模型设计，列表、字段表单及 ER 画布共用此定义
COMMENT ON TABLE dh_modeling_logic_model IS '数据建模-逻辑模型';
-- 表说明（原文）：数据建模-统一设计版本，发布版本冻结业务定义与关系
COMMENT ON TABLE dh_modeling_logic_model_version IS '数据建模-逻辑模型版本';
COMMENT ON TABLE dh_modeling_physical_model IS '数据建模-统一模型的部署绑定，原物理编号保持不变';
COMMENT ON COLUMN dh_modeling_physical_model.logic_model_id IS '唯一设计编号；部署绑定必须关联同租户设计';
COMMENT ON COLUMN dh_modeling_physical_model.latest_version IS '最近物理候选版本号，独立于统一设计版本号';
COMMENT ON COLUMN dh_modeling_physical_model.status IS '部署候选准备状态，不能作为实际数据库部署成功状态';
COMMENT ON TABLE dh_modeling_physical_model_version IS '数据建模-部署候选及历史物理版本；历史独立草稿只读归档';

-- 保留全部既有规划引用保护，只移除已无业务归属列的物理绑定分支。
CREATE OR REPLACE FUNCTION "datahub-center".modeling_ownership_reference_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
DECLARE
    row_data jsonb; old_data jsonb; tenant bigint; object_id bigint;
    deleting boolean; tbl text; ref_field text; ref_table text; ref_id bigint;
    found_row boolean; primary_id bigint; model_table text;
BEGIN
    row_data := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    old_data := CASE WHEN TG_OP = 'INSERT' THEN '{}'::jsonb ELSE to_jsonb(OLD) END;
    tenant := (row_data->>'tenant_id')::bigint;
    object_id := (row_data->>'id')::bigint;
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-tenant:' || tenant::text, 0));
    deleting := TG_OP = 'DELETE' OR COALESCE((row_data->>'deleted')::integer, 0) <> 0;
    tbl := TG_TABLE_NAME;

    IF tbl IN ('dh_modeling_concept_model', 'dh_modeling_logic_model')
       AND NOT deleting THEN
        FOR ref_field, ref_table IN
            SELECT * FROM (VALUES
                ('data_domain_id','dh_modeling_data_domain'),
                ('subject_domain_id','dh_modeling_subject_domain'),
                ('business_process_id','dh_modeling_business_process'),
                ('layer_id','dh_modeling_dw_layer')) AS refs(field_name, table_name)
        LOOP
            ref_id := (row_data->>ref_field)::bigint;
            IF ref_id IS NOT NULL THEN
                EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND tenant_id=$2 AND deleted=0)', ref_table)
                    INTO found_row USING ref_id, tenant;
                IF NOT found_row THEN
                    RAISE EXCEPTION 'Model ownership reference missing or belongs to another tenant: %', ref_field USING ERRCODE='23514';
                END IF;
            END IF;
        END LOOP;
        SELECT p.data_domain_id INTO primary_id FROM "datahub-center".dh_modeling_business_process p
        WHERE p.id = (row_data->>'business_process_id')::bigint AND p.tenant_id = tenant AND p.deleted = 0;
        IF primary_id IS NOT NULL AND (row_data->>'data_domain_id')::bigint IS NOT NULL
           AND primary_id <> (row_data->>'data_domain_id')::bigint THEN
            RAISE EXCEPTION 'Model data domain must match process primary domain' USING ERRCODE='23514';
        END IF;
        IF row_data->>'business_process_id' IS NOT NULL AND row_data->>'subject_domain_id' IS NOT NULL
           AND NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_subject_domain_process_rel r
                           WHERE r.tenant_id=tenant AND r.deleted=0
                             AND r.business_process_id=(row_data->>'business_process_id')::bigint
                             AND r.subject_domain_id=(row_data->>'subject_domain_id')::bigint) THEN
            RAISE EXCEPTION 'Model subject domain and process are not associated' USING ERRCODE='23514';
        END IF;
    ELSIF tbl IN ('dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_business_process','dh_modeling_dw_layer')
       AND (deleting OR (tbl = 'dh_modeling_business_process' AND TG_OP = 'UPDATE'
                         AND old_data->>'data_domain_id' IS DISTINCT FROM row_data->>'data_domain_id')) THEN
        ref_field := CASE tbl WHEN 'dh_modeling_data_domain' THEN 'data_domain_id'
            WHEN 'dh_modeling_subject_domain' THEN 'subject_domain_id'
            WHEN 'dh_modeling_dw_layer' THEN 'layer_id' ELSE 'business_process_id' END;
        FOREACH model_table IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model']
        LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE %I=$1 AND tenant_id=$2 AND deleted=0
                AND ($3 OR $4 IS NOT NULL OR (data_domain_id IS NOT NULL AND data_domain_id IS DISTINCT FROM $5)))', model_table, ref_field)
                INTO found_row USING object_id, tenant, deleting, (old_data->>'data_domain_id')::bigint,
                    (row_data->>'data_domain_id')::bigint;
            IF found_row THEN
                RAISE EXCEPTION 'Planning object is referenced by a model; cannot delete or move ownership' USING ERRCODE='23514';
            END IF;
        END LOOP;
        IF deleting AND tbl = 'dh_modeling_data_domain' AND (
            EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_business_process p
                   WHERE p.tenant_id=tenant AND p.data_domain_id=object_id AND p.deleted=0)
            OR EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel r
                      WHERE r.tenant_id=tenant AND r.data_domain_id=object_id AND r.deleted=0)) THEN
            RAISE EXCEPTION 'Data domain is referenced by a business process' USING ERRCODE='23514';
        END IF;
    END IF;
    IF tbl = 'dh_modeling_subject_domain' AND deleting AND EXISTS (
        SELECT 1 FROM "datahub-center".dh_modeling_subject_domain_process_rel r
        WHERE r.tenant_id=tenant AND r.subject_domain_id=object_id AND r.deleted=0) THEN
        RAISE EXCEPTION 'Subject domain is referenced by a process' USING ERRCODE='23514';
    END IF;
    IF tbl = 'dh_modeling_subject_domain_process_rel' AND TG_OP <> 'INSERT'
       AND (deleting OR old_data->>'subject_domain_id' IS DISTINCT FROM row_data->>'subject_domain_id'
            OR old_data->>'business_process_id' IS DISTINCT FROM row_data->>'business_process_id') THEN
        FOREACH model_table IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model']
        LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE subject_domain_id=$1
                AND business_process_id=$2 AND tenant_id=$3 AND deleted=0)', model_table)
                INTO found_row USING (old_data->>'subject_domain_id')::bigint,
                    (old_data->>'business_process_id')::bigint, tenant;
            IF found_row THEN RAISE EXCEPTION 'Subject-process association is referenced by a model' USING ERRCODE='23514'; END IF;
        END LOOP;
    END IF;
    IF tbl IN ('dh_modeling_business_process_supporting_domain_rel','dh_modeling_subject_domain_process_rel') AND NOT deleting THEN
        SELECT p.data_domain_id INTO primary_id FROM "datahub-center".dh_modeling_business_process p
        WHERE p.id=(row_data->>'business_process_id')::bigint AND p.tenant_id=tenant AND p.deleted=0;
        IF NOT FOUND THEN RAISE EXCEPTION 'Association process missing or belongs to another tenant' USING ERRCODE='23514'; END IF;
        ref_field := CASE tbl WHEN 'dh_modeling_subject_domain_process_rel' THEN 'subject_domain_id' ELSE 'data_domain_id' END;
        ref_table := CASE tbl WHEN 'dh_modeling_subject_domain_process_rel' THEN 'dh_modeling_subject_domain' ELSE 'dh_modeling_data_domain' END;
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND tenant_id=$2 AND deleted=0)',ref_table)
            INTO found_row USING (row_data->>ref_field)::bigint, tenant;
        IF NOT found_row THEN RAISE EXCEPTION 'Association target missing or belongs to another tenant' USING ERRCODE='23514'; END IF;
        IF tbl='dh_modeling_business_process_supporting_domain_rel'
           AND (primary_id IS NULL OR primary_id=(row_data->>'data_domain_id')::bigint) THEN
            RAISE EXCEPTION 'Supporting domain requires a different confirmed primary domain' USING ERRCODE='23514';
        END IF;
    END IF;
    IF tbl = 'dh_modeling_business_process' AND NOT deleting AND row_data->>'data_domain_id' IS NOT NULL THEN
        IF NOT EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_data_domain d
                       WHERE d.id=(row_data->>'data_domain_id')::bigint AND d.tenant_id=tenant AND d.deleted=0) THEN
            RAISE EXCEPTION 'Process primary domain missing or belongs to another tenant' USING ERRCODE='23514';
        END IF;
        IF EXISTS (SELECT 1 FROM "datahub-center".dh_modeling_business_process_supporting_domain_rel r
                   WHERE r.business_process_id=object_id AND r.tenant_id=tenant AND r.deleted=0
                     AND r.data_domain_id=(row_data->>'data_domain_id')::bigint) THEN
            RAISE EXCEPTION 'Primary and supporting domains cannot overlap' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END $guard$;
COMMENT ON FUNCTION "datahub-center".modeling_ownership_reference_guard() IS '统一设计接管业务归属后，保护概念模型、统一设计及规划对象的租户与引用不变量';
CREATE OR REPLACE FUNCTION "datahub-center".modeling_guard_layer_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='UPDATE' THEN
  IF NEW.deleted=OLD.deleted AND NEW.status=OLD.status AND NEW.node_type=OLD.node_type
    AND NEW.layer_code IS NOT DISTINCT FROM OLD.layer_code AND NEW.table_prefix IS NOT DISTINCT FROM OLD.table_prefix
    AND NEW.default_table_type IS NOT DISTINCT FROM OLD.default_table_type THEN RETURN NEW; END IF;
 END IF;
 IF EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_concept_model WHERE tenant_id=OLD.tenant_id AND layer_id=OLD.id AND deleted=0)
 OR EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_logic_model WHERE tenant_id=OLD.tenant_id AND layer_id=OLD.id AND deleted=0) THEN
  RAISE EXCEPTION '分层已被模型引用，不能删除、停用或改变技术配置' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END $$;
COMMENT ON FUNCTION "datahub-center".modeling_guard_layer_change() IS '保护仍被概念模型或统一设计引用的数仓分层；部署绑定从设计读取归属';

-- 绑定编号及设计归属是历史物理候选的身份；更换设计必须新建绑定，不能重挂旧部署记录。
CREATE OR REPLACE FUNCTION dh_modeling_unified_binding_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
BEGIN
    IF ROW(NEW.id,NEW.tenant_id,NEW.logic_model_id) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.logic_model_id) THEN
        RAISE EXCEPTION '部署绑定身份和唯一设计归属不可修改；更换设计须新建绑定';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unified_binding_guard() IS '固定部署绑定的租户和设计身份，防止改变父记录后使历史候选指向另一设计';
DROP TRIGGER IF EXISTS modeling_unified_binding_guard ON dh_modeling_physical_model;
CREATE TRIGGER modeling_unified_binding_guard BEFORE UPDATE ON dh_modeling_physical_model
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unified_binding_guard();

CREATE OR REPLACE FUNCTION dh_modeling_published_design_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
BEGIN
    IF OLD.status='PUBLISHED' THEN
        IF TG_OP='DELETE' THEN RAISE EXCEPTION '已发布统一设计版本不可物理删除'; END IF;
        IF (to_jsonb(NEW)-ARRAY['deleted','updater','update_time']) IS DISTINCT FROM
           (to_jsonb(OLD)-ARRAY['deleted','updater','update_time']) THEN
            RAISE EXCEPTION '已发布统一设计内容不可修改，缺失的历史字段标识只允许在新草稿补齐';
        END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_published_design_guard() IS '冻结已发布设计及关系快照，不允许字段标识回填工具改写历史';
DROP TRIGGER IF EXISTS modeling_published_design_guard ON dh_modeling_logic_model_version;
CREATE TRIGGER modeling_published_design_guard BEFORE UPDATE OR DELETE ON dh_modeling_logic_model_version
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_published_design_guard();

CREATE OR REPLACE FUNCTION dh_modeling_unified_version_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
DECLARE binding_design bigint; version_design bigint; design_status text;
BEGIN
    IF TG_OP<>'INSERT' THEN
        IF OLD.definition_origin IN ('LEGACY_DRAFT','LEGACY_PUBLISHED') THEN
            RAISE EXCEPTION '历史独立物理版本只读归档；变更新建设计版本和部署候选，不修改旧证据';
        END IF;
        IF TG_OP='DELETE' THEN RAISE EXCEPTION '部署候选历史不可物理删除'; END IF;
        IF OLD.status='PUBLISHED' AND
            (to_jsonb(NEW)-ARRAY['deleted','updater','update_time']) IS DISTINCT FROM
            (to_jsonb(OLD)-ARRAY['deleted','updater','update_time']) THEN
            RAISE EXCEPTION '已发布的物理候选证据不可修改';
        END IF;
    END IF;
    IF NEW.definition_origin<>'UNIFIED' OR NEW.design_version_id IS NULL THEN
        RAISE EXCEPTION '新物理候选必须来自精确统一设计版本，不得创建独立物理字段定义';
    END IF;
    SELECT logic_model_id INTO binding_design FROM dh_modeling_physical_model
        WHERE tenant_id=NEW.tenant_id AND id=NEW.model_id AND deleted=0 FOR SHARE;
    SELECT model_id,status INTO version_design,design_status FROM dh_modeling_logic_model_version
        WHERE tenant_id=NEW.tenant_id AND id=NEW.design_version_id AND deleted=0 FOR SHARE;
    IF binding_design IS NULL OR binding_design IS DISTINCT FROM version_design OR design_status IS DISTINCT FROM 'PUBLISHED' THEN
        RAISE EXCEPTION '部署候选必须绑定同一模型同租户的已发布设计版本';
    END IF;
    IF NEW.status='PUBLISHED' AND (jsonb_typeof(NEW.model_snapshot) IS DISTINCT FROM 'object'
        OR jsonb_typeof(NEW.fields) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '发布部署候选必须冻结完整物理快照与字段数组';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unified_version_guard() IS '统一模型部署候选来源与历史只读守卫，不把旧草稿伪装成发布版本';
DROP TRIGGER IF EXISTS modeling_unified_version_guard ON dh_modeling_physical_model_version;
CREATE TRIGGER modeling_unified_version_guard BEFORE INSERT OR UPDATE OR DELETE ON dh_modeling_physical_model_version
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unified_version_guard();

-- 业务关系保留同一份数据；历史缺 UID 时明确留空，新编辑由服务在事务中验证复合键并推进设计修订。
CREATE OR REPLACE FUNCTION dh_modeling_unified_relation_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
DECLARE pair jsonb;
BEGIN
    IF NEW.deleted<>0 THEN RETURN NEW; END IF;
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_logic_model WHERE id=NEW.source_model_id AND tenant_id=NEW.tenant_id AND deleted=0)
        OR NOT EXISTS (SELECT 1 FROM dh_modeling_logic_model WHERE id=NEW.target_model_id AND tenant_id=NEW.tenant_id AND deleted=0) THEN
        RAISE EXCEPTION 'ER 关系两端必须是同租户有效模型';
    END IF;
    IF NEW.field_pairs IS NULL THEN
        RAISE EXCEPTION '新建或编辑关系须提供稳定字段标识，不得仅按字段名称保存';
    END IF;
    FOR pair IN SELECT value FROM jsonb_array_elements(NEW.field_pairs) LOOP
        IF jsonb_typeof(pair)<>'object' OR NULLIF(btrim(pair->>'sourceFieldUid'),'') IS NULL
            OR NULLIF(btrim(pair->>'targetFieldUid'),'') IS NULL THEN
            RAISE EXCEPTION '复合关联键必须提供非空的两端字段标识';
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.field_pairs) p GROUP BY p->>'sourceFieldUid' HAVING count(*)>1)
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.field_pairs) p GROUP BY p->>'targetFieldUid' HAVING count(*)>1) THEN
        RAISE EXCEPTION '复合关联键不能重复使用同一端字段';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unified_relation_guard() IS '新 ER 关系写入校验租户和复合字段标识，实际字段存在性及双端编辑权限由应用事务校验';
DROP TRIGGER IF EXISTS modeling_unified_relation_guard ON dh_modeling_logic_relation;
CREATE TRIGGER modeling_unified_relation_guard BEFORE INSERT OR UPDATE ON dh_modeling_logic_relation
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unified_relation_guard();

COMMIT;

-- Migration: 0125
-- Purpose: 新版统一模型验收后复用原逻辑模型菜单切换入口，保留原路径、编号、权限和角色授权，旧入口仅隐藏。
-- Depends on: 0124_modeling_unified-target-cleanup.sql；统一模型前后端已部署并验收，旧写入入口已停用。
-- Target: 已有 PostgreSQL 平台库的 datahub-center 模式；仅执行 SQL 不会提供新版页面或接口。
-- Repeatable: 是；首轮记录五个菜单完整前后镜像；重放核对镜像与权限覆盖后不重复修改。
-- Rollback: 不删除菜单或授权；菜单前后镜像仅作诊断证据，回切须同时恢复兼容数据库结构及应用，禁止直接回退旧应用。
-- 风险：事务内短时锁定菜单及角色菜单表；不会自动补授查询权，旧页面独立授权未覆盖统一入口时整笔拒绝。
-- 执行前在同一会话声明 SET datahub.modeling_unified_cutover='UNIFIED_MODEL_V1'；该声明不能代替部署验收。
-- 原物理、概念或检测页面独立授权角色须先由管理员通过正式角色管理审查；只赋检测权限的角色不可自动升级查询范围。
BEGIN;
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

DO $precondition$
BEGIN
    IF current_setting('datahub.modeling_unified_cutover', true) IS DISTINCT FROM 'UNIFIED_MODEL_V1' THEN
        RAISE EXCEPTION '未声明统一模型新版已部署验收，拒绝切换菜单';
    END IF;
    IF to_regclass('dh_modeling_unification_state') IS NULL
        OR to_regclass('system_menu') IS NULL OR to_regclass('system_role_menu') IS NULL THEN
        RAISE EXCEPTION '缺少统一模型阶段账本或系统菜单授权表，须先完成前置迁移';
    END IF;
END $precondition$;

LOCK TABLE dh_modeling_unification_state, system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;

DO $phase$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state
        WHERE migration_key='UNIFIED_MODEL_V1' AND phase='CLEANED') THEN
        RAISE EXCEPTION '统一模型清理阶段尚未完成，须先完整执行 0124';
    END IF;
END $phase$;

CREATE TABLE IF NOT EXISTS dh_modeling_unified_menu_backup (
    migration_key varchar(40) NOT NULL,
    menu_id bigint NOT NULL,
    original_component varchar(255) NOT NULL,
    before_image jsonb NOT NULL,
    after_image jsonb NOT NULL,
    operator_name varchar(128) NOT NULL,
    applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (migration_key, menu_id),
    UNIQUE (migration_key, original_component)
);
COMMENT ON TABLE dh_modeling_unified_menu_backup IS '统一模型菜单切换证据账本；保留完整前后镜像，不作为权限配置来源';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.migration_key IS '菜单切换契约编号';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.menu_id IS '被修改的原菜单编号，保持不变';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.original_component IS '切换前组件路径，用于严格定位原入口';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.before_image IS '首次切换前完整菜单行镜像，包含原权限与展示状态';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.after_image IS '首次切换后完整菜单行镜像，重放时用于发现后续人工变更';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.operator_name IS '首次执行菜单切换的数据库身份';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.applied_at IS '首次完成菜单切换的时间';

LOCK TABLE dh_modeling_unified_menu_backup IN SHARE ROW EXCLUSIVE MODE;

DO $menus$
DECLARE
    unified_menu bigint;
    hidden_menus bigint[];
    menu_ids bigint[];
    menu_id bigint;
    matches integer;
    backup_count integer;
    missing_grants text;
    item record;
    original jsonb;
    updated jsonb;
    is_replay boolean;
BEGIN
    SELECT count(*) INTO backup_count FROM dh_modeling_unified_menu_backup
        WHERE migration_key='UNIFIED_MODEL_V1';
    IF backup_count NOT IN (0, 5) THEN
        RAISE EXCEPTION '统一菜单备份账本不完整，须核查，禁止覆盖原始证据';
    END IF;
    is_replay := backup_count=5;

    -- 新旧组件合计只能命中一个有效入口；首次执行禁止认领没有证据账本的既有统一页面。
    SELECT count(*), min(id) INTO matches, unified_menu FROM system_menu
        WHERE deleted=0 AND type=2 AND trim(both '/' from component) IN
            ('modeling/logicmodel/index', 'modeling/tablemodel/index');
    IF matches<>1 THEN
        RAISE EXCEPTION '逻辑模型或统一模型菜单不是唯一有效入口，须先消除组件冲突';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id=unified_menu AND status=0 AND visible
        AND trim(both '/' from component)=CASE WHEN is_replay
            THEN 'modeling/tablemodel/index' ELSE 'modeling/logicmodel/index' END) THEN
        RAISE EXCEPTION '统一入口的组件、启用或显示状态不符合首次切换或重放前置条件';
    END IF;
    menu_ids := ARRAY[unified_menu];
    hidden_menus := ARRAY[]::bigint[];

    FOR item IN SELECT * FROM (VALUES
        ('modeling/conceptmodel/index', true),
        ('modeling/physicalmodel/index', true),
        ('modeling/modelcheck/index', true),
        ('modeling/modelpublish/index', false)
    ) AS old_menus(component, should_hide) LOOP
        SELECT count(*), min(id) INTO matches, menu_id FROM system_menu
            WHERE deleted=0 AND type=2 AND trim(both '/' from component)=item.component;
        IF matches<>1 THEN
            RAISE EXCEPTION '缺少唯一有效旧菜单组件：%', item.component;
        END IF;
        menu_ids := array_append(menu_ids, menu_id);
        IF item.should_hide THEN hidden_menus := array_append(hidden_menus, menu_id); END IF;
    END LOOP;

    -- 权限字符串相同不等于菜单可达；按租户与角色核验实际页面授权，不插入或修改任何角色授权。
    -- 包括停用角色和暂存的角色菜单关联，避免日后恢复角色时旧授权被静默遗失。
    SELECT string_agg(format('租户=%s/角色=%s', tenant_id, role_id), '；') INTO missing_grants
    FROM (
        SELECT DISTINCT old_grant.tenant_id, old_grant.role_id FROM system_role_menu old_grant
        WHERE old_grant.deleted=0 AND old_grant.menu_id=ANY(hidden_menus)
            AND NOT EXISTS (SELECT 1 FROM system_role_menu unified_grant
                WHERE unified_grant.deleted=0 AND unified_grant.tenant_id=old_grant.tenant_id
                    AND unified_grant.role_id=old_grant.role_id AND unified_grant.menu_id=unified_menu)
        ORDER BY old_grant.tenant_id, old_grant.role_id LIMIT 20
    ) AS missing;
    IF missing_grants IS NOT NULL THEN
        RAISE EXCEPTION '旧页面角色缺少统一入口授权，未自动增加权限；管理员须通过正式角色管理审查后再执行。前二十项：%', missing_grants;
    END IF;

    IF is_replay THEN
        IF EXISTS (SELECT 1 FROM dh_modeling_unified_menu_backup b
            LEFT JOIN system_menu m ON m.id=b.menu_id
            WHERE b.migration_key='UNIFIED_MODEL_V1' AND
                (NOT b.menu_id=ANY(menu_ids) OR m.id IS NULL OR to_jsonb(m) IS DISTINCT FROM b.after_image)) THEN
            RAISE EXCEPTION '切换后的菜单被修改或账本引用不一致；禁止重放覆盖，请先审查差异';
        END IF;
        RETURN;
    END IF;

    FOREACH menu_id IN ARRAY menu_ids LOOP
        SELECT to_jsonb(m) INTO original FROM system_menu m WHERE m.id=menu_id;
        IF menu_id=unified_menu THEN
            UPDATE system_menu SET name='模型管理', component='modeling/tablemodel/index',
                component_name='ModelingTableModel', updater='migration:0125', update_time=CURRENT_TIMESTAMP
                WHERE id=menu_id;
        ELSIF menu_id=ANY(hidden_menus) THEN
            UPDATE system_menu SET visible=false, updater='migration:0125', update_time=CURRENT_TIMESTAMP
                WHERE id=menu_id;
        ELSE
            UPDATE system_menu SET name='发布记录', updater='migration:0125', update_time=CURRENT_TIMESTAMP
                WHERE id=menu_id;
        END IF;
        SELECT to_jsonb(m) INTO updated FROM system_menu m WHERE m.id=menu_id;
        INSERT INTO dh_modeling_unified_menu_backup
            (migration_key,menu_id,original_component,before_image,after_image,operator_name)
        VALUES ('UNIFIED_MODEL_V1',menu_id,trim(both '/' from original->>'component'),original,updated,current_user);
    END LOOP;
END $menus$;
COMMIT;

RESET datahub.modeling_unified_cutover;

-- Migration: 0126 建模工作台退役与统一设计并发约束
-- Purpose: 归档后删除建模协作、审批、检查归档、收件箱、变更分发及引用回执；保留即时检查、实际引用、统一迁移证据和部署历史。
-- Depends on: 已按顺序完成 0123、0124、0125，停止所有旧建模实例与建模审批/投递任务；旧 BPM 实例及引用事务均已对账结束。
-- Target: 已有 PostgreSQL 平台数据库；新库通过包含本迁移的全量基线安装。
-- Repeatable: 是；已完成时验证退役表没有重新出现，保留首次归档证据，不重复改写角色或套餐。
-- Rollback: 删除七个业务表和三个按钮权限，不可仅回滚应用；恢复维护窗口前完整数据库备份与匹配旧应用。行级归档用于核对，不能代替完整备份。
-- 风险：访问范围按明确的新产品规则改为 RBAC 加租户隔离；原对象 ACL 只作归档，不再参与授权。索引创建和归档持写锁，须维护窗口执行。
-- 不取消、不通过、不消费 BPM 审批；仍活动的审批或建模引用 mutation 会整笔阻断。旧通知投递以退役归档终止，不伪造已送达。
BEGIN;
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

LOCK TABLE dh_modeling_unification_state, dh_modeling_logic_model, dh_modeling_physical_model,
    dh_dataforge_reference_mutation, system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
DECLARE source_table text; active_count bigint; duplicate_targets text;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='UNIFIED_MODEL_V1' AND phase='CLEANED')
       OR (SELECT count(*) FROM dh_modeling_unified_menu_backup WHERE migration_key='UNIFIED_MODEL_V1')<>5 THEN
        RAISE EXCEPTION '必须先完成统一设计 0124 及菜单切换 0125';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN
        IF to_regclass('dh_modeling_workspace_removal_archive') IS NULL THEN
            RAISE EXCEPTION '退役账本已完成但原始归档丢失，禁止重建空证据';
        END IF;
        IF EXISTS (SELECT 1 FROM system_menu WHERE permission IN
            ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox')) THEN
            RAISE EXCEPTION '已退役权限重新出现，须调查来源，禁止覆盖首次归档';
        END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM system_menu child JOIN system_menu removed ON child.parent_id=removed.id
        WHERE removed.permission IN ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox')) THEN
        RAISE EXCEPTION '待删除功能按钮下存在子菜单，须先人工审查菜单结构';
    END IF;
    FOREACH source_table IN ARRAY ARRAY['dh_modeling_collaboration','dh_modeling_collaborator','dh_modeling_approval',
        'dh_modeling_design_report','dh_modeling_inbox','dh_modeling_object_change','dh_modeling_reference_receipt'] LOOP
        IF to_regclass(source_table) IS NOT NULL THEN
            IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN
                RAISE EXCEPTION '退役后旧表重新出现，拒绝覆盖原始证据：%', source_table;
            END IF;
            EXECUTE format('LOCK TABLE %I IN SHARE ROW EXCLUSIVE MODE', source_table);
        ELSIF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN
            RAISE EXCEPTION '首次退役缺少原表，无法证明完整归档：%', source_table;
        END IF;
    END LOOP;
    IF to_regclass('dh_modeling_approval') IS NOT NULL THEN
        EXECUTE 'SELECT count(*) FROM dh_modeling_approval WHERE deleted=0 AND status NOT IN (''REJECTED'',''CANCELLED'',''CONSUMED'')' INTO active_count;
        IF active_count>0 THEN RAISE EXCEPTION '仍有 % 个未终结建模审批，须先由旧应用与 BPM 正式对账，禁止伪造终态',active_count; END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM dh_dataforge_reference_mutation WHERE owner='modeling' AND state='ACTIVE') THEN
        RAISE EXCEPTION '仍有活动建模引用变更，须旧应用完成或通过数据源正式人工对账后再退役';
    END IF;
    SELECT string_agg(format('租户=%s/数据源=%s/表=%s/数量=%s',tenant_id,database_id,table_name,n),'；') INTO duplicate_targets
    FROM (SELECT tenant_id,database_id,table_name,count(*) n FROM dh_modeling_physical_model
        WHERE deleted=0 GROUP BY tenant_id,database_id,table_name HAVING count(*)>1 LIMIT 20) d;
    IF duplicate_targets IS NOT NULL THEN
        RAISE EXCEPTION '部署目标存在重复绑定，须人工审查，禁止按名称合并：%', duplicate_targets;
    END IF;
END $preflight$;

CREATE TABLE IF NOT EXISTS dh_modeling_workspace_removal_archive (
    source_table varchar(80) NOT NULL,
    row_key varchar(160) NOT NULL,
    row_image jsonb NOT NULL,
    operator_name varchar(128) NOT NULL,
    archived_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (source_table,row_key)
);
COMMENT ON TABLE dh_modeling_workspace_removal_archive IS '0126退役前原始行证据，仅供数据库迁移核对，不提供业务查询或恢复授权入口';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.source_table IS '被退役或清理的原表名称';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.row_key IS '租户加原记录编号或引用操作编号，保持原始身份';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.row_image IS '首次退役前完整原行，含旧ACL、审批状态或菜单授权';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.operator_name IS '归档时数据库执行身份';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.archived_at IS '首次归档时间';
REVOKE ALL ON dh_modeling_workspace_removal_archive FROM PUBLIC;

DO $archive$
DECLARE source_name text; expected_count bigint; archived_count bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_workspace_removal_archive) THEN
        RAISE EXCEPTION '首次退役时归档表已有数据，拒绝覆盖未知证据';
    END IF;
    FOREACH source_name IN ARRAY ARRAY['dh_modeling_collaboration','dh_modeling_collaborator','dh_modeling_approval',
        'dh_modeling_design_report','dh_modeling_inbox','dh_modeling_object_change','dh_modeling_reference_receipt'] LOOP
        EXECUTE format('INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
            SELECT %L,COALESCE(to_jsonb(s)->>''tenant_id'',''-'')||'':''||COALESCE(to_jsonb(s)->>''id'',to_jsonb(s)->>''operation_id''),to_jsonb(s),current_user FROM %I s',source_name,source_name);
        EXECUTE format('SELECT count(*) FROM %I',source_name) INTO expected_count;
        SELECT count(*) INTO archived_count FROM dh_modeling_workspace_removal_archive a WHERE a.source_table=source_name;
        IF expected_count<>archived_count THEN RAISE EXCEPTION '原表归档数量不一致：%',source_name; END IF;
    END LOOP;
    INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
        SELECT 'system_menu',id::text,to_jsonb(m),current_user FROM system_menu m
        WHERE permission IN ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox');
    INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
        SELECT 'system_role_menu',r.tenant_id||':'||r.id,to_jsonb(r),current_user FROM system_role_menu r
        WHERE r.menu_id IN (SELECT id FROM system_menu WHERE permission IN
            ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'));
    INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
        SELECT 'system_tenant_package',p.id::text,to_jsonb(p),current_user FROM system_tenant_package p
        WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(p.menu_ids::jsonb) e(value)
            JOIN system_menu m ON m.id::text=e.value WHERE m.permission IN
                ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'));
    UPDATE system_tenant_package p SET menu_ids=(SELECT COALESCE(jsonb_agg(e.value ORDER BY e.ordinality),'[]'::jsonb)::text
        FROM jsonb_array_elements(p.menu_ids::jsonb) WITH ORDINALITY e(value,ordinality)
        WHERE NOT EXISTS (SELECT 1 FROM system_menu m WHERE m.id::text=(e.value#>>'{}') AND m.permission IN
            ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'))),
        updater='migration:0126',update_time=CURRENT_TIMESTAMP
        WHERE p.id::text IN (SELECT row_key FROM dh_modeling_workspace_removal_archive WHERE source_table='system_tenant_package');
    DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM system_menu WHERE permission IN
        ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'));
    DELETE FROM system_menu WHERE permission IN
        ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox');
END $archive$;

