-- 第二阶段：菜单切换和首次镜像核验。
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

DO $precondition$
BEGIN
    IF current_setting('datahub.modeling_unified_cutover', true) IS DISTINCT FROM 'UNIFIED_MODEL_V1' THEN
        RAISE EXCEPTION '未声明统一模型新版已部署验收，拒绝切换菜单';
    END IF;
    IF to_regclass('dh_modeling_unification_state') IS NULL
        OR to_regclass('system_menu') IS NULL OR to_regclass('system_role_menu') IS NULL THEN
        RAISE EXCEPTION '缺少统一模型阶段账本或系统菜单授权表，须先完成前置迁移';
    END IF;
END $precondition$;

LOCK TABLE dh_modeling_unification_state, system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;

DO $phase$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state
        WHERE migration_key='UNIFIED_MODEL_V1' AND phase='CLEANED') THEN
        RAISE EXCEPTION '统一模型清理阶段尚未完成，须先完整执行 0124';
    END IF;
END $phase$;

CREATE TABLE IF NOT EXISTS dh_modeling_unified_menu_backup (
    migration_key varchar(40) NOT NULL,
    menu_id bigint NOT NULL,
    original_component varchar(255) NOT NULL,
    before_image jsonb NOT NULL,
    after_image jsonb NOT NULL,
    operator_name varchar(128) NOT NULL,
    applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (migration_key, menu_id),
    UNIQUE (migration_key, original_component)
);
COMMENT ON TABLE dh_modeling_unified_menu_backup IS '统一模型菜单切换证据账本；保留完整前后镜像，不作为权限配置来源';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.migration_key IS '菜单切换契约编号';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.menu_id IS '被修改的原菜单编号，保持不变';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.original_component IS '切换前组件路径，用于严格定位原入口';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.before_image IS '首次切换前完整菜单行镜像，包含原权限与展示状态';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.after_image IS '首次切换后完整菜单行镜像，重放时用于发现后续人工变更';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.operator_name IS '首次执行菜单切换的数据库身份';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.applied_at IS '首次完成菜单切换的时间';

LOCK TABLE dh_modeling_unified_menu_backup IN SHARE ROW EXCLUSIVE MODE;

DO $menus$
DECLARE
    unified_menu bigint;
    hidden_menus bigint[];
    menu_ids bigint[];
    menu_id bigint;
    matches integer;
    backup_count integer;
    missing_grants text;
    item record;
    original jsonb;
    updated jsonb;
    is_replay boolean;
BEGIN
    SELECT count(*) INTO backup_count FROM dh_modeling_unified_menu_backup
        WHERE migration_key='UNIFIED_MODEL_V1';
    IF backup_count NOT IN (0, 5) THEN
        RAISE EXCEPTION '统一菜单备份账本不完整，须核查，禁止覆盖原始证据';
    END IF;
    is_replay := backup_count=5;

    -- 新旧组件合计只能命中一个有效入口；首次执行禁止认领没有证据账本的既有统一页面。
    SELECT count(*), min(id) INTO matches, unified_menu FROM system_menu
        WHERE deleted=0 AND type=2 AND trim(both '/' from component) IN
            ('modeling/logicmodel/index', 'modeling/tablemodel/index');
    IF matches<>1 THEN
        RAISE EXCEPTION '逻辑模型或统一模型菜单不是唯一有效入口，须先消除组件冲突';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id=unified_menu AND status=0 AND visible
        AND trim(both '/' from component)=CASE WHEN is_replay
            THEN 'modeling/tablemodel/index' ELSE 'modeling/logicmodel/index' END) THEN
        RAISE EXCEPTION '统一入口的组件、启用或显示状态不符合首次切换或重放前置条件';
    END IF;
    menu_ids := ARRAY[unified_menu];
    hidden_menus := ARRAY[]::bigint[];

    FOR item IN SELECT * FROM (VALUES
        ('modeling/conceptmodel/index', true),
        ('modeling/physicalmodel/index', true),
        ('modeling/modelcheck/index', true),
        ('modeling/modelpublish/index', false)
    ) AS old_menus(component, should_hide) LOOP
        SELECT count(*), min(id) INTO matches, menu_id FROM system_menu
            WHERE deleted=0 AND type=2 AND trim(both '/' from component)=item.component;
        IF matches<>1 THEN
            RAISE EXCEPTION '缺少唯一有效旧菜单组件：%', item.component;
        END IF;
        menu_ids := array_append(menu_ids, menu_id);
        IF item.should_hide THEN hidden_menus := array_append(hidden_menus, menu_id); END IF;
    END LOOP;

    -- 权限字符串相同不等于菜单可达；按租户与角色核验实际页面授权，不插入或修改任何角色授权。
    -- 包括停用角色和暂存的角色菜单关联，避免日后恢复角色时旧授权被静默遗失。
    SELECT string_agg(format('租户=%s/角色=%s', tenant_id, role_id), '；') INTO missing_grants
    FROM (
        SELECT DISTINCT old_grant.tenant_id, old_grant.role_id FROM system_role_menu old_grant
        WHERE old_grant.deleted=0 AND old_grant.menu_id=ANY(hidden_menus)
            AND NOT EXISTS (SELECT 1 FROM system_role_menu unified_grant
                WHERE unified_grant.deleted=0 AND unified_grant.tenant_id=old_grant.tenant_id
                    AND unified_grant.role_id=old_grant.role_id AND unified_grant.menu_id=unified_menu)
        ORDER BY old_grant.tenant_id, old_grant.role_id LIMIT 20
    ) AS missing;
    IF missing_grants IS NOT NULL THEN
        RAISE EXCEPTION '旧页面角色缺少统一入口授权，未自动增加权限；管理员须通过正式角色管理审查后再执行。前二十项：%', missing_grants;
    END IF;

    IF is_replay THEN
        IF EXISTS (SELECT 1 FROM dh_modeling_unified_menu_backup b
            LEFT JOIN system_menu m ON m.id=b.menu_id
            WHERE b.migration_key='UNIFIED_MODEL_V1' AND
                (NOT b.menu_id=ANY(menu_ids) OR m.id IS NULL OR to_jsonb(m) IS DISTINCT FROM b.after_image)) THEN
            RAISE EXCEPTION '切换后的菜单被修改或账本引用不一致；禁止重放覆盖，请先审查差异';
        END IF;
        RETURN;
    END IF;

    FOREACH menu_id IN ARRAY menu_ids LOOP
        SELECT to_jsonb(m) INTO original FROM system_menu m WHERE m.id=menu_id;
        IF menu_id=unified_menu THEN
            UPDATE system_menu SET name='模型管理', component='modeling/tablemodel/index',
                component_name='ModelingTableModel', updater='migration:0125', update_time=CURRENT_TIMESTAMP
                WHERE id=menu_id;
        ELSIF menu_id=ANY(hidden_menus) THEN
            UPDATE system_menu SET visible=false, updater='migration:0125', update_time=CURRENT_TIMESTAMP
                WHERE id=menu_id;
        ELSE
            UPDATE system_menu SET name='发布记录', updater='migration:0125', update_time=CURRENT_TIMESTAMP
                WHERE id=menu_id;
        END IF;
        SELECT to_jsonb(m) INTO updated FROM system_menu m WHERE m.id=menu_id;
        INSERT INTO dh_modeling_unified_menu_backup
            (migration_key,menu_id,original_component,before_image,after_image,operator_name)
        VALUES ('UNIFIED_MODEL_V1',menu_id,trim(both '/' from original->>'component'),original,updated,current_user);
    END LOOP;
END $menus$;

-- 第三阶段：工作台退役，已完成时保留首次归档并验证重放条件。
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

LOCK TABLE dh_modeling_unification_state, dh_modeling_logic_model, dh_modeling_physical_model,
    dh_dataforge_reference_mutation, system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
DECLARE source_table text; active_count bigint; duplicate_targets text;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='UNIFIED_MODEL_V1' AND phase='CLEANED')
       OR (SELECT count(*) FROM dh_modeling_unified_menu_backup WHERE migration_key='UNIFIED_MODEL_V1')<>5 THEN
        RAISE EXCEPTION '必须先完成统一设计 0124 及菜单切换 0125';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN
        IF to_regclass('dh_modeling_workspace_removal_archive') IS NULL THEN
            RAISE EXCEPTION '退役账本已完成但原始归档丢失，禁止重建空证据';
        END IF;
        IF EXISTS (SELECT 1 FROM system_menu WHERE permission IN
            ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox')) THEN
            RAISE EXCEPTION '已退役权限重新出现，须调查来源，禁止覆盖首次归档';
        END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM system_menu child JOIN system_menu removed ON child.parent_id=removed.id
        WHERE removed.permission IN ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox')) THEN
        RAISE EXCEPTION '待删除功能按钮下存在子菜单，须先人工审查菜单结构';
    END IF;
    FOREACH source_table IN ARRAY ARRAY['dh_modeling_collaboration','dh_modeling_collaborator','dh_modeling_approval',
        'dh_modeling_design_report','dh_modeling_inbox','dh_modeling_object_change','dh_modeling_reference_receipt'] LOOP
        IF to_regclass(source_table) IS NOT NULL THEN
            IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN
                RAISE EXCEPTION '退役后旧表重新出现，拒绝覆盖原始证据：%', source_table;
            END IF;
            EXECUTE format('LOCK TABLE %I IN SHARE ROW EXCLUSIVE MODE', source_table);
        ELSIF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN
            RAISE EXCEPTION '首次退役缺少原表，无法证明完整归档：%', source_table;
        END IF;
    END LOOP;
    IF to_regclass('dh_modeling_approval') IS NOT NULL THEN
        EXECUTE 'SELECT count(*) FROM dh_modeling_approval WHERE deleted=0 AND status NOT IN (''REJECTED'',''CANCELLED'',''CONSUMED'')' INTO active_count;
        IF active_count>0 THEN RAISE EXCEPTION '仍有 % 个未终结建模审批，须先由旧应用与 BPM 正式对账，禁止伪造终态',active_count; END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM dh_dataforge_reference_mutation WHERE owner='modeling' AND state='ACTIVE') THEN
        RAISE EXCEPTION '仍有活动建模引用变更，须旧应用完成或通过数据源正式人工对账后再退役';
    END IF;
    SELECT string_agg(format('租户=%s/数据源=%s/表=%s/数量=%s',tenant_id,database_id,table_name,n),'；') INTO duplicate_targets
    FROM (SELECT tenant_id,database_id,table_name,count(*) n FROM dh_modeling_physical_model
        WHERE deleted=0 GROUP BY tenant_id,database_id,table_name HAVING count(*)>1 LIMIT 20) d;
    IF duplicate_targets IS NOT NULL THEN
        RAISE EXCEPTION '部署目标存在重复绑定，须人工审查，禁止按名称合并：%', duplicate_targets;
    END IF;
END $preflight$;

CREATE TABLE IF NOT EXISTS dh_modeling_workspace_removal_archive (
    source_table varchar(80) NOT NULL,
    row_key varchar(160) NOT NULL,
    row_image jsonb NOT NULL,
    operator_name varchar(128) NOT NULL,
    archived_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (source_table,row_key)
);
COMMENT ON TABLE dh_modeling_workspace_removal_archive IS '0126退役前原始行证据，仅供数据库迁移核对，不提供业务查询或恢复授权入口';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.source_table IS '被退役或清理的原表名称';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.row_key IS '租户加原记录编号或引用操作编号，保持原始身份';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.row_image IS '首次退役前完整原行，含旧ACL、审批状态或菜单授权';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.operator_name IS '归档时数据库执行身份';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.archived_at IS '首次归档时间';
REVOKE ALL ON dh_modeling_workspace_removal_archive FROM PUBLIC;

DO $archive$
DECLARE source_name text; expected_count bigint; archived_count bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN RETURN; END IF;
    IF EXISTS (SELECT 1 FROM dh_modeling_workspace_removal_archive) THEN
        RAISE EXCEPTION '首次退役时归档表已有数据，拒绝覆盖未知证据';
    END IF;
    FOREACH source_name IN ARRAY ARRAY['dh_modeling_collaboration','dh_modeling_collaborator','dh_modeling_approval',
        'dh_modeling_design_report','dh_modeling_inbox','dh_modeling_object_change','dh_modeling_reference_receipt'] LOOP
        EXECUTE format('INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
            SELECT %L,COALESCE(to_jsonb(s)->>''tenant_id'',''-'')||'':''||COALESCE(to_jsonb(s)->>''id'',to_jsonb(s)->>''operation_id''),to_jsonb(s),current_user FROM %I s',source_name,source_name);
        EXECUTE format('SELECT count(*) FROM %I',source_name) INTO expected_count;
        SELECT count(*) INTO archived_count FROM dh_modeling_workspace_removal_archive a WHERE a.source_table=source_name;
        IF expected_count<>archived_count THEN RAISE EXCEPTION '原表归档数量不一致：%',source_name; END IF;
    END LOOP;
    INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
        SELECT 'system_menu',id::text,to_jsonb(m),current_user FROM system_menu m
        WHERE permission IN ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox');
    INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
        SELECT 'system_role_menu',r.tenant_id||':'||r.id,to_jsonb(r),current_user FROM system_role_menu r
        WHERE r.menu_id IN (SELECT id FROM system_menu WHERE permission IN
            ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'));
    INSERT INTO dh_modeling_workspace_removal_archive(source_table,row_key,row_image,operator_name)
        SELECT 'system_tenant_package',p.id::text,to_jsonb(p),current_user FROM system_tenant_package p
        WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(p.menu_ids::jsonb) e(value)
            JOIN system_menu m ON m.id::text=e.value WHERE m.permission IN
                ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'));
    UPDATE system_tenant_package p SET menu_ids=(SELECT COALESCE(jsonb_agg(e.value ORDER BY e.ordinality),'[]'::jsonb)::text
        FROM jsonb_array_elements(p.menu_ids::jsonb) WITH ORDINALITY e(value,ordinality)
        WHERE NOT EXISTS (SELECT 1 FROM system_menu m WHERE m.id::text=(e.value#>>'{}') AND m.permission IN
            ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'))),
        updater='migration:0126',update_time=CURRENT_TIMESTAMP
        WHERE p.id::text IN (SELECT row_key FROM dh_modeling_workspace_removal_archive WHERE source_table='system_tenant_package');
    DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM system_menu WHERE permission IN
        ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox'));
    DELETE FROM system_menu WHERE permission IN
        ('modeling:workspace:approval','modeling:workspace:collaboration','modeling:workspace:inbox');
END $archive$;

DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_concept_model;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_concept_entity;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_concept_relation;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_logic_model;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_logic_model_version;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_physical_model;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_physical_model_version;
DROP FUNCTION IF EXISTS dh_modeling_confirm_unification(bigint,bigint,jsonb);
DROP FUNCTION IF EXISTS dh_modeling_unification_acl(bigint,text,bigint,text);
DROP TABLE IF EXISTS dh_modeling_inbox;
DROP TABLE IF EXISTS dh_modeling_object_change;
DROP TABLE IF EXISTS dh_modeling_design_report;
DROP TABLE IF EXISTS dh_modeling_approval;
DROP TABLE IF EXISTS dh_modeling_collaborator;
DROP TABLE IF EXISTS dh_modeling_collaboration;
DROP TABLE IF EXISTS dh_modeling_reference_receipt;
DROP FUNCTION IF EXISTS dh_modeling_approval_freeze_guard();
DROP FUNCTION IF EXISTS dh_modeling_approval_snapshot_immutable();
DROP FUNCTION IF EXISTS dh_modeling_design_report_immutable();
DROP SEQUENCE IF EXISTS dh_modeling_inbox_seq,dh_modeling_object_change_seq,dh_modeling_design_report_seq,
    dh_modeling_approval_seq,dh_modeling_collaborator_seq,dh_modeling_collaboration_seq;

ALTER TABLE dh_modeling_logic_model ADD COLUMN IF NOT EXISTS layout_revision bigint NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_modeling_logic_model.layout_revision IS 'ER布局并发修订号，与模型定义修订分离';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_active_deploy_target ON dh_modeling_physical_model
    (tenant_id,database_id,table_name) WHERE deleted=0;
COMMENT ON INDEX uq_modeling_active_deploy_target IS '同租户同数据源表只能存在一个活动部署绑定，防止并发占用';

CREATE OR REPLACE FUNCTION dh_modeling_workspace_archive_guard() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
BEGIN
    IF TG_OP='INSERT' AND NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='WORKSPACE_REMOVAL_V1') THEN RETURN NEW; END IF;
    RAISE EXCEPTION '工作台退役原始证据禁止新增、修改、删除或清空' USING ERRCODE='23514';
END $guard$;
COMMENT ON FUNCTION dh_modeling_workspace_archive_guard() IS '保护工作台退役前原行证据';
DROP TRIGGER IF EXISTS modeling_workspace_archive_guard ON dh_modeling_workspace_removal_archive;
CREATE TRIGGER modeling_workspace_archive_guard BEFORE INSERT OR UPDATE OR DELETE ON dh_modeling_workspace_removal_archive
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_workspace_archive_guard();
DROP TRIGGER IF EXISTS modeling_workspace_archive_truncate_guard ON dh_modeling_workspace_removal_archive;
CREATE TRIGGER modeling_workspace_archive_truncate_guard BEFORE TRUNCATE ON dh_modeling_workspace_removal_archive
    FOR EACH STATEMENT EXECUTE FUNCTION dh_modeling_workspace_archive_guard();
INSERT INTO dh_modeling_unification_state(migration_key,phase,operator_name)
    VALUES ('WORKSPACE_REMOVAL_V1','CLEANED',current_user) ON CONFLICT (migration_key) DO NOTHING;

-- 第四阶段：业务过程对象退役和最终模型归属守卫。
SET LOCAL search_path = "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';

LOCK TABLE dh_modeling_unification_state, dh_modeling_concept_model, dh_modeling_concept_entity,
    dh_modeling_logic_model, dh_modeling_data_domain, dh_modeling_subject_domain, dh_modeling_dw_layer,
    system_menu, system_role_menu, system_tenant_package, system_dict_type, system_dict_data
    IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
DECLARE source_table text;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state
                   WHERE migration_key='WORKSPACE_REMOVAL_V1' AND phase='CLEANED') THEN
        RAISE EXCEPTION '请先完成 0126 建模工作台退役';
    END IF;
    FOREACH source_table IN ARRAY ARRAY[
        'dh_modeling_business_process','dh_modeling_business_process_data_domain_rel',
        'dh_modeling_business_process_supporting_domain_rel','dh_modeling_business_process_domain_candidate',
        'dh_modeling_subject_domain_process_rel','dh_modeling_business_object',
        'dh_modeling_business_object_attribute','dh_modeling_business_object_process_rel',
        'dh_modeling_business_object_version','dh_modeling_business_object_external_ref'] LOOP
        IF to_regclass(source_table) IS NOT NULL THEN
            EXECUTE format('LOCK TABLE %I IN SHARE ROW EXCLUSIVE MODE',source_table);
        END IF;
    END LOOP;
END $preflight$;

-- 先替换引用守卫，避免后续回填仍触发即将退役的过程关联要求。
-- 继续校验数据域、主题域、分层均属于当前租户，并保护仍被模型引用的规划对象。
CREATE OR REPLACE FUNCTION "datahub-center".modeling_ownership_reference_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $guard$
DECLARE
    row_data jsonb; tenant bigint; object_id bigint; deleting boolean;
    tbl text; ref_field text; ref_table text; ref_id bigint; found_row boolean; model_table text;
BEGIN
    row_data := CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    tenant := (row_data->>'tenant_id')::bigint;
    object_id := (row_data->>'id')::bigint;
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-tenant:'||tenant::text,0));
    deleting := TG_OP='DELETE' OR COALESCE((row_data->>'deleted')::integer,0)<>0;
    tbl := TG_TABLE_NAME;
    IF tbl IN ('dh_modeling_concept_model','dh_modeling_logic_model') AND NOT deleting THEN
        FOR ref_field,ref_table IN SELECT * FROM (VALUES
            ('data_domain_id','dh_modeling_data_domain'),
            ('subject_domain_id','dh_modeling_subject_domain'),
            ('layer_id','dh_modeling_dw_layer')) AS refs(field_name,table_name) LOOP
            ref_id := (row_data->>ref_field)::bigint;
            IF ref_id IS NOT NULL THEN
                EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND tenant_id=$2 AND deleted=0)',ref_table)
                    INTO found_row USING ref_id,tenant;
                IF NOT found_row THEN
                    RAISE EXCEPTION '模型归属不存在或不属于当前租户：%',ref_field USING ERRCODE='23514';
                END IF;
            END IF;
        END LOOP;
    ELSIF tbl IN ('dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_dw_layer') AND deleting THEN
        ref_field := CASE tbl WHEN 'dh_modeling_data_domain' THEN 'data_domain_id'
            WHEN 'dh_modeling_subject_domain' THEN 'subject_domain_id' ELSE 'layer_id' END;
        FOREACH model_table IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model'] LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE %I=$1 AND tenant_id=$2 AND deleted=0)',model_table,ref_field)
                INTO found_row USING object_id,tenant;
            IF found_row THEN
                RAISE EXCEPTION '规划对象仍被模型引用，不能删除' USING ERRCODE='23514';
            END IF;
        END LOOP;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION "datahub-center".modeling_ownership_reference_guard() IS '保护概念模型和统一设计的数据域、主题域、分层引用与租户一致性';

-- 仅补齐原本由过程隐式提供的主模型数据域，不覆盖显式归属，不改变不可变版本及门禁摘要。
DO $backfill$
DECLARE model_table text;
BEGIN
    IF to_regclass('dh_modeling_business_process') IS NULL THEN RETURN; END IF;
    FOREACH model_table IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_logic_model'] LOOP
        IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema='datahub-center'
                   AND table_name=model_table AND column_name='business_process_id') THEN
            EXECUTE format('UPDATE %I m SET data_domain_id=p.data_domain_id
                FROM dh_modeling_business_process p JOIN dh_modeling_data_domain d
                  ON d.id=p.data_domain_id AND d.tenant_id=p.tenant_id AND d.deleted=0
                WHERE m.business_process_id=p.id AND m.tenant_id=p.tenant_id
                  AND m.deleted=0 AND p.deleted=0
                  AND m.data_domain_id IS NULL AND p.data_domain_id IS NOT NULL',model_table);
        END IF;
    END LOOP;
END $backfill$;

-- 新归属规则不再要求过程，重算主设计的筛选状态；历史版本中的原始状态保持不变。
-- 与应用的状态判断一致：仅状态一表示停用，空值不视为停用；实际数据库状态列仍保持原约束。
-- 持有写锁期间只更新派生状态，暂缓该表的引用触发器，允许历史失效引用被标为未归属；不修改或认可这些引用。
ALTER TABLE dh_modeling_logic_model DISABLE TRIGGER modeling_ownership_reference_guard;
WITH classifications AS (
    SELECT m.id,m.tenant_id,
        CASE WHEN m.table_type IN ('SOURCE','DETAIL','DIMENSION','SUMMARY','APPLICATION')
          AND EXISTS (SELECT 1 FROM dh_modeling_dw_layer l WHERE l.id=m.layer_id AND l.tenant_id=m.tenant_id
                      AND l.deleted=0 AND l.node_type='LAYER' AND l.status IS DISTINCT FROM 1)
          AND EXISTS (SELECT 1 FROM dh_modeling_data_domain d WHERE d.id=m.data_domain_id AND d.tenant_id=m.tenant_id
                      AND d.deleted=0 AND d.status IS DISTINCT FROM 1)
          AND (m.subject_domain_id IS NULL OR EXISTS (
              SELECT 1 FROM dh_modeling_subject_domain s WHERE s.id=m.subject_domain_id AND s.tenant_id=m.tenant_id
                AND s.deleted=0 AND s.status IS DISTINCT FROM 1))
        THEN 'CONFIRMED' ELSE 'UNCLASSIFIED' END AS next_status
    FROM dh_modeling_logic_model m WHERE m.deleted=0
)
UPDATE dh_modeling_logic_model m SET classification_status=c.next_status
FROM classifications c WHERE m.id=c.id AND m.tenant_id=c.tenant_id
    AND m.classification_status IS DISTINCT FROM c.next_status;
ALTER TABLE dh_modeling_logic_model ENABLE TRIGGER modeling_ownership_reference_guard;

-- 精确识别两项功能的菜单及其按钮；保留业务域所在的业务架构父目录。
CREATE TEMPORARY TABLE modeling_removed_planning_menu(id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO modeling_removed_planning_menu
SELECT id FROM system_menu
WHERE permission LIKE 'modeling:business-process:%' OR permission LIKE 'modeling:business-object:%'
   OR trim(both '/' from COALESCE(component,'')) IN ('modeling/businessprocess/index','modeling/businessobject/index')
   OR component_name IN ('ModelingBusinessProcess','ModelingBusinessObject');
WITH RECURSIVE buttons(id) AS (
    SELECT id FROM modeling_removed_planning_menu
    UNION
    SELECT child.id FROM system_menu child JOIN buttons parent ON child.parent_id=parent.id WHERE child.type=3
)
INSERT INTO modeling_removed_planning_menu SELECT id FROM buttons ON CONFLICT (id) DO NOTHING;
DO $menu_guard$
BEGIN
    IF EXISTS (SELECT 1 FROM system_menu child JOIN modeling_removed_planning_menu parent ON child.parent_id=parent.id
               WHERE child.type<>3 AND NOT EXISTS (SELECT 1 FROM modeling_removed_planning_menu own WHERE own.id=child.id)) THEN
        RAISE EXCEPTION '待删除菜单包含其他页面或目录，须先调整菜单归属，禁止连带删除';
    END IF;
END $menu_guard$;

UPDATE system_tenant_package p
SET menu_ids=(SELECT COALESCE(jsonb_agg(e.value ORDER BY e.ordinality),'[]'::jsonb)::text
              FROM jsonb_array_elements(p.menu_ids::jsonb) WITH ORDINALITY e(value,ordinality)
              WHERE NOT EXISTS (SELECT 1 FROM modeling_removed_planning_menu m WHERE m.id::text=(e.value#>>'{}'))),
    updater='migration:0127',update_time=CURRENT_TIMESTAMP
WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(p.menu_ids::jsonb) e(value)
              JOIN modeling_removed_planning_menu m ON m.id::text=e.value);
DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM modeling_removed_planning_menu);
DELETE FROM system_menu WHERE id IN (SELECT id FROM modeling_removed_planning_menu);

-- 当前基线没有专属字典；同时清理历史环境使用这两个明确命名空间的字典，保留通用状态和字段类型字典。
UPDATE system_menu SET name='分析主题',updater='migration:0131',update_time=CURRENT_TIMESTAMP WHERE trim(both '/' from component)='modeling/subjectdomain/index' AND name<>'分析主题';
DELETE FROM system_dict_data WHERE dict_type ~ '^modeling_business_(process|object)(_|$)';
DELETE FROM system_dict_type WHERE type ~ '^modeling_business_(process|object)(_|$)';

ALTER TABLE dh_modeling_concept_model DROP COLUMN IF EXISTS business_process_id;
ALTER TABLE dh_modeling_logic_model DROP COLUMN IF EXISTS business_process_id;
ALTER TABLE dh_modeling_concept_entity DROP COLUMN IF EXISTS business_object_id;
ALTER TABLE dh_modeling_concept_entity DROP COLUMN IF EXISTS business_object_version;

-- 不使用级联删除；未知数据库依赖会使整个事务回滚，防止误删其他业务能力。
DROP TABLE IF EXISTS dh_modeling_business_object_external_ref;
DROP TABLE IF EXISTS dh_modeling_business_object_process_rel;
DROP TABLE IF EXISTS dh_modeling_business_object_attribute;
DROP TABLE IF EXISTS dh_modeling_business_object_version;
DROP TABLE IF EXISTS dh_modeling_business_object;
DROP TABLE IF EXISTS dh_modeling_subject_domain_process_rel;
DROP TABLE IF EXISTS dh_modeling_business_process_supporting_domain_rel;
DROP TABLE IF EXISTS dh_modeling_business_process_domain_candidate;
DROP TABLE IF EXISTS dh_modeling_business_process_data_domain_rel;
DROP TABLE IF EXISTS dh_modeling_business_process;
DROP SEQUENCE IF EXISTS dh_modeling_business_object_external_ref_seq,dh_modeling_business_object_process_rel_seq,
    dh_modeling_business_object_attribute_seq,dh_modeling_business_object_version_seq,dh_modeling_business_object_seq,
    dh_modeling_subject_domain_process_rel_seq,dh_modeling_business_process_supporting_domain_rel_seq,
    dh_modeling_business_process_domain_candidate_seq,dh_modeling_business_process_data_domain_rel_seq,
    dh_modeling_business_process_seq;

INSERT INTO dh_modeling_unification_state(migration_key,phase,operator_name)
VALUES ('BUSINESS_PLANNING_REMOVAL_V1','CLEANED',current_user) ON CONFLICT (migration_key) DO NOTHING;
-- 最终核验：只有结构和三个业务阶段同时完成才提交。
DO $final_state$
DECLARE table_name text; missing_guard text;
BEGIN
    IF (SELECT count(*) FROM dh_modeling_unification_state WHERE phase='CLEANED'
        AND migration_key IN ('UNIFIED_MODEL_V1','WORKSPACE_REMOVAL_V1','BUSINESS_PLANNING_REMOVAL_V1'))<>3 THEN
        RAISE EXCEPTION '最终阶段未全部完成，整笔升级回滚';
    END IF;
    FOREACH table_name IN ARRAY ARRAY[
        'dh_modeling_collaboration','dh_modeling_collaborator','dh_modeling_approval',
        'dh_modeling_design_report','dh_modeling_inbox','dh_modeling_object_change','dh_modeling_reference_receipt',
        'dh_modeling_business_process','dh_modeling_business_process_data_domain_rel',
        'dh_modeling_business_process_supporting_domain_rel','dh_modeling_business_process_domain_candidate',
        'dh_modeling_subject_domain_process_rel','dh_modeling_business_object','dh_modeling_business_object_attribute',
        'dh_modeling_business_object_process_rel','dh_modeling_business_object_version','dh_modeling_business_object_external_ref'] LOOP
        IF to_regclass(format('%I.%I','datahub-center',table_name)) IS NOT NULL THEN
            RAISE EXCEPTION '退役表仍存在：%，整笔升级回滚',table_name;
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema='datahub-center'
        AND ((c.table_name='dh_modeling_physical_model' AND c.column_name IN
                ('theme_id','name','code','description','model_style','warehouse_layer','layer_id',
                 'subject_domain_id','business_process_id','data_domain_id','table_type','classification_status'))
            OR (c.table_name IN ('dh_modeling_logic_model','dh_modeling_concept_model') AND c.column_name='business_process_id')
            OR (c.table_name='dh_modeling_concept_entity' AND c.column_name IN ('business_object_id','business_object_version')))) THEN
        RAISE EXCEPTION '旧业务归属列仍存在，整笔升级回滚';
    END IF;
    SELECT string_agg(expected.name, ',') INTO missing_guard
    FROM (VALUES ('dh_modeling_physical_model','modeling_unified_binding_guard'),
                 ('dh_modeling_logic_model_version','modeling_published_design_guard'),
                 ('dh_modeling_physical_model_version','modeling_unified_version_guard'),
                 ('dh_modeling_logic_relation','modeling_unified_relation_guard')) expected(table_name,name)
    WHERE NOT EXISTS (SELECT 1 FROM pg_trigger t
        WHERE t.tgrelid=to_regclass(format('%I.%I','datahub-center',expected.table_name))
          AND t.tgname=expected.name AND t.tgenabled='O');
    IF missing_guard IS NOT NULL THEN RAISE EXCEPTION '最终守卫未启用：%',missing_guard; END IF;
    IF position('dh_modeling_business_process' IN pg_get_functiondef('"datahub-center".modeling_ownership_reference_guard()'::regprocedure))>0 THEN
        RAISE EXCEPTION '模型归属守卫仍引用已删除业务过程表，整笔升级回滚';
    END IF;
    RAISE NOTICE '统一模型升级已完整完成；无需再单独执行 0124 至 0128';
END $final_state$;
        $complete_previous$;
        RETURN;
    END IF;
    IF EXISTS(SELECT 1 FROM dh_modeling_unification_state) THEN RAISE EXCEPTION '空模型恢复不接受已有不完整历史账本'; END IF;
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_logic_model','dh_modeling_logic_model_version','dh_modeling_logic_relation',
        'dh_modeling_physical_model','dh_modeling_physical_model_version'] LOOP
        IF to_regclass(format('%I.%I','datahub-center',table_name)) IS NULL THEN
            RAISE EXCEPTION '缺少核心表 %，无法验证空模型恢复边界',table_name;
        END IF;
        EXECUTE format('LOCK TABLE %I IN ACCESS EXCLUSIVE MODE',table_name);
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I)',table_name) INTO has_rows;
        IF has_rows THEN RAISE EXCEPTION '旧结构不完整且核心表 % 非空，不能自动推断历史升级状态',table_name; END IF;
    END LOOP;
    -- 设计已空但开发期可能留有孤儿部署与回采记录；只允许已终结且没有可靠投递未决的原行。
    -- 原部署一行不删，原基线由下文全量存证；不会为这些记录新造模型、版本或成功状态。
    IF to_regclass('dh_modeling_deploy_record') IS NULL THEN RAISE EXCEPTION '缺少部署表，无法核实孤儿历史安全状态'; END IF;
    LOCK TABLE dh_modeling_deploy_record IN ACCESS EXCLUSIVE MODE;
    IF EXISTS(SELECT 1 FROM dh_modeling_deploy_record WHERE status IS NULL OR status NOT IN('SUCCEEDED','FAILED')
        OR delivery_lease_until>CURRENT_TIMESTAMP
        OR ((metadata_payload IS NOT NULL OR metadata_status IS NOT NULL) AND metadata_status IS DISTINCT FROM 'SUCCEEDED')
        OR (baseline_status IS NOT NULL AND baseline_status<>'SAVED')) THEN
        RAISE EXCEPTION '空设计恢复中的孤儿部署仍有未结束状态或待可靠登记，禁止略过真实DDL结果';
    END IF;
    SELECT count(*) INTO orphan_deploy_count FROM dh_modeling_deploy_record;
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_unification_map','dh_modeling_unified_menu_backup',
        'dh_modeling_workspace_removal_archive','dh_modeling_collaboration','dh_modeling_collaborator','dh_modeling_approval',
        'dh_modeling_design_report','dh_modeling_inbox','dh_modeling_object_change','dh_modeling_reference_receipt',
        'dh_modeling_model_check','dh_modeling_model_check_result','dh_modeling_environment_target'] LOOP
        IF to_regclass(format('%I.%I','datahub-center',table_name)) IS NOT NULL THEN
            EXECUTE format('LOCK TABLE %I IN ACCESS EXCLUSIVE MODE',table_name);
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM %I)',table_name) INTO has_rows;
            IF has_rows THEN RAISE EXCEPTION '空模型恢复存在 % 历史或任务证据，禁止伪造阶段或丢弃记录',table_name; END IF;
        END IF;
    END LOOP;
    UPDATE modeling_simplify_context SET empty_recovery=true,
        evidence=evidence||jsonb_build_object('preparationMode','EMPTY_MODEL_FINALIZATION','designRowsVerifiedEmpty',true,
            'retainedOrphanDeploymentCount',orphan_deploy_count);
    RAISE NOTICE '严格确认设计、版本、关系及旧迁移证据为空，保留%条已终结孤儿部署；直接完成最终结构，不补造0123至0127阶段',orphan_deploy_count;
END $prepare$;

-- 内嵌旧迁移可能重设账本注释，统一在其后安装最终契约，保证首次与重放结构一致。
COMMENT ON TABLE dh_modeling_unification_state IS '建模迁移阶段与不可变精简证据；完成标志只在对应实际操作成功后登记';
COMMENT ON COLUMN dh_modeling_unification_state.migration_key IS '迁移契约编号';
COMMENT ON COLUMN dh_modeling_unification_state.phase IS '真实完成阶段';
COMMENT ON COLUMN dh_modeling_unification_state.operator_name IS '执行数据库身份';
COMMENT ON COLUMN dh_modeling_unification_state.create_time IS '首次登记时间';
COMMENT ON COLUMN dh_modeling_unification_state.update_time IS '阶段完成时间';

-- 空模型恢复只创建最终结构需要的证据容器，不重建已经退役的业务表。
CREATE TABLE IF NOT EXISTS dh_modeling_unification_map (
    tenant_id bigint NOT NULL,
    physical_model_id bigint NOT NULL,
    logic_model_id bigint NOT NULL,
    migration_kind varchar(16) NOT NULL CHECK (migration_kind IN ('LINKED','CREATED')),
    original_head jsonb NOT NULL,
    original_versions jsonb NOT NULL,
    original_policy jsonb,
    original_members jsonb NOT NULL,
    canonical_head jsonb NOT NULL,
    canonical_versions jsonb NOT NULL,
    canonical_policy jsonb,
    canonical_members jsonb NOT NULL,
    review_issues jsonb NOT NULL DEFAULT '[]',
    review_status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK (review_status IN ('PENDING','CONFIRMED')),
    review_evidence jsonb,
    reviewed_by varchar(128),
    reviewed_at timestamp,
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id,physical_model_id),
    CONSTRAINT ck_modeling_unification_review CHECK (
        review_status<>'CONFIRMED' OR (review_evidence IS NOT NULL AND reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL))
);
COMMENT ON TABLE dh_modeling_unification_map IS '旧物理模型到统一设计的迁移映射与证据备份，仅供迁移追溯，不作为第三套业务定义';
COMMENT ON COLUMN dh_modeling_unification_map.tenant_id IS '所属租户';
COMMENT ON COLUMN dh_modeling_unification_map.physical_model_id IS '原物理模型编号，切换后仍为部署绑定编号';
COMMENT ON COLUMN dh_modeling_unification_map.logic_model_id IS '唯一设计编号，沿用逻辑模型编号';
COMMENT ON COLUMN dh_modeling_unification_map.migration_kind IS '已有明确链接或由独立物理模型创建草稿';
COMMENT ON COLUMN dh_modeling_unification_map.original_head IS '删除重复列前的完整物理模型头，保持原始证据';
COMMENT ON COLUMN dh_modeling_unification_map.original_versions IS '原物理模型全部历史版本备份，包含逻辑删除版本，不改写发布证据';
COMMENT ON COLUMN dh_modeling_unification_map.original_policy IS '原物理对象有效协作策略；空表示原有默认权限';
COMMENT ON COLUMN dh_modeling_unification_map.original_members IS '原物理对象有效协作授权';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_head IS '准备时唯一设计头，用于审查及漂移校验';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_versions IS '准备时唯一设计全部版本，用于漂移校验';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_policy IS '准备时唯一设计有效协作策略';
COMMENT ON COLUMN dh_modeling_unification_map.canonical_members IS '准备时唯一设计有效协作授权';
COMMENT ON COLUMN dh_modeling_unification_map.review_issues IS '需要审查的历史差异及缺失项，不等于审批通过';
COMMENT ON COLUMN dh_modeling_unification_map.review_status IS '迁移人工审查状态，与业务发布审批独立';
COMMENT ON COLUMN dh_modeling_unification_map.review_evidence IS '决定保留唯一设计并归档旧独立内容的审查证据及双端授权约定';
COMMENT ON COLUMN dh_modeling_unification_map.reviewed_by IS '实际执行审查确认的数据库身份';
COMMENT ON COLUMN dh_modeling_unification_map.reviewed_at IS '迁移审查确认时间';
COMMENT ON COLUMN dh_modeling_unification_map.create_time IS '映射准备时间';
COMMENT ON COLUMN dh_modeling_unification_map.update_time IS '审查状态最近更新时间';

CREATE TABLE IF NOT EXISTS dh_modeling_unified_menu_backup (
    migration_key varchar(40) NOT NULL,
    menu_id bigint NOT NULL,
    original_component varchar(255) NOT NULL,
    before_image jsonb NOT NULL,
    after_image jsonb NOT NULL,
    operator_name varchar(128) NOT NULL,
    applied_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (migration_key, menu_id),
    UNIQUE (migration_key, original_component)
);
COMMENT ON TABLE dh_modeling_unified_menu_backup IS '统一模型菜单切换证据账本；保留完整前后镜像，不作为权限配置来源';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.migration_key IS '菜单切换契约编号';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.menu_id IS '被修改的原菜单编号，保持不变';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.original_component IS '切换前组件路径，用于严格定位原入口';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.before_image IS '首次切换前完整菜单行镜像，包含原权限与展示状态';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.after_image IS '首次切换后完整菜单行镜像，重放时用于发现后续人工变更';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.operator_name IS '首次执行菜单切换的数据库身份';
COMMENT ON COLUMN dh_modeling_unified_menu_backup.applied_at IS '首次完成菜单切换的时间';

CREATE TABLE IF NOT EXISTS dh_modeling_workspace_removal_archive (
    source_table varchar(80) NOT NULL,
    row_key varchar(160) NOT NULL,
    row_image jsonb NOT NULL,
    operator_name varchar(128) NOT NULL,
    archived_at timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (source_table,row_key)
);
COMMENT ON TABLE dh_modeling_workspace_removal_archive IS '0126退役前原始行证据，仅供数据库迁移核对，不提供业务查询或恢复授权入口';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.source_table IS '被退役或清理的原表名称';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.row_key IS '租户加原记录编号或引用操作编号，保持原始身份';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.row_image IS '首次退役前完整原行，含旧ACL、审批状态或菜单授权';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.operator_name IS '归档时数据库执行身份';
COMMENT ON COLUMN dh_modeling_workspace_removal_archive.archived_at IS '首次归档时间';
REVOKE ALL ON dh_modeling_workspace_removal_archive FROM PUBLIC;

CREATE OR REPLACE FUNCTION dh_modeling_unification_evidence_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
BEGIN
    IF TG_OP='DELETE' THEN RAISE EXCEPTION '模型迁移原始证据不可删除'; END IF;
    IF (to_jsonb(NEW)-ARRAY['review_status','review_evidence','reviewed_by','reviewed_at','update_time'])
       IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['review_status','review_evidence','reviewed_by','reviewed_at','update_time']) THEN
        RAISE EXCEPTION '模型迁移映射及原始备份不可修改';
    END IF;
    IF OLD.review_status='CONFIRMED' AND to_jsonb(NEW) IS DISTINCT FROM to_jsonb(OLD) THEN
        RAISE EXCEPTION '已确认的模型迁移审查证据不可修改';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unification_evidence_guard() IS '保护切换备份与迁移审查证据，防止覆盖原始行或重置已确认决定';
DROP TRIGGER IF EXISTS modeling_unification_evidence_guard ON dh_modeling_unification_map;
CREATE TRIGGER modeling_unification_evidence_guard BEFORE UPDATE OR DELETE ON dh_modeling_unification_map
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unification_evidence_guard();

CREATE OR REPLACE FUNCTION dh_modeling_workspace_archive_guard() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
BEGIN
    IF TG_OP='INSERT' AND NOT EXISTS (SELECT 1 FROM dh_modeling_unification_state WHERE migration_key IN ('WORKSPACE_REMOVAL_V1','MODEL_SIMPLIFICATION_V1')) THEN RETURN NEW; END IF;
    RAISE EXCEPTION '工作台退役原始证据禁止新增、修改、删除或清空' USING ERRCODE='23514';
END $guard$;
COMMENT ON FUNCTION dh_modeling_workspace_archive_guard() IS '保护工作台退役前原行证据';
DROP TRIGGER IF EXISTS modeling_workspace_archive_guard ON dh_modeling_workspace_removal_archive;
CREATE TRIGGER modeling_workspace_archive_guard BEFORE INSERT OR UPDATE OR DELETE ON dh_modeling_workspace_removal_archive
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_workspace_archive_guard();
DROP TRIGGER IF EXISTS modeling_workspace_archive_truncate_guard ON dh_modeling_workspace_removal_archive;
CREATE TRIGGER modeling_workspace_archive_truncate_guard BEFORE TRUNCATE ON dh_modeling_workspace_removal_archive
    FOR EACH STATEMENT EXECUTE FUNCTION dh_modeling_workspace_archive_guard();


LOCK TABLE dh_modeling_logic_model,dh_modeling_logic_model_version,dh_modeling_logic_relation,
    dh_modeling_physical_model,dh_modeling_physical_model_version,dh_modeling_deploy_record,
    system_menu,system_role_menu,system_tenant_package IN ACCESS EXCLUSIVE MODE;

-- 幂等补齐最终核心列和约束；普通升级中均已由真实准备建立，空模型恢复也采用同一约束。
ALTER TABLE dh_modeling_logic_model ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
ALTER TABLE dh_modeling_logic_model_version ADD COLUMN IF NOT EXISTS relation_snapshot jsonb;
ALTER TABLE dh_modeling_physical_model ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
ALTER TABLE dh_modeling_physical_model_version ADD COLUMN IF NOT EXISTS design_version_id bigint;
ALTER TABLE dh_modeling_physical_model_version ADD COLUMN IF NOT EXISTS definition_origin varchar(24);
ALTER TABLE dh_modeling_logic_relation ADD COLUMN IF NOT EXISTS field_pairs jsonb;
ALTER TABLE dh_modeling_logic_relation ADD COLUMN IF NOT EXISTS revision bigint NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_modeling_logic_model.revision IS '统一设计聚合乐观锁；字段、关系或业务口径变更在同一事务递增';
COMMENT ON COLUMN dh_modeling_logic_model_version.relation_snapshot IS '本版本发布时冻结的关系及字段标识快照；历史未知保持为空，不根据现状伪造';
COMMENT ON COLUMN dh_modeling_physical_model.revision IS '部署绑定配置乐观锁，与统一设计修订号独立';
COMMENT ON COLUMN dh_modeling_physical_model_version.design_version_id IS '本次物理候选精确采用的统一设计版本；旧版本来源无法证明时保持为空';
COMMENT ON COLUMN dh_modeling_physical_model_version.definition_origin IS '定义来源：LEGACY_PUBLISHED 历史发布、LEGACY_DRAFT 历史独立草稿、UNIFIED 统一设计派生';
COMMENT ON COLUMN dh_modeling_logic_relation.field_pairs IS '有序复合关联键数组：[{sourceFieldUid,targetFieldUid}]；历史只按名称保存的关联保持为空待确认';
COMMENT ON COLUMN dh_modeling_logic_relation.revision IS '关系编辑乐观锁；同时更新涉及的设计聚合修订号';

-- 当前历史快照从未冻结精确逻辑版本来源；不可用可变头 source_logic_version_id 猜测所有旧版本。
UPDATE dh_modeling_physical_model_version
SET definition_origin=CASE WHEN status='PUBLISHED' THEN 'LEGACY_PUBLISHED' ELSE 'LEGACY_DRAFT' END
WHERE definition_origin IS NULL;
ALTER TABLE dh_modeling_physical_model_version ALTER COLUMN definition_origin SET NOT NULL;
-- 准备阶段兼容旧服务新增草稿；0124 切换后默认改为 UNIFIED，未带精确设计版本的写入将失败。
ALTER TABLE dh_modeling_physical_model_version ALTER COLUMN definition_origin SET DEFAULT 'LEGACY_DRAFT';

CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_active_name ON dh_modeling_logic_model(tenant_id,name) WHERE deleted=0;
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_active_code ON dh_modeling_logic_model(tenant_id,code) WHERE deleted=0 AND code IS NOT NULL AND code<>'';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_tenant_id ON dh_modeling_logic_model(tenant_id,id);
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_version_tenant_id ON dh_modeling_logic_model_version(tenant_id,id);
CREATE INDEX IF NOT EXISTS idx_modeling_physical_design ON dh_modeling_physical_model(tenant_id,logic_model_id);
CREATE INDEX IF NOT EXISTS idx_modeling_physical_version_design ON dh_modeling_physical_model_version(tenant_id,design_version_id);

DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_physical_model_version'::regclass AND conname='ck_modeling_definition_origin') THEN
        ALTER TABLE dh_modeling_physical_model_version ADD CONSTRAINT ck_modeling_definition_origin CHECK (
            definition_origin IN ('LEGACY_PUBLISHED','LEGACY_DRAFT','UNIFIED')
            AND (definition_origin<>'UNIFIED' OR design_version_id IS NOT NULL));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_physical_model_version'::regclass AND conname='fk_modeling_physical_design_version') THEN
        ALTER TABLE dh_modeling_physical_model_version ADD CONSTRAINT fk_modeling_physical_design_version
            FOREIGN KEY (tenant_id,design_version_id) REFERENCES dh_modeling_logic_model_version(tenant_id,id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_logic_relation'::regclass AND conname='ck_modeling_relation_field_pairs') THEN
        ALTER TABLE dh_modeling_logic_relation ADD CONSTRAINT ck_modeling_relation_field_pairs CHECK (
            field_pairs IS NULL OR (jsonb_typeof(field_pairs)='array' AND jsonb_array_length(field_pairs)>0));
    END IF;
END $constraints$;


ALTER TABLE dh_modeling_logic_model ADD COLUMN IF NOT EXISTS layout_revision bigint NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_modeling_logic_model.layout_revision IS '画布布局独立乐观锁';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_active_deploy_target ON dh_modeling_physical_model
    (tenant_id,database_id,table_name) WHERE deleted=0;
COMMENT ON INDEX uq_modeling_active_deploy_target IS '同租户同数据源表只能存在一个活动部署绑定，防止并发占用';
ALTER TABLE dh_modeling_physical_model ALTER COLUMN logic_model_id SET NOT NULL;
DO $binding_fk$
BEGIN
    IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='dh_modeling_physical_model'::regclass AND conname='fk_modeling_binding_design') THEN
        ALTER TABLE dh_modeling_physical_model ADD CONSTRAINT fk_modeling_binding_design
            FOREIGN KEY(tenant_id,logic_model_id) REFERENCES dh_modeling_logic_model(tenant_id,id);
    END IF;
END $binding_fk$;
ALTER TABLE dh_modeling_physical_model_version ALTER COLUMN definition_origin SET DEFAULT 'UNIFIED';
ALTER TABLE dh_modeling_deploy_record ADD COLUMN IF NOT EXISTS observed_schema_snapshot text;
COMMENT ON COLUMN dh_modeling_deploy_record.observed_schema_snapshot IS '成功部署核验后采集的完整字段数组JSON；旧来源不可证明时保持空，不伪造实库基线';
COMMENT ON COLUMN dh_modeling_deploy_record.baseline_status IS '本条部署记录内实库快照保存状态；历史兼容为空或SAVED，不再写独立基线表';
COMMENT ON COLUMN dh_modeling_deploy_record.baseline_saved_at IS '成功记录内实库快照保存时间，迁移采用可证明的原回采时间';

DO $preflight$
BEGIN
    IF EXISTS(SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='MODEL_SIMPLIFICATION_V1' AND phase='CLEANED') THEN RETURN; END IF;
    IF EXISTS(SELECT 1 FROM dh_modeling_deploy_record WHERE deleted=0 AND
        (status NOT IN('SUCCEEDED','FAILED') OR delivery_lease_until>CURRENT_TIMESTAMP
         OR ((metadata_payload IS NOT NULL OR metadata_status IS NOT NULL) AND metadata_status IS DISTINCT FROM 'SUCCEEDED')
         OR (baseline_status IS NOT NULL AND baseline_status<>'SAVED')))
       OR EXISTS(SELECT 1 FROM dh_modeling_physical_model WHERE deleted=0 AND COALESCE(deploy_status,'NOT_DEPLOYED') NOT IN('NOT_DEPLOYED','SUCCEEDED','FAILED')) THEN
        RAISE EXCEPTION '部署、可靠登记或基线保存尚未完成，必须先核验并停写';
    END IF;
END $preflight$;

-- 同一基线只能由五项完整身份唯一对应到成功部署；不存在可证明关联时只保存迁移证据。
CREATE OR REPLACE FUNCTION pg_temp.modeling_valid_observed_snapshot(raw text) RETURNS boolean LANGUAGE plpgsql AS $valid$
DECLARE fields jsonb;
BEGIN
    BEGIN fields:=raw::jsonb; EXCEPTION WHEN invalid_text_representation THEN RETURN false; END;
    IF fields IS NULL OR jsonb_typeof(fields)<>'array' OR jsonb_array_length(fields)=0 THEN RETURN false; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(fields) f WHERE jsonb_typeof(f)<>'object'
        OR jsonb_typeof(f->'fieldName') IS DISTINCT FROM 'string' OR NULLIF(btrim(f->>'fieldName'),'') IS NULL
        OR jsonb_typeof(f->'dataType') IS DISTINCT FROM 'string' OR NULLIF(btrim(f->>'dataType'),'') IS NULL) THEN RETURN false; END IF;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(fields) f GROUP BY lower(btrim(f->>'fieldName')) HAVING count(*)>1) THEN RETURN false; END IF;
    RETURN true;
END $valid$;
COMMENT ON FUNCTION pg_temp.modeling_valid_observed_snapshot(text) IS '迁移临时校验：仅非空且字段名、类型和唯一性完整的数组可成为运行时快照';
DO $merge_baselines$
DECLARE all_rows jsonb:='[]'; merged integer:=0; total integer:=0; blocked text;
BEGIN
    IF EXISTS(SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='MODEL_SIMPLIFICATION_V1' AND phase='CLEANED') THEN RETURN; END IF;
    IF to_regclass('dh_modeling_schema_baseline') IS NULL THEN
        UPDATE modeling_simplify_context SET evidence=evidence||jsonb_build_object('legacyBaselines','[]'::jsonb,'baselineMergeSummary',jsonb_build_object('total',0,'merged',0,'archivedOnly',0));
        RETURN;
    END IF;
    LOCK TABLE dh_modeling_schema_baseline IN ACCESS EXCLUSIVE MODE;
    IF EXISTS(SELECT 1 FROM dh_modeling_deploy_record WHERE status='SUCCEEDED' AND deleted=0
        AND observed_schema_snapshot IS NOT NULL AND NOT pg_temp.modeling_valid_observed_snapshot(observed_schema_snapshot)) THEN
        RAISE EXCEPTION '成功部署已有快照无法解码为有效非空字段数组，禁止覆盖或忽略';
    END IF;
    SELECT COALESCE(jsonb_agg(to_jsonb(b) ORDER BY tenant_id,id),'[]'::jsonb),count(*) INTO all_rows,total FROM dh_modeling_schema_baseline b;
    CREATE TEMPORARY TABLE modeling_baseline_match ON COMMIT DROP AS
    SELECT b.id AS baseline_id,b.tenant_id,b.model_id,b.database_id,b.table_name,b.version_no,b.fields,b.collected_time,
        min(d.id) AS deploy_id,count(d.id) AS matches
    FROM dh_modeling_schema_baseline b LEFT JOIN dh_modeling_deploy_record d
        ON d.tenant_id=b.tenant_id AND d.model_id=b.model_id AND d.database_id=b.database_id
        AND d.table_name=b.table_name AND d.version_no=b.version_no AND d.status='SUCCEEDED' AND d.deleted=0
        AND EXISTS(SELECT 1 FROM dh_modeling_physical_model_version v WHERE v.id=d.version_id AND v.tenant_id=d.tenant_id AND v.model_id=d.model_id AND v.version=b.version_no)
    WHERE b.deleted=0 AND pg_temp.modeling_valid_observed_snapshot(b.fields::text)
    GROUP BY b.id,b.tenant_id,b.model_id,b.database_id,b.table_name,b.version_no,b.fields,b.collected_time;
    -- 同一成功记录存在互不相同的回采内容时不能选择最新一条冒充对应证据。
    UPDATE modeling_baseline_match m SET matches=0 WHERE m.deploy_id IN(
        SELECT deploy_id FROM modeling_baseline_match WHERE matches=1 GROUP BY deploy_id HAVING count(DISTINCT fields)>1);
    IF EXISTS(SELECT 1 FROM modeling_baseline_match m JOIN dh_modeling_deploy_record d ON d.id=m.deploy_id AND d.tenant_id=m.tenant_id
        WHERE m.matches=1 AND d.observed_schema_snapshot IS NOT NULL AND d.observed_schema_snapshot::jsonb IS DISTINCT FROM m.fields) THEN
        RAISE EXCEPTION '成功部署已有快照与旧基线不一致，禁止覆盖；请先核对来源';
    END IF;
    SELECT string_agg(format('租户%s/目标%s/基线%s',b.tenant_id,b.model_id,b.id),'；') INTO blocked
    FROM dh_modeling_schema_baseline b JOIN dh_modeling_physical_model p ON p.tenant_id=b.tenant_id AND p.id=b.model_id AND p.deleted=0
    WHERE b.deleted=0 AND NOT EXISTS(SELECT 1 FROM modeling_baseline_match m WHERE m.tenant_id=b.tenant_id AND m.baseline_id=b.id AND m.matches=1)
      AND NOT EXISTS(SELECT 1 FROM dh_modeling_deploy_record d WHERE d.id=(
            SELECT x.id FROM dh_modeling_deploy_record x WHERE x.tenant_id=p.tenant_id AND x.model_id=p.id
                AND x.database_id=p.database_id AND x.table_name=p.table_name AND x.deleted=0 AND x.status='SUCCEEDED'
                ORDER BY x.id DESC LIMIT 1)
            AND (pg_temp.modeling_valid_observed_snapshot(d.observed_schema_snapshot)
                OR (d.observed_schema_snapshot IS NULL AND NULLIF(btrim(d.observed_schema_hash),'') IS NOT NULL)));
    IF blocked IS NOT NULL THEN RAISE EXCEPTION '有效目标原基线无法证明所属成功部署，且无可验证运行时摘要；禁止丢弃保护语义：%',blocked; END IF;
    UPDATE dh_modeling_deploy_record d SET observed_schema_snapshot=m.fields::text,
        baseline_saved_at=COALESCE(d.baseline_saved_at,m.collected_time),baseline_status=COALESCE(d.baseline_status,'SAVED')
    FROM (SELECT deploy_id,tenant_id,fields,max(collected_time) AS collected_time FROM modeling_baseline_match WHERE matches=1 GROUP BY deploy_id,tenant_id,fields) m
    WHERE d.id=m.deploy_id AND d.tenant_id=m.tenant_id AND d.observed_schema_snapshot IS NULL;
    SELECT count(*) INTO merged FROM modeling_baseline_match WHERE matches=1;
    UPDATE modeling_simplify_context SET evidence=evidence||jsonb_build_object('legacyBaselines',all_rows,
        'baselineMergeSummary',jsonb_build_object('total',total,'merged',merged,'archivedOnly',total-merged),
        'baselineMatches',COALESCE((SELECT jsonb_agg(jsonb_build_object('tenantId',tenant_id,'baselineId',baseline_id,'deployId',CASE WHEN matches=1 THEN deploy_id END)
            ORDER BY tenant_id,baseline_id) FROM modeling_baseline_match),'[]'::jsonb));
END $merge_baselines$;

-- 下列归属守卫只引用最终保留表；业务分类仍是规划对象，不恢复已退役的旧分类跨域关系。
CREATE OR REPLACE FUNCTION modeling_ownership_reference_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE row_data jsonb; tenant bigint; object_id bigint; deleting boolean; ref_field text; ref_table text; found_row boolean;
BEGIN
    row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    tenant:=(row_data->>'tenant_id')::bigint; object_id:=(row_data->>'id')::bigint;
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-tenant:'||tenant::text,0));
    deleting:=TG_OP='DELETE' OR COALESCE((row_data->>'deleted')::integer,0)<>0;
    IF TG_TABLE_NAME='dh_modeling_logic_model' AND NOT deleting THEN
        FOR ref_field,ref_table IN SELECT * FROM(VALUES('data_domain_id','dh_modeling_data_domain'),('subject_domain_id','dh_modeling_subject_domain'),('layer_id','dh_modeling_dw_layer')) r(f,t) LOOP
            IF row_data->>ref_field IS NOT NULL THEN
                EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND tenant_id=$2 AND deleted=0)',ref_table)
                    INTO found_row USING (row_data->>ref_field)::bigint,tenant;
                IF NOT found_row THEN RAISE EXCEPTION '模型归属不存在或不属于当前租户：%',ref_field USING ERRCODE='23514'; END IF;
            END IF;
        END LOOP;
    ELSIF TG_TABLE_NAME IN('dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_dw_layer') AND deleting THEN
        ref_field:=CASE TG_TABLE_NAME WHEN 'dh_modeling_data_domain' THEN 'data_domain_id' WHEN 'dh_modeling_subject_domain' THEN 'subject_domain_id' ELSE 'layer_id' END;
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_logic_model WHERE %I=$1 AND tenant_id=$2 AND deleted=0)',ref_field)
            INTO found_row USING object_id,tenant;
        IF found_row THEN RAISE EXCEPTION '规划对象仍被模型引用，不能删除' USING ERRCODE='23514'; END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_ownership_reference_guard() IS '保护统一设计与数据域、主题域、分层的租户一致性及删除引用';
CREATE OR REPLACE FUNCTION modeling_guard_layer_change() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
BEGIN
    IF TG_OP='UPDATE' AND ROW(NEW.deleted,NEW.status,NEW.node_type,NEW.layer_code,NEW.table_prefix,NEW.default_table_type)
        IS NOT DISTINCT FROM ROW(OLD.deleted,OLD.status,OLD.node_type,OLD.layer_code,OLD.table_prefix,OLD.default_table_type) THEN RETURN NEW; END IF;
    IF EXISTS(SELECT 1 FROM dh_modeling_logic_model WHERE tenant_id=OLD.tenant_id AND layer_id=OLD.id AND deleted=0) THEN
        RAISE EXCEPTION '分层已被模型引用，不能删除、停用或改变技术配置' USING ERRCODE='23514';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_guard_layer_change() IS '保护仍被统一设计引用的数仓分层';
CREATE OR REPLACE FUNCTION modeling_audit_planning_change() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $audit$
DECLARE old_data jsonb:='{}'; new_data jsonb:='{}'; detail jsonb:='{}'; key text; actor_text text; actor bigint; row_data jsonb; operation text:=TG_OP;
BEGIN
    IF TG_OP<>'INSERT' THEN old_data:=to_jsonb(OLD); END IF;
    IF TG_OP<>'DELETE' THEN new_data:=to_jsonb(NEW); END IF;
    row_data:=CASE WHEN TG_OP='DELETE' THEN old_data ELSE new_data END;
    IF TG_OP='UPDATE' AND old_data->>'deleted'='0' AND new_data->>'deleted'<>'0' THEN operation:='DELETE'; END IF;
    FOREACH key IN ARRAY ARRAY['name','code','layer_name','layer_code','parent_id','status','node_type','table_prefix','default_table_type',
        'leader_user_id','owner_user_id','owner_department','scope_includes','scope_excludes','responsibility_scope','deleted'] LOOP
        IF old_data->key IS DISTINCT FROM new_data->key THEN detail:=detail||jsonb_build_object(key,jsonb_build_object('before',old_data->>key,'after',new_data->>key)); END IF;
    END LOOP;
    IF detail='{}'::jsonb THEN RETURN COALESCE(NEW,OLD); END IF;
    actor_text:=CASE WHEN TG_OP='INSERT' THEN row_data->>'creator' WHEN TG_OP='UPDATE' AND
        (new_data->>'updater' IS DISTINCT FROM old_data->>'updater' OR new_data->>'update_time' IS DISTINCT FROM old_data->>'update_time') THEN row_data->>'updater' ELSE NULL END;
    BEGIN actor:=actor_text::bigint; EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN actor:=NULL; END;
    INSERT INTO dh_modeling_planning_change(tenant_id,kind,object_id,actor_id,action,changes,creator,updater)
        VALUES((row_data->>'tenant_id')::bigint,TG_ARGV[0],(row_data->>'id')::bigint,actor,operation,detail,COALESCE(actor_text,''),COALESCE(actor_text,''));
    RETURN COALESCE(NEW,OLD);
END $audit$;
COMMENT ON FUNCTION modeling_audit_planning_change() IS '仅记录保留规划对象的业务字段变化，不将迁移身份伪装为用户';
DO $install_guards$
DECLARE table_name text; kind text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_logic_model','dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_dw_layer'] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS modeling_ownership_reference_guard ON %I',table_name);
        EXECUTE format('CREATE TRIGGER modeling_ownership_reference_guard BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION modeling_ownership_reference_guard()',table_name);
    END LOOP;
    FOR table_name,kind IN SELECT * FROM(VALUES('dh_modeling_biz_category','BIZ_CATEGORY'),('dh_modeling_data_domain','DATA_DOMAIN'),('dh_modeling_subject_domain','SUBJECT_DOMAIN'),('dh_modeling_dw_layer','DW_LAYER')) t(n,k) LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS trg_modeling_planning_audit ON %I',table_name);
        EXECUTE format('CREATE TRIGGER trg_modeling_planning_audit AFTER INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION modeling_audit_planning_change(%L)',table_name,kind);
    END LOOP;
END $install_guards$;
DROP TRIGGER IF EXISTS trg_modeling_layer_change ON dh_modeling_dw_layer;
CREATE TRIGGER trg_modeling_layer_change BEFORE UPDATE OR DELETE ON dh_modeling_dw_layer FOR EACH ROW EXECUTE FUNCTION modeling_guard_layer_change();
DROP TRIGGER IF EXISTS trg_modeling_layer_reference ON dh_modeling_physical_model;
DROP TRIGGER IF EXISTS modeling_ownership_reference_guard ON dh_modeling_physical_model;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_logic_model;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_logic_model_version;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_physical_model;
DROP TRIGGER IF EXISTS modeling_approval_freeze ON dh_modeling_physical_model_version;
CREATE OR REPLACE FUNCTION dh_modeling_unified_binding_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
BEGIN
    IF ROW(NEW.id,NEW.tenant_id,NEW.logic_model_id) IS DISTINCT FROM ROW(OLD.id,OLD.tenant_id,OLD.logic_model_id) THEN
        RAISE EXCEPTION '部署绑定身份和唯一设计归属不可修改；更换设计须新建绑定';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unified_binding_guard() IS '固定部署绑定的租户和设计身份，防止改变父记录后使历史候选指向另一设计';
DROP TRIGGER IF EXISTS modeling_unified_binding_guard ON dh_modeling_physical_model;
CREATE TRIGGER modeling_unified_binding_guard BEFORE UPDATE ON dh_modeling_physical_model
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unified_binding_guard();

CREATE OR REPLACE FUNCTION dh_modeling_published_design_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
BEGIN
    IF OLD.status='PUBLISHED' THEN
        IF TG_OP='DELETE' THEN RAISE EXCEPTION '已发布统一设计版本不可物理删除'; END IF;
        IF (to_jsonb(NEW)-ARRAY['deleted','updater','update_time']) IS DISTINCT FROM
           (to_jsonb(OLD)-ARRAY['deleted','updater','update_time']) THEN
            RAISE EXCEPTION '已发布统一设计内容不可修改，缺失的历史字段标识只允许在新草稿补齐';
        END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_published_design_guard() IS '冻结已发布设计及关系快照，不允许字段标识回填工具改写历史';
DROP TRIGGER IF EXISTS modeling_published_design_guard ON dh_modeling_logic_model_version;
CREATE TRIGGER modeling_published_design_guard BEFORE UPDATE OR DELETE ON dh_modeling_logic_model_version
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_published_design_guard();

CREATE OR REPLACE FUNCTION dh_modeling_unified_version_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
DECLARE binding_design bigint; version_design bigint; design_status text;
BEGIN
    IF TG_OP<>'INSERT' THEN
        IF OLD.definition_origin IN ('LEGACY_DRAFT','LEGACY_PUBLISHED') THEN
            RAISE EXCEPTION '历史独立物理版本只读归档；变更新建设计版本和部署候选，不修改旧证据';
        END IF;
        IF TG_OP='DELETE' THEN RAISE EXCEPTION '部署候选历史不可物理删除'; END IF;
        IF OLD.status='PUBLISHED' AND
            (to_jsonb(NEW)-ARRAY['deleted','updater','update_time']) IS DISTINCT FROM
            (to_jsonb(OLD)-ARRAY['deleted','updater','update_time']) THEN
            RAISE EXCEPTION '已发布的物理候选证据不可修改';
        END IF;
    END IF;
    IF NEW.definition_origin<>'UNIFIED' OR NEW.design_version_id IS NULL THEN
        RAISE EXCEPTION '新物理候选必须来自精确统一设计版本，不得创建独立物理字段定义';
    END IF;
    SELECT logic_model_id INTO binding_design FROM dh_modeling_physical_model
        WHERE tenant_id=NEW.tenant_id AND id=NEW.model_id AND deleted=0 FOR SHARE;
    SELECT model_id,status INTO version_design,design_status FROM dh_modeling_logic_model_version
        WHERE tenant_id=NEW.tenant_id AND id=NEW.design_version_id AND deleted=0 FOR SHARE;
    IF binding_design IS NULL OR binding_design IS DISTINCT FROM version_design OR design_status IS DISTINCT FROM 'PUBLISHED' THEN
        RAISE EXCEPTION '部署候选必须绑定同一模型同租户的已发布设计版本';
    END IF;
    IF NEW.status='PUBLISHED' AND (jsonb_typeof(NEW.model_snapshot) IS DISTINCT FROM 'object'
        OR jsonb_typeof(NEW.fields) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '发布部署候选必须冻结完整物理快照与字段数组';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unified_version_guard() IS '统一模型部署候选来源与历史只读守卫，不把旧草稿伪装成发布版本';
DROP TRIGGER IF EXISTS modeling_unified_version_guard ON dh_modeling_physical_model_version;
CREATE TRIGGER modeling_unified_version_guard BEFORE INSERT OR UPDATE OR DELETE ON dh_modeling_physical_model_version
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unified_version_guard();

-- 业务关系保留同一份数据；历史缺 UID 时明确留空，新编辑由服务在事务中验证复合键并推进设计修订。
CREATE OR REPLACE FUNCTION dh_modeling_unified_relation_guard()
RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $fn$
DECLARE pair jsonb;
BEGIN
    IF NEW.deleted<>0 THEN RETURN NEW; END IF;
    IF NOT EXISTS (SELECT 1 FROM dh_modeling_logic_model WHERE id=NEW.source_model_id AND tenant_id=NEW.tenant_id AND deleted=0)
        OR NOT EXISTS (SELECT 1 FROM dh_modeling_logic_model WHERE id=NEW.target_model_id AND tenant_id=NEW.tenant_id AND deleted=0) THEN
        RAISE EXCEPTION 'ER 关系两端必须是同租户有效模型';
    END IF;
    IF NEW.field_pairs IS NULL THEN
        RAISE EXCEPTION '新建或编辑关系须提供稳定字段标识，不得仅按字段名称保存';
    END IF;
    FOR pair IN SELECT value FROM jsonb_array_elements(NEW.field_pairs) LOOP
        IF jsonb_typeof(pair)<>'object' OR NULLIF(btrim(pair->>'sourceFieldUid'),'') IS NULL
            OR NULLIF(btrim(pair->>'targetFieldUid'),'') IS NULL THEN
            RAISE EXCEPTION '复合关联键必须提供非空的两端字段标识';
        END IF;
    END LOOP;
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.field_pairs) p GROUP BY p->>'sourceFieldUid' HAVING count(*)>1)
        OR EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.field_pairs) p GROUP BY p->>'targetFieldUid' HAVING count(*)>1) THEN
        RAISE EXCEPTION '复合关联键不能重复使用同一端字段';
    END IF;
    RETURN NEW;
END $fn$;
COMMENT ON FUNCTION dh_modeling_unified_relation_guard() IS '新 ER 关系写入校验租户和复合字段标识，实际字段存在性及双端编辑权限由应用事务校验';
DROP TRIGGER IF EXISTS modeling_unified_relation_guard ON dh_modeling_logic_relation;
CREATE TRIGGER modeling_unified_relation_guard BEFORE INSERT OR UPDATE ON dh_modeling_logic_relation
    FOR EACH ROW EXECUTE FUNCTION dh_modeling_unified_relation_guard();



CREATE TEMPORARY TABLE modeling_simplify_menus(id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO modeling_simplify_menus SELECT id FROM system_menu WHERE
    permission LIKE 'modeling:biz-theme:%' OR permission LIKE 'modeling:theme-plan:%'
    OR permission LIKE 'modeling:subject-domain-link:%' OR permission IN('modeling:model:check-config','modeling:workspace:environment')
    OR permission LIKE 'modeling:workspace:approval%' OR permission LIKE 'modeling:workspace:collaboration%' OR permission LIKE 'modeling:workspace:inbox%'
    OR permission LIKE 'modeling:business-process:%' OR permission LIKE 'modeling:business-object:%'
    OR trim(both '/' from COALESCE(component,'')) IN('modeling/conceptmodel/index','modeling/conceptmodel/design','modeling/biztheme/index',
        'modeling/themeplan/index','modeling/themerel/index','modeling/subjectdomainlink/index','modeling/modelcheck/index',
        'modeling/checkresult/index','modeling/physicalmodel/index','modeling/businessprocess/index','modeling/businessobject/index');
WITH RECURSIVE buttons(id) AS(SELECT id FROM modeling_simplify_menus UNION SELECT c.id FROM system_menu c JOIN buttons p ON c.parent_id=p.id WHERE c.type=3)
INSERT INTO modeling_simplify_menus SELECT id FROM buttons ON CONFLICT(id) DO NOTHING;
DO $menu_preflight$
DECLARE matches integer; menu_id bigint;
BEGIN
    IF EXISTS(SELECT 1 FROM system_menu c JOIN modeling_simplify_menus p ON c.parent_id=p.id WHERE c.type<>3
        AND NOT EXISTS(SELECT 1 FROM modeling_simplify_menus r WHERE r.id=c.id)) THEN RAISE EXCEPTION '退休菜单包含其他页面或目录，禁止连带删除'; END IF;
    SELECT count(*),min(id) INTO matches,menu_id FROM system_menu WHERE deleted=0 AND type=2 AND trim(both '/' from component) IN('modeling/logicmodel/index','modeling/tablemodel/index');
    IF matches<>1 THEN RAISE EXCEPTION '模型管理入口缺失或不唯一，禁止猜测菜单身份'; END IF;
    IF NOT EXISTS(SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='MODEL_SIMPLIFICATION_V1') THEN
        UPDATE modeling_simplify_context SET evidence=evidence||jsonb_build_object('menuBefore',COALESCE((SELECT jsonb_agg(to_jsonb(m) ORDER BY m.id)
            FROM system_menu m WHERE m.id IN(SELECT id FROM modeling_simplify_menus) OR m.id=menu_id),'[]'::jsonb));
    END IF;
    UPDATE system_menu SET name='模型管理',component='modeling/tablemodel/index',component_name='ModelingTableModel',updater='migration:0131',update_time=CURRENT_TIMESTAMP
        WHERE id=menu_id AND (name,component,component_name) IS DISTINCT FROM ('模型管理','modeling/tablemodel/index','ModelingTableModel');
END $menu_preflight$;
UPDATE system_tenant_package p SET menu_ids=(SELECT COALESCE(jsonb_agg(e.value ORDER BY e.ordinality),'[]'::jsonb)::text
    FROM jsonb_array_elements(p.menu_ids::jsonb) WITH ORDINALITY e(value,ordinality)
    WHERE NOT EXISTS(SELECT 1 FROM modeling_simplify_menus m WHERE m.id::text=e.value#>>'{}')),updater='migration:0131',update_time=CURRENT_TIMESTAMP
WHERE EXISTS(SELECT 1 FROM jsonb_array_elements_text(p.menu_ids::jsonb) e(value) JOIN modeling_simplify_menus m ON m.id::text=e.value);
DELETE FROM system_role_menu WHERE menu_id IN(SELECT id FROM modeling_simplify_menus);
DELETE FROM system_menu WHERE id IN(SELECT id FROM modeling_simplify_menus);
UPDATE system_menu SET name='检查模型设计',updater='migration:0131',update_time=CURRENT_TIMESTAMP WHERE permission='modeling:model:check' AND name<>'检查模型设计';
UPDATE system_menu SET name='分析主题',updater='migration:0131',update_time=CURRENT_TIMESTAMP WHERE trim(both '/' from component)='modeling/subjectdomain/index' AND name<>'分析主题';
DELETE FROM system_dict_data WHERE dict_type ~ '^modeling_(concept|biz_theme|theme_plan|theme_rel|model_check|check_result|environment|subject_domain_link|business_process|business_object)(_|$)';
DELETE FROM system_dict_type WHERE type ~ '^modeling_(concept|biz_theme|theme_plan|theme_rel|model_check|check_result|environment|subject_domain_link|business_process|business_object)(_|$)';

DO $retire$
DECLARE table_name text; count_rows bigint; counts jsonb:='{}'; sources jsonb:='[]'; col text;
BEGIN
    IF EXISTS(SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='MODEL_SIMPLIFICATION_V1' AND phase='CLEANED') THEN RETURN; END IF;
    IF EXISTS(SELECT 1 FROM information_schema.columns c WHERE c.table_schema='datahub-center' AND c.table_name='dh_modeling_logic_model' AND c.column_name='concept_entity_id') THEN
        EXECUTE 'SELECT COALESCE(jsonb_agg(jsonb_build_object(''logicModelId'',id,''tenantId'',tenant_id,''conceptEntityId'',concept_entity_id) ORDER BY tenant_id,id),''[]''::jsonb) FROM dh_modeling_logic_model WHERE concept_entity_id IS NOT NULL' INTO sources;
    END IF;
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_concept_sync_record','dh_modeling_concept_logic_sync','dh_modeling_concept_model_version',
        'dh_modeling_concept_relation','dh_modeling_concept_entity','dh_modeling_concept_model','dh_modeling_subject_domain_link',
        'dh_modeling_theme_rel','dh_modeling_theme_plan','dh_modeling_biz_theme','dh_modeling_biz_category_data_domain_rel',
        'dh_modeling_environment_target','dh_modeling_model_check_result','dh_modeling_model_check_config','dh_modeling_model_check','dh_modeling_schema_baseline',
        'dh_modeling_collaborator','dh_modeling_collaboration','dh_modeling_approval','dh_modeling_design_report','dh_modeling_inbox','dh_modeling_reference_receipt','dh_modeling_object_change',
        'dh_modeling_business_object_external_ref','dh_modeling_business_object_process_rel','dh_modeling_business_object_attribute','dh_modeling_business_object_version','dh_modeling_business_object',
        'dh_modeling_subject_domain_process_rel','dh_modeling_business_process_supporting_domain_rel','dh_modeling_business_process_domain_candidate',
        'dh_modeling_business_process_data_domain_rel','dh_modeling_business_process'] LOOP
        IF to_regclass(format('%I.%I','datahub-center',table_name)) IS NOT NULL THEN
            EXECUTE format('LOCK TABLE %I IN ACCESS EXCLUSIVE MODE',table_name);
            EXECUTE format('SELECT count(*) FROM %I',table_name) INTO count_rows;
            counts:=counts||jsonb_build_object(table_name,count_rows);
            EXECUTE format('DROP TABLE %I',table_name);
        END IF;
        EXECUTE format('DROP SEQUENCE IF EXISTS %I',table_name||'_seq');
    END LOOP;
    UPDATE modeling_simplify_context SET evidence=evidence||jsonb_build_object('removedTableCounts',counts,'legacyConceptSources',sources);
    FOREACH col IN ARRAY ARRAY['theme_id','concept_entity_id','business_process_id'] LOOP
        EXECUTE format('ALTER TABLE dh_modeling_logic_model DROP COLUMN IF EXISTS %I',col);
    END LOOP;
    FOREACH col IN ARRAY ARRAY['theme_id','name','code','description','model_style','warehouse_layer','layer_id','subject_domain_id','business_process_id','data_domain_id','table_type','classification_status'] LOOP
        EXECUTE format('ALTER TABLE dh_modeling_physical_model DROP COLUMN IF EXISTS %I',col);
    END LOOP;
END $retire$;
DROP FUNCTION IF EXISTS dh_modeling_unification_acl(bigint,text,bigint,text);
DROP FUNCTION IF EXISTS dh_modeling_confirm_unification(bigint,bigint,jsonb);
DROP FUNCTION IF EXISTS dh_modeling_approval_freeze_guard();
DROP FUNCTION IF EXISTS dh_modeling_approval_snapshot_immutable();
DROP FUNCTION IF EXISTS dh_modeling_design_report_immutable();

CREATE OR REPLACE FUNCTION dh_modeling_simplification_evidence_guard() RETURNS trigger LANGUAGE plpgsql AS $guard$
BEGIN
    IF TG_OP='TRUNCATE' THEN RAISE EXCEPTION '原始迁移证据不可修改或清空'; END IF;
    IF OLD.migration_key IN('MODEL_SIMPLIFICATION_V1','EMPTY_MODEL_FINALIZATION_V1') THEN
        RAISE EXCEPTION '已完成精简或空模型恢复的原始迁移证据不可修改或删除';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW;
END $guard$;
COMMENT ON FUNCTION dh_modeling_simplification_evidence_guard() IS '保护本次原始基线和精简证据，不允许重放覆盖';
DROP TRIGGER IF EXISTS modeling_simplification_evidence_guard ON dh_modeling_unification_state;
CREATE TRIGGER modeling_simplification_evidence_guard BEFORE UPDATE OR DELETE ON dh_modeling_unification_state FOR EACH ROW EXECUTE FUNCTION dh_modeling_simplification_evidence_guard();
DROP TRIGGER IF EXISTS modeling_simplification_evidence_truncate_guard ON dh_modeling_unification_state;
CREATE TRIGGER modeling_simplification_evidence_truncate_guard BEFORE TRUNCATE ON dh_modeling_unification_state FOR EACH STATEMENT EXECUTE FUNCTION dh_modeling_simplification_evidence_guard();

INSERT INTO dh_modeling_unification_state(migration_key,phase,operator_name,migration_evidence)
    SELECT 'EMPTY_MODEL_FINALIZATION_V1','CLEANED',current_user,jsonb_build_object('designRowsVerifiedEmpty',true,'performedBy','0131',
        'retainedOrphanDeploymentCount',evidence->'retainedOrphanDeploymentCount')
    FROM modeling_simplify_context WHERE empty_recovery ON CONFLICT(migration_key) DO NOTHING;
INSERT INTO dh_modeling_unification_state(migration_key,phase,operator_name,migration_evidence)
    SELECT 'MODEL_SIMPLIFICATION_V1','CLEANED',current_user,evidence FROM modeling_simplify_context ON CONFLICT(migration_key) DO NOTHING;

DO $final$
DECLARE table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_logic_model','dh_modeling_logic_model_version','dh_modeling_logic_relation','dh_modeling_physical_model','dh_modeling_physical_model_version','dh_modeling_deploy_record',
        'dh_modeling_biz_category','dh_modeling_data_domain','dh_modeling_dw_layer','dh_modeling_subject_domain','dh_modeling_planning_change',
        'dh_modeling_legacy_adaptation_run','dh_modeling_legacy_adaptation_backup','dh_modeling_legacy_adaptation_issue','dh_modeling_unification_state','dh_modeling_unification_map','dh_modeling_unified_menu_backup','dh_modeling_workspace_removal_archive'] LOOP
        IF to_regclass(format('%I.%I','datahub-center',table_name)) IS NULL THEN RAISE EXCEPTION '最终保留表缺失：%',table_name; END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='datahub-center' AND tablename LIKE 'dh_modeling_%' AND tablename NOT IN(
        'dh_modeling_logic_model','dh_modeling_logic_model_version','dh_modeling_logic_relation','dh_modeling_physical_model','dh_modeling_physical_model_version','dh_modeling_deploy_record',
        'dh_modeling_biz_category','dh_modeling_data_domain','dh_modeling_dw_layer','dh_modeling_subject_domain','dh_modeling_planning_change',
        'dh_modeling_legacy_adaptation_run','dh_modeling_legacy_adaptation_backup','dh_modeling_legacy_adaptation_issue','dh_modeling_unification_state','dh_modeling_unification_map','dh_modeling_unified_menu_backup','dh_modeling_workspace_removal_archive')) THEN
        RAISE EXCEPTION '仍有未识别的建模业务表，未按名称猜测删除，须核查额外结构';
    END IF;
    IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='datahub-center' AND p.prokind='f'
        AND p.prosrc ~ 'dh_modeling_(concept_|model_check|biz_theme|theme_plan|theme_rel|subject_domain_link|environment_target)') THEN
        RAISE EXCEPTION '仍有数据库函数引用退役表，须补齐实际守卫变更';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM dh_modeling_unification_state WHERE migration_key='MODEL_SIMPLIFICATION_V1' AND phase='CLEANED'
        AND migration_evidence ? 'legacyBaselines') THEN RAISE EXCEPTION '最终迁移证据不完整，整笔回滚'; END IF;
END $final$;
COMMIT;
SELECT migration_key AS "迁移阶段",phase AS "状态",migration_evidence->'baselineMergeSummary' AS "旧基线合并摘要"
FROM "datahub-center".dh_modeling_unification_state WHERE migration_key IN('MODEL_SIMPLIFICATION_V1','EMPTY_MODEL_FINALIZATION_V1');

-- 新库数据源密码密文扩容；已有库执行0132编号增量。
-- Migration: 0132 扩容数据源密码密文存储
-- Purpose: 将数据源密码密文列由定长上限字符类型扩为文本，避免AES加密及Base64编码后长度超过50导致创建或更新失败。
-- Depends on: 0131_modeling_simplify-design-deploy.sql 对应平台状态；dh_dataforge_database及password列已存在。
-- Target: 已有PostgreSQL平台库；新库使用包含本迁移的datahub-center.sql。
-- Repeatable: 是；重复转换为text及设置相同注释不会改写密文值。
-- Rollback: 失败整笔回滚；提交后可保留text供旧应用读取。不得截断回退；若确需缩容，应先证明全部密文长度满足旧限制。
-- 仅扩容平台存储列，不重新加密、不输出密码或密钥，不改变任何外部数据源。
-- ALTER TABLE需要短暂排他锁，锁等待超过10秒则整笔失败，适合维护窗口执行。
BEGIN;
SET LOCAL lock_timeout='10s';

ALTER TABLE "datahub-center".dh_dataforge_database
    ALTER COLUMN password TYPE text;
COMMENT ON COLUMN "datahub-center".dh_dataforge_database.password
    IS '数据库密码密文（使用secret_key进行AES加密并Base64编码）；文本列避免密文膨胀造成截断';

COMMIT;

-- 新库删除建模规划引用与影响审计；已有库执行0133编号增量。
-- Migration: 0133 删除建模规划引用与影响审计
-- Purpose: 下线建模「引用与影响」功能：移除业务分类、数据域、主题域、数仓分层上的规划审计触发器、审计函数及 dh_modeling_planning_change 表与序列。
-- Depends on: 0131_modeling_simplify-design-deploy.sql 对应平台状态（规划审计触发器挂在四张规划表上）；0132_dataforge_database-password-ciphertext.sql 已执行。
-- Target: 已有PostgreSQL平台库；新库使用包含本迁移的datahub-center.sql。
-- Repeatable: 是；全部使用 IF EXISTS，重复执行无副作用。
-- Rollback: 失败整笔回滚；提交后审计记录不可恢复，如需保留请先备份 dh_modeling_planning_change。应用侧须同时升级到不再调用 /modeling/planning 的版本。
-- 删除前序必须是触发器→函数→表→序列，否则四张规划表的写入会因审计函数引用不存在的表而失败。
-- 保留 modeling_ownership_reference_guard、trg_modeling_layer_change 等引用校验触发器，不在本迁移范围内。
BEGIN;
SET LOCAL lock_timeout='10s';

DROP TRIGGER IF EXISTS trg_modeling_planning_audit ON "datahub-center".dh_modeling_biz_category;
DROP TRIGGER IF EXISTS trg_modeling_planning_audit ON "datahub-center".dh_modeling_data_domain;
DROP TRIGGER IF EXISTS trg_modeling_planning_audit ON "datahub-center".dh_modeling_subject_domain;
DROP TRIGGER IF EXISTS trg_modeling_planning_audit ON "datahub-center".dh_modeling_dw_layer;
DROP FUNCTION IF EXISTS "datahub-center".modeling_audit_planning_change();
DROP TABLE IF EXISTS "datahub-center".dh_modeling_planning_change;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_planning_change_seq;

COMMIT;
-- 0139: design check removed; a fresh database does not keep the model check tables.
DROP TABLE IF EXISTS "datahub-center".dh_modeling_model_check_result;
DROP TABLE IF EXISTS "datahub-center".dh_modeling_model_check;
DROP TABLE IF EXISTS "datahub-center".dh_modeling_model_check_config;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_model_check_result_seq;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_model_check_seq;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_model_check_config_seq;

-- 新库同步建模迁移 0134 至 0144，已有数据库按编号升级，不重复导入全量基线。

-- 新库最终状态来源：0134_modeling_drop-migration-evidence.sql
-- Migration: 0134 删除建模历史迁移证据/备份表（7 张）
-- Status: 产品认删 + 架构认草稿（2026-10-10）；合环境前必须先 pg_dump
-- Purpose: 清理 0131 白名单保留的历史迁移证据表；非日常业务查询入口。
-- Depends on: 0133_modeling_drop-planning-change.sql 已执行；
--   且 dh_modeling_unification_state 中 MODEL_SIMPLIFICATION_V1.phase = CLEANED。
-- Target: schema "datahub-center"（PostgreSQL）
-- Repeatable: 是（IF EXISTS）；重复执行无副作用。
-- Rollback: 提交后不可脚本回滚；删前请 pg_dump 留底（尤其 unification_state）。
-- 明确不删: dh_dataforge_etl_archive / _action、dh_supply_legacy_admin_disposal、
--   dh_modeling_physical_model_version、dh_modeling_design_report 等业务表。
--
-- 删前建议（人工）:
--   pg_dump -n "datahub-center" -t "datahub-center.dh_modeling_unification_state" \
--     -t "datahub-center.dh_modeling_unification_map" \
--     -t "datahub-center.dh_modeling_legacy_adaptation_run" \
--     -t "datahub-center.dh_modeling_legacy_adaptation_backup" \
--     -t "datahub-center.dh_modeling_legacy_adaptation_issue" \
--     -t "datahub-center.dh_modeling_unified_menu_backup" \
--     -t "datahub-center.dh_modeling_workspace_removal_archive" \
--     -f backup_0134_modeling_evidence_$(date +%Y%m%d).sql

BEGIN;
SET LOCAL search_path TO "datahub-center", public;
SET LOCAL lock_timeout = '10s';

-- 门禁：未 CLEANED 则拒绝删证据表
DO $gate$
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM "datahub-center".dh_modeling_unification_state
        WHERE migration_key = 'MODEL_SIMPLIFICATION_V1'
          AND phase = 'CLEANED'
    ) THEN
        RAISE EXCEPTION '0134 拒绝执行：MODEL_SIMPLIFICATION_V1 未处于 CLEANED，禁止删除迁移证据表';
    END IF;
END $gate$;

-- unification_state 上有 0131 证据保护触发器，须先卸再 DROP
DROP TRIGGER IF EXISTS modeling_simplification_evidence_guard
    ON "datahub-center".dh_modeling_unification_state;
DROP TRIGGER IF EXISTS modeling_simplification_evidence_truncate_guard
    ON "datahub-center".dh_modeling_unification_state;
DROP FUNCTION IF EXISTS "datahub-center".dh_modeling_simplification_evidence_guard();

