  "sort" int DEFAULT NULL,
  "comment" varchar(1000) DEFAULT NULL,
  "remark" varchar(512) DEFAULT NULL,
  "agg_type" varchar(64) DEFAULT NULL,
  "standard_id" bigint DEFAULT NULL,
  "standard_code" varchar(128) DEFAULT NULL,
  "standard_name" varchar(256) DEFAULT NULL,
  "standard_column_type" varchar(128) DEFAULT NULL,
  "creator" varchar(64) DEFAULT '',
  "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updater" varchar(64) DEFAULT '',
  "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "deleted" smallint NOT NULL DEFAULT 0,
  "tenant_id" bigint NOT NULL DEFAULT 0,
  CONSTRAINT "dh_modeling_logic_model_column_pkey" PRIMARY KEY ("id")
);

-- 表说明（原文）：数据建模-逻辑模型字段（真相源；版本表 fields 仅作历史快照）
COMMENT ON TABLE "datahub-center"."dh_modeling_logic_model_column" IS '数据建模-逻辑模型字段';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."model_id" IS '逻辑模型编号';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."field_uid" IS '字段稳定标识（= ModelFieldItem.fieldUid）';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."source_attr_uid" IS '历史来源属性稳定标识';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."field_name" IS '字段英文名';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."cn_name" IS '字段中文名';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."pk_flag" IS '是否主键：1/0';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."nullable_flag" IS '是否可空：1=可空 0=非空';
COMMENT ON COLUMN "datahub-center"."dh_modeling_logic_model_column"."standard_id" IS '关联数据标准编号';

CREATE UNIQUE INDEX IF NOT EXISTS "uk_dh_modeling_logic_model_column_uid"
  ON "datahub-center"."dh_modeling_logic_model_column" ("tenant_id", "model_id", "field_uid")
  WHERE "deleted" = 0;

CREATE INDEX IF NOT EXISTS "idx_dh_modeling_logic_model_column_model"
  ON "datahub-center"."dh_modeling_logic_model_column" ("tenant_id", "model_id")
  WHERE "deleted" = 0;

-- 幂等回填：先软删未删行，再按「优先 PUBLISHED 最新，否则 version 最大」解析 fields JSON 插入
UPDATE "datahub-center"."dh_modeling_logic_model_column"
SET "deleted" = 1, "update_time" = CURRENT_TIMESTAMP
WHERE "deleted" = 0;

WITH picked_version AS (
  SELECT DISTINCT ON (v."model_id")
         v."model_id",
         v."tenant_id",
         v."fields",
         v."creator",
         v."updater"
  FROM "datahub-center"."dh_modeling_logic_model_version" v
  WHERE v."deleted" = 0
    AND v."fields" IS NOT NULL
    AND NULLIF(BTRIM(v."fields"::text), '') IS NOT NULL
    AND NULLIF(BTRIM(v."fields"::text), 'null') IS NOT NULL
    AND NULLIF(BTRIM(v."fields"::text), '[]') IS NOT NULL
  ORDER BY v."model_id",
           CASE WHEN v."status" = 'PUBLISHED' THEN 0 ELSE 1 END,
           v."version" DESC,
           v."id" DESC
),
expanded AS (
  SELECT
    p."model_id",
    p."tenant_id",
    p."creator",
    p."updater",
    elem AS "elem",
    ord AS "ord",
    NULLIF(BTRIM(elem->>'fieldUid'), '') AS "raw_field_uid",
    NULLIF(BTRIM(elem->>'fieldName'), '') AS "field_name",
    NULLIF(BTRIM(elem->>'dataType'), '') AS "data_type"
  FROM picked_version p
  CROSS JOIN LATERAL jsonb_array_elements(
    CASE
      WHEN jsonb_typeof(p."fields"::jsonb) = 'array' THEN p."fields"::jsonb
      ELSE '[]'::jsonb
    END
  ) WITH ORDINALITY AS t(elem, ord)
),
deduped AS (
  SELECT DISTINCT ON (e."tenant_id", e."model_id", COALESCE(e."raw_field_uid", e."field_name", e."ord"::text))
         e.*
  FROM expanded e
  WHERE e."field_name" IS NOT NULL
    AND e."data_type" IS NOT NULL
  ORDER BY e."tenant_id", e."model_id",
           COALESCE(e."raw_field_uid", e."field_name", e."ord"::text),
           e."ord"
)
INSERT INTO "datahub-center"."dh_modeling_logic_model_column" (
  "model_id", "field_uid", "source_attr_uid", "field_name", "cn_name", "data_type",
  "data_length", "data_precision", "data_scale", "data_format", "measure_unit",
  "value_range", "default_value", "pk_flag", "nullable_flag", "sort", "comment", "remark",
  "agg_type", "standard_id", "standard_code", "standard_name", "standard_column_type",
  "creator", "create_time", "updater", "update_time", "deleted", "tenant_id"
)
SELECT
  d."model_id",
  COALESCE(d."raw_field_uid", replace(gen_random_uuid()::text, '-', '')),
  NULLIF(BTRIM(d."elem"->>'sourceAttrUid'), ''),
  d."field_name",
  NULLIF(BTRIM(d."elem"->>'cnName'), ''),
  d."data_type",
  CASE WHEN (d."elem"->>'dataLength') ~ '^-?[0-9]+$' THEN (d."elem"->>'dataLength')::int ELSE NULL END,
  CASE WHEN (d."elem"->>'dataPrecision') ~ '^-?[0-9]+$' THEN (d."elem"->>'dataPrecision')::int ELSE NULL END,
  CASE WHEN (d."elem"->>'dataScale') ~ '^-?[0-9]+$' THEN (d."elem"->>'dataScale')::int ELSE NULL END,
  NULLIF(BTRIM(d."elem"->>'dataFormat'), ''),
  NULLIF(BTRIM(d."elem"->>'measureUnit'), ''),
  NULLIF(BTRIM(d."elem"->>'valueRange'), ''),
  NULLIF(BTRIM(d."elem"->>'defaultValue'), ''),
  CASE
    WHEN lower(COALESCE(d."elem"->>'pkFlag', 'false')) IN ('true', '1', 't', 'yes') THEN 1
    ELSE 0
  END,
  CASE
    WHEN lower(COALESCE(d."elem"->>'nullableFlag', 'true')) IN ('false', '0', 'f', 'no') THEN 0
    ELSE 1
  END,
  CASE
    WHEN (d."elem"->>'sort') ~ '^-?[0-9]+$' THEN (d."elem"->>'sort')::int
    ELSE d."ord"::int
  END,
  NULLIF(BTRIM(d."elem"->>'comment'), ''),
  NULLIF(BTRIM(d."elem"->>'remark'), ''),
  NULLIF(BTRIM(d."elem"->>'aggType'), ''),
  CASE WHEN (d."elem"->>'standardId') ~ '^[0-9]+$' THEN (d."elem"->>'standardId')::bigint ELSE NULL END,
  NULLIF(BTRIM(d."elem"->>'standardCode'), ''),
  NULLIF(BTRIM(d."elem"->>'standardName'), ''),
  NULLIF(BTRIM(d."elem"->>'standardColumnType'), ''),
  COALESCE(d."creator", ''),
  CURRENT_TIMESTAMP,
  COALESCE(d."updater", ''),
  CURRENT_TIMESTAMP,
  0,
  COALESCE(d."tenant_id", 0)
FROM deduped d;

COMMIT;


-- 新库最终状态来源：0143_modeling_drop-physical-menu.sql
-- Migration: 0143 删除物理模型菜单
-- Purpose: 清理物理模型菜单与权限；删除前后端物理模型代码后的配套。不 DROP 物理表（留给 0144）
-- Depends on: 0142_modeling_logic-model-column.sql
-- Target: schema datahub-center（不要对生产库直接执行；执行前 LI 先备份）
-- Repeatable: yes; DELETE 匹配 0 行可重跑
-- Rollback: 需从备份恢复 system_menu / system_role_menu

BEGIN;
SET LOCAL search_path TO "datahub-center", public;

-- 角色菜单：物理模型菜单及其按钮
DELETE FROM system_role_menu
WHERE menu_id IN (
    SELECT id FROM system_menu
    WHERE deleted = 0
      AND (
        trim(both '/' from coalesce(component, '')) = 'modeling/physicalmodel/index'
        OR path IN ('physical-model', '/modeling/physical-model')
        OR component_name = 'ModelingPhysicalModel'
        OR (type = 2 AND name = '物理模型' AND path = 'physical-model')
      )
);

-- 子权限（挂在物理模型菜单下的按钮）先删子再删父
DELETE FROM system_menu
WHERE parent_id IN (
    SELECT id FROM system_menu
    WHERE deleted = 0
      AND (
        trim(both '/' from coalesce(component, '')) = 'modeling/physicalmodel/index'
        OR component_name = 'ModelingPhysicalModel'
        OR (type = 2 AND name = '物理模型' AND path = 'physical-model')
      )
);

DELETE FROM system_menu
WHERE deleted = 0
  AND (
    trim(both '/' from coalesce(component, '')) = 'modeling/physicalmodel/index'
    OR path IN ('physical-model')
    OR component_name = 'ModelingPhysicalModel'
    OR (type = 2 AND name = '物理模型' AND path = 'physical-model')
  );

-- 不 DROP dh_modeling_physical_model / dh_modeling_physical_model_version（P3/0144）

COMMIT;


-- 新库最终状态来源：0144_modeling_drop-physical-tables.sql
-- Migration: 0144 删除已退役的物理模型与版本表
-- Purpose: 完成物理模型下线，删除两张平台表、专属序列与守卫函数，清理残留菜单、角色授权及租户套餐菜单引用。
-- Depends on: 0143_modeling_drop-physical-menu.sql 已执行；0140 的物化发布表与 0142 的逻辑模型字段表已存在，应用已停止使用物理模型接口。
-- Target: 已有 PostgreSQL 平台库，固定 schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；对象使用 IF EXISTS，菜单清理只处理仍存在的退役记录，重放不修改保留记录。
-- Rollback: 失败整笔回滚；提交后两表数据、序列状态与授权不可恢复，须从执行前的独立备份恢复。执行前停止旧应用并备份两表及菜单、角色授权、租户套餐。
-- DROP TABLE 需要排他锁，超过十秒即失败；不使用级联删除，未知外键、视图或函数依赖会阻止整笔提交。
-- 仅删除平台的旧物理模型元数据，不操作任何已发布模型对应的外部数据源表。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

-- 明确核对新发布链路前置结构，避免在旧平台状态下直接删掉唯一的模型定义。
DO $preflight$
BEGIN
    IF to_regclass('"datahub-center".dh_modeling_logic_model') IS NULL
       OR to_regclass('"datahub-center".dh_modeling_logic_model_version') IS NULL
       OR to_regclass('"datahub-center".dh_modeling_logic_model_column') IS NULL
       OR to_regclass('"datahub-center".dh_modeling_model_materialized') IS NULL
       OR to_regclass('"datahub-center".dh_modeling_model_materialized_log') IS NULL THEN
        RAISE EXCEPTION '0144 前置结构缺失：须先完成逻辑模型字段与物化发布迁移';
    END IF;
END $preflight$;

-- 不按共享的 modeling:model:* 权限删除；这些权限仍属于逻辑模型。
CREATE TEMPORARY TABLE modeling_0144_retired_menus (id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO modeling_0144_retired_menus (id)
SELECT id FROM system_menu
WHERE trim(both '/' from coalesce(component, '')) = 'modeling/physicalmodel/index'
   OR component_name = 'ModelingPhysicalModel'
   OR (type = 2 AND trim(both '/' from coalesce(path, '')) IN ('physical-model', 'modeling/physical-model'))
   OR permission LIKE 'modeling:physical-model:%';

WITH RECURSIVE buttons (id) AS (
    SELECT id FROM modeling_0144_retired_menus
    UNION
    SELECT child.id FROM system_menu child JOIN buttons parent ON child.parent_id = parent.id
    WHERE child.type = 3
)
INSERT INTO modeling_0144_retired_menus (id)
SELECT id FROM buttons ON CONFLICT (id) DO NOTHING;

DO $menu_preflight$
BEGIN
    IF EXISTS (
        SELECT 1 FROM system_menu child JOIN modeling_0144_retired_menus parent ON child.parent_id = parent.id
        WHERE NOT EXISTS (SELECT 1 FROM modeling_0144_retired_menus retired WHERE retired.id = child.id)
    ) THEN
        RAISE EXCEPTION '0144 退役菜单仍挂有其他页面或目录，禁止连带删除';
    END IF;
END $menu_preflight$;

-- 同时处理软删除菜单；保留套餐中其他菜单的值类型和顺序。
UPDATE system_tenant_package package
SET menu_ids = (
        SELECT coalesce(jsonb_agg(entry.value ORDER BY entry.ordinality), '[]'::jsonb)::text
        FROM jsonb_array_elements(package.menu_ids::jsonb) WITH ORDINALITY entry(value, ordinality)
        WHERE NOT EXISTS (
            SELECT 1 FROM modeling_0144_retired_menus retired WHERE retired.id::text = entry.value #>> '{}'
        )
    ),
    updater = 'migration:0144', update_time = CURRENT_TIMESTAMP
WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
    JOIN modeling_0144_retired_menus retired ON retired.id::text = entry.value
);
DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM modeling_0144_retired_menus);
DELETE FROM system_menu WHERE id IN (SELECT id FROM modeling_0144_retired_menus);

-- 先删版本表再删模型头；两表自有触发器、索引及约束随表删除。
DROP TABLE IF EXISTS "datahub-center".dh_modeling_physical_model_version;
DROP TABLE IF EXISTS "datahub-center".dh_modeling_physical_model;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_physical_model_version_seq;
DROP SEQUENCE IF EXISTS "datahub-center".dh_modeling_physical_model_seq;
DROP FUNCTION IF EXISTS "datahub-center".dh_modeling_unified_version_guard();
DROP FUNCTION IF EXISTS "datahub-center".dh_modeling_unified_binding_guard();

-- 拒绝残留函数引用；未知自定义依赖必须单独评估，不能静默保留一个运行时报错的函数。
DO $postflight$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_proc function JOIN pg_namespace namespace ON namespace.oid = function.pronamespace
        WHERE namespace.nspname = 'datahub-center'
          AND function.prokind IN ('f', 'p')
          AND function.prosrc ~ '\mdh_modeling_physical_model(_version)?\M'
    ) THEN
        RAISE EXCEPTION '0144 仍有函数引用退役物理模型表，整笔回滚；请核对自定义依赖';
    END IF;
END $postflight$;
COMMIT;




