-- 复合引用保证模型与域、规则和变更账本处于同一租户；已有模型回填后再建立约束。
DO $model_constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_master_model_domain' AND conrelid = 'dh_governance_master_model'::regclass) THEN
        ALTER TABLE dh_governance_master_model ADD CONSTRAINT fk_master_model_domain
            FOREIGN KEY (tenant_id, domain_id) REFERENCES dh_governance_master_domain (tenant_id, id);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_master_model_status' AND conrelid = 'dh_governance_master_model'::regclass) THEN
        ALTER TABLE dh_governance_master_model ADD CONSTRAINT ck_master_model_status CHECK (status IN (0, 1, 2));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_master_model_version' AND conrelid = 'dh_governance_master_model'::regclass) THEN
        ALTER TABLE dh_governance_master_model ADD CONSTRAINT ck_master_model_version CHECK (version > 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'ck_master_model_publish_state' AND conrelid = 'dh_governance_master_model'::regclass) THEN
        ALTER TABLE dh_governance_master_model ADD CONSTRAINT ck_master_model_publish_state CHECK (publish_state IN ('READY', 'APPLYING', 'UNKNOWN'));
    END IF;
END $model_constraints$;

-- 沿用原模型菜单编号和授权，按实际父菜单补齐新页面，避免固定编号碰撞。
DO $menu_preflight$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE type = 2 AND deleted = 0 AND trim(both '/' from coalesce(component, '')) = 'governance/masterdata/index') THEN
        RAISE EXCEPTION '0150 缺少主数据模型菜单，请先完成当前平台基线或等价升级';
    END IF;
END $menu_preflight$;
LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
SELECT setval('"datahub-center".system_menu_id_seq',
              greatest((SELECT last_value FROM "datahub-center".system_menu_id_seq), coalesce((SELECT max(id) FROM system_menu), 1)), true);

UPDATE system_menu SET name = '主数据模型', sort = 2, updater = 'migration:0150', update_time = CURRENT_TIMESTAMP
WHERE type = 2 AND deleted = 0 AND trim(both '/' from coalesce(component, '')) = 'governance/masterdata/index';
UPDATE system_menu SET sort = 7, updater = 'migration:0150', update_time = CURRENT_TIMESTAMP
WHERE type = 2 AND deleted = 0 AND trim(both '/' from coalesce(component, '')) = 'governance/masterdistribute/index';

INSERT INTO system_menu (name, permission, type, sort, parent_id, path, icon, component, component_name, status, creator, updater)
SELECT page.name, page.permission, 2, page.sort, model.parent_id, page.path, page.icon, page.component, page.component_name, 0, 'migration:0150', 'migration:0150'
FROM (VALUES
    ('主数据域', 'governance:master-domain:query', 1, 'masterdomain', 'carbon:folder', 'governance/masterdomain/index', 'GovernanceMasterDomain'),
    ('主数据维护', 'governance:master-data:query', 3, 'mastermaintain', 'carbon:data-table', 'governance/mastermaintain/index', 'GovernanceMasterMaintain'),
    ('编码规则', 'governance:master-code-rule:query', 4, 'mastercoderule', 'carbon:barcode', 'governance/mastercoderule/index', 'GovernanceMasterCodeRule'),
    ('主数据审批', 'governance:master-approval:query', 5, 'masterapproval', 'carbon:task-approved', 'governance/masterapproval/index', 'GovernanceMasterApproval'),
    ('变更日志', 'governance:master-change-log:query', 6, 'masterchangelog', 'carbon:change-catalog', 'governance/masterchangelog/index', 'GovernanceMasterChangeLog')
) page(name, permission, sort, path, icon, component, component_name)
JOIN LATERAL (SELECT parent_id FROM system_menu WHERE type = 2 AND deleted = 0 AND trim(both '/' from coalesce(component, '')) = 'governance/masterdata/index' ORDER BY id LIMIT 1) model ON true
WHERE NOT EXISTS (SELECT 1 FROM system_menu existing WHERE existing.type = 2 AND existing.deleted = 0 AND trim(both '/' from coalesce(existing.component, '')) = page.component);

-- 数据按钮移到维护页面，保留原编号及权限；不改已有角色菜单关系。
UPDATE system_menu button SET parent_id = page.id, updater = 'migration:0150', update_time = CURRENT_TIMESTAMP
FROM system_menu page
WHERE page.type = 2 AND page.deleted = 0 AND trim(both '/' from coalesce(page.component, '')) = 'governance/mastermaintain/index'
  AND button.type = 3 AND button.deleted = 0 AND button.permission IN ('governance:master-data:query', 'governance:master-data:create', 'governance:master-data:update', 'governance:master-data:delete');

INSERT INTO system_menu (name, permission, type, sort, parent_id, status, creator, updater)
SELECT button.name, button.permission, 3, button.sort, page.id, 0, 'migration:0150', 'migration:0150'
FROM (VALUES
    ('主数据域新增', 'governance:master-domain:create', 1, 'governance/masterdomain/index'),
    ('主数据域修改', 'governance:master-domain:update', 2, 'governance/masterdomain/index'),
    ('主数据域删除', 'governance:master-domain:delete', 3, 'governance/masterdomain/index'),
    ('编码规则新增', 'governance:master-code-rule:create', 1, 'governance/mastercoderule/index'),
    ('编码规则修改', 'governance:master-code-rule:update', 2, 'governance/mastercoderule/index'),
    ('编码规则删除', 'governance:master-code-rule:delete', 3, 'governance/mastercoderule/index'),
    ('审批通过', 'governance:master-approval:approve', 1, 'governance/masterapproval/index'),
    ('审批驳回', 'governance:master-approval:reject', 2, 'governance/masterapproval/index'),
    ('审批流程对账', 'governance:master-approval:reconcile', 3, 'governance/masterapproval/index'),
    ('数据变更结果核查', 'governance:master-approval:resolve', 4, 'governance/masterapproval/index')
) button(name, permission, sort, component)
JOIN system_menu page ON page.type = 2 AND page.deleted = 0 AND trim(both '/' from coalesce(page.component, '')) = button.component
WHERE NOT EXISTS (SELECT 1 FROM system_menu existing WHERE existing.deleted = 0 AND existing.permission = button.permission);

COMMIT;

-- Migration: 0152 调用记录合并写操作台账页签
-- Purpose: 将写操作查询和核查权限移到调用记录，删除独立台账入口；原有业务权限、核查记录和操作账本保持不变。
-- Depends on: 0151_asset_catalog-delivery-removal.sql 已执行，或等价完整平台状态；调用记录菜单及开放写操作查询、核查权限已存在。
-- Target: 已有 PostgreSQL 平台库，固定结构为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；只在原入口仍绑定日志查询权限时迁移该授权，重放不会向仅有合并入口的角色或套餐授予日志查询权限。
-- Rollback: 失败整笔回滚，序列已取值可能留下间隔；提交后须从执行前备份恢复菜单、角色菜单及租户套餐，并回退前端页面。
-- 执行前备份上述权限表并停止旧应用实例；迁移后刷新系统权限缓存并重新登录。事务内菜单锁等待超过十秒即失败。
-- 本迁移只删除独立菜单和该菜单的角色关联，不删除写操作账本、核查证据或查询与核查权限，也不自动扩大业务权限。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $merge_operation_tabs$
DECLARE
    log_menu system_menu%ROWTYPE;
    query_menu bigint;
    matches integer;
    query_was_on_page boolean;
    retired_ids bigint[];
    active_retired_ids bigint[];
    operation_permission_ids bigint[];
    role_grant record;
    package record;
    entries jsonb;
    next_entries jsonb;
    original_log_entry jsonb;
    operation_entry jsonb;
BEGIN
    SELECT count(*) INTO matches FROM system_menu
    WHERE deleted = 0 AND type = 2 AND trim(both '/' from coalesce(component, '')) = 'supply/apilog/index';
    IF matches <> 1 THEN RAISE EXCEPTION '0152 需要唯一有效的调用记录菜单'; END IF;
    SELECT * INTO log_menu FROM system_menu
    WHERE deleted = 0 AND type = 2 AND trim(both '/' from coalesce(component, '')) = 'supply/apilog/index';
    IF log_menu.status <> 0 OR log_menu.permission NOT IN ('', 'supply:api-log:query') THEN
        RAISE EXCEPTION '0152 调用记录菜单已停用或绑定了其他权限，禁止自动覆盖';
    END IF;
    query_was_on_page := log_menu.permission = 'supply:api-log:query';

    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]),
           coalesce(array_agg(id) FILTER (WHERE deleted = 0 AND status = 0), ARRAY[]::bigint[])
    INTO retired_ids, active_retired_ids FROM system_menu
    WHERE trim(both '/' from coalesce(component, '')) = 'supply/operation/index'
       OR component_name = 'SupplyWriteOperation';
    IF cardinality(active_retired_ids) > 1 OR EXISTS (
        SELECT 1 FROM system_menu WHERE id = ANY(retired_ids)
        AND (type <> 2 OR deleted <> 0 OR status <> 0 OR parent_id <> log_menu.parent_id OR permission <> '')
    ) THEN RAISE EXCEPTION '0152 写操作台账菜单重复或归属冲突'; END IF;
    IF EXISTS (
        SELECT 1 FROM system_menu WHERE parent_id = ANY(retired_ids)
        AND (type <> 3 OR permission NOT IN ('supply:data-api:operation-query', 'supply:data-api:operation-resolve'))
    ) THEN RAISE EXCEPTION '0152 台账菜单下存在其他页面或权限，禁止连带删除'; END IF;

    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO operation_permission_ids FROM system_menu
    WHERE deleted = 0 AND type = 3 AND permission IN ('supply:data-api:operation-query', 'supply:data-api:operation-resolve');
    IF cardinality(operation_permission_ids) <> 2 OR EXISTS (
        SELECT 1 FROM system_menu WHERE id = ANY(operation_permission_ids)
        AND parent_id <> log_menu.id AND NOT (parent_id = ANY(retired_ids))
    ) THEN RAISE EXCEPTION '0152 缺少台账查询、核查权限或权限归属冲突'; END IF;
    IF EXISTS (
        SELECT 1 FROM system_menu WHERE deleted = 0
        AND permission IN ('supply:data-api:operation-query', 'supply:data-api:operation-resolve')
        GROUP BY permission HAVING count(*) <> 1
    ) THEN RAISE EXCEPTION '0152 台账权限重复'; END IF;

    SELECT count(*), min(id) INTO matches, query_menu FROM system_menu
    WHERE id <> log_menu.id AND permission = 'supply:api-log:query';
    IF matches > 1 OR (matches = 1 AND NOT EXISTS (
        SELECT 1 FROM system_menu WHERE id = query_menu AND type = 3 AND deleted = 0 AND parent_id = log_menu.id
        AND (NOT query_was_on_page OR status = 0)
    )) THEN RAISE EXCEPTION '0152 日志查询子权限重复或归属冲突'; END IF;
    IF matches = 0 AND NOT query_was_on_page THEN
        RAISE EXCEPTION '0152 合并入口缺少日志查询子权限，禁止猜测授权';
    END IF;

    -- 同步数据库默认序列和应用使用的序列，避免新菜单及角色关联编号碰撞。
    PERFORM setval('system_menu_id_seq', greatest((SELECT last_value FROM system_menu_id_seq), coalesce((SELECT max(id) FROM system_menu), 1)), true);
    PERFORM setval('system_menu_seq', greatest((SELECT last_value FROM system_menu_seq), coalesce((SELECT max(id) FROM system_menu), 1)), true);
    PERFORM setval('system_role_menu_seq', greatest((SELECT last_value FROM system_role_menu_seq), coalesce((SELECT max(id) FROM system_role_menu), 1)), true);
    IF query_menu IS NULL THEN
        INSERT INTO system_menu (name, permission, type, sort, parent_id, creator, updater)
        VALUES ('查询调用日志', 'supply:api-log:query', 3, 0, log_menu.id, 'migration:0152', 'migration:0152')
        RETURNING id INTO query_menu;
    END IF;
    PERFORM setval('system_menu_seq', greatest((SELECT last_value FROM system_menu_seq), coalesce((SELECT max(id) FROM system_menu), 1)), true);

    -- 先继承原日志查询授权，再合并台账入口；两个页签的查询权限继续独立。
    IF query_was_on_page THEN
        FOR role_grant IN SELECT DISTINCT role_id, tenant_id FROM system_role_menu
            WHERE menu_id = log_menu.id AND deleted = 0
        LOOP
            IF NOT EXISTS (SELECT 1 FROM system_role_menu WHERE role_id = role_grant.role_id
                AND tenant_id = role_grant.tenant_id AND menu_id = query_menu AND deleted = 0) THEN
                INSERT INTO system_role_menu (id, role_id, menu_id, tenant_id, creator, updater)
                VALUES (nextval('system_role_menu_seq'), role_grant.role_id, query_menu, role_grant.tenant_id, 'migration:0152', 'migration:0152');
            END IF;
        END LOOP;
    END IF;
    FOR role_grant IN SELECT DISTINCT role_id, tenant_id FROM system_role_menu
        WHERE deleted = 0 AND (menu_id = ANY(active_retired_ids) OR menu_id IN (
            SELECT id FROM system_menu WHERE id = ANY(operation_permission_ids) AND status = 0
        ))
    LOOP
        IF NOT EXISTS (SELECT 1 FROM system_role_menu WHERE role_id = role_grant.role_id
            AND tenant_id = role_grant.tenant_id AND menu_id = log_menu.id AND deleted = 0) THEN
            INSERT INTO system_role_menu (id, role_id, menu_id, tenant_id, creator, updater)
            VALUES (nextval('system_role_menu_seq'), role_grant.role_id, log_menu.id, role_grant.tenant_id, 'migration:0152', 'migration:0152');
        END IF;
    END LOOP;

    -- 套餐仅替换入口并继承原日志权限；保留其他编号的顺序及数字、字符串类型。
    FOR package IN SELECT id, menu_ids FROM system_tenant_package LOOP
        entries := package.menu_ids::jsonb;
        original_log_entry := NULL;
        operation_entry := NULL;
        SELECT value INTO original_log_entry FROM jsonb_array_elements(entries) WITH ORDINALITY entry(value, ordinal)
        WHERE value #>> '{}' = log_menu.id::text ORDER BY ordinal LIMIT 1;
        SELECT value INTO operation_entry FROM jsonb_array_elements(entries) WITH ORDINALITY entry(value, ordinal)
        WHERE value #>> '{}' IN (SELECT id::text FROM unnest(active_retired_ids || operation_permission_ids) id)
        ORDER BY ordinal LIMIT 1;

        SELECT coalesce(jsonb_agg(value ORDER BY ordinal), '[]'::jsonb) INTO next_entries
        FROM jsonb_array_elements(entries) WITH ORDINALITY entry(value, ordinal)
        WHERE value #>> '{}' NOT IN (SELECT id::text FROM unnest(retired_ids) id);
        IF original_log_entry IS NULL AND operation_entry IS NOT NULL THEN
            next_entries := next_entries || jsonb_build_array(CASE WHEN jsonb_typeof(operation_entry) = 'string'
                THEN to_jsonb(log_menu.id::text) ELSE to_jsonb(log_menu.id) END);
        END IF;
        IF query_was_on_page AND original_log_entry IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(next_entries) entry(value) WHERE value #>> '{}' = query_menu::text
        ) THEN
            next_entries := next_entries || jsonb_build_array(CASE WHEN jsonb_typeof(original_log_entry) = 'string'
                THEN to_jsonb(query_menu::text) ELSE to_jsonb(query_menu) END);
        END IF;
        IF next_entries IS DISTINCT FROM entries THEN
            UPDATE system_tenant_package SET menu_ids = next_entries::text,
                updater = 'migration:0152', update_time = CURRENT_TIMESTAMP WHERE id = package.id;
        END IF;
    END LOOP;

    UPDATE system_menu SET permission = '', updater = 'migration:0152', update_time = CURRENT_TIMESTAMP
    WHERE id = log_menu.id AND permission <> '';
    UPDATE system_menu SET parent_id = log_menu.id, updater = 'migration:0152', update_time = CURRENT_TIMESTAMP
    WHERE parent_id = ANY(retired_ids) AND type = 3
      AND permission IN ('supply:data-api:operation-query', 'supply:data-api:operation-resolve');
    DELETE FROM system_role_menu WHERE menu_id = ANY(retired_ids);
    DELETE FROM system_menu WHERE id = ANY(retired_ids);
END $merge_operation_tabs$;

COMMIT;

-- Migration: 0153 主数据域业务字段对齐
-- Purpose: 主数据域独立存储，补齐与数据域一致的负责人及备注字段；0154 已移除范围说明。
-- Depends on: 0152_supply_api-log-operation-tabs.sql 已执行；0150 已建立主数据域表及模型归属约束。
-- Target: 已有 PostgreSQL 平台库，固定结构为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；新增列按存在性处理，重放仅更新字段注释，不覆盖已有业务值。
-- Rollback: 失败整笔回滚；提交后回退应用可保留新增可空列。删除新增列前须备份对应业务值。
-- 加列会短时锁表；等待超过十秒或执行超过两分钟则回滚。不复制数据域记录，不指定历史域负责人。
-- 保留现有编码长度、图标、排序、历史目录编号及模型引用；不修改租户隔离、唯一约束和菜单权限。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_governance_master_domain
    ADD COLUMN IF NOT EXISTS leader_user_id bigint,
    ADD COLUMN IF NOT EXISTS leader_phone varchar(20),
    ADD COLUMN IF NOT EXISTS remark varchar(500);

COMMENT ON COLUMN dh_governance_master_domain.leader_user_id IS '负责人用户编号';
COMMENT ON COLUMN dh_governance_master_domain.leader_phone IS '负责人电话';
COMMENT ON COLUMN dh_governance_master_domain.remark IS '备注';

COMMIT;

-- Migration: 0154 删除数据域及主数据域的范围说明字段
-- Purpose: 删除两域的责任部门、包含范围、排除范围列，与前后端域管理字段同步。
-- Depends on: 0153_governance_master-domain-parity.sql 已执行；两域表已建立。
-- Target: 已有 PostgreSQL 平台库，结构为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；仅删除仍存在的列，重复执行不修改剩余业务数据。
-- Rollback: 事务失败整笔回滚；提交后须从执行前备份恢复三列及原值，脚本不能恢复已删除内容。
-- 不可逆变更：永久删除两表这三列的业务值。执行前备份两表，先部署对应新版本并停止旧版本写入。
-- 删除列会短时锁表；锁等待超过十秒或执行超过两分钟则回滚，不级联删除任何依赖对象。
-- 保留负责人、电话、备注、租户、审计记录、模型归属及现有约束和索引。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_modeling_data_domain
    DROP COLUMN IF EXISTS owner_department,
    DROP COLUMN IF EXISTS scope_includes,
    DROP COLUMN IF EXISTS scope_excludes;

ALTER TABLE dh_governance_master_domain
    DROP COLUMN IF EXISTS owner_department,
    DROP COLUMN IF EXISTS scope_includes,
    DROP COLUMN IF EXISTS scope_excludes;

COMMIT;

-- Migration: 0156 数据库运行监控、采样与告警
-- Purpose: 增加逐租户分钟采样、数据库告警规则和可审计处置记录；复用现有数据库查询与更新权限。
-- Depends on: 0155_dataforge_remove-data-explore.sql 已执行，或平台达到对应状态；数据库、同步执行和开发执行表已存在。
-- Target: 已有 PostgreSQL 平台库，固定 schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；表、序列和索引均使用存在性保护，不重置已有采样、规则和告警。
-- Rollback: 失败整笔回滚；提交后先停用 databaseMonitorCollectJob 并回退应用，再备份并删除本迁移新增的三张表及其序列。
-- 加法式变更，不删除现有数据；采样保留三十五天，告警处置记录不自动删除。数据库告警不发送外部通知。
-- 仅创建平台存储，不连接外部数据库，也不修改外部 XXL-Job 管理库；调度建议每分钟执行。
-- 历史执行表新增查询索引会在建索引期间阻止写入；建议低峰执行，十秒锁等待和两分钟语句超时失败后整笔回滚。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_database_sample_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_database_sample (
    id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_database_sample_seq'),
    database_id bigint NOT NULL,
    slot_time timestamp NOT NULL,
    collected_time timestamp,
    state varchar(16) NOT NULL DEFAULT 'COLLECTING' CHECK (state IN ('COLLECTING','COMPLETE','DISCARDED')),
    lease_token varchar(36) NOT NULL,
    lease_until timestamp NOT NULL,
    connection_status integer CHECK (connection_status IN (0,1,2)),
    collection_status varchar(16) CHECK (collection_status IN ('SUCCESS','FAILED','UNSUPPORTED')),
    collection_message varchar(200),
    response_time_ms bigint CHECK (response_time_ms >= 0),
    capacity_used varchar(32) CHECK (capacity_used ~ '^[0-9]+$'),
    creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT now(),
    updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT now(),
    deleted smallint NOT NULL DEFAULT 0, tenant_id bigint NOT NULL,
    CONSTRAINT uk_database_sample_slot UNIQUE (tenant_id, database_id, slot_time)
);
CREATE INDEX IF NOT EXISTS idx_database_sample_trend ON dh_dataforge_database_sample (tenant_id,database_id,collected_time DESC) WHERE state='COMPLETE' AND deleted=0;
COMMENT ON TABLE dh_dataforge_database_sample IS '数据库监控-采样记录';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_database_alarm_rule_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_database_alarm_rule (
    id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_database_alarm_rule_seq'),
    database_id bigint NOT NULL,
    name varchar(100) NOT NULL,
    description varchar(500) NOT NULL DEFAULT '',
    metric varchar(32) NOT NULL CHECK (metric IN ('CONNECTION_STATUS','RESPONSE_TIME')),
    operator varchar(8) NOT NULL CHECK (operator IN ('EQ','GT','GTE','LT','LTE')),
    threshold varchar(32) NOT NULL CHECK (threshold ~ '^[0-9]{1,12}([.][0-9]{1,6})?$'),
    level varchar(16) NOT NULL CHECK (level IN ('GENERAL','SERIOUS','URGENT')),
    status integer NOT NULL DEFAULT 0 CHECK (status IN (0,1)),
    owner varchar(100) NOT NULL,
    creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT now(),
    updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT now(),
    deleted smallint NOT NULL DEFAULT 0, tenant_id bigint NOT NULL,
    CONSTRAINT ck_database_alarm_threshold CHECK (
        (metric='CONNECTION_STATUS' AND operator='EQ' AND threshold::numeric=0)
        OR (metric='RESPONSE_TIME' AND threshold::numeric>0))
);
CREATE INDEX IF NOT EXISTS idx_database_alarm_rule_scope ON dh_dataforge_database_alarm_rule (tenant_id,database_id,status) WHERE deleted=0;
COMMENT ON TABLE dh_dataforge_database_alarm_rule IS '数据库监控-告警规则';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_database_alarm_record_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_database_alarm_record (
    id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_database_alarm_record_seq'),
    database_id bigint NOT NULL,
    rule_id bigint NOT NULL,
    rule_name varchar(100) NOT NULL,
    description varchar(500) NOT NULL DEFAULT '',
    metric varchar(32) NOT NULL,
    operator varchar(8) NOT NULL,
    threshold varchar(32) NOT NULL,
    current_value varchar(32) NOT NULL,
    level varchar(16) NOT NULL CHECK (level IN ('GENERAL','SERIOUS','URGENT')),
    status varchar(16) NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','HANDLED','IGNORED')),
    first_time timestamp NOT NULL,
    last_time timestamp NOT NULL,
    occurrences integer NOT NULL DEFAULT 1 CHECK (occurrences>0),
    handled_by varchar(64), handled_time timestamp, handle_remark varchar(500),
    creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT now(),
    updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT now(),
    deleted smallint NOT NULL DEFAULT 0, tenant_id bigint NOT NULL,
    CONSTRAINT ck_database_alarm_disposition CHECK (status='PENDING' OR (handled_by IS NOT NULL AND handled_time IS NOT NULL AND length(trim(handle_remark))>0))
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_database_alarm_pending ON dh_dataforge_database_alarm_record (tenant_id,database_id,rule_id) WHERE status='PENDING' AND deleted=0;
CREATE INDEX IF NOT EXISTS idx_database_alarm_record_scope ON dh_dataforge_database_alarm_record (tenant_id,database_id,last_time DESC) WHERE deleted=0;
COMMENT ON TABLE dh_dataforge_database_alarm_record IS '数据库监控-告警记录';

CREATE INDEX IF NOT EXISTS idx_database_monitor_access_source ON dh_dataforge_access_task (tenant_id,(config_json->>'sourceDatabaseId'),create_time DESC) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_database_monitor_access_target ON dh_dataforge_access_task (tenant_id,(config_json->>'targetDatabaseId'),create_time DESC) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_database_monitor_dev_scope ON dh_dataforge_dev_record (tenant_id,database_id,create_time DESC) WHERE deleted=0;

-- 三张表的公共字段和业务字段逐项中文注释；重放仅修正说明，不更新业务数据。
DO $comments$
DECLARE
    v_table_name text;
    v_column_name text;
    label text;
BEGIN
    FOREACH v_table_name IN ARRAY ARRAY['dh_dataforge_database_sample','dh_dataforge_database_alarm_rule','dh_dataforge_database_alarm_record'] LOOP
        FOR v_column_name,label IN SELECT * FROM (VALUES
          ('id','主键编号'),('database_id','本租户数据库编号'),('tenant_id','租户编号'),
          ('creator','创建人编号'),('create_time','创建时间'),('updater','更新人编号'),('update_time','更新时间'),('deleted','逻辑删除标记'),
          ('slot_time','分钟采样槽，租户与数据库内唯一'),('collected_time','采样时间'),('state','采样状态：采集中、完成或已废弃'),
          ('lease_token','采集租约令牌，旧执行结果不能覆盖新令牌'),('lease_until','采集租约截止时间'),
          ('connection_status','连接状态：零未知、一在线、二离线'),('collection_status','采集结果：成功、失败或不支持'),('collection_message','固定脱敏采集结果说明'),
          ('response_time_ms','连接建立并完成探活查询的耗时毫秒'),('capacity_used','数据库已用字节十进制字符串，未知为空'),
          ('name','规则名称'),('description','业务说明'),('metric','告警指标：连接状态或响应时间'),('operator','阈值比较运算符'),
          ('threshold','精确阈值十进制字符串，连接断开为零，响应时间单位毫秒'),('level','告警级别：一般、严重、紧急'),
          ('status','规则零启用一停用；告警待处理、已处理或已忽略'),('owner','负责人文字说明，不隐含通知授权'),
          ('rule_id','规则编号，删除规则后保留告警历史'),('rule_name','最近触发时规则名称快照'),('current_value','最近触发采样值十进制字符串'),
          ('first_time','首次触发时间'),('last_time','最近触发时间'),('occurrences','未处置期间触发次数'),
          ('handled_by','处置人编号'),('handled_time','处置时间'),('handle_remark','处置原因')
        ) AS descriptions(column_key,column_label) LOOP
            IF EXISTS (SELECT 1 FROM information_schema.columns c WHERE c.table_schema='datahub-center' AND c.table_name=v_table_name AND c.column_name=v_column_name) THEN
                EXECUTE format('COMMENT ON COLUMN %I.%I IS %L',v_table_name,v_column_name,label);
            END IF;
        END LOOP;
    END LOOP;
END $comments$;

COMMIT;

-- 同步 0158：接口配置归属任务和节点，清理独立管理入口。
-- Migration: 0158 退役独立接口管理，接口配置归属采集任务和 ETL 节点。
-- Purpose: 删除旧独立 API 定义表和序列，清理旧菜单、角色授权与套餐引用，更新 API 输入组件说明。
-- Depends on: 0157_asset_governance-terms.sql 已执行，或已核验平台达到对应状态；系统菜单、角色菜单、租户套餐和 ETL 工具表已存在。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；旧独立 API 定义已由用户确认为可删除的测试数据。新库使用包含本迁移的全量基线。
-- Repeatable: 是；目标菜单按功能标识定位，表和序列使用 IF EXISTS，工具说明仅在发生变化时更新。
-- Rollback: 失败整笔回滚；提交后旧 API 测试记录不可恢复。如需回滚，先从执行前备份恢复定义表、序列、菜单授权、套餐引用和工具说明，再恢复旧应用版本。
-- 不可逆操作：直接删除旧独立 API 定义表中的全部测试数据，包括逻辑删除记录；采集任务、运行记录、逐表执行结果及 Supply API 服务不受影响。
-- 删除表获取排他锁，菜单与授权清理期间阻止并发写入；锁等待超过十秒或语句执行超过两分钟即回滚。不使用 CASCADE，存在未预期依赖时拒绝执行。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMPORARY TABLE dataforge_0158_retired_menus (id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO dataforge_0158_retired_menus (id)
SELECT id FROM system_menu
WHERE permission LIKE 'dataforge:data-api:%'
   OR trim(both '/' from coalesce(component, '')) = 'dataforge/dataapi/index'
   OR component_name = 'DataforgeDataApi';

-- 补齐页面下无权限码的专用按钮；存在其他功能子项时拒绝连带清理。
WITH RECURSIVE buttons (id) AS (
    SELECT id FROM dataforge_0158_retired_menus
    UNION
    SELECT child.id FROM system_menu child JOIN buttons parent ON child.parent_id = parent.id
    WHERE child.type = 3 AND coalesce(child.permission, '') = ''
)
INSERT INTO dataforge_0158_retired_menus (id)
SELECT id FROM buttons ON CONFLICT (id) DO NOTHING;

DO $menu_preflight$
BEGIN
    IF EXISTS (
        SELECT 1 FROM system_menu child JOIN dataforge_0158_retired_menus parent ON child.parent_id = parent.id
        WHERE NOT EXISTS (SELECT 1 FROM dataforge_0158_retired_menus retired WHERE retired.id = child.id)
    ) THEN
        RAISE EXCEPTION '0158 旧 API 管理页面下存在其他功能子项，禁止连带删除';
    END IF;
END $menu_preflight$;

-- 保留其余套餐条目的顺序和数字或字符串类型；拼接紧凑 JSON，避免超过 menu_ids 长度限制。
UPDATE system_tenant_package package
SET menu_ids = (
        SELECT '[' || coalesce(string_agg(entry.value::text, ',' ORDER BY entry.ordinality), '') || ']'
        FROM jsonb_array_elements(package.menu_ids::jsonb) WITH ORDINALITY entry(value, ordinality)
        WHERE NOT EXISTS (
            SELECT 1 FROM dataforge_0158_retired_menus retired WHERE retired.id::text = entry.value #>> '{}'
        )
    ),
    updater = 'migration:0158', update_time = CURRENT_TIMESTAMP
WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
    JOIN dataforge_0158_retired_menus retired ON retired.id::text = entry.value
);

DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM dataforge_0158_retired_menus);
DELETE FROM system_menu WHERE id IN (SELECT id FROM dataforge_0158_retired_menus);

UPDATE dh_dataforge_etl_tool
SET description = '在节点中独立配置 HTTP 接口、测试请求并解析返回字段，支持分页拉取',
    updater = 'migration:0158', update_time = CURRENT_TIMESTAMP
WHERE code = 'rest-api'
  AND description IS DISTINCT FROM '在节点中独立配置 HTTP 接口、测试请求并解析返回字段，支持分页拉取';

-- 接口定义已经随采集任务和 ETL 节点保存；直接清理确认可删除的旧测试数据。
DROP TABLE IF EXISTS "datahub-center".dh_dataforge_api;
DROP SEQUENCE IF EXISTS "datahub-center".dh_dataforge_api_seq;

COMMIT;

-- Migration: 0160 删除数据交换功能。
-- Purpose: 删除交换契约、交换任务和交付批次表及序列，清理交换菜单、角色授权、租户套餐引用及平台旧调度配置和日志。
-- Depends on: 0159_dataforge_table-comments.sql 已执行，或已核验平台达到对应状态；系统菜单、角色菜单和租户套餐表已存在。
-- Target: 已有 PostgreSQL 平台库，固定 schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；按功能标识定位菜单，表与序列使用 IF EXISTS，重复执行不会修改同步和推送配置。
-- Rollback: 失败整笔回滚；提交后交换契约、任务、交付历史不可恢复，须从执行前备份恢复专属表、序列、菜单授权、套餐及旧调度配置和日志，并恢复对应应用版本。
-- 不可逆操作：永久删除全部数据交换记录，包括逻辑删除记录。执行前备份上述对象，停止所有旧版交换执行实例，并停用 XXL-Job 的 dataforgeExchangeJob。
-- 仅清理平台自身配置；外部 XXL-Job 管理库中的任务须在部署时停用，本脚本不连接或修改该管理库。
-- 删除表获取排他锁；菜单授权清理期间阻止并发写入。锁等待超过十秒或语句执行超过两分钟则回滚。
-- 不使用级联删除；发现其他功能菜单子项或数据库依赖时拒绝执行，避免连带删除。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMPORARY TABLE dataforge_0160_retired_menus (id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO dataforge_0160_retired_menus (id)
SELECT menu.id FROM system_menu menu
WHERE permission LIKE 'dataforge:exchange-%'
   OR trim(both '/' from coalesce(component, '')) = 'dataforge/exchange'
   OR trim(both '/' from coalesce(component, '')) LIKE 'dataforge/exchange/%'
   OR component_name LIKE 'DataforgeExchange%'
   OR (type = 1 AND name = '数据交换'
       AND trim(both '/' from coalesce(path, '')) = 'exchange');

-- 补齐专属页面下无权限码的按钮；逻辑删除菜单也必须清理，避免残留授权。
WITH RECURSIVE buttons (id) AS (
    SELECT id FROM dataforge_0160_retired_menus
    UNION
    SELECT child.id FROM system_menu child JOIN buttons parent ON child.parent_id = parent.id
    WHERE child.type = 3 AND coalesce(child.permission, '') = ''
)
INSERT INTO dataforge_0160_retired_menus (id)
SELECT id FROM buttons ON CONFLICT (id) DO NOTHING;

DO $menu_preflight$
BEGIN
    IF EXISTS (
        SELECT 1 FROM system_menu child JOIN dataforge_0160_retired_menus parent ON child.parent_id = parent.id
        WHERE NOT EXISTS (SELECT 1 FROM dataforge_0160_retired_menus retired WHERE retired.id = child.id)
    ) THEN
        RAISE EXCEPTION '0160 数据交换菜单下存在其他功能子项，禁止连带删除';
    END IF;
END $menu_preflight$;

-- 仅移除目标菜单编号，保留其他套餐条目的顺序和数字或字符串类型。
-- 拼接紧凑 JSON，避免序列化增加分隔空格而超过 menu_ids 的长度限制。
UPDATE system_tenant_package package
SET menu_ids = (
        SELECT '[' || coalesce(string_agg(entry.value::text, ',' ORDER BY entry.ordinality), '') || ']'
        FROM jsonb_array_elements(package.menu_ids::jsonb) WITH ORDINALITY entry(value, ordinality)
        WHERE NOT EXISTS (
            SELECT 1 FROM dataforge_0160_retired_menus retired WHERE retired.id::text = entry.value #>> '{}'
        )
    ),
    updater = 'migration:0160', update_time = CURRENT_TIMESTAMP
WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
    JOIN dataforge_0160_retired_menus retired ON retired.id::text = entry.value
);

DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM dataforge_0160_retired_menus);
DELETE FROM system_menu WHERE id IN (SELECT id FROM dataforge_0160_retired_menus);

-- 清理平台中可能保留的旧调度配置，保留同步、推送及其他任务。
DO $legacy_jobs$
BEGIN
    IF to_regclass('"datahub-center".infra_job_log') IS NOT NULL THEN
        DELETE FROM infra_job_log WHERE handler_name = 'dataforgeExchangeJob';
    END IF;
    IF to_regclass('"datahub-center".infra_job') IS NOT NULL THEN
        DELETE FROM infra_job WHERE handler_name = 'dataforgeExchangeJob';
    END IF;
END $legacy_jobs$;

-- 先删除交付批次，再删除任务与契约；外部依赖会使整笔事务失败。
DROP TABLE IF EXISTS "datahub-center".dh_dataforge_exchange_delivery;
DROP TABLE IF EXISTS "datahub-center".dh_dataforge_exchange_job;
DROP TABLE IF EXISTS "datahub-center".dh_dataforge_exchange_contract;

DROP SEQUENCE IF EXISTS "datahub-center".dh_dataforge_exchange_delivery_seq;
DROP SEQUENCE IF EXISTS "datahub-center".dh_dataforge_exchange_job_seq;
DROP SEQUENCE IF EXISTS "datahub-center".dh_dataforge_exchange_contract_seq;

COMMIT;

-- Migration: 0163 数据开发保存即生效，退役独立草稿发布阶段。
-- Purpose: 将发布版本指针改为当前保存版本指针，合并旧发布授权至既有保存权限；保留历史版本、运行记录及原始快照。
-- Depends on: 0162_dataforge_task-monitor-drawers.sql 已执行，或已核验平台达到对应状态；数据开发任务、版本、运行记录和系统权限表已存在。
-- Target: 已有 PostgreSQL 平台库，固定 schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；只允许旧指针列或新指针列之一存在，权限按唯一有效保存按钮定位，已退役的发布引用不会再次合并。
-- Rollback: 失败整笔回滚；提交后须先停新版应用，从执行前备份恢复发布菜单、角色与套餐引用，并将 current_version_id 改回 published_version_id 后回退应用。新版产生的保存版本不得删除，历史数据不自动逆向转换。
-- 风险：列重命名取得任务表排他锁，权限清理会删除旧发布菜单及引用。升级前停止旧执行与调度节点并备份；锁等待超过十秒或单语句超过两分钟则回滚，升级后刷新权限缓存并重新登录。
-- 旧指针原值保持不变，只表示此前已授权的冻结版本；未发布的旧定义不会被本脚本激活，首次保存由服务重新校验并冻结完整定义。
-- 不启用管理员已停用的按钮或套餐，不继承已停用发布按钮的授权，不增加运行、原生执行或 Schema 执行权限。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

DO $definition_preflight$
DECLARE
    old_pointer boolean;
    new_pointer boolean;
BEGIN
    IF to_regclass('"datahub-center".dh_dataforge_dev_task') IS NULL
       OR to_regclass('"datahub-center".dh_dataforge_dev_task_version') IS NULL
       OR to_regclass('"datahub-center".dh_dataforge_dev_record') IS NULL THEN
        RAISE EXCEPTION '0163 数据开发任务、历史版本或运行记录前置表缺失';
    END IF;
    SELECT EXISTS (SELECT 1 FROM pg_attribute
        WHERE attrelid = 'dh_dataforge_dev_task'::regclass AND attname = 'published_version_id' AND NOT attisdropped)
        INTO old_pointer;
    SELECT EXISTS (SELECT 1 FROM pg_attribute
        WHERE attrelid = 'dh_dataforge_dev_task'::regclass AND attname = 'current_version_id' AND NOT attisdropped)
        INTO new_pointer;
    IF old_pointer = new_pointer THEN
        RAISE EXCEPTION '0163 任务版本指针缺失或旧新列并存，禁止推断并覆盖';
    END IF;
    IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_dataforge_dev_task'::regclass
        AND attname IN ('published_version_id', 'current_version_id') AND NOT attisdropped
        AND atttypid <> 'bigint'::regtype)
       OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_dataforge_dev_task'::regclass
           AND attname = 'revision' AND NOT attisdropped AND atttypid = 'integer'::regtype)
       OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_dataforge_dev_task_version'::regclass
           AND attname = 'snapshot_json' AND NOT attisdropped AND atttypid = 'jsonb'::regtype)
       OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_dataforge_dev_record'::regclass
           AND attname = 'version_id' AND NOT attisdropped AND atttypid = 'bigint'::regtype) THEN
        RAISE EXCEPTION '0163 任务修订号、版本指针或历史快照字段与前置契约不一致';
    END IF;
    IF old_pointer THEN
        ALTER TABLE dh_dataforge_dev_task RENAME COLUMN published_version_id TO current_version_id;
    END IF;
END $definition_preflight$;

COMMENT ON COLUMN dh_dataforge_dev_task.current_version_id IS '当前已校验保存版本编号；旧指针保留此前已授权的冻结版本';
COMMENT ON COLUMN dh_dataforge_dev_task.revision IS '任务定义乐观锁修订号';
COMMENT ON COLUMN dh_dataforge_dev_task_version.snapshot_json IS '不可变保存快照及冻结的上游版本；历史快照原文保留';
COMMENT ON COLUMN dh_dataforge_dev_record.version_id IS '实际执行的保存版本；历史运行仍关联原冻结版本';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMPORARY TABLE dataforge_0163_retired_publish (id bigint PRIMARY KEY, inherit_grants boolean NOT NULL) ON COMMIT DROP;
INSERT INTO dataforge_0163_retired_publish (id, inherit_grants)
SELECT id, deleted = 0 AND status = 0 FROM system_menu WHERE permission = 'dataforge:dev-task:publish';

DO $retire_publish$
DECLARE
    save_menu system_menu%ROWTYPE;
    publish_menu system_menu%ROWTYPE;
    matches integer;
    package record;
    entries jsonb;
    next_entries text;
    first_inherited_ordinal bigint;
    save_present boolean;
BEGIN
    SELECT count(*) INTO matches FROM system_menu WHERE deleted = 0 AND permission = 'dataforge:dev-task:save';
    IF matches <> 1 THEN
        RAISE EXCEPTION '0163 需要唯一有效的既有任务保存权限，禁止创建或选择冲突权限';
    END IF;
    SELECT * INTO save_menu FROM system_menu WHERE deleted = 0 AND permission = 'dataforge:dev-task:save';
    IF save_menu.type <> 3 THEN
        RAISE EXCEPTION '0163 保存权限不是既有按钮，禁止覆盖其他入口';
    END IF;
    SELECT count(*) INTO matches FROM system_menu WHERE deleted = 0 AND permission = 'dataforge:dev-task:publish';
    IF matches > 1 THEN
        RAISE EXCEPTION '0163 有效任务发布权限重复，须先核对授权来源';
    END IF;
    IF matches = 1 THEN
        SELECT * INTO publish_menu FROM system_menu WHERE deleted = 0 AND permission = 'dataforge:dev-task:publish';
        IF publish_menu.type <> 3 OR publish_menu.parent_id <> save_menu.parent_id THEN
            RAISE EXCEPTION '0163 发布与保存按钮归属冲突，禁止跨入口合并';
        END IF;
    END IF;
    IF EXISTS (SELECT 1 FROM system_menu child JOIN dataforge_0163_retired_publish retired ON retired.id = child.parent_id) THEN
        RAISE EXCEPTION '0163 发布按钮仍挂有子项，禁止连带删除';
    END IF;

    -- 复用原授权行编号，不分配序列；同租户同角色已有保存授权时直接保留已有授权。
    UPDATE system_role_menu grant_row
    SET menu_id = save_menu.id, updater = 'migration:0163', update_time = CURRENT_TIMESTAMP
    WHERE grant_row.id IN (
        SELECT min(source.id) FROM system_role_menu source
        JOIN dataforge_0163_retired_publish retired ON retired.id = source.menu_id AND retired.inherit_grants
        WHERE source.deleted = 0 AND NOT EXISTS (
            SELECT 1 FROM system_role_menu existing WHERE existing.tenant_id = source.tenant_id
                AND existing.role_id = source.role_id AND existing.menu_id = save_menu.id AND existing.deleted = 0
        )
        GROUP BY source.tenant_id, source.role_id
    );

    -- 在原位置替换首个有效发布条目；数字和字符串类型、其他条目及顺序保持不变，已有保存条目不重复追加。
    FOR package IN SELECT id, menu_ids FROM system_tenant_package
    WHERE EXISTS (SELECT 1 FROM jsonb_array_elements(menu_ids::jsonb) entry(value)
        JOIN dataforge_0163_retired_publish retired ON retired.id::text = entry.value #>> '{}')
    LOOP
        entries := package.menu_ids::jsonb;
        SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(entries) entry(value)
            WHERE entry.value #>> '{}' = save_menu.id::text) INTO save_present;
        SELECT min(entry.ordinality) INTO first_inherited_ordinal
        FROM jsonb_array_elements(entries) WITH ORDINALITY entry(value, ordinality)
        JOIN dataforge_0163_retired_publish retired ON retired.id::text = entry.value #>> '{}' AND retired.inherit_grants;

        SELECT '[' || coalesce(string_agg(value::text, ',' ORDER BY ordinality), '') || ']' INTO next_entries
        FROM (
            SELECT entry.ordinality, CASE
                WHEN retired.id IS NOT NULL THEN CASE WHEN jsonb_typeof(entry.value) = 'string'
                    THEN to_jsonb(save_menu.id::text) ELSE to_jsonb(save_menu.id) END
                ELSE entry.value END AS value
            FROM jsonb_array_elements(entries) WITH ORDINALITY entry(value, ordinality)
            LEFT JOIN dataforge_0163_retired_publish retired ON retired.id::text = entry.value #>> '{}'
            WHERE retired.id IS NULL OR (NOT save_present AND entry.ordinality = first_inherited_ordinal)
        ) replacement;
        UPDATE system_tenant_package SET menu_ids = next_entries,
            updater = 'migration:0163', update_time = CURRENT_TIMESTAMP
        WHERE id = package.id AND menu_ids IS DISTINCT FROM next_entries;
    END LOOP;

    DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM dataforge_0163_retired_publish);
    DELETE FROM system_menu WHERE id IN (SELECT id FROM dataforge_0163_retired_publish);
END $retire_publish$;

COMMIT;

-- Migration: 0164 数据开发周期触发改由 DolphinScheduler 维护。
-- Purpose: 建立调度绑定、租约和同步状态台账，切换任务调度枚举；停用旧 XXL 周期触发并备份旧 Cron，保留历史版本及运行快照。
-- Depends on: 0163_dataforge_dev-task-direct-save.sql 已执行，或已核验平台达到对应状态；数据开发任务、历史版本和运行记录表存在，已停旧执行和调度节点。
-- Target: 已有 PostgreSQL 平台库，固定 schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；新表和索引按存在性创建，验证已有表契约；只切换仍标识 XXL_JOB 的任务，重放不关闭新版已登记的调度。
-- Rollback: 失败整笔回滚；提交后回退前先通过新版关闭已登记的 DolphinScheduler 外部调度并核对在途实例，再恢复执行前任务和枚举约束备份。绑定台账及历史记录应保留，不能仅回退数据库列而遗留外部周期触发。
-- 风险：任务枚举修改获取短时排他锁，旧周期任务升级后保持关闭，管理员须核对 Quartz Cron、可信执行身份与引擎档案后重新启用。锁等待超过十秒或单语句超过两分钟则整笔回滚。
-- 不在 SQL 中创建、删除或上线外部调度，不把旧 Spring Cron 直接视为已登记的 Quartz Cron；调度登记、取消、未知结果和触发导入由维护任务对账。
-- 不修改历史版本、运行记录或 JSON 原文，不新增运行、原生执行、保存或调度权限。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

DO $schedule_preflight$
DECLARE
    scheduler_check text;
BEGIN
    IF to_regclass('"datahub-center".dh_dataforge_dev_task') IS NULL
       OR to_regclass('"datahub-center".dh_dataforge_dev_task_version') IS NULL
       OR to_regclass('"datahub-center".dh_dataforge_dev_record') IS NULL THEN
        RAISE EXCEPTION '0164 缺少数据开发任务、历史版本或运行记录前置表';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_dataforge_dev_task'::regclass
        AND attname = 'current_version_id' AND NOT attisdropped AND atttypid = 'bigint'::regtype) THEN
        RAISE EXCEPTION '0164 缺少当前保存版本指针，须先完成 0163';
    END IF;
    SELECT pg_get_expr(conbin, conrelid) INTO scheduler_check FROM pg_constraint
    WHERE conrelid = 'dh_dataforge_dev_task'::regclass AND conname = 'ck_dataforge_dev_scheduler' AND contype = 'c';
    IF scheduler_check IS NULL OR scheduler_check NOT IN (
        '((scheduler)::text = ''XXL_JOB''::text)', '((scheduler)::text = ''DOLPHIN_SCHEDULER''::text)') THEN
        RAISE EXCEPTION '0164 调度枚举约束缺失或含未知定制规则，禁止静默覆盖';
    END IF;
    IF EXISTS (SELECT 1 FROM dh_dataforge_dev_task WHERE scheduler IS NULL
        OR scheduler NOT IN ('XXL_JOB', 'DOLPHIN_SCHEDULER')) THEN
        RAISE EXCEPTION '0164 存在未知任务调度系统，须先核对迁移来源';
    END IF;
END $schedule_preflight$;

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_dev_schedule_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_dev_schedule (
    id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_dev_schedule_seq'::regclass),
    tenant_id bigint NOT NULL,
    task_id bigint NOT NULL,
    version_id bigint NOT NULL,
    generation integer NOT NULL,
    cron_expression varchar(100) NOT NULL,
    ds_project_code bigint NOT NULL,
    worker_group varchar(100) NOT NULL,
    tenant_code varchar(100) NOT NULL,
    timezone_id varchar(64) NOT NULL DEFAULT 'Asia/Shanghai',
    desired_enabled boolean NOT NULL DEFAULT false,
    synced_enabled boolean NOT NULL DEFAULT false,
    ds_workflow_code bigint,
    ds_schedule_id integer,
    sync_status varchar(24) NOT NULL DEFAULT 'PENDING',
    attempts integer NOT NULL DEFAULT 0,
    lease_owner varchar(64),
    lease_until timestamp,
    last_error varchar(1000),
    last_ds_instance_id bigint NOT NULL DEFAULT 0,
    poll_end_time timestamp,
    poll_page_no integer NOT NULL DEFAULT 1,
    poll_high_water_id bigint NOT NULL DEFAULT 0,
    last_poll_time timestamp,
    schedule_start_time timestamp NOT NULL,
    creator varchar(64) DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT ck_dataforge_dev_schedule_sync_status CHECK (sync_status IN ('PENDING', 'SYNCED', 'ERROR')),
    CONSTRAINT ck_dataforge_dev_schedule_counters CHECK (generation >= 0 AND attempts >= 0 AND last_ds_instance_id >= 0
        AND poll_page_no >= 1 AND poll_high_water_id >= 0),
    CONSTRAINT ck_dataforge_dev_schedule_deleted CHECK (deleted IN (0, 1))
);
ALTER SEQUENCE dh_dataforge_dev_schedule_seq OWNED BY dh_dataforge_dev_schedule.id;

-- 防止同名遗留表或不完整手工建表被 IF NOT EXISTS 静默接受。
DO $binding_contract$
BEGIN
    IF EXISTS (
        SELECT 1 FROM (VALUES
            ('id', 'bigint', true), ('tenant_id', 'bigint', true), ('task_id', 'bigint', true),
            ('version_id', 'bigint', true), ('generation', 'integer', true), ('cron_expression', 'character varying(100)', true),
            ('ds_project_code', 'bigint', true), ('worker_group', 'character varying(100)', true), ('tenant_code', 'character varying(100)', true),
            ('timezone_id', 'character varying(64)', true), ('desired_enabled', 'boolean', true), ('synced_enabled', 'boolean', true),
            ('ds_workflow_code', 'bigint', false), ('ds_schedule_id', 'integer', false), ('sync_status', 'character varying(24)', true),
            ('attempts', 'integer', true), ('lease_owner', 'character varying(64)', false), ('lease_until', 'timestamp without time zone', false),
            ('last_error', 'character varying(1000)', false), ('last_ds_instance_id', 'bigint', true),
            ('poll_end_time', 'timestamp without time zone', false), ('poll_page_no', 'integer', true),
            ('poll_high_water_id', 'bigint', true), ('last_poll_time', 'timestamp without time zone', false),
            ('schedule_start_time', 'timestamp without time zone', true),
            ('creator', 'character varying(64)', false), ('create_time', 'timestamp without time zone', true),
            ('updater', 'character varying(64)', false), ('update_time', 'timestamp without time zone', true), ('deleted', 'smallint', true)
        ) expected(name, type_name, required)
        LEFT JOIN pg_attribute actual ON actual.attrelid = 'dh_dataforge_dev_schedule'::regclass
            AND actual.attname = expected.name AND NOT actual.attisdropped
        WHERE actual.attnum IS NULL OR format_type(actual.atttypid, actual.atttypmod) <> expected.type_name
            OR actual.attnotnull <> expected.required
    ) THEN
        RAISE EXCEPTION '0164 调度绑定表字段与当前契约不一致，禁止覆盖或截断既有台账';
    END IF;
END $binding_contract$;

COMMENT ON TABLE dh_dataforge_dev_schedule IS '数据开发-DolphinScheduler周期绑定与同步恢复台账';
COMMENT ON COLUMN dh_dataforge_dev_schedule.id IS '调度绑定编号';
COMMENT ON COLUMN dh_dataforge_dev_schedule.tenant_id IS '平台租户编号';
COMMENT ON COLUMN dh_dataforge_dev_schedule.task_id IS '数据开发任务编号';
COMMENT ON COLUMN dh_dataforge_dev_schedule.version_id IS '本代周期触发绑定的不可变保存版本编号';
COMMENT ON COLUMN dh_dataforge_dev_schedule.generation IS '任务修订号对应的调度代次；旧代先取消，当前代再登记';
COMMENT ON COLUMN dh_dataforge_dev_schedule.cron_expression IS '经校验的 DolphinScheduler Quartz Cron 表达式';
COMMENT ON COLUMN dh_dataforge_dev_schedule.ds_project_code IS 'DolphinScheduler调度项目编号';
COMMENT ON COLUMN dh_dataforge_dev_schedule.worker_group IS '调度登记时冻结的执行工作组';
COMMENT ON COLUMN dh_dataforge_dev_schedule.tenant_code IS '调度登记时冻结的引擎租户代码';
COMMENT ON COLUMN dh_dataforge_dev_schedule.timezone_id IS '外部周期触发及实例计划时间使用的时区';
COMMENT ON COLUMN dh_dataforge_dev_schedule.desired_enabled IS '平台期望启用状态；旧代取消也通过此状态对账';
COMMENT ON COLUMN dh_dataforge_dev_schedule.synced_enabled IS '最后已确认的外部周期启用状态';
COMMENT ON COLUMN dh_dataforge_dev_schedule.ds_workflow_code IS '平台托管的无业务副作用触发流程编号；未知创建结果可为空';
COMMENT ON COLUMN dh_dataforge_dev_schedule.ds_schedule_id IS '外部调度登记编号；创建和启停结果由维护任务确认';
COMMENT ON COLUMN dh_dataforge_dev_schedule.sync_status IS '同步状态：PENDING待同步、SYNCED已确认、ERROR需重试';
COMMENT ON COLUMN dh_dataforge_dev_schedule.attempts IS '当前同步累计尝试次数';
COMMENT ON COLUMN dh_dataforge_dev_schedule.lease_owner IS '当前同步或轮询执行者租约令牌';
COMMENT ON COLUMN dh_dataforge_dev_schedule.lease_until IS '租约截止时间；过期后允许其他执行者恢复';
COMMENT ON COLUMN dh_dataforge_dev_schedule.last_error IS '最近受控同步错误摘要；不得存储连接凭据';
COMMENT ON COLUMN dh_dataforge_dev_schedule.last_ds_instance_id IS '最后已导入的外部触发实例编号；运行服务仍以实例编号幂等去重';
COMMENT ON COLUMN dh_dataforge_dev_schedule.poll_end_time IS '本轮分页轮询冻结的截止时间；未完成时从同一时间窗口恢复';
COMMENT ON COLUMN dh_dataforge_dev_schedule.poll_page_no IS '本轮下一页编号，从一开始；失败或未完成时保留恢复位置';
COMMENT ON COLUMN dh_dataforge_dev_schedule.poll_high_water_id IS '本轮已处理的最大实例编号；所有页成功后才推进全局导入游标';
COMMENT ON COLUMN dh_dataforge_dev_schedule.last_poll_time IS '最后成功完成全部分页的轮询截止时间';
COMMENT ON COLUMN dh_dataforge_dev_schedule.schedule_start_time IS '本代调度允许接收的计划触发起点';
COMMENT ON COLUMN dh_dataforge_dev_schedule.creator IS '创建者';
COMMENT ON COLUMN dh_dataforge_dev_schedule.create_time IS '创建时间';
COMMENT ON COLUMN dh_dataforge_dev_schedule.updater IS '最后更新者';
COMMENT ON COLUMN dh_dataforge_dev_schedule.update_time IS '最后更新时间';
COMMENT ON COLUMN dh_dataforge_dev_schedule.deleted IS '逻辑删除标识：0未删除、1已删除；外部取消前不得删除绑定';

CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_dev_schedule_generation
    ON dh_dataforge_dev_schedule (tenant_id, task_id, generation) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_dataforge_dev_schedule_sync
    ON dh_dataforge_dev_schedule (sync_status, lease_until, id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_dataforge_dev_schedule_task_version
    ON dh_dataforge_dev_schedule (tenant_id, task_id, version_id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_dataforge_dev_schedule_poll
    ON dh_dataforge_dev_schedule (tenant_id, ds_project_code, ds_workflow_code, last_ds_instance_id)
    WHERE deleted = 0 AND synced_enabled;

ALTER TABLE dh_dataforge_dev_task DROP CONSTRAINT ck_dataforge_dev_scheduler;
ALTER TABLE dh_dataforge_dev_task ALTER COLUMN scheduler SET DEFAULT 'DOLPHIN_SCHEDULER';
ALTER TABLE dh_dataforge_dev_task ADD COLUMN IF NOT EXISTS legacy_cron_expression varchar(100);
DO $legacy_cron_contract$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_dataforge_dev_task'::regclass
        AND attname = 'legacy_cron_expression' AND NOT attisdropped
        AND format_type(atttypid, atttypmod) = 'character varying(100)') THEN
        RAISE EXCEPTION '0164 旧 Cron 备份列类型冲突，禁止截断或覆盖';
    END IF;
END $legacy_cron_contract$;
COMMENT ON COLUMN dh_dataforge_dev_task.legacy_cron_expression IS '只读原 XXL Spring Cron 备份；不代表可直接启用的 DolphinScheduler Quartz Cron';
-- 原表达式转存只读备份；不覆盖非空备份，不推断数字星期转换，不制造外部调度成功记录。
UPDATE dh_dataforge_dev_task
SET scheduler = 'DOLPHIN_SCHEDULER', schedule_status = 0, next_run_time = NULL,
    legacy_cron_expression = CASE WHEN nullif(legacy_cron_expression, '') IS NULL THEN cron_expression ELSE legacy_cron_expression END,
    cron_expression = NULL,
    updater = 'migration:0164', update_time = CURRENT_TIMESTAMP
WHERE scheduler = 'XXL_JOB';
ALTER TABLE dh_dataforge_dev_task ADD CONSTRAINT ck_dataforge_dev_scheduler CHECK (scheduler IN ('DOLPHIN_SCHEDULER'));
COMMENT ON COLUMN dh_dataforge_dev_task.scheduler IS '调度系统：DOLPHIN_SCHEDULER；外部周期触发经绑定台账和维护任务导入平台运行链路';

COMMIT;

-- Migration: 0165 模型物化部署版本冻结、目标互斥与未知结果恢复。
-- Purpose: 增加已发布版本关联和持久部署尝试，跨租户以权威物理目标互斥；历史运行中状态转为未知，禁止推断部署成功或直接重建。
-- Depends on: 0164_dataforge_dev-dolphinscheduler-schedules.sql 已执行或核验达到对应状态；0140 的物化记录及日志表、逻辑模型版本表存在。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；加列、建表、索引按存在性保护；历史运行中状态仅首次转换，已有尝试和冻结证据不覆盖。
-- Rollback: 失败整笔回滚；提交后回退应用前停止部署节点并核对所有 RUNNING/UNKNOWN 外部结果，保留尝试与证据列。不能删除未知占用后直接重跑破坏性部署。
-- 风险：短时结构锁与索引创建；升级前停止旧物化发布节点，备份物化记录。旧记录未记录冻结版本和外部证据，不按当前版本猜测回填。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_modeling_model_materialized ADD COLUMN IF NOT EXISTS version_id bigint;
ALTER TABLE dh_modeling_model_materialized ADD COLUMN IF NOT EXISTS attempt_id bigint;
COMMENT ON COLUMN dh_modeling_model_materialized.version_id IS '本次物化使用的已发布逻辑模型冻结版本；历史未知不回填';
COMMENT ON COLUMN dh_modeling_model_materialized.attempt_id IS '当前持久部署尝试编号；终态按尝试编号更新防止迟到结果覆盖';
COMMENT ON COLUMN dh_modeling_model_materialized.status IS '状态：RUNNING执行中、SUCCESS已确认成功、FAIL已确认失败、UNKNOWN外部结果待对账';
ALTER TABLE dh_modeling_model_materialized_log ADD COLUMN IF NOT EXISTS audit_evidence_json jsonb;
COMMENT ON COLUMN dh_modeling_model_materialized_log.audit_evidence_json IS '历史未知人工核验的操作者、租户、物理目标观察、理由和外部证据；不包含连接凭据';
UPDATE dh_modeling_model_materialized SET status = 'UNKNOWN',
    message = '旧部署缺少冻结证据，须先人工核验外部结果，禁止直接重建',
    updater = 'migration:0165', update_time = CURRENT_TIMESTAMP
WHERE status = 'RUNNING' AND attempt_id IS NULL;

CREATE SEQUENCE IF NOT EXISTS dh_modeling_deployment_attempt_seq;
CREATE TABLE IF NOT EXISTS dh_modeling_deployment_attempt (
    id bigint PRIMARY KEY DEFAULT nextval('dh_modeling_deployment_attempt_seq'::regclass),
    materialized_id bigint NOT NULL,
    version_id bigint NOT NULL,
    datasource_id bigint NOT NULL,
    target_key varchar(64) NOT NULL,
    schema_name varchar(128) NOT NULL,
    table_name varchar(128) NOT NULL,
    configuration_revision varchar(100) NOT NULL,
    publish_mode varchar(32) NOT NULL,
    status varchar(32) NOT NULL DEFAULT 'RUNNING',
    phase varchar(24) NOT NULL DEFAULT 'PREPARED',
    lease_owner varchar(64) NOT NULL,
    lease_until timestamp NOT NULL,
    before_observation_json jsonb NOT NULL,
    ddl_sql text NOT NULL,
    fields_json jsonb NOT NULL,
    model_snapshot_json jsonb NOT NULL,
    message varchar(2000),
    finished_time timestamp,
    creator varchar(64) DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    tenant_id bigint NOT NULL,
    CONSTRAINT ck_modeling_deployment_status CHECK (status IN ('RUNNING', 'SUCCESS', 'FAIL', 'UNKNOWN')),
    CONSTRAINT ck_modeling_deployment_phase CHECK (phase IN ('PREPARED', 'EXECUTING', 'FINISHED')),
    CONSTRAINT ck_modeling_deployment_deleted CHECK (deleted IN (0, 1))
);
ALTER SEQUENCE dh_modeling_deployment_attempt_seq OWNED BY dh_modeling_deployment_attempt.id;
DO $contract$
BEGIN
    IF EXISTS (
        SELECT 1 FROM (VALUES
            ('id', 'bigint', true), ('materialized_id', 'bigint', true), ('version_id', 'bigint', true),
            ('datasource_id', 'bigint', true), ('target_key', 'character varying(64)', true),
            ('schema_name', 'character varying(128)', true), ('table_name', 'character varying(128)', true),
            ('configuration_revision', 'character varying(100)', true), ('publish_mode', 'character varying(32)', true),
            ('status', 'character varying(32)', true), ('phase', 'character varying(24)', true),
            ('lease_owner', 'character varying(64)', true), ('lease_until', 'timestamp without time zone', true),
            ('before_observation_json', 'jsonb', true), ('ddl_sql', 'text', true), ('fields_json', 'jsonb', true),
            ('model_snapshot_json', 'jsonb', true), ('tenant_id', 'bigint', true)
        ) expected(name, type_name, required)
        LEFT JOIN pg_attribute actual ON actual.attrelid = 'dh_modeling_deployment_attempt'::regclass
            AND actual.attname = expected.name AND NOT actual.attisdropped
        WHERE actual.attnum IS NULL OR format_type(actual.atttypid, actual.atttypmod) <> expected.type_name
            OR actual.attnotnull <> expected.required
    ) THEN RAISE EXCEPTION '0165 部署尝试表不满足冻结证据和围栏契约，禁止接受同名不完整表'; END IF;
    IF EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_modeling_model_materialized'::regclass
        AND attname IN ('version_id', 'attempt_id') AND NOT attisdropped AND atttypid <> 'bigint'::regtype)
        OR NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid = 'dh_modeling_model_materialized_log'::regclass
        AND attname = 'audit_evidence_json' AND NOT attisdropped AND atttypid = 'jsonb'::regtype) THEN
        RAISE EXCEPTION '0165 物化版本、尝试编号或审计证据列类型冲突';
    END IF;
END $contract$;
COMMENT ON TABLE dh_modeling_deployment_attempt IS '数据建模-部署尝试';
COMMENT ON COLUMN dh_modeling_deployment_attempt.id IS '部署尝试编号';
COMMENT ON COLUMN dh_modeling_deployment_attempt.materialized_id IS '物化发布记录编号';
COMMENT ON COLUMN dh_modeling_deployment_attempt.version_id IS '经设计发布的不可变逻辑模型版本编号';
COMMENT ON COLUMN dh_modeling_deployment_attempt.datasource_id IS '平台目标数据源编号';
COMMENT ON COLUMN dh_modeling_deployment_attempt.target_key IS '数据库组件读取的权威物理目标摘要；不含用户、平台编号或连接凭据';
COMMENT ON COLUMN dh_modeling_deployment_attempt.schema_name IS '冻结目标模式名称';
COMMENT ON COLUMN dh_modeling_deployment_attempt.table_name IS '冻结最终物理表名';
COMMENT ON COLUMN dh_modeling_deployment_attempt.configuration_revision IS '冻结数据源配置修订；恢复时必须一致';
COMMENT ON COLUMN dh_modeling_deployment_attempt.publish_mode IS '冻结发布模式：REBUILD重建、INCREMENT增量';
COMMENT ON COLUMN dh_modeling_deployment_attempt.status IS '尝试状态；RUNNING和UNKNOWN保持物理目标占用';
COMMENT ON COLUMN dh_modeling_deployment_attempt.phase IS '阶段：PREPARED未进入DDL、EXECUTING可能已执行、FINISHED已完成';
COMMENT ON COLUMN dh_modeling_deployment_attempt.lease_owner IS '执行或对账的随机围栏令牌';
COMMENT ON COLUMN dh_modeling_deployment_attempt.lease_until IS '租约截止；过期仅允许接管对账，不允许直接执行新DDL';
COMMENT ON COLUMN dh_modeling_deployment_attempt.before_observation_json IS '执行前无密原生结构及关系身份冻结证据';
COMMENT ON COLUMN dh_modeling_deployment_attempt.ddl_sql IS '冻结的完整DDL计划；重建包含同事务DROP与CREATE';
COMMENT ON COLUMN dh_modeling_deployment_attempt.fields_json IS '已发布版本字段快照';
COMMENT ON COLUMN dh_modeling_deployment_attempt.model_snapshot_json IS '已发布版本模型及业务口径快照';
COMMENT ON COLUMN dh_modeling_deployment_attempt.message IS '受控结果或对账摘要，不存连接错误原文';
COMMENT ON COLUMN dh_modeling_deployment_attempt.finished_time IS '已确认终态时间；未知保持空';
COMMENT ON COLUMN dh_modeling_deployment_attempt.creator IS '创建者';
COMMENT ON COLUMN dh_modeling_deployment_attempt.create_time IS '创建时间';
COMMENT ON COLUMN dh_modeling_deployment_attempt.updater IS '更新者';
COMMENT ON COLUMN dh_modeling_deployment_attempt.update_time IS '更新时间';
COMMENT ON COLUMN dh_modeling_deployment_attempt.deleted IS '逻辑删除标识；未知尝试不得删除';
COMMENT ON COLUMN dh_modeling_deployment_attempt.tenant_id IS '平台租户编号';
-- 物理目标可能被不同租户或不同数据源编号共享，因此互斥唯一键不包含平台租户编号。
CREATE UNIQUE INDEX IF NOT EXISTS uk_modeling_deployment_active_target
    ON dh_modeling_deployment_attempt(target_key) WHERE deleted = 0 AND status IN ('RUNNING', 'UNKNOWN');
CREATE INDEX IF NOT EXISTS idx_modeling_deployment_materialized
    ON dh_modeling_deployment_attempt(tenant_id, materialized_id, id DESC) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_modeling_deployment_recovery
    ON dh_modeling_deployment_attempt(tenant_id, status, lease_until) WHERE deleted = 0;
COMMIT;

-- Migration: 0166 移除模型旧记录人工恢复的专用字段。
-- Purpose: 项目尚未投产，仅保留当前冻结部署尝试及 UNKNOWN 自动核验流程，移除旧记录人工登记证据列。
-- Depends on: 0165_modeling_materialized-deployment-safety.sql 已执行，物化记录、日志及部署尝试表存在。
-- Target: 达到 0165 的 PostgreSQL 平台库，schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；删除列使用存在性保护，字段注释可重复执行，不改部署尝试和运行状态。
-- Rollback: 失败整笔回滚；提交后可重新添加 audit_evidence_json jsonb 列，但无法恢复被删除的列数据。本项目未投产，不提供旧记录迁移或人工恢复流程。
-- 风险：删除专用证据列不可逆，ALTER TABLE 获取短时结构锁；执行期间应暂停物化日志写入。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_modeling_model_materialized_log DROP COLUMN IF EXISTS audit_evidence_json;
COMMENT ON COLUMN dh_modeling_model_materialized.version_id IS '本次物化使用的已发布逻辑模型冻结版本编号';
COMMENT ON COLUMN dh_modeling_model_materialized.attempt_id IS '当前持久部署尝试编号；终态按尝试编号更新防止迟到结果覆盖';
COMMIT;

-- 0168 新库整合：原始菜单种子已采用旧调用按钮退役后的状态，无需重放固定编号清理。
-- 前述迁移可能把空闲编号 6911 分配给新的治理权限；新库必须保留该权限，不能再按旧菜单编号删除。
-- 0170 新库整合：上述种子已满足按实际身份退役的最终状态，保留复用编号的治理菜单及其授权。
-- 已有数据库若 0168 因编号复用失败，使用独立 0170 替代，再继续未执行的 0169；本基线不可用作已有库升级。

-- Migration: 0169 数据中台业务切换为单租户。
-- Purpose: 删除 dh_* 业务表的 tenant_id，保留全局业务唯一性、复合引用、排他约束和守卫。
-- Depends on: 0168_supply_retire-legacy-invoke-menu.sql 已执行，或已核验平台达到对应结构；旧应用和后台任务全部停止。
-- Target: datahub-center 开发平台库；新库使用包含本迁移的全量基线。system、infra、bpm 等脚手架表及外部引擎 tenant_code 不在删除范围内。
-- Repeatable: 是；已移除的列不再处理，命名范围转换幂等，全局扫描游标只在首次转换时重置。
-- Rollback: 单事务失败完整回滚；提交后原租户归属不可恢复，恢复必须使用执行前备份和旧应用。全局扫描游标首次重置，下一轮重新扫描，业务记录不删除。
-- 风险：事务对全部受影响业务表获取排他锁并重建索引，执行前停机并备份；十秒内无法取得锁即失败。新全局唯一键或有效期区间冲突会在删除列前阻断，不自动合并或删除业务数据。
-- 开发状态：旧分组/整表恢复材料的认证摘要及类型化检查点绑定包含租户，不能自动重签或沿用。发现这些旧运行状态即阻断；未上线开发环境推荐使用新基线新建数据库，不将失效认证材料视为迁移成功。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '15min';

CREATE TEMP TABLE single_tenant_tables ON COMMIT DROP AS
SELECT c.oid AS table_oid, c.relname AS table_name, a.attnum AS tenant_attnum
FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
JOIN pg_attribute a ON a.attrelid = c.oid AND a.attname = 'tenant_id' AND NOT a.attisdropped
WHERE n.nspname = 'datahub-center' AND c.relname LIKE 'dh\_%' ESCAPE '\' AND c.relkind = 'r';

CREATE TEMP TABLE single_tenant_constraints (
    table_oid oid, constraint_name name, constraint_type "char", definition text
) ON COMMIT DROP;
CREATE TEMP TABLE single_tenant_indexes (
    table_oid oid, index_oid oid, index_name name, is_unique boolean, is_constraint boolean, definition text
) ON COMMIT DROP;

DO $single_tenant_plan$
DECLARE
    item record;
    definition text;
    probe_name text;
    has_legacy_material boolean;
BEGIN
    -- 在读取约束和验证唯一性前阻止并发写入，避免预检和重建之间出现新冲突。
    FOR item IN SELECT * FROM single_tenant_tables ORDER BY table_name LOOP
        EXECUTE format('LOCK TABLE %s IN ACCESS EXCLUSIVE MODE', item.table_oid::regclass);
    END LOOP;

    -- 当前权限由 database + schema + table 精确定位；退役已被精确索引替代的旧无 schema 唯一键。
    -- 某些历史基线在精确索引之后又重建旧索引，不能把该残留带入全局唯一性预检。
    IF to_regclass('"datahub-center".uk_safety_table_exact_role') IS NOT NULL THEN
        DROP INDEX IF EXISTS "datahub-center".uk_dh_safety_table_permission_role;
    END IF;
    IF to_regclass('"datahub-center".uk_safety_field_exact_role') IS NOT NULL THEN
        DROP INDEX IF EXISTS "datahub-center".uk_dh_safety_field_permission_role;
    END IF;

    FOR item IN SELECT * FROM single_tenant_tables WHERE table_name IN(
        'dh_dataforge_access_group_pin','dh_dataforge_access_table_pin','dh_dataforge_access_checkpoint') LOOP
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM %s)',item.table_oid::regclass) INTO has_legacy_material;
        IF has_legacy_material THEN
            RAISE EXCEPTION '单租户迁移发现无法沿用认证绑定的旧开发运行材料：%；请先完成原任务恢复和核验，或使用新基线新建开发库，不得自动重签或清空',item.table_name;
        END IF;
    END LOOP;

    -- 未知的租户表达式、分区或跨脚手架引用不作猜测性改写，直接要求先核验实际结构。
    IF EXISTS (
        SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace
        JOIN pg_attribute a ON a.attrelid=c.oid AND a.attname='tenant_id' AND NOT a.attisdropped
        WHERE n.nspname='datahub-center' AND c.relname LIKE 'dh\_%' ESCAPE '\' AND c.relkind='p'
    ) THEN RAISE EXCEPTION '单租户迁移不接受未核验的租户分区表'; END IF;

    FOR item IN
        SELECT i.*, t.tenant_attnum, t.table_name, ci.relname AS index_name,
               EXISTS(SELECT 1 FROM pg_constraint con WHERE con.conindid=i.indexrelid AND con.contype IN ('p','u','x')) AS is_constraint
        FROM single_tenant_tables t JOIN pg_index i ON i.indrelid=t.table_oid
        JOIN pg_class ci ON ci.oid=i.indexrelid
        WHERE t.tenant_attnum=ANY(i.indkey)
           OR pg_get_expr(i.indexprs,i.indrelid) ~ '\mtenant_id\M'
           OR pg_get_expr(i.indpred,i.indrelid) ~ '\mtenant_id\M'
    LOOP
        IF COALESCE(pg_get_expr(item.indexprs,item.indrelid),'') ~ '\mtenant_id\M'
           OR COALESCE(pg_get_expr(item.indpred,item.indrelid),'') ~ '\mtenant_id\M' THEN
            RAISE EXCEPTION '单租户迁移遇到未支持的租户表达式索引：%', item.index_name;
        END IF;
        IF EXISTS(SELECT 1 FROM generate_series(1,item.indnatts) p
                  WHERE item.indkey[p-1]=item.tenant_attnum AND pg_get_indexdef(item.indexrelid,p,true)<>'tenant_id') THEN
            RAISE EXCEPTION '单租户迁移遇到未核验的租户索引排序或操作符：%', item.index_name;
        END IF;
        IF item.indnkeyatts=1 AND item.indkey[0]=item.tenant_attnum THEN
            IF item.table_name<>'dh_governance_quality_exception_expiry_cursor' THEN
                RAISE EXCEPTION '单租户迁移遇到未核验的仅租户索引：%', item.index_name;
            END IF;
            CONTINUE;
        END IF;
        definition:=pg_get_indexdef(item.indexrelid);
        definition:=regexp_replace(definition,'\mtenant_id\M, ','','g');
        definition:=regexp_replace(definition,', tenant_id\M','','g');
        definition:=replace(definition,' INCLUDE (tenant_id)','');
        IF definition ~ '\mtenant_id\M' THEN
            RAISE EXCEPTION '单租户索引仍引用租户列：%', item.index_name;
        END IF;
        INSERT INTO single_tenant_indexes VALUES(item.indrelid,item.indexrelid,item.index_name,item.indisunique,item.is_constraint,definition);
        IF item.indisunique THEN
            -- 由 PostgreSQL 原生唯一索引预检，保留表达式、排序规则、空值语义和部分索引条件。
            probe_name:='single_tenant_probe_'||item.indexrelid;
            BEGIN
                EXECUTE replace(definition,'INDEX '||quote_ident(item.index_name)||' ON ',
                                'INDEX '||quote_ident(probe_name)||' ON ');
            EXCEPTION WHEN unique_violation THEN
                RAISE EXCEPTION '单租户预检失败：表 % 的全局唯一键 % 存在冲突，请先明确处理冲突记录',item.table_name,item.index_name;
            END;
            EXECUTE format('DROP INDEX %I',probe_name);
        END IF;
    END LOOP;

    FOR item IN
        SELECT con.*, t.tenant_attnum, t.table_name
        FROM single_tenant_tables t JOIN pg_constraint con ON con.conrelid=t.table_oid
        WHERE t.tenant_attnum=ANY(con.conkey) AND con.contype IN ('p','u','f','x','c')
    LOOP
        definition:=pg_get_constraintdef(item.oid);
        IF item.contype='c' THEN
            IF item.conkey=ARRAY[item.tenant_attnum]::smallint[] THEN CONTINUE; END IF;
            IF item.conname='ck_safety_write_audit_identity' AND item.table_name='dh_governance_safety_write_audit' THEN
                definition:='CHECK (database_id > 0 AND role_id > 0 AND actor_id > 0)';
            ELSE
                RAISE EXCEPTION '单租户迁移遇到未核验的混合检查约束：%',item.conname;
            END IF;
        ELSE
            IF item.contype='f' AND NOT EXISTS(SELECT 1 FROM single_tenant_tables WHERE table_oid=item.confrelid) THEN
                RAISE EXCEPTION '业务租户外键引用范围外对象：%',item.conname;
            END IF;
            IF item.conkey=ARRAY[item.tenant_attnum]::smallint[] THEN
                IF item.table_name='dh_governance_quality_exception_expiry_cursor' AND item.contype='u' THEN CONTINUE; END IF;
                RAISE EXCEPTION '单租户迁移遇到未核验的仅租户约束：%',item.conname;
            END IF;
            definition:=regexp_replace(definition,'\mtenant_id\M WITH =, ','','g');
            definition:=regexp_replace(definition,'\mtenant_id\M, ','','g');
            definition:=regexp_replace(definition,', tenant_id\M','','g');
        END IF;
        IF definition ~ '\mtenant_id\M' THEN RAISE EXCEPTION '单租户约束仍引用租户列：%',item.conname; END IF;
        INSERT INTO single_tenant_constraints VALUES(item.conrelid,item.conname,item.contype,definition);
        IF item.contype='x' THEN
            probe_name:='single_tenant_probe_'||item.oid;
            BEGIN
                EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I %s',item.conrelid::regclass,probe_name,definition);
            EXCEPTION WHEN exclusion_violation THEN
                RAISE EXCEPTION '单租户预检失败：表 % 的全局有效期排他约束 % 存在冲突',item.table_name,item.conname;
            END;
            EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',item.conrelid::regclass,probe_name);
        END IF;
    END LOOP;
END $single_tenant_plan$;

DO $single_tenant_apply$
DECLARE item record;
BEGIN
    -- 先解除外键，再移除其依赖的唯一键；重建时顺序相反。
    FOR item IN SELECT * FROM single_tenant_constraints ORDER BY (constraint_type='f') DESC,table_oid,constraint_name LOOP
        EXECUTE format('ALTER TABLE %s DROP CONSTRAINT %I',item.table_oid::regclass,item.constraint_name);
    END LOOP;
    FOR item IN SELECT * FROM single_tenant_indexes WHERE NOT is_constraint LOOP
        EXECUTE format('DROP INDEX %I',item.index_name);
    END LOOP;
    IF EXISTS(SELECT 1 FROM single_tenant_tables WHERE table_name='dh_governance_standard_code_item') THEN
        DROP TRIGGER IF EXISTS trg_std_code_item_validate_hierarchy ON dh_governance_standard_code_item;
    END IF;
    FOR item IN SELECT * FROM single_tenant_tables ORDER BY table_name LOOP
        -- 不使用 CASCADE；未知视图或外部依赖会阻止迁移并使整笔事务回滚。
        EXECUTE format('ALTER TABLE %s DROP COLUMN tenant_id',item.table_oid::regclass);
    END LOOP;
    FOR item IN SELECT * FROM single_tenant_constraints WHERE constraint_type<>'f' ORDER BY table_oid,constraint_name LOOP
        EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I %s',item.table_oid::regclass,item.constraint_name,item.definition);
    END LOOP;
    FOR item IN SELECT * FROM single_tenant_indexes WHERE NOT is_constraint LOOP EXECUTE item.definition; END LOOP;
    FOR item IN SELECT * FROM single_tenant_constraints WHERE constraint_type='f' ORDER BY table_oid,constraint_name LOOP
        EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I %s',item.table_oid::regclass,item.constraint_name,item.definition);
    END LOOP;

    IF EXISTS(SELECT 1 FROM single_tenant_tables WHERE table_name='dh_governance_quality_exception_expiry_cursor') THEN
        -- 扫描位置属于可重建内部状态，重置后从头扫描，不改变提交或审批业务数据。
        DELETE FROM dh_governance_quality_exception_expiry_cursor;
        INSERT INTO dh_governance_quality_exception_expiry_cursor(id) VALUES(1);
        ALTER TABLE dh_governance_quality_exception_expiry_cursor ALTER COLUMN id SET DEFAULT 1;
        ALTER TABLE dh_governance_quality_exception_expiry_cursor ADD CONSTRAINT ck_quality_expiry_cursor_singleton CHECK(id=1);
        COMMENT ON COLUMN dh_governance_quality_exception_expiry_cursor.id IS '全局扫描游标，固定为一';
    END IF;
END $single_tenant_apply$;

CREATE OR REPLACE FUNCTION dh_validate_standard_code_item_hierarchy() RETURNS trigger LANGUAGE plpgsql AS $guard$
DECLARE resolved_type varchar(100); has_cycle boolean;
BEGIN
    IF NEW.deleted=0 THEN
        -- 码集作为聚合锁根，串行化层级修改，阻止并发父节点更新形成环。
        SELECT code_set.type INTO resolved_type FROM "datahub-center".dh_governance_standard_code_set code_set
        WHERE code_set.id=NEW.code_set_id AND code_set.deleted=0 FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION '标准码项必须引用有效码集'; END IF;
        IF NEW.dict_type<>resolved_type THEN RAISE EXCEPTION '标准码项类型必须与所属码集一致'; END IF;
    END IF;
    IF NEW.parent_id IS NULL THEN RETURN NEW; END IF;
    IF NEW.parent_id=NEW.id THEN RAISE EXCEPTION '标准码项不能以自身为父节点'; END IF;
    IF NOT EXISTS(SELECT 1 FROM "datahub-center".dh_governance_standard_code_item p
                  WHERE p.id=NEW.parent_id AND p.code_set_id=NEW.code_set_id AND p.deleted=0) THEN
        RAISE EXCEPTION '标准码项父节点必须为同一码集的有效节点';
    END IF;
    WITH RECURSIVE ancestors AS (
        SELECT p.id,p.parent_id,ARRAY[p.id]::int4[] AS path FROM "datahub-center".dh_governance_standard_code_item p
        WHERE p.id=NEW.parent_id AND p.code_set_id=NEW.code_set_id AND p.deleted=0
        UNION ALL
        SELECT p.id,p.parent_id,a.path||p.id FROM ancestors a
        JOIN "datahub-center".dh_governance_standard_code_item p ON p.id=a.parent_id
        AND p.code_set_id=NEW.code_set_id AND p.deleted=0 WHERE NOT p.id=ANY(a.path)
    ) SELECT EXISTS(SELECT 1 FROM ancestors WHERE id=NEW.id) INTO has_cycle;
    IF has_cycle THEN RAISE EXCEPTION '标准码项层级存在循环'; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION dh_validate_standard_code_item_hierarchy() IS '保护标准码集层级引用、类型一致性和无环约束';
DO $single_tenant_code_hierarchy$
BEGIN
    IF to_regclass('"datahub-center".dh_governance_standard_code_item') IS NOT NULL THEN
        DROP TRIGGER IF EXISTS trg_std_code_item_validate_hierarchy ON dh_governance_standard_code_item;
        CREATE TRIGGER trg_std_code_item_validate_hierarchy BEFORE INSERT OR UPDATE OF code_set_id,dict_type,parent_id,deleted
        ON dh_governance_standard_code_item FOR EACH ROW EXECUTE FUNCTION dh_validate_standard_code_item_hierarchy();
    END IF;
END $single_tenant_code_hierarchy$;

CREATE OR REPLACE FUNCTION modeling_guard_layer_reference() RETURNS trigger LANGUAGE plpgsql AS $guard$
DECLARE v_layer record;
BEGIN
    IF NEW.deleted<>0 OR NEW.layer_id IS NULL THEN RETURN NEW; END IF;
    IF TG_OP='UPDATE' AND NEW.layer_id IS NOT DISTINCT FROM OLD.layer_id THEN RETURN NEW; END IF;
    SELECT node_type,status INTO v_layer FROM "datahub-center".dh_modeling_dw_layer
    WHERE id=NEW.layer_id AND deleted=0 FOR SHARE;
    IF NOT FOUND OR v_layer.node_type<>'LAYER' OR v_layer.status<>0 THEN
        RAISE EXCEPTION '分层不存在、不是实际分层或已停用' USING ERRCODE='23514';
    END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_guard_layer_reference() IS '保护模型对有效实际分层的引用';

CREATE OR REPLACE FUNCTION modeling_ownership_reference_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE row_data jsonb; object_id bigint; deleting boolean; ref_field text; ref_table text; found_row boolean;
BEGIN
    row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    object_id:=(row_data->>'id')::bigint;
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-global',0));
    deleting:=TG_OP='DELETE' OR COALESCE((row_data->>'deleted')::integer,0)<>0;
    IF TG_TABLE_NAME='dh_modeling_logic_model' AND NOT deleting THEN
        FOR ref_field,ref_table IN SELECT * FROM(VALUES('data_domain_id','dh_modeling_data_domain'),('subject_domain_id','dh_modeling_subject_domain'),('layer_id','dh_modeling_dw_layer')) r(f,t) LOOP
            IF row_data->>ref_field IS NOT NULL THEN
                EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND deleted=0)',ref_table)
                    INTO found_row USING (row_data->>ref_field)::bigint;
                IF NOT found_row THEN RAISE EXCEPTION '模型归属不存在：%',ref_field USING ERRCODE='23514'; END IF;
            END IF;
        END LOOP;
    ELSIF TG_TABLE_NAME IN('dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_dw_layer') AND deleting THEN
        ref_field:=CASE TG_TABLE_NAME WHEN 'dh_modeling_data_domain' THEN 'data_domain_id' WHEN 'dh_modeling_subject_domain' THEN 'subject_domain_id' ELSE 'layer_id' END;
        EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".dh_modeling_logic_model WHERE %I=$1 AND deleted=0)',ref_field)
            INTO found_row USING object_id;
        IF found_row THEN RAISE EXCEPTION '规划对象仍被模型引用，不能删除' USING ERRCODE='23514'; END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_ownership_reference_guard() IS '保护模型与数据域、主题域、分层的有效归属和删除引用';

CREATE OR REPLACE FUNCTION modeling_guard_layer_change() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
BEGIN
    IF TG_OP='UPDATE' AND ROW(NEW.deleted,NEW.status,NEW.node_type,NEW.layer_code,NEW.table_prefix,NEW.default_table_type)
       IS NOT DISTINCT FROM ROW(OLD.deleted,OLD.status,OLD.node_type,OLD.layer_code,OLD.table_prefix,OLD.default_table_type) THEN RETURN NEW; END IF;
    IF EXISTS(SELECT 1 FROM dh_modeling_logic_model WHERE layer_id=OLD.id AND deleted=0) THEN
        RAISE EXCEPTION '分层已被模型引用，不能删除、停用或改变技术配置' USING ERRCODE='23514';
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_guard_layer_change() IS '阻止修改仍被模型引用的分层技术配置';

CREATE OR REPLACE FUNCTION dh_modeling_unified_relation_guard() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
DECLARE pair jsonb;
BEGIN
    IF NEW.deleted<>0 THEN RETURN NEW; END IF;
    IF NOT EXISTS(SELECT 1 FROM dh_modeling_logic_model WHERE id=NEW.source_model_id AND deleted=0)
       OR NOT EXISTS(SELECT 1 FROM dh_modeling_logic_model WHERE id=NEW.target_model_id AND deleted=0) THEN
        RAISE EXCEPTION 'ER 关系两端必须是有效模型';
    END IF;
    IF NEW.field_pairs IS NULL THEN RAISE EXCEPTION '新建或编辑关系须提供稳定字段标识，不得仅按字段名称保存'; END IF;
    FOR pair IN SELECT value FROM jsonb_array_elements(NEW.field_pairs) LOOP
        IF jsonb_typeof(pair)<>'object' OR NULLIF(btrim(pair->>'sourceFieldUid'),'') IS NULL OR NULLIF(btrim(pair->>'targetFieldUid'),'') IS NULL THEN
            RAISE EXCEPTION '复合关联键必须提供非空的两端字段标识';
        END IF;
    END LOOP;
    IF EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.field_pairs) p GROUP BY p->>'sourceFieldUid' HAVING count(*)>1)
       OR EXISTS(SELECT 1 FROM jsonb_array_elements(NEW.field_pairs) p GROUP BY p->>'targetFieldUid' HAVING count(*)>1) THEN
        RAISE EXCEPTION '复合关联键不能重复使用同一端字段';
    END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION dh_modeling_unified_relation_guard() IS '校验 ER 关系有效模型和复合字段标识；字段存在性及双端权限由应用事务校验';

DO $single_tenant_scope$
BEGIN
    IF to_regclass('"datahub-center".dh_dataforge_dev_schedule') IS NOT NULL THEN
        COMMENT ON COLUMN dh_dataforge_dev_schedule.tenant_code IS '外部调度引擎的执行用户代码，属于引擎运行配置';
    END IF;
END $single_tenant_scope$;

COMMIT;

-- Migration: 0171 概念模型与指标模型业务能力。
-- Purpose: 新建单租户概念设计、原子及派生指标，保护归属和版本引用，注册管理菜单与细分权限。
-- Depends on: 0170_supply_retire-legacy-invoke-menu-by-identity.sql 对应权限状态及 0169 单租户迁移已完成；已存在统一模型、规划表和建模概览菜单。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库使用同步的全量基线。
-- Repeatable: 是；结构与索引存在即跳过，守卫替换，菜单按组件和权限身份查找，重放不增加授权。
-- Rollback: 失败事务回滚；回退应用可保留新增表。若需移除，先备份两类模型和菜单，再移除新增触发器并恢复 0169 归属守卫；删除新增业务记录不可逆。
-- 风险：菜单维护及触发器安装短时锁表，锁等待超过十秒即失败；不自动赋予现有普通角色新权限，由管理员在角色管理中按需授权。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE SEQUENCE IF NOT EXISTS dh_modeling_concept_model_seq;
CREATE TABLE IF NOT EXISTS dh_modeling_concept_model (
    id bigint PRIMARY KEY DEFAULT nextval('dh_modeling_concept_model_seq'),
    name varchar(100) NOT NULL,
    code varchar(64) NOT NULL,
    data_domain_id bigint NOT NULL,
    subject_domain_id bigint,
    description varchar(2000),
    status varchar(16) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE')),
    revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
    design jsonb NOT NULL DEFAULT '{"entities":[],"relations":[]}'::jsonb
        CHECK (jsonb_typeof(design)='object' AND design ?& ARRAY['entities','relations']
            AND jsonb_typeof(design->'entities')='array' AND jsonb_typeof(design->'relations')='array'),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
);
COMMENT ON TABLE dh_modeling_concept_model IS '数据建模-概念模型';
COMMENT ON COLUMN dh_modeling_concept_model.id IS '概念模型编号';
COMMENT ON COLUMN dh_modeling_concept_model.name IS '概念模型名称';
COMMENT ON COLUMN dh_modeling_concept_model.code IS '概念模型编码';
COMMENT ON COLUMN dh_modeling_concept_model.data_domain_id IS '所属数据域编号';
COMMENT ON COLUMN dh_modeling_concept_model.subject_domain_id IS '可选分析主题域编号';
COMMENT ON COLUMN dh_modeling_concept_model.description IS '业务说明';
COMMENT ON COLUMN dh_modeling_concept_model.status IS '状态：草稿或已启用';
COMMENT ON COLUMN dh_modeling_concept_model.revision IS '并发修订号';
COMMENT ON COLUMN dh_modeling_concept_model.design IS '实体、属性、稳定标识及关系端点的结构化设计';
COMMENT ON COLUMN dh_modeling_concept_model.creator IS '创建人';
COMMENT ON COLUMN dh_modeling_concept_model.create_time IS '创建时间';
COMMENT ON COLUMN dh_modeling_concept_model.updater IS '更新人';
COMMENT ON COLUMN dh_modeling_concept_model.update_time IS '更新时间';
COMMENT ON COLUMN dh_modeling_concept_model.deleted IS '逻辑删除标记';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_concept_code ON dh_modeling_concept_model(lower(code)) WHERE deleted=0;
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_concept_domain_name ON dh_modeling_concept_model(data_domain_id,name) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_concept_subject ON dh_modeling_concept_model(subject_domain_id) WHERE deleted=0;

CREATE SEQUENCE IF NOT EXISTS dh_modeling_indicator_model_seq;
CREATE TABLE IF NOT EXISTS dh_modeling_indicator_model (
    id bigint PRIMARY KEY DEFAULT nextval('dh_modeling_indicator_model_seq'),
    code varchar(100) NOT NULL, name varchar(100) NOT NULL,
    indicator_type varchar(16) NOT NULL CHECK (indicator_type IN ('ATOMIC','DERIVED')),
    data_domain_id bigint NOT NULL, subject_domain_id bigint, owner_user_id bigint,
    description varchar(2000), definition varchar(2000), unit varchar(50),
    data_freshness varchar(100), result_data_type varchar(32),
    source_model_id bigint, source_version_id bigint, value_field_uid varchar(64), time_field_uid varchar(64),
    aggregation varchar(20) CHECK (aggregation IN ('SUM','COUNT','COUNT_DISTINCT','AVG','MIN','MAX')),
    base_indicator_id bigint, time_period varchar(16) CHECK (time_period IN ('DAY','WEEK','MONTH','QUARTER','YEAR')),
    business_condition varchar(2000),
    status varchar(16) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE')),
    revision bigint NOT NULL DEFAULT 0 CHECK (revision >= 0),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
    CONSTRAINT ck_modeling_indicator_definition CHECK (
        (indicator_type='ATOMIC' AND source_model_id IS NOT NULL AND source_version_id IS NOT NULL
            AND nullif(btrim(value_field_uid),'') IS NOT NULL AND aggregation IS NOT NULL
            AND base_indicator_id IS NULL AND time_period IS NULL AND business_condition IS NULL)
        OR (indicator_type='DERIVED' AND base_indicator_id IS NOT NULL AND base_indicator_id<>id
            AND time_period IS NOT NULL AND nullif(btrim(business_condition),'') IS NOT NULL
            AND source_model_id IS NULL AND source_version_id IS NULL AND value_field_uid IS NULL
            AND time_field_uid IS NULL AND aggregation IS NULL)
    )
);
COMMENT ON TABLE dh_modeling_indicator_model IS '数据建模-指标模型';
COMMENT ON COLUMN dh_modeling_indicator_model.id IS '指标编号';
COMMENT ON COLUMN dh_modeling_indicator_model.code IS '指标英文编码';
COMMENT ON COLUMN dh_modeling_indicator_model.name IS '指标中文名称';
COMMENT ON COLUMN dh_modeling_indicator_model.indicator_type IS '指标类型：原子或派生';
COMMENT ON COLUMN dh_modeling_indicator_model.data_domain_id IS '所属数据域编号';
COMMENT ON COLUMN dh_modeling_indicator_model.subject_domain_id IS '可选分析主题域编号';
COMMENT ON COLUMN dh_modeling_indicator_model.owner_user_id IS '负责人用户编号';
COMMENT ON COLUMN dh_modeling_indicator_model.description IS '指标说明';
COMMENT ON COLUMN dh_modeling_indicator_model.definition IS '指标业务口径';
COMMENT ON COLUMN dh_modeling_indicator_model.unit IS '度量单位';
COMMENT ON COLUMN dh_modeling_indicator_model.data_freshness IS '数据时效说明';
COMMENT ON COLUMN dh_modeling_indicator_model.result_data_type IS '指标结果数据类型';
COMMENT ON COLUMN dh_modeling_indicator_model.source_model_id IS '原子指标来源逻辑模型编号';
COMMENT ON COLUMN dh_modeling_indicator_model.source_version_id IS '原子指标绑定的已发布不可变版本编号';
COMMENT ON COLUMN dh_modeling_indicator_model.value_field_uid IS '参与计算的稳定字段标识';
COMMENT ON COLUMN dh_modeling_indicator_model.time_field_uid IS '统计时间字段稳定标识';
COMMENT ON COLUMN dh_modeling_indicator_model.aggregation IS '聚合方式';
COMMENT ON COLUMN dh_modeling_indicator_model.base_indicator_id IS '派生指标关联的已启用原子指标编号';
COMMENT ON COLUMN dh_modeling_indicator_model.time_period IS '派生指标统计周期';
COMMENT ON COLUMN dh_modeling_indicator_model.business_condition IS '派生指标业务限定定义';
COMMENT ON COLUMN dh_modeling_indicator_model.status IS '状态：草稿或已启用';
COMMENT ON COLUMN dh_modeling_indicator_model.revision IS '并发修订号';
COMMENT ON COLUMN dh_modeling_indicator_model.creator IS '创建人';
COMMENT ON COLUMN dh_modeling_indicator_model.create_time IS '创建时间';
COMMENT ON COLUMN dh_modeling_indicator_model.updater IS '更新人';
COMMENT ON COLUMN dh_modeling_indicator_model.update_time IS '更新时间';
COMMENT ON COLUMN dh_modeling_indicator_model.deleted IS '逻辑删除标记';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_indicator_code ON dh_modeling_indicator_model(lower(code)) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_indicator_domain ON dh_modeling_indicator_model(data_domain_id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_indicator_subject ON dh_modeling_indicator_model(subject_domain_id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_indicator_base ON dh_modeling_indicator_model(base_indicator_id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_indicator_source ON dh_modeling_indicator_model(source_model_id,source_version_id) WHERE deleted=0;

-- 复用同一归属互斥键，确保规划对象删除与新增模型引用不能并发穿透。
CREATE OR REPLACE FUNCTION modeling_ownership_reference_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $guard$
DECLARE row_data jsonb; object_id bigint; deleting boolean; ref_field text; ref_table text; found_row boolean;
BEGIN
    row_data:=CASE WHEN TG_OP='DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    object_id:=(row_data->>'id')::bigint;
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-global',0));
    deleting:=TG_OP='DELETE' OR COALESCE((row_data->>'deleted')::integer,0)<>0;
    IF TG_TABLE_NAME IN ('dh_modeling_logic_model','dh_modeling_concept_model','dh_modeling_indicator_model') AND NOT deleting THEN
        FOR ref_field,ref_table IN SELECT * FROM(VALUES('data_domain_id','dh_modeling_data_domain'),('subject_domain_id','dh_modeling_subject_domain'),('layer_id','dh_modeling_dw_layer')) r(f,t) LOOP
            IF row_data->>ref_field IS NOT NULL THEN
                EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE id=$1 AND deleted=0)',ref_table)
                    INTO found_row USING (row_data->>ref_field)::bigint;
                IF NOT found_row THEN RAISE EXCEPTION '模型归属不存在：%',ref_field USING ERRCODE='23514'; END IF;
            END IF;
        END LOOP;
    ELSIF TG_TABLE_NAME IN('dh_modeling_data_domain','dh_modeling_subject_domain','dh_modeling_dw_layer') AND deleting THEN
        ref_field:=CASE TG_TABLE_NAME WHEN 'dh_modeling_data_domain' THEN 'data_domain_id' WHEN 'dh_modeling_subject_domain' THEN 'subject_domain_id' ELSE 'layer_id' END;
        FOR ref_table IN SELECT unnest(CASE WHEN ref_field='layer_id' THEN ARRAY['dh_modeling_logic_model']
            ELSE ARRAY['dh_modeling_logic_model','dh_modeling_concept_model','dh_modeling_indicator_model'] END) LOOP
            EXECUTE format('SELECT EXISTS(SELECT 1 FROM "datahub-center".%I WHERE %I=$1 AND deleted=0)',ref_table,ref_field)
                INTO found_row USING object_id;
            IF found_row THEN RAISE EXCEPTION '规划对象仍被模型引用，不能删除' USING ERRCODE='23514'; END IF;
        END LOOP;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_ownership_reference_guard() IS '保护逻辑、概念及指标模型的规划归属和删除引用';

CREATE OR REPLACE FUNCTION modeling_indicator_reference_guard() RETURNS trigger LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
DECLARE version_fields jsonb;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-global',0));
    IF TG_TABLE_NAME='dh_modeling_indicator_model' THEN
        IF TG_OP<>'INSERT' AND EXISTS(SELECT 1 FROM dh_modeling_indicator_model WHERE base_indicator_id=OLD.id AND deleted=0) THEN
            IF TG_OP='DELETE' THEN RAISE EXCEPTION '原子指标仍被派生指标引用' USING ERRCODE='23514'; END IF;
            IF (to_jsonb(NEW)-ARRAY['updater','update_time','revision']) IS DISTINCT FROM
               (to_jsonb(OLD)-ARRAY['updater','update_time','revision']) THEN
                RAISE EXCEPTION '原子指标仍被派生指标引用，不能修改或停用' USING ERRCODE='23514';
            END IF;
        END IF;
        IF TG_OP='DELETE' THEN RETURN OLD; END IF;
        IF NEW.deleted<>0 THEN RETURN NEW; END IF;
        IF NEW.indicator_type='DERIVED' THEN
            IF NOT EXISTS(SELECT 1 FROM dh_modeling_indicator_model WHERE id=NEW.base_indicator_id
                AND deleted=0 AND indicator_type='ATOMIC' AND status='ACTIVE' AND data_domain_id=NEW.data_domain_id) THEN
                RAISE EXCEPTION '派生指标必须关联同一数据域的已启用原子指标' USING ERRCODE='23514';
            END IF;
        ELSE
            SELECT v.fields INTO version_fields FROM dh_modeling_logic_model_version v
                JOIN dh_modeling_logic_model m ON m.id=v.model_id AND m.deleted=0 AND m.status<>'DISCARDED'
                WHERE v.id=NEW.source_version_id AND v.model_id=NEW.source_model_id AND v.deleted=0 AND v.status='PUBLISHED';
            IF NOT FOUND THEN RAISE EXCEPTION '指标来源必须是有效模型的已发布版本' USING ERRCODE='23514'; END IF;
            IF jsonb_typeof(version_fields) IS DISTINCT FROM 'array'
                OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(version_fields) field WHERE field->>'fieldUid'=NEW.value_field_uid)
                OR (NEW.time_field_uid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(version_fields) field WHERE field->>'fieldUid'=NEW.time_field_uid)) THEN
                RAISE EXCEPTION '指标字段不在绑定版本的稳定字段集合中' USING ERRCODE='23514';
            END IF;
        END IF;
    ELSE
        IF TG_OP='UPDATE' THEN
            IF NEW.deleted=0 AND (TG_TABLE_NAME<>'dh_modeling_logic_model' OR to_jsonb(NEW)->>'status'<>'DISCARDED') THEN RETURN NEW; END IF;
        END IF;
        IF EXISTS(SELECT 1 FROM dh_modeling_indicator_model WHERE deleted=0 AND
            CASE WHEN TG_TABLE_NAME='dh_modeling_logic_model' THEN source_model_id=OLD.id ELSE source_version_id=OLD.id END) THEN
            RAISE EXCEPTION '模型版本仍被指标引用，不能删除或废弃' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_indicator_reference_guard() IS '串行保护派生指标、原子指标及已发布来源版本的完整引用';

DO $install_guards$
DECLARE table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_concept_model','dh_modeling_indicator_model'] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS modeling_ownership_reference_guard ON %I',table_name);
        EXECUTE format('CREATE TRIGGER modeling_ownership_reference_guard BEFORE INSERT OR UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION modeling_ownership_reference_guard()',table_name);
    END LOOP;
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_indicator_model','dh_modeling_logic_model','dh_modeling_logic_model_version'] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS modeling_indicator_reference_guard ON %I',table_name);
        EXECUTE format('CREATE TRIGGER modeling_indicator_reference_guard BEFORE %s ON %I FOR EACH ROW EXECUTE FUNCTION modeling_indicator_reference_guard()',
            CASE WHEN table_name='dh_modeling_indicator_model' THEN 'INSERT OR UPDATE OR DELETE' ELSE 'UPDATE OR DELETE' END,table_name);
    END LOOP;
END $install_guards$;

-- 按组件定位建模目录和新菜单，不复用已删除旧概念模型的历史编号及授权。
LOCK TABLE system_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE root_id bigint; planning_id bigint; matches integer; item record; page_id bigint; button_id bigint; action text;
BEGIN
    SELECT count(*),min(parent_id) INTO matches,root_id FROM system_menu
        WHERE deleted=0 AND type=2 AND trim(both '/' from component)='governance/model-home/index';
    IF matches<>1 THEN RAISE EXCEPTION '建模概览菜单缺失或不唯一，禁止猜测新功能目录'; END IF;
    IF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=root_id AND deleted=0 AND type=1) THEN
        RAISE EXCEPTION '建模概览所属目录无效，禁止猜测新功能目录';
    END IF;
    SELECT count(*),min(parent_id) INTO matches,planning_id FROM system_menu
        WHERE deleted=0 AND type=2 AND trim(both '/' from component)='modeling/datadomain/index';
    IF matches>1 THEN RAISE EXCEPTION '数据域菜单不唯一，禁止猜测概念模型目录'; END IF;
    IF matches=1 AND NOT EXISTS(
        WITH RECURSIVE ancestors AS (
            SELECT id,parent_id FROM system_menu WHERE id=planning_id AND deleted=0 AND type=1
            UNION
            SELECT menu.id,menu.parent_id FROM system_menu menu JOIN ancestors child ON child.parent_id=menu.id
                WHERE menu.deleted=0 AND menu.type=1
        ) SELECT 1 FROM ancestors WHERE id=root_id
    ) THEN RAISE EXCEPTION '数据域菜单所属目录不在数据建模下，禁止跨模块创建菜单'; END IF;
    FOR item IN SELECT * FROM (VALUES
        ('概念模型','concept-model','modeling/concept-model/index','ModelingConceptModel','carbon:concept',coalesce(planning_id,root_id),30),
        ('指标模型','indicator-model','modeling/indicator-model/index','ModelingIndicatorModel','carbon:chart-line',root_id,40)
    ) t(label,path,component,component_name,icon,parent_id,sort) LOOP
        SELECT count(*),min(id) INTO matches,page_id FROM system_menu
            WHERE trim(both '/' from component)=item.component OR permission='modeling:'||item.path||':query';
        IF matches>1 THEN RAISE EXCEPTION '新增模型菜单身份重复：%',item.component; END IF;
        IF matches=0 THEN
            SELECT coalesce(max(id),0)+1 INTO page_id FROM system_menu;
            INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,deleted)
            VALUES(page_id,item.label,'modeling:'||item.path||':query',2,item.sort,item.parent_id,item.path,item.icon,item.component,item.component_name,0,true,true,true,'migration:0171','migration:0171',0);
        ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=page_id AND deleted=0 AND type=2 AND parent_id=item.parent_id AND component=item.component AND permission='modeling:'||item.path||':query') THEN
            RAISE EXCEPTION '模型菜单身份冲突，需核查已有菜单：%',page_id;
        END IF;
        FOREACH action IN ARRAY ARRAY['create','update','delete'] LOOP
            SELECT count(*),min(id) INTO matches,button_id FROM system_menu WHERE permission='modeling:'||item.path||':'||action;
            IF matches>1 THEN RAISE EXCEPTION '模型按钮权限重复：%',action; END IF;
            IF matches=0 THEN
                SELECT coalesce(max(id),0)+1 INTO button_id FROM system_menu;
                INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
                VALUES(button_id,item.label||CASE action WHEN 'create' THEN '新增' WHEN 'update' THEN '修改及启停' ELSE '删除' END,
                    'modeling:'||item.path||':'||action,3,0,page_id,'',0,true,true,true,'migration:0171','migration:0171',0);
            ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=button_id AND parent_id=page_id AND type=3 AND deleted=0) THEN
                RAISE EXCEPTION '模型按钮归属冲突：%',button_id;
            END IF;
        END LOOP;
    END LOOP;
    PERFORM setval('system_menu_id_seq',greatest((SELECT last_value FROM system_menu_id_seq),(SELECT max(id) FROM system_menu)));
    PERFORM setval('system_menu_seq',greatest((SELECT last_value FROM system_menu_seq),(SELECT max(id) FROM system_menu)));
END $menus$;
COMMIT;

-- 0176 数据集市门户的最终结构与菜单。
-- Migration: 0176 数据集市类目、门户与资产地图。
-- Purpose: 补齐数据资产集市门户所需的个人收藏、集市导航和菜单权限。
-- Depends on: 0175_dataforge_remove-connection-driver-profile.sql 已执行；资产发布目录和现有集市申请表已存在。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；结构与索引可重放，菜单按组件身份定位，个人收藏与资产记录不被覆盖。
-- Rollback: 单事务失败完整回滚；提交后回退代码前应导出新增收藏与类目数据，按部署前菜单备份恢复导航。
-- 事务边界：结构与菜单变更在同一事务内执行；不删除既有资产、申请、交付和审计记录。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE SEQUENCE IF NOT EXISTS dh_asset_market_category_seq;
CREATE TABLE IF NOT EXISTS dh_asset_market_category (
    id bigint NOT NULL DEFAULT nextval('dh_asset_market_category_seq'),
    parent_id bigint NOT NULL DEFAULT 0,
    name varchar(50) NOT NULL,
    description varchar(256),
    status smallint NOT NULL DEFAULT 0,
    sort integer NOT NULL DEFAULT 0,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT pk_asset_market_category PRIMARY KEY (id),
    CONSTRAINT ck_asset_market_category_status CHECK (status IN (0, 1)),
    CONSTRAINT ck_asset_market_category_deleted CHECK (deleted IN (0, 1)),
    CONSTRAINT ck_asset_market_category_parent CHECK (parent_id >= 0 AND parent_id <> id),
    CONSTRAINT ck_asset_market_category_name CHECK (name = btrim(name) AND name <> ''),
    CONSTRAINT ck_asset_market_category_sort CHECK (sort >= 0)
);
ALTER SEQUENCE dh_asset_market_category_seq OWNED BY dh_asset_market_category.id;
COMMENT ON TABLE dh_asset_market_category IS '数据资产-集市类目';
COMMENT ON COLUMN dh_asset_market_category.id IS '集市类目编号';
COMMENT ON COLUMN dh_asset_market_category.parent_id IS '父集市类目编号，顶级为零';
COMMENT ON COLUMN dh_asset_market_category.name IS '集市类目名称，最多五十个字符';
COMMENT ON COLUMN dh_asset_market_category.description IS '集市类目描述，最多二百五十六个字符';
COMMENT ON COLUMN dh_asset_market_category.status IS '状态：0-启用 1-停用';
COMMENT ON COLUMN dh_asset_market_category.sort IS '显示顺序，非负整数';
COMMENT ON COLUMN dh_asset_market_category.creator IS '创建者';
COMMENT ON COLUMN dh_asset_market_category.create_time IS '创建时间';
COMMENT ON COLUMN dh_asset_market_category.updater IS '更新者';
COMMENT ON COLUMN dh_asset_market_category.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_market_category.deleted IS '是否删除：0-未删除 1-已删除';
CREATE UNIQUE INDEX IF NOT EXISTS uk_asset_market_category_parent_name
    ON dh_asset_market_category(parent_id, name) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_asset_market_category_parent
    ON dh_asset_market_category(parent_id, sort, id) WHERE deleted = 0;

CREATE TABLE IF NOT EXISTS dh_asset_market_listing (
    asset_id bigint NOT NULL,
    market_category_id bigint,
    display_name varchar(256) NOT NULL,
    description varchar(256),
    frequency varchar(64) NOT NULL,
    delivery_types varchar(32) NOT NULL,
    revision bigint NOT NULL DEFAULT 0,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT pk_asset_market_listing PRIMARY KEY (asset_id),
    CONSTRAINT ck_asset_market_listing_deleted CHECK (deleted IN (0, 1)),
    CONSTRAINT ck_asset_market_listing_name CHECK (btrim(display_name) <> ''),
    CONSTRAINT ck_asset_market_listing_revision CHECK (revision >= 0),
    CONSTRAINT ck_asset_market_listing_frequency CHECK (btrim(frequency) <> ''),
    CONSTRAINT ck_asset_market_listing_delivery CHECK (
        delivery_types IN ('1', '2', '3', '1,2', '1,3', '2,3', '1,2,3')
    ),
    CONSTRAINT fk_asset_market_listing_asset FOREIGN KEY (asset_id)
        REFERENCES dh_asset_data_asset(id) ON DELETE CASCADE,
    CONSTRAINT fk_asset_market_listing_category FOREIGN KEY (market_category_id)
        REFERENCES dh_asset_market_category(id) ON DELETE RESTRICT
);
COMMENT ON TABLE dh_asset_market_listing IS '数据资产-集市展示信息';
COMMENT ON COLUMN dh_asset_market_listing.asset_id IS '资产编号；发布状态及版本仍以资产发布目录为准';
COMMENT ON COLUMN dh_asset_market_listing.market_category_id IS '挂载的独立集市类目编号';
COMMENT ON COLUMN dh_asset_market_listing.display_name IS '集市展示名称';
COMMENT ON COLUMN dh_asset_market_listing.description IS '集市描述，最多二百五十六个字符';
COMMENT ON COLUMN dh_asset_market_listing.frequency IS '更新频率';
COMMENT ON COLUMN dh_asset_market_listing.delivery_types IS '交付形态声明：1-数据库表 2-接口 3-文件，升序逗号分隔，不替代交付授权';
COMMENT ON COLUMN dh_asset_market_listing.revision IS '集市展示信息修订号，防止并发发布覆盖，不替代资产目录修订号';
COMMENT ON COLUMN dh_asset_market_listing.creator IS '创建者';
COMMENT ON COLUMN dh_asset_market_listing.create_time IS '创建时间';
COMMENT ON COLUMN dh_asset_market_listing.updater IS '更新者';
COMMENT ON COLUMN dh_asset_market_listing.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_market_listing.deleted IS '是否删除：0-未删除 1-已删除';
CREATE INDEX IF NOT EXISTS idx_asset_market_listing_category
    ON dh_asset_market_listing(market_category_id, asset_id) WHERE deleted = 0;

CREATE SEQUENCE IF NOT EXISTS dh_asset_market_favorite_seq;
CREATE TABLE IF NOT EXISTS dh_asset_market_favorite (
    id bigint NOT NULL DEFAULT nextval('dh_asset_market_favorite_seq'),
    user_id bigint NOT NULL,
    asset_id bigint NOT NULL,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT pk_asset_market_favorite PRIMARY KEY (id),
    CONSTRAINT ck_asset_market_favorite_deleted CHECK (deleted IN (0, 1)),
    CONSTRAINT fk_asset_market_favorite_asset FOREIGN KEY (asset_id)
        REFERENCES dh_asset_data_asset(id) ON DELETE CASCADE
);
ALTER SEQUENCE dh_asset_market_favorite_seq OWNED BY dh_asset_market_favorite.id;
COMMENT ON TABLE dh_asset_market_favorite IS '数据资产-个人集市收藏';
COMMENT ON COLUMN dh_asset_market_favorite.id IS '收藏编号';
COMMENT ON COLUMN dh_asset_market_favorite.user_id IS '收藏用户编号，由当前登录身份提供';
COMMENT ON COLUMN dh_asset_market_favorite.asset_id IS '已发布资产编号';
COMMENT ON COLUMN dh_asset_market_favorite.creator IS '创建者';
COMMENT ON COLUMN dh_asset_market_favorite.create_time IS '收藏时间';
COMMENT ON COLUMN dh_asset_market_favorite.updater IS '更新者';
COMMENT ON COLUMN dh_asset_market_favorite.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_market_favorite.deleted IS '是否删除：0-未删除 1-已删除';
CREATE UNIQUE INDEX IF NOT EXISTS uk_asset_market_favorite_user_asset
    ON dh_asset_market_favorite(user_id, asset_id) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_asset_market_favorite_user
    ON dh_asset_market_favorite(user_id, create_time DESC, id DESC) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_asset_market_favorite_asset
    ON dh_asset_market_favorite(asset_id) WHERE deleted = 0;

-- 页面按组件身份定位，不把旧消费页面的角色授权直接改成草稿管理权限。
LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE
    asset_root bigint;
    market_root bigint;
    matches integer;
    page_id bigint;
    mart_id bigint;
    category_id bigint;
    button_id bigint;
    old_pages bigint[];
    market_sources bigint[];
    manage_sources bigint[];
    category_sources bigint[];
    source_ids bigint[];
    item record;
BEGIN
    SELECT count(*), min(id) INTO matches, asset_root FROM system_menu
    WHERE deleted = 0 AND type = 1 AND trim(both '/' from path) = 'asset' AND parent_id = 0;
    IF matches <> 1 THEN
        RAISE EXCEPTION '数据资产根目录必须唯一，禁止猜测菜单归属';
    END IF;
    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO old_pages FROM system_menu
    WHERE type = 2 AND trim(both '/' from component) IN ('market/overview/index', 'market/resource/index');
    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO market_sources FROM system_menu
    WHERE deleted = 0 AND status = 0 AND permission = 'asset:market:query';
    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO manage_sources FROM system_menu
    WHERE deleted = 0 AND status = 0 AND permission = 'asset:data-asset:query';
    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO category_sources FROM system_menu
    WHERE deleted = 0 AND status = 0 AND permission = 'asset:category-data-asset:query';

    SELECT count(*), min(id) INTO matches, market_root FROM system_menu
    WHERE deleted = 0 AND type = 1 AND trim(both '/' from path) = 'market'
      AND parent_id IN (0, asset_root);
    IF matches > 1 THEN RAISE EXCEPTION '数据集市目录身份冲突'; END IF;
    IF matches = 0 THEN
        SELECT coalesce(max(id), 0) + 1 INTO market_root FROM system_menu;
        INSERT INTO system_menu(id, name, permission, type, sort, parent_id, path, icon,
                                status, visible, keep_alive, always_show, creator, updater, deleted)
        VALUES(market_root, '数据集市', '', 1, 8, asset_root, 'market', 'carbon:store',
               0, true, true, true, 'migration:0176', 'migration:0176', 0);
    ELSE
        UPDATE system_menu SET parent_id = asset_root, path = 'market', name = '数据集市',
            updater = 'migration:0176', update_time = CURRENT_TIMESTAMP WHERE id = market_root;
    END IF;

    FOR item IN SELECT * FROM (VALUES
        ('数据集市', 'mart', 'asset/market/index', 'AssetMarketMart', 'carbon:store', market_root, 1,
         'asset:market:query', market_sources),
        ('资产地图', 'map', 'asset/market/map/index', 'AssetMarketMap', 'carbon:map', market_root, 2,
         'asset:data-asset:query', manage_sources),
        ('集市类目', 'market-category', 'asset/marketcategory/index', 'AssetMarketCategory', 'carbon:categories', asset_root, 9,
         'asset:market-category:query', category_sources)
    ) t(label, path, component, component_name, icon, parent_id, sort, permission, source_ids) LOOP
        SELECT count(*), min(id) INTO matches, page_id FROM system_menu
        WHERE trim(both '/' from component) = item.component;
        IF matches > 1 THEN RAISE EXCEPTION '页面组件身份不唯一：%', item.component; END IF;
        IF matches = 0 THEN
            IF EXISTS(SELECT 1 FROM system_menu WHERE deleted = 0 AND parent_id = item.parent_id AND path = item.path) THEN
                RAISE EXCEPTION '页面路径已被其他功能占用：%', item.path;
            END IF;
            SELECT coalesce(max(id), 0) + 1 INTO page_id FROM system_menu;
            INSERT INTO system_menu(id, name, permission, type, sort, parent_id, path, icon, component,
                                    component_name, status, visible, keep_alive, always_show, creator, updater, deleted)
            VALUES(page_id, item.label, item.permission, 2, item.sort, item.parent_id, item.path, item.icon,
                   item.component, item.component_name, 0, true, true, true, 'migration:0176', 'migration:0176', 0);
        ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id = page_id AND deleted = 0 AND type = 2
                         AND parent_id = item.parent_id AND permission = item.permission AND path = item.path) THEN
            RAISE EXCEPTION '页面归属或权限身份冲突：%', item.component;
        END IF;
        INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
        SELECT (SELECT coalesce(max(id), 0) FROM system_role_menu)
                   + row_number() OVER(ORDER BY pending.role_id, pending.tenant_id),
               pending.role_id, page_id, pending.tenant_id, 'migration:0176', 'migration:0176', 0
        FROM (SELECT DISTINCT old_grant.role_id, old_grant.tenant_id
            FROM system_role_menu old_grant WHERE old_grant.deleted = 0 AND old_grant.menu_id = ANY(item.source_ids)
              AND NOT EXISTS(SELECT 1 FROM system_role_menu current_grant WHERE current_grant.deleted = 0
                  AND current_grant.role_id = old_grant.role_id AND current_grant.tenant_id = old_grant.tenant_id
                  AND current_grant.menu_id = page_id)) pending;
        IF item.component = 'asset/market/index' THEN mart_id = page_id; END IF;
        IF item.component = 'asset/marketcategory/index' THEN category_id = page_id; END IF;
    END LOOP;

    -- 新目录的空权限只承载导航；不能因此授予资产管理或类目维护权限。
    FOREACH page_id IN ARRAY ARRAY[asset_root, market_root] LOOP
        source_ids = market_sources || manage_sources;
        IF page_id = asset_root THEN source_ids = source_ids || category_sources; END IF;
        INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
        SELECT (SELECT coalesce(max(id), 0) FROM system_role_menu)
                   + row_number() OVER(ORDER BY pending.role_id, pending.tenant_id),
               pending.role_id, page_id, pending.tenant_id, 'migration:0176', 'migration:0176', 0
        FROM (SELECT DISTINCT old_grant.role_id, old_grant.tenant_id
            FROM system_role_menu old_grant WHERE old_grant.deleted = 0
              AND old_grant.menu_id = ANY(source_ids)
              AND NOT EXISTS(SELECT 1 FROM system_role_menu current_grant WHERE current_grant.deleted = 0
                  AND current_grant.role_id = old_grant.role_id AND current_grant.tenant_id = old_grant.tenant_id
                  AND current_grant.menu_id = page_id)) pending;
    END LOOP;

    FOR item IN SELECT * FROM (VALUES
        ('收藏资产', 'asset:market:favorite', mart_id, market_sources),
        ('新增集市类目', 'asset:market-category:create', category_id, ARRAY(SELECT id FROM system_menu
            WHERE deleted = 0 AND status = 0 AND permission = 'asset:category-data-asset:create')),
        ('修改集市类目', 'asset:market-category:update', category_id, ARRAY(SELECT id FROM system_menu
            WHERE deleted = 0 AND status = 0 AND permission = 'asset:category-data-asset:update')),
        ('删除集市类目', 'asset:market-category:delete', category_id, ARRAY(SELECT id FROM system_menu
            WHERE deleted = 0 AND status = 0 AND permission = 'asset:category-data-asset:delete'))
    ) t(label, permission, parent_id, source_ids) LOOP
        SELECT count(*), min(id) INTO matches, button_id FROM system_menu WHERE permission = item.permission;
        IF matches > 1 THEN RAISE EXCEPTION '按钮权限重复：%', item.permission; END IF;
        IF matches = 0 THEN
            SELECT coalesce(max(id), 0) + 1 INTO button_id FROM system_menu;
            INSERT INTO system_menu(id, name, permission, type, sort, parent_id, path,
                                    status, visible, keep_alive, always_show, creator, updater, deleted)
            VALUES(button_id, item.label, item.permission, 3, 0, item.parent_id, '',
                   0, true, true, true, 'migration:0176', 'migration:0176', 0);
        ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id = button_id AND deleted = 0
                         AND parent_id = item.parent_id AND type = 3) THEN
            RAISE EXCEPTION '按钮归属冲突：%', item.permission;
        END IF;
        INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
        SELECT (SELECT coalesce(max(id), 0) FROM system_role_menu)
                   + row_number() OVER(ORDER BY pending.role_id, pending.tenant_id),
               pending.role_id, button_id, pending.tenant_id, 'migration:0176', 'migration:0176', 0
        FROM (SELECT DISTINCT old_grant.role_id, old_grant.tenant_id
            FROM system_role_menu old_grant WHERE old_grant.deleted = 0 AND old_grant.menu_id = ANY(item.source_ids)
              AND NOT EXISTS(SELECT 1 FROM system_role_menu current_grant WHERE current_grant.deleted = 0
                  AND current_grant.role_id = old_grant.role_id AND current_grant.tenant_id = old_grant.tenant_id
                  AND current_grant.menu_id = button_id)) pending;
    END LOOP;
    UPDATE system_menu SET parent_id = mart_id, updater = 'migration:0176', update_time = CURRENT_TIMESTAMP
    WHERE parent_id = ANY(old_pages) AND type = 3 AND deleted = 0;
    UPDATE system_menu SET deleted = 1, status = 1, visible = false,
        updater = 'migration:0176', update_time = CURRENT_TIMESTAMP WHERE id = ANY(old_pages) AND deleted = 0;

    IF to_regclass('system_menu_id_seq') IS NOT NULL THEN
        PERFORM setval('system_menu_id_seq', greatest((SELECT last_value FROM system_menu_id_seq), (SELECT max(id) FROM system_menu)));
    END IF;
    IF to_regclass('system_menu_seq') IS NOT NULL THEN
        PERFORM setval('system_menu_seq', greatest((SELECT last_value FROM system_menu_seq), (SELECT max(id) FROM system_menu)));
    END IF;
END $menus$;

COMMIT;


-- 0177 独立资产管理入口退役，细粒度权限与原查询授权由资产地图承接。
-- Migration: 0177 退役独立资产管理入口。
-- Purpose: 由资产地图承接旧资产管理导航和查询授权，保留细粒度按钮编号、原授权及共享资产数据。
-- Depends on: 0176_asset_market-catalog-and-portal.sql 已执行；资产地图及其数据资产、数据集市祖先目录存在。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；按组件身份定位，旧入口删除后再次执行不新增授权、不改套餐、不移动已迁按钮。
-- Rollback: 表变更在单事务内失败回滚；提交后旧入口及其关联不能凭空恢复，须按执行前菜单、角色菜单及套餐备份恢复。
-- 执行前备份三个权限表并停用旧前端实例；不删除资产、注册、详情、申请、交付、类目或其他业务表。
-- 若新增角色授权需推进现有编号序列；序列不回退，异常时可能留下安全跳号，不能据此回退其他会话的编号。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;
DO $retire_asset_management$
DECLARE
    old_id bigint;
    map_id bigint;
    market_root bigint;
    asset_root bigint;
    matches integer;
    old_enabled boolean;
    target_id bigint;
    inserted integer;
    inserted_total integer := 0;
BEGIN
    -- 包括停用和软删除的同组件记录；身份不唯一时不能猜测哪一项属于本功能。
    SELECT count(*), min(id) INTO matches, map_id FROM system_menu
    WHERE trim(both '/' from coalesce(component, '')) = 'asset/market/map/index';
    IF matches <> 1 OR NOT EXISTS (
        SELECT 1 FROM system_menu WHERE id = map_id AND type = 2 AND deleted = 0 AND status = 0
          AND permission = 'asset:data-asset:query' AND trim(both '/' from coalesce(path, '')) = 'map'
    ) THEN
        RAISE EXCEPTION '0177 需要唯一有效且权限正确的资产地图菜单';
    END IF;
    SELECT parent_id INTO market_root FROM system_menu WHERE id = map_id;
    SELECT parent_id INTO asset_root FROM system_menu WHERE id = market_root;
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id = market_root AND type = 1 AND deleted = 0 AND status = 0
                   AND coalesce(permission, '') = '' AND trim(both '/' from coalesce(path, '')) = 'market')
       OR NOT EXISTS (SELECT 1 FROM system_menu WHERE id = asset_root AND type = 1 AND deleted = 0 AND status = 0
                   AND parent_id = 0 AND coalesce(permission, '') = '' AND trim(both '/' from coalesce(path, '')) = 'asset') THEN
        RAISE EXCEPTION '0177 资产地图的无权限导航祖先身份不正确';
    END IF;
    SELECT count(*), min(id) INTO matches, old_id FROM system_menu
    WHERE trim(both '/' from coalesce(component, '')) = 'asset/dataasset/index';
    IF matches > 1 THEN RAISE EXCEPTION '0177 旧资产管理菜单身份不唯一'; END IF;
    IF matches = 0 THEN RETURN; END IF;
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id = old_id AND type = 2
                   AND permission = 'asset:data-asset:query' AND parent_id = asset_root) THEN
        RAISE EXCEPTION '0177 旧资产管理菜单归属或权限不正确';
    END IF;
    SELECT deleted = 0 AND status = 0 INTO old_enabled FROM system_menu WHERE id = old_id;

    -- 所有层级的按钮都保留；出现独立页面或目录子树时中止，避免连带移走未知功能。
    IF EXISTS (
        WITH RECURSIVE descendants AS (
            SELECT id, type FROM system_menu WHERE parent_id = old_id
            UNION
            SELECT child.id, child.type FROM system_menu child JOIN descendants parent ON child.parent_id = parent.id
        ) SELECT 1 FROM descendants WHERE type IS DISTINCT FROM 3
    ) THEN
        RAISE EXCEPTION '0177 旧资产管理下存在未知页面或目录子树，禁止连带清理';
    END IF;
    IF EXISTS (SELECT 1 FROM system_tenant_package WHERE jsonb_typeof(menu_ids::jsonb) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '0177 套餐菜单编号必须为 JSON 数组';
    END IF;

    -- 仅承接原有效查询入口的角色授权；按钮授权和消费市场授权不能派生管理查询权限。
    IF old_enabled THEN
        FOREACH target_id IN ARRAY ARRAY[map_id, market_root, asset_root] LOOP
            INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
            SELECT (SELECT coalesce(max(id), 0) FROM system_role_menu)
                       + row_number() OVER (ORDER BY pending.role_id, pending.tenant_id),
                   pending.role_id, target_id, pending.tenant_id, 'migration:0177', 'migration:0177', 0
            FROM (
                SELECT DISTINCT source.role_id, source.tenant_id FROM system_role_menu source
                WHERE source.menu_id = old_id AND source.deleted = 0
                  AND NOT EXISTS (SELECT 1 FROM system_role_menu current_grant WHERE current_grant.deleted = 0
                      AND current_grant.role_id = source.role_id AND current_grant.tenant_id = source.tenant_id
                      AND current_grant.menu_id = target_id)
            ) pending;
            GET DIAGNOSTICS inserted = ROW_COUNT;
            inserted_total := inserted_total + inserted;
        END LOOP;
    END IF;

    -- 只移动旧入口的直接按钮，按钮后代保留原层级；停用及软删除按钮不恢复状态或授权。
    UPDATE system_menu SET parent_id = map_id, updater = 'migration:0177', update_time = CURRENT_TIMESTAMP
    WHERE parent_id = old_id AND type = 3;

    -- 只处理持有旧页编号的套餐。替换保留数字/字符串类型与其他元素顺序，已含地图时仅去旧编号。
    -- 补入的祖先经过上方空权限校验，仅承载导航；停用旧入口只清理引用，不能恢复管理权限。
    WITH candidates AS (
        SELECT package.id, package.menu_ids::jsonb AS original,
               EXISTS (SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) item(value)
                       WHERE item.value = map_id::text) AS has_map
        FROM system_tenant_package package
        WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) item(value)
                      WHERE item.value = old_id::text)
    ), replacements AS (
        SELECT candidate.id,
               (SELECT coalesce(jsonb_agg(
                   CASE WHEN entry.value #>> '{}' = old_id::text THEN
                       CASE WHEN jsonb_typeof(entry.value) = 'string' THEN to_jsonb(map_id::text) ELSE to_jsonb(map_id) END
                       ELSE entry.value END ORDER BY entry.ordinality), '[]'::jsonb)
                FROM jsonb_array_elements(candidate.original) WITH ORDINALITY entry(value, ordinality)
                WHERE entry.value #>> '{}' IS DISTINCT FROM old_id::text OR (old_enabled AND NOT candidate.has_map)) AS entries
        FROM candidates candidate
    ), navigation AS (
        SELECT replacement.id, replacement.entries
               || CASE WHEN old_enabled AND NOT EXISTS (
                       SELECT 1 FROM jsonb_array_elements_text(replacement.entries) item(value) WHERE item.value = asset_root::text
                   ) THEN to_jsonb(ARRAY[asset_root]) ELSE '[]'::jsonb END
               || CASE WHEN old_enabled AND NOT EXISTS (
                       SELECT 1 FROM jsonb_array_elements_text(replacement.entries) item(value) WHERE item.value = market_root::text
                   ) THEN to_jsonb(ARRAY[market_root]) ELSE '[]'::jsonb END AS entries
        FROM replacements replacement
    )
    UPDATE system_tenant_package package SET menu_ids = navigation.entries::text,
        updater = 'migration:0177', update_time = CURRENT_TIMESTAMP
    FROM navigation WHERE package.id = navigation.id AND package.menu_ids::jsonb IS DISTINCT FROM navigation.entries;

    DELETE FROM system_role_menu WHERE menu_id = old_id;
    DELETE FROM system_menu WHERE id = old_id;
    IF inserted_total > 0 AND to_regclass('system_role_menu_seq') IS NOT NULL THEN
        PERFORM setval('system_role_menu_seq', greatest(
            (SELECT last_value FROM system_role_menu_seq), (SELECT coalesce(max(id), 1) FROM system_role_menu)));
    END IF;
END $retire_asset_management$;
COMMIT;

-- Migration: 0178 拆分公共目录导航与原查询授权。
-- Purpose: 数据集市和资产地图作为登录后公共导航；原查询授权保留为按钮，不派生任何维护、预览或交付权限。
-- Depends on: 0177_asset_retire-standalone-management-menu.sql 已执行；两页及其无权限祖先目录存在。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；仅在页面仍承载原查询权限时迁移授权及套餐，重放不恢复已撤销的按钮、角色授权或套餐能力。
-- Rollback: 单事务内失败回滚；提交后需按执行前权限表备份恢复页面权限、查询按钮和新增关联。序列前进不回退。
-- 应与支持公共导航配置及对象数据范围的新版本同步发布；不执行任何资产数据修改。
-- 执行前停止全部旧版 system 实例及权限写入，菜单编号分配也须停止；迁移提交前不得恢复写入。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $catalog_navigation$
DECLARE
    target record;
    page_id bigint;
    query_id bigint;
    ancestor_id bigint;
    matches integer;
    visited bigint[];
    changed boolean := false;
    migrate_query boolean;
    inserted integer;
    inserted_total integer := 0;
    menu_high_watermark bigint;
BEGIN
    IF EXISTS (SELECT 1 FROM system_tenant_package WHERE jsonb_typeof(menu_ids::jsonb) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '0178 套餐菜单编号必须为 JSON 数组';
    END IF;
    -- 在停写前提下合并表与两套序列的高水位，避免复用已删除菜单的历史编号。
    SELECT coalesce(max(id), 0) INTO menu_high_watermark FROM system_menu;
    IF to_regclass('system_menu_seq') IS NOT NULL THEN
        SELECT greatest(menu_high_watermark, last_value) INTO menu_high_watermark FROM system_menu_seq;
    END IF;
    IF to_regclass('system_menu_id_seq') IS NOT NULL THEN
        SELECT greatest(menu_high_watermark, last_value) INTO menu_high_watermark FROM system_menu_id_seq;
    END IF;
    FOR target IN SELECT * FROM (VALUES
        ('asset/market/index', 'AssetMarketMart', 'asset:market:query', '集市接口查询'),
        ('asset/market/map/index', 'AssetMarketMap', 'asset:data-asset:query', '资产管理查询')
    ) AS targets(component, component_name, permission, name)
    LOOP
        SELECT count(*), min(id) INTO matches, page_id FROM system_menu
        WHERE trim(both '/' from coalesce(component, '')) = target.component;
        IF matches <> 1 OR NOT EXISTS (
            SELECT 1 FROM system_menu WHERE id = page_id AND type = 2 AND deleted = 0
                AND component_name = target.component_name AND permission IN ('', target.permission)
        ) THEN
            RAISE EXCEPTION '0178 目录页面身份或原查询权限不正确：%', target.component;
        END IF;
        SELECT permission = target.permission INTO migrate_query FROM system_menu WHERE id = page_id;
        SELECT parent_id INTO ancestor_id FROM system_menu WHERE id = page_id;
        visited := ARRAY[page_id];
        WHILE ancestor_id <> 0 LOOP
            IF ancestor_id = ANY(visited) OR NOT EXISTS (
                SELECT 1 FROM system_menu WHERE id = ancestor_id AND type = 1 AND deleted = 0 AND permission = ''
            ) THEN
                RAISE EXCEPTION '0178 公共目录祖先必须为无权限目录且不能成环：%', target.component;
            END IF;
            visited := array_append(visited, ancestor_id);
            SELECT parent_id INTO ancestor_id FROM system_menu WHERE id = ancestor_id;
        END LOOP;

        SELECT count(*), min(id) INTO matches, query_id FROM system_menu
        WHERE parent_id = page_id AND type = 3 AND permission = target.permission;
        IF matches > 1 THEN RAISE EXCEPTION '0178 查询权限按钮身份不唯一：%', target.permission; END IF;
        -- 页面已转为公共导航后，不因人工删除查询按钮而重新创建；软删除与停用状态也保持原样。
        IF matches = 0 AND NOT migrate_query THEN CONTINUE; END IF;
        IF matches = 0 THEN
            menu_high_watermark := menu_high_watermark + 1;
            query_id := menu_high_watermark;
            INSERT INTO system_menu(id, name, permission, type, sort, parent_id, status, visible, creator, updater)
            SELECT query_id, target.name, target.permission, 3, 0, page_id, status, false, 'migration:0178', 'migration:0178'
            FROM system_menu WHERE id = page_id;
            changed := true;
        END IF;

        IF migrate_query THEN
            -- 原页面权限作为一次性迁移标记；重放不能从公共导航授权恢复已撤销的查询授权。
            INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
            SELECT (SELECT coalesce(max(id), 0) FROM system_role_menu)
                       + row_number() OVER (ORDER BY pending.role_id, pending.tenant_id),
                   pending.role_id, query_id, pending.tenant_id, 'migration:0178', 'migration:0178', 0
            FROM (
                SELECT DISTINCT original.role_id, original.tenant_id FROM system_role_menu original
                WHERE original.menu_id = page_id AND original.deleted = 0
                    AND NOT EXISTS (SELECT 1 FROM system_role_menu current_grant
                        WHERE current_grant.role_id = original.role_id AND current_grant.tenant_id = original.tenant_id
                            AND current_grant.menu_id = query_id AND current_grant.deleted = 0)
            ) pending;
            GET DIAGNOSTICS inserted = ROW_COUNT;
            inserted_total := inserted_total + inserted;

            -- 查询能力从页面迁入按钮时同步套餐许可，保留已有元素及顺序，不扩大其他套餐。
            UPDATE system_tenant_package package
            SET menu_ids = (package.menu_ids::jsonb || to_jsonb(query_id))::text,
                updater = 'migration:0178', update_time = CURRENT_TIMESTAMP
            WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) item(value)
                          WHERE item.value = page_id::text)
                AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) item(value)
                                WHERE item.value = query_id::text);
        END IF;

        UPDATE system_menu SET permission = '', updater = 'migration:0178', update_time = CURRENT_TIMESTAMP
        WHERE id = page_id AND permission <> '';
    END LOOP;
    IF changed THEN
        -- 菜单同时存在 ORM 与数据库默认序列，只前进到当前最大编号，避免后续主键冲突。
        IF to_regclass('system_menu_seq') IS NOT NULL THEN
            PERFORM setval('system_menu_seq', greatest((SELECT last_value FROM system_menu_seq),
                (SELECT max(id) FROM system_menu)));
        END IF;
        IF to_regclass('system_menu_id_seq') IS NOT NULL THEN
            PERFORM setval('system_menu_id_seq', greatest((SELECT last_value FROM system_menu_id_seq),
                (SELECT max(id) FROM system_menu)));
        END IF;
    END IF;
    IF inserted_total > 0 AND to_regclass('system_role_menu_seq') IS NOT NULL THEN
        PERFORM setval('system_role_menu_seq', greatest((SELECT last_value FROM system_role_menu_seq),
            (SELECT coalesce(max(id), 1) FROM system_role_menu)));
    END IF;
END $catalog_navigation$;
COMMIT;

-- Migration: 0179 恢复数据集市和资产地图的角色菜单配置。
-- Purpose: 以当前查询按钮授权与套餐许可收敛页面授权，撤销公共导航拆分，不扩大查询或任何写权限。
-- Depends on: 0177_asset_retire-standalone-management-menu.sql 已执行；兼容已执行或未执行 0178 的页面状态，不要求补跑 0178。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；仅页面权限为空时补偿，恢复原查询权限后重放不新增授权、不恢复撤销、不再次调整套餐。
-- Rollback: 单事务失败完整回滚；提交后不自动恢复已收敛的导航授权，须按执行前菜单、角色菜单和套餐备份恢复。序列前进不回退。
-- 执行前停止全部旧版 system 实例、权限写入与编号分配，备份三个权限表；按有序迁移执行，禁止重放 0178 来回退本脚本。
-- 与移除公共导航白名单的新版本同步发布；可能移除无有效查询授权的旧导航关联，不修改资产数据或写权限按钮。
-- 原始 SQL 不触发 Spring 缓存失效；提交后按部署真实 Redis 前缀及租户后缀清除 permission_menu_ids 中两个查询权限的缓存。
-- 同时清除页面、查询来源及所补祖先涉及的 menu_role_ids 缓存键，再重启相关服务清理本地权限缓存。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $restore_role_navigation$
DECLARE
    target record;
    page_id bigint;
    ancestor_id bigint;
    matches integer;
    visited bigint[];
    active_query_ids bigint[];
    retired_query_ids bigint[];
    role_high_watermark bigint;
    inserted integer;
    inserted_total integer := 0;
BEGIN
    SELECT coalesce(max(id), 0) INTO role_high_watermark FROM system_role_menu;
    IF to_regclass('system_role_menu_seq') IS NOT NULL THEN
        SELECT greatest(role_high_watermark, last_value) INTO role_high_watermark FROM system_role_menu_seq;
    END IF;
    FOR target IN SELECT * FROM (VALUES
        ('asset/market/index', 'AssetMarketMart', 'asset:market:query', '集市接口查询'),
        ('asset/market/map/index', 'AssetMarketMap', 'asset:data-asset:query', '资产管理查询')
    ) AS targets(component, component_name, permission, name)
    LOOP
        SELECT count(*), min(id) INTO matches, page_id FROM system_menu
        WHERE trim(both '/' from coalesce(component, '')) = target.component;
        IF matches <> 1 OR NOT EXISTS (
            SELECT 1 FROM system_menu WHERE id = page_id AND type = 2 AND deleted = 0
                AND component_name = target.component_name AND permission IN ('', target.permission)
        ) THEN
            RAISE EXCEPTION '0179 页面身份或查询权限不正确：%', target.component;
        END IF;
        -- 未执行公共导航拆分，或已经补偿的页面不做权限写入，避免重放恢复人工撤销。
        IF EXISTS (SELECT 1 FROM system_menu WHERE id = page_id AND permission = target.permission) THEN
            CONTINUE;
        END IF;
        SELECT parent_id INTO ancestor_id FROM system_menu WHERE id = page_id;
        visited := ARRAY[page_id];
        WHILE ancestor_id <> 0 LOOP
            IF ancestor_id = ANY(visited) OR NOT EXISTS (
                SELECT 1 FROM system_menu WHERE id = ancestor_id AND type = 1 AND deleted = 0 AND permission = ''
            ) THEN
                RAISE EXCEPTION '0179 页面祖先必须为无权限目录且不能成环：%', target.component;
            END IF;
            visited := array_append(visited, ancestor_id);
            SELECT parent_id INTO ancestor_id FROM system_menu WHERE id = ancestor_id;
        END LOOP;
        IF EXISTS (SELECT 1 FROM system_tenant_package WHERE jsonb_typeof(menu_ids::jsonb) IS DISTINCT FROM 'array') THEN
            RAISE EXCEPTION '0179 套餐菜单编号必须为 JSON 数组';
        END IF;

        SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO active_query_ids FROM system_menu
        WHERE permission = target.permission AND status = 0 AND deleted = 0;
        -- 只有来源、审计时间与初始形状均未变化且没有后代的迁移按钮可退役，人工节点保持原样。
        SELECT coalesce(array_agg(menu.id), ARRAY[]::bigint[]) INTO retired_query_ids FROM system_menu menu
        JOIN system_menu page ON page.id = page_id
        WHERE menu.parent_id = page_id AND menu.type = 3 AND menu.permission = target.permission AND menu.deleted = 0
            AND menu.creator = 'migration:0178' AND menu.updater = 'migration:0178'
            AND menu.create_time = menu.update_time AND menu.name = target.name AND menu.sort = 0
            AND menu.status = page.status AND menu.visible = false AND menu.keep_alive = true AND menu.always_show = true
            AND menu.path = '' AND menu.icon = '#' AND menu.component IS NULL AND menu.component_name IS NULL
            AND NOT EXISTS (SELECT 1 FROM system_menu child WHERE child.parent_id = menu.id);

        -- 旧公共页面只承载导航，必须先删除没有当前查询授权的关联，不能直接恢复其权限。
        UPDATE system_role_menu page_grant SET deleted = 1, updater = 'migration:0179', update_time = CURRENT_TIMESTAMP
        WHERE page_grant.menu_id = page_id AND page_grant.deleted = 0 AND NOT EXISTS (
            SELECT 1 FROM system_role_menu query_grant WHERE query_grant.menu_id = ANY(active_query_ids)
                AND query_grant.deleted = 0 AND query_grant.role_id = page_grant.role_id
                AND query_grant.tenant_id = page_grant.tenant_id
        );
        INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
        SELECT role_high_watermark + row_number() OVER (ORDER BY pending.role_id, pending.tenant_id, pending.menu_id),
               pending.role_id, pending.menu_id, pending.tenant_id, 'migration:0179', 'migration:0179', 0
        FROM (
            -- 相同权限的现有查询来源只补页面和空权限祖先，保持全仓同权限授权的或关系。
            SELECT DISTINCT query_grant.role_id, query_grant.tenant_id, navigation.id AS menu_id
            FROM system_role_menu query_grant CROSS JOIN unnest(visited) navigation(id)
            WHERE query_grant.menu_id = ANY(active_query_ids) AND query_grant.deleted = 0
                AND NOT EXISTS (SELECT 1 FROM system_role_menu page_grant
                    WHERE page_grant.menu_id = navigation.id AND page_grant.deleted = 0
                        AND page_grant.role_id = query_grant.role_id AND page_grant.tenant_id = query_grant.tenant_id)
        ) pending;
        GET DIAGNOSTICS inserted = ROW_COUNT;
        inserted_total := inserted_total + inserted;
        role_high_watermark := role_high_watermark + inserted;

        -- 套餐按当前查询许可收敛；保留其余元素的类型和顺序，只清理本次明确退役的按钮引用。
        WITH allowances AS (
            SELECT package.id, package.menu_ids::jsonb AS original,
                EXISTS (SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
                        WHERE entry.value = ANY(active_query_ids::text[])) AS has_query
            FROM system_tenant_package package
        ), cleaned AS (
            SELECT allowance.id, allowance.has_query,
                (SELECT coalesce(jsonb_agg(entry.value ORDER BY entry.ordinality), '[]'::jsonb)
                 FROM jsonb_array_elements(allowance.original) WITH ORDINALITY entry(value, ordinality)
                 WHERE coalesce(NOT (entry.value #>> '{}' = ANY(retired_query_ids::text[])), true)
                    AND (entry.value #>> '{}' IS DISTINCT FROM page_id::text OR allowance.has_query)) AS entries
            FROM allowances allowance
        ), restored AS (
            SELECT cleaned.id, cleaned.entries || CASE WHEN cleaned.has_query THEN to_jsonb(ARRAY(
                SELECT navigation.id FROM unnest(visited) WITH ORDINALITY navigation(id, position)
                WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(cleaned.entries) entry(value)
                                  WHERE entry.value = navigation.id::text)
                ORDER BY navigation.position DESC
            )) ELSE '[]'::jsonb END AS entries FROM cleaned
        )
        UPDATE system_tenant_package package SET menu_ids = restored.entries::text,
            updater = 'migration:0179', update_time = CURRENT_TIMESTAMP
        FROM restored WHERE package.id = restored.id AND package.menu_ids::jsonb IS DISTINCT FROM restored.entries;

        UPDATE system_role_menu SET deleted = 1, updater = 'migration:0179', update_time = CURRENT_TIMESTAMP
        WHERE menu_id = ANY(retired_query_ids) AND deleted = 0;
        UPDATE system_menu SET deleted = 1, updater = 'migration:0179', update_time = CURRENT_TIMESTAMP
        WHERE id = ANY(retired_query_ids) AND deleted = 0;
        UPDATE system_menu SET permission = target.permission, updater = 'migration:0179', update_time = CURRENT_TIMESTAMP
        WHERE id = page_id AND permission = '';
    END LOOP;
    IF inserted_total > 0 AND to_regclass('system_role_menu_seq') IS NOT NULL THEN
        PERFORM setval('system_role_menu_seq', greatest((SELECT last_value FROM system_role_menu_seq), role_high_watermark));
    END IF;
END $restore_role_navigation$;
COMMIT;

-- Migration: 0180 删除智能落标、跨系统码值映射和血缘能力。
-- Purpose: 清理三个退役工作台及其权限、授权、套餐引用、推荐专属数据、码值映射和血缘持久化与调度配置。
-- Depends on: 0179_asset_restore-role-catalog-navigation.sql 已执行；正式落标映射、标准码集和标准码项继续保留。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql，不操作外部业务库或独立调度中心库。
-- Repeatable: 是；对象按组件、权限或精确对象名清理，缺失对象不重建，不影响其余菜单、数据与任务。
-- Rollback: 单事务失败完整回滚；提交后推荐证据、码值映射和血缘数据不可恢复，必须用执行前整表及权限表备份恢复，不能靠重跑旧迁移恢复数据。
-- 执行前停止治理、研发和建模旧实例及相关任务，备份被删表、菜单、角色菜单、套餐和任务配置；存在未知依赖时以 RESTRICT 中止，禁止使用 CASCADE 绕过。
-- 与删除相关接口和执行路径的新代码同步发布；独立调度中心也须停用三个退役处理器，禁止旧实例在表删除后继续写入。
-- 原始 SQL 不触发 Spring 缓存失效；提交后按真实 Redis 前缀清理受影响的 permission_menu_ids、menu_role_ids，并重启相关服务清除本地权限缓存。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $retire_governance_workbenches$
DECLARE
    retired_ids bigint[];
BEGIN
    IF EXISTS (SELECT 1 FROM system_tenant_package WHERE jsonb_typeof(menu_ids::jsonb) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '0180 套餐菜单编号必须为 JSON 数组';
    END IF;
    WITH RECURSIVE roots AS (
        SELECT menu.id FROM system_menu menu WHERE trim(both '/' from coalesce(menu.component, '')) IN (
            'governance/standardmapping/index', 'governance/standardcodemapping/index', 'governance/lineage/index')
        UNION
        SELECT menu.id FROM system_menu menu JOIN system_menu parent ON parent.id = menu.parent_id
        WHERE menu.type = 1 AND menu.name = '数据血缘' AND trim(both '/' from coalesce(menu.path, '')) = 'lineage'
            AND coalesce(menu.permission, '') = '' AND parent.type = 1 AND parent.parent_id = 0
            AND trim(both '/' from coalesce(parent.path, '')) IN ('govern', 'governance')
        UNION
        SELECT id FROM system_menu WHERE type = 3 AND (
            permission LIKE 'governance:standard-mapping:%' OR permission LIKE 'governance:standard-code-mapping:%'
            OR permission LIKE 'governance:lineage:%' OR permission = 'asset:data-asset:lineage')
    ), descendants AS (
        SELECT id FROM roots
        UNION
        SELECT child.id FROM system_menu child JOIN descendants parent ON child.parent_id = parent.id
    ) SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO retired_ids FROM descendants;

    IF EXISTS (SELECT 1 FROM system_menu WHERE id = ANY(retired_ids) AND type IN (1, 2)
        AND trim(both '/' from coalesce(component, '')) NOT IN (
            'governance/standardmapping/index', 'governance/standardcodemapping/index', 'governance/lineage/index')
        AND NOT (type = 1 AND name = '数据血缘' AND trim(both '/' from coalesce(path, '')) = 'lineage'
                 AND coalesce(permission, '') = '')) THEN
        RAISE EXCEPTION '0180 退役菜单包含未知页面或目录，禁止连带删除';
    END IF;
    -- 仅移除精确退役编号；保留其他元素的类型、顺序、重复项以及未知 JSON 元素。
    WITH cleaned AS (
        SELECT package.id,
            (SELECT coalesce(jsonb_agg(entry.value ORDER BY entry.ordinality), '[]'::jsonb)
             FROM jsonb_array_elements(package.menu_ids::jsonb) WITH ORDINALITY entry(value, ordinality)
             WHERE NOT EXISTS (SELECT 1 FROM unnest(retired_ids) retired(id)
                               WHERE entry.value #>> '{}' = retired.id::text)) AS entries
        FROM system_tenant_package package
    )
    UPDATE system_tenant_package package SET menu_ids = cleaned.entries::text,
        updater = 'migration:0180', update_time = CURRENT_TIMESTAMP
    FROM cleaned WHERE package.id = cleaned.id AND package.menu_ids::jsonb IS DISTINCT FROM cleaned.entries;
    DELETE FROM system_role_menu WHERE menu_id = ANY(retired_ids);
    DELETE FROM system_menu WHERE id = ANY(retired_ids);
END $retire_governance_workbenches$;

-- 推荐运行与候选仅供已删除的智能推荐工作台使用；正式手工落标事实保留。
DROP TABLE IF EXISTS dh_governance_standard_mapping_candidate RESTRICT;
DROP TABLE IF EXISTS dh_governance_standard_mapping_recommend_run RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_standard_mapping_candidate_seq RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_standard_mapping_recommend_run_seq RESTRICT;
-- 跨系统码值映射能力全部退役，引用的标准码集、标准码项及其数据保留。
DROP TABLE IF EXISTS dh_governance_standard_code_mapping RESTRICT;
DROP TABLE IF EXISTS dh_governance_standard_source_code_set RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_standard_code_mapping_seq RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_standard_source_code_set_seq RESTRICT;
-- 治理血缘及研发专属投递记录全部退役，其余同步、ETL 运行和质量记录保留。
DROP TABLE IF EXISTS dh_governance_lineage_relation RESTRICT;
DROP TABLE IF EXISTS dh_governance_lineage_node RESTRICT;
DROP TABLE IF EXISTS dh_governance_lineage_event_outbox RESTRICT;
DROP TABLE IF EXISTS dh_governance_lineage_apply_watermark RESTRICT;
DROP TABLE IF EXISTS dh_dataforge_access_lineage RESTRICT;
DROP TABLE IF EXISTS dh_dataforge_etl_lineage_delivery RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_lineage_relation_seq RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_lineage_node_seq RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_lineage_event_outbox_seq RESTRICT;
DROP SEQUENCE IF EXISTS dh_governance_lineage_apply_watermark_seq RESTRICT;
DROP SEQUENCE IF EXISTS dh_dataforge_etl_lineage_delivery_seq RESTRICT;
-- 已退役 framework 血缘组件的旧持久化对象，只处理平台当前 schema 中的精确对象名。
DROP TABLE IF EXISTS data_lineage_relation RESTRICT;
DROP TABLE IF EXISTS data_blood_column RESTRICT;
DROP TABLE IF EXISTS data_lineage_node RESTRICT;
DROP TABLE IF EXISTS data_blood_tb RESTRICT;
DROP SEQUENCE IF EXISTS seq_data_lineage_relation_id RESTRICT;
DROP SEQUENCE IF EXISTS seq_data_lineage_node_id RESTRICT;
-- 仅移除建模部署记录的血缘专属列，元数据登记状态、计划与执行证据继续保留。
ALTER TABLE IF EXISTS dh_modeling_deploy_record
    DROP COLUMN IF EXISTS lineage_status RESTRICT,
    DROP COLUMN IF EXISTS lineage_error RESTRICT,
    DROP COLUMN IF EXISTS lineage_reported_at RESTRICT,
    DROP COLUMN IF EXISTS lineage_payload RESTRICT;

DO $retire_lineage_jobs$
BEGIN
    IF to_regclass('infra_job') IS NOT NULL THEN
        DELETE FROM infra_job WHERE handler_name IN (
            'accessLineageDeliveryJob', 'governanceLineageOutboxRelayJob', 'modelingLineageReconcileJob');
    END IF;
    -- 注册移除后旧画布由新执行器显式拒绝，不把标准映射节点静默改写为普通转换。
    IF to_regclass('dh_dataforge_etl_tool') IS NOT NULL THEN
        DELETE FROM dh_dataforge_etl_tool WHERE code = 'standard-map';
    END IF;
END $retire_lineage_jobs$;
COMMIT;

-- Migration: 0181 删除数据资产统计和资产使用情况页面。
-- Purpose: 清理两个退役看板、专属按钮及角色和套餐引用，移除清理后空置的数据资产监控目录。
-- Depends on: 0180_governance_remove-retired-workbenches.sql 已执行；平台三张菜单权限表已存在。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；按组件和专属按钮权限识别，不依赖固定编号，重放不改动其他授权或审计字段。
-- Rollback: 单事务失败完整回滚；提交后菜单和授权配置须从执行前的三张权限表备份恢复。
-- 执行前备份菜单、角色菜单和套餐表，暂停这些配置的维护，并与移除看板的新前后端同步发布。
-- 本迁移只删除菜单配置；资产、申请、交付、使用日志及领域审计数据全部保留。
-- 提交后按部署真实 Redis 前缀清理受影响的 permission_menu_ids、menu_role_ids 缓存，并重新登录刷新菜单。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $retire_asset_monitor_pages$
DECLARE
    retired_ids bigint[];
    empty_directory_ids bigint[];
BEGIN
    IF EXISTS (SELECT 1 FROM system_tenant_package WHERE json_typeof(menu_ids::json) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '0181 套餐菜单编号必须为 JSON 数组';
    END IF;
    WITH RECURSIVE roots AS (
        SELECT id FROM system_menu WHERE trim(both '/' from coalesce(component, '')) IN (
            'asset/monitor/statistics/index', 'asset/monitor/usage/index')
        UNION
        SELECT id FROM system_menu WHERE type = 3 AND permission = 'asset:monitor:query'
    ), descendants AS (
        SELECT id FROM roots
        UNION
        SELECT child.id FROM system_menu child JOIN descendants parent ON child.parent_id = parent.id
    ) SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO retired_ids FROM descendants;

    -- 专用按钮随页面移除；出现其他页面、目录或异常类型时整笔中止，避免连带删除。
    IF EXISTS (SELECT 1 FROM system_menu WHERE id = ANY(retired_ids) AND NOT (
        type = 3 OR (type = 2 AND trim(both '/' from coalesce(component, '')) IN (
            'asset/monitor/statistics/index', 'asset/monitor/usage/index')))) THEN
        RAISE EXCEPTION '0181 退役看板下包含未知页面或目录，禁止连带删除';
    END IF;

    -- 仅清理资产根目录下无剩余子项的监控目录；保留仍承载其他菜单的目录及授权。
    SELECT coalesce(array_agg(directory.id), ARRAY[]::bigint[]) INTO empty_directory_ids
    FROM system_menu directory JOIN system_menu parent ON parent.id = directory.parent_id
    WHERE directory.type = 1 AND trim(both '/' from coalesce(directory.path, '')) = 'monitor'
        AND coalesce(directory.component, '') = '' AND coalesce(directory.permission, '') = ''
        AND parent.type = 1 AND parent.parent_id = 0
        AND trim(both '/' from coalesce(parent.path, '')) = 'asset'
        AND NOT EXISTS (SELECT 1 FROM system_menu child
                        WHERE child.parent_id = directory.id AND NOT (child.id = ANY(retired_ids)));
    retired_ids := retired_ids || empty_directory_ids;

    -- 使用 json 保留其他元素的原始表示；紧凑拼接不会因 JSONB 格式化扩大套餐字段长度。
    WITH cleaned AS (
        SELECT package.id,
            (SELECT '[' || coalesce(string_agg(entry.value::text, ',' ORDER BY entry.ordinality), '') || ']'
             FROM json_array_elements(package.menu_ids::json) WITH ORDINALITY entry(value, ordinality)
             WHERE NOT EXISTS (SELECT 1 FROM unnest(retired_ids) retired(id)
                               WHERE entry.value #>> '{}' = retired.id::text)) AS entries
        FROM system_tenant_package package
    )
    UPDATE system_tenant_package package SET menu_ids = cleaned.entries,
        updater = 'migration:0181', update_time = CURRENT_TIMESTAMP
    FROM cleaned WHERE package.id = cleaned.id AND package.menu_ids::jsonb IS DISTINCT FROM cleaned.entries::jsonb;
    DELETE FROM system_role_menu WHERE menu_id = ANY(retired_ids);
    DELETE FROM system_menu WHERE id = ANY(retired_ids);
END $retire_asset_monitor_pages$;
COMMIT;

-- Migration: 0182 元数据维护并发凭据与标准版本质量模板。
-- Purpose: 防止旧表单覆盖治理属性，隔离已确认删除对象的重建身份，修复物理命名空间，按标准版本区分质量模板并统一登记长整型引用。
-- Depends on: 0181_asset_remove-monitor-pages.sql 已执行；平台已完成单租户改造，元数据和标准质量表已存在。
-- Target: 已有 PostgreSQL 平台库；全新数据库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；列和检查约束按名称保护，索引在事务内重建，菜单按组件精确更新。
-- Rollback: 事务失败完整回滚；提交后回滚应用前应先停止维护与采集，不得缩窄登记编号、清空已修正命名空间或重置并发凭据。
-- 索引重建和字段类型扩展需要短时表锁；应在应用停止写入时执行，超时则整笔回滚并择期重试。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_governance_meta_table ADD COLUMN IF NOT EXISTS biz_revision integer NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_governance_meta_table.biz_revision IS '表业务属性并发修订号，独立于采集结构版本';
ALTER TABLE dh_governance_meta_db ADD COLUMN IF NOT EXISTS tag_revision integer NOT NULL DEFAULT 0;
ALTER TABLE dh_governance_meta_table ADD COLUMN IF NOT EXISTS tag_revision integer NOT NULL DEFAULT 0;
ALTER TABLE dh_governance_meta_column ADD COLUMN IF NOT EXISTS tag_revision integer NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_governance_meta_db.tag_revision IS '数据库元数据标签集合并发修订号';
COMMENT ON COLUMN dh_governance_meta_table.tag_revision IS '表元数据标签集合并发修订号';
COMMENT ON COLUMN dh_governance_meta_column.tag_revision IS '字段元数据标签集合并发修订号';

-- 已确认删除的对象保留为历史墓碑；同名对象再次采集时必须生成新的编号和资源标识。
-- 待确认删除对象仍占自然键，允许采集恢复同一身份；仅状态三释放自然键。
DROP INDEX IF EXISTS uk_dh_governance_meta_db_natural_key;
CREATE UNIQUE INDEX uk_dh_governance_meta_db_natural_key
    ON dh_governance_meta_db (datasource_id, db_name, schema_name)
    WHERE deleted = 0 AND object_status <> 3;
DROP INDEX IF EXISTS uk_dh_governance_meta_table_natural_key;
CREATE UNIQUE INDEX uk_dh_governance_meta_table_natural_key
    ON dh_governance_meta_table (db_id, table_name)
    WHERE deleted = 0 AND object_status <> 3;
DROP INDEX IF EXISTS uk_dh_governance_meta_column_natural_key;
CREATE UNIQUE INDEX uk_dh_governance_meta_column_natural_key
    ON dh_governance_meta_column (table_id, column_name)
    WHERE deleted = 0 AND object_status <> 3;

-- 旧采集、手工登记及导入统一把关系命名空间传为库分组名称，却遗漏 schema_name。
-- 按该生产者契约恢复已保存的精确名称，保留编号、URN、标签及映射；不猜默认 schema。
-- 同一自然键若已有另一活动身份，必须停止迁移并核对，不自动合并历史对象。
DO $p0_namespaces$
BEGIN
    IF EXISTS (
        SELECT 1 FROM dh_governance_meta_db legacy
        JOIN dh_governance_meta_db current_db
          ON current_db.datasource_id = legacy.datasource_id
         AND current_db.db_name = legacy.db_name
         AND current_db.schema_name = legacy.db_name
         AND current_db.id <> legacy.id
         AND current_db.deleted = 0 AND current_db.object_status <> 3
        WHERE legacy.deleted = 0 AND legacy.object_status <> 3
          AND legacy.origin IN (1, 2, 3) AND legacy.schema_name = ''
          AND btrim(legacy.db_name) <> ''
    ) THEN
        RAISE EXCEPTION '元数据库命名空间回填发现不同活动身份冲突，请核对后重新执行0182；禁止自动合并'
            USING ERRCODE = '23505';
    END IF;
END $p0_namespaces$;
UPDATE dh_governance_meta_db
SET schema_name = db_name, updater = 'migration:0182', update_time = CURRENT_TIMESTAMP
WHERE deleted = 0 AND origin IN (1, 2, 3) AND schema_name = '' AND btrim(db_name) <> '';
COMMENT ON COLUMN dh_governance_meta_db.schema_name IS 'DB Switch关系命名空间；schema型产品保存schema，catalog型产品保存catalog，与读取表时的输入一致';

-- 标准登记主键为长整型，数据元引用必须能无损保存同一编号。
ALTER TABLE dh_governance_standard_element ALTER COLUMN document_id TYPE bigint USING document_id::bigint;
COMMENT ON COLUMN dh_governance_standard_element.document_id IS '来源标准登记编号，与标准登记长整型主键保持一致';

-- 相同约束在多个发布版本中各有不可变模板，不能用新版本刷新旧版本的模板参数。
DROP INDEX IF EXISTS uk_dh_governance_quality_rule_std_constraint;
CREATE UNIQUE INDEX uk_dh_governance_quality_rule_std_constraint
    ON dh_governance_quality_rule (standard_element_id, element_version, constraint_hash)
    WHERE deleted = 0 AND standard_element_id IS NOT NULL;
COMMENT ON COLUMN dh_governance_quality_rule.constraint_hash IS '冻结约束哈希，与标准编号和固定发布版本共同构成模板幂等键';
DO $p0_checks$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid = 'dh_governance_quality_rule'::regclass
                   AND conname = 'ck_quality_standard_template_identity') THEN
        ALTER TABLE dh_governance_quality_rule ADD CONSTRAINT ck_quality_standard_template_identity
            CHECK (standard_element_id IS NULL OR
                   (element_version IS NOT NULL AND element_version > 0
                    AND constraint_hash IS NOT NULL AND constraint_hash ~ '^[0-9a-f]{64}$'));
    END IF;
END $p0_checks$;

-- 仅调整现有入口名称；任务、实例、最新观测和已发布快照继续各自拥有独立页面及权限。
UPDATE system_menu SET name = '最新元数据（库表）', updater = 'migration:0182', update_time = CURRENT_TIMESTAMP
WHERE deleted = 0 AND type = 2 AND trim(both '/' from component) = 'governance/metaobject/index'
  AND name IS DISTINCT FROM '最新元数据（库表）';
UPDATE system_menu SET name = '定版元数据', updater = 'migration:0182', update_time = CURRENT_TIMESTAMP
WHERE deleted = 0 AND type = 2 AND trim(both '/' from component) = 'governance/metapublished/index'
  AND name IS DISTINCT FROM '定版元数据';
COMMIT;

-- Migration: 0184 将我的资产作为数据资产下的独立菜单创建。
-- Purpose: 修复0183依赖固定数据集市父目录的问题，保留管理员已有菜单排列，仅在数据资产根目录末尾新增我的资产。
-- Depends on: 0182_governance_metadata-standard-p0.sql 已完成；0183_asset_my-assets.sql 可以已完成或因自定义菜单整体回滚，无需先重跑0183。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；已存在的我的资产只校验身份与数据资产归属，不补授权、不恢复人工停用或软删除、不移动位置。
-- Rollback: 单事务失败完整回滚；提交后按执行前权限表备份恢复新增菜单和授权，序列前进不回退，不修改资产或批准记录。
-- 执行前回滚此前失败事务，停止菜单、角色、套餐写入与编号分配并备份权限表；提交后刷新权限缓存并重新登录。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE INDEX IF NOT EXISTS idx_market_my_approved_assets
    ON dh_market_resource_apply (apply_user_id, create_time DESC, id DESC)
    WHERE deleted = 0 AND status IN (2, 5, 6);
COMMENT ON INDEX idx_market_my_approved_assets IS '我的资产按当前申请人查询已批准授权并按申请时间分页，包含暂停及到期历史';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;
DO $my_assets_root_menu$
DECLARE
    asset_root bigint;
    page_id bigint;
    ancestor_id bigint;
    ancestor_parent bigint;
    visited bigint[];
    matches integer;
    page_sort integer;
    source_ids bigint[];
    navigation_ids bigint[];
    menu_high bigint;
    role_high bigint;
    inserted integer;
BEGIN
    -- 根目录按稳定路由身份识别，显示名称、现有子项顺序和数据集市所在层级均不作为前置条件。
    SELECT count(*), min(id) INTO matches, asset_root FROM system_menu
    WHERE deleted = 0 AND parent_id = 0 AND trim(both '/' from coalesce(path, '')) = 'asset';
    IF matches <> 1 OR NOT EXISTS (
        SELECT 1 FROM system_menu WHERE id = asset_root AND type = 1 AND coalesce(permission, '') = ''
    ) THEN
        RAISE EXCEPTION '0184 数据资产根目录必须唯一、类型为目录且不得附带业务权限';
    END IF;

    SELECT count(*), min(id) INTO matches, page_id FROM system_menu
    WHERE trim(both '/' from coalesce(component, '')) = 'asset/market/my-assets/index';
    IF matches > 1 THEN RAISE EXCEPTION '0184 我的资产页面组件身份重复'; END IF;
    IF matches = 1 THEN
        IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id = page_id AND type = 2
            AND path = 'my-assets' AND permission = 'asset:market:my-assets:query' AND component_name = 'AssetMarketMyAssets') THEN
            RAISE EXCEPTION '0184 我的资产页面路由或权限身份冲突';
        END IF;
        -- 已有页面可以被管理员移动到数据资产内其他目录，重放不覆盖该决定。
        SELECT parent_id INTO ancestor_id FROM system_menu WHERE id = page_id;
        visited := ARRAY[page_id];
        WHILE ancestor_id <> 0 LOOP
            IF ancestor_id = ANY(visited) THEN RAISE EXCEPTION '0184 我的资产菜单祖先不能成环'; END IF;
            SELECT parent_id INTO ancestor_parent FROM system_menu
            WHERE id = ancestor_id AND type = 1 AND deleted = 0 AND coalesce(permission, '') = '';
            IF NOT FOUND THEN RAISE EXCEPTION '0184 我的资产祖先必须为有效且无业务权限的目录'; END IF;
            visited := array_append(visited, ancestor_id);
            IF ancestor_parent = 0 AND ancestor_id <> asset_root THEN
                RAISE EXCEPTION '0184 我的资产必须归属数据资产根目录';
            END IF;
            ancestor_id := ancestor_parent;
        END LOOP;
        IF NOT asset_root = ANY(visited) THEN RAISE EXCEPTION '0184 我的资产必须归属数据资产根目录'; END IF;
        RETURN;
    END IF;
    IF EXISTS (SELECT 1 FROM system_menu WHERE deleted = 0 AND
        ((parent_id = asset_root AND path = 'my-assets') OR permission = 'asset:market:my-assets:query')) THEN
        RAISE EXCEPTION '0184 我的资产路径或权限已被其他功能占用';
    END IF;
    IF EXISTS (SELECT 1 FROM system_tenant_package WHERE jsonb_typeof(menu_ids::jsonb) IS DISTINCT FROM 'array') THEN
        RAISE EXCEPTION '0184 套餐菜单编号必须为JSON数组';
    END IF;

    -- 只从当前有效的明确查询权限初始化，公共导航和资产管理权限均不作为授权来源。
    SELECT coalesce(array_agg(id), ARRAY[]::bigint[]) INTO source_ids FROM system_menu
    WHERE deleted = 0 AND status = 0 AND type IN (2, 3) AND permission = 'asset:market:query';
    SELECT coalesce(max(id), 0) INTO menu_high FROM system_menu;
    IF to_regclass('system_menu_seq') IS NOT NULL THEN
        SELECT greatest(menu_high, last_value) INTO menu_high FROM system_menu_seq;
    END IF;
    IF to_regclass('system_menu_id_seq') IS NOT NULL THEN
        SELECT greatest(menu_high, last_value) INTO menu_high FROM system_menu_id_seq;
    END IF;
    page_id := menu_high + 1;
    SELECT coalesce(max(sort), 0) + 1 INTO page_sort FROM system_menu WHERE parent_id = asset_root AND deleted = 0;
    INSERT INTO system_menu(id, name, permission, type, sort, parent_id, path, icon, component,
                            component_name, status, visible, keep_alive, always_show, creator, updater, deleted)
    VALUES(page_id, '我的资产', 'asset:market:my-assets:query', 2, page_sort, asset_root, 'my-assets',
           'carbon:folder-shared', 'asset/market/my-assets/index', 'AssetMarketMyAssets',
           0, true, false, true, 'migration:0184', 'migration:0184', 0);
    navigation_ids := ARRAY[asset_root, page_id];

    SELECT coalesce(max(id), 0) INTO role_high FROM system_role_menu;
    IF to_regclass('system_role_menu_seq') IS NOT NULL THEN
        SELECT greatest(role_high, last_value) INTO role_high FROM system_role_menu_seq;
    END IF;
    INSERT INTO system_role_menu(id, role_id, menu_id, tenant_id, creator, updater, deleted)
    SELECT role_high + row_number() OVER (ORDER BY pending.role_id, pending.tenant_id, pending.menu_id),
        pending.role_id, pending.menu_id, pending.tenant_id, 'migration:0184', 'migration:0184', 0
    FROM (
        SELECT DISTINCT source.role_id, source.tenant_id, navigation.id AS menu_id
        FROM system_role_menu source CROSS JOIN unnest(navigation_ids) navigation(id)
        WHERE source.deleted = 0 AND source.menu_id = ANY(source_ids)
          AND NOT EXISTS (SELECT 1 FROM system_role_menu existing WHERE existing.deleted = 0
            AND existing.role_id = source.role_id AND existing.tenant_id = source.tenant_id AND existing.menu_id = navigation.id)
    ) pending;
    GET DIAGNOSTICS inserted = ROW_COUNT;
    IF inserted > 0 AND to_regclass('system_role_menu_seq') IS NOT NULL THEN
        PERFORM setval('system_role_menu_seq', greatest((SELECT last_value FROM system_role_menu_seq), role_high + inserted));
    END IF;
    -- 脚手架套餐仅追加新页面及数据资产导航，保留原有JSON元素类型和顺序。
    WITH permitted AS (
        SELECT package.id, package.menu_ids::jsonb AS original
        FROM system_tenant_package package
        WHERE package.deleted = 0 AND EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
            WHERE entry.value = ANY(source_ids::text[])
        )
    ), expanded AS (
        SELECT permitted.id, permitted.original || to_jsonb(ARRAY(
            SELECT navigation.id FROM unnest(navigation_ids) WITH ORDINALITY navigation(id, position)
            WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements_text(permitted.original) entry(value)
                              WHERE entry.value = navigation.id::text)
            ORDER BY navigation.position
        )) AS entries FROM permitted
    )
    UPDATE system_tenant_package package SET menu_ids = expanded.entries::text,
        updater = 'migration:0184', update_time = CURRENT_TIMESTAMP
    FROM expanded WHERE package.id = expanded.id AND package.menu_ids::jsonb IS DISTINCT FROM expanded.entries;
END $my_assets_root_menu$;

-- 已执行0183的数据库也要同步默认序列；只推进编号，不改变已有页面位置、状态或授权。
DO $my_assets_menu_sequences$
DECLARE
    high_watermark bigint;
BEGIN
    SELECT greatest(coalesce(max(id), 1), 1) INTO high_watermark FROM system_menu;
    IF to_regclass('system_menu_seq') IS NOT NULL THEN
        SELECT greatest(high_watermark, last_value) INTO high_watermark FROM system_menu_seq;
    END IF;
    IF to_regclass('system_menu_id_seq') IS NOT NULL THEN
        SELECT greatest(high_watermark, last_value) INTO high_watermark FROM system_menu_id_seq;
    END IF;
    IF to_regclass('system_menu_seq') IS NOT NULL THEN PERFORM setval('system_menu_seq', high_watermark); END IF;
    IF to_regclass('system_menu_id_seq') IS NOT NULL THEN PERFORM setval('system_menu_id_seq', high_watermark); END IF;
END $my_assets_menu_sequences$;
COMMIT;

-- Migration: 0185 指标模型分组与独立业务限定。
-- Purpose: 新增单租户业务限定定义及来源保护，将指标模型分为原子指标、业务限定和派生指标。
-- Depends on: 0184_asset_my-assets-root-menu.sql；0171_modeling_concept-indicator-models.sql 已建立指标页面和模型来源。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；结构与触发器可重放，菜单按稳定组件校验，仅首次迁移复制原指标导航授权。
-- Rollback: 单事务失败完整回滚；提交后恢复执行前菜单和授权备份，新增业务限定数据先导出再删除，序列前进不回退。
-- 本迁移不执行计算逻辑；菜单迁移持有权限表锁，请在维护窗口停止菜单和权限写入并刷新权限缓存。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE SEQUENCE IF NOT EXISTS dh_modeling_business_condition_seq;
CREATE TABLE IF NOT EXISTS dh_modeling_business_condition (
    id bigint PRIMARY KEY DEFAULT nextval('dh_modeling_business_condition_seq'),
    code varchar(100) NOT NULL CHECK (code ~ '^[a-zA-Z][a-zA-Z0-9_]*$'),
    name varchar(100) NOT NULL CHECK (nullif(btrim(name),'') IS NOT NULL),
    data_domain_id bigint NOT NULL, subject_domain_id bigint, owner_user_id bigint,
    description varchar(2000), business_entity varchar(100), data_freshness varchar(100),
    source_model_id bigint NOT NULL, source_version_id bigint NOT NULL,
    config_type varchar(16) NOT NULL DEFAULT 'BASIC' CHECK (config_type='BASIC'),
    logic_mode varchar(16) NOT NULL DEFAULT 'UNIFIED' CHECK (logic_mode='UNIFIED'),
    expression varchar(4000) NOT NULL CHECK (nullif(btrim(expression),'') IS NOT NULL),
    status varchar(16) NOT NULL DEFAULT 'DRAFT' CHECK (status IN ('DRAFT','ACTIVE')),
    revision bigint NOT NULL DEFAULT 0 CHECK (revision>=0),
    creator varchar(64) DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
);
COMMENT ON TABLE dh_modeling_business_condition IS '数据建模-业务限定';
COMMENT ON COLUMN dh_modeling_business_condition.id IS '业务限定编号';
COMMENT ON COLUMN dh_modeling_business_condition.code IS '英文编码';
COMMENT ON COLUMN dh_modeling_business_condition.name IS '中文名称';
COMMENT ON COLUMN dh_modeling_business_condition.data_domain_id IS '归属数据域编号';
COMMENT ON COLUMN dh_modeling_business_condition.subject_domain_id IS '可选分析主题域编号';
COMMENT ON COLUMN dh_modeling_business_condition.owner_user_id IS '负责人用户编号';
COMMENT ON COLUMN dh_modeling_business_condition.description IS '描述';
COMMENT ON COLUMN dh_modeling_business_condition.business_entity IS '可选业务实体描述';
COMMENT ON COLUMN dh_modeling_business_condition.data_freshness IS '数据时效说明';
COMMENT ON COLUMN dh_modeling_business_condition.source_model_id IS '来源逻辑模型编号';
COMMENT ON COLUMN dh_modeling_business_condition.source_version_id IS '来源不可变已发布版本编号';
COMMENT ON COLUMN dh_modeling_business_condition.config_type IS '配置方式：当前仅支持基础限定BASIC';
COMMENT ON COLUMN dh_modeling_business_condition.logic_mode IS '计算逻辑方式：当前仅支持全时段统一UNIFIED';
COMMENT ON COLUMN dh_modeling_business_condition.expression IS '只保存不执行的计算逻辑定义';
COMMENT ON COLUMN dh_modeling_business_condition.status IS '状态：草稿DRAFT或已启用ACTIVE';
COMMENT ON COLUMN dh_modeling_business_condition.revision IS '并发修订号';
COMMENT ON COLUMN dh_modeling_business_condition.creator IS '创建人编号';
COMMENT ON COLUMN dh_modeling_business_condition.create_time IS '创建时间';
COMMENT ON COLUMN dh_modeling_business_condition.updater IS '更新人编号';
COMMENT ON COLUMN dh_modeling_business_condition.update_time IS '更新时间';
COMMENT ON COLUMN dh_modeling_business_condition.deleted IS '逻辑删除标记';
CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_condition_code ON dh_modeling_business_condition(lower(code)) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_condition_domain ON dh_modeling_business_condition(data_domain_id,subject_domain_id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_condition_source ON dh_modeling_business_condition(source_model_id,source_version_id) WHERE deleted=0;
COMMENT ON INDEX uq_modeling_condition_code IS '有效业务限定英文编码不区分大小写唯一';
COMMENT ON INDEX idx_modeling_condition_domain IS '有效业务限定按归属筛选';
COMMENT ON INDEX idx_modeling_condition_source IS '有效业务限定来源版本引用';

-- 与现有指标和规划引用共用事务锁，覆盖逻辑删除、来源废弃、下线和发布快照修改。
CREATE OR REPLACE FUNCTION modeling_business_condition_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
DECLARE ref_field text; referenced boolean;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-global',0));
    IF TG_TABLE_NAME='dh_modeling_business_condition' THEN
        IF TG_OP='DELETE' THEN RETURN OLD; END IF;
        IF NEW.deleted<>0 THEN RETURN NEW; END IF;
        IF NOT EXISTS(SELECT 1 FROM dh_modeling_data_domain WHERE id=NEW.data_domain_id AND deleted=0)
           OR (NEW.subject_domain_id IS NOT NULL AND NOT EXISTS(
               SELECT 1 FROM dh_modeling_subject_domain WHERE id=NEW.subject_domain_id AND deleted=0)) THEN
            RAISE EXCEPTION '业务限定归属不存在' USING ERRCODE='23514';
        END IF;
        IF NOT EXISTS(SELECT 1 FROM dh_modeling_logic_model_version v
            JOIN dh_modeling_logic_model m ON m.id=v.model_id AND m.deleted=0 AND m.enabled=1 AND m.status<>'DISCARDED' AND m.data_domain_id=NEW.data_domain_id
            WHERE v.id=NEW.source_version_id AND v.model_id=NEW.source_model_id AND v.deleted=0 AND v.status='PUBLISHED') THEN
            RAISE EXCEPTION '业务限定来源必须为有效逻辑模型的已发布版本' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    ref_field:=CASE TG_TABLE_NAME WHEN 'dh_modeling_logic_model' THEN 'source_model_id'
        WHEN 'dh_modeling_logic_model_version' THEN 'source_version_id'
        WHEN 'dh_modeling_data_domain' THEN 'data_domain_id' ELSE 'subject_domain_id' END;
    EXECUTE format('SELECT EXISTS(SELECT 1 FROM dh_modeling_business_condition WHERE %I=$1 AND deleted=0)',ref_field)
        INTO referenced USING OLD.id;
    IF referenced THEN
        IF TG_OP='DELETE' THEN RAISE EXCEPTION '对象仍被业务限定引用，不能删除' USING ERRCODE='23514'; END IF;
        IF NEW.deleted<>0 THEN RAISE EXCEPTION '对象仍被业务限定引用，不能删除' USING ERRCODE='23514'; END IF;
        IF TG_TABLE_NAME='dh_modeling_logic_model' AND
            (to_jsonb(NEW)->>'status'='DISCARDED' OR (to_jsonb(NEW)->>'enabled')::integer<>1
             OR (to_jsonb(NEW)->>'data_domain_id') IS DISTINCT FROM (to_jsonb(OLD)->>'data_domain_id')) THEN
            RAISE EXCEPTION '逻辑模型仍被业务限定引用，不能废弃或停用' USING ERRCODE='23514';
        END IF;
        IF TG_TABLE_NAME='dh_modeling_logic_model_version' AND
            ((to_jsonb(NEW)->>'status')<>'PUBLISHED' OR
             (to_jsonb(NEW)-ARRAY['updater','update_time']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['updater','update_time'])) THEN
            RAISE EXCEPTION '已发布版本仍被业务限定引用，不能变更' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_business_condition_guard() IS '串行保护业务限定的规划归属和不可变来源版本';
DO $install_guards$
DECLARE table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_business_condition','dh_modeling_logic_model',
        'dh_modeling_logic_model_version','dh_modeling_data_domain','dh_modeling_subject_domain'] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS modeling_business_condition_guard ON %I',table_name);
        EXECUTE format('CREATE TRIGGER modeling_business_condition_guard BEFORE %s ON %I FOR EACH ROW EXECUTE FUNCTION modeling_business_condition_guard()',
            CASE WHEN table_name='dh_modeling_business_condition' THEN 'INSERT OR UPDATE OR DELETE' ELSE 'UPDATE OR DELETE' END,table_name);
    END LOOP;
END $install_guards$;

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;
DO $metric_menus$
DECLARE metric_parent_id bigint; matches integer; page_id bigint; button_id bigint; item record; action text;
    initial_split boolean; navigation_ids bigint[]:=ARRAY[]::bigint[]; menu_high bigint; role_high bigint; inserted integer;
BEGIN
    SELECT count(*),min(id) INTO matches,metric_parent_id FROM system_menu
    WHERE component='modeling/indicator-model/index' OR
        (component_name='ModelingIndicatorModelRoot' AND path='indicator-model');
    IF matches<>1 OR NOT EXISTS(SELECT 1 FROM system_menu WHERE id=metric_parent_id AND deleted=0 AND status=0) THEN
        RAISE EXCEPTION '0185 指标模型菜单缺失、不唯一或已停用，请先核查菜单';
    END IF;
    SELECT type=2 INTO initial_split FROM system_menu WHERE id=metric_parent_id;
    IF initial_split THEN
        UPDATE system_menu SET name='指标模型',type=1,permission='',component=NULL,component_name='ModelingIndicatorModelRoot',
            updater='migration:0185',update_time=CURRENT_TIMESTAMP WHERE id=metric_parent_id;
    ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=metric_parent_id AND type=1 AND coalesce(permission,'')='' AND component_name='ModelingIndicatorModelRoot') THEN
        RAISE EXCEPTION '0185 指标模型目录身份冲突';
    END IF;
    SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq)) INTO menu_high FROM system_menu;
    FOR item IN SELECT * FROM (VALUES
        ('原子指标','atomic','modeling/indicator-model/atomic/index','ModelingAtomicIndicator','modeling:indicator-model:query',10),
        ('业务限定','condition','modeling/business-condition/index','ModelingBusinessCondition','modeling:business-condition:query',20),
        ('派生指标','derived','modeling/indicator-model/derived/index','ModelingDerivedIndicator','modeling:indicator-model:query',30)
    ) t(label,path,component,component_name,permission,sort) LOOP
        SELECT count(*),min(id) INTO matches,page_id FROM system_menu WHERE component=item.component;
        IF matches>1 THEN RAISE EXCEPTION '0185 指标子页面组件身份重复：%',item.component; END IF;
        IF matches=0 THEN
            IF EXISTS(SELECT 1 FROM system_menu WHERE system_menu.parent_id=metric_parent_id AND path=item.path) THEN
                RAISE EXCEPTION '0185 指标子页面路径已被占用：%',item.path;
            END IF;
            menu_high:=menu_high+1; page_id:=menu_high;
            INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,
                visible,keep_alive,always_show,creator,updater,deleted)
            VALUES(page_id,item.label,item.permission,2,item.sort,metric_parent_id,item.path,'carbon:chart-line',item.component,
                item.component_name,0,true,true,true,'migration:0185','migration:0185',0);
        ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=page_id AND system_menu.parent_id=metric_parent_id AND type=2
            AND path=item.path AND permission=item.permission AND deleted=0) THEN
            RAISE EXCEPTION '0185 指标子页面归属或权限冲突：%',item.component;
        END IF;
        IF item.path IN ('atomic','derived') THEN navigation_ids:=array_append(navigation_ids,page_id); END IF;
        IF item.path='condition' THEN
            FOREACH action IN ARRAY ARRAY['create','update','delete'] LOOP
                SELECT count(*),min(id) INTO matches,button_id FROM system_menu WHERE permission='modeling:business-condition:'||action;
                IF matches>1 THEN RAISE EXCEPTION '0185 业务限定按钮权限重复'; END IF;
                IF matches=0 THEN
                    menu_high:=menu_high+1; button_id:=menu_high;
                    INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
                    VALUES(button_id,'业务限定'||CASE action WHEN 'create' THEN '新增' WHEN 'update' THEN '修改及启停' ELSE '删除' END,
                        'modeling:business-condition:'||action,3,0,page_id,'',0,true,true,true,'migration:0185','migration:0185',0);
                ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=button_id AND system_menu.parent_id=page_id AND type=3 AND deleted=0) THEN
                    RAISE EXCEPTION '0185 业务限定按钮归属冲突';
                END IF;
            END LOOP;
        END IF;
    END LOOP;
    IF initial_split THEN
        -- 原指标查询授权仅继承给原子和派生导航，新增业务限定权限由管理员明确分配。
        SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO role_high FROM system_role_menu;
        INSERT INTO system_role_menu(id,role_id,menu_id,tenant_id,creator,updater,deleted)
        SELECT role_high+row_number() OVER(ORDER BY pending.role_id,pending.tenant_id,pending.menu_id),
            pending.role_id,pending.menu_id,pending.tenant_id,'migration:0185','migration:0185',0
        FROM (SELECT DISTINCT source.role_id,source.tenant_id,navigation.id AS menu_id
            FROM system_role_menu source CROSS JOIN unnest(navigation_ids) navigation(id)
            WHERE source.deleted=0 AND source.menu_id=metric_parent_id AND NOT EXISTS(SELECT 1 FROM system_role_menu existing
                WHERE existing.deleted=0 AND existing.role_id=source.role_id AND existing.tenant_id=source.tenant_id AND existing.menu_id=navigation.id)) pending;
        GET DIAGNOSTICS inserted=ROW_COUNT;
        IF inserted>0 THEN PERFORM setval('system_role_menu_seq',greatest((SELECT last_value FROM system_role_menu_seq),role_high+inserted)); END IF;
        IF EXISTS(SELECT 1 FROM system_tenant_package WHERE jsonb_typeof(menu_ids::jsonb) IS DISTINCT FROM 'array') THEN
            RAISE EXCEPTION '0185 套餐菜单编号必须为JSON数组';
        END IF;
        WITH permitted AS (SELECT package.id,package.menu_ids::jsonb AS original FROM system_tenant_package package
            WHERE package.deleted=0 AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value) WHERE entry.value=metric_parent_id::text)),
        expanded AS (SELECT permitted.id,permitted.original||to_jsonb(ARRAY(SELECT navigation.id FROM unnest(navigation_ids) navigation(id)
            WHERE NOT EXISTS(SELECT 1 FROM jsonb_array_elements_text(permitted.original) entry(value) WHERE entry.value=navigation.id::text))) entries FROM permitted)
        UPDATE system_tenant_package package SET menu_ids=expanded.entries::text,updater='migration:0185',update_time=CURRENT_TIMESTAMP
            FROM expanded WHERE package.id=expanded.id;
    END IF;
    PERFORM setval('system_menu_seq',greatest((SELECT last_value FROM system_menu_seq),menu_high));
    PERFORM setval('system_menu_id_seq',greatest((SELECT last_value FROM system_menu_id_seq),menu_high));
END $metric_menus$;
COMMIT;

-- Migration: 0186 外部连接文件管理。
-- Purpose: 用 FTP/WebHDFS 文件管理替换平台文件分组和上传登记，补充操作审计、连接类型及下载权限。
-- Depends on: 0185_modeling_metric-pages-business-condition.sql；0173 已建立连接类型目录及分类字典，0169 已完成单租户转换。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；表和索引按存在性创建，类型和菜单按有效身份补齐，旧表按存在性删除。
-- Rollback: 事务失败回滚；提交后删除的旧文件元数据和分组不可恢复，须用执行前备份恢复。源端文件和 infra 文件对象不由本脚本删除。
-- 风险：按本次不保留旧数据的产品要求物理删除旧文件表；在维护窗口停止旧应用文件写入及菜单写入，再执行本脚本。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE dh_dataforge_database_type, system_menu IN ACCESS EXCLUSIVE MODE;

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_file_operation_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_file_operation (
    id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_file_operation_seq'),
    connection_id bigint NOT NULL,
    action varchar(16) NOT NULL CHECK (action IN ('UPLOAD','MKDIR','RENAME','DELETE')),
    path varchar(4096) NOT NULL,
    target_path varchar(4096),
    status varchar(16) NOT NULL CHECK (status IN ('PENDING','SUCCESS','UNKNOWN')),
    result_message varchar(255),
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0
);
COMMENT ON TABLE dh_dataforge_file_operation IS '外部文件操作意图和结果审计，不保存源文件内容及凭据';
COMMENT ON COLUMN dh_dataforge_file_operation.id IS '操作编号';
COMMENT ON COLUMN dh_dataforge_file_operation.connection_id IS '平台受管文件连接编号';
COMMENT ON COLUMN dh_dataforge_file_operation.action IS '操作类型：上传、建目录、重命名、删除';
COMMENT ON COLUMN dh_dataforge_file_operation.path IS '连接根目录内的逻辑路径';
COMMENT ON COLUMN dh_dataforge_file_operation.target_path IS '重命名目标逻辑路径';
COMMENT ON COLUMN dh_dataforge_file_operation.status IS '结果：待执行、成功、源端结果未知需刷新核对';
COMMENT ON COLUMN dh_dataforge_file_operation.result_message IS '不含连接凭据的结果摘要';
COMMENT ON COLUMN dh_dataforge_file_operation.creator IS '操作人';
COMMENT ON COLUMN dh_dataforge_file_operation.create_time IS '意图登记时间';
COMMENT ON COLUMN dh_dataforge_file_operation.updater IS '结果更新人';
COMMENT ON COLUMN dh_dataforge_file_operation.update_time IS '结果更新时间';
COMMENT ON COLUMN dh_dataforge_file_operation.deleted IS '逻辑删除标记';
CREATE INDEX IF NOT EXISTS idx_file_operation_connection_time ON dh_dataforge_file_operation(connection_id, create_time DESC) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_file_operation_pending ON dh_dataforge_file_operation(status, create_time) WHERE deleted=0 AND status<>'SUCCESS';

DO $file_catalog$
DECLARE item record; new_id bigint;
BEGIN
    FOR item IN SELECT * FROM (VALUES
        ('FTP','FTP 文件服务','FTP','21','FTP 文件目录，支持被动模式及根目录边界。'),
        ('HDFS','HDFS 文件服务','WEBHDFS','9870','通过显式 WebHDFS HTTP 端点访问 HDFS；使用简单用户认证，非 NameNode RPC 端口。')
    ) seed(code,name,protocol,port,description) LOOP
        IF NOT EXISTS (SELECT 1 FROM dh_dataforge_database_type WHERE upper(type_code)=item.code AND deleted=0) THEN
            SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM dh_foundation_database_type_seq))+1 INTO new_id FROM dh_dataforge_database_type;
            INSERT INTO dh_dataforge_database_type(id,type_code,type_name,description,category_code,protocol_type,
                port_templates,sort,status,creator,updater,deleted)
            VALUES(new_id,item.code,item.name,item.description,'FILE_OBJECT_STORAGE',item.protocol,item.port,80,0,'migration:0186','migration:0186',0);
            PERFORM setval('dh_foundation_database_type_seq',new_id);
        END IF;
    END LOOP;
END $file_catalog$;

DO $file_menus$
DECLARE page_id bigint; matches integer; new_id bigint;
BEGIN
    SELECT count(*),min(id) INTO matches,page_id FROM system_menu WHERE component='dataforge/datafile/index' AND deleted=0;
    IF matches<>1 THEN RAISE EXCEPTION '0186 文件管理页面菜单缺失或重复，请核查原文件采集菜单'; END IF;
    UPDATE system_menu SET name='文件管理', updater='migration:0186',update_time=CURRENT_TIMESTAMP WHERE id=page_id;
    UPDATE system_menu SET name='文件上传及新建目录',updater='migration:0186',update_time=CURRENT_TIMESTAMP
        WHERE permission='dataforge:data-file:create' AND parent_id=page_id AND deleted=0;
    UPDATE system_menu SET name='文件重命名',updater='migration:0186',update_time=CURRENT_TIMESTAMP
        WHERE permission='dataforge:data-file:update' AND parent_id=page_id AND deleted=0;
    SELECT count(*) INTO matches FROM system_menu WHERE permission='dataforge:data-file:download' AND deleted=0;
    IF matches=0 THEN
        SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO new_id FROM system_menu;
        INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
        VALUES(new_id,'文件下载','dataforge:data-file:download',3,4,page_id,'',0,true,true,true,'migration:0186','migration:0186',0);
        PERFORM setval('system_menu_seq',new_id);
        PERFORM setval('system_menu_id_seq',new_id);
    ELSIF matches<>1 OR NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='dataforge:data-file:download' AND parent_id=page_id AND type=3 AND deleted=0) THEN
        RAISE EXCEPTION '0186 文件下载权限归属冲突';
    END IF;
END $file_menus$;

-- 新增下载权限由管理员明确授权，不从查询权限推导下载权。
DROP TABLE IF EXISTS dh_dataforge_file;
DROP TABLE IF EXISTS dh_dataforge_file_category;
DROP SEQUENCE IF EXISTS dh_dataforge_file_seq;
DROP SEQUENCE IF EXISTS dh_dataforge_file_category_seq;
COMMIT;

-- 0187 元数据管理最终结构及权限
-- Migration: 0187 元数据管理、实例队列及独立定版。
-- Purpose: 拆分发布与定版，冻结业务镜像；采集实例持有租约，支持文件元数据及细粒度权限。
-- Depends on: 0186_dataforge_remote-file-management.sql；0182 已建立元数据修订号及单租户结构。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；列、索引和菜单按有效身份补齐，旧任务租约列仅首次移除。
-- Rollback: 事务失败自动回滚；提交后旧任务租约字段不可恢复，须停服务并从备份恢复；不会删除外部源数据或 infra 文件。
-- 风险：执行前停止元数据采集工作进程；旧运行中实例首次迁移标记失败。DDL 和菜单写入需短暂锁表。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE dh_governance_meta_collect_task, dh_governance_meta_collect_instance, dh_governance_meta_table, system_menu IN ACCESS EXCLUSIVE MODE;

ALTER TABLE dh_governance_meta_table ADD COLUMN IF NOT EXISTS state_revision integer NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_governance_meta_table.state_revision IS '发布和定版状态修订号，采集与业务修订独立';
ALTER TABLE dh_governance_meta_table ADD COLUMN IF NOT EXISTS finalized_time timestamp;
COMMENT ON COLUMN dh_governance_meta_table.finalized_time IS '确认定版时间';
ALTER TABLE dh_governance_meta_table ADD COLUMN IF NOT EXISTS finalized_by varchar(64);
COMMENT ON COLUMN dh_governance_meta_table.finalized_by IS '确认定版操作人';
ALTER TABLE dh_governance_meta_table ADD COLUMN IF NOT EXISTS finalized_snapshot jsonb;
COMMENT ON COLUMN dh_governance_meta_table.finalized_snapshot IS '所选历史技术结构与确认时业务信息的只读镜像，独立于发布开关';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS collect_type smallint NOT NULL DEFAULT 1;
COMMENT ON COLUMN dh_governance_meta_collect_task.collect_type IS '采集类型：1数据库、2文件';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS execute_strategy varchar(32) NOT NULL DEFAULT 'SERIAL_DISCARD';
COMMENT ON COLUMN dh_governance_meta_collect_task.execute_strategy IS '执行策略：SERIAL_DISCARD串行丢弃、SERIAL_WAIT串行等待、SERIAL_PRIORITY串行取最新等待、PARALLEL并行执行';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS file_path varchar(4096);
COMMENT ON COLUMN dh_governance_meta_collect_task.file_path IS '文件采集根目录内的逻辑路径';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS datasource_name varchar(200);
COMMENT ON COLUMN dh_governance_meta_collect_task.datasource_name IS '连接名称展示快照';
ALTER TABLE dh_governance_meta_collect_task ADD COLUMN IF NOT EXISTS owner_name varchar(100);
COMMENT ON COLUMN dh_governance_meta_collect_task.owner_name IS '负责人名称展示快照';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS task_name varchar(200);
COMMENT ON COLUMN dh_governance_meta_collect_instance.task_name IS '执行时任务名称';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS datasource_id bigint;
COMMENT ON COLUMN dh_governance_meta_collect_instance.datasource_id IS '执行时数据连接编号';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS datasource_name varchar(200);
COMMENT ON COLUMN dh_governance_meta_collect_instance.datasource_name IS '执行时连接名称';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS source_system_id bigint;
COMMENT ON COLUMN dh_governance_meta_collect_instance.source_system_id IS '执行时来源系统编号';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS source_system_name varchar(200);
COMMENT ON COLUMN dh_governance_meta_collect_instance.source_system_name IS '执行时来源系统名称';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS collect_type smallint NOT NULL DEFAULT 1;
COMMENT ON COLUMN dh_governance_meta_collect_instance.collect_type IS '执行时采集类型：1数据库、2文件';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS owner_user_id bigint;
COMMENT ON COLUMN dh_governance_meta_collect_instance.owner_user_id IS '执行时负责人编号';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS owner_name varchar(100);
COMMENT ON COLUMN dh_governance_meta_collect_instance.owner_name IS '执行时负责人名称';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS owner_phone varchar(32);
COMMENT ON COLUMN dh_governance_meta_collect_instance.owner_phone IS '执行时负责人电话';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS description varchar(1024);
COMMENT ON COLUMN dh_governance_meta_collect_instance.description IS '执行时任务描述';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS file_count integer NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_governance_meta_collect_instance.file_count IS '处理文件数量';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS execution_token varchar(64);
COMMENT ON COLUMN dh_governance_meta_collect_instance.execution_token IS '实例执行租约令牌，过期令牌禁止回写';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS lease_until timestamp;
COMMENT ON COLUMN dh_governance_meta_collect_instance.lease_until IS '实例执行租约截止时间';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS attempt_count integer NOT NULL DEFAULT 0;
COMMENT ON COLUMN dh_governance_meta_collect_instance.attempt_count IS '实例执行尝试次数';
ALTER TABLE dh_governance_meta_collect_instance ADD COLUMN IF NOT EXISTS execution_user_id bigint;
COMMENT ON COLUMN dh_governance_meta_collect_instance.execution_user_id IS '手动执行操作人编号';

ALTER TABLE dh_governance_meta_collect_instance ALTER COLUMN start_time DROP NOT NULL;
COMMENT ON COLUMN dh_governance_meta_collect_instance.status IS '实例状态：0排队、1运行、2成功、3失败、4部分成功、5已丢弃';
COMMENT ON COLUMN dh_governance_meta_table.publish_status IS '发布开关：0未发布、1已发布；与定版独立';
COMMENT ON COLUMN dh_governance_meta_table.published_version IS '当前定版结构版本号，取消发布不清除';
COMMENT ON COLUMN dh_governance_meta_table.published_snapshot_id IS '当前定版结构快照编号，资产历史引用继续有效';
DO $retire_task_lease$
BEGIN
    IF EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema=current_schema()
            AND table_name='dh_governance_meta_collect_task' AND column_name='execution_token') THEN
        UPDATE dh_governance_meta_collect_instance SET status=3, error_type='MIGRATION_INTERRUPTED',
            end_time=CURRENT_TIMESTAMP, remark='元数据执行机制升级，旧实例终止，请重新执行任务',
            updater='migration:0187',update_time=CURRENT_TIMESTAMP WHERE status=1 AND deleted=0;
    END IF;
END $retire_task_lease$;
ALTER TABLE dh_governance_meta_collect_task DROP COLUMN IF EXISTS execution_token;
ALTER TABLE dh_governance_meta_collect_task DROP COLUMN IF EXISTS lease_until;
ALTER TABLE dh_governance_meta_collect_task DROP COLUMN IF EXISTS running_instance_id;
CREATE INDEX IF NOT EXISTS idx_meta_instance_queue ON dh_governance_meta_collect_instance(status,id) WHERE deleted=0 AND status=0;
CREATE INDEX IF NOT EXISTS idx_meta_instance_lease ON dh_governance_meta_collect_instance(lease_until,id) WHERE deleted=0 AND status=1;
CREATE INDEX IF NOT EXISTS idx_meta_instance_task_state ON dh_governance_meta_collect_instance(task_id,status,id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_meta_table_finalized ON dh_governance_meta_table(finalized_time DESC,id) WHERE deleted=0 AND published_snapshot_id IS NOT NULL;
CREATE SEQUENCE IF NOT EXISTS dh_governance_meta_file_seq;
CREATE TABLE IF NOT EXISTS dh_governance_meta_file (
    id bigint PRIMARY KEY DEFAULT nextval('dh_governance_meta_file_seq'),
    datasource_id bigint NOT NULL, datasource_name varchar(200), source_system_id bigint, source_system_name varchar(200),
    task_id bigint, instance_id bigint, path varchar(4096) NOT NULL, parent_path varchar(4096) NOT NULL,
    name varchar(255) NOT NULL, file_type varchar(32), size bigint NOT NULL DEFAULT 0,
    source_modified_time timestamp, first_seen_time timestamp, last_seen_time timestamp,
    object_status smallint NOT NULL DEFAULT 1, business_name varchar(200), description varchar(1024),
    owner_user_id bigint, tech_leader_user_id bigint, tech_leader_phone varchar(32),
    business_leader_user_id bigint, business_leader_phone varchar(32), biz_revision integer NOT NULL DEFAULT 0,
    creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0
);
COMMENT ON TABLE dh_governance_meta_file IS '独立文件元数据登记，只保存源端文件描述，不保存文件内容';

COMMENT ON COLUMN dh_governance_meta_file.id IS '文件元数据编号';
COMMENT ON COLUMN dh_governance_meta_file.datasource_id IS '受管连接编号';
COMMENT ON COLUMN dh_governance_meta_file.datasource_name IS '连接名称快照';
COMMENT ON COLUMN dh_governance_meta_file.source_system_id IS '来源系统编号';
COMMENT ON COLUMN dh_governance_meta_file.source_system_name IS '来源系统名称快照';
COMMENT ON COLUMN dh_governance_meta_file.task_id IS '最近采集任务编号';
COMMENT ON COLUMN dh_governance_meta_file.instance_id IS '最近采集实例编号';
COMMENT ON COLUMN dh_governance_meta_file.path IS '连接根目录内的完整逻辑路径';
COMMENT ON COLUMN dh_governance_meta_file.parent_path IS '逻辑父目录';
COMMENT ON COLUMN dh_governance_meta_file.name IS '文件名称';
COMMENT ON COLUMN dh_governance_meta_file.file_type IS '文件扩展类型';
COMMENT ON COLUMN dh_governance_meta_file.size IS '源文件大小字节数';
COMMENT ON COLUMN dh_governance_meta_file.source_modified_time IS '源文件修改时间';
COMMENT ON COLUMN dh_governance_meta_file.first_seen_time IS '首次发现时间';
COMMENT ON COLUMN dh_governance_meta_file.last_seen_time IS '最近确认时间';
COMMENT ON COLUMN dh_governance_meta_file.object_status IS '对象状态：1正常、2源端已缺失';
COMMENT ON COLUMN dh_governance_meta_file.business_name IS '平台维护业务名称';
COMMENT ON COLUMN dh_governance_meta_file.description IS '平台维护描述';
COMMENT ON COLUMN dh_governance_meta_file.owner_user_id IS '负责人编号';
COMMENT ON COLUMN dh_governance_meta_file.tech_leader_user_id IS '技术负责人编号';
COMMENT ON COLUMN dh_governance_meta_file.tech_leader_phone IS '技术负责人电话';
COMMENT ON COLUMN dh_governance_meta_file.business_leader_user_id IS '业务负责人编号';
COMMENT ON COLUMN dh_governance_meta_file.business_leader_phone IS '业务负责人电话';
COMMENT ON COLUMN dh_governance_meta_file.biz_revision IS '业务属性并发修订号';
COMMENT ON COLUMN dh_governance_meta_file.creator IS '创建者';
COMMENT ON COLUMN dh_governance_meta_file.create_time IS '创建时间';
COMMENT ON COLUMN dh_governance_meta_file.updater IS '更新者';
COMMENT ON COLUMN dh_governance_meta_file.update_time IS '更新时间';
COMMENT ON COLUMN dh_governance_meta_file.deleted IS '逻辑删除：0有效、1删除';
CREATE UNIQUE INDEX IF NOT EXISTS uk_meta_file_source_path ON dh_governance_meta_file(datasource_id,md5(path)) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_meta_file_parent_path ON dh_governance_meta_file(datasource_id,md5(parent_path)) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_meta_file_source_system ON dh_governance_meta_file(source_system_id,id) WHERE deleted=0;
DO $metadata_constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_table'::regclass AND conname='ck_meta_table_state_revision') THEN
        ALTER TABLE dh_governance_meta_table ADD CONSTRAINT ck_meta_table_state_revision CHECK (state_revision >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_collect_task'::regclass AND conname='ck_meta_task_collect_type') THEN
        ALTER TABLE dh_governance_meta_collect_task ADD CONSTRAINT ck_meta_task_collect_type CHECK (collect_type IN (1,2));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_collect_task'::regclass AND conname='ck_meta_task_execute_strategy') THEN
        ALTER TABLE dh_governance_meta_collect_task ADD CONSTRAINT ck_meta_task_execute_strategy CHECK (execute_strategy IN ('SERIAL_DISCARD','SERIAL_WAIT','SERIAL_PRIORITY','PARALLEL'));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_collect_instance'::regclass AND conname='ck_meta_instance_status') THEN
        ALTER TABLE dh_governance_meta_collect_instance ADD CONSTRAINT ck_meta_instance_status CHECK (status BETWEEN 0 AND 5);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_collect_instance'::regclass AND conname='ck_meta_instance_collect_type') THEN
        ALTER TABLE dh_governance_meta_collect_instance ADD CONSTRAINT ck_meta_instance_collect_type CHECK (collect_type IN (1,2));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_collect_instance'::regclass AND conname='ck_meta_instance_attempts') THEN
        ALTER TABLE dh_governance_meta_collect_instance ADD CONSTRAINT ck_meta_instance_attempts CHECK (attempt_count >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_file'::regclass AND conname='ck_meta_file_status') THEN
        ALTER TABLE dh_governance_meta_file ADD CONSTRAINT ck_meta_file_status CHECK (object_status IN (1,2));
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_file'::regclass AND conname='ck_meta_file_revision') THEN
        ALTER TABLE dh_governance_meta_file ADD CONSTRAINT ck_meta_file_revision CHECK (biz_revision >= 0);
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conrelid='dh_governance_meta_file'::regclass AND conname='ck_meta_file_size') THEN
        ALTER TABLE dh_governance_meta_file ADD CONSTRAINT ck_meta_file_size CHECK (size >= 0);
    END IF;
END $metadata_constraints$;
DO $metadata_menus$
DECLARE root_id bigint; page_id bigint; target_id bigint; row_count integer; item record;
BEGIN
    SELECT count(*),min(id) INTO row_count,root_id FROM system_menu WHERE path='metadata' AND type=1 AND deleted=0;
    IF row_count<>1 THEN RAISE EXCEPTION '0187 元数据管理目录缺失或重复'; END IF;
    UPDATE system_menu SET name='最新元数据',updater='migration:0187',update_time=CURRENT_TIMESTAMP
        WHERE component='governance/metaobject/index' AND deleted=0;
    UPDATE system_menu SET name='元数据发布与定版',updater='migration:0187',update_time=CURRENT_TIMESTAMP
        WHERE permission='governance:meta-table:publish' AND deleted=0;
    -- 文件元数据在最新元数据页的文件页签内展示，仅补充独立操作权限。
    FOR item IN SELECT * FROM (VALUES
        ('governance/metaobject/index','文件元数据查询','governance:meta-file:query',5),
        ('governance/metaobject/index','文件元数据维护','governance:meta-file:update',6),
        ('governance/metaobject/index','文件元数据删除','governance:meta-file:delete',7),
        ('governance/metacollectinstance/index','采集实例删除','governance:meta-collect-instance:delete',1)
    ) seed(component,name,permission,sort) LOOP
        SELECT count(*),min(id) INTO row_count,page_id FROM system_menu WHERE component=item.component AND deleted=0;
        IF row_count<>1 THEN RAISE EXCEPTION '0187 元数据页面菜单缺失或重复：%',item.component; END IF;
        SELECT count(*) INTO row_count FROM system_menu WHERE permission=item.permission AND deleted=0;
        IF row_count=0 THEN
            SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO target_id FROM system_menu;
            INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
            VALUES(target_id,item.name,item.permission,3,item.sort,page_id,'',0,true,true,true,'migration:0187','migration:0187',0);
            PERFORM setval('system_menu_seq',target_id);
            PERFORM setval('system_menu_id_seq',target_id);
        ELSIF row_count<>1 OR NOT EXISTS(SELECT 1 FROM system_menu WHERE permission=item.permission AND parent_id=page_id AND type=3 AND deleted=0) THEN
            RAISE EXCEPTION '0187 元数据权限菜单归属冲突：%',item.permission;
        END IF;
    END LOOP;
END $metadata_menus$;
-- 新操作权限由管理员按角色授权，不从查询权限推导维护或删除权限。
COMMIT;


-- 0188 主数据推送最终结构与菜单
-- Migration: 0188 主数据维护和 REST 推送。
-- Purpose: 增加推送凭据密文、按记录增量检查点及执行统计，补齐主数据推送菜单名称。
-- Depends on: 0187_governance_metadata-management.sql；主数据派发持久运行协议和单租户迁移已完成。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；列和表按存在性补齐，索引和菜单更新具有幂等性。
-- Rollback: 失败时事务回滚；提交后回滚应用前须停用推送工作进程，导出密文及检查点备份。删除检查点会使下一次增量重新发送，不能直接删表回退。
-- 风险：执行前停止主数据派发工作进程；DDL 获取短暂表锁。迁移不接触业务源表，不转换旧配置中的明文凭据。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_governance_master_distribute ADD COLUMN IF NOT EXISTS request_secrets text;
ALTER TABLE dh_governance_master_distribute ALTER COLUMN description TYPE varchar(256);
COMMENT ON COLUMN dh_governance_master_distribute.request_secrets IS '请求凭据密文，由平台加密类型处理器读写，不向管理端返回明文';
COMMENT ON COLUMN dh_governance_master_distribute.description IS '主数据推送说明，最多256个字符';

ALTER TABLE dh_governance_master_distribute_log
    ADD COLUMN IF NOT EXISTS total_count bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS success_count bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS failure_count bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS unknown_count bigint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS push_scope varchar(16),
    ADD COLUMN IF NOT EXISTS push_mode varchar(16);
COMMENT ON COLUMN dh_governance_master_distribute_log.total_count IS '本次选入推送批次的记录总数';
COMMENT ON COLUMN dh_governance_master_distribute_log.success_count IS '已收到成功响应的记录数';
COMMENT ON COLUMN dh_governance_master_distribute_log.failure_count IS '已确认失败的记录数，不包含结果未知记录';
COMMENT ON COLUMN dh_governance_master_distribute_log.unknown_count IS '已发送但无法确认结果的记录数';
COMMENT ON COLUMN dh_governance_master_distribute_log.push_scope IS '执行时推送范围快照';
COMMENT ON COLUMN dh_governance_master_distribute_log.push_mode IS '执行时推送模式快照';

CREATE TABLE IF NOT EXISTS dh_governance_master_distribute_checkpoint (
    distribute_id bigint NOT NULL,
    row_key_hash varchar(64) NOT NULL,
    payload_hash varchar(64) NOT NULL,
    run_id bigint NOT NULL,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT pk_master_distribute_checkpoint PRIMARY KEY (distribute_id, row_key_hash),
    CONSTRAINT fk_master_distribute_checkpoint_task FOREIGN KEY (distribute_id)
        REFERENCES dh_governance_master_distribute(id),
    CONSTRAINT fk_master_distribute_checkpoint_run FOREIGN KEY (run_id)
        REFERENCES dh_governance_master_distribute_log(id),
    CONSTRAINT ck_master_distribute_checkpoint_hash CHECK (
        row_key_hash ~ '^[0-9a-f]{64}$' AND payload_hash ~ '^[0-9a-f]{64}$'),
    CONSTRAINT ck_master_distribute_checkpoint_deleted CHECK (deleted IN (0, 1))
);
COMMENT ON TABLE dh_governance_master_distribute_checkpoint IS '主数据推送已确认记录检查点，只保存摘要和执行引用，不保存源业务数据';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.distribute_id IS '主数据推送任务编号';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.row_key_hash IS '模型主键规范化后的摘要';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.payload_hash IS '成功发送的映射后内容摘要';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.run_id IS '最近确认该记录的执行日志编号';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.creator IS '首次确认操作人';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.create_time IS '首次确认时间';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.updater IS '最近确认操作人';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.update_time IS '最近确认时间';
COMMENT ON COLUMN dh_governance_master_distribute_checkpoint.deleted IS '逻辑删除标记';
CREATE INDEX IF NOT EXISTS idx_master_distribute_checkpoint_run
    ON dh_governance_master_distribute_checkpoint(run_id);

UPDATE system_menu SET name='主数据推送', updater='migration:0188', update_time=CURRENT_TIMESTAMP
WHERE type=2 AND deleted=0 AND trim(both '/' from coalesce(component,''))='governance/masterdistribute/index'
    AND name IS DISTINCT FROM '主数据推送';
COMMIT;

-- Migration: 0189
-- Purpose: 质量任务独立评测配置、历史报告关联和问题行处置审计。
-- Depends on: 已执行至 0188 的单租户平台结构，包含质量任务、对象、审计日志与问题汇总表。
-- Target: 已有数据库增量升级；新库由 datahub-center.sql 一次性安装。
-- Repeatable: 是；结构使用存在性判断，整个脚本在一个事务内提交。
-- Rollback: 无删除或回填业务数据。回滚应用前先备份新表；有评测或处置记录后不得直接删表。
-- 风险：新增外键和字段需短时表锁；请在低峰执行。问题行仅存授权投影的摘要，不写回源业务数据。
BEGIN;
SET LOCAL search_path TO "datahub-center", public;

-- 历史导出表仅保留非空编号，先补全编号唯一性才能建立可验证引用；若已有重复编号则整笔中止，禁止静默去重。
CREATE UNIQUE INDEX IF NOT EXISTS uk_quality_task_id ON dh_governance_quality_task(id);
CREATE UNIQUE INDEX IF NOT EXISTS uk_quality_check_object_id ON dh_governance_quality_check_object(id);
CREATE UNIQUE INDEX IF NOT EXISTS uk_quality_issue_data_id ON dh_governance_quality_issue_data(id);
COMMENT ON INDEX uk_quality_task_id IS '质量任务编号全局唯一，支撑任务评测引用';
COMMENT ON INDEX uk_quality_check_object_id IS '稽查对象编号全局唯一，支撑任务评测引用';
COMMENT ON INDEX uk_quality_issue_data_id IS '问题汇总编号全局唯一，支撑行处置审计引用';

CREATE SEQUENCE IF NOT EXISTS dh_governance_quality_task_evaluation_seq;
COMMENT ON SEQUENCE dh_governance_quality_task_evaluation_seq IS '质量任务评测规则主键序列';
CREATE TABLE IF NOT EXISTS dh_governance_quality_task_evaluation (
    id bigint PRIMARY KEY DEFAULT nextval('dh_governance_quality_task_evaluation_seq'),
    task_id bigint NOT NULL REFERENCES dh_governance_quality_task(id),
    object_id bigint NOT NULL REFERENCES dh_governance_quality_check_object(id),
    evaluation_name varchar(128) NOT NULL,
    rule_code varchar(64) NOT NULL,
    strategy_key varchar(64) NOT NULL,
    quality_dim varchar(32) NOT NULL,
    severity varchar(16) NOT NULL,
    status integer NOT NULL DEFAULT 0 CHECK (status IN (0, 1)),
    description varchar(256) NOT NULL DEFAULT '',
    error_example varchar(256) NOT NULL DEFAULT '',
    repair_advice varchar(256) NOT NULL DEFAULT '',
    where_clause varchar(256) NOT NULL DEFAULT '',
    column_names jsonb NOT NULL CHECK (jsonb_typeof(column_names) = 'array'),
    config jsonb NOT NULL CHECK (jsonb_typeof(config) = 'object'),
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1))
);
COMMENT ON TABLE dh_governance_quality_task_evaluation IS '任务专属评测配置，执行时冻结为实例快照';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.id IS '评测配置编号';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.task_id IS '质量任务编号';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.object_id IS '本任务绑定的稽查对象编号';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.evaluation_name IS '任务内唯一评测名称';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.rule_code IS '稽查规则目录编码';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.strategy_key IS '质量组件执行策略';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.quality_dim IS '质量维度';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.severity IS '告警等级';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.status IS '规则状态：零上线，一下线';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.description IS '规则描述';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.error_example IS '错误示例';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.repair_advice IS '修复建议';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.where_clause IS '经质量组件解析的只读筛选条件';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.column_names IS '检查字段名数组';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.config IS '规则参数；精确数值使用十进制字符串';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.creator IS '创建人';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.create_time IS '创建时间';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.updater IS '更新人';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.update_time IS '更新时间';
COMMENT ON COLUMN dh_governance_quality_task_evaluation.deleted IS '逻辑删除标记';
CREATE UNIQUE INDEX IF NOT EXISTS uk_quality_task_evaluation_name
    ON dh_governance_quality_task_evaluation(task_id, evaluation_name) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_quality_task_evaluation_object ON dh_governance_quality_task_evaluation(object_id);

ALTER TABLE dh_governance_quality_audit_log ADD COLUMN IF NOT EXISTS evaluation_id bigint;
-- 多字段评测与限定 schema 的物理表名可能超过历史单字段长度；只放宽类型，不改写已有值。
ALTER TABLE dh_governance_quality_audit_log ALTER COLUMN check_field TYPE text,
    ALTER COLUMN table_name TYPE varchar(512);
ALTER TABLE dh_governance_quality_issue_data ALTER COLUMN check_field TYPE text,
    ALTER COLUMN table_name TYPE varchar(512);
COMMENT ON COLUMN dh_governance_quality_audit_log.evaluation_id IS '执行时任务评测编号，具体配置以实例快照为准';
CREATE INDEX IF NOT EXISTS idx_quality_audit_evaluation ON dh_governance_quality_audit_log(evaluation_id);

CREATE SEQUENCE IF NOT EXISTS dh_governance_quality_issue_row_state_seq;
COMMENT ON SEQUENCE dh_governance_quality_issue_row_state_seq IS '质量问题行处置主键序列';
CREATE TABLE IF NOT EXISTS dh_governance_quality_issue_row_state (
    id bigint PRIMARY KEY DEFAULT nextval('dh_governance_quality_issue_row_state_seq'),
    issue_id bigint NOT NULL REFERENCES dh_governance_quality_issue_data(id),
    row_key varchar(64) NOT NULL CHECK (row_key ~ '^[0-9a-f]{64}$'),
    state varchar(16) NOT NULL DEFAULT 'UNPROCESSED' CHECK (state IN ('UNPROCESSED', 'IGNORED')),
    revision integer NOT NULL DEFAULT 0 CHECK (revision >= 0),
    remark varchar(500) NOT NULL DEFAULT '',
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0, 1)),
