COMMENT ON COLUMN dh_governance_standard_element_rule.element_id IS '所属数据元编号';
COMMENT ON COLUMN dh_governance_standard_element_rule.kind IS '清洗或稽查类型';
COMMENT ON COLUMN dh_governance_standard_element_rule.name IS '规则实例名称';
COMMENT ON COLUMN dh_governance_standard_element_rule.template_id IS '对应类型的模板编号';
COMMENT ON COLUMN dh_governance_standard_element_rule.status IS '启用状态：0启用1停用';
COMMENT ON COLUMN dh_governance_standard_element_rule.description IS '规则描述';
COMMENT ON COLUMN dh_governance_standard_element_rule.where_condition IS '可复用过滤条件，执行绑定时再次验证';
COMMENT ON COLUMN dh_governance_standard_element_rule.config_json IS '实例规则参数JSON对象';
COMMENT ON COLUMN dh_governance_standard_element_rule.severity IS '严重程度';
COMMENT ON COLUMN dh_governance_standard_element_rule.error_example IS '错误示例';
COMMENT ON COLUMN dh_governance_standard_element_rule.repair_suggestion IS '修复建议';
COMMENT ON COLUMN dh_governance_standard_element_rule.revision IS '编辑并发版本';
COMMENT ON COLUMN dh_governance_standard_element_rule.creator IS '创建者';
COMMENT ON COLUMN dh_governance_standard_element_rule.create_time IS '创建时间';
COMMENT ON COLUMN dh_governance_standard_element_rule.updater IS '更新者';
COMMENT ON COLUMN dh_governance_standard_element_rule.update_time IS '更新时间';
COMMENT ON COLUMN dh_governance_standard_element_rule.deleted IS '逻辑删除：0有效1删除';
COMMENT ON TABLE dh_governance_standard_code_value_mapping IS '代码表原始值映射';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.id IS '映射编号';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.code_set_id IS '所属代码表编号';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.original_value IS '原始值';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.code_item_id IS '所属代码表内的目标码值编号';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.revision IS '编辑并发版本';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.creator IS '创建者';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.create_time IS '创建时间';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.updater IS '更新者';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.update_time IS '更新时间';
COMMENT ON COLUMN dh_governance_standard_code_value_mapping.deleted IS '逻辑删除：0有效1删除';

-- 子配置写入先锁父对象，父对象删除与配置写入使用同一行锁边界。
CREATE OR REPLACE FUNCTION standard_workbench_child_guard() RETURNS trigger LANGUAGE plpgsql AS $guard$
BEGIN
 IF NEW.deleted <> 0 THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME = 'dh_governance_standard_element_rule' THEN
  PERFORM 1 FROM dh_governance_standard_element WHERE id = NEW.element_id AND deleted = 0 AND lifecycle_status NOT IN ('REVIEWING','DEPRECATED') FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '数据元不存在或当前生命周期不可编辑'; END IF;
  IF NEW.kind = 'AUDIT' THEN
   PERFORM 1 FROM dh_governance_audit_rule WHERE id = NEW.template_id AND deleted = 0;
  ELSE
   PERFORM 1 FROM dh_governance_clean_rule WHERE id = NEW.template_id AND deleted = 0;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION '关联规则模板不存在'; END IF;
 ELSE
  PERFORM 1 FROM dh_governance_standard_code_set WHERE id = NEW.code_set_id AND deleted = 0 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '代码表不存在'; END IF;
  PERFORM 1 FROM dh_governance_standard_code_item WHERE id = NEW.code_item_id AND code_set_id = NEW.code_set_id AND deleted = 0 AND status = 0;
  IF NOT FOUND THEN RAISE EXCEPTION '映射码值不属于该代码表或已停用'; END IF;
 END IF;
 RETURN NEW;
END $guard$;
DROP TRIGGER IF EXISTS standard_element_rule_guard ON dh_governance_standard_element_rule;
CREATE TRIGGER standard_element_rule_guard BEFORE INSERT OR UPDATE ON dh_governance_standard_element_rule FOR EACH ROW EXECUTE FUNCTION standard_workbench_child_guard();
DROP TRIGGER IF EXISTS standard_code_value_mapping_guard ON dh_governance_standard_code_value_mapping;
CREATE TRIGGER standard_code_value_mapping_guard BEFORE INSERT OR UPDATE ON dh_governance_standard_code_value_mapping FOR EACH ROW EXECUTE FUNCTION standard_workbench_child_guard();

-- 新引用验证在父行锁内完成，解决存在性检查与软删除之间的竞态。
CREATE OR REPLACE FUNCTION standard_workbench_reference_guard() RETURNS trigger LANGUAGE plpgsql AS $reference$
BEGIN
 IF NEW.deleted <> 0 THEN RETURN NEW; END IF;
 IF NEW.category_id IS NOT NULL THEN
  PERFORM 1 FROM dh_governance_category_datameta WHERE id = NEW.category_id AND deleted = 0 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '共享标准分类不存在'; END IF;
 END IF;
 IF NEW.document_id IS NOT NULL THEN
  PERFORM 1 FROM dh_governance_standard_doc WHERE id = NEW.document_id AND deleted = 0 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '标准文件不存在'; END IF;
 END IF;
 IF TG_TABLE_NAME = 'dh_governance_standard_element' THEN
 IF NEW.code_set_id IS NOT NULL THEN
  PERFORM 1 FROM dh_governance_standard_code_set WHERE id = NEW.code_set_id AND deleted = 0 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '关联代码表不存在'; END IF;
 END IF;
 END IF;
 RETURN NEW;
END $reference$;
DROP TRIGGER IF EXISTS standard_element_reference_guard ON dh_governance_standard_element;
CREATE TRIGGER standard_element_reference_guard BEFORE INSERT OR UPDATE OF category_id,document_id,code_set_id,deleted ON dh_governance_standard_element FOR EACH ROW EXECUTE FUNCTION standard_workbench_reference_guard();
DROP TRIGGER IF EXISTS standard_code_set_reference_guard ON dh_governance_standard_code_set;
CREATE TRIGGER standard_code_set_reference_guard BEFORE INSERT OR UPDATE OF category_id,document_id,deleted ON dh_governance_standard_code_set FOR EACH ROW EXECUTE FUNCTION standard_workbench_reference_guard();

CREATE OR REPLACE FUNCTION standard_workbench_delete_guard() RETURNS trigger LANGUAGE plpgsql AS $delete$
BEGIN
 IF NEW.deleted = 0 OR OLD.deleted <> 0 THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME = 'dh_governance_standard_code_item' THEN
  IF EXISTS (SELECT 1 FROM dh_governance_standard_code_value_mapping WHERE code_item_id = OLD.id AND deleted = 0) THEN RAISE EXCEPTION '码值仍被原始值映射引用'; END IF;
 ELSIF TG_TABLE_NAME = 'dh_governance_standard_code_set' THEN
  IF EXISTS (SELECT 1 FROM dh_governance_standard_element WHERE code_set_id = OLD.id AND deleted = 0)
   OR EXISTS (SELECT 1 FROM dh_governance_standard_code_value_mapping WHERE code_set_id = OLD.id AND deleted = 0) THEN RAISE EXCEPTION '代码表仍被引用'; END IF;
 ELSIF TG_TABLE_NAME = 'dh_governance_standard_element' THEN
  IF EXISTS (SELECT 1 FROM dh_governance_standard_element_rule WHERE element_id = OLD.id AND deleted = 0) THEN RAISE EXCEPTION '数据元仍有关联规则实例'; END IF;
 ELSIF TG_TABLE_NAME = 'dh_governance_category_datameta' THEN
  IF EXISTS (SELECT 1 FROM dh_governance_standard_element WHERE category_id = OLD.id AND deleted = 0)
   OR EXISTS (SELECT 1 FROM dh_governance_standard_code_set WHERE category_id = OLD.id AND deleted = 0) THEN RAISE EXCEPTION '分类仍被标准引用'; END IF;
 ELSIF TG_TABLE_NAME = 'dh_governance_standard_doc' THEN
  IF EXISTS (SELECT 1 FROM dh_governance_standard_element WHERE document_id = OLD.id AND deleted = 0)
   OR EXISTS (SELECT 1 FROM dh_governance_standard_code_set WHERE document_id = OLD.id AND deleted = 0) THEN RAISE EXCEPTION '标准文件仍被引用'; END IF;
 END IF;
 RETURN NEW;
END $delete$;
DROP TRIGGER IF EXISTS workbench_delete_guard ON dh_governance_standard_code_item;
CREATE TRIGGER workbench_delete_guard BEFORE UPDATE OF deleted ON dh_governance_standard_code_item FOR EACH ROW EXECUTE FUNCTION standard_workbench_delete_guard();
DROP TRIGGER IF EXISTS workbench_delete_guard ON dh_governance_standard_code_set;
CREATE TRIGGER workbench_delete_guard BEFORE UPDATE OF deleted ON dh_governance_standard_code_set FOR EACH ROW EXECUTE FUNCTION standard_workbench_delete_guard();
DROP TRIGGER IF EXISTS workbench_delete_guard ON dh_governance_standard_element;
CREATE TRIGGER workbench_delete_guard BEFORE UPDATE OF deleted ON dh_governance_standard_element FOR EACH ROW EXECUTE FUNCTION standard_workbench_delete_guard();
DROP TRIGGER IF EXISTS workbench_delete_guard ON dh_governance_category_datameta;
CREATE TRIGGER workbench_delete_guard BEFORE UPDATE OF deleted ON dh_governance_category_datameta FOR EACH ROW EXECUTE FUNCTION standard_workbench_delete_guard();
DROP TRIGGER IF EXISTS workbench_delete_guard ON dh_governance_standard_doc;
CREATE TRIGGER workbench_delete_guard BEFORE UPDATE OF deleted ON dh_governance_standard_doc FOR EACH ROW EXECUTE FUNCTION standard_workbench_delete_guard();

-- 所有标准父对象变更都递增编辑版本，包括原有绑定及生命周期专用命令。
CREATE OR REPLACE FUNCTION standard_workbench_revision_guard() RETURNS trigger LANGUAGE plpgsql AS $revision$
BEGIN
 NEW.revision := OLD.revision + 1;
 RETURN NEW;
END $revision$;
DROP TRIGGER IF EXISTS workbench_revision_guard ON dh_governance_standard_element;
CREATE TRIGGER workbench_revision_guard BEFORE UPDATE ON dh_governance_standard_element FOR EACH ROW EXECUTE FUNCTION standard_workbench_revision_guard();
DROP TRIGGER IF EXISTS workbench_revision_guard ON dh_governance_standard_code_set;
CREATE TRIGGER workbench_revision_guard BEFORE UPDATE ON dh_governance_standard_code_set FOR EACH ROW EXECUTE FUNCTION standard_workbench_revision_guard();

-- 将已实现且源站数据元启用的两个模板接入现有注册表，不改变规则编号或配置。
DO $templates$
DECLARE item record; matches integer;
BEGIN
 FOR item IN SELECT * FROM (VALUES ('112','FOREIGN_KEY_VALIDATION'),('118','MUTUAL_EXCLUSION_VALIDATION')) AS templates(code,strategy_key) LOOP
  SELECT count(*) INTO matches FROM dh_governance_audit_rule WHERE code=item.code AND deleted=0;
  IF matches<>1 OR EXISTS (SELECT 1 FROM dh_governance_audit_rule WHERE code=item.code AND deleted=0 AND strategy_key IS NOT NULL AND strategy_key<>item.strategy_key) THEN
   RAISE EXCEPTION '0191 稽查规则模板归属冲突: %',item.code;
  END IF;
  UPDATE dh_governance_audit_rule SET strategy_key=item.strategy_key,status=0,updater='migration:0191' WHERE code=item.code AND deleted=0;
 END LOOP;
END $templates$;

-- 移动既有页面和其权限子节点，保留页面ID及已有角色授权。
LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE folder_id bigint; menu_high bigint; role_high bigint; inserted integer; matches integer;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id = 6126 AND path = '/model' AND deleted = 0)
 OR NOT EXISTS (SELECT 1 FROM system_menu WHERE id = 6209 AND component = 'governance/standardelement/index' AND deleted = 0)
 OR NOT EXISTS (SELECT 1 FROM system_menu WHERE id = 6203 AND component = 'governance/standardcodeset/index' AND deleted = 0) THEN
  RAISE EXCEPTION '0191 标准菜单前置状态缺失';
 END IF;
 SELECT count(*), min(id) INTO matches, folder_id FROM system_menu WHERE parent_id = 6126 AND path = 'standard-data-element' AND deleted = 0;
 IF matches > 1 THEN RAISE EXCEPTION '0191 标准目录菜单冲突'; END IF;
 IF matches = 0 THEN
  SELECT greatest(coalesce(max(id),0), (SELECT last_value FROM system_menu_seq), (SELECT last_value FROM system_menu_id_seq)) + 1 INTO folder_id FROM system_menu;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,deleted)
  VALUES(folder_id,'标准数据元','',1,30,6126,'standard-data-element','carbon:data-class',NULL,NULL,0,true,true,true,'migration:0191','migration:0191',0);
 ELSIF NOT EXISTS (SELECT 1 FROM system_menu WHERE id=folder_id AND type=1 AND permission='') THEN RAISE EXCEPTION '0191 标准目录菜单归属冲突';
 END IF;
 UPDATE system_menu SET parent_id=folder_id,name='数据元',path='data-element',sort=1,updater='migration:0191',update_time=CURRENT_TIMESTAMP WHERE id=6209;
 UPDATE system_menu SET parent_id=folder_id,name='代码表',path='code-table',sort=2,updater='migration:0191',update_time=CURRENT_TIMESTAMP WHERE id=6203;
 SELECT greatest(coalesce(max(id),0), (SELECT last_value FROM system_menu_seq), (SELECT last_value FROM system_menu_id_seq)) INTO menu_high FROM system_menu;
 PERFORM setval('system_menu_seq',menu_high); PERFORM setval('system_menu_id_seq',menu_high);
 SELECT greatest(coalesce(max(id),0), (SELECT last_value FROM system_role_menu_seq)) INTO role_high FROM system_role_menu;
 INSERT INTO system_role_menu(id,role_id,menu_id,tenant_id,creator,updater,deleted)
 SELECT role_high + row_number() OVER (ORDER BY p.role_id,p.tenant_id,p.menu_id), p.role_id,p.menu_id,p.tenant_id,'migration:0191','migration:0191',0
 FROM (SELECT DISTINCT old.role_id,old.tenant_id, destination.id AS menu_id
  FROM system_role_menu old JOIN system_menu leaf ON leaf.id=old.menu_id CROSS JOIN unnest(ARRAY[folder_id,6126::bigint]) destination(id)
  WHERE old.deleted=0 AND leaf.deleted=0 AND (leaf.id IN (6209,6203) OR leaf.parent_id IN (6209,6203))
  AND NOT EXISTS (SELECT 1 FROM system_role_menu current WHERE current.role_id=old.role_id AND current.tenant_id=old.tenant_id AND current.menu_id=destination.id AND current.deleted=0)) p;
 GET DIAGNOSTICS inserted = ROW_COUNT;
 IF inserted > 0 THEN PERFORM setval('system_role_menu_seq',role_high+inserted); END IF;
END $menus$;
COMMIT;

-- Migration: 0192 批量文件入库。
-- Purpose: 新增批量文件任务、受管素材、持久执行快照、基础设施文件回执及数据接入菜单权限。
-- Depends on: 0191_governance_standard-element-workbench.sql；数据接入目录、infra 文件及平台身份权限表已就绪。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；表、序列、索引按存在性创建，菜单按组件及权限身份补齐，授权按缺失关系补齐。
-- Rollback: 失败时事务回滚；提交后新增配置与执行审计不可丢弃，回退应用时保留本次新增表，需删除时先备份。
-- 风险：执行本脚本不会连接外部数据库或导入文件；菜单写入持有短锁，建议在维护窗口执行。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE SEQUENCE IF NOT EXISTS infra_managed_file_seq;
CREATE TABLE IF NOT EXISTS infra_managed_file (
 id bigint PRIMARY KEY DEFAULT nextval('infra_managed_file_seq'),
 owner_service varchar(64) NOT NULL,
 operation_key varchar(128) NOT NULL,
 name varchar(255) NOT NULL,
 sha256 varchar(64) NOT NULL,
 size bigint NOT NULL CHECK (size BETWEEN 0 AND 20971520),
 config_id bigint NOT NULL,
 path varchar(1024) NOT NULL,
 state varchar(32) NOT NULL CHECK (state IN ('PENDING','UPLOADING','READY','FAILED','CLEANUP_PENDING','DELETED')),
 file_id bigint,
 creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1)),
 CONSTRAINT uk_infra_managed_file_operation UNIQUE (owner_service, operation_key)
);
CREATE INDEX IF NOT EXISTS idx_infra_managed_file_pending ON infra_managed_file(state,update_time,id) WHERE state IN ('PENDING','UPLOADING','CLEANUP_PENDING','DELETED');

CREATE SEQUENCE IF NOT EXISTS dh_batch_file_task_seq;
CREATE TABLE IF NOT EXISTS dh_batch_file_task (
 id bigint PRIMARY KEY DEFAULT nextval('dh_batch_file_task_seq'),
 task_name varchar(100) NOT NULL,
 responsible_user_id bigint NOT NULL, responsible_name varchar(100) NOT NULL, responsible_phone varchar(32) NOT NULL,
 description varchar(256), remark varchar(256),
 target_database_id bigint NOT NULL, target_database_name varchar(200) NOT NULL,
 online boolean NOT NULL DEFAULT false, revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
 config_json text NOT NULL CHECK (jsonb_typeof(config_json::jsonb) = 'object'),
 last_status varchar(32) NOT NULL DEFAULT 'NOT_EXECUTED' CHECK (last_status IN ('NOT_EXECUTED','QUEUED','RUNNING','SUCCESS','PARTIAL_SUCCESS','FAILED','UNKNOWN')),
 last_run_id bigint, last_run_time timestamp,
 file_count integer NOT NULL CHECK (file_count BETWEEN 1 AND 20), target_count integer NOT NULL CHECK (target_count BETWEEN 1 AND 20),
 success_files integer NOT NULL DEFAULT 0 CHECK (success_files >= 0), failed_files integer NOT NULL DEFAULT 0 CHECK (failed_files >= 0),
 creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_batch_file_task_live_name ON dh_batch_file_task(lower(task_name)) WHERE deleted=0;

CREATE SEQUENCE IF NOT EXISTS dh_batch_file_upload_seq;
CREATE TABLE IF NOT EXISTS dh_batch_file_upload (
 id bigint PRIMARY KEY DEFAULT nextval('dh_batch_file_upload_seq'),
 owner_id bigint NOT NULL, operation_key varchar(64) NOT NULL UNIQUE, storage_file_id bigint,
 name varchar(255) NOT NULL, file_type varchar(8) NOT NULL CHECK (file_type IN ('csv','xls','xlsx')),
 source varchar(16) NOT NULL CHECK (source IN ('LOCAL','SYSTEM')), connection_id bigint, path varchar(2048),
 size bigint NOT NULL CHECK (size BETWEEN 1 AND 20971520), sha256 varchar(64) NOT NULL,
 state varchar(24) NOT NULL CHECK (state IN ('PENDING','READY','FAILED','CLEANUP_PENDING','CLEANED')),
 row_count integer CHECK (row_count BETWEEN 0 AND 100000), fields_json text CHECK (fields_json IS NULL OR jsonb_typeof(fields_json::jsonb)='array'),
 task_id bigint REFERENCES dh_batch_file_task(id), expires_at timestamp NOT NULL,
 creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
);
CREATE INDEX IF NOT EXISTS idx_batch_file_upload_owner ON dh_batch_file_upload(owner_id,task_id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_batch_file_upload_cleanup ON dh_batch_file_upload(expires_at) WHERE task_id IS NULL AND state<>'CLEANED';

CREATE SEQUENCE IF NOT EXISTS dh_batch_file_run_seq;
CREATE TABLE IF NOT EXISTS dh_batch_file_run (
 id bigint PRIMARY KEY DEFAULT nextval('dh_batch_file_run_seq'),
 task_id bigint NOT NULL REFERENCES dh_batch_file_task(id), request_id varchar(64) NOT NULL UNIQUE, execution_user_id bigint NOT NULL,
 config_json text NOT NULL CHECK (jsonb_typeof(config_json::jsonb)='object'),
 status varchar(32) NOT NULL CHECK (status IN ('QUEUED','RUNNING','SUCCESS','PARTIAL_SUCCESS','FAILED','UNKNOWN')),
 lease_token varchar(64), lease_until timestamp, start_time timestamp, end_time timestamp,
 file_count integer NOT NULL CHECK (file_count BETWEEN 1 AND 20),
 success_count integer NOT NULL DEFAULT 0 CHECK (success_count >= 0), failed_count integer NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
 written_rows bigint NOT NULL DEFAULT 0 CHECK (written_rows >= 0),
 items_json text NOT NULL CHECK (jsonb_typeof(items_json::jsonb)='array'), error_message varchar(500),
 resolved_by bigint, resolved_time timestamp, resolution_reason varchar(500),
 creator varchar(64) NOT NULL DEFAULT '', create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '', update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0 CHECK (deleted IN (0,1))
);
CREATE UNIQUE INDEX IF NOT EXISTS uk_batch_file_run_active ON dh_batch_file_run(task_id)
 WHERE deleted=0 AND (status IN ('QUEUED','RUNNING') OR (status='UNKNOWN' AND resolved_time IS NULL));
CREATE INDEX IF NOT EXISTS idx_batch_file_run_task ON dh_batch_file_run(task_id,id DESC) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_batch_file_run_lease ON dh_batch_file_run(status,lease_until) WHERE deleted=0 AND status IN ('QUEUED','RUNNING');

COMMENT ON TABLE infra_managed_file IS '受服务身份约束的文件存储意图及可重放回执';
COMMENT ON TABLE dh_batch_file_task IS '批量文件入库配置，保存不触发外部写入';
COMMENT ON TABLE dh_batch_file_upload IS '批量文件入库素材登记及归属';
COMMENT ON TABLE dh_batch_file_run IS '批量文件入库持久执行快照及逐文件结果';

-- 所有字段均补充中文说明，循环仅用于减少相同审计字段的重复语句。
DO $comments$
DECLARE item record; table_name text;
BEGIN
 FOR item IN SELECT * FROM (VALUES
 ('infra_managed_file','id','受管文件编号'),('infra_managed_file','owner_service','认证得到的调用服务身份'),
 ('infra_managed_file','operation_key','调用服务范围内稳定幂等键'),('infra_managed_file','name','原文件名称'),
 ('infra_managed_file','sha256','内容摘要'),('infra_managed_file','size','内容字节数'),('infra_managed_file','config_id','基础设施文件配置编号'),
 ('infra_managed_file','path','服务端生成的对象路径'),('infra_managed_file','state','存储生命周期状态'),('infra_managed_file','file_id','已登记的平台文件编号'),
 ('dh_batch_file_task','id','任务编号'),('dh_batch_file_task','task_name','任务名称'),('dh_batch_file_task','responsible_user_id','负责人编号'),
 ('dh_batch_file_task','responsible_name','负责人名称快照'),('dh_batch_file_task','responsible_phone','负责人联系电话快照'),
 ('dh_batch_file_task','description','任务描述'),('dh_batch_file_task','remark','任务备注'),('dh_batch_file_task','target_database_id','目标数据源编号'),
 ('dh_batch_file_task','target_database_name','目标数据源名称快照'),('dh_batch_file_task','online','是否上线'),('dh_batch_file_task','revision','并发编辑修订号'),
 ('dh_batch_file_task','config_json','文件结构及目标分组配置，不含连接凭据'),('dh_batch_file_task','last_status','最近执行状态'),
 ('dh_batch_file_task','last_run_id','最近执行实例编号'),('dh_batch_file_task','last_run_time','最近执行时间'),
 ('dh_batch_file_task','file_count','配置文件数量'),('dh_batch_file_task','target_count','目标表数量'),
 ('dh_batch_file_task','success_files','最近实例成功文件数'),('dh_batch_file_task','failed_files','最近实例失败文件数'),
 ('dh_batch_file_upload','id','素材编号'),('dh_batch_file_upload','owner_id','上传者编号'),('dh_batch_file_upload','operation_key','跨服务存储幂等键'),
 ('dh_batch_file_upload','storage_file_id','基础设施受管文件编号'),('dh_batch_file_upload','name','文件名称'),('dh_batch_file_upload','file_type','文件扩展类型'),
 ('dh_batch_file_upload','source','文件来源：本地或系统文件'),('dh_batch_file_upload','connection_id','系统文件连接编号'),
 ('dh_batch_file_upload','path','来源逻辑路径'),('dh_batch_file_upload','size','文件字节数'),('dh_batch_file_upload','sha256','文件内容摘要'),
 ('dh_batch_file_upload','state','上传登记状态'),('dh_batch_file_upload','row_count','解析数据行数'),('dh_batch_file_upload','fields_json','原始字段结构'),
 ('dh_batch_file_upload','task_id','绑定任务编号'),('dh_batch_file_upload','expires_at','未绑定素材回收时间'),
 ('dh_batch_file_run','id','执行实例编号'),('dh_batch_file_run','task_id','所属任务编号'),('dh_batch_file_run','request_id','浏览器执行命令幂等键'),
 ('dh_batch_file_run','execution_user_id','执行人编号'),('dh_batch_file_run','config_json','受理时冻结的任务配置'),('dh_batch_file_run','status','执行结果状态'),
 ('dh_batch_file_run','lease_token','执行领取令牌'),('dh_batch_file_run','lease_until','领取有效期'),('dh_batch_file_run','start_time','执行开始时间'),
 ('dh_batch_file_run','end_time','执行结束时间'),('dh_batch_file_run','file_count','文件总数'),('dh_batch_file_run','success_count','成功文件数'),
 ('dh_batch_file_run','failed_count','失败文件数'),('dh_batch_file_run','written_rows','已确认写入行数'),('dh_batch_file_run','items_json','逐文件写入结果'),
 ('dh_batch_file_run','error_message','脱敏结果说明'),('dh_batch_file_run','resolved_by','人工核对人编号'),
 ('dh_batch_file_run','resolved_time','人工核对时间'),('dh_batch_file_run','resolution_reason','人工确认终止与核对目标的说明')
 ) descriptions(table_name,column_name,description) LOOP
  EXECUTE format('COMMENT ON COLUMN %I.%I IS %L',item.table_name,item.column_name,item.description);
 END LOOP;
 FOREACH table_name IN ARRAY ARRAY['infra_managed_file','dh_batch_file_task','dh_batch_file_upload','dh_batch_file_run'] LOOP
  EXECUTE format('COMMENT ON COLUMN %I.creator IS %L',table_name,'创建人');
  EXECUTE format('COMMENT ON COLUMN %I.create_time IS %L',table_name,'创建时间');
  EXECUTE format('COMMENT ON COLUMN %I.updater IS %L',table_name,'更新人');
  EXECUTE format('COMMENT ON COLUMN %I.update_time IS %L',table_name,'更新时间');
  EXECUTE format('COMMENT ON COLUMN %I.deleted IS %L',table_name,'逻辑删除标记');
 END LOOP;
END $comments$;

LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE page_id bigint; new_id bigint; high_id bigint; matches integer; item record;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id=5987 AND path='integrate' AND deleted=0) THEN
  RAISE EXCEPTION '0192 数据接入父菜单缺失';
 END IF;
 SELECT count(*),min(id) INTO matches,page_id FROM system_menu WHERE component='dataforge/batchfile/index' AND deleted=0;
 IF matches>1 THEN RAISE EXCEPTION '0192 批量文件入库页面重复'; END IF;
 IF matches=0 THEN
  IF EXISTS(SELECT 1 FROM system_menu WHERE deleted=0 AND (permission='dataforge:batch-file:query' OR (parent_id=5987 AND path='batch-file'))) THEN
   RAISE EXCEPTION '0192 批量文件菜单身份冲突';
  END IF;
  SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO page_id FROM system_menu;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,deleted)
  VALUES(page_id,'批量文件入库','dataforge:batch-file:query',2,4,5987,'batch-file','carbon:document-import','dataforge/batchfile/index','DataforgeBatchFile',0,true,true,true,'migration:0192','migration:0192',0);
 ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=page_id AND parent_id=5987 AND path='batch-file' AND permission='dataforge:batch-file:query' AND type=2) THEN
  RAISE EXCEPTION '0192 批量文件菜单归属冲突';
 END IF;
 FOR item IN SELECT * FROM (VALUES ('create','新增及上传',1),('update','配置及上下线',2),('delete','删除任务',3),('execute','执行及异常核对',4)) permissions(code,label,sort) LOOP
  SELECT count(*) INTO matches FROM system_menu WHERE permission='dataforge:batch-file:'||item.code AND deleted=0;
  IF matches=0 THEN
   SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO new_id FROM system_menu;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
   VALUES(new_id,item.label,'dataforge:batch-file:'||item.code,3,item.sort,page_id,'',0,true,true,true,'migration:0192','migration:0192',0);
  ELSIF matches<>1 OR NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='dataforge:batch-file:'||item.code AND parent_id=page_id AND type=3 AND deleted=0) THEN
   RAISE EXCEPTION '0192 批量文件权限归属冲突';
  END IF;
 END LOOP;
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq)) INTO high_id FROM system_menu;
 PERFORM setval('system_menu_seq',high_id); PERFORM setval('system_menu_id_seq',high_id);
 -- 仅补齐超级管理员授权，其他角色由管理员按职责分配。
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
 INSERT INTO system_role_menu(id,role_id,menu_id,tenant_id,creator,updater,deleted)
 SELECT high_id+row_number() OVER(ORDER BY r.id,r.tenant_id,m.id),r.id,m.id,r.tenant_id,'migration:0192','migration:0192',0
 FROM system_role r CROSS JOIN system_menu m
 WHERE r.code='super_admin' AND r.deleted=0 AND m.deleted=0 AND (m.id=page_id OR m.parent_id=page_id)
 AND NOT EXISTS(SELECT 1 FROM system_role_menu old WHERE old.role_id=r.id AND old.tenant_id=r.tenant_id AND old.menu_id=m.id AND old.deleted=0);
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
 PERFORM setval('system_role_menu_seq',high_id);
END $menus$;
COMMIT;

-- 0195 市政务标准数据元类目初始化；新库直接得到最终分类和未分类的旧标准。
-- Migration: 0195 重建市政务标准数据元类目。
-- Purpose: 清空误用的清洗规则分类，建立七个公共数据元对象根类及二十八个平台管理子类，解除旧分类引用并保留标准本体。
-- Depends on: 0194_governance_remove-standard-naming.sql 已执行，或已核验平台达到对应状态；0191 的共享分类、修订号和引用触发器已生效。
-- Target: 已有 PostgreSQL 平台库，固定 schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 否；一次性全量替换，检测到本迁移创建的类目即拒绝再次执行，避免覆盖后续维护的数据。
-- Rollback: 失败整笔回滚；提交后须从执行前备份恢复类目表及三个标准表的分类、修订号和审计字段，保留序列高水位。
-- 不可逆操作：物理删除全部现有类目，包括停用和逻辑删除记录；三个标准表的旧分类全部置空，历史版本快照不重写。
-- 执行前备份类目、标准数据元、标准码表和业务术语四表，并暂停相关编辑；不级联删除其他业务记录。
-- 事务内锁定四表及编号序列，锁等待超过十秒或语句执行超过两分钟则回滚。
-- 分类依据：GB/T 19488.2-2008 第 4.2 条的人员、机构、位置、时间、公文、金融、其他七类；二级为平台管理细分。
-- 国家标准信息：https://openstd.samr.gov.cn/bzgk/std/newGbInfo?hcno=C908E4E99C95626962B7C6648816CBFB
-- 类目主键及层级路径只用于平台管理，不作为国家标准的数据元内部标识符。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE dh_governance_standard_element, dh_governance_standard_code_set,
    dh_governance_standard_term, dh_governance_category_datameta IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM dh_governance_category_datameta WHERE creator = 'migration:0195') THEN
        RAISE EXCEPTION '0195 标准数据元类目已初始化，禁止再次清空';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_sequence
        WHERE seqrelid = 'dh_foundation_category_datameta_seq'::regclass AND seqincrement = 1
    ) THEN
        RAISE EXCEPTION '0195 类目编号序列不存在或步长不是一，禁止重建';
    END IF;
END $preflight$;

-- 获取序列事务锁后再读取高水位；事务式重启避免回退并发已分配的编号。
ALTER SEQUENCE dh_foundation_category_datameta_seq INCREMENT BY 1;

DO $reset_categories$
DECLARE
    high_id bigint;
    new_id bigint;
    parent_id bigint;
    category_path text;
    new_ids bigint[] := ARRAY[]::bigint[];
    item record;
BEGIN
    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM dh_foundation_category_datameta_seq))
    INTO high_id FROM dh_governance_category_datameta;
    IF high_id > 9223372036854775807 - 35 THEN
        RAISE EXCEPTION '0195 类目编号空间不足，禁止重建';
    END IF;
    EXECUTE format('ALTER SEQUENCE dh_foundation_category_datameta_seq RESTART WITH %s', high_id + 1);

    -- 原分类没有可靠的政务语义映射，当前标准归为未分类；修订触发器使并发旧表单失效。
    UPDATE dh_governance_standard_element
    SET category_id = NULL, revision = revision + 1, updater = 'migration:0195', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;
    UPDATE dh_governance_standard_code_set
    SET category_id = NULL, revision = revision + 1, updater = 'migration:0195', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;
    UPDATE dh_governance_standard_term
    SET category_id = NULL, updater = 'migration:0195', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;

    DELETE FROM dh_governance_category_datameta;

    -- 父类先于子类分配新编号，全部编号高于旧类目及序列高水位，避免历史快照误认新分类。
    FOR item IN SELECT * FROM (VALUES
        (1, 0, '人员类', 1, '依据 GB/T 19488.2-2008 第4.2条设置，管理自然人相关公共数据元。'),
        (2, 1, '身份标识', 1, '平台管理子类：姓名、身份证件类型、证件号码等自然人身份标识。'),
        (3, 1, '人口特征', 2, '平台管理子类：性别、民族、国籍、婚姻状况等人口基本特征。'),
        (4, 1, '教育与专业', 3, '平台管理子类：学历、学位、所学专业、专业技术资格等信息。'),
        (5, 1, '从业与任职', 4, '平台管理子类：职业、职务、职级、就业状态等从业任职信息。'),
        (6, 1, '联系信息', 5, '平台管理子类：联系电话、电子邮箱等自然人联系信息，地址归入位置类。'),
        (7, 0, '机构类', 2, '依据 GB/T 19488.2-2008 第4.2条设置，管理法人及其他组织相关公共数据元。'),
        (8, 7, '机构标识', 1, '平台管理子类：统一社会信用代码、组织机构代码等机构身份标识。'),
        (9, 7, '机构名称', 2, '平台管理子类：机构全称、简称、曾用名等机构名称信息。'),
        (10, 7, '机构类型', 3, '平台管理子类：机构类别、组织形式、经济类型等机构分类信息。'),
        (11, 7, '行业与经营', 4, '平台管理子类：行业类别、经营范围、登记状态等机构经营属性。'),
        (12, 7, '设立与注销', 5, '平台管理子类：登记机关、设立方式、注销原因等登记管理属性，具体日期归入时间类。'),
        (13, 0, '位置类', 3, '依据 GB/T 19488.2-2008 第4.2条设置，管理行政区划、地理位置及地址相关公共数据元。'),
        (14, 13, '行政区划', 1, '平台管理子类：行政区划代码、行政区划名称、乡镇街道及村社区标识。'),
        (15, 13, '地理位置', 2, '平台管理子类：经度、纬度、空间位置标识等地理定位信息。'),
        (16, 13, '地址信息', 3, '平台管理子类：标准地址、道路名称、门楼牌号、邮政编码等地址要素。'),
        (17, 0, '时间类', 4, '依据 GB/T 19488.2-2008 第4.2条设置，管理日期、时刻及日期时间相关公共数据元。'),
        (18, 17, '日期', 1, '平台管理子类：出生日期、成立日期、办理日期、有效期起止日期等日历日期。'),
        (19, 17, '时刻', 2, '平台管理子类：受理时刻、办结时刻等不含日期的日内时间。'),
        (20, 17, '日期时间', 3, '平台管理子类：登记时间、更新时间、事件发生时间等完整日期时间。'),
        (21, 0, '公文类', 5, '依据 GB/T 19488.2-2008 第4.2条设置，管理政务公文及其流转相关公共数据元。'),
        (22, 21, '公文标识', 1, '平台管理子类：公文标识、发文字号、文种等公文识别信息。'),
        (23, 21, '标题与主题', 2, '平台管理子类：公文标题、主题词、内容摘要等主题信息。'),
        (24, 21, '行文主体', 3, '平台管理子类：发文机关、主送机关、抄送机关等行文主体信息。'),
        (25, 21, '密级与紧急程度', 4, '平台管理子类：公文密级、保密期限、紧急程度等管理属性。'),
        (26, 21, '印发与流转', 5, '平台管理子类：印发机构、份号、份数、流转状态等印发流转属性，具体日期归入时间类。'),
        (27, 0, '金融类', 6, '依据 GB/T 19488.2-2008 第4.2条设置，管理货币、金额、账户及汇率相关公共数据元。'),
        (28, 27, '币种与货币代码', 1, '平台管理子类：货币名称、货币字母代码、货币数字代码等币种信息。'),
        (29, 27, '金额与资金', 2, '平台管理子类：金额、资金数额、收支金额等货币度量信息。'),
        (30, 27, '银行账户', 3, '平台管理子类：银行账号、账户名称、开户银行等银行账户信息。'),
        (31, 27, '汇率', 4, '平台管理子类：汇率数值、汇率种类、折算比例等货币兑换信息。'),
        (32, 0, '其他类', 7, '依据 GB/T 19488.2-2008 第4.2条设置，管理前六类之外的其他公共数据元。'),
        (33, 32, '物品与商品', 1, '平台管理子类：物品名称、商品标识、规格型号等物品与商品属性。'),
        (34, 32, '计量单位', 2, '平台管理子类：计量单位名称、单位符号、计量单位代码等单位信息。'),
        (35, 32, '通用描述', 3, '平台管理子类：备注、说明等无法归入其他对象类的通用描述信息。')
    ) AS seed(seed_key, parent_key, category_name, sort, remark) ORDER BY seed_key
    LOOP
        new_id := nextval('dh_foundation_category_datameta_seq');
        new_ids[item.seed_key] := new_id;
        parent_id := CASE WHEN item.parent_key = 0 THEN 0 ELSE new_ids[item.parent_key] END;
        category_path := CASE WHEN parent_id = 0 THEN '0,' || new_id
            ELSE '0,' || parent_id || ',' || new_id END;
        INSERT INTO dh_governance_category_datameta
            (id, parent_id, category_name, category_code, sort, status, remark, creator, updater, deleted)
        VALUES (new_id, parent_id, item.category_name, category_path, item.sort, 0, item.remark,
            'migration:0195', 'migration:0195', 0);
    END LOOP;
END $reset_categories$;

COMMIT;

-- Migration: 0196 清理无调用的旧资产持久化对象
-- Purpose: 删除旧资源数据项、旧交付台账及其序列；当前交付继续使用 dh_market_delivery_operation。
-- Depends on: 0195_governance_government-datameta-categories.sql；资产旧表来自既有平台基线。
-- Target: 已升级至 0195 的 PostgreSQL 平台数据库；新库由完整基线包含本变更。
-- Repeatable: 是；对象缺失时跳过，全部操作位于同一事务。
-- Rollback: 不可自动回滚；恢复结构需使用执行前备份。非空旧表会中止，须先独立核实并归档数据。
-- 风险：删除表需要排他锁；等待超过 5 秒即失败。保留外部依赖检查，不使用 CASCADE。

BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL search_path = "datahub-center", pg_catalog;

DO $retire_unused_asset_tables$
DECLARE
    retired_table text;
    contains_data boolean;
BEGIN
    FOREACH retired_table IN ARRAY ARRAY['dh_asset_data_item', 'dh_asset_delivery_op']
    LOOP
        IF to_regclass(format('%I.%I', 'datahub-center', retired_table)) IS NOT NULL THEN
            -- 锁定后再检查数据，避免检查与删除之间出现并发写入。
            EXECUTE format('LOCK TABLE %I.%I IN ACCESS EXCLUSIVE MODE', 'datahub-center', retired_table);
            EXECUTE format('SELECT EXISTS (SELECT 1 FROM %I.%I LIMIT 1)', 'datahub-center', retired_table)
                INTO contains_data;
            IF contains_data THEN
                RAISE EXCEPTION '旧资产表 % 非空，已中止清理；请先核实并归档存量数据', retired_table;
            END IF;
        END IF;
    END LOOP;
END $retire_unused_asset_tables$;

DROP TABLE IF EXISTS "datahub-center".dh_asset_data_item;
DROP TABLE IF EXISTS "datahub-center".dh_asset_delivery_op;
DROP SEQUENCE IF EXISTS "datahub-center".dh_asset_data_item_seq;
DROP SEQUENCE IF EXISTS "datahub-center".dh_asset_delivery_op_seq;

COMMIT;

-- Migration: 0197 多协议连接器目录及仅测连接入。
-- Purpose: 补齐九种数据库、六种外部文件/缓存/消息连接及 SFTP，保留 InfluxDB 3 并新增 2.x 兼容入口。
-- Depends on: 0196_asset_remove-unused-persistence.sql；0173 的连接分类、0186 的文件连接及既有目录序列已存在。
-- Target: 已升级至 0196 的 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；有效类型按规范编码补齐，不改写原编号、连接引用、用户模板和已有描述。
-- Rollback: 事务失败自动回滚；提交后可停用新增目录，不能删除已被连接引用的类型；列扩容回退前须检查已有值长度。
-- 风险：列扩容及目录、字典写入需要短暂锁；不连接或修改任何外部数据源，不产生平台租户字段。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

ALTER TABLE dh_dataforge_database ALTER COLUMN database_ip TYPE varchar(253);
ALTER TABLE dh_dataforge_database ALTER COLUMN user_name TYPE varchar(512);
COMMENT ON COLUMN dh_dataforge_database.database_ip IS '连接主机，Endpoint 或服务器列表协议可为空串，按协议校验';
COMMENT ON COLUMN dh_dataforge_database.database_port IS '连接端口，Endpoint 或服务器列表协议可为空串';
COMMENT ON COLUMN dh_dataforge_database.user_name IS '账号、AccessKey 标识或 InfluxDB 组织名称，不保存秘密';
COMMENT ON COLUMN dh_dataforge_database.database_name IS '目标数据库、Bucket 或项目名称，按连接协议解释';
COMMENT ON COLUMN dh_dataforge_database.extend_config IS 'JDBC 为连接参数；新原生协议为版本化非秘密 JSON，凭据只存加密密码列';
COMMENT ON COLUMN dh_dataforge_database_type.protocol_type IS '连接协议：JDBC、HTTP、S3、FTP、SFTP、WEBHDFS、REDIS、KAFKA、AMQP、ROCKETMQ、ODPS、BOLT、MILVUS 等';

CREATE TEMP TABLE connect_only_seed (
    code text, name text, category text, protocol text, port text, template text, probe text, description text, ordering integer
) ON COMMIT DROP;
