DO $catalog$
DECLARE item record; matches integer;
BEGIN
 FOR item IN SELECT * FROM audit_engine_seed LOOP
  SELECT count(*) INTO matches FROM dh_governance_audit_rule WHERE code=item.code AND name=item.name AND deleted=0;
  IF matches<>1 OR EXISTS (SELECT 1 FROM dh_governance_audit_rule WHERE code=item.code AND deleted=0 AND
      (name<>item.name OR (nullif(btrim(strategy_key),'') IS NOT NULL AND strategy_key<>item.strategy_key))) THEN
   RAISE EXCEPTION '0198 稽查内置目录归属冲突: %',item.code;
  END IF;
 END LOOP;
 FOR item IN SELECT * FROM clean_engine_seed LOOP
  SELECT count(*) INTO matches FROM dh_governance_clean_rule WHERE code=item.code AND name=item.name AND deleted=0;
  IF matches<>1 OR EXISTS (SELECT 1 FROM dh_governance_clean_rule WHERE code=item.code AND deleted=0 AND
      (name<>item.name OR (nullif(btrim(strategy_key),'') IS NOT NULL AND strategy_key<>item.strategy_key))) THEN
   RAISE EXCEPTION '0198 清洗内置目录归属冲突: %',item.code;
  END IF;
 END LOOP;
END $catalog$;

UPDATE dh_governance_audit_rule t SET strategy_key=s.strategy_key,rule_level=s.rule_level,
 status=CASE WHEN nullif(btrim(t.strategy_key),'') IS NULL THEN 0 ELSE t.status END,
 updater='migration:0198',update_time=CURRENT_TIMESTAMP
FROM audit_engine_seed s WHERE t.code=s.code AND t.name=s.name AND t.deleted=0
 AND (nullif(btrim(t.strategy_key),'') IS NULL OR t.rule_level<>s.rule_level);

UPDATE dh_governance_clean_rule t SET strategy_key=s.strategy_key,rule_level=s.rule_level,
 status=CASE WHEN nullif(btrim(t.strategy_key),'') IS NULL THEN 0 ELSE t.status END,
 updater='migration:0198',update_time=CURRENT_TIMESTAMP
FROM clean_engine_seed s WHERE t.code=s.code AND t.name=s.name AND t.deleted=0
 AND (nullif(btrim(t.strategy_key),'') IS NULL OR t.rule_level<>s.rule_level);
COMMIT;

-- Migration: 0199 标准文件分类、版本信息与关联工作台。
-- Purpose: 保留原页面为标准文件检索，新建标准文件登记入口，扩展元信息、状态字典、关联索引及类目引用保护。
-- Depends on: 0198_governance_complete-rule-engines.sql 已执行；0191 标准工作台和 0195 共享类目已就绪。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 是；字段、约束、索引及字典均检测存在性，触发器和函数可重建。
-- Rollback: 失败整体回滚；提交后回退应用可保留新增字段。删除字段会丢失类目、版本号和废止日期，须先备份并单独编写回滚迁移。
-- 执行影响：在事务内短暂锁定标准文件及类目表，普通索引构建会阻塞相应写入；锁等待十秒或执行两分钟超时即整体回滚。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_governance_standard_doc ADD COLUMN IF NOT EXISTS category_id bigint;
ALTER TABLE dh_governance_standard_doc ADD COLUMN IF NOT EXISTS version_no varchar(64);
ALTER TABLE dh_governance_standard_doc ADD COLUMN IF NOT EXISTS abolish_date date;
COMMENT ON COLUMN dh_governance_standard_doc.category_id IS '共享标准类目编号；历史未分类记录允许为空';
COMMENT ON COLUMN dh_governance_standard_doc.version_no IS '标准文件标注的版本号，与平台版本快照序号独立';
COMMENT ON COLUMN dh_governance_standard_doc.abolish_date IS '标准废止日期';

DO $constraints$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'fk_standard_doc_category'
            AND conrelid = 'dh_governance_standard_doc'::regclass) THEN
        ALTER TABLE dh_governance_standard_doc ADD CONSTRAINT fk_standard_doc_category
            FOREIGN KEY (category_id) REFERENCES dh_governance_category_datameta(id);
    END IF;
END $constraints$;

CREATE INDEX IF NOT EXISTS idx_standard_doc_category_live
    ON dh_governance_standard_doc(category_id, std_type, id DESC) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_standard_element_document_live
    ON dh_governance_standard_element(document_id, id DESC) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_standard_code_set_document_live
    ON dh_governance_standard_code_set(document_id, id DESC) WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_logic_model_document_live
    ON dh_modeling_logic_model(document_id, id DESC) WHERE deleted = 0;

-- 文档写入与类目逻辑删除争用相同父行锁，避免检查通过后父类目被删除。
CREATE OR REPLACE FUNCTION standard_doc_category_reference_guard() RETURNS trigger
LANGUAGE plpgsql AS $guard$
BEGIN
    IF NEW.deleted = 0 AND NEW.category_id IS NOT NULL THEN
        PERFORM 1 FROM dh_governance_category_datameta
            WHERE id = NEW.category_id AND deleted = 0 FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION '标准文件类目不存在或已删除'; END IF;
    END IF;
    RETURN NEW;
END $guard$;
DROP TRIGGER IF EXISTS standard_doc_category_reference_guard ON dh_governance_standard_doc;
CREATE TRIGGER standard_doc_category_reference_guard
    BEFORE INSERT OR UPDATE OF category_id, deleted ON dh_governance_standard_doc
    FOR EACH ROW EXECUTE FUNCTION standard_doc_category_reference_guard();

CREATE OR REPLACE FUNCTION standard_doc_category_delete_guard() RETURNS trigger
LANGUAGE plpgsql AS $guard$
BEGIN
    IF NEW.deleted <> 0 AND OLD.deleted = 0 AND EXISTS (
        SELECT 1 FROM dh_governance_standard_doc WHERE category_id = OLD.id AND deleted = 0
    ) THEN
        RAISE EXCEPTION '类目仍被标准文件引用';
    END IF;
    RETURN NEW;
END $guard$;
DROP TRIGGER IF EXISTS standard_doc_category_delete_guard ON dh_governance_category_datameta;
CREATE TRIGGER standard_doc_category_delete_guard BEFORE UPDATE OF deleted ON dh_governance_category_datameta
    FOR EACH ROW EXECUTE FUNCTION standard_doc_category_delete_guard();

-- 使用现有字典协议，保留已有状态、标签和历史数据。
LOCK TABLE system_dict_data IN SHARE ROW EXCLUSIVE MODE;
SELECT setval('system_dict_data_seq', GREATEST(
    (SELECT last_value FROM system_dict_data_seq),
    COALESCE((SELECT max(id) FROM system_dict_data), 1)
));
INSERT INTO system_dict_data (id, sort, label, value, dict_type, status, color_type, creator, updater, deleted)
SELECT nextval('system_dict_data_seq'), seed.sort, seed.label, seed.value,
    'standard_implement_status', 0, seed.color_type, 'migration:0199', 'migration:0199', 0
FROM (VALUES
    (0, '草案', 'DRAFT', 'default'),
    (5, '修订中', 'REVISING', 'orange'),
    (6, '过渡期', 'TRANSITION', 'gold')
) AS seed(sort, label, value, color_type)
WHERE NOT EXISTS (SELECT 1 FROM system_dict_data existing
    WHERE existing.dict_type = 'standard_implement_status' AND existing.value = seed.value AND existing.deleted = 0);

-- 原页面只更名，组件、路径及原有权限不变；登记使用独立页面并共用标准文件操作权限。
LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;
SELECT setval('system_menu_seq', GREATEST(
    (SELECT last_value FROM system_menu_seq), (SELECT last_value FROM system_menu_id_seq),
    COALESCE((SELECT max(id) FROM system_menu), 1)
));
CREATE TEMP TABLE standard_doc_menu_mapping (source_id bigint PRIMARY KEY, target_id bigint NOT NULL) ON COMMIT DROP;
DO $menus$
DECLARE original system_menu%ROWTYPE; action system_menu%ROWTYPE; registration_id bigint; action_id bigint;
BEGIN
    SELECT * INTO STRICT original FROM system_menu WHERE component = 'governance/doc/index' AND deleted = 0;
    UPDATE system_menu SET name = '标准文件检索', updater = 'migration:0199', update_time = CURRENT_TIMESTAMP
        WHERE id = original.id AND name <> '标准文件检索';
    IF EXISTS (SELECT 1 FROM system_menu WHERE parent_id = original.parent_id AND path = 'doc-register'
            AND deleted = 0 AND component IS DISTINCT FROM 'governance/doc-register/index') THEN
        RAISE EXCEPTION '标准文件登记菜单路径被其他组件占用';
    END IF;
    SELECT id INTO registration_id FROM system_menu
        WHERE component = 'governance/doc-register/index' AND deleted = 0;
    IF registration_id IS NULL THEN
        registration_id := nextval('system_menu_seq');
        INSERT INTO system_menu (id, name, permission, type, sort, parent_id, path, icon, component,
            component_name, status, visible, keep_alive, always_show, creator, updater, deleted)
        VALUES (registration_id, '标准文件登记', '', 2, original.sort + 1, original.parent_id,
            'doc-register', 'carbon:document-add', 'governance/doc-register/index', 'StandardDocRegister',
            original.status, true, true, true, 'migration:0199', 'migration:0199', 0);
    END IF;
    INSERT INTO standard_doc_menu_mapping VALUES (original.id, registration_id);
    FOR action IN SELECT * FROM system_menu
        WHERE parent_id = original.id AND type = 3 AND deleted = 0 AND permission LIKE 'governance:doc:%'
    LOOP
        SELECT id INTO action_id FROM system_menu
            WHERE parent_id = registration_id AND permission = action.permission AND type = 3 AND deleted = 0;
        IF action_id IS NULL THEN
            action_id := nextval('system_menu_seq');
            INSERT INTO system_menu (id, name, permission, type, sort, parent_id, path, icon, component,
                component_name, status, visible, keep_alive, always_show, creator, updater, deleted)
            VALUES (action_id, action.name, action.permission, 3, action.sort, registration_id, '', '', '', '',
                action.status, true, true, true, 'migration:0199', 'migration:0199', 0);
        END IF;
        INSERT INTO standard_doc_menu_mapping VALUES (action.id, action_id);
    END LOOP;
END $menus$;
SELECT setval('system_menu_id_seq', GREATEST((SELECT last_value FROM system_menu_id_seq),
    (SELECT last_value FROM system_menu_seq), (SELECT max(id) FROM system_menu)));
SELECT setval('system_role_menu_seq', GREATEST((SELECT last_value FROM system_role_menu_seq),
    COALESCE((SELECT max(id) FROM system_role_menu), 1)));

-- 仅继承原菜单和对应按钮已有的授权，不向只读角色新增写权限。
INSERT INTO system_role_menu (id, role_id, menu_id, tenant_id, creator, updater, deleted)
SELECT nextval('system_role_menu_seq'), source.role_id, mapping.target_id, source.tenant_id,
    'migration:0199', 'migration:0199', 0
FROM (SELECT DISTINCT role_id, menu_id, tenant_id FROM system_role_menu WHERE deleted = 0) source
JOIN standard_doc_menu_mapping mapping ON mapping.source_id = source.menu_id
WHERE NOT EXISTS (SELECT 1 FROM system_role_menu existing WHERE existing.role_id = source.role_id
    AND existing.menu_id = mapping.target_id AND existing.tenant_id = source.tenant_id AND existing.deleted = 0);

-- 通用脚手架套餐保留原有元素及权限范围，仅追加与已有菜单对应的新入口。
WITH additions AS (
    SELECT package.id, jsonb_agg(mapping.target_id ORDER BY mapping.target_id) AS ids
    FROM system_tenant_package package
    JOIN standard_doc_menu_mapping mapping ON EXISTS (
        SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
        WHERE entry.value = mapping.source_id::text
    )
    WHERE package.deleted = 0 AND NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
        WHERE entry.value = mapping.target_id::text
    )
    GROUP BY package.id
)
UPDATE system_tenant_package package SET menu_ids = (package.menu_ids::jsonb || additions.ids)::text,
    updater = 'migration:0199', update_time = CURRENT_TIMESTAMP
FROM additions WHERE additions.id = package.id;

COMMIT;


-- Migration: 0200 按参考截图重建水利行业标准分类。
-- Purpose: 清空现有共享标准类目，建立十个一级、五十六个二级类目，保留标准文件、数据元、代码表和业务术语本体。
-- Depends on: 0199_governance_standard-document-workbench.sql 已执行；0191 的标准引用及修订触发器、0195 的单平台共享类目已就绪。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 否；一次性全量替换，检测到本迁移创建的类目即拒绝执行，防止覆盖后续人工维护的数据。
-- Rollback: 失败整体回滚；提交后须从执行前备份恢复类目及四个标准表的分类、修订号和审计字段，保留序列高水位。
-- 不可逆操作：物理删除全部旧类目（含停用及逻辑删除记录），四个标准表的旧类目关联置空；不可变历史版本快照不重写。
-- 执行前备份上述五表及类目序列状态，并暂停相关编辑；不会级联删除任何标准业务记录。
-- 执行影响：事务内锁定五表及类目编号序列，锁等待十秒或单语句执行两分钟超时即整体回滚。
-- 数据来源：用户提供的五张标准分类管理截图；名称、两级关系、描述和从零开始的排序逐项对应，启用状态沿用平台协议零。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE dh_governance_standard_doc, dh_governance_standard_element,
    dh_governance_standard_code_set, dh_governance_standard_term,
    dh_governance_category_datameta IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM dh_governance_category_datameta WHERE creator = 'migration:0200') THEN
        RAISE EXCEPTION '0200 水利标准分类已初始化，禁止再次清空';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_sequence
        WHERE seqrelid = 'dh_foundation_category_datameta_seq'::regclass AND seqincrement = 1
    ) THEN
        RAISE EXCEPTION '0200 类目编号序列不存在或步长不是一，禁止重建';
    END IF;
END $preflight$;

-- 在读取高水位之前取得序列事务锁，防止并发分配编号被重置。
ALTER SEQUENCE dh_foundation_category_datameta_seq INCREMENT BY 1;

DO $replace_categories$
DECLARE
    high_id bigint;
    root_id bigint;
    child_id bigint;
    root_item record;
    child_item record;
BEGIN
    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM dh_foundation_category_datameta_seq))
    INTO high_id FROM dh_governance_category_datameta;
    IF high_id > 9223372036854775807 - 66 THEN
        RAISE EXCEPTION '0200 类目编号空间不足，禁止重建';
    END IF;
    EXECUTE format('ALTER SEQUENCE dh_foundation_category_datameta_seq RESTART WITH %s', high_id + 1);

    -- 旧分类与水利分类没有可靠映射，解除关联后由使用者重新分类；包含逻辑删除记录以满足外键。
    UPDATE dh_governance_standard_doc
    SET category_id = NULL, updater = 'migration:0200', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;
    UPDATE dh_governance_standard_element
    SET category_id = NULL, revision = revision + 1, updater = 'migration:0200', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;
    UPDATE dh_governance_standard_code_set
    SET category_id = NULL, revision = revision + 1, updater = 'migration:0200', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;
    UPDATE dh_governance_standard_term
    SET category_id = NULL, updater = 'migration:0200', update_time = CURRENT_TIMESTAMP
    WHERE category_id IS NOT NULL;

    DELETE FROM dh_governance_category_datameta;

    -- 新编号均超过旧类目及序列高水位，历史版本中的旧编号不会误指向新的类目。
    FOR root_item IN SELECT * FROM (VALUES
        (0, '基础通用', '归集水利行业通用基础、数据治理和共享交换方面的标准文件。',
            ARRAY['术语符号与计量','分类编码与标识','数据元与指标','元数据与目录','交换与共享']),
        (1, '水文监测与预报', '归集水文站网、测验监测、资料整编和预报分析方面的标准文件。',
            ARRAY['水文站网与测站','水文测验与监测','水情编码与报送','水文资料整编','水文预报与分析']),
        (2, '水资源管理', '归集水资源调查、取用水监管、配置调度和节约用水方面的标准文件。',
            ARRAY['调查评价','取用水许可','计量监测','配置调度','节约用水','地下水管理']),
        (3, '水利工程', '归集水利工程勘测设计、建设施工、安全监测和运行维护方面的标准文件。',
            ARRAY['勘测设计','建设施工','质量验收','安全监测','运行调度','维修养护']),
        (4, '水旱灾害防御', '归集洪水、干旱、山洪灾害的监测预警、调度和应急处置方面的标准文件。',
            ARRAY['洪水监测预报','风险预警','防洪调度','山洪防治','抗旱管理','应急处置']),
        (5, '河湖与水生态', '归集河湖空间管理、水域监管、水生态保护和生态流量方面的标准文件。',
            ARRAY['河湖名录与岸线','河湖长制','水域监管','生态流量','水生态','水质评价']),
        (6, '农村水利', '归集灌溉排水、灌区建设、农村供水和农业节水方面的标准文件。',
            ARRAY['灌溉排水','灌区管理','农村供水','泵站运行','农业节水']),
        (7, '水土保持', '归集水土流失调查、方案管理、监测评价和治理工程方面的标准文件。',
            ARRAY['调查规划','方案与验收','监测评价','治理工程','遥感监管']),
        (8, '智慧水利', '归集水利信息化、数据资源、空间信息、物联网和网络安全方面的标准文件。',
            ARRAY['信息化建设','数据资源','地理信息与遥感','自动化与物联网','数据服务','网络安全']),
        (9, '水行政与综合管理', '归集水行政许可、执法监督、规划项目、统计档案和移民管理方面的标准文件。',
            ARRAY['行政许可','执法监督','规划项目','水利统计','档案管理','水库移民'])
    ) AS seed(sort, category_name, remark, children) ORDER BY sort
    LOOP
        root_id := nextval('dh_foundation_category_datameta_seq');
        INSERT INTO dh_governance_category_datameta
            (id, parent_id, category_name, category_code, sort, status, remark, creator, updater, deleted)
        VALUES (root_id, 0, root_item.category_name, '0,' || root_id, root_item.sort, 0, root_item.remark,
            'migration:0200', 'migration:0200', 0);

        FOR child_item IN SELECT name, ordinal - 1 AS sort
            FROM unnest(root_item.children) WITH ORDINALITY AS child(name, ordinal) ORDER BY ordinal
        LOOP
            child_id := nextval('dh_foundation_category_datameta_seq');
            INSERT INTO dh_governance_category_datameta
                (id, parent_id, category_name, category_code, sort, status, remark, creator, updater, deleted)
            VALUES (child_id, root_id, child_item.name, '0,' || root_id || ',' || child_id,
                child_item.sort, 0, '归集水利行业' || child_item.name || '相关标准文件，用于标准登记、检索和统一管理。',
                'migration:0200', 'migration:0200', 0);
        END LOOP;
    END LOOP;

    IF (SELECT count(*) FROM dh_governance_category_datameta) <> 66
        OR (SELECT count(*) FROM dh_governance_category_datameta WHERE parent_id = 0) <> 10 THEN
        RAISE EXCEPTION '0200 分类数量校验失败，整体回滚';
    END IF;
END $replace_categories$;

COMMIT;


-- Migration: 0201 按参考站点重建水利业务数据质量类目。
-- Purpose: 替换旧质量维度树为八个一级、八十七个二级类目；保留规则、执行内容和历史快照，旧分类关联改为未分类。
-- Depends on: 0200_governance_water-standard-categories.sql 已执行；现有质量类目、稽查规则及质量任务表已就绪。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库使用包含本迁移的全量基线。
-- Repeatable: 否；检测到本迁移创建的类目即拒绝再次清空，避免覆盖后续维护的数据。
-- Rollback: 失败整体回滚；提交后从执行前备份恢复类目、规则和任务的分类及审计字段，再恢复稽查维度原非空约束；保留序列高水位。
-- 不可逆操作：物理删除旧类目（包括停用及逻辑删除记录），解除旧类目关联；不删除规则或任务，不修改质量评分维度、策略、参数、所有权及不可变快照。
-- 执行前备份类目、稽查规则、质量任务三表及类目序列状态并暂停相关编辑；事务内锁定三表及序列，锁等待十秒或单语句执行两分钟超时即整体回滚。
-- 稽查规则仅为历史未分类记录放开数据库非空限制；新建和编辑仍由现有请求校验及服务校验强制选择有效类目。
-- 数据来源：用户授权参考站点的质量类目只读接口；完整树与截图可见节点核对一致，未导入远站账号、审计字段或业务主键。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE dh_governance_category_data_quality, dh_governance_audit_rule,
    dh_governance_quality_task IN SHARE ROW EXCLUSIVE MODE;

DO $preflight$
BEGIN
    IF EXISTS (SELECT 1 FROM dh_governance_category_data_quality WHERE creator = 'migration:0201') THEN
        RAISE EXCEPTION '0201 数据质量类目已初始化，禁止再次清空';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM pg_sequence
        WHERE seqrelid = 'dh_foundation_category_data_quality_seq'::regclass AND seqincrement = 1
    ) THEN
        RAISE EXCEPTION '0201 质量类目编号序列不存在或步长不是一，禁止重建';
    END IF;
END $preflight$;

-- 在读取序列高水位之前取得序列事务锁。
ALTER SEQUENCE dh_foundation_category_data_quality_seq INCREMENT BY 1;

DO $replace_quality_categories$
DECLARE
    high_id bigint;
    local_id bigint;
    parent_id bigint;
    category_path text;
    local_ids bigint[] := ARRAY[]::bigint[];
    item record;
BEGIN
    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM dh_foundation_category_data_quality_seq))
    INTO high_id FROM dh_governance_category_data_quality;
    IF high_id > 9223372036854775807 - 95 THEN
        RAISE EXCEPTION '0201 质量类目编号空间不足，禁止重建';
    END IF;
    EXECUTE format('ALTER SEQUENCE dh_foundation_category_data_quality_seq RESTART WITH %s', high_id + 1);

    -- 旧质量维度与新业务领域没有可靠映射，保留规则内容并将历史分类留待重新选择。
    ALTER TABLE dh_governance_audit_rule ALTER COLUMN dimension_id DROP NOT NULL;
    COMMENT ON COLUMN dh_governance_audit_rule.dimension_id IS '所属数据质量类目编号；分类替换后的历史规则允许未分类，新建和编辑由接口校验有效类目';
    UPDATE dh_governance_audit_rule
    SET dimension_id = NULL, updater = 'migration:0201', update_time = CURRENT_TIMESTAMP
    WHERE dimension_id IS NOT NULL;
    -- 任务分类还承载资产、加工及其他专用值，只清除精确匹配旧类目编码的引用。
    UPDATE dh_governance_quality_task
    SET task_category = NULL, updater = 'migration:0201', update_time = CURRENT_TIMESTAMP
    WHERE task_category NOT IN ('ASSET', 'ETL') AND task_category IN (
        SELECT category_code FROM dh_governance_category_data_quality
        WHERE category_code IS NOT NULL AND btrim(category_code) <> ''
    );

