    LOOP
        local_id := nextval('dh_foundation_category_data_quality_seq');
        local_ids[item.seed_key] := local_id;
        parent_id := CASE WHEN item.parent_key = 0 THEN 0 ELSE local_ids[item.parent_key] END;
        IF parent_id IS NULL THEN
            RAISE EXCEPTION '0201 质量类目父节点未初始化，整体回滚';
        END IF;
        category_path := CASE WHEN parent_id = 0 THEN '0,' || local_id
            ELSE '0,' || parent_id || ',' || local_id END;
        INSERT INTO dh_governance_category_data_quality
            (id, parent_id, category_name, category_code, sort, status, remark, creator, updater, deleted)
        VALUES (local_id, parent_id, item.category_name, category_path, item.sort, item.status, item.remark,
            'migration:0201', 'migration:0201', 0);
    END LOOP;

    IF (SELECT count(*) FROM dh_governance_category_data_quality) <> 95
        OR (SELECT count(*) FROM dh_governance_category_data_quality category WHERE category.parent_id = 0) <> 8 THEN
        RAISE EXCEPTION '0201 质量类目数量校验失败，整体回滚';
    END IF;
END $replace_quality_categories$;

COMMIT;


