(119,'refund_amount_7d','近7日成功退款金额','VARCHAR',64,NULL,NULL,0,0,8,NULL),
(119,'refund_cnt_7d','近7日成功退款笔数','VARCHAR',64,NULL,NULL,0,0,7,NULL),
(119,'day_refund_amount','当日成功退款金额','VARCHAR',64,NULL,NULL,0,0,6,NULL),
(119,'day_refund_cnt','当日成功退款笔数','INTEGER',NULL,NULL,NULL,0,0,5,NULL),
(119,'brand_name','品牌名称','VARCHAR',128,NULL,NULL,0,0,4,NULL),
(119,'category_id','商品类目ID','BIGINT',NULL,NULL,NULL,0,0,3,NULL),
(119,'product_name','商品名称','VARCHAR',128,NULL,NULL,0,0,2,NULL),
(119,'product_id','商品ID','BIGINT',NULL,NULL,NULL,0,0,1,NULL),
(122,'warning_publish_id','预警发布编码','VARCHAR2',32,NULL,NULL,1,1,2,'正式发布预警'),
(122,'ds','统计日期','DATE',NULL,NULL,NULL,1,1,1,'汇总数据所属业务日期')
) AS v(model_id, field_name, cn_name, data_type, data_length, data_scale, default_value, pk_flag, nullable_flag, sort, comment);

-- 每个逻辑表建立修订中的版本 1，字段快照与字段表一致，供详情与修改复用既有建模流程。
INSERT INTO dh_modeling_logic_model_version (model_id, version, status, fields, creator, updater)
SELECT m.id, 1, 'REVISING', coalesce((
        SELECT jsonb_agg(jsonb_strip_nulls(jsonb_build_object(
            'fieldUid', c.field_uid, 'fieldName', c.field_name, 'cnName', c.cn_name, 'dataType', c.data_type,
            'dataLength', c.data_length, 'dataScale', c.data_scale, 'defaultValue', c.default_value,
            'sort', c.sort, 'comment', c.comment, 'pkFlag', c.pk_flag = 1, 'nullableFlag', c.nullable_flag <> 0))
            ORDER BY c.sort, c.id)
        FROM dh_modeling_logic_model_column c WHERE c.model_id = m.id AND c.deleted = 0), '[]'::jsonb), '1', '1'
FROM dh_modeling_logic_model m;

-- 5. 字典：维度类型、业务类型、统计时效。
CREATE TEMP TABLE logic_dict_seed (dict_type text, dict_name text, sort integer, label text, value text, color_type text) ON COMMIT DROP;
INSERT INTO logic_dict_seed VALUES
    ('modeling_logic_obj_type', '逻辑表维度类型', 1, '普通对象', '1', 'primary'),
    ('modeling_logic_obj_type', '逻辑表维度类型', 2, '层级对象', '2', 'primary'),
    ('modeling_logic_business_type', '逻辑表业务类型', 1, '业务事件', '1', 'primary'),
    ('modeling_logic_business_type', '逻辑表业务类型', 2, '业务流程', '2', 'primary'),
    ('modeling_logic_data_timeliness', '逻辑表统计时效', 1, '天（T+1）', '1', 'success'),
    ('modeling_logic_data_timeliness', '逻辑表统计时效', 2, '小时（T+h）', '2', 'success'),
    ('modeling_logic_data_timeliness', '逻辑表统计时效', 3, '分钟（T+h）', '3', 'success');
SELECT setval('system_dict_type_seq', greatest((SELECT last_value FROM system_dict_type_seq), (SELECT max(id) FROM system_dict_type)));
SELECT setval('system_dict_data_seq', greatest((SELECT last_value FROM system_dict_data_seq), (SELECT max(id) FROM system_dict_data)));
INSERT INTO system_dict_type (id, name, type, status, creator, updater)
SELECT nextval('system_dict_type_seq'), s.dict_name, s.dict_type, 0, 'migration:0208', 'migration:0208'
FROM (SELECT DISTINCT dict_type, dict_name FROM logic_dict_seed) s
WHERE NOT EXISTS (SELECT 1 FROM system_dict_type t WHERE t.type = s.dict_type AND t.deleted = 0)
ORDER BY s.dict_type;
INSERT INTO system_dict_data (id, sort, label, value, dict_type, status, color_type, creator, updater)
SELECT nextval('system_dict_data_seq'), s.sort, s.label, s.value, s.dict_type, 0, s.color_type, 'migration:0208', 'migration:0208'
FROM logic_dict_seed s
WHERE NOT EXISTS (SELECT 1 FROM system_dict_data d WHERE d.dict_type = s.dict_type AND d.value = s.value AND d.deleted = 0)
ORDER BY s.dict_type, s.sort;

-- 6. 菜单：逻辑模型下新增五个逻辑表页面，原“创建模型”页面隐藏（保留其权限供详情、ER 图等辅助页面使用）。
DO $menus$
DECLARE
    page record;
    action record;
    page_id bigint;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id = 6216 AND deleted = 0) THEN
        RAISE EXCEPTION '缺少逻辑模型目录菜单 6216';
    END IF;
    -- 重复执行：先移除本迁移此前创建的菜单及角色授权。
    DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM system_menu WHERE creator = 'migration:0208');
    DELETE FROM system_menu WHERE creator = 'migration:0208';
    UPDATE system_menu SET visible = false, updater = 'migration:0208', update_time = CURRENT_TIMESTAMP WHERE id = 6722;
    PERFORM setval('system_menu_id_seq', greatest((SELECT last_value FROM system_menu_id_seq), (SELECT max(id) FROM system_menu)));
    FOR page IN SELECT * FROM (VALUES
            (1, '贴源逻辑表', 'source-table', 'modeling/logictable/source/index', 'ModelingLogicSourceTable'),
            (2, '维度逻辑表', 'dimension-table', 'modeling/logictable/dimension/index', 'ModelingLogicDimensionTable'),
            (3, '事实逻辑表', 'fact-table', 'modeling/logictable/fact/index', 'ModelingLogicFactTable'),
            (4, '汇总逻辑表', 'summary-table', 'modeling/logictable/summary/index', 'ModelingLogicSummaryTable'),
            (5, 'ADS应用表', 'application-table', 'modeling/logictable/application/index', 'ModelingLogicApplicationTable')
        ) AS p(position, label, path, component, component_name)
    LOOP
        INSERT INTO system_menu (name, permission, type, sort, parent_id, path, icon, component, component_name, status,
            visible, keep_alive, always_show, creator, updater, deleted)
        VALUES (page.label, 'modeling:logic-table:query', 2, page.position, 6216, page.path, '', page.component,
            page.component_name, 0, true, true, true, 'migration:0208', 'migration:0208', 0)
        RETURNING id INTO page_id;
        FOR action IN SELECT * FROM (VALUES
                (1, '逻辑表查询', 'query'), (2, '逻辑表新增', 'create'), (3, '逻辑表修改', 'update'), (4, '逻辑表删除', 'delete')
            ) AS a(position, label, code)
        LOOP
            INSERT INTO system_menu (name, permission, type, sort, parent_id, path, status, visible, keep_alive,
                always_show, creator, updater, deleted)
            VALUES (action.label, 'modeling:logic-table:' || action.code, 3, action.position, page_id, '', 0, true, true,
                true, 'migration:0208', 'migration:0208', 0);
        END LOOP;
    END LOOP;
    -- 已授权“创建模型”的角色同步获得五个逻辑表页面及按钮。
    INSERT INTO system_role_menu (id, role_id, menu_id, creator, updater, deleted, tenant_id)
    SELECT nextval('system_role_menu_seq'), r.role_id, m.id, 'migration:0208', 'migration:0208', 0, r.tenant_id
    FROM (SELECT DISTINCT role_id, tenant_id FROM system_role_menu WHERE menu_id = 6722 AND deleted = 0) r
    CROSS JOIN system_menu m
    WHERE m.creator = 'migration:0208' AND m.deleted = 0
      AND NOT EXISTS (SELECT 1 FROM system_role_menu x WHERE x.role_id = r.role_id AND x.menu_id = m.id AND x.deleted = 0);
    PERFORM setval('system_menu_seq', greatest((SELECT last_value FROM system_menu_seq), (SELECT max(id) FROM system_menu)));
END $menus$;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM dh_modeling_logic_model) <> 51
        OR (SELECT count(*) FROM dh_modeling_logic_model_column) <> 443
        OR (SELECT count(*) FROM dh_modeling_logic_model_version) <> 51
        OR (SELECT count(*) FROM dh_modeling_source_system) <> 6 THEN
        RAISE EXCEPTION '逻辑表初始化数量不匹配';
    END IF;
    IF (SELECT count(*) FROM system_menu WHERE creator = 'migration:0208' AND type = 2 AND deleted = 0) <> 5 THEN
        RAISE EXCEPTION '逻辑表菜单数量不匹配';
    END IF;
END $verify$;
COMMIT;

-- Migration: 0209 连接图标统一为本地 PNG 并补齐占位图标。
-- Purpose: 为 18 种仍使用通用占位图标的连接类型补齐对应的 PNG 图标，并把内置 SVG 连接图标统一更换为 PNG 格式。
-- Depends on: 0208_modeling_logic-table-qdata.sql 已执行；管理端已发布 public/connection-icons 下的 PNG 静态资源。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；仅按产品编码更新空图标或仍指向内置 /connection-icons/ 目录的图标路径，保留类型编号、连接引用和用户上传的自定义图标。
-- Rollback: 单个事务失败时整笔回滚；提交后如需恢复原图标，按执行前快照恢复对应 icon_path，其他连接配置、目录编号和引用不变。
-- 事务边界：只更新目录图标列，短事务；不连接、不修改任何外部数据源。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

-- 内置图标按产品编码归位，供连接器列表、连接向导和连接详情共用同一份本地 PNG 资源。
UPDATE dh_dataforge_database_type AS t
SET icon_path = s.icon_path,
    updater = 'migration:0209',
    update_time = CURRENT_TIMESTAMP
FROM (VALUES
    ('SQLSERVER2000', '/connection-icons/sqlserver2000.png'),
    ('DB2',           '/connection-icons/db2.png'),
    ('SQLITE3',       '/connection-icons/sqlite3.png'),
    ('SYBASE',        '/connection-icons/sybase.png'),
    ('TIDB',          '/connection-icons/tidb.png'),
    ('MONGODB',       '/connection-icons/mongodb.png'),
    ('ELASTICSEARCH', '/connection-icons/elasticsearch.png'),
    ('TDENGINE',      '/connection-icons/tdengine.png'),
    ('INFLUXDB3',     '/connection-icons/influxdb3.png'),
    ('FTP',           '/connection-icons/ftp.png'),
    ('HDFS',          '/connection-icons/hdfs.png'),
    ('GBASE8C',       '/connection-icons/gbase8c.png'),
    ('GAUSSDB',       '/connection-icons/gaussdb.png'),
    ('PHOENIX',       '/connection-icons/phoenix.png'),
    ('SAPHANA',       '/connection-icons/saphana.png'),
    ('PRESTO',        '/connection-icons/presto.png'),
    ('ODPS',          '/connection-icons/odps.png'),
    ('OSS',           '/connection-icons/oss.png'),
    ('MINIO',         '/connection-icons/minio.png'),
    ('REDIS',         '/connection-icons/redis.png'),
    ('KAFKA',         '/connection-icons/kafka.png'),
    ('RABBITMQ',      '/connection-icons/rabbitmq.png'),
    ('ROCKETMQ',      '/connection-icons/rocketmq.png'),
    ('NEO4J',         '/connection-icons/neo4j.png'),
    ('MILVUS',        '/connection-icons/milvus.png'),
    ('INFLUXDB2',     '/connection-icons/influxdb2.png'),
    ('SFTP',          '/connection-icons/sftp.png')
) AS s(product_code, icon_path)
WHERE t.deleted = 0
  AND CASE regexp_replace(upper(t.type_code), '[-_[:space:]]', '', 'g')
      WHEN 'SQLITE' THEN 'SQLITE3'
      WHEN 'INFLUXDB' THEN 'INFLUXDB3'
      WHEN 'ES' THEN 'ELASTICSEARCH'
      ELSE regexp_replace(upper(t.type_code), '[-_[:space:]]', '', 'g')
      END = s.product_code
  AND (
      coalesce(btrim(t.icon_path), '') = ''
      OR t.icon_path LIKE '/connection-icons/%'
  )
  AND t.icon_path IS DISTINCT FROM s.icon_path;

COMMIT;

-- Migration: 0210 补齐逻辑模型下五个逻辑表菜单图标。
-- Purpose: 为贴源、维度、事实、汇总及 ADS 应用表菜单补齐图标，保留已配置的自定义图标。
-- Depends on: 0208_modeling_logic-table-qdata.sql 已完整执行；按全局顺序在 0209_dataforge_connection-icons-png.sql 之后执行。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；仅修改空白图标，重复执行不改写图标及审计时间。
-- Rollback: 本事务失败时全部回滚；提交后如需撤销，按执行前快照恢复这五个菜单的 icon、updater 和 update_time。
-- 事务边界：只更新菜单展示图标，不新增菜单、不变更权限或角色授权；短事务并限制锁等待。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

DO $icons$
DECLARE
    page record;
    menu_matches integer;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id = 6216 AND deleted = 0) THEN
        RAISE EXCEPTION '缺少逻辑模型目录菜单 6216，请先确认 0208 迁移已完整执行';
    END IF;
    FOR page IN SELECT * FROM (VALUES
            ('source-table', 'modeling/logictable/source/index', 'lucide:database'),
            ('dimension-table', 'modeling/logictable/dimension/index', 'lucide:boxes'),
            ('fact-table', 'modeling/logictable/fact/index', 'lucide:table-properties'),
            ('summary-table', 'modeling/logictable/summary/index', 'lucide:chart-column'),
            ('application-table', 'modeling/logictable/application/index', 'lucide:layout-dashboard')
        ) AS p(path, component, icon)
    LOOP
        SELECT count(*) INTO menu_matches FROM system_menu
        WHERE parent_id = 6216 AND type = 2 AND deleted = 0
          AND path = page.path AND component = page.component;
        IF menu_matches <> 1 THEN
            RAISE EXCEPTION '逻辑模型子菜单 % 匹配到 % 条，预期恰好一条；请先确认 0208 迁移已完整执行',
                page.path, menu_matches;
        END IF;
        UPDATE system_menu AS menu
        SET icon = page.icon, updater = 'migration:0210', update_time = CURRENT_TIMESTAMP
        WHERE menu.parent_id = 6216 AND menu.type = 2 AND menu.deleted = 0
          AND menu.path = page.path AND menu.component = page.component
          AND nullif(btrim(menu.icon), '') IS NULL;
    END LOOP;
END $icons$;
COMMIT;


-- 新库最终状态来源：0211_modeling_materialized-log-snapshot.sql
-- Migration: 0211 固化模型发布日志的部署关联和展示快照。
-- Purpose: 每次写入发布日志时保存部署尝试编号、模型名称、目标数据源和发布说明，防止重新发布篡改历史展示。
-- Depends on: 0210_modeling_logic-table-menu-icons.sql 已执行；前置状态为已完成冻结部署与单租户升级，存在部署尝试表及物化日志表。
-- Target: 已有 PostgreSQL 平台库的 datahub-center schema；新库由包含本增量的全量基线安装。
-- Repeatable: 是；所有列使用 IF NOT EXISTS，重复执行只重申字段注释，不回填或改写日志。
-- Rollback: 事务失败自动回滚；提交后撤销需先停用依赖新列的应用并备份日志，再删除本迁移新增列，删除会丢失发布快照。
-- 事务边界：加法式短事务，限制锁等待；历史日志保持空值，不通过时间或当前物化状态猜测原始关联。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';

DO $preflight$
BEGIN
    IF to_regclass('dh_modeling_model_materialized_log') IS NULL
       OR to_regclass('dh_modeling_deployment_attempt') IS NULL THEN
        RAISE EXCEPTION '发布日志快照迁移缺少冻结部署前置表，请先完成平台基线升级';
    END IF;
END $preflight$;

ALTER TABLE dh_modeling_model_materialized_log
    ADD COLUMN IF NOT EXISTS attempt_id bigint,
    ADD COLUMN IF NOT EXISTS model_name varchar(255),
    ADD COLUMN IF NOT EXISTS model_alias varchar(255),
    ADD COLUMN IF NOT EXISTS datasource_id bigint,
    ADD COLUMN IF NOT EXISTS datasource_name varchar(255),
    ADD COLUMN IF NOT EXISTS datasource_type varchar(64),
    ADD COLUMN IF NOT EXISTS description varchar(500);

COMMENT ON COLUMN dh_modeling_model_materialized_log.attempt_id IS '本条日志对应的持久部署尝试编号；历史未知不回填';
COMMENT ON COLUMN dh_modeling_model_materialized_log.model_name IS '发布时模型英文名称快照';
COMMENT ON COLUMN dh_modeling_model_materialized_log.model_alias IS '发布时模型中文名称快照';
COMMENT ON COLUMN dh_modeling_model_materialized_log.datasource_id IS '发布时目标数据源编号快照';
COMMENT ON COLUMN dh_modeling_model_materialized_log.datasource_name IS '发布时目标数据源名称快照';
COMMENT ON COLUMN dh_modeling_model_materialized_log.datasource_type IS '发布时目标数据库产品编码快照';
COMMENT ON COLUMN dh_modeling_model_materialized_log.description IS '本次发布说明快照';

COMMIT;

-- Migration: 0212 逻辑模型详情、两步编辑与汇总自动字段契约。
-- Purpose: 补齐字段类别、维度、分类分级、代码表、汇总粒度及指标来源口径快照，约束同类实体时效唯一，复用统一模型和版本字段存储。
-- Depends on: 0211_modeling_materialized-log-snapshot.sql；0208_modeling_logic-table-qdata.sql 已建立五类逻辑模型。
-- Target: 已有 PostgreSQL 平台库；新库使用同步后的 datahub-center.sql。
-- Preconditions: 有效 DIMENSION/DETAIL 记录不存在相同类型、业务实体与统计时效；如有重复，索引创建将失败并整体回滚，不自动删改业务数据。
-- Repeatable: yes；使用 ADD COLUMN IF NOT EXISTS、CREATE UNIQUE INDEX IF NOT EXISTS 和可重放注释。
-- Rollback: 事务失败自动回滚；成功后可删除本迁移新增列，但会不可逆丢弃新字段元数据，执行前应备份。
-- Risk: 加法式 DDL 获取短时表锁，lock_timeout=10s；仅为可唯一解析的存量汇总定义补充元数据，保留字段身份和历史发布快照。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_modeling_logic_model ADD COLUMN IF NOT EXISTS grain_entity_ids varchar(1024);
COMMENT ON COLUMN dh_modeling_logic_model.grain_entity_ids IS '汇总统计粒度业务实体编号列表，逗号分隔';

ALTER TABLE dh_modeling_logic_model_column
    ADD COLUMN IF NOT EXISTS field_category varchar(32),
    ADD COLUMN IF NOT EXISTS dimension_id bigint,
    ADD COLUMN IF NOT EXISTS dimension_name varchar(255),
    ADD COLUMN IF NOT EXISTS data_classification_id bigint,
    ADD COLUMN IF NOT EXISTS data_classification_name varchar(255),
    ADD COLUMN IF NOT EXISTS data_grade varchar(64),
    ADD COLUMN IF NOT EXISTS code_table_id bigint,
    ADD COLUMN IF NOT EXISTS code_table_name varchar(255),
    ADD COLUMN IF NOT EXISTS unique_flag smallint NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS indicator_id bigint,
    ADD COLUMN IF NOT EXISTS atomic_indicator_name varchar(255),
    ADD COLUMN IF NOT EXISTS business_condition varchar(2000),
    ADD COLUMN IF NOT EXISTS statistics_period varchar(32),
    ADD COLUMN IF NOT EXISTS source_model_name varchar(255);
COMMENT ON COLUMN dh_modeling_logic_model_column.field_category IS '字段类别：PRIMARY_KEY/ATTRIBUTE/DIMENSION/MEASURE/TIME/GRAIN/INDICATOR/NORMAL';
COMMENT ON COLUMN dh_modeling_logic_model_column.dimension_id IS '关联维度业务实体编号';
COMMENT ON COLUMN dh_modeling_logic_model_column.dimension_name IS '关联维度名称';
COMMENT ON COLUMN dh_modeling_logic_model_column.data_classification_id IS '治理数据分类编号';
COMMENT ON COLUMN dh_modeling_logic_model_column.data_classification_name IS '治理数据分类名称';
COMMENT ON COLUMN dh_modeling_logic_model_column.data_grade IS '治理数据分级编码';
COMMENT ON COLUMN dh_modeling_logic_model_column.code_table_id IS '标准代码表编号';
COMMENT ON COLUMN dh_modeling_logic_model_column.code_table_name IS '标准代码表名称';
COMMENT ON COLUMN dh_modeling_logic_model_column.unique_flag IS '是否唯一：1 是，0 否';
COMMENT ON COLUMN dh_modeling_logic_model_column.indicator_id IS '汇总自动字段来源派生指标编号';
COMMENT ON COLUMN dh_modeling_logic_model_column.atomic_indicator_name IS '原子指标名称快照';
COMMENT ON COLUMN dh_modeling_logic_model_column.business_condition IS '指标业务限定口径快照';
COMMENT ON COLUMN dh_modeling_logic_model_column.statistics_period IS '指标统计周期快照';
COMMENT ON COLUMN dh_modeling_logic_model_column.source_model_name IS '指标绑定的发布版本来源模型名称快照';

-- 旧页面只保存粒度名称。仅同板块/主题域且唯一匹配已启用普通对象时回填，歧义或停用对象留空供人工重新选择。
WITH requested AS (
    SELECT id, data_domain_id, subject_domain_id, string_to_array(statistics_str, ',') AS names
    FROM dh_modeling_logic_model
    WHERE table_type = 'SUMMARY' AND deleted = 0 AND grain_entity_ids IS NULL
        AND statistics_str IS NOT NULL AND btrim(statistics_str) <> ''
), resolved AS (
    SELECT r.id, wanted.position, min(e.id) AS entity_id
    FROM requested r CROSS JOIN LATERAL unnest(r.names) WITH ORDINALITY wanted(name, position)
    JOIN dh_modeling_business_entity e ON e.data_domain_id = r.data_domain_id AND e.subject_domain_id = r.subject_domain_id
        AND e.name = btrim(wanted.name) AND e.entity_type = 'OBJECT' AND e.entity_subtype = 'NORMAL'
        AND e.status = 0 AND e.deleted = 0
    GROUP BY r.id, wanted.position HAVING count(*) = 1
), complete AS (
    SELECT resolved.id, string_agg(entity_id::text, ',' ORDER BY position) AS ids
    FROM resolved JOIN requested ON requested.id = resolved.id
    GROUP BY resolved.id, requested.names HAVING count(*) = cardinality(requested.names)
)
UPDATE dh_modeling_logic_model m SET grain_entity_ids = complete.ids FROM complete WHERE m.id = complete.id;

UPDATE dh_modeling_logic_model_column c SET field_category = 'TIME'
FROM dh_modeling_logic_model m
WHERE c.model_id = m.id AND m.table_type = 'SUMMARY' AND c.field_name = 'ds'
    AND c.deleted = 0 AND m.deleted = 0 AND c.field_category IS NULL;
UPDATE dh_modeling_logic_model_column c SET field_category = 'GRAIN', dimension_id = e.id, dimension_name = e.name
FROM dh_modeling_logic_model m JOIN dh_modeling_business_entity e
    ON e.id::text = ANY(string_to_array(m.grain_entity_ids, ','))
WHERE c.model_id = m.id AND m.table_type = 'SUMMARY' AND lower(c.field_name) = lower(e.code) || '_id'
    AND c.deleted = 0 AND m.deleted = 0 AND c.field_category IS NULL;

-- 仅当前修订版本补充同一字段的元数据；不重写字段 UUID、不触碰发布版本。
UPDATE dh_modeling_logic_model_version v SET fields = (
    SELECT jsonb_agg(item.value || coalesce(jsonb_strip_nulls(jsonb_build_object(
        'fieldCategory', c.field_category, 'dimensionId', c.dimension_id, 'dimensionName', c.dimension_name)), '{}'::jsonb)
        ORDER BY item.position)
    FROM jsonb_array_elements(v.fields) WITH ORDINALITY item(value, position)
    LEFT JOIN dh_modeling_logic_model_column c ON c.model_id = v.model_id AND c.deleted = 0
        AND c.field_uid = item.value->>'fieldUid'
)
FROM dh_modeling_logic_model m
WHERE v.model_id = m.id AND m.table_type = 'SUMMARY' AND v.status = 'REVISING'
    AND v.version = m.latest_version AND v.deleted = 0 AND m.deleted = 0 AND jsonb_array_length(v.fields) > 0;

CREATE UNIQUE INDEX IF NOT EXISTS uq_modeling_logic_entity_time_live
    ON dh_modeling_logic_model (table_type, entity_id, data_timeliness)
    WHERE deleted = 0 AND status <> 'DISCARDED' AND table_type IN ('DIMENSION', 'DETAIL')
        AND entity_id IS NOT NULL AND data_timeliness IS NOT NULL;
COMMENT ON INDEX uq_modeling_logic_entity_time_live IS '同类逻辑表的业务实体与统计时效单平台唯一';
COMMIT;

-- Migration: 0213 原子指标及业务限定的实体绑定和来源归属保护。
-- Purpose: 新增实体编号，保护同板块、主题、实体、时效的启用维度/事实表发布来源，保留既有版本和引用锁规则。
-- Depends on: 0212_modeling_logic-table-definition.sql；现有指标、限定、业务实体、逻辑模型及发布版本表和引用触发器已建立。
-- Target: 已有 PostgreSQL 平台库；新库使用同步后的 datahub-center.sql。
-- Repeatable: 是；加列、索引及触发器可重放；仅对来源归属可确定的旧定义补充实体编号，不重写业务口径或发布版本。
-- Rollback: 事务失败整体回滚；成功后回退应用可保留新增列。删除列及触发器前须备份新定义，避免丢失实体引用和并发保护。
-- Risk: 加法式结构变更及有限回填获取表锁；共享引用事务锁等待受 lock_timeout 约束，不清空数据、不新增角色授权。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

ALTER TABLE dh_modeling_indicator_model ADD COLUMN IF NOT EXISTS entity_id bigint;
ALTER TABLE dh_modeling_business_condition ADD COLUMN IF NOT EXISTS entity_id bigint;
COMMENT ON COLUMN dh_modeling_indicator_model.entity_id IS '绑定业务实体编号；派生指标继承原子指标实体';
COMMENT ON COLUMN dh_modeling_business_condition.entity_id IS '绑定的业务对象或业务活动编号';
CREATE INDEX IF NOT EXISTS idx_modeling_indicator_entity ON dh_modeling_indicator_model(entity_id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_modeling_condition_entity ON dh_modeling_business_condition(entity_id) WHERE deleted=0;
COMMENT ON INDEX idx_modeling_indicator_entity IS '有效指标的业务实体引用';
COMMENT ON INDEX idx_modeling_condition_entity IS '有效业务限定的业务实体引用';

-- 只从同归属、同时效且仍启用的已知来源补充旧实体；不能确定的旧定义保留为空，重新编辑时明确选择。
UPDATE dh_modeling_indicator_model i SET entity_id=m.entity_id
FROM dh_modeling_logic_model m JOIN dh_modeling_business_entity e ON e.id=m.entity_id AND e.deleted=0 AND e.status=0
WHERE i.entity_id IS NULL AND i.deleted=0 AND i.indicator_type='ATOMIC' AND i.source_model_id=m.id
    -- 被派生引用的原子定义已有不可变保护，不为回填绕过或停用该保护。
    AND NOT EXISTS(SELECT 1 FROM dh_modeling_indicator_model d WHERE d.base_indicator_id=i.id AND d.deleted=0)
    AND m.deleted=0 AND m.enabled=1 AND m.table_type IN ('DIMENSION','DETAIL')
    AND i.data_domain_id=m.data_domain_id AND i.subject_domain_id=m.subject_domain_id AND i.data_freshness=m.data_timeliness
    AND EXISTS(SELECT 1 FROM dh_modeling_logic_model_version v WHERE v.id=i.source_version_id AND v.model_id=m.id
        AND v.deleted=0 AND v.status='PUBLISHED' AND v.model_snapshot->>'entityId'=e.id::text
        AND v.model_snapshot->>'dataDomainId'=e.data_domain_id::text AND v.model_snapshot->>'subjectDomainId'=e.subject_domain_id::text
        AND v.model_snapshot->>'dataTimeliness'=m.data_timeliness);
UPDATE dh_modeling_indicator_model i SET entity_id=b.entity_id FROM dh_modeling_indicator_model b
WHERE i.entity_id IS NULL AND i.deleted=0 AND i.indicator_type='DERIVED' AND i.base_indicator_id=b.id
    AND b.deleted=0 AND b.indicator_type='ATOMIC' AND b.entity_id IS NOT NULL;
UPDATE dh_modeling_business_condition c SET entity_id=m.entity_id
FROM dh_modeling_logic_model m JOIN dh_modeling_business_entity e ON e.id=m.entity_id AND e.deleted=0 AND e.status=0
WHERE c.entity_id IS NULL AND c.deleted=0 AND c.source_model_id=m.id
    AND m.deleted=0 AND m.enabled=1 AND m.table_type IN ('DIMENSION','DETAIL')
    AND c.data_domain_id=m.data_domain_id AND c.subject_domain_id=m.subject_domain_id AND c.data_freshness=m.data_timeliness
    AND EXISTS(SELECT 1 FROM dh_modeling_logic_model_version v WHERE v.id=c.source_version_id AND v.model_id=m.id
        AND v.deleted=0 AND v.status='PUBLISHED' AND v.model_snapshot->>'entityId'=e.id::text
        AND v.model_snapshot->>'dataDomainId'=e.data_domain_id::text AND v.model_snapshot->>'subjectDomainId'=e.subject_domain_id::text
        AND v.model_snapshot->>'dataTimeliness'=m.data_timeliness);

CREATE OR REPLACE FUNCTION modeling_metric_entity_guard() RETURNS trigger
LANGUAGE plpgsql SET search_path="datahub-center",pg_catalog AS $guard$
DECLARE data jsonb; referenced boolean; entity bigint;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('modeling-ownership-global',0));
    IF TG_TABLE_NAME IN ('dh_modeling_indicator_model','dh_modeling_business_condition') THEN
        IF TG_OP='DELETE' THEN RETURN OLD; END IF;
        IF NEW.deleted<>0 THEN RETURN NEW; END IF;
        data:=to_jsonb(NEW); entity:=(data->>'entity_id')::bigint;
        IF TG_TABLE_NAME='dh_modeling_indicator_model' AND data->>'indicator_type'='DERIVED' THEN
            IF NOT EXISTS(SELECT 1 FROM dh_modeling_indicator_model b WHERE b.id=(data->>'base_indicator_id')::bigint
                AND b.deleted=0 AND b.indicator_type='ATOMIC' AND b.entity_id IS NOT DISTINCT FROM entity) THEN
                RAISE EXCEPTION '派生指标实体必须继承原子指标' USING ERRCODE='23514';
            END IF;
            RETURN NEW;
        END IF;
        -- 旧未知实体记录允许停用或删除，不得借旧形态启用或新建定义。
        IF entity IS NULL AND TG_OP='UPDATE' AND data->>'status'='DRAFT' AND to_jsonb(OLD)->>'entity_id' IS NULL THEN RETURN NEW; END IF;
        IF NOT EXISTS(SELECT 1 FROM dh_modeling_business_entity e
            JOIN dh_modeling_logic_model m ON m.id=(data->>'source_model_id')::bigint AND m.entity_id=e.id
            JOIN dh_modeling_logic_model_version v ON v.id=(data->>'source_version_id')::bigint AND v.model_id=m.id
            WHERE e.id=entity AND e.deleted=0 AND e.status=0
                AND e.data_domain_id=(data->>'data_domain_id')::bigint AND e.subject_domain_id=(data->>'subject_domain_id')::bigint
                AND m.deleted=0 AND m.enabled=1 AND m.status<>'DISCARDED' AND m.table_type IN ('DIMENSION','DETAIL')
                AND m.data_domain_id=e.data_domain_id AND m.subject_domain_id=e.subject_domain_id
                AND m.data_timeliness=data->>'data_freshness' AND m.data_timeliness IN ('1','2','3')
                AND v.deleted=0 AND v.status='PUBLISHED'
                AND v.model_snapshot->>'modelId'=m.id::text AND v.model_snapshot->>'entityId'=e.id::text
                AND v.model_snapshot->>'dataDomainId'=e.data_domain_id::text
                AND v.model_snapshot->>'subjectDomainId'=e.subject_domain_id::text
                AND v.model_snapshot->>'dataTimeliness'=m.data_timeliness
                AND v.model_snapshot->>'tableType' IN ('DIMENSION','DETAIL')) THEN
            RAISE EXCEPTION '指标或限定必须绑定同归属实体及时效的有效发布来源' USING ERRCODE='23514';
        END IF;
        RETURN NEW;
    END IF;
    IF TG_TABLE_NAME='dh_modeling_business_entity' THEN
        SELECT EXISTS(SELECT 1 FROM dh_modeling_indicator_model WHERE entity_id=OLD.id AND deleted=0)
            OR EXISTS(SELECT 1 FROM dh_modeling_business_condition WHERE entity_id=OLD.id AND deleted=0) INTO referenced;
        IF referenced AND (TG_OP='DELETE' OR NEW.deleted<>0 OR NEW.status<>0
            OR NEW.data_domain_id IS DISTINCT FROM OLD.data_domain_id OR NEW.subject_domain_id IS DISTINCT FROM OLD.subject_domain_id
            OR NEW.entity_type IS DISTINCT FROM OLD.entity_type OR NEW.entity_subtype IS DISTINCT FROM OLD.entity_subtype) THEN
            RAISE EXCEPTION '业务实体仍被指标或限定引用，不能删除、停用或变更归属类型' USING ERRCODE='23514';
        END IF;
    ELSIF TG_TABLE_NAME='dh_modeling_logic_model' THEN
        SELECT EXISTS(SELECT 1 FROM dh_modeling_indicator_model WHERE source_model_id=OLD.id AND deleted=0)
            OR EXISTS(SELECT 1 FROM dh_modeling_business_condition WHERE source_model_id=OLD.id AND deleted=0) INTO referenced;
        IF referenced AND (TG_OP='DELETE' OR NEW.deleted<>0 OR NEW.enabled<>1 OR NEW.status='DISCARDED'
            OR NEW.table_type IS DISTINCT FROM OLD.table_type OR NEW.entity_id IS DISTINCT FROM OLD.entity_id
            OR NEW.data_domain_id IS DISTINCT FROM OLD.data_domain_id OR NEW.subject_domain_id IS DISTINCT FROM OLD.subject_domain_id
            OR NEW.data_timeliness IS DISTINCT FROM OLD.data_timeliness) THEN
            RAISE EXCEPTION '来源仍被指标或限定引用，不能停用或变更实体和时效归属' USING ERRCODE='23514';
        END IF;
    ELSE
        SELECT EXISTS(SELECT 1 FROM dh_modeling_indicator_model WHERE source_version_id=OLD.id AND deleted=0)
            OR EXISTS(SELECT 1 FROM dh_modeling_business_condition WHERE source_version_id=OLD.id AND deleted=0) INTO referenced;
        IF referenced AND (TG_OP='DELETE' OR (to_jsonb(NEW)-ARRAY['updater','update_time']) IS DISTINCT FROM
            (to_jsonb(OLD)-ARRAY['updater','update_time'])) THEN
            RAISE EXCEPTION '指标或限定绑定的发布版本不可变更' USING ERRCODE='23514';
        END IF;
    END IF;
    IF TG_OP='DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END $guard$;
COMMENT ON FUNCTION modeling_metric_entity_guard() IS '以共享事务锁保护指标及限定的实体、时效和发布来源';
DO $install$
DECLARE table_name text;
BEGIN
    FOREACH table_name IN ARRAY ARRAY['dh_modeling_indicator_model','dh_modeling_business_condition',
        'dh_modeling_business_entity','dh_modeling_logic_model','dh_modeling_logic_model_version'] LOOP
        EXECUTE format('DROP TRIGGER IF EXISTS modeling_metric_entity_guard ON %I',table_name);
        EXECUTE format('CREATE TRIGGER modeling_metric_entity_guard BEFORE %s ON %I FOR EACH ROW EXECUTE FUNCTION modeling_metric_entity_guard()',
            CASE WHEN table_name IN ('dh_modeling_indicator_model','dh_modeling_business_condition') THEN 'INSERT OR UPDATE OR DELETE'
                ELSE 'UPDATE OR DELETE' END,table_name);
    END LOOP;
END $install$;
COMMIT;

-- Migration: 0214 指标单位字典及七类单位目录。
-- Purpose: 将已核实的单位叶子名称作为字典值，备注保存分组，复用系统字典能力。
-- Depends on: 0213_modeling_metric-entity-binding.sql；既有 system_dict_type、system_dict_data 及其序列。
-- Target: 已有 PostgreSQL 平台库；新库基线已包含本迁移。
-- Repeatable: 是；仅补充缺失的有效字典类型和键值，不覆盖管理员已维护的标签、备注或状态。
-- Rollback: 无破坏性操作；如需撤回，先确认指标单位使用情况，再删除本迁移创建且未被修改的字典记录。

BEGIN;
SET LOCAL search_path TO "datahub-center", public;
CREATE TEMP TABLE metric_unit_seed (sort integer, label text, category text) ON COMMIT DROP;
INSERT INTO metric_unit_seed VALUES
    (1, '其他', '其他'),
