    MAX(`OBJTP`) AS `OBJTP`,
    MAX(`OBJCD`) AS `OBJCD`,
    MAX(`OBJNM`) AS `OBJNM`,
    MAX(`RVCD`) AS `RVCD`,
    MAX(`RVNM`) AS `RVNM`,
    MAX(`RSCD`) AS `RSCD`,
    MAX(`RSNM`) AS `RSNM`,
    MAX(`SECCD`) AS `SECCD`,
    MAX(`SECNM`) AS `SECNM`,
    `STCD`,
    MAX(`STNM`) AS `STNM`,
    -- 使用2000年承载月日，兼容2月29日
    CAST(CONCAT(''2000-'', `MONTH_DAY`) AS DATE) AS `STATDT`,
    -- 多年平均统计周期
    ''MYAVG'' AS `STTPRD`,
    -- 历史数据覆盖的最早开始时间
    MIN(`BGNTM`) AS `BGNTM`,
    -- 历史数据覆盖的最晚结束时间
    MAX(`ENDTM`) AS `ENDTM`,
    -- 不同年份同一月日的平均水位
    CAST(AVG(`AVGZ`) AS DECIMAL(10, 3)) AS `AVGZ`,
    -- 不同年份同一月日的历史最高水位
    CAST(MAX(`MAXZ`) AS DECIMAL(10, 3)) AS `MAXZ`,
    -- 不同年份同一月日的历史最低水位
    CAST(MIN(`MINZ`) AS DECIMAL(10, 3)) AS `MINZ`,
    -- 不同年份同一月日的平均上涨速率
    CAST(AVG(`ZRR`) AS DECIMAL(10, 3)) AS `ZRR`
FROM (
    SELECT
        `ID`,
        `OBJTP`,
        `OBJCD`,
        `OBJNM`,
        `RVCD`,
        `RVNM`,
        `RSCD`,
        `RSNM`,
        `SECCD`,
        `SECNM`,
        -- 源表STCD为CHAR类型，去除可能存在的尾部空格
        TRIM(`STCD`) AS `STCD`,
        `STNM`,
        `BGNTM`,
        `ENDTM`,
        `AVGZ`,
        `MAXZ`,
        `MINZ`,
        `ZRR`,
        -- 提取统计日期的月日
        DATE_FORMAT(
            CAST(`STATDT` AS TIMESTAMP),
            ''MM-dd''
        ) AS `MONTH_DAY`
    FROM DORIS_DWS_RH_HIST_ST_Z_DAY_S_SOURCE
) SOURCE_DATA
GROUP BY
    `STCD`,
    `MONTH_DAY`;
