-- 河道水情_DWD到DWS_多年平均水位
-- 多年平均口径汇总_每日
-- =====================================================
-- =====================================================
-- 1. Flink 批处理基础配置
-- =====================================================
-- 使用批处理模式
SET ''execution.runtime-mode'' = ''batch'';
-- 等待批处理任务执行完成后再退出
SET ''table.dml-sync'' = ''true'';
-- 设置默认并行度
SET ''parallelism.default'' = ''1'';
-- =====================================================
-- 2. 创建 Doris 日水位统计源表
-- =====================================================
DROP TABLE IF EXISTS DORIS_DWS_RH_HIST_ST_Z_DAY_S_SOURCE;
CREATE TABLE DORIS_DWS_RH_HIST_ST_Z_DAY_S_SOURCE (
    `ID` BIGINT,
    `OBJTP` STRING,
    `OBJCD` STRING,
    `OBJNM` STRING,
    `RVCD` STRING,
    `RVNM` STRING,
    `RSCD` STRING,
    `RSNM` STRING,
    `SECCD` STRING,
    `SECNM` STRING,
    `STCD` STRING,
    `STNM` STRING,
    `STATDT` DATE,
    `STTPRD` STRING,
    `BGNTM` TIMESTAMP(0),
    `ENDTM` TIMESTAMP(0),
    `AVGZ` DECIMAL(15, 6),
    `MAXZ` DECIMAL(10, 3),
    `MINZ` DECIMAL(10, 3),
    `ZRR` DECIMAL(10, 3)
) WITH (
    ''connector'' = ''doris'',
    ''fenodes'' = ''[INTERNAL_HOST]'',
    ''table.identifier'' = ''DWS.DWS_RH_HIST_ST_Z_DAY_S'',
[连接身份与敏感参数已脱敏]
[连接身份与敏感参数已脱敏]
);
-- =====================================================
-- 3. 创建 Doris 多年平均水位目标表
-- =====================================================
DROP TABLE IF EXISTS DORIS_DWS_RH_STAT_ST_Z_MYAVG_S;
CREATE TABLE DORIS_DWS_RH_STAT_ST_Z_MYAVG_S (
    `ID` BIGINT,
    `OBJTP` STRING,
    `OBJCD` STRING,
    `OBJNM` STRING,
    `RVCD` STRING,
    `RVNM` STRING,
    `RSCD` STRING,
    `RSNM` STRING,
    `SECCD` STRING,
    `SECNM` STRING,
    `STCD` STRING,
    `STNM` STRING,
    `STATDT` DATE,
    `STTPRD` STRING,
    `BGNTM` TIMESTAMP(0),
    `ENDTM` TIMESTAMP(0),
    `AVGZ` DECIMAL(10, 3),
    `MAXZ` DECIMAL(10, 3),
    `MINZ` DECIMAL(10, 3),
    `ZRR` DECIMAL(10, 3)
) WITH (
    ''connector'' = ''doris'',
    ''fenodes'' = ''[INTERNAL_HOST]'',
    ''table.identifier'' = ''DWS.DWS_RH_STAT_ST_Z_MYAVG_S'',
[连接身份与敏感参数已脱敏]
[连接身份与敏感参数已脱敏]
    ''sink.label-prefix'' = ''doris_batch_st_z_myavg_s_dws_20260804_01'',
    ''sink.enable-2pc'' = ''false'',
    ''sink.properties.format'' = ''json'',
    ''sink.properties.read_json_by_line'' = ''true'',
    -- Doris 2.1 不支持压缩 JSON
    ''sink.properties.compress_type'' = ''''
);
-- =====================================================
-- 4. 计算多年平均水位和历史极值
-- 汇总维度：测站编码 + 月日
-- =====================================================
INSERT INTO DORIS_DWS_RH_STAT_ST_Z_MYAVG_S
SELECT
    -- 使用当前分组中最小的原始记录ID作为汇总记录ID
    MIN(`ID`) AS `ID`,
    -- 同一测站的基础属性原则上保持一致
    MAX(`OBJTP`) AS `OBJTP`,
    MAX(`OBJCD`) AS `OBJCD`,
    MAX(`OBJNM`) AS `OBJNM`,
    MAX(`RVCD`) AS `RVCD`,
    MAX(`RVNM`) AS `RVNM`,
    MAX(`RSCD`) AS `RSCD`,
    MAX(`RSNM`) AS `RSNM`,
    MAX(`SECCD`) AS `SECCD`,
    MAX(`SECNM`) AS `SECNM`,
    `STCD`,
    MAX(`STNM`) AS `STNM`,
    -- 使用2000年承载月日，兼容2月29日
    CAST(CONCAT(''2000-'', `MONTH_DAY`) AS DATE) AS `STATDT`,
    -- 多年平均统计周期
    ''MYAVG'' AS `STTPRD`,
    -- 历史数据覆盖的最早开始时间
    MIN(`BGNTM`) AS `BGNTM`,
    -- 历史数据覆盖的最晚结束时间
    MAX(`ENDTM`) AS `ENDTM`,
    -- 不同年份同一月日的平均水位
    CAST(AVG(`AVGZ`) AS DECIMAL(10, 3)) AS `AVGZ`,
    -- 不同年份同一月日的历史最高水位
    CAST(MAX(`MAXZ`) AS DECIMAL(10, 3)) AS `MAXZ`,
    -- 不同年份同一月日的历史最低水位
    CAST(MIN(`MINZ`) AS DECIMAL(10, 3)) AS `MINZ`,
    -- 不同年份同一月日的平均上涨速率
    CAST(AVG(`ZRR`) AS DECIMAL(10, 3)) AS `ZRR`
FROM (
    SELECT
        `ID`,
        `OBJTP`,
        `OBJCD`,
        `OBJNM`,
        `RVCD`,
        `RVNM`,
        `RSCD`,
        `RSNM`,
        `SECCD`,
        `SECNM`,
        -- 源表STCD为CHAR类型，去除可能存在的尾部空格
        TRIM(`STCD`) AS `STCD`,
        `STNM`,
        `BGNTM`,
        `ENDTM`,
        `AVGZ`,
        `MAXZ`,
        `MINZ`,
        `ZRR`,
        -- 提取统计日期的月日
        DATE_FORMAT(
            CAST(`STATDT` AS TIMESTAMP),
            ''MM-dd''
        ) AS `MONTH_DAY`
    FROM DORIS_DWS_RH_HIST_ST_Z_DAY_S_SOURCE
) SOURCE_DATA
GROUP BY
    `STCD`,
    `MONTH_DAY`;
