-- Repeatable: 是；仅填充从未发生本地编辑或日志且持有首次待填充标记的数据集，完成后移除标记，重放不会覆盖本地修改。
-- Rollback: 单事务失败完整回滚；提交后业务行可能已被编辑或引用，不能自动删除回滚，必须保留备份及本地编辑日志。
-- 风险：来源接口未提供跨页事务快照；已对全部真实字段升序分页，逐页核验总数和页长，并重读首尾页摘要；十六个源端失败表及一个文件只保留明确的不完整状态。
-- 来源：353014 条去重下载行，来源资产66和47同一底层数据集各建独立本地副本三行，共353017条；未把来源行内ID当成本地主键。
-- 无损编码：单元格字典全部为原始字符串或空值，数值用 Decimal/整数转十进制字符串；模式索引和出现顺序还原每一次重复，未抽样、截断或计算近似数值。
-- 事务边界：所有业务行、覆盖状态和待填充标记在一个事务内提交；不访问源站或任何外部数据库，不生成历史编辑日志。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '600s';
LOCK TABLE dh_asset_import_dataset, dh_asset_import_row, dh_asset_import_row_log IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMP TABLE qdata_row_seed_eligible (asset_id bigint PRIMARY KEY) ON COMMIT DROP;
CREATE TEMP TABLE qdata_encoded_seed (payload jsonb NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE qdata_seed_column (column_index integer PRIMARY KEY,column_name text NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE qdata_seed_dictionary (column_index integer,value_index integer,value_json jsonb,
    PRIMARY KEY(column_index,value_index)) ON COMMIT DROP;
CREATE TEMP TABLE qdata_seed_pattern_cell (pattern_id integer,column_index integer,value_index integer,
    PRIMARY KEY(pattern_id,column_index)) ON COMMIT DROP;
CREATE TEMP TABLE qdata_seed_pattern (pattern_id integer PRIMARY KEY,row_json jsonb NOT NULL) ON COMMIT DROP;
CREATE TEMP TABLE qdata_seed_ordering (ordinal integer PRIMARY KEY,pattern_id integer NOT NULL) ON COMMIT DROP;

DO $sequence$
DECLARE
    current_value bigint;
    current_called boolean;
    next_value numeric;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_sequence WHERE seqrelid='dh_asset_import_row_seq'::regclass AND seqincrement=1 AND NOT seqcycle) THEN
        RAISE EXCEPTION '业务行序列必须使用步长一且禁止循环';
    END IF;
    SELECT last_value,is_called INTO current_value,current_called FROM dh_asset_import_row_seq;
    SELECT greatest(coalesce(max(id),0)::numeric+1,current_value::numeric+CASE WHEN current_called THEN 1 ELSE 0 END)
      INTO next_value FROM dh_asset_import_row;
    IF next_value > 9223372036854422790 THEN RAISE EXCEPTION '业务行序列剩余空间不足'; END IF;
    EXECUTE format('ALTER SEQUENCE dh_asset_import_row_seq RESTART WITH %s', next_value);
END;
$sequence$;

