INSERT INTO qdata_seed_column(column_index,column_name)
 SELECT (position-1)::integer,value FROM qdata_encoded_seed,jsonb_array_elements_text(payload->'columns') WITH ORDINALITY AS item(value,position);
INSERT INTO qdata_seed_dictionary(column_index,value_index,value_json)
 SELECT (column_position-1)::integer,(value_position-1)::integer,value_json
 FROM qdata_encoded_seed,jsonb_array_elements(payload->'dictionaries') WITH ORDINALITY AS column_values(dictionary,column_position),
      jsonb_array_elements(dictionary) WITH ORDINALITY AS cell_values(value_json,value_position);
INSERT INTO qdata_seed_pattern_cell(pattern_id,column_index,value_index)
 SELECT (pattern_position-1)::integer,(column_position-1)::integer,(value_index::text)::integer
 FROM qdata_encoded_seed,jsonb_array_elements(payload->'patterns') WITH ORDINALITY AS patterns(pattern,pattern_position),
      jsonb_array_elements(pattern) WITH ORDINALITY AS cells(value_index,column_position);
