$qdata_rows_1$::jsonb);
-- 分阶段展开小型字典，避免将大型源对象带入分组排序或重复解压。
INSERT INTO qdata_seed_column(column_index,column_name)
 SELECT (position-1)::integer,value FROM qdata_encoded_seed,jsonb_array_elements_text(payload->'columns') WITH ORDINALITY AS item(value,position);
INSERT INTO qdata_seed_dictionary(column_index,value_index,value_json)
 SELECT (column_position-1)::integer,(value_position-1)::integer,value_json
 FROM qdata_encoded_seed,jsonb_array_elements(payload->'dictionaries') WITH ORDINALITY AS column_values(dictionary,column_position),
      jsonb_array_elements(dictionary) WITH ORDINALITY AS cell_values(value_json,value_position);
INSERT INTO qdata_seed_pattern_cell(pattern_id,column_index,value_index)
 SELECT (pattern_position-1)::integer,(column_position-1)::integer,(value_index::text)::integer
 FROM qdata_encoded_seed,jsonb_array_elements(payload->'patterns') WITH ORDINALITY AS patterns(pattern,pattern_position),
      jsonb_array_elements(pattern) WITH ORDINALITY AS cells(value_index,column_position);
INSERT INTO qdata_seed_pattern(pattern_id,row_json)
 SELECT cells.pattern_id,jsonb_object_agg(columns.column_name,dictionary.value_json)
 FROM qdata_seed_pattern_cell cells JOIN qdata_seed_column columns USING(column_index)
 JOIN qdata_seed_dictionary dictionary USING(column_index,value_index) GROUP BY cells.pattern_id;
INSERT INTO qdata_seed_ordering(ordinal,pattern_id)
 SELECT position::integer,(value::text)::integer FROM qdata_encoded_seed,
      jsonb_array_elements(payload->'ordering') WITH ORDINALITY AS items(value,position);
INSERT INTO dh_asset_import_row(asset_id,ordinal,row_json,revision,creator,updater)
SELECT eligible.asset_id,ordering.ordinal,patterns.row_json,0,'migration:0222','migration:0222'
 FROM qdata_row_seed_eligible eligible CROSS JOIN qdata_seed_ordering ordering JOIN qdata_seed_pattern patterns USING(pattern_id);
DO $verify_1$
BEGIN
 IF EXISTS(SELECT 1 FROM qdata_row_seed_eligible eligible
    WHERE (SELECT count(*) FROM dh_asset_import_row row_data WHERE row_data.asset_id=eligible.asset_id) <> 52608) THEN
    RAISE EXCEPTION '来源资产 1 的完整业务行还原数量不一致';
 END IF;
END;
$verify_1$;
UPDATE dh_asset_import_dataset dataset SET imported_row_count=52608,complete=true,
    file_info_json=dataset.file_info_json-'rowSeedPending',updater='migration:0222',update_time=CURRENT_TIMESTAMP
 FROM qdata_row_seed_eligible eligible WHERE dataset.asset_id=eligible.asset_id;

-- 失败源端与文件不产生伪造空表；清除首次填充标志后仍明确保持不完整覆盖。
UPDATE dh_asset_import_dataset dataset SET imported_row_count=0,complete=false,
    file_info_json=dataset.file_info_json-'rowSeedPending',updater='migration:0222',update_time=CURRENT_TIMESTAMP
 WHERE dataset.creator='migration:0221' AND dataset.revision=0 AND dataset.deleted=0
   AND dataset.file_info_json->>'rowSeedPending'='true'
   AND dataset.file_info_json->>'sourcePreviewStatus' IN ('SOURCE_UNAVAILABLE','FILE_METADATA_ONLY')
   AND NOT EXISTS(SELECT 1 FROM dh_asset_import_row row_data WHERE row_data.asset_id=dataset.asset_id)
   AND NOT EXISTS(SELECT 1 FROM dh_asset_import_row_log row_log WHERE row_log.asset_id=dataset.asset_id);

COMMIT;

-- Migration: 0223_asset_registration-sources.sql
-- Purpose: 保存资产注册业务配置及真实 API/文件来源事实，不伪造物理表和技术交付能力。
-- Depends on: 0221_asset_qdata-map-datasets.sql；资产目录及技术对象关联基础结构已存在。
-- Target: 已有 PostgreSQL 数据库；新库由完整基线包含。
-- Repeatable: 是；新增列、表和索引均带存在性保护。
-- Rollback: 回滚应用后可删除新表及 registration_config_json 列，会丢失新增注册配置与来源记录；原资产目录保留。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
ALTER TABLE dh_asset_data_asset ADD COLUMN IF NOT EXISTS registration_config_json text;
COMMENT ON COLUMN dh_asset_data_asset.registration_config_json IS '资产注册业务配置白名单；不替代物理表元数据及授权依据';

CREATE TABLE IF NOT EXISTS dh_asset_registration_source (
    asset_id bigint PRIMARY KEY REFERENCES dh_asset_data_asset(id),
    source_kind integer NOT NULL CHECK (source_kind IN (2, 3)),
    source_id bigint NOT NULL CHECK (source_id > 0),
    source_version varchar(128),
    source_name varchar(512) NOT NULL,
    file_type varchar(128),
    source_path varchar(2048),
    storage_size bigint,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0
);
COMMENT ON TABLE dh_asset_registration_source IS '资产注册的真实非表来源事实；不等同于可用交付合同';
COMMENT ON COLUMN dh_asset_registration_source.asset_id IS '资产编号，一项资产对应一个注册来源';
COMMENT ON COLUMN dh_asset_registration_source.source_kind IS '真实来源类型：2已发布 API，3当前有效文件元数据';
COMMENT ON COLUMN dh_asset_registration_source.source_id IS '提供方真实对象编号';
COMMENT ON COLUMN dh_asset_registration_source.source_version IS '注册时提供方发布编号或文件业务修订号';
COMMENT ON COLUMN dh_asset_registration_source.source_name IS '注册时提供方真实对象名称';
COMMENT ON COLUMN dh_asset_registration_source.file_type IS '文件提供方声明的文件类型；API 为空';
COMMENT ON COLUMN dh_asset_registration_source.source_path IS '提供方文件路径或 API 相对路径，不存连接凭据';
COMMENT ON COLUMN dh_asset_registration_source.storage_size IS '提供方文件大小，单位字节';
COMMENT ON COLUMN dh_asset_registration_source.creator IS '创建人';
COMMENT ON COLUMN dh_asset_registration_source.create_time IS '创建时间';
COMMENT ON COLUMN dh_asset_registration_source.updater IS '更新人';
COMMENT ON COLUMN dh_asset_registration_source.update_time IS '更新时间';
COMMENT ON COLUMN dh_asset_registration_source.deleted IS '逻辑删除：0未删除，1已删除';
CREATE INDEX IF NOT EXISTS idx_asset_registration_source_object ON dh_asset_registration_source(source_kind, source_id) WHERE deleted=0;
COMMIT;


-- Migration: 0224 资产质量任务内评测定义持久化。
-- Purpose: 持久保存用户完整规则配置，允许与治理质量引擎同步失败后按原任务编号核对和重试。
-- Depends on: 0223_asset_registration-sources.sql；dh_asset_quality_task 已包含质量引擎关联和远端错误列。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的完整基线。
-- Repeatable: 是；仅新增可空列，不改写已有旧规则或任务配置。
-- Rollback: 事务失败完整回滚；提交后删除此列会丢失任务内配置，回滚前必须备份，不能自动破坏性回滚。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
ALTER TABLE dh_asset_quality_task ADD COLUMN IF NOT EXISTS evaluation_json text;
COMMENT ON COLUMN dh_asset_quality_task.evaluation_json IS '任务内完整评测配置；旧规则任务为空，远端同步失败不丢弃此定义';
ALTER TABLE dh_asset_quality_task ADD COLUMN IF NOT EXISTS pending_run_key varchar(64);
COMMENT ON COLUMN dh_asset_quality_task.pending_run_key IS '尚未收到回执的稳定运行键，复用治理幂等执行接口核对同一次运行，成功取得实例编号后清空';
COMMIT;

-- Migration: 0225 资产服务审批来源工单
-- Purpose: 隔离保存来源审批快照和本地审核意见，不建立真实申请、批准凭证或数据交付。
-- Depends on: 0224_asset_quality-inline-evaluations.sql；已有单租户资产、申请与市场审计表。
-- Target: 已有 PostgreSQL 数据库；新库由同步后的全量基线创建。
-- Repeatable: yes；对象使用存在性保护，已存在的来源数据和本地意见不被覆盖。
-- Rollback: 确认无须保留来源意见与审计后可删除本表及序列；删除会不可逆丢失来源快照和本地审核意见，真实授权表不受影响。
-- 事务边界：本迁移全部在单一事务内执行；只新增独立表及索引，不改写历史申请。

BEGIN;

CREATE SEQUENCE IF NOT EXISTS dh_market_approval_work_order_seq;

CREATE TABLE IF NOT EXISTS dh_market_approval_work_order (
    id bigint PRIMARY KEY DEFAULT nextval('dh_market_approval_work_order_seq'),
    source_system varchar(32) NOT NULL,
    source_record_id varchar(128) NOT NULL,
    mart_source_id varchar(128),
    mart_name varchar(256) NOT NULL,
    applicant_key varchar(128) NOT NULL,
    applicant_name varchar(128) NOT NULL,
    applicant_dept_name varchar(256),
    apply_type smallint NOT NULL,
    start_time timestamp,
    end_time timestamp,
    apply_time timestamp NOT NULL,
    apply_reason text,
    source_status varchar(16) NOT NULL,
    source_approval_reason text,
    source_approval_time timestamp,
    detail_snapshot jsonb NOT NULL DEFAULT '{}'::jsonb,
    local_status varchar(16),
    local_approval_reason varchar(500),
    local_check_user_id bigint,
    local_check_time timestamp,
    revision integer NOT NULL DEFAULT 1,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT uk_market_approval_source UNIQUE (source_system, source_record_id),
    CONSTRAINT ck_market_approval_source_system CHECK (source_system = 'QDATA'),
    CONSTRAINT ck_market_approval_source_id CHECK (length(trim(source_record_id)) > 0),
    CONSTRAINT ck_market_approval_applicant CHECK (length(trim(applicant_key)) > 0),
    CONSTRAINT ck_market_approval_apply_type CHECK (apply_type IN (1, 2)),
    CONSTRAINT ck_market_approval_source_status CHECK (source_status IN ('1', '2', '3', '4', '5', '6')),
    CONSTRAINT ck_market_approval_local_status CHECK (local_status IS NULL OR local_status IN ('3', '4')),
    CONSTRAINT ck_market_approval_local_actor CHECK (
        (local_status IS NULL AND local_check_user_id IS NULL AND local_check_time IS NULL)
        OR (local_status IS NOT NULL AND local_check_user_id IS NOT NULL
            AND local_check_user_id > 0 AND local_check_time IS NOT NULL)),
    CONSTRAINT ck_market_approval_snapshot CHECK (jsonb_typeof(detail_snapshot) = 'object'),
    CONSTRAINT ck_market_approval_revision CHECK (revision > 0),
    CONSTRAINT ck_market_approval_deleted CHECK (deleted IN (0, 1))
);

ALTER SEQUENCE dh_market_approval_work_order_seq OWNED BY dh_market_approval_work_order.id;

COMMENT ON TABLE dh_market_approval_work_order IS '来源审批工单隔离快照；本地意见不代表正式数据授权';
COMMENT ON COLUMN dh_market_approval_work_order.id IS '本地隔离工单主键，仅用于审计关联';
COMMENT ON COLUMN dh_market_approval_work_order.source_system IS '来源系统，目前为QDATA';
COMMENT ON COLUMN dh_market_approval_work_order.source_record_id IS '来源工单编号字符串，不是本地申请编号';
COMMENT ON COLUMN dh_market_approval_work_order.mart_source_id IS '来源集市资源编号字符串，不作为本地资产编号';
COMMENT ON COLUMN dh_market_approval_work_order.mart_name IS '来源集市资产名称快照';
COMMENT ON COLUMN dh_market_approval_work_order.applicant_key IS '来源人员标识字符串，不映射本地登录身份';
COMMENT ON COLUMN dh_market_approval_work_order.applicant_name IS '来源申请人名称快照';
COMMENT ON COLUMN dh_market_approval_work_order.applicant_dept_name IS '来源申请机构名称快照';
COMMENT ON COLUMN dh_market_approval_work_order.apply_type IS '来源申请周期：1长期有效、2自定义';
COMMENT ON COLUMN dh_market_approval_work_order.start_time IS '来源申请生效时间；长期有效时可空';
COMMENT ON COLUMN dh_market_approval_work_order.end_time IS '来源申请截止时间；长期有效时可空';
COMMENT ON COLUMN dh_market_approval_work_order.apply_time IS '来源申请时间快照';
COMMENT ON COLUMN dh_market_approval_work_order.apply_reason IS '来源申请理由快照';
COMMENT ON COLUMN dh_market_approval_work_order.source_status IS '不可变来源状态：1未授权、2待授权、3已通过、4已驳回、5已下架、6已过期';
COMMENT ON COLUMN dh_market_approval_work_order.source_approval_reason IS '来源审批意见快照';
COMMENT ON COLUMN dh_market_approval_work_order.source_approval_time IS '来源审批时间快照';
COMMENT ON COLUMN dh_market_approval_work_order.detail_snapshot IS '脱敏的资源、字段、预览和接口文档展示快照；不得包含远端凭证';
COMMENT ON COLUMN dh_market_approval_work_order.local_status IS '本地保存的工单意见结果：3通过、4驳回；不生成正式数据授权';
COMMENT ON COLUMN dh_market_approval_work_order.local_approval_reason IS '本地审批意见';
COMMENT ON COLUMN dh_market_approval_work_order.local_check_user_id IS '可信当前登录的本地审批人编号，区别于来源人员标识';
COMMENT ON COLUMN dh_market_approval_work_order.local_check_time IS '本地意见保存时间';
COMMENT ON COLUMN dh_market_approval_work_order.revision IS '本地工单意见并发版本号';
COMMENT ON COLUMN dh_market_approval_work_order.creator IS '创建者审计标识';
COMMENT ON COLUMN dh_market_approval_work_order.create_time IS '本地导入创建时间';
COMMENT ON COLUMN dh_market_approval_work_order.updater IS '更新者审计标识';
COMMENT ON COLUMN dh_market_approval_work_order.update_time IS '本地更新时间';
COMMENT ON COLUMN dh_market_approval_work_order.deleted IS '逻辑删除标记：0有效、1已删除';

CREATE INDEX IF NOT EXISTS idx_market_approval_status_time
    ON dh_market_approval_work_order ((COALESCE(local_status, source_status)), apply_time DESC, id DESC)
    WHERE deleted = 0;
CREATE INDEX IF NOT EXISTS idx_market_approval_applicant_time
    ON dh_market_approval_work_order (applicant_key, apply_time DESC, id DESC)
    WHERE deleted = 0;

COMMIT;


-- Migration: 0226 qData 敏感清单分类定义迁入。
-- Purpose: 迁入实测的三十六个目录和五十六个分类，复用治理现有四级分级，不创建未经取得配置的脱敏执行规则。
-- Depends on: 当前单租户治理基线，已存在 category_data/safety_category/safety_level 三表及两个序列，L1 至 L4 各有唯一启用定义；不依赖并发任务的 0225。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的 datahub-center.sql。
-- Repeatable: 是；按来源目录编码和分类缩写核验身份，已有定义与人工编辑保持原样，来源身份冲突或已删除时失败。
-- Rollback: 单事务失败完整回滚；提交后须核验清单及治理引用再逐条删除迁入定义，禁止自动删除；两序列事务性前移不复用旧编号。
-- 来源：2026-10-22 经授权只读取得的分类树与分类详情；仅迁入定义文字、分级和状态，不迁入账号、联系方式、连接配置或规则执行参数。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '60s';
SELECT pg_advisory_xact_lock(1500, 32);
LOCK TABLE dh_governance_category_data, dh_governance_safety_category, dh_governance_safety_level IN SHARE ROW EXCLUSIVE MODE;
