-- Migration: 0245 为数据安全增加敏感清单入口。
-- Purpose: 复用资产敏感清单页面及权限，仅向已有该页面查询权限的角色和套餐增加入口。
-- Depends on: 0244_governance_access-audit-menu-icon.sql；0227_asset_sensitive-list.sql 已建立资产敏感清单菜单。
-- Target: 已有 PostgreSQL 数据库；新库使用同步后的 datahub-center.sql。
-- Repeatable: 是；仅首次创建入口时迁移对应授权，重放不会恢复后来撤销的授权。
-- Rollback: 按执行前备份恢复菜单、角色菜单授权和租户套餐；原资产入口及业务数据不受影响。
-- 事务边界：单事务；身份冲突或套餐菜单格式错误时回滚；执行后重新登录以刷新权限缓存。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

DO $migration$
DECLARE
    asset_page_id bigint;
    safety_id bigint;
    new_page_id bigint;
    high_id bigint;
    matches integer;
BEGIN
    SELECT count(*), min(id) INTO matches, asset_page_id FROM system_menu
    WHERE deleted = 0 AND type = 2 AND permission = 'asset:sensitive-list:query'
      AND trim(both '/' from coalesce(component, '')) = 'asset/sensitive/index';
    IF matches <> 1 THEN RAISE EXCEPTION '0245 未找到唯一的资产敏感清单菜单'; END IF;

    SELECT count(*), min(safety.id) INTO matches, safety_id FROM system_menu safety
    JOIN system_menu governance ON governance.id = safety.parent_id
    WHERE safety.deleted = 0 AND safety.type = 1 AND safety.path = 'safety'
      AND governance.deleted = 0 AND governance.type = 1 AND governance.parent_id = 0
      AND trim(both '/' from coalesce(governance.path, '')) = 'govern';
    IF matches <> 1 THEN RAISE EXCEPTION '0245 未找到唯一的数据安全菜单'; END IF;

    SELECT count(*), min(id) INTO matches, new_page_id FROM system_menu
    WHERE trim(both '/' from coalesce(component, '')) = 'governance/security/sensitive/index';
    IF matches > 1 OR EXISTS (SELECT 1 FROM system_menu WHERE id = new_page_id
       AND (deleted IS DISTINCT FROM 0 OR type IS DISTINCT FROM 2 OR parent_id IS DISTINCT FROM safety_id
            OR permission IS DISTINCT FROM '' OR path IS DISTINCT FROM 'sensitive-list'
            OR component_name IS DISTINCT FROM 'GovernanceSensitiveList'))
       OR EXISTS (SELECT 1 FROM system_menu WHERE deleted = 0 AND parent_id = safety_id
                  AND path = 'sensitive-list' AND id IS DISTINCT FROM new_page_id)
       OR EXISTS (SELECT 1 FROM system_menu WHERE deleted = 0
                  AND component_name = 'GovernanceSensitiveList' AND id IS DISTINCT FROM new_page_id)
    THEN RAISE EXCEPTION '0245 数据安全敏感清单菜单身份冲突'; END IF;

    IF matches = 0 THEN
        IF EXISTS (SELECT 1 FROM system_tenant_package WHERE deleted = 0
                   AND jsonb_typeof(menu_ids::jsonb) <> 'array') THEN
            RAISE EXCEPTION '0245 租户套餐菜单必须为数组';
        END IF;
        SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_menu_seq),
                        (SELECT last_value FROM system_menu_id_seq)) + 1 INTO new_page_id FROM system_menu;
        INSERT INTO system_menu (id, name, permission, type, sort, parent_id, path, icon,
                                 component, component_name, creator, updater)
        VALUES (new_page_id, '敏感清单', '', 2, 7, safety_id, 'sensitive-list', 'lucide:shield-check',
                'governance/security/sensitive/index', 'GovernanceSensitiveList', 'migration:0245', 'migration:0245');

        SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_role_menu_seq)) INTO high_id
        FROM system_role_menu;
        INSERT INTO system_role_menu (id, role_id, menu_id, tenant_id, creator, updater, deleted)
        SELECT high_id + row_number() OVER (ORDER BY source.role_id, source.tenant_id),
               source.role_id, new_page_id, source.tenant_id, 'migration:0245', 'migration:0245', 0
        FROM (SELECT DISTINCT role_id, tenant_id FROM system_role_menu
              WHERE deleted = 0 AND menu_id = asset_page_id) source;

        UPDATE system_tenant_package package
        SET menu_ids = (package.menu_ids::jsonb || jsonb_build_array(new_page_id))::text,
            updater = 'migration:0245', update_time = CURRENT_TIMESTAMP
        WHERE package.deleted = 0 AND EXISTS (
            SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) item(value)
            WHERE item.value = asset_page_id::text);

        SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_menu_seq),
                        (SELECT last_value FROM system_menu_id_seq)) INTO high_id FROM system_menu;
        PERFORM setval('system_menu_seq', high_id, true);
        PERFORM setval('system_menu_id_seq', high_id, true);
        SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_role_menu_seq)) INTO high_id
        FROM system_role_menu;
        PERFORM setval('system_role_menu_seq', high_id, true);
    END IF;
END $migration$;

COMMIT;

-- Migration: 0246 数据推送类目及基础管理入口。
-- Purpose: 新增独立推送类目树和任务归属，在基础管理下增加类目维护菜单；历史任务保持未分类。
-- Depends on: 0245_governance_sensitive-list-entry.sql；0216_dataforge_project-categories.sql 创建的基础管理类目目录及现有推送任务表。
-- Target: 已有 PostgreSQL 平台库；新库使用同步后的 datahub-center.sql。
-- Repeatable: 是；结构和菜单按身份检查并复用，不恢复后续删除的业务类目或重置任务归属。
-- Rollback: 执行前备份菜单及授权；回滚须先恢复原版代码并移除本次菜单授权与菜单，备份新增类目及任务归属后才能删除新增列、表和序列。
-- 事务边界：单事务；创建索引和新增列会短时持锁，锁等待超过十秒失败。序列在失败回滚时可能前移。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_push_category_seq;
COMMENT ON SEQUENCE dh_dataforge_push_category_seq IS '数据推送类目编号序列';

CREATE TABLE IF NOT EXISTS dh_dataforge_push_category (
    id bigint NOT NULL DEFAULT nextval('dh_dataforge_push_category_seq'::regclass),
    parent_id bigint NOT NULL DEFAULT 0,
    name varchar(128) NOT NULL,
    sort integer NOT NULL DEFAULT 0,
    status smallint NOT NULL DEFAULT 0,
    description varchar(500),
    creator varchar(64) DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    PRIMARY KEY (id),
    CONSTRAINT ck_dataforge_push_category_status CHECK (status IN (0, 1)),
    CONSTRAINT ck_dataforge_push_category_parent CHECK (parent_id >= 0)
);
COMMENT ON TABLE dh_dataforge_push_category IS '数据推送任务类目';
COMMENT ON COLUMN dh_dataforge_push_category.id IS '类目编号';
COMMENT ON COLUMN dh_dataforge_push_category.parent_id IS '父类目编号，0 表示根类目';
COMMENT ON COLUMN dh_dataforge_push_category.name IS '类目名称';
COMMENT ON COLUMN dh_dataforge_push_category.sort IS '同级排序';
COMMENT ON COLUMN dh_dataforge_push_category.status IS '状态：0 启用，1 停用';
COMMENT ON COLUMN dh_dataforge_push_category.description IS '类目描述';
COMMENT ON COLUMN dh_dataforge_push_category.creator IS '创建人';
COMMENT ON COLUMN dh_dataforge_push_category.create_time IS '创建时间';
COMMENT ON COLUMN dh_dataforge_push_category.updater IS '更新人';
COMMENT ON COLUMN dh_dataforge_push_category.update_time IS '更新时间';
COMMENT ON COLUMN dh_dataforge_push_category.deleted IS '逻辑删除标识：0 未删除，1 已删除';

CREATE UNIQUE INDEX IF NOT EXISTS uk_dataforge_push_category_parent_name
    ON dh_dataforge_push_category (parent_id, name) WHERE deleted = 0;
COMMENT ON INDEX uk_dataforge_push_category_parent_name IS '有效推送类目同级名称唯一';

ALTER TABLE dh_dataforge_push_task ADD COLUMN IF NOT EXISTS category_id bigint;
COMMENT ON COLUMN dh_dataforge_push_task.category_id IS '推送类目编号，空表示未分类';
CREATE INDEX IF NOT EXISTS idx_dataforge_push_task_category
    ON dh_dataforge_push_task (category_id, id) WHERE deleted = 0;
COMMENT ON INDEX idx_dataforge_push_task_category IS '按类目查询有效推送任务';

-- 菜单与角色关联需要互斥分配编号，不改变其他角色的授权范围。
LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE
    basic_id bigint;
    category_id bigint;
    page_id bigint;
    action_id bigint;
    high_id bigint;
    matches integer;
    grant_ids bigint[];
    action record;
BEGIN
    SELECT count(*), min(id) INTO matches, basic_id FROM system_menu
    WHERE deleted = 0 AND type = 1 AND parent_id = 0
      AND trim(both '/' from coalesce(path, '')) = 'basic';
    IF matches <> 1 THEN RAISE EXCEPTION '0246 需要唯一的基础管理菜单'; END IF;
    SELECT count(*), min(id) INTO matches, category_id FROM system_menu
    WHERE deleted = 0 AND type = 1 AND parent_id = basic_id
      AND trim(both '/' from coalesce(path, '')) = 'category';
    IF matches <> 1 THEN RAISE EXCEPTION '0246 需要唯一的类目管理菜单'; END IF;

    SELECT count(*), min(id) INTO matches, page_id FROM system_menu
    WHERE trim(both '/' from coalesce(component, '')) = 'dataforge/categorypush/index';
    IF matches > 1 OR EXISTS (SELECT 1 FROM system_menu WHERE id = page_id AND
       (deleted <> 0 OR type <> 2 OR parent_id <> category_id OR path <> 'push-category'
        OR permission <> 'dataforge:push-category:query'))
       OR EXISTS (SELECT 1 FROM system_menu WHERE deleted = 0 AND parent_id = category_id
                  AND path = 'push-category' AND id IS DISTINCT FROM page_id)
       OR EXISTS (SELECT 1 FROM system_menu WHERE deleted = 0
                  AND component_name = 'DataforgePushCategory' AND id IS DISTINCT FROM page_id)
    THEN RAISE EXCEPTION '0246 数据推送类目菜单身份冲突'; END IF;
    IF matches = 0 THEN
        SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_menu_seq),
                        (SELECT last_value FROM system_menu_id_seq)) + 1 INTO page_id FROM system_menu;
        INSERT INTO system_menu (id, name, permission, type, sort, parent_id, path, icon,
                                 component, component_name, status, visible, keep_alive, always_show,
                                 creator, updater, deleted)
        VALUES (page_id, '数据推送类目', 'dataforge:push-category:query', 2, 90, category_id,
                'push-category', 'lucide:folder-tree', 'dataforge/categorypush/index',
                'DataforgePushCategory', 0, true, true, true, 'migration:0246', 'migration:0246', 0);
    END IF;
    grant_ids := ARRAY[basic_id, category_id, page_id];

    FOR action IN SELECT * FROM (VALUES
        ('create', '新增类目', 1), ('update', '修改及切换状态', 2), ('delete', '删除及批量删除', 3)
    ) AS permissions(code, label, sort) LOOP
        SELECT count(*), min(id) INTO matches, action_id FROM system_menu
        WHERE permission = 'dataforge:push-category:' || action.code;
        IF matches > 1 OR EXISTS (SELECT 1 FROM system_menu WHERE id = action_id
             AND (deleted <> 0 OR type <> 3 OR parent_id <> page_id)) THEN
            RAISE EXCEPTION '0246 数据推送类目按钮身份冲突：%', action.code;
        END IF;
        IF matches = 0 THEN
            SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_menu_seq),
                            (SELECT last_value FROM system_menu_id_seq)) + 1 INTO action_id FROM system_menu;
            INSERT INTO system_menu (id, name, permission, type, sort, parent_id, path, status,
                                     visible, keep_alive, always_show, creator, updater, deleted)
            VALUES (action_id, action.label, 'dataforge:push-category:' || action.code, 3, action.sort,
                    page_id, '', 0, true, true, true, 'migration:0246', 'migration:0246', 0);
        END IF;
        grant_ids := array_append(grant_ids, action_id);
    END LOOP;

    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_menu_seq),
                    (SELECT last_value FROM system_menu_id_seq)) INTO high_id FROM system_menu;
    PERFORM setval('system_menu_seq', high_id, true);
    PERFORM setval('system_menu_id_seq', high_id, true);
    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_role_menu_seq))
      INTO high_id FROM system_role_menu;
    INSERT INTO system_role_menu (id, role_id, menu_id, tenant_id, creator, updater, deleted)
    SELECT high_id + row_number() OVER (ORDER BY role.id, role.tenant_id, menu.id),
           role.id, menu.id, role.tenant_id, 'migration:0246', 'migration:0246', 0
    FROM system_role role CROSS JOIN system_menu menu
    WHERE role.code = 'super_admin' AND role.status = 0 AND role.deleted = 0
      AND menu.id = ANY(grant_ids) AND menu.deleted = 0
      AND NOT EXISTS (SELECT 1 FROM system_role_menu old WHERE old.deleted = 0
          AND old.role_id = role.id AND old.tenant_id = role.tenant_id AND old.menu_id = menu.id);
    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_role_menu_seq))
      INTO high_id FROM system_role_menu;
    PERFORM setval('system_role_menu_seq', high_id, true);
END $menus$;

COMMIT;


