-- Migration: 0251 删除数据元审批与数据元、代码表版本能力
-- Purpose: 移除专用快照、审批、版本字段和权限；保留标准文件快照、质量规则及任务引用。
-- Depends on: 0250_dataforge_remove-access-overview-menu.sql；相关旧版服务及任务已停止。
-- Target: 已有 PostgreSQL 平台库；新库使用包含本迁移的全量基线。
-- Repeatable: 是；对象按存在性删除，权限清理和状态转换可重复执行。
-- Rollback: 失败时整笔回滚；提交后版本与审批记录不可恢复，须从执行前独立备份恢复数据、结构和权限。
-- 执行前停止旧版应用和任务并备份相关表；落标及质量规则改为跟随数据元当前内容，不再冻结历史版本。
-- 删除和索引重建需要表锁；不使用级联删除，未知依赖将阻止事务提交。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;
CREATE TEMPORARY TABLE governance_0251_retired_menus (id bigint PRIMARY KEY) ON COMMIT DROP;
INSERT INTO governance_0251_retired_menus (id)
SELECT id FROM system_menu WHERE permission = 'governance:standard-element:approve';
UPDATE system_tenant_package package
SET menu_ids = (
    SELECT coalesce(jsonb_agg(entry.value ORDER BY entry.ordinality), '[]'::jsonb)::text
    FROM jsonb_array_elements(package.menu_ids::jsonb) WITH ORDINALITY entry(value, ordinality)
    WHERE NOT EXISTS (SELECT 1 FROM governance_0251_retired_menus retired WHERE retired.id::text = entry.value #>> '{}')
), updater = 'migration:0251', update_time = CURRENT_TIMESTAMP
WHERE EXISTS (SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) entry(value)
              JOIN governance_0251_retired_menus retired ON retired.id::text = entry.value);
DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM governance_0251_retired_menus);
DELETE FROM system_menu WHERE id IN (SELECT id FROM governance_0251_retired_menus);

-- 审核中的对象恢复为草稿，保留已发布、已废止及乐观锁版本。
UPDATE dh_governance_standard_element SET lifecycle_status = 'DRAFT', revision = revision + 1,
    updater = 'migration:0251', update_time = CURRENT_TIMESTAMP
WHERE lifecycle_status = 'REVIEWING';
COMMENT ON COLUMN dh_governance_standard_element.lifecycle_status IS '生命周期状态：DRAFT-草稿 PUBLISHED-已发布 DEPRECATED-已废止';

CREATE OR REPLACE FUNCTION standard_workbench_child_guard() RETURNS trigger LANGUAGE plpgsql AS $guard$
BEGIN
 IF NEW.deleted <> 0 THEN RETURN NEW; END IF;
 IF TG_TABLE_NAME = 'dh_governance_standard_element_rule' THEN
  PERFORM 1 FROM dh_governance_standard_element WHERE id = NEW.element_id AND deleted = 0 AND lifecycle_status <> 'DEPRECATED' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '数据元不存在或当前生命周期不可编辑'; END IF;
  IF NEW.kind = 'AUDIT' THEN
   PERFORM 1 FROM dh_governance_audit_rule WHERE id = NEW.template_id AND deleted = 0;
  ELSE
   PERFORM 1 FROM dh_governance_clean_rule WHERE id = NEW.template_id AND deleted = 0;
  END IF;
  IF NOT FOUND THEN RAISE EXCEPTION '关联规则模板不存在'; END IF;
 ELSE
  PERFORM 1 FROM dh_governance_standard_code_set WHERE id = NEW.code_set_id AND deleted = 0 FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '代码表不存在'; END IF;
  PERFORM 1 FROM dh_governance_standard_code_item WHERE id = NEW.code_item_id AND code_set_id = NEW.code_set_id AND deleted = 0 AND status = 0;
  IF NOT FOUND THEN RAISE EXCEPTION '映射码值不属于该代码表或已停用'; END IF;
 END IF;
 RETURN NEW;
END $guard$;

-- 历史规则可能被质量任务引用；允许相同摘要的多条历史记录，保留规则编号和参数。
DROP INDEX IF EXISTS uk_dh_governance_quality_rule_std_constraint;
ALTER TABLE dh_governance_quality_rule DROP CONSTRAINT IF EXISTS ck_quality_standard_template_identity;
ALTER TABLE dh_governance_quality_rule DROP COLUMN IF EXISTS element_version;
ALTER TABLE dh_governance_quality_rule ADD CONSTRAINT ck_quality_standard_template_identity
 CHECK (standard_element_id IS NULL OR (constraint_hash IS NOT NULL AND constraint_hash ~ '^[0-9a-f]{64}$'));
CREATE INDEX IF NOT EXISTS idx_quality_rule_standard_constraint
 ON dh_governance_quality_rule (standard_element_id, constraint_hash)
 WHERE deleted = 0 AND standard_element_id IS NOT NULL;
COMMENT ON COLUMN dh_governance_quality_rule.constraint_hash IS '生成规则时的约束摘要，用于匹配当前数据元配置';
ALTER TABLE dh_governance_standard_mapping DROP COLUMN IF EXISTS element_version;

-- 对象版本表由标准文件与代码表共用，只删除代码表快照。
DELETE FROM dh_governance_standard_object_version WHERE object_type = 'CODE_SET';
DROP TABLE IF EXISTS dh_governance_standard_element_approval;
DROP TABLE IF EXISTS dh_governance_standard_element_version;
DROP FUNCTION IF EXISTS reject_standard_element_version_mutation();
DROP SEQUENCE IF EXISTS dh_governance_standard_element_approval_seq;
DROP SEQUENCE IF EXISTS dh_governance_standard_element_version_seq;
COMMIT;


-- Migration: 0252 数据集成 DS 原生执行控制面
-- Purpose: 保存受管 DS 工作流与真实实例绑定，允许集成任务原生周期调度
-- Depends on: 0250_dataforge_remove-access-overview-menu.sql; 已存在数据集成任务和记录表
-- Target: 已有 PostgreSQL 数据中台库；新库基线已同步
-- Repeatable: yes; 加法字段和条件索引可重复执行，约束按固定最终定义重建
-- Rollback: 先下线 DS 工作流及调度，再移除新增绑定列与索引；不删除真实 DS 实例，历史实例需管理员保留

BEGIN;
ALTER TABLE dh_dataforge_integration_task
 ADD COLUMN IF NOT EXISTS ds_project_code bigint,
 ADD COLUMN IF NOT EXISTS ds_definition_code bigint,
 ADD COLUMN IF NOT EXISTS ds_schedule_id integer,
 ADD COLUMN IF NOT EXISTS ds_binding_hash varchar(64);
COMMENT ON COLUMN dh_dataforge_integration_task.ds_project_code IS '受管 DolphinScheduler 项目编码';
COMMENT ON COLUMN dh_dataforge_integration_task.ds_definition_code IS '正式保存流程生成的 DS 工作流编码';
COMMENT ON COLUMN dh_dataforge_integration_task.ds_schedule_id IS 'DS 周期调度编号';
COMMENT ON COLUMN dh_dataforge_integration_task.ds_binding_hash IS '正式发布时原生参数与受管运行环境摘要';
ALTER TABLE dh_dataforge_integration_record
 ADD COLUMN IF NOT EXISTS ds_project_code bigint,
 ADD COLUMN IF NOT EXISTS ds_instance_id integer;
COMMENT ON COLUMN dh_dataforge_integration_record.ds_project_code IS '真实执行的 DS 项目编码，迁入记录为空';
COMMENT ON COLUMN dh_dataforge_integration_record.ds_instance_id IS '真实执行的 DS 工作流实例编号，迁入记录为空';
CREATE UNIQUE INDEX IF NOT EXISTS uk_integration_record_ds_instance
 ON dh_dataforge_integration_record(ds_project_code,ds_instance_id) WHERE ds_instance_id IS NOT NULL AND deleted=0;
DO $constraints$
DECLARE item record;
BEGIN
 FOR item IN SELECT conname FROM pg_constraint WHERE conrelid='dh_dataforge_integration_task'::regclass
  AND contype='c' AND position('pipeline_id' IN pg_get_constraintdef(oid))>0
  AND position('schedule_status' IN pg_get_constraintdef(oid))>0 LOOP
  EXECUTE format('ALTER TABLE dh_dataforge_integration_task DROP CONSTRAINT %I',item.conname);
 END LOOP;
 ALTER TABLE dh_dataforge_integration_task ADD CONSTRAINT ck_integration_ds_schedule
  CHECK(schedule_status=0 OR (status=1 AND (pipeline_id IS NOT NULL OR ds_definition_code IS NOT NULL)));
END $constraints$;
COMMIT;

-- 补齐整库同步向导持久化结构。
-- Migration: 0237_dataforge_full-sync-wizard.sql
-- Purpose: 持久化整库同步四步向导草稿及 DB Switch / DolphinScheduler DataX 提交边界。
-- Depends on: 0235_governance_qdata-whitelist-policies.sql；0236_modeling_remove-model-versions.sql（若已部署则继续沿用，未部署也不影响本表）。
-- Target: 已有 PostgreSQL 平台库；新库基线需包含本迁移。
-- Repeatable: 是；序列、表、索引和约束均使用存在性保护。
-- Rollback: 删除本表会丢失未提交向导草稿及外部工作流引用，执行前须确认没有 SUBMITTING/UNKNOWN 记录；不自动删除 DolphinScheduler 流程。
-- Security 安全说明：config_json 仅保存业务配置；DolphinScheduler 数据源编号作为外部引用，禁止保存密码、令牌或连接串。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_full_sync_wizard_seq;

CREATE TABLE IF NOT EXISTS dh_dataforge_full_sync_wizard (
    id bigint NOT NULL DEFAULT nextval('dh_dataforge_full_sync_wizard_seq'::regclass),
    current_step integer NOT NULL DEFAULT 1,
    revision bigint NOT NULL DEFAULT 1,
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    execution_mode varchar(32) NOT NULL DEFAULT 'DBSWITCH',
    data_access_id bigint,
    ds_project_code bigint,
    ds_worker_group varchar(128),
    ds_tenant_code varchar(128),
    ds_source_datasource_code bigint,
    ds_target_datasource_code bigint,
    ds_workflow_code bigint,
    ds_schedule_id integer,
    ds_instance_id integer,
    submit_request_id varchar(64),
    last_error varchar(512),
    config_json jsonb NOT NULL DEFAULT '{}'::jsonb,
    creator varchar(64) NOT NULL DEFAULT '',
    create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updater varchar(64) NOT NULL DEFAULT '',
    update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    deleted smallint NOT NULL DEFAULT 0,
    CONSTRAINT pk_dh_dataforge_full_sync_wizard PRIMARY KEY (id),
    CONSTRAINT ck_dh_full_sync_wizard_step CHECK (current_step BETWEEN 1 AND 4),
    CONSTRAINT ck_dh_full_sync_wizard_revision CHECK (revision > 0),
    CONSTRAINT ck_dh_full_sync_wizard_status CHECK (status IN ('DRAFT','SUBMITTING','SUBMITTED','FAILED','UNKNOWN')),
    CONSTRAINT ck_dh_full_sync_wizard_mode CHECK (execution_mode IN ('DBSWITCH','DOLPHIN_DATAX')),
    CONSTRAINT ck_dh_full_sync_wizard_config CHECK (jsonb_typeof(config_json) = 'object')
);

ALTER SEQUENCE dh_dataforge_full_sync_wizard_seq OWNED BY dh_dataforge_full_sync_wizard.id;
CREATE INDEX IF NOT EXISTS idx_dh_full_sync_wizard_status
    ON dh_dataforge_full_sync_wizard(status, update_time DESC) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_dh_full_sync_wizard_data_access
    ON dh_dataforge_full_sync_wizard(data_access_id) WHERE deleted=0 AND data_access_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_dh_full_sync_wizard_ds_workflow
    ON dh_dataforge_full_sync_wizard(ds_project_code, ds_workflow_code)
    WHERE deleted=0 AND ds_workflow_code IS NOT NULL;

COMMENT ON TABLE dh_dataforge_full_sync_wizard IS '整库同步四步向导草稿及外部执行提交状态';
COMMENT ON COLUMN dh_dataforge_full_sync_wizard.config_json IS '四步业务配置 JSON；禁止保存密码、令牌和连接串';
COMMENT ON COLUMN dh_dataforge_full_sync_wizard.ds_source_datasource_code IS 'DolphinScheduler 数据源中心来源编号，仅外部引用';
COMMENT ON COLUMN dh_dataforge_full_sync_wizard.ds_target_datasource_code IS 'DolphinScheduler 数据源中心目标编号，仅外部引用';
COMMENT ON COLUMN dh_dataforge_full_sync_wizard.status IS 'DRAFT/SUBMITTING/SUBMITTED/FAILED/UNKNOWN；UNKNOWN 需人工核对外部调度器';

COMMIT;



-- Migration: 0253 整库同步配置菜单与权限
-- Purpose: 新增整库同步列表入口及查询、新增、配置、删除权限；不授予发布执行权限。
-- Depends on: 0237_dataforge_full-sync-wizard.sql；0252_dataforge_integration-ds-runtime.sql（编号链）；数据接入父菜单 system_menu.id=5987。
-- Target: 已有 PostgreSQL 平台库；新库基线包含本迁移。
-- Repeatable: 是；按组件和权限身份校验并补齐，重复执行不重复创建。
-- Rollback: 仅添加菜单和授权；回滚时先删除本菜单及其按钮的角色授权，再删除对应菜单，不删除向导配置。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE page_id bigint; new_id bigint; high_id bigint; matches integer; item record;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM system_menu WHERE id=5987 AND path='integrate' AND deleted=0) THEN
  RAISE EXCEPTION '0253 数据接入父菜单缺失';
 END IF;
 SELECT count(*),min(id) INTO matches,page_id FROM system_menu WHERE component='dataforge/fullsync/index' AND deleted=0;
 IF matches>1 THEN RAISE EXCEPTION '0253 整库同步页面重复'; END IF;
 IF matches=0 THEN
  IF EXISTS(SELECT 1 FROM system_menu WHERE deleted=0 AND (permission='dataforge:full-sync:query' OR (parent_id=5987 AND path='full-sync'))) THEN
   RAISE EXCEPTION '0253 整库同步菜单身份冲突';
  END IF;
  SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO page_id FROM system_menu;
  INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,deleted)
  VALUES(page_id,'整库同步','dataforge:full-sync:query',2,5,5987,'full-sync','lucide:database-backup','dataforge/fullsync/index','DataforgeFullSync',0,true,true,true,'migration:0253','migration:0253',0);
 ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=page_id AND parent_id=5987 AND path='full-sync' AND permission='dataforge:full-sync:query' AND type=2) THEN
  RAISE EXCEPTION '0253 整库同步菜单归属冲突';
 END IF;
 FOR item IN SELECT * FROM (VALUES ('create','新增整库同步配置',1),('update','配置整库同步任务',2),('delete','删除整库同步配置',3)) permissions(code,label,sort) LOOP
  SELECT count(*) INTO matches FROM system_menu WHERE permission='dataforge:full-sync:'||item.code AND deleted=0;
  IF matches=0 THEN
   SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO new_id FROM system_menu;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
   VALUES(new_id,item.label,'dataforge:full-sync:'||item.code,3,item.sort,page_id,'',0,true,true,true,'migration:0253','migration:0253',0);
  ELSIF matches<>1 OR NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='dataforge:full-sync:'||item.code AND parent_id=page_id AND type=3 AND deleted=0) THEN
   RAISE EXCEPTION '0253 整库同步权限归属冲突';
  END IF;
 END LOOP;
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq)) INTO high_id FROM system_menu;
 PERFORM setval('system_menu_seq',high_id); PERFORM setval('system_menu_id_seq',high_id);
 -- 只补齐超级管理员配置管理权限，不修改既有发布执行权限。
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
 INSERT INTO system_role_menu(id,role_id,menu_id,tenant_id,creator,updater,deleted)
 SELECT high_id+row_number() OVER(ORDER BY r.id,r.tenant_id,m.id),r.id,m.id,r.tenant_id,'migration:0253','migration:0253',0
 FROM system_role r CROSS JOIN system_menu m
 WHERE r.code='super_admin' AND r.deleted=0 AND m.deleted=0 AND (m.id=page_id OR m.parent_id=page_id)
 AND NOT EXISTS(SELECT 1 FROM system_role_menu old WHERE old.role_id=r.id AND old.tenant_id=r.tenant_id AND old.menu_id=m.id AND old.deleted=0);
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
 PERFORM setval('system_role_menu_seq',high_id);
END $menus$;
COMMIT;

-- 新库同步增量：0254_dataforge_offline-realtime-task-menus.sql
-- Migration: 0254 数据开发离线任务与实时任务入口
-- Purpose: 在原数据开发目录下新增离线和实时任务页面，保留工作台及既有任务操作权限。
-- Depends on: 0253_dataforge_full-sync-menu.sql（编号链）；现有 /develop/dev 目录及 dataforge/dev/index 工作台。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库基线包含本迁移。
-- Repeatable: 是；按页面组件校验身份后补齐，已存在菜单和角色授权保持不变。
-- Rollback: 删除 migration:0254 创建的两个页面及其角色菜单关联；不删除工作台、任务或操作权限。
-- 仅将原工作台已有菜单可见范围延伸到同权限的新入口，不新增保存、运行或原生执行授权。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';
LOCK TABLE system_menu, system_role_menu IN SHARE ROW EXCLUSIVE MODE;

DO $menus$
DECLARE
    directory_id bigint;
    workbench_id bigint;
    page_id bigint;
    high_id bigint;
    matches integer;
    item record;
BEGIN
    SELECT count(*), min(d.id) INTO matches, directory_id
    FROM system_menu d JOIN system_menu root ON root.id = d.parent_id
    WHERE d.deleted = 0 AND d.type = 1 AND d.path = 'dev'
      AND root.deleted = 0 AND trim(both '/' from root.path) = 'develop';
    IF matches <> 1 THEN
        RAISE EXCEPTION '0254 数据开发目录缺失或重复';
    END IF;
    SELECT count(*), min(id) INTO matches, workbench_id
    FROM system_menu
    WHERE deleted = 0 AND type = 2 AND parent_id = directory_id
      AND trim(both '/' from coalesce(component, '')) = 'dataforge/dev/index'
      AND permission = 'dataforge:dev-task:query';
    IF matches <> 1 THEN
        RAISE EXCEPTION '0254 原数据开发工作台缺失或权限归属不一致';
    END IF;

    FOR item IN SELECT * FROM (VALUES
        ('offline', '离线任务', 'dataforge/dev/offline/index', 'DataforgeDevOffline', 'lucide:calendar-clock', 2),
        ('realtime', '实时任务', 'dataforge/dev/realtime/index', 'DataforgeDevRealtime', 'lucide:radio', 3)
    ) entries(path, label, component, component_name, icon, sort) LOOP
        SELECT count(*), min(id) INTO matches, page_id
        FROM system_menu WHERE deleted = 0 AND component = item.component;
        IF matches > 1 THEN
            RAISE EXCEPTION '0254 页面组件重复：%', item.component;
        END IF;
        IF matches = 0 THEN
            IF EXISTS (SELECT 1 FROM system_menu
                       WHERE deleted = 0 AND parent_id = directory_id AND path = item.path) THEN
                RAISE EXCEPTION '0254 菜单路径冲突：%', item.path;
            END IF;
            SELECT greatest(coalesce(max(id), 0),
                   (SELECT last_value FROM system_menu_seq),
                   (SELECT last_value FROM system_menu_id_seq)) + 1 INTO page_id FROM system_menu;
            INSERT INTO system_menu
                (id, name, permission, type, sort, parent_id, path, icon, component, component_name,
                 status, visible, keep_alive, always_show, creator, updater, deleted)
            VALUES
                (page_id, item.label, 'dataforge:dev-task:query', 2, item.sort, directory_id,
                 item.path, item.icon, item.component, item.component_name, 0, true, true, true,
                 'migration:0254', 'migration:0254', 0);
        ELSIF NOT EXISTS (SELECT 1 FROM system_menu
                          WHERE id = page_id AND parent_id = directory_id AND path = item.path
                            AND permission = 'dataforge:dev-task:query' AND type = 2) THEN
            RAISE EXCEPTION '0254 菜单身份冲突：%', item.component;
        END IF;

        SELECT greatest(coalesce(max(id), 0),
               (SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
        INSERT INTO system_role_menu (id, role_id, menu_id, tenant_id, creator, updater, deleted)
        SELECT high_id + row_number() OVER (ORDER BY source.role_id, source.tenant_id),
               source.role_id, page_id, source.tenant_id, 'migration:0254', 'migration:0254', 0
        FROM (SELECT DISTINCT role_id, tenant_id FROM system_role_menu
              WHERE menu_id = workbench_id AND deleted = 0) source
        WHERE NOT EXISTS (SELECT 1 FROM system_role_menu existing
                          WHERE existing.role_id = source.role_id AND existing.tenant_id = source.tenant_id
                            AND existing.menu_id = page_id AND existing.deleted = 0);
    END LOOP;

    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_menu_seq),
           (SELECT last_value FROM system_menu_id_seq)) INTO high_id FROM system_menu;
    PERFORM setval('system_menu_seq', high_id);
    PERFORM setval('system_menu_id_seq', high_id);
    SELECT greatest(coalesce(max(id), 0), (SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
    PERFORM setval('system_role_menu_seq', high_id);
END $menus$;
COMMIT;

-- Migration: 0255 作业管理与整库同步、作业运维实例
-- Purpose: 新增平台共享作业编排、受管调度状态、可追踪执行记录和显式演示历史数据，补齐两类运维菜单。
-- Depends on: 0254_dataforge_offline-realtime-task-menus.sql；0217_dataforge_operations-instances.sql；0237_dataforge_full-sync-wizard.sql。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库基线同步包含本迁移。
-- Repeatable: 是；结构按存在性补齐，演示数据按业务唯一名和请求编号首次插入，菜单按组件校验。
-- Rollback: 先确认没有活动 DS 作业或调度，再移除 migration:0255 菜单与新表；删除新表会丢失作业配置及历史记录，不自动删除远端 DS 定义。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_job_category_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_job_category(id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_job_category_seq'),
 parent_id bigint NOT NULL DEFAULT 0,name varchar(100) NOT NULL,sort integer NOT NULL DEFAULT 0,
 creator varchar(64) NOT NULL DEFAULT '',create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '',update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0);
ALTER SEQUENCE dh_dataforge_job_category_seq OWNED BY dh_dataforge_job_category.id;
COMMENT ON TABLE dh_dataforge_job_category IS '作业类目';
COMMENT ON COLUMN dh_dataforge_job_category.id IS '记录编号';
COMMENT ON COLUMN dh_dataforge_job_category.parent_id IS '父类目编号，零表示根类目';
COMMENT ON COLUMN dh_dataforge_job_category.name IS '名称';
COMMENT ON COLUMN dh_dataforge_job_category.sort IS '排序';
COMMENT ON COLUMN dh_dataforge_job_category.creator IS '创建人';
COMMENT ON COLUMN dh_dataforge_job_category.create_time IS '创建时间';
COMMENT ON COLUMN dh_dataforge_job_category.updater IS '更新人';
COMMENT ON COLUMN dh_dataforge_job_category.update_time IS '更新时间';
COMMENT ON COLUMN dh_dataforge_job_category.deleted IS '逻辑删除标记';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_job_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_job(id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_job_seq'),
 revision integer NOT NULL DEFAULT 0,category_id bigint NOT NULL REFERENCES dh_dataforge_job_category(id),
 name varchar(200) NOT NULL,owner_id bigint,owner_name varchar(100),owner_phone varchar(50),
 status smallint NOT NULL DEFAULT 0 CHECK(status IN(0,1)),schedule_status smallint NOT NULL DEFAULT 0 CHECK(schedule_status IN(0,1)),
 strategy varchar(32) NOT NULL DEFAULT 'PARALLEL' CHECK(strategy IN('PARALLEL','SERIAL_WAIT','SERIAL_DISCARD','SERIAL_PRIORITY')),
 cron_expression varchar(128),description varchar(2000),flow_json jsonb NOT NULL DEFAULT '{"nodes":[],"edges":[]}'::jsonb CHECK(jsonb_typeof(flow_json)='object'),
 ds_project_code bigint,ds_definition_code bigint,ds_schedule_id integer,
 operation_state varchar(16) NOT NULL DEFAULT 'IDLE' CHECK(operation_state IN('IDLE','BUSY')),
 creator varchar(64) NOT NULL DEFAULT '',create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '',update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0);
ALTER SEQUENCE dh_dataforge_job_seq OWNED BY dh_dataforge_job.id;
COMMENT ON TABLE dh_dataforge_job IS '作业编排配置与受管调度控制状态';
COMMENT ON COLUMN dh_dataforge_job.id IS '记录编号';
COMMENT ON COLUMN dh_dataforge_job.revision IS '乐观锁修订号';
COMMENT ON COLUMN dh_dataforge_job.category_id IS '作业类目编号';
COMMENT ON COLUMN dh_dataforge_job.name IS '名称';
COMMENT ON COLUMN dh_dataforge_job.owner_id IS '负责人编号';
COMMENT ON COLUMN dh_dataforge_job.owner_name IS '负责人姓名';
COMMENT ON COLUMN dh_dataforge_job.owner_phone IS '负责人联系方式';
COMMENT ON COLUMN dh_dataforge_job.status IS '配置上线状态或实例执行状态';
COMMENT ON COLUMN dh_dataforge_job.schedule_status IS '受管调度开关';
COMMENT ON COLUMN dh_dataforge_job.strategy IS '执行策略';
COMMENT ON COLUMN dh_dataforge_job.cron_expression IS '上海时区 Quartz 调度表达式';
COMMENT ON COLUMN dh_dataforge_job.description IS '业务描述，演示记录明确注明来源';
COMMENT ON COLUMN dh_dataforge_job.flow_json IS '不包含凭据的作业节点和连线';
COMMENT ON COLUMN dh_dataforge_job.ds_project_code IS '受管调度器项目编号';
COMMENT ON COLUMN dh_dataforge_job.ds_definition_code IS '受管工作流定义编号';
COMMENT ON COLUMN dh_dataforge_job.ds_schedule_id IS '受管周期编号';
COMMENT ON COLUMN dh_dataforge_job.operation_state IS '远端控制操作占用状态；异常中断需管理员核对远端后恢复';
COMMENT ON COLUMN dh_dataforge_job.creator IS '创建人';
COMMENT ON COLUMN dh_dataforge_job.create_time IS '创建时间';
COMMENT ON COLUMN dh_dataforge_job.updater IS '更新人';
COMMENT ON COLUMN dh_dataforge_job.update_time IS '更新时间';
COMMENT ON COLUMN dh_dataforge_job.deleted IS '逻辑删除标记';

CREATE SEQUENCE IF NOT EXISTS dh_dataforge_job_record_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_job_record(id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_job_record_seq'),
 job_id bigint NOT NULL REFERENCES dh_dataforge_job(id),origin varchar(16) NOT NULL DEFAULT 'PLATFORM' CHECK(origin IN('SOURCE','PLATFORM')),
 request_id varchar(64),instance_name varchar(512) NOT NULL,status varchar(16) NOT NULL CHECK(status IN('WAITING','RUNNING','SUCCESS','FAILURE','STOPPED','UNKNOWN','IDLE')),
 execution_type varchar(16) NOT NULL DEFAULT 'START',ds_project_code bigint,ds_instance_id integer,
 start_time timestamp,end_time timestamp,duration bigint,log_content text,flow_json jsonb,children_json jsonb NOT NULL DEFAULT '[]'::jsonb,
 creator varchar(64) NOT NULL DEFAULT '',create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '',update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0);
ALTER SEQUENCE dh_dataforge_job_record_seq OWNED BY dh_dataforge_job_record.id;
COMMENT ON TABLE dh_dataforge_job_record IS '作业执行实例，SOURCE 为演示历史，PLATFORM 为真实提交';
COMMENT ON COLUMN dh_dataforge_job_record.id IS '记录编号';
COMMENT ON COLUMN dh_dataforge_job_record.job_id IS '所属作业编号';
COMMENT ON COLUMN dh_dataforge_job_record.origin IS 'SOURCE 演示历史或 PLATFORM 真实运行';
COMMENT ON COLUMN dh_dataforge_job_record.request_id IS '运行幂等请求编号';
COMMENT ON COLUMN dh_dataforge_job_record.instance_name IS '实例名称';
COMMENT ON COLUMN dh_dataforge_job_record.status IS '配置上线状态或实例执行状态';
COMMENT ON COLUMN dh_dataforge_job_record.execution_type IS '启动或停止类型';
COMMENT ON COLUMN dh_dataforge_job_record.ds_project_code IS '受管调度器项目编号';
