CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_dataforge_job_name ON dh_dataforge_job(name) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_dh_dataforge_job_category ON dh_dataforge_job(category_id) WHERE deleted=0;
CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_dataforge_job_request ON dh_dataforge_job_record(request_id) WHERE deleted=0 AND request_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_dh_dataforge_job_record_task ON dh_dataforge_job_record(job_id,start_time DESC,id DESC) WHERE deleted=0;
CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_dataforge_job_ds_instance ON dh_dataforge_job_record(ds_project_code,ds_instance_id) WHERE deleted=0 AND ds_instance_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_dh_dataforge_ops_aux_demo ON dh_dataforge_ops_aux_snapshot(kind,instance_name) WHERE deleted=0;

DO $demo$
DECLARE label text; category_id bigint; job_id bigint; task record; graph jsonb; nodes jsonb; edges jsonb; children jsonb; rownum integer:=0; instance_time timestamp;
BEGIN
 FOR label IN SELECT unnest(ARRAY['河道水情业务','灌区管理业务','防洪减灾业务','农村供水业务','水土保持业务','水资源管理业务','水利工程管理业务','生态流量监管业务']) LOOP
  IF NOT EXISTS(SELECT 1 FROM dh_dataforge_job_category c WHERE c.name=label AND c.deleted=0) THEN
   INSERT INTO dh_dataforge_job_category(parent_id,name,sort,creator,updater) VALUES(0,label,rownum,'migration:0255','migration:0255');
  END IF;
  rownum:=rownum+1;
 END LOOP;
 rownum:=0;
 FOR label IN SELECT unnest(ARRAY['河道水情_月水位统计数据产品_每日作业','灌区管理_用水量汇总_每日作业','防洪减灾_雨水情监测_每日作业']) LOOP
  rownum:=rownum+1;
  SELECT c.id INTO category_id FROM dh_dataforge_job_category c WHERE c.deleted=0 ORDER BY c.sort,c.id OFFSET rownum-1 LIMIT 1;
  nodes:='[]'::jsonb;edges:='[]'::jsonb;children:='[]'::jsonb;
  FOR task IN SELECT id,name,'INTEGRATION'::text kind FROM dh_dataforge_integration_task WHERE deleted=0 ORDER BY id LIMIT 2 LOOP
   nodes:=nodes||jsonb_build_array(jsonb_build_object('id','task_'||task.id,'kind',task.kind,'taskId',task.id::text,'name',task.name,'x',100+jsonb_array_length(nodes)*300,'y',170));
   IF jsonb_array_length(nodes)>1 THEN edges:=edges||jsonb_build_array(jsonb_build_object('source',nodes->0->>'id','target','task_'||task.id));END IF;
   children:=children||jsonb_build_array(jsonb_build_object('id',task.id::text,'kind',task.kind,'origin','SOURCE','taskId',task.id::text,'taskName',task.name,'instanceName',task.name||'-演示历史','status','SUCCESS','executionType','START','startTime','2026-10-31 02:00:00','endTime','2026-10-31 02:00:12','duration',12,'description','演示历史数据，仅用于页面查看，不代表本平台执行'));
  END LOOP;
  graph:=jsonb_build_object('nodes',nodes,'edges',edges);
  IF NOT EXISTS(SELECT 1 FROM dh_dataforge_job j WHERE j.name=label AND j.deleted=0) THEN
   INSERT INTO dh_dataforge_job(category_id,name,strategy,cron_expression,description,flow_json,creator,updater)
   VALUES(category_id,label,CASE WHEN rownum=1 THEN 'SERIAL_WAIT' ELSE 'PARALLEL' END,'0 0 2 * * ?','演示作业，可编辑配置。历史实例为测试数据，不表示本平台真实执行。',graph,'migration:0255','migration:0255');
  END IF;
  SELECT j.id INTO job_id FROM dh_dataforge_job j WHERE j.name=label AND j.deleted=0;
  instance_time:='2026-10-31 02:00:00'::timestamp+make_interval(mins=>rownum);
  IF NOT EXISTS(SELECT 1 FROM dh_dataforge_job_record WHERE request_id='demo0255_job_'||rownum) THEN
   INSERT INTO dh_dataforge_job_record(job_id,origin,request_id,instance_name,status,start_time,end_time,duration,log_content,flow_json,children_json,creator,updater)
   VALUES(job_id,'SOURCE','demo0255_job_'||rownum,label||'-1-20261031020000',CASE WHEN rownum=3 THEN 'FAILURE' ELSE 'SUCCESS' END,instance_time,instance_time+interval '12 seconds',12,'演示历史日志：仅用于页面与弹窗查看，不代表本平台执行。',graph,children,'migration:0255','migration:0255');
  END IF;
  INSERT INTO dh_dataforge_ops_aux_snapshot(kind,task_id,category_id,task_name,instance_name,status,start_time,end_time,duration,description,log_content,creator,updater)
  VALUES('FULL_SYNC',job_id,category_id,CASE rownum WHEN 1 THEN '基础业务数据整库同步' WHEN 2 THEN '水利监测数据整库同步' ELSE '业务档案整库同步' END,'整库同步-演示历史-'||rownum,CASE WHEN rownum=3 THEN 'FAILURE' ELSE 'SUCCESS' END,instance_time,instance_time+interval '42 seconds',42,'演示历史数据，仅供页面查看，不表示本平台同步成功。','演示日志：已准备页面展示所需测试数据，未连接源库或目标库。','migration:0255','migration:0255')
  ON CONFLICT(kind,instance_name) WHERE deleted=0 DO NOTHING;
 END LOOP;
END $demo$;

LOCK TABLE system_menu,system_role_menu IN SHARE ROW EXCLUSIVE MODE;
DO $menus$
DECLARE root_id bigint; ops_id bigint; job_id bigint; page_id bigint; new_id bigint; high_id bigint; entry record;
BEGIN
 SELECT id INTO root_id FROM system_menu WHERE deleted=0 AND trim(both '/' from path)='develop' AND parent_id=0;
 IF root_id IS NULL THEN RAISE EXCEPTION '0255 数据研发父菜单缺失'; END IF;
 SELECT id INTO ops_id FROM system_menu WHERE parent_id=root_id AND path='operations' AND deleted=0;
 IF ops_id IS NULL THEN RAISE EXCEPTION '0255 既有运维管理菜单缺失，请先执行0217';END IF;
 FOR entry IN SELECT * FROM (VALUES
 ('作业管理','job','dataforge/job/index','DataforgeJob',root_id,4,'dataforge:job:query'),
 ('整库同步实例','full-sync','dataforge/ops/fullsync/index','DataforgeOpsFullSync',ops_id,3,'dataforge:ops-instance:query'),
 ('作业管理实例','job','dataforge/ops/job/index','DataforgeOpsJob',ops_id,4,'dataforge:ops-instance:query')
 ) e(label,path,component,component_name,parent,sort,permission) LOOP
  SELECT id INTO page_id FROM system_menu WHERE component=entry.component AND deleted=0;
  IF page_id IS NULL THEN
   IF EXISTS(SELECT 1 FROM system_menu WHERE parent_id=entry.parent AND path=entry.path AND deleted=0) THEN RAISE EXCEPTION '0255 菜单路径冲突：%',entry.path; END IF;
   SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO page_id FROM system_menu;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,icon,component,component_name,status,visible,keep_alive,always_show,creator,updater,deleted)
   VALUES(page_id,entry.label,entry.permission,2,entry.sort,entry.parent,entry.path,'carbon:task',entry.component,entry.component_name,0,true,true,true,'migration:0255','migration:0255',0);
  ELSIF NOT EXISTS(SELECT 1 FROM system_menu WHERE id=page_id AND parent_id=entry.parent AND path=entry.path AND permission=entry.permission) THEN RAISE EXCEPTION '0255 菜单组件身份冲突：%',entry.component;END IF;
  IF entry.component='dataforge/job/index' THEN job_id:=page_id;END IF;
 END LOOP;
 FOR entry IN SELECT * FROM (VALUES('新增作业','create'),('编辑作业与配置','update'),('删除作业','delete'),('运行与停止作业','run')) e(label,code) LOOP
  IF NOT EXISTS(SELECT 1 FROM system_menu WHERE parent_id=job_id AND permission='dataforge:job:'||entry.code AND deleted=0) THEN
   SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq))+1 INTO new_id FROM system_menu;
   INSERT INTO system_menu(id,name,permission,type,sort,parent_id,path,status,visible,keep_alive,always_show,creator,updater,deleted)
   VALUES(new_id,entry.label,'dataforge:job:'||entry.code,3,1,job_id,'',0,true,true,true,'migration:0255','migration:0255',0);
  END IF;
 END LOOP;
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_menu_seq),(SELECT last_value FROM system_menu_id_seq)) INTO high_id FROM system_menu;
 PERFORM setval('system_menu_seq',high_id);PERFORM setval('system_menu_id_seq',high_id);
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;
 INSERT INTO system_role_menu(id,role_id,menu_id,tenant_id,creator,updater,deleted)
 SELECT high_id+row_number() OVER(ORDER BY r.id,r.tenant_id,m.id),r.id,m.id,r.tenant_id,'migration:0255','migration:0255',0 FROM system_role r CROSS JOIN system_menu m
 WHERE r.code='super_admin' AND r.deleted=0 AND m.deleted=0 AND m.creator='migration:0255'
 AND NOT EXISTS(SELECT 1 FROM system_role_menu old WHERE old.role_id=r.id AND old.tenant_id=r.tenant_id AND old.menu_id=m.id AND old.deleted=0);
 SELECT greatest(coalesce(max(id),0),(SELECT last_value FROM system_role_menu_seq)) INTO high_id FROM system_role_menu;PERFORM setval('system_role_menu_seq',high_id);
END $menus$;
COMMIT;

-- Migration: 0256 作业真实父子执行与开发受管编排
-- Purpose: 持久化作业父流程、冻结执行人及逐节点平台记录与真实 DS 身份，支持可核对的混合作业。
-- Depends on: 0255_dataforge_job-management-operations.sql；0252_dataforge_integration-ds-runtime.sql；现有开发任务版本与运行记录表。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库基线同步包含本迁移。
-- Repeatable: 是；加法字段、序列、表及索引按存在性创建，不修改既有作业或演示数据。
-- Rollback: 确认所有父子运行已结束后再移除新字段与关系表；删除关系会丢失运行核对链，不自动删除远端定义。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
ALTER TABLE dh_dataforge_job_record
 ADD COLUMN IF NOT EXISTS ds_definition_code bigint,
 ADD COLUMN IF NOT EXISTS execution_user_id bigint,
 ADD COLUMN IF NOT EXISTS submission_stage varchar(32),
 ADD COLUMN IF NOT EXISTS runtime_target_json jsonb;
COMMENT ON COLUMN dh_dataforge_job_record.ds_definition_code IS '本次父工作流定义编号，不与后续运行复用';
COMMENT ON COLUMN dh_dataforge_job_record.execution_user_id IS '服务端冻结的实际执行人，不接受客户端覆盖';
COMMENT ON COLUMN dh_dataforge_job_record.submission_stage IS '准备、触发意图与已确认阶段，未知触发禁止盲目重试';
COMMENT ON COLUMN dh_dataforge_job_record.runtime_target_json IS '本次冻结的受管项目、工作组、外部执行用户与环境引用，不含凭据';
CREATE SEQUENCE IF NOT EXISTS dh_dataforge_job_node_run_seq;
CREATE TABLE IF NOT EXISTS dh_dataforge_job_node_run (
 id bigint PRIMARY KEY DEFAULT nextval('dh_dataforge_job_node_run_seq'),
 job_record_id bigint NOT NULL REFERENCES dh_dataforge_job_record(id),
 node_id varchar(80) NOT NULL,kind varchar(20) NOT NULL CHECK(kind IN('INTEGRATION','DEVELOPMENT')),
 task_id bigint NOT NULL,task_name varchar(200),task_version bigint,platform_record_id bigint,
 ds_project_code bigint NOT NULL,ds_definition_code bigint,parent_task_code bigint,
 parent_task_instance_id integer,ds_instance_id integer,status varchar(20) NOT NULL DEFAULT 'WAITING',
 creator varchar(64) NOT NULL DEFAULT '',create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 updater varchar(64) NOT NULL DEFAULT '',update_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
 deleted smallint NOT NULL DEFAULT 0);
ALTER SEQUENCE dh_dataforge_job_node_run_seq OWNED BY dh_dataforge_job_node_run.id;
COMMENT ON TABLE dh_dataforge_job_node_run IS '作业运行内冻结节点及真实平台、调度器父子实例关联';
COMMENT ON COLUMN dh_dataforge_job_node_run.id IS '记录编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.job_record_id IS '本次作业父记录编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.node_id IS '保存图中的稳定节点编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.kind IS '集成或开发节点类型';
COMMENT ON COLUMN dh_dataforge_job_node_run.task_id IS '平台任务编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.task_name IS '准备运行时冻结的真实任务名称';
COMMENT ON COLUMN dh_dataforge_job_node_run.task_version IS '冻结开发版本或集成修订号';
COMMENT ON COLUMN dh_dataforge_job_node_run.platform_record_id IS '对应模块的真实运行记录编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.ds_project_code IS '冻结受管调度器项目编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.ds_definition_code IS '本次节点实际工作流定义编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.parent_task_code IS '父工作流内稳定任务编码';
COMMENT ON COLUMN dh_dataforge_job_node_run.parent_task_instance_id IS '已验证的父任务实例编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.ds_instance_id IS '已双向核验的子工作流实例编号';
COMMENT ON COLUMN dh_dataforge_job_node_run.status IS '真实执行或等待状态，不从提交响应推断成功';
COMMENT ON COLUMN dh_dataforge_job_node_run.creator IS '创建人';
COMMENT ON COLUMN dh_dataforge_job_node_run.create_time IS '创建时间';
COMMENT ON COLUMN dh_dataforge_job_node_run.updater IS '更新人';
COMMENT ON COLUMN dh_dataforge_job_node_run.update_time IS '更新时间';
COMMENT ON COLUMN dh_dataforge_job_node_run.deleted IS '逻辑删除标记';
CREATE UNIQUE INDEX IF NOT EXISTS uk_job_node_run_identity ON dh_dataforge_job_node_run(job_record_id,node_id) WHERE deleted=0;
CREATE UNIQUE INDEX IF NOT EXISTS uk_job_node_parent_code ON dh_dataforge_job_node_run(job_record_id,parent_task_code) WHERE deleted=0 AND parent_task_code IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS uk_job_node_real_child ON dh_dataforge_job_node_run(kind,ds_project_code,ds_instance_id) WHERE deleted=0 AND ds_instance_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_job_node_platform_record ON dh_dataforge_job_node_run(kind,platform_record_id) WHERE deleted=0;
COMMIT;


-- Migration: 0257 作业真实集成子记录状态契约
-- Purpose: 扩展旧集成记录检查约束，允许受管 DS 等待、未知、停止状态及经核验的作业触发来源。
-- Depends on: 0252_dataforge_integration-ds-runtime.sql；0256_dataforge_job-native-children.sql。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；新库基线同步包含本迁移。
-- Repeatable: 是；事务内重建同名检查约束，不修改既有业务记录。
-- Rollback: 先确认不存在新状态及 JOB 触发记录；恢复旧约束会拒绝这些真实运行，不自动重写审计数据。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
ALTER TABLE dh_dataforge_integration_record DROP CONSTRAINT IF EXISTS dh_dataforge_integration_record_status_check;
ALTER TABLE dh_dataforge_integration_record ADD CONSTRAINT dh_dataforge_integration_record_status_check
 CHECK (status IN ('WAITING','RUNNING','SUCCESS','FAILURE','IDLE','STOPPED','UNKNOWN'));
ALTER TABLE dh_dataforge_integration_record DROP CONSTRAINT IF EXISTS dh_dataforge_integration_record_trigger_type_check;
ALTER TABLE dh_dataforge_integration_record ADD CONSTRAINT dh_dataforge_integration_record_trigger_type_check
 CHECK (trigger_type IN ('IMPORTED','MANUAL','SCHEDULE','JOB'));
COMMENT ON COLUMN dh_dataforge_integration_record.status IS '执行状态；等待、运行、成功、失败、停止、未知及兼容旧停止标记 IDLE';
COMMENT ON COLUMN dh_dataforge_integration_record.trigger_type IS '触发来源；JOB 仅用于双向核验父子身份后的真实作业运行';
COMMIT;


-- Migration: 0258 作业级持久周期与并发策略队列
-- Purpose: 持久化周期代次、执行身份、冻结运行与串行占位，支持跨实例恢复与无重复业务触发。
-- Depends on: 0256_dataforge_job-native-children.sql；0257_dataforge_job-child-record-states.sql。
-- Target: 已有 PostgreSQL 平台库，schema 为 datahub-center；迁移时停止旧版本作业写入口，新库基线同步包含本迁移。
-- Repeatable: 是；仅加法字段、索引及已停旧写入口的过期控制面占位修复，不修改运行审计或示例。
-- Rollback: 先关闭所有平台周期并确认队列及真实运行结束；移除字段会丢失恢复链，不能自动回退到旧 DS 直接业务周期。
BEGIN;
SET LOCAL search_path TO "datahub-center",pg_catalog;
SET LOCAL lock_timeout='10s';
SET LOCAL statement_timeout='120s';
ALTER TABLE dh_dataforge_job
 ADD COLUMN IF NOT EXISTS schedule_generation bigint NOT NULL DEFAULT 0,
 ADD COLUMN IF NOT EXISTS schedule_user_id bigint,
 ADD COLUMN IF NOT EXISTS next_run_time timestamp,
 ADD COLUMN IF NOT EXISTS schedule_snapshot_json jsonb;
COMMENT ON COLUMN dh_dataforge_job.schedule_generation IS '周期配置代次；槽位唯一身份的一部分';
COMMENT ON COLUMN dh_dataforge_job.schedule_user_id IS '启用周期的实际登录执行人，不使用负责人替代';
COMMENT ON COLUMN dh_dataforge_job.next_run_time IS '上海时区下一个尚未持久受理的 Quartz 槽位';
COMMENT ON COLUMN dh_dataforge_job.schedule_snapshot_json IS '周期冻结的作业图、子版本与执行目标引用，不含凭据';
ALTER TABLE dh_dataforge_job_record
 ADD COLUMN IF NOT EXISTS run_snapshot_json jsonb,
 ADD COLUMN IF NOT EXISTS queue_state varchar(32),
 ADD COLUMN IF NOT EXISTS queue_reason varchar(1000),
 ADD COLUMN IF NOT EXISTS queued_time timestamp,
 ADD COLUMN IF NOT EXISTS scheduled_time timestamp,
 ADD COLUMN IF NOT EXISTS schedule_generation bigint,
 ADD COLUMN IF NOT EXISTS serial_slot boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS stop_requested boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS lease_owner varchar(64),
 ADD COLUMN IF NOT EXISTS lease_until timestamp;
COMMENT ON COLUMN dh_dataforge_job_record.run_snapshot_json IS '入队时冻结的实际执行人、作业图、子版本及目标引用';
COMMENT ON COLUMN dh_dataforge_job_record.queue_state IS '队列状态；业务终态仍由真实父子和原生门禁共同确定';
COMMENT ON COLUMN dh_dataforge_job_record.queue_reason IS '真实受理、等待、拒绝、抢占或恢复原因，不伪造 Worker 输出';
COMMENT ON COLUMN dh_dataforge_job_record.queued_time IS '平台持久受理时间';
COMMENT ON COLUMN dh_dataforge_job_record.scheduled_time IS '实际业务 Cron 槽位，人工运行为空';
COMMENT ON COLUMN dh_dataforge_job_record.schedule_generation IS '该周期槽所属配置代次';
COMMENT ON COLUMN dh_dataforge_job_record.serial_slot IS '作业级串行占位；仅真实终态或可证明未触发时释放';
COMMENT ON COLUMN dh_dataforge_job_record.stop_requested IS '持久停止意图；准备者必须在触发前再次核验';
COMMENT ON COLUMN dh_dataforge_job_record.lease_owner IS '本次准备派发的领取令牌';
COMMENT ON COLUMN dh_dataforge_job_record.lease_until IS '派发租约截止；失租约不证明远端已停止';
CREATE UNIQUE INDEX IF NOT EXISTS uk_job_record_serial_slot ON dh_dataforge_job_record(job_id) WHERE deleted=0 AND serial_slot;
CREATE UNIQUE INDEX IF NOT EXISTS uk_job_record_cron_slot ON dh_dataforge_job_record(job_id,schedule_generation,scheduled_time) WHERE deleted=0 AND scheduled_time IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_job_record_durable_queue ON dh_dataforge_job_record(queue_state,queued_time,id) WHERE deleted=0;
CREATE INDEX IF NOT EXISTS idx_job_due_schedule ON dh_dataforge_job(next_run_time,id) WHERE deleted=0 AND schedule_status=1 AND schedule_snapshot_json IS NOT NULL;
-- 旧版 BUSY 仅为请求级控制面锁；旧写入口停用后清除它，新版使用事务行锁与持久运行租约。
UPDATE dh_dataforge_job SET operation_state='IDLE' WHERE operation_state='BUSY';
COMMIT;


-- Migration: 0259 补充多协议连接器地址模板
-- Purpose: 为缺少地址模板的内置连接器提供符合现有连接配置的格式示例。
-- Depends on: 0186_dataforge_remote-file-management.sql 和 0197_dataforge_connect-only-connectors.sql 已执行；平台库已升级至 0258。
-- Target: 已有 PostgreSQL 平台库；新库基线包含本迁移。
-- Repeatable: 是；仅填充有效记录中的空模板，保留已有自定义值。
-- Rollback: 事务失败自动回滚；提交后如需恢复空值，应先核对记录和模板，再按记录撤销，避免覆盖后续修改。
BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

UPDATE dh_dataforge_database_type AS t
SET url_templates = s.template,
    updater = 'migration:0259',
    update_time = CURRENT_TIMESTAMP
FROM (VALUES
    ('FTP', 'ftp://${host}:${port}'),
    ('HDFS', 'http://${host}:${port}/webhdfs/v1'),
    ('SFTP', 'sftp://${host}:${port}'),
    ('ODPS', 'https://${host}:${port}'),
    ('OSS', 'https://${host}:${port}'),
    ('MINIO', 'http://${host}:${port}'),
    ('REDIS', 'redis://${host}:${port}/${dbName}'),
    ('KAFKA', '${host}:${port}'),
    ('RABBITMQ', 'amqp://${host}:${port}'),
    ('ROCKETMQ', '${host}:${port}'),
    ('NEO4J', 'bolt://${host}:${port}'),
    ('MILVUS', 'http://${host}:${port}'),
    ('INFLUXDB2', 'http://${host}:${port}')
) AS s(code, template)
WHERE t.deleted = 0
  AND regexp_replace(upper(t.type_code), '[-_[:space:]]', '', 'g') = s.code
  AND coalesce(btrim(t.url_templates), '') = '';
COMMIT;


-- Migration: 0264 移除通用数据推送菜单及专用授权。
-- Purpose: 退役数据研发中的推送任务、配置和类目入口，清理专用角色授权、套餐引用及平台遗留调度配置。
-- Depends on: 0161_dataforge_single-push-task-entry.sql、0246_dataforge_push-categories.sql 所建立的菜单状态；平台库已升级至 0263。
-- Target: 已有 PostgreSQL 平台库；新库使用同步后的 datahub-center.sql。
-- Repeatable: 是；仅清理与通用数据推送身份匹配的记录，重复执行不再产生变更。
-- Rollback: 事务失败自动回滚；提交后恢复执行前备份中的目标菜单、角色授权、套餐及旧调度配置，并恢复应用版本。
-- 部署前在外部 XXL-Job 管理端停用 dataforge-server 的 dataPushSyncJob、dataPushAlertRelayJob、
-- dataPushAlertDispositionJob 和 dataPushAlertCleanJob，确认旧执行已结束。保留任务配置数据及运行历史。

BEGIN;
SET LOCAL search_path TO "datahub-center", pg_catalog;
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '120s';

LOCK TABLE system_menu, system_role_menu, system_tenant_package IN SHARE ROW EXCLUSIVE MODE;

CREATE TEMPORARY TABLE dataforge_0264_retired_menus (id bigint PRIMARY KEY) ON COMMIT DROP;

INSERT INTO dataforge_0264_retired_menus (id)
SELECT id FROM system_menu
WHERE permission LIKE 'dataforge:data-push:%'
   OR permission LIKE 'dataforge:push-category:%'
   OR trim(both '/' from coalesce(component, '')) IN (
       'dataforge/datapush/task/index', 'dataforge/datapush/config/index', 'dataforge/categorypush/index'
   )
   OR component_name IN ('DataforgeDataPushTask', 'DataforgeDataPushConfig', 'DataforgePushCategory');

-- 一并清理目标页面下无权限码的专用按钮。
INSERT INTO dataforge_0264_retired_menus (id)
SELECT child.id FROM system_menu child
JOIN dataforge_0264_retired_menus parent ON child.parent_id = parent.id
WHERE child.type = 3 AND child.permission = ''
ON CONFLICT (id) DO NOTHING;

DO $menu_preflight$
BEGIN
    IF EXISTS (
        SELECT 1 FROM system_menu child
        JOIN dataforge_0264_retired_menus parent ON child.parent_id = parent.id
        WHERE NOT EXISTS (SELECT 1 FROM dataforge_0264_retired_menus retired WHERE retired.id = child.id)
    ) THEN
        RAISE EXCEPTION '0264 通用数据推送菜单下存在其他功能子项，请核对后再执行';
    END IF;
END $menu_preflight$;

-- 保留套餐中其他条目的顺序及数字或字符串类型。
UPDATE system_tenant_package package
SET menu_ids = (
        SELECT '[' || coalesce(string_agg(item.value::text, ',' ORDER BY item.ordinality), '') || ']'
        FROM jsonb_array_elements(package.menu_ids::jsonb) WITH ORDINALITY item(value, ordinality)
        WHERE NOT EXISTS (
            SELECT 1 FROM dataforge_0264_retired_menus retired WHERE retired.id::text = item.value #>> '{}'
        )
    ),
    updater = 'migration:0264', update_time = CURRENT_TIMESTAMP
WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements_text(package.menu_ids::jsonb) item(value)
    JOIN dataforge_0264_retired_menus retired ON retired.id::text = item.value
);

DELETE FROM system_role_menu WHERE menu_id IN (SELECT id FROM dataforge_0264_retired_menus);
DELETE FROM system_menu WHERE id IN (SELECT id FROM dataforge_0264_retired_menus);

-- 仅移除平台中可能残留的专用调度配置，保留日志和外部调度库。
DO $legacy_jobs$
BEGIN
    IF to_regclass('"datahub-center".infra_job') IS NOT NULL THEN
        DELETE FROM infra_job WHERE handler_name IN (
            'dataPushSyncJob', 'dataPushAlertRelayJob', 'dataPushAlertDispositionJob', 'dataPushAlertCleanJob'
        );
    END IF;
END $legacy_jobs$;

COMMIT;
